// Hyperrealism in p5.brush — 1970s Fondue Night at Carpet Level
// Monochrome Amber-Umber-Gold Foundation with Burnt-Orange Enamel Accent

const PAL = {
  // Deep chocolate & walnut shadows
  voidUmber: "#0e0805",
  darkChoc: "#1a0f08",
  chocBrown: "#2b180d",
  warmWalnut: "#3f2312",
  teakDark: "#542e16",
  teakMid: "#78431e",
  teakLight: "#9e5c28",
  teakGlow: "#c47a38",

  // Smoked glass & amber glass
  smokedDark: "#17110c",
  smokedMid: "#291e15",
  smokedAmber: "#45301e",
  glassBevel: "#d8b882",
  amberDeep: "#4d2105",
  amberMid: "#8f410a",
  amberBright: "#cc6814",
  amberHoney: "#edb32e",

  // Harvest gold & mustard shag rug
  rugShadow: "#241608",
  rugDeep: "#3b250d",
  rugUmber: "#573812",
  rugBronze: "#784f16",
  rugMustard: "#9c6a1c",
  rugGold: "#bf8624",
  rugBright: "#de9f2e",
  rugSunlit: "#f2be49",
  rugTip: "#fae084",

  // Muted avocado & olive undertones
  avocadoShadow: "#2e3315",
  avocadoDark: "#464f1e",
  avocadoMid: "#65732b",
  avocadoLight: "#8ca140",
  avocadoHighlight: "#bdd16b",

  // Focal Accent: Saturated 1970s Burnt Orange Enamel
  enamelShadow: "#3b0f05",
  enamelMahogany: "#611808",
  enamelDeep: "#8f240b",
  enamelBurnt: "#bf3611",
  enamelVivid: "#e34a19",
  enamelBright: "#f76321",
  enamelFlame: "#ff8433",
  enamelPeach: "#ffb978",

  // Cheese, Bread & Napkin
  cheeseShadow: "#8c5812",
  cheeseMid: "#bd7e1a",
  cheeseGold: "#e09f28",
  cheeseBright: "#f5c249",
  cheeseCream: "#fae38c",
  specWhite: "#fff9e8",
  napkinShadow: "#785e3d",
  napkinMid: "#ab8d65",
  napkinWarm: "#cfb48c",
  napkinLight: "#e8d2ae",
  napkinHighlight: "#f7ead2",
  ashGrey: "#9e968c",
  ashLight: "#cfc7bc"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1974);
  noiseSeed(1974);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.voidUmber);

  // 1. Background 1970s Wood Panelling & Smoky Room Wash
  drawWoodPanelling();

  // 2. Shag Rug Underpainting & Back/Mid-ground Curling Strands
  drawShagRugBase();
  drawShagStrandsRange(575, 855, 1950);

  // 3. Smoked-Glass & Teak Coffee Table (Legs, Frame, Reflective Smoked Top)
  drawCoffeeTable();

  // 4. Ribbed Amber Glass Tumbler & Honey Caustics on Table
  drawAmberGlassTumbler();

  // 5. Fondue Rechaud, Alcohol Burner Flame & Burnt-Orange Enamel Pot
  drawFondueRechaudAndPot();

  // 6. Bubbling Cheese, Coloured-Tip Forks & Speared Bread Dripping Cheese
  drawCheeseForksAndBread();

  // 7. Foreground Shag Strands, Table-Leg Overlap & Cigarette-Burned Napkin
  drawShagStrandsRange(845, 955, 850);
  drawFallenNapkinWithBurn();
  drawShagStrandsRange(945, 1200, 1350);

  // 8. Hanging Tasselled Lamp & Smoky Hazy Atmospheric Light
  drawTasselledLamp();
  drawSmokyHazeAndSteam();

  noLoop();
}

// =========================================================================
// GEOMETRY & BRUSH HELPERS
// =========================================================================

function washPoly(pts, col, opacity) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function fillPoly(pts, col, opacity, bleed = 0.08, tex = 0.35, border = 0.25) {
  brush.noStroke();
  brush.noWash();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function makeEllipsePts(cx, cy, rx, ry, n = 36, rotDeg = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * 360;
    let ex = cos(ang) * rx;
    let ey = sin(ang) * ry;
    pts.push([cx + ex * c - ey * s, cy + ex * s + ey * c]);
  }
  return pts;
}

function strokeEllipseArc(cx, cy, rx, ry, aStart, aEnd, steps = 28, curvature = 0.5) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(aStart, aEnd, t);
    let p = 0.7 + 0.5 * sin(t * 180);
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry, p]);
  }
  brush.spline(pts, curvature);
}

// Lighting model for the room (lamp at upper-left x=265, y=155, burner at x=635, y=455)
function getRugLight(x, y) {
  // Cone from hanging lamp
  let dxL = (x - 265) / 680;
  let dyL = (y - 155) / 980;
  let lampCone = constrain(1.18 - sqrt(dxL * dxL * 0.85 + dyL * dyL * 0.55), 0, 1);

  // Shadow under coffee table (x: 140..1040, y: 600..855)
  let inTableX = constrain(1 - abs(x - 590) / 450, 0, 1);
  let inTableY = constrain(1 - abs(y - 725) / 145, 0, 1);
  let tableShadow = pow(inTableX * inTableY, 1.35) * 0.62;

  // Warm orange-amber bounce under fondue pot & amber glass
  let dPot = dist(x, y * 1.2, 640, 720 * 1.2);
  let potGlow = constrain(1 - dPot / 280, 0, 1) * 0.35;

  // Shadow immediately under fallen napkin (x: 235..510, y: 900..1040)
  let inNapX = constrain(1 - abs(x - 375) / 155, 0, 1);
  let inNapY = constrain(1 - abs(y - 975) / 72, 0, 1);
  let napShadow = pow(inNapX * inNapY, 1.6) * 0.65;

  return constrain(lampCone * 0.88 - tableShadow + potGlow - napShadow, 0.04, 1.0);
}

// =========================================================================
// 1. WOOD PANELLING & BASEBOARD
// =========================================================================

function drawWoodPanelling() {
  // Deep chocolate base over upper wall
  washPoly([[0, 0], [1200, 0], [1200, 595], [0, 595]], PAL.darkChoc, 240);

  // Diagonal warm light wash from lamp across panelling
  fillPoly([[0, 0], [680, 0], [980, 585], [0, 585]], PAL.warmWalnut, 130, 0.25, 0.4, 0.15);
  fillPoly([[80, 80], [560, 80], [820, 585], [90, 585]], PAL.teakDark, 115, 0.3, 0.4, 0.15);
  fillPoly([[150, 120], [460, 120], [670, 575], [160, 575]], PAL.teakMid, 90, 0.35, 0.35, 0.1);

  // 13 Vertical Teak Panels
  let panelW = 94;
  for (let p = 0; p < 13; p++) {
    let x0 = p * panelW;
    let x1 = x0 + panelW;
    let xm = (x0 + x1) * 0.5;

    // Illumination across this plank
    let plankLight = constrain(1.08 - abs(xm - 360) / 620, 0.12, 1.0);

    // Marker sheen strips on wood planks
    let colMain = plankLight > 0.65 ? PAL.teakMid : (plankLight > 0.38 ? PAL.teakDark : PAL.warmWalnut);
    let colHi = plankLight > 0.65 ? PAL.teakLight : (plankLight > 0.38 ? PAL.teakMid : PAL.teakDark);

    brush.set("marker", colMain, 2.2);
    for (let s = 0; s < 7; s++) {
      let sx = x0 + 8 + s * 12 + random(-2, 2);
      brush.line(sx, 0, sx, 552);
    }

    // Specular satin varnish streaks on lit planks
    if (plankLight > 0.35) {
      brush.set("marker", colHi, 1.4);
      for (let s = 0; s < 3; s++) {
        let sx = x0 + 18 + s * 26 + random(-4, 4);
        let yTop = random(20, 140);
        let yBot = random(420, 548);
        brush.line(sx, yTop, sx, yBot);
      }
    }

    // Cathedral wood grain figure with colored pencil
    let grainCol = plankLight > 0.5 ? PAL.chocBrown : PAL.darkChoc;
    brush.set("cpencil", grainCol, 0.55);
    let knotY = random(140, 440);
    for (let g = 0; g < 11; g++) {
      let gx = x0 + 6 + g * 8;
      let pts = [];
      for (let y = 0; y <= 550; y += 55) {
        let bend = sin((y - knotY) * 0.8) * 5 * exp(- abs(y - knotY) / 120);
        let nx = gx + bend + (noise(p * 10 + g, y * 0.01) - 0.5) * 7;
        pts.push([constrain(nx, x0 + 2, x1 - 2), y, 0.7]);
      }
      brush.spline(pts, 0.5);
    }

    // Warm golden wood-pore streaks
    if (plankLight > 0.45) {
      brush.set("cpencil", PAL.teakGlow, 0.42);
      for (let g = 0; g < 5; g++) {
        let gx = x0 + 14 + g * 16 + random(-3, 3);
        brush.line(gx, random(60, 220), gx, random(360, 540));
      }
    }

    // Vertical V-groove seam between planks
    brush.set("rotring", PAL.voidUmber, 0.95);
    brush.line(x0, 0, x0, 552);
    brush.set("2B", PAL.darkChoc, 0.8);
    brush.line(x0 + 2, 0, x0 + 2, 552);

    // Beveled edge catch-light on the side facing the lamp
    let bevelCol = xm > 265 ? PAL.teakLight : PAL.teakMid;
    brush.set("cpencil", bevelCol, 0.55);
    let bevelX = xm > 265 ? x0 + 3.5 : x1 - 2.5;
    brush.line(bevelX, 20, bevelX, 550);
  }

  // Baseboard molding (y = 548..586)
  washPoly([[0, 548], [1200, 548], [1200, 588], [0, 588]], PAL.darkChoc, 245);
  brush.set("marker", PAL.warmWalnut, 1.8);
  brush.line(0, 556, 1200, 556);
  brush.line(0, 570, 1200, 570);
  brush.set("marker", PAL.teakMid, 1.1);
  brush.line(60, 551, 920, 551);
  brush.set("cpencil", PAL.teakGlow, 0.65);
  brush.line(120, 549, 780, 549);
  brush.set("rotring", PAL.voidUmber, 1.1);
  brush.line(0, 585, 1200, 585);
}

// =========================================================================
// 2. HARVEST-GOLD SHAG RUG BASE & CURLING COLOURED-PENCIL STRANDS
// =========================================================================

function drawShagRugBase() {
  // Deep foundation across carpet plane (y = 582..1200)
  washPoly([[0, 582], [1200, 582], [1200, 1200], [0, 1200]], PAL.rugDeep, 250);

  // Broad tonal pools of harvest gold, mustard, and deep chocolate shadow
  fillPoly([[0, 585], [980, 585], [1200, 1200], [0, 1200]], PAL.rugUmber, 165, 0.25, 0.45, 0.2);
  fillPoly([[40, 610], [820, 600], [1050, 1200], [0, 1200]], PAL.rugBronze, 150, 0.3, 0.45, 0.2);
  fillPoly([[80, 740], [640, 760], [860, 1200], [40, 1200]], PAL.rugMustard, 135, 0.3, 0.4, 0.2);
  fillPoly([[110, 820], [520, 840], [680, 1180], [90, 1180]], PAL.rugGold, 110, 0.3, 0.35, 0.15);

  // Deep shadow pool beneath coffee table frame
  fillPoly([[150, 630], [1030, 630], [1080, 845], [120, 855]], PAL.rugShadow, 185, 0.25, 0.4, 0.2);
  fillPoly([[190, 665], [980, 665], [1010, 815], [170, 825]], PAL.voidUmber, 140, 0.2, 0.35, 0.15);

  // Warm orange-gold glow on carpet directly under the fondue burner & amber glass
  fillPoly(makeEllipsePts(640, 735, 195, 58), PAL.amberMid, 95, 0.35, 0.3, 0.1);
  fillPoly(makeEllipsePts(910, 720, 130, 42), PAL.rugGold, 105, 0.35, 0.3, 0.1);
}

// Renders thousands of curling coloured-pencil strands batched by color & weight
function drawShagStrandsRange(yMin, yMax, totalTufts) {
  let buckets = [
    { brush: "2B", col: PAL.voidUmber, w: 0.72, splines: [] },       // 0: deepest root crevices
    { brush: "cpencil", col: PAL.rugShadow, w: 0.82, splines: [] },  // 1: dark chocolate shadow
    { brush: "cpencil", col: PAL.avocadoShadow, w: 0.78, splines: [] }, // 2: dark olive-avocado undertone
    { brush: "cpencil", col: PAL.rugDeep, w: 0.88, splines: [] },    // 3: deep walnut-umber
    { brush: "cpencil", col: PAL.rugUmber, w: 0.92, splines: [] },   // 4: warm umber
    { brush: "cpencil", col: PAL.avocadoDark, w: 0.80, splines: [] },// 5: muted avocado shadow strand
    { brush: "cpencil", col: PAL.rugBronze, w: 0.96, splines: [] },  // 6: harvest bronze
    { brush: "cpencil", col: PAL.rugMustard, w: 1.02, splines: [] }, // 7: rich mustard
    { brush: "cpencil", col: PAL.amberMid, w: 0.90, splines: [] },   // 8: burnt-amber bounce tone
    { brush: "cpencil", col: PAL.rugGold, w: 1.05, splines: [] },    // 9: harvest gold
    { brush: "cpencil", col: PAL.rugBright, w: 1.00, splines: [] },  // 10: bright golden ochre
    { brush: "cpencil", col: PAL.rugSunlit, w: 0.92, splines: [] },  // 11: sunlit gold tips
    { brush: "HB", col: PAL.rugTip, w: 0.68, splines: [] }           // 12: crisp cream-gold specular fibre tips
  ];

  for (let i = 0; i < totalTufts; i++) {
    // Stratified sampling with perspective bias toward foreground
    let u = (i + random(0.1, 0.9)) / totalTufts;
    let y = lerp(yMin, yMax, pow(u, 0.92));
    let x = random(-25, 1225);

    // Perspective scale from back of room (y=580) to immediate carpet edge (y=1200)
    let pScale = map(y, 575, 1200, 0.28, 1.48);
    let light = getRugLight(x, y);
    let nVal = noise(x * 0.008, y * 0.012);

    // Each tuft spawns 2 to 4 curling strands (root shadow + mid body + lit tip)
    let strandsInTuft = y > 920 ? 3 : 2;
    let tuftDir = (noise(x * 0.005, y * 0.005) - 0.5) * 150 - 90;

    for (let s = 0; s < strandsInTuft; s++) {
      let len = random(18, 44) * pScale * (s === 0 ? 0.82 : 1.05);
      let a0 = tuftDir + random(-48, 48);
      let curl = random(-65, 65) * (random() < 0.5 ? 1 : -1);

      let x0 = x + random(-6, 6) * pScale;
      let y0 = y + random(-3, 3) * pScale;
      let x1 = x0 + cos(a0) * (len * 0.36);
      let y1 = y0 + sin(a0) * (len * 0.28);
      let x2 = x1 + cos(a0 + curl * 0.55) * (len * 0.36);
      let y2 = y1 + sin(a0 + curl * 0.55) * (len * 0.28);
      let x3 = x2 + cos(a0 + curl) * (len * 0.32);
      let y3 = y2 + sin(a0 + curl) * (len * 0.26);

      let pts = [
        [x0, y0, 0.95 * pScale],
        [x1, y1, 0.85 * pScale],
        [x2, y2, 0.65 * pScale],
        [x3, y3, 0.35 * pScale]
      ];

      // Choose bucket based on strand role (root vs mid vs sunlit tip) and local light
      let bIdx = 0;
      if (s === 0) {
        // Root / under-strand
        if (light < 0.25) bIdx = random() < 0.6 ? 0 : 1;
        else if (light < 0.55) bIdx = random() < 0.28 ? 2 : (random() < 0.5 ? 1 : 3);
        else bIdx = random() < 0.25 ? 5 : 4;
      } else if (s === 1) {
        // Main body yarn strand
        let tVal = constrain(light + (nVal - 0.5) * 0.35, 0, 1);
        if (tVal < 0.22) bIdx = 3;
        else if (tVal < 0.38) bIdx = random() < 0.25 ? 5 : 4;
        else if (tVal < 0.56) bIdx = random() < 0.2 ? 8 : 6;
        else if (tVal < 0.74) bIdx = 7;
        else if (tVal < 0.88) bIdx = 9;
        else bIdx = 10;
      } else {
        // Top highlight curl in foreground tufts
        if (light > 0.68) bIdx = random() < 0.38 ? 12 : 11;
        else if (light > 0.42) bIdx = random() < 0.3 ? 10 : 9;
        else bIdx = 6;
      }

      buckets[bIdx].splines.push(pts);
    }
  }

  // Render all buckets in order from darkest root shadows to brightest golden tips
  let avgScale = map((yMin + yMax) * 0.5, 575, 1200, 0.48, 1.25);
  for (let b = 0; b < buckets.length; b++) {
    let bk = buckets[b];
    if (bk.splines.length === 0) continue;
    brush.set(bk.brush, bk.col, bk.w * avgScale);
    for (let k = 0; k < bk.splines.length; k++) {
      brush.spline(bk.splines[k], 0.65);
    }
  }
}

// Helper to draw targeted carpet tufts curling up around table legs or napkin edges
function drawLocalShagTufts(xMin, xMax, yBase, count, pScale) {
  let shadowSplines = [];
  let midSplines = [];
  let hiSplines = [];

  for (let i = 0; i < count; i++) {
    let x = lerp(xMin, xMax, (i + random(0.1, 0.9)) / count);
    let y = yBase + random(-8, 12) * pScale;
    let light = getRugLight(x, y);
    let len = random(24, 48) * pScale;
    let a0 = random(-125, -55);
    let curl = random(-55, 55);

    let pts = [
      [x, y + 6 * pScale, 0.95],
      [x + cos(a0) * len * 0.35, y + sin(a0) * len * 0.35, 0.85],
      [x + cos(a0 + curl * 0.5) * len * 0.7, y + sin(a0 + curl * 0.5) * len * 0.65, 0.6],
      [x + cos(a0 + curl) * len, y + sin(a0 + curl) * len * 0.88, 0.3]
    ];

    if (i % 3 === 0) shadowSplines.push(pts);
    else if (light > 0.52 && i % 3 === 2) hiSplines.push(pts);
    else midSplines.push(pts);
  }

  brush.set("2B", PAL.rugShadow, 0.85 * pScale);
  for (let s of shadowSplines) brush.spline(s, 0.65);

  brush.set("cpencil", PAL.rugMustard, 0.95 * pScale);
  for (let s of midSplines) brush.spline(s, 0.65);

  brush.set("cpencil", PAL.rugSunlit, 0.85 * pScale);
  for (let s of hiSplines) brush.spline(s, 0.65);
}

// =========================================================================
// 3. SMOKED-GLASS & TEAK COFFEE TABLE
// =========================================================================

function drawTeakBeam(pts, baseCol, markerCol, hiCol, isVertical) {
  washPoly(pts, baseCol, 245);
  brush.set("marker", markerCol, 1.8);
  let steps = 9;
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    if (isVertical) {
      let xTop = lerp(pts[0][0], pts[1][0], t);
      let yTop = lerp(pts[0][1], pts[1][1], t);
      let xBot = lerp(pts[3][0], pts[2][0], t);
      let yBot = lerp(pts[3][1], pts[2][1], t);
      brush.line(xTop, yTop, xBot, yBot);
    } else {
      let xL = lerp(pts[0][0], pts[3][0], t);
      let yL = lerp(pts[0][1], pts[3][1], t);
      let xR = lerp(pts[1][0], pts[2][0], t);
      let yR = lerp(pts[1][1], pts[2][1], t);
      brush.line(xL, yL, xR, yR);
    }
  }
  // Specular marker highlight along edge
  brush.set("marker", hiCol, 1.2);
  brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  brush.set("cpencil", PAL.voidUmber, 0.75);
  brush.line(pts[3][0], pts[3][1], pts[2][0], pts[2][1]);
}

function drawCoffeeTable() {
  // --- A. Back Teak Legs & Lower Stretcher Rails (seen through/under smoked glass) ---
  // Back-left leg (x=250..295, y=455..705)
  drawTeakBeam([[252, 455], [292, 455], [282, 705], [244, 705]], PAL.darkChoc, PAL.chocBrown, PAL.teakDark, true);
  // Back-right leg (x=885..928, y=455..695)
  drawTeakBeam([[885, 455], [925, 455], [935, 695], [895, 695]], PAL.darkChoc, PAL.chocBrown, PAL.teakDark, true);
  // Cross stretcher bar connecting legs under the glass
  drawTeakBeam([[195, 645], [985, 638], [985, 668], [195, 676]], PAL.darkChoc, PAL.warmWalnut, PAL.teakMid, false);

  // Shag carpet tufts curling around the base of the back legs
  drawLocalShagTufts(238, 290, 702, 22, 0.55);
  drawLocalShagTufts(888, 942, 692, 22, 0.55);

  // --- B. Sculptural Angled Front Teak Legs & Beveled Under-Frame ---
  // Front-left angled leg (x=125..205, y=485..845)
  // Lit front-left chamfer plane
  drawTeakBeam([[124, 485], [162, 492], [148, 845], [114, 838]], PAL.warmWalnut, PAL.teakMid, PAL.teakGlow, true);
  // Darker inner-right shadow plane of front-left leg
  drawTeakBeam([[162, 492], [202, 498], [182, 842], [148, 845]], PAL.darkChoc, PAL.chocBrown, PAL.teakDark, true);
  // Sharp wood arris highlight down the center ridge of the leg
  brush.set("cpencil", PAL.rugSunlit, 0.65);
  brush.line(162, 492, 148, 842);

  // Front-right angled leg (x=975..1055, y=480..815)
  // Lit inner-left chamfer plane (facing the lamp & pot)
  drawTeakBeam([[975, 492], [1012, 488], [1024, 815], [992, 818]], PAL.warmWalnut, PAL.teakMid, PAL.teakLight, true);
  // Dark outer-right shadow plane
  drawTeakBeam([[1012, 488], [1052, 482], [1058, 808], [1024, 815]], PAL.darkChoc, PAL.chocBrown, PAL.warmWalnut, true);
  brush.set("cpencil", PAL.teakGlow, 0.6);
  brush.line(1012, 488, 1024, 815);

  // Shag rug strands curling up over the bottom of the front teak legs
  drawLocalShagTufts(108, 190, 840, 38, 0.82);
  drawLocalShagTufts(985, 1065, 812, 36, 0.78);

  // Teak Apron / Under-rail directly beneath the smoked glass
  // Back rail (seen through glass)
  drawTeakBeam([[195, 422], [990, 420], [1005, 444], [180, 446]], PAL.darkChoc, PAL.warmWalnut, PAL.teakMid, false);
  // Left side rail in perspective
  drawTeakBeam([[92, 518], [195, 422], [212, 446], [118, 548]], PAL.warmWalnut, PAL.teakMid, PAL.teakLight, false);
  // Right side rail in perspective
  drawTeakBeam([[990, 420], [1095, 512], [1072, 542], [975, 445]], PAL.darkChoc, PAL.chocBrown, PAL.teakDark, false);

  // --- C. The Smoked-Glass Tabletop (y = 415..538) ---
  let glassTopPts = [
    [185, 416], [1000, 414],
    [1112, 508], [1082, 526],
    [104, 530], [74, 512]
  ];

  // Translucent smoked-amber & espresso washes
  washPoly(glassTopPts, PAL.smokedDark, 195);
  fillPoly(glassTopPts, PAL.smokedMid, 130, 0.08, 0.25, 0.2);

  // Warm amber-bronze light transmitted/reflected across left-center of glass
  fillPoly([
    [185, 416], [780, 415], [840, 527], [104, 530], [74, 512]
  ], PAL.smokedAmber, 110, 0.15, 0.25, 0.15);

  // --- D. Mirror Reflections in the Smoked Glass ---
  // 1. Reflection of the glowing tasselled lamp (x=190..450, y=430..522)
  fillPoly(makeEllipsePts(320, 476, 125, 38), PAL.teakMid, 95, 0.25, 0.25, 0.1);
  fillPoly(makeEllipsePts(310, 472, 78, 24), PAL.rugGold, 90, 0.25, 0.2, 0.1);
  brush.set("marker", PAL.teakGlow, 1.5);
  for (let i = 0; i < 9; i++) {
    let ry = 448 + i * 6;
    let span = sin(map(i, 0, 8, 20, 160)) * 95;
    brush.line(315 - span, ry, 315 + span, ry);
  }
  brush.set("marker", PAL.rugTip, 1.1);
  for (let i = 0; i < 5; i++) {
    let ry = 462 + i * 5;
    brush.line(275 - i * 4, ry, 345 + i * 4, ry);
  }

  // 2. Reflection of the Burnt-Orange Fondue Pot & Flame (x=495..770, y=482..530)
  fillPoly(makeEllipsePts(635, 508, 138, 22), PAL.enamelMahogany, 135, 0.2, 0.2, 0.1);
  fillPoly(makeEllipsePts(620, 510, 95, 17), PAL.enamelBurnt, 125, 0.2, 0.2, 0.1);
  brush.set("marker", PAL.enamelVivid, 1.6);
  for (let i = 0; i < 7; i++) {
    let ry = 496 + i * 4.5;
    let w = sin(map(i, 0, 6, 25, 155)) * 105;
    brush.line(625 - w, ry, 625 + w * 0.85, ry);
  }
  // Reflection of the pot's specular window highlight in the glass
  brush.set("marker", PAL.enamelPeach, 1.1);
  brush.line(535, 502, 575, 502);
  brush.line(542, 510, 582, 510);

  // 3. Sleek horizontal marker streaks across smoked glass for mirror-flatness
  brush.set("marker", PAL.chocBrown, 1.3);
  for (let i = 0; i < 16; i++) {
    let y = random(422, 522);
    let t = map(y, 416, 528, 0, 1);
    let xMin = lerp(185, 95, t) + random(10, 180);
    let xMax = min(lerp(1000, 1090, t) - random(10, 120), xMin + random(140, 380));
    brush.line(xMin, y, xMax, y);
  }

  // Crisp surface sheen lines with fine pen/2H
  brush.set("2H", PAL.glassBevel, 0.45);
  for (let i = 0; i < 12; i++) {
    let y = random(426, 524);
    let xStart = random(140, 760);
    brush.line(xStart, y, xStart + random(80, 240), y);
  }

  // --- E. Front Teak Apron Rail & Thick Polished Smoked-Glass Bevel Edge ---
  // Front horizontal teak rail (y = 532..564) sitting just below the glass overhang
  drawTeakBeam([[118, 534], [1072, 528], [1062, 560], [128, 566]], PAL.chocBrown, PAL.teakDark, PAL.teakMid, false);
  // Warm glow on front teak rail under the lamp & pot
  brush.set("marker", PAL.teakLight, 1.4);
  brush.line(180, 538, 760, 535);
  brush.set("cpencil", PAL.teakGlow, 0.7);
  brush.line(220, 535, 690, 533);

  // Thick 3/4-inch Polished Smoked-Glass Front Edge (y = 522..535)
  let bevelPts = [[74, 512], [104, 526], [1082, 522], [1112, 508], [1112, 517], [1082, 533], [104, 537], [74, 521]];
  washPoly(bevelPts, PAL.voidUmber, 250);

  // Internal amber-olive refraction inside the thick glass edge
  brush.set("marker", PAL.amberMid, 1.35);
  brush.line(106, 531, 980, 527);
  brush.set("marker", PAL.avocadoMid, 0.9);
  brush.line(140, 529, 520, 528);
  brush.line(720, 527, 1040, 525);

  // Razor-sharp top and bottom arris highlights of the glass slab
  brush.set("rotring", PAL.glassBevel, 0.85);
  brush.line(74, 512, 104, 526);
  brush.line(104, 526, 1082, 522);
  brush.line(1082, 522, 1112, 508);

  brush.set("pen", PAL.specWhite, 0.65);
  brush.line(165, 526, 745, 523.5);

  brush.set("rotring", PAL.teakGlow, 0.7);
  brush.line(104, 536.5, 1082, 532.5);
}

// =========================================================================
// 4. VINTAGE RIBBED AMBER GLASS TUMBLER ON TABLE
// =========================================================================

function drawAmberGlassTumbler() {
  let gx = 900;
  let gyBot = 482;
  let gyTop = 388;
  let rxBot = 40;
  let rxTop = 47;

  // 1. Cast shadow & glowing honey-amber caustic on the smoked glass tabletop
  fillPoly(makeEllipsePts(gx + 34, gyBot + 8, 62, 16, 32, 4), PAL.voidUmber, 150, 0.15, 0.25, 0.15);
  fillPoly(makeEllipsePts(gx + 42, gyBot + 10, 44, 12, 32, 5), PAL.amberBright, 165, 0.2, 0.2, 0.1);
  fillPoly(makeEllipsePts(gx + 48, gyBot + 10, 26, 7, 28, 5), PAL.amberHoney, 190, 0.15, 0.15, 0.1);
  brush.set("cpencil", PAL.specWhite, 0.65);
  strokeEllipseArc(gx + 48, gyBot + 10, 16, 4, -30, 140, 14);

  // Reflection of amber tumbler in smoked glass below (y = 485..524)
  fillPoly([
    [gx - rxBot, gyBot], [gx + rxBot, gyBot],
    [gx + rxBot - 4, 522], [gx - rxBot + 4, 522]
  ], PAL.amberDeep, 125, 0.15, 0.2, 0.1);
  brush.set("marker", PAL.amberMid, 1.3);
  brush.line(gx - 24, 495, gx + 22, 495);
  brush.line(gx - 18, 508, gx + 18, 508);

  // 2. Tumbler Body Silhouette
  let bodyPts = [
    [gx - rxTop, gyTop], [gx + rxTop, gyTop],
    [gx + rxBot, gyBot], [gx - rxBot, gyBot]
  ];
  washPoly(bodyPts, PAL.amberDeep, 215);
  fillPoly(bodyPts, PAL.amberMid, 145, 0.1, 0.25, 0.2);

  // Liquid meniscus inside glass (y = 428)
  let liqPts = [
    [gx - 42, 428], [gx + 42, 428],
    [gx + rxBot - 2, gyBot - 8], [gx - rxBot + 2, gyBot - 8]
  ];
  fillPoly(liqPts, PAL.amberBright, 155, 0.1, 0.2, 0.15);

  // Vertical molded flutes / ribs in marker
  let numFlutes = 7;
  for (let f = 0; f < numFlutes; f++) {
    let t = (f + 0.5) / numFlutes;
    let fxTop = lerp(gx - rxTop + 4, gx + rxTop - 4, t);
    let fxBot = lerp(gx - rxBot + 4, gx + rxBot - 4, t);

    let col = f < 2 ? PAL.amberBright : (f < 4 ? PAL.amberMid : (f === 5 ? PAL.amberDeep : PAL.amberBright));
    brush.set("marker", col, 1.5);
    brush.line(fxTop, gyTop + 6, fxBot, gyBot - 4);

    if (f === 1 || f === 6) {
      brush.set("marker", PAL.amberHoney, 1.0);
      brush.line(fxTop, gyTop + 14, fxBot, gyBot - 10);
    }
  }

  // Heavy solid amber glass base (gyBot - 14 .. gyBot)
  fillPoly(makeEllipsePts(gx, gyBot - 2, rxBot, 10), PAL.amberDeep, 220, 0.05, 0.2, 0.2);
  fillPoly(makeEllipsePts(gx, gyBot - 6, rxBot - 4, 8), PAL.amberHoney, 160, 0.08, 0.15, 0.1);

  // Liquid surface ellipse & ice cube refraction glints
  brush.set("pen", PAL.amberHoney, 0.75);
  strokeEllipseArc(gx, 428, 42, 8, 0, 360, 28);
  brush.set("cpencil", PAL.specWhite, 0.7);
  strokeEllipseArc(gx - 6, 426, 18, 5, 190, 340, 14);
  strokeEllipseArc(gx + 12, 430, 15, 4, 10, 165, 14);

  // Top Rim of Amber Glass & Crisp Vertical Specular Streaks
  brush.set("rotring", PAL.amberDeep, 0.85);
  strokeEllipseArc(gx, gyTop, rxTop, 9, 0, 360, 32);
  brush.set("pen", PAL.specWhite, 0.8);
  strokeEllipseArc(gx, gyTop, rxTop, 9, 165, 315, 22);
  strokeEllipseArc(gx, gyTop, rxTop - 2, 8, 345, 75, 16);

  // Vertical glass specular highlight bar on left & right rim
  brush.set("pen", PAL.specWhite, 0.85);
  brush.line(gx - rxTop + 9, gyTop + 6, gx - rxBot + 9, gyBot - 8);
  brush.set("marker", PAL.specWhite, 0.9);
  brush.line(gx - rxTop + 11, gyTop + 18, gx - rxBot + 11, gyBot - 22);
  brush.set("pen", PAL.amberHoney, 0.75);
  brush.line(gx + rxTop - 7, gyTop + 10, gx + rxBot - 7, gyBot - 10);
}

// =========================================================================
// 5. FONDUE RECHAUD, ALCOHOL BURNER & BURNT-ORANGE ENAMEL POT
// =========================================================================

function drawFondueRechaudAndPot() {
  let cx = 635;

  // --- A. Circular Teak Base Tray on Smoked Glass (y = 492) ---
  // Shadow of tray on glass
  fillPoly(makeEllipsePts(cx + 8, 498, 168, 30), PAL.voidUmber, 220, 0.08, 0.2, 0.2);

  // Turned teak tray thickness & top face
  let traySidePts = [
    ...makeEllipsePts(cx, 488, 162, 27, 24).slice(0, 13),
    ...makeEllipsePts(cx, 498, 162, 28, 24).slice(0, 13).reverse()
  ];
  washPoly(traySidePts, PAL.darkChoc, 245);
  fillPoly(makeEllipsePts(cx, 488, 162, 27), PAL.warmWalnut, 235, 0.05, 0.25, 0.2);

  // Marker sheen across turned teak tray
  brush.set("marker", PAL.teakMid, 1.6);
  for (let r = 40; r <= 155; r += 22) {
    strokeEllipseArc(cx, 488, r, r * 0.165, 150, 380, 22);
  }
  brush.set("marker", PAL.teakLight, 1.3);
  strokeEllipseArc(cx, 488, 145, 24, 165, 285, 18);
  strokeEllipseArc(cx, 488, 110, 18, 175, 275, 16);

  // Warm orange-gold reflection of burner flame on center of teak tray
  fillPoly(makeEllipsePts(cx, 485, 78, 14), PAL.amberBright, 135, 0.2, 0.2, 0.1);
  brush.set("cpencil", PAL.specWhite, 0.65);
  strokeEllipseArc(cx, 489, 161, 27, 155, 290, 20);

  // --- B. Chrome/Steel Sterno Alcohol Burner (cx=635, y=456..486) ---
  let bRx = 56;
  let burnerPts = [
    [cx - bRx, 462], [cx + bRx, 462],
    [cx + bRx + 4, 484], [cx - bRx - 4, 484]
  ];
  washPoly(burnerPts, PAL.darkChoc, 245);

  // Metallic vertical chrome reflections on burner body
  let chromeCols = [PAL.chocBrown, PAL.glassBevel, PAL.specWhite, PAL.teakMid, PAL.voidUmber, PAL.enamelBurnt, PAL.amberHoney, PAL.darkChoc];
  for (let i = 0; i < chromeCols.length; i++) {
    let bx = map(i, 0, chromeCols.length - 1, cx - bRx + 4, cx + bRx - 4);
    brush.set("marker", chromeCols[i], 1.5);
    brush.line(bx, 462, bx, 484);
  }
  // Burner top lid & central perforated flame collar
  fillPoly(makeEllipsePts(cx, 462, bRx, 10), PAL.teakMid, 220, 0.04, 0.2, 0.2);
  brush.set("rotring", PAL.voidUmber, 0.85);
  strokeEllipseArc(cx, 462, bRx, 10, 0, 360, 24);
  brush.set("pen", PAL.specWhite, 0.75);
  strokeEllipseArc(cx, 462, bRx, 10, 160, 310, 18);
  strokeEllipseArc(cx, 458, 26, 5, 0, 360, 18);

  // Burner Snuffer Lever Handle jutting to the front-right
  brush.set("rotring", PAL.voidUmber, 1.3);
  brush.line(cx + 22, 464, cx + 108, 476);
  brush.set("pen", PAL.specWhite, 0.75);
  brush.line(cx + 22, 462.5, cx + 108, 474.5);
  // Small black wooden knob on burner lever
  fillPoly(makeEllipsePts(cx + 114, 476, 11, 7), PAL.voidUmber, 250, 0.02, 0.1, 0.2);
  brush.set("cpencil", PAL.teakGlow, 0.6);
  strokeEllipseArc(cx + 114, 475, 9, 5, 160, 310, 10);

  // --- C. Alcohol Burner Flame Licking the Bottom of the Pot (y = 424..458) ---
  // Outer translucent blue-violet alcohol glow
  fillPoly(makeEllipsePts(cx, 444, 44, 16), "#3868b5", 110, 0.35, 0.2, 0.05);
  fillPoly(makeEllipsePts(cx, 442, 32, 13), "#63a4eb", 130, 0.3, 0.2, 0.05);
  // Warm amber-orange flame tongues curling under the pot base
  fillPoly([
    [cx - 24, 456], [cx - 34, 434], [cx - 12, 426],
    [cx + 14, 426], [cx + 32, 435], [cx + 22, 456]
  ], PAL.enamelFlame, 175, 0.25, 0.2, 0.1);
  fillPoly(makeEllipsePts(cx - 2, 438, 18, 9), PAL.specWhite, 210, 0.2, 0.1, 0.05);

  // --- D. Wrought-Iron Rechaud Stand Legs (Back & Side Prongs) ---
  // Back struts
  brush.set("marker", PAL.voidUmber, 1.6);
  brush.line(cx - 88, 405, cx - 105, 480);
  brush.line(cx + 88, 405, cx + 105, 480);

  // --- E. THE BURNT-ORANGE ENAMEL FONDUE POT (cx=635, y=252..434) ---
  // Helper for pot radius from y=252 (flared rim) to y=434 (rounded bottom)
  function getPotRx(y) {
    let t = constrain((y - 252) / (434 - 252), 0, 1);
    if (t < 0.14) {
      // Flared top lip tapering into neck
      return lerp(142, 130, sin((t / 0.14) * 90));
    } else if (t < 0.65) {
      // Bulbous mid-belly
      let u = (t - 0.14) / 0.51;
      return lerp(130, 166, sin(u * 90));
    } else {
      // Rounded bottom bowl curving inward to base
      let u = (t - 0.65) / 0.35;
      return lerp(166, 86, pow(u, 1.55));
    }
  }

  // Construct full pot silhouette polygon
  let potLeftPts = [];
  let potRightPts = [];
  for (let y = 252; y <= 434; y += 6) {
    let rx = getPotRx(y);
    potLeftPts.push([cx - rx, y]);
    potRightPts.push([cx + rx, y]);
  }
  let potPoly = [...potLeftPts, ...potRightPts.reverse()];

  // 1. Solid opaque enamel base wash
  washPoly(potPoly, PAL.enamelDeep, 255);
  fillPoly(potPoly, PAL.enamelBurnt, 185, 0.04, 0.2, 0.2);

  // 2. Dense 3D Contoured Marker Shading across the Enamel Body
  // We draw latitude-following curved marker bands modulated by longitude angle
  for (let y = 255; y <= 432; y += 3.5) {
    let tY = (y - 252) / (434 - 252);
    let rx = getPotRx(y);
    let ryCurve = lerp(24, 34, tY); // perspective ellipse depth at this latitude

    // Divide each latitude arc into 5 longitude zones from left (180 deg) to right (0 deg):
    // Zone 1 (180..152 deg): Far-left dark mahogany turning edge
    brush.set("marker", y > 400 ? PAL.enamelBurnt : PAL.enamelMahogany, 1.45);
    strokeEllipseArc(cx, y - ryCurve * sin(166), rx, ryCurve, 148, 178, 8);

    // Zone 2 (152..102 deg): Main Lamp-Lit Saturated Burnt Orange Face
    let litCol = tY > 0.78 ? PAL.enamelFlame : (tY < 0.18 ? PAL.enamelVivid : PAL.enamelBright);
    brush.set("marker", litCol, 1.65);
    strokeEllipseArc(cx, y - ryCurve * sin(126), rx, ryCurve, 98, 152, 12);

    // Zone 3 (102..55 deg): Rich Mid-Tone Burnt Orange Center
    let midCol = tY > 0.82 ? PAL.enamelBright : PAL.enamelVivid;
    brush.set("marker", midCol, 1.65);
    strokeEllipseArc(cx, y - ryCurve * sin(78), rx, ryCurve, 52, 102, 12);

    // Zone 4 (55..22 deg): Core Shadow Band (Deep Persimmon / Mahogany)
    let coreCol = tY > 0.84 ? PAL.enamelBurnt : PAL.enamelDeep;
    brush.set("marker", coreCol, 1.6);
    strokeEllipseArc(cx, y - ryCurve * sin(38), rx, ryCurve, 20, 56, 10);

    // Zone 5 (22..2 deg): Right Rim Reflected Warm Amber Glow (from Amber Glass Tumbler)
    let rimCol = tY > 0.5 ? PAL.enamelVivid : PAL.enamelBurnt;
    brush.set("marker", rimCol, 1.35);
    strokeEllipseArc(cx, y - ryCurve * sin(12), rx, ryCurve, 2, 24, 8);
  }

  // 3. Longitude Marker Sweeps for Glassy Vertical Enamel Continuity
  let lonAngles = [165, 150, 136, 122, 108, 92, 76, 58, 40, 24, 12];
  for (let a of lonAngles) {
    let pts = [];
    for (let y = 256; y <= 430; y += 12) {
      let rx = getPotRx(y);
      let ry = lerp(24, 34, (y - 252) / 182);
      pts.push([cx + cos(a) * rx, y + sin(a) * ry * 0.25, 0.85]);
    }
    let col = (a >= 105 && a <= 145) ? PAL.enamelBright :
              (a >= 70 && a < 105) ? PAL.enamelVivid :
              (a >= 32 && a < 70) ? PAL.enamelDeep : PAL.enamelBurnt;
    brush.set("marker", col, 1.35);
    brush.spline(pts, 0.5);
  }

  // 4. Fiery Underglow on Bottom Belly from Burner Flame
  brush.set("marker", PAL.enamelFlame, 1.4);
  strokeEllipseArc(cx, 408, getPotRx(422), 28, 35, 145, 16);
  brush.set("cpencil", PAL.amberHoney, 0.85);
  strokeEllipseArc(cx, 414, getPotRx(428), 26, 50, 130, 14);

  // 5. Hyperrealistic Porcelain-Enamel Specular Reflections
  // Primary curved window/lamp highlight band on left-center belly (a = 128..142 deg)
  for (let a = 126; a <= 142; a += 2.5) {
    let pts = [];
    for (let y = 264; y <= 412; y += 10) {
      let rx = getPotRx(y);
      let ry = lerp(24, 34, (y - 252) / 182);
      pts.push([cx + cos(a) * rx, y + sin(a) * ry * 0.22, 0.9]);
    }
    let isCore = (a >= 131 && a <= 137);
    brush.set("marker", isCore ? PAL.specWhite : PAL.enamelPeach, isCore ? 1.25 : 1.5);
    brush.spline(pts, 0.55);
  }

  // Crisp razor-sharp window reflection panes inside the enamel highlight
  brush.set("pen", PAL.specWhite, 0.9);
  for (let a = 132; a <= 136; a += 2) {
    let pts1 = [];
    let pts2 = [];
    for (let y = 278; y <= 338; y += 10) {
      let rx = getPotRx(y);
      pts1.push([cx + cos(a) * rx, y + 5, 0.9]);
    }
    for (let y = 348; y <= 398; y += 10) {
      let rx = getPotRx(y);
      pts2.push([cx + cos(a) * rx, y + 6, 0.85]);
    }
    brush.spline(pts1, 0.5);
    brush.spline(pts2, 0.5);
  }

  // Secondary smaller specular reflection on right belly from amber tumbler
  brush.set("marker", PAL.enamelFlame, 1.15);
  for (let a = 16; a <= 22; a += 3) {
    let pts = [];
    for (let y = 290; y <= 390; y += 12) {
      let rx = getPotRx(y);
      pts.push([cx + cos(a) * rx, y + 4, 0.75]);
    }
    brush.spline(pts, 0.5);
  }
  brush.set("cpencil", PAL.enamelPeach, 0.65);
  strokeEllipseArc(cx, 260, 134, 24, 20, 160, 22);

  // Subtle porcelain glaze micro-texture along the highlight boundary
  brush.set("cpencil", PAL.enamelPeach, 0.45);
  for (let i = 0; i < 45; i++) {
    let y = random(270, 405);
    let rx = getPotRx(y);
    let a = random(116, 148);
    let px = cx + cos(a) * rx;
    let py = y + sin(a) * 6;
    brush.line(px, py, px + random(-3, 3), py + random(-2, 2));
  }

  // Crisp outer contour definition of the enamel pot
  brush.set("rotring", PAL.enamelShadow, 0.85);
  brush.spline(potLeftPts.map(p => [p[0], p[1], 0.8]), 0.5);
  brush.spline(potRightPts.map(p => [p[0], p[1], 0.8]), 0.5);

  // --- F. Wrought-Iron Front Support Prongs Cradling the Pot ---
  // Front-left prong (`x = 520..548, y = 392..490`) & Front-right prong (`x = 722..750, y = 392..490`)
  let leftProng = [[528, 388], [548, 398], [538, 442], [512, 492], [498, 490], [524, 438]];
  let rightProng = [[742, 388], [722, 398], [732, 442], [758, 492], [772, 490], [746, 438]];
  washPoly(leftProng, PAL.voidUmber, 250);
  washPoly(rightProng, PAL.voidUmber, 250);
  // Upper metal ring cradling pot belly
  brush.set("marker", PAL.voidUmber, 2.0);
  strokeEllipseArc(cx, 398, 156, 28, 18, 162, 24);
  brush.set("pen", PAL.enamelPeach, 0.7);
  strokeEllipseArc(cx, 396.5, 156, 28, 30, 150, 20);
  brush.line(528, 388, 524, 438);
  brush.line(524, 438, 498, 490);
  brush.line(742, 388, 746, 438);

  // --- G. Teak Wood Side Handle & Chrome Bracket (Left of Pot, x=320..502, y=288..342) ---
  // 1. Chrome mounting boss on left side of pot (x=475..506, y=306..340)
  let bracketPts = [[472, 310], [502, 304], [506, 338], [474, 334]];
  washPoly(bracketPts, PAL.darkChoc, 250);
  brush.set("marker", PAL.glassBevel, 1.5);
  brush.line(474, 314, 502, 310);
  brush.set("marker", PAL.enamelVivid, 1.3);
  brush.line(475, 326, 504, 328);
  brush.set("pen", PAL.specWhite, 0.85);
  brush.line(473, 312, 501, 308);
  brush.set("rotring", PAL.voidUmber, 0.8);
  strokeEllipseArc(473, 322, 6, 12, 0, 360, 16);

  // 2. Turned Teak Wood Handle (from x=473, y=322 out to x=328, y=296)
  let hPts = [
    [328, 282], [473, 310],
    [473, 334], [324, 312]
  ];
  washPoly(hPts, PAL.darkChoc, 255);

  // Longitudinal marker passes for turned teak cylinder
  let hCols = [
    { t: 0.12, col: PAL.teakLight, w: 1.4 },
    { t: 0.25, col: PAL.teakGlow, w: 1.3 },
    { t: 0.42, col: PAL.teakMid, w: 1.6 },
    { t: 0.62, col: PAL.warmWalnut, w: 1.6 },
    { t: 0.80, col: PAL.chocBrown, w: 1.5 },
    { t: 0.92, col: PAL.teakDark, w: 1.2 }
  ];
  for (let hc of hCols) {
    let xL = lerp(328, 324, hc.t);
    let yL = lerp(282, 312, hc.t);
    let xR = 473;
    let yR = lerp(310, 334, hc.t);
    brush.set("marker", hc.col, hc.w);
    brush.line(xL, yL, xR, yR);
  }

  // Wood grain & specular highlight along the top ridge of the teak handle
  brush.set("cpencil", PAL.rugTip, 0.75);
  brush.line(330, 286, 471, 313);
  brush.set("cpencil", PAL.voidUmber, 0.65);
  for (let g = 0; g < 5; g++) {
    let t = 0.2 + g * 0.15;
    brush.line(lerp(328, 324, t), lerp(282, 312, t), 473, lerp(310, 334, t));
  }

  // Handle end cap & black iron hanging ring at x=325, y=297
  fillPoly(makeEllipsePts(326, 297, 7, 15, 20, 8), PAL.chocBrown, 250, 0.02, 0.2, 0.2);
  brush.set("rotring", PAL.voidUmber, 1.1);
  strokeEllipseArc(326, 297, 7, 15, 0, 360, 18);
  strokeEllipseArc(312, 302, 14, 11, 40, 330, 18);
  brush.set("pen", PAL.glassBevel, 0.65);
  strokeEllipseArc(312, 301, 14, 11, 160, 290, 12);
}

// =========================================================================
// 6. BUBBLING CHEESE, COLOURED-TIP FORKS & DRIPPING BREAD CUBE
// =========================================================================

function drawCheeseForksAndBread() {
  let cx = 635;
  let rimY = 254;
  let rimRx = 142;
  let rimRy = 26;

  // --- A. Enameled Rim Lip & Cream Interior Wall ---
  // Outer burnt-orange rolled lip
  fillPoly(makeEllipsePts(cx, rimY, rimRx, rimRy), PAL.enamelShadow, 250, 0.02, 0.15, 0.2);
  // Cream-glazed interior wall visible above cheese level
  fillPoly(makeEllipsePts(cx, rimY + 1, rimRx - 7, rimRy - 2), PAL.napkinMid, 245, 0.04, 0.25, 0.2);
  brush.set("marker", PAL.napkinLight, 1.5);
  strokeEllipseArc(cx, rimY, rimRx - 8, rimRy - 3, 195, 345, 22);
  brush.set("marker", PAL.napkinShadow, 1.4);
  strokeEllipseArc(cx, rimY, rimRx - 8, rimRy - 3, 18, 175, 20);

  // --- B. Molten Bubbling Gruyère & Cheddar Cheese Pool (y = 257) ---
  let chRx = rimRx - 11;
  let chRy = rimRy - 4;
  washPoly(makeEllipsePts(cx, rimY + 3, chRx, chRy), PAL.cheeseMid, 255);
  fillPoly(makeEllipsePts(cx, rimY + 3, chRx - 4, chRy - 1), PAL.cheeseGold, 210, 0.08, 0.25, 0.15);
  fillPoly(makeEllipsePts(cx - 14, rimY + 2, chRx * 0.72, chRy * 0.72), PAL.cheeseBright, 185, 0.12, 0.2, 0.1);

  // Swirling velvety cheese texture in marker
  brush.set("marker", PAL.cheeseGold, 1.5);
  strokeEllipseArc(cx, rimY + 3, chRx * 0.85, chRy * 0.82, 10, 350, 26);
  brush.set("marker", PAL.cheeseBright, 1.4);
  strokeEllipseArc(cx - 8, rimY + 2, chRx * 0.62, chRy * 0.62, 140, 380, 22);
  brush.set("marker", PAL.cheeseCream, 1.2);
  strokeEllipseArc(cx - 18, rimY + 1, chRx * 0.42, chRy * 0.42, 165, 330, 16);

  // Glossy Blistered Cheese Bubbles Across the Surface
  let bubbles = [
    { x: 552, y: 256, rx: 14, ry: 5.5 },
    { x: 584, y: 249, rx: 18, ry: 6.5 },
    { x: 618, y: 261, rx: 22, ry: 7.5 },
    { x: 652, y: 251, rx: 19, ry: 6.8 },
    { x: 688, y: 258, rx: 16, ry: 5.8 },
    { x: 718, y: 253, rx: 12, ry: 4.5 },
    { x: 636, y: 244, rx: 13, ry: 4.8 },
    { x: 568, y: 264, rx: 11, ry: 4.2 },
    { x: 672, y: 266, rx: 14, ry: 5.0 },
    { x: 602, y: 254, rx: 10, ry: 3.8 },
    { x: 702, y: 247, rx: 9, ry: 3.5 }
  ];

  for (let b of bubbles) {
    // Darker golden-amber shadow ring around bubble base
    brush.set("marker", PAL.cheeseShadow, 1.1);
    strokeEllipseArc(b.x, b.y + 1, b.rx, b.ry, 0, 360, 16);
    // Swollen golden dome of the bubble
    brush.set("marker", PAL.cheeseBright, 1.3);
    strokeEllipseArc(b.x, b.y - 0.5, b.rx * 0.78, b.ry * 0.78, 160, 370, 14);
    // Razor-sharp white-cream specular crescent on upper-left of bubble
    brush.set("pen", PAL.specWhite, 0.75);
    strokeEllipseArc(b.x - b.rx * 0.15, b.y - b.ry * 0.2, b.rx * 0.55, b.ry * 0.5, 185, 315, 10);
  }

  // Front lip of the pot rim overlapping the front edge of the cheese pool
  brush.set("marker", PAL.enamelVivid, 1.6);
  strokeEllipseArc(cx, rimY, rimRx - 2, rimRy, 8, 172, 28);
  brush.set("rotring", PAL.enamelShadow, 0.9);
  strokeEllipseArc(cx, rimY, rimRx, rimRy, 0, 360, 36);
  // Bright porcelain rim highlight
  brush.set("pen", PAL.specWhite, 0.85);
  strokeEllipseArc(cx, rimY, rimRx - 3, rimRy - 1, 95, 168, 18);
  strokeEllipseArc(cx, rimY, rimRx - 3, rimRy - 1, 200, 265, 14);

  // --- C. Long Fondue Forks with 1970s Coloured Tips ---
  function drawFondueFork(xSub, ySub, xTip, yTip, handleColDark, handleColMid, handleColHi, tipBandCol, tipBandHi) {
    let dx = xTip - xSub;
    let dy = yTip - ySub;
    let len = sqrt(dx * dx + dy * dy);
    let ux = dx / len;
    let uy = dy / len;
    let nx = -uy;
    let ny = ux;

    // Steel shaft from cheese surface (0.0) to wooden handle ferrule (0.56)
    let xFer = xSub + ux * (len * 0.56);
    let yFer = ySub + uy * (len * 0.56);

    // Shadow under shaft on pot rim
    brush.set("2B", PAL.voidUmber, 0.85);
    brush.line(xSub + 2, ySub + 3, xFer + 2, yFer + 3);

    // Stainless steel shaft
    brush.set("rotring", PAL.darkChoc, 1.25);
    brush.line(xSub, ySub, xFer, yFer);
    brush.set("pen", PAL.specWhite, 0.85);
    brush.line(xSub + nx * 1.3, ySub + ny * 1.3, xFer + nx * 1.3, yFer + ny * 1.3);

    // Cheese ripple around submerged shaft entry point
    brush.set("marker", PAL.cheeseShadow, 1.0);
    strokeEllipseArc(xSub, ySub, 9, 3.5, 0, 360, 12);
    brush.set("pen", PAL.specWhite, 0.65);
    strokeEllipseArc(xSub, ySub - 0.5, 7, 2.5, 170, 330, 10);

    // Wooden/Bakelite Handle (from 0.56 to 0.86) + Coloured Tip (from 0.86 to 1.0)
    let xColStart = xSub + ux * (len * 0.85);
    let yColStart = ySub + uy * (len * 0.85);
    let hw = 6.2;

    let bodyPts = [
      [xFer + nx * (hw * 0.7), yFer + ny * (hw * 0.7)],
      [xColStart + nx * hw, yColStart + ny * hw],
      [xColStart - nx * hw, yColStart - ny * hw],
      [xFer - nx * (hw * 0.7), yFer - ny * (hw * 0.7)]
    ];
    washPoly(bodyPts, handleColDark, 255);
    brush.set("marker", handleColMid, 1.4);
    brush.line(xFer, yFer, xColStart, yColStart);
    brush.set("pen", handleColHi, 0.8);
    brush.line(xFer + nx * (hw * 0.45), yFer + ny * (hw * 0.45), xColStart + nx * (hw * 0.65), yColStart + ny * (hw * 0.65));

    // Coloured Tip Cap (0.85 to 1.0)
    let tipPts = [
      [xColStart + nx * hw, yColStart + ny * hw],
      [xTip + nx * (hw * 0.85), yTip + ny * (hw * 0.85)],
      [xTip - nx * (hw * 0.85), yTip - ny * (hw * 0.85)],
      [xColStart - nx * hw, yColStart - ny * hw]
    ];
    washPoly(tipPts, tipBandCol, 255);
    brush.set("marker", tipBandCol, 1.5);
    brush.line(xColStart, yColStart, xTip, yTip);
    brush.set("pen", tipBandHi, 0.9);
    brush.line(xColStart + nx * (hw * 0.5), yColStart + ny * (hw * 0.5), xTip + nx * (hw * 0.45), yTip + ny * (hw * 0.45));

    // Chrome ferrule ring & division ring
    brush.set("pen", PAL.specWhite, 0.85);
    brush.line(xFer + nx * hw * 0.75, yFer + ny * hw * 0.75, xFer - nx * hw * 0.75, yFer - ny * hw * 0.75);
    brush.line(xColStart + nx * hw, yColStart + ny * hw, xColStart - nx * hw, yColStart - ny * hw);

    // Crisp outline around handle
    brush.set("rotring", PAL.voidUmber, 0.65);
    brush.line(xFer + nx * (hw * 0.7), yFer + ny * (hw * 0.7), xTip + nx * (hw * 0.85), yTip + ny * (hw * 0.85));
    brush.line(xFer - nx * (hw * 0.7), yFer - ny * (hw * 0.7), xTip - nx * (hw * 0.85), yTip - ny * (hw * 0.85));
    brush.line(xTip + nx * (hw * 0.85), yTip + ny * (hw * 0.85), xTip - nx * (hw * 0.85), yTip - ny * (hw * 0.85));
  }

  // Fork 1 (Back-Left, Chocolate/Walnut handle with Mustard Tip)
  drawFondueFork(572, 248, 492, 118, PAL.darkChoc, PAL.warmWalnut, PAL.teakLight, PAL.rugBright, PAL.rugTip);

  // Fork 2 (Back-Right, Dark Teak handle with Avocado Green Tip)
  drawFondueFork(668, 246, 762, 108, PAL.darkChoc, PAL.teakDark, PAL.teakLight, PAL.avocadoMid, PAL.avocadoHighlight);

  // Fork 3 (Front-Right, Ebony/Chocolate handle with Harvest Mustard/Amber Tip)
  drawFondueFork(706, 255, 845, 138, PAL.voidUmber, PAL.chocBrown, PAL.teakMid, PAL.amberBright, PAL.amberHoney);

  // --- D. 4th Fork Holding a Cube of Crusty Bread Dripping Cheese (x=425..612, y=95..258) ---
  // Fork 4 held poised above the pot from upper-left (425, 92) to bread cube at (594, 184)
  // Draw handle & shaft first (with Burnt-Orange Tip!)
  drawFondueFork(584, 180, 425, 92, PAL.darkChoc, PAL.warmWalnut, PAL.teakGlow, PAL.enamelVivid, PAL.enamelPeach);

  // Twin steel prongs piercing the top of the bread cube
  brush.set("rotring", PAL.darkChoc, 0.95);
  brush.line(576, 175, 592, 186);
  brush.line(580, 171, 597, 182);
  brush.set("pen", PAL.specWhite, 0.75);
  brush.line(577, 174, 593, 185);
  brush.line(581, 170, 598, 181);

  // --- E. The Cube of Crusty Sourdough Bread (center ~ 604, 196) ---
  // Top-left toasted crust plane
  let breadTopPts = [[578, 184], [612, 172], [634, 185], [600, 198]];
  // Left porous crumb plane (lit by lamp)
  let breadLeftPts = [[578, 184], [600, 198], [598, 224], [576, 210]];
  // Right crumb plane (in warm shadow)
  let breadRightPts = [[600, 198], [634, 185], [630, 212], [598, 224]];

  washPoly(breadTopPts, PAL.teakDark, 250);
  washPoly(breadLeftPts, PAL.napkinWarm, 250);
  washPoly(breadRightPts, PAL.napkinShadow, 250);

  // Golden-brown crust & porous bread crumb texture
  brush.set("marker", PAL.teakLight, 1.3);
  brush.line(582, 184, 612, 174);
  brush.line(588, 188, 622, 178);
  brush.set("cpencil", PAL.napkinHighlight, 0.75);
  for (let i = 0; i < 18; i++) {
    let bx = random(580, 598);
    let by = random(188, 212);
    brush.line(bx, by, bx + random(-2, 2), by + random(-2, 2));
  }
  // Tiny toasted air pockets in the bread crumb
  brush.set("2B", PAL.chocBrown, 0.65);
  let pores = [[584, 193], [591, 198], [587, 203], [594, 194], [608, 195], [616, 192], [622, 197], [612, 201]];
  for (let p of pores) {
    brush.line(p[0], p[1], p[0] + 2, p[1] + 1);
  }

  // --- F. Molten Cheese Coating the Bread & Dripping into the Pot ---
  // Thick golden cheese blanket wrapping the lower half of the bread cube
  let coatPts = [
    [575, 198], [590, 195], [604, 200], [620, 194], [633, 198],
    [631, 215], [615, 222], [598, 228], [582, 220], [574, 212]
  ];
  washPoly(coatPts, PAL.cheeseGold, 255);
  fillPoly(coatPts, PAL.cheeseBright, 220, 0.05, 0.2, 0.15);

  // Three viscous strands of melted cheese stretching down from the bread into the pot!
  // 1. Main central thick ribbon (from x=598, y=224 down to x=602, y=258)
  let mainDripPts = [
    [591, 221], [606, 221],
    [602, 238], [604, 252], [612, 259],
    [592, 259], [597, 252], [596, 238]
  ];
  washPoly(mainDripPts, PAL.cheeseGold, 250);
  brush.set("marker", PAL.cheeseBright, 1.5);
  brush.spline([[598, 212, 1.0], [599, 232, 0.7], [600, 246, 0.65], [602, 258, 0.95]], 0.5);

  // 2. Left thinner strand with hanging molten teardrop bead (x=581, y=216..255)
  brush.set("marker", PAL.cheeseGold, 1.15);
  brush.spline([[581, 215, 0.9], [582, 232, 0.55], [583, 246, 0.85]], 0.4);
  fillPoly(makeEllipsePts(583, 245, 4.5, 7), PAL.cheeseBright, 245, 0.02, 0.1, 0.1);
  // Falling droplet below left strand
  fillPoly(makeEllipsePts(584, 256, 3.5, 4.5), PAL.cheeseBright, 245, 0.02, 0.1, 0.1);

  // 3. Right stretching cheese thread (x=618, y=216..256)
  brush.set("marker", PAL.cheeseGold, 1.1);
  brush.spline([[618, 215, 0.95], [616, 234, 0.45], [615, 255, 0.8]], 0.45);

  // Shadow edge on right side of cheese coating & drips
  brush.set("cpencil", PAL.cheeseShadow, 0.75);
  brush.spline([[632, 199, 0.8], [630, 214, 0.8], [615, 222, 0.8], [604, 226, 0.8]], 0.5);
  brush.line(603, 224, 604, 256);
  brush.line(619, 216, 616, 254);

  // Glossy white-cream specular highlights on the wet dripping cheese!
  brush.set("pen", PAL.specWhite, 0.85);
  brush.spline([[578, 203, 0.8], [588, 208, 0.9], [598, 216, 0.9], [599, 236, 0.75], [600, 255, 0.8]], 0.5);
  brush.spline([[606, 204, 0.7], [616, 208, 0.8], [617, 228, 0.6]], 0.5);
  brush.line(581, 218, 582, 246);
  // Specular concentric rings where the cheese drip lands in the pot
  strokeEllipseArc(602, 258, 12, 4, 150, 390, 14);
  strokeEllipseArc(615, 255, 7, 2.5, 160, 360, 10);
}

// =========================================================================
// 7. FALLEN COCKTAIL NAPKIN WITH CIGARETTE-BURNED EDGE
// =========================================================================

function drawFallenNapkinWithBurn() {
  // The cocktail napkin lies nestled in the foreground shag pile at x=215..520, y=885..1045.
  // Its right edge (around x=475..505, y=950..990) has a scalloped cigarette burn notch!

  // 1. Deep shadow cast into the shag carpet tufts beneath the napkin
  let shadowPts = [
    [225, 938], [362, 888], [518, 938],
    [495, 962], [472, 974], [488, 992],
    [468, 1012], [352, 1052], [218, 952]
  ];
  fillPoly(shadowPts, PAL.voidUmber, 210, 0.15, 0.35, 0.2);

  // 2. Napkin Silhouette with Concave Scalloped Cigarette-Burn Bite on Right Edge
  // Top-left corner: (220, 934)
  // Top-back corner: (360, 882)
  // Far-right corner: (514, 932)
  // Burn notch enters at (494, 952), curves inward around (462, 968), exits at (478, 992)
  // Bottom-front corner: (348, 1044)
  let napkinPts = [
    [220, 934], [290, 906], [360, 882], [438, 905], [514, 932],
    [504, 943], [494, 952],
    // Irregular scalloped cigarette burn notch
    [479, 954], [467, 960], [461, 969], [464, 979], [472, 986], [478, 992],
    // Remainder of lower-right edge to bottom corner
    [464, 1004], [410, 1025], [348, 1044], [282, 992], [220, 934]
  ];

  // Warm vintage cream paper base toned by the amber room light
  washPoly(napkinPts, PAL.napkinWarm, 250);

  // Left half (tilted up toward the hanging lamp — brighter warm cream)
  let leftFoldPts = [
    [220, 934], [360, 882], [392, 955], [348, 1044], [282, 992]
  ];
  fillPoly(leftFoldPts, PAL.napkinLight, 195, 0.08, 0.3, 0.15);

  // Right half (sloping slightly away — warm golden-ecru shadow)
  let rightFoldPts = [
    [360, 882], [514, 932], [494, 952],
    [467, 960], [461, 969], [464, 979], [478, 992],
    [464, 1004], [348, 1044], [392, 955]
  ];
  fillPoly(rightFoldPts, PAL.napkinMid, 165, 0.08, 0.3, 0.15);

  // Soft fold ridges & crumple valleys across the paper
  brush.set("marker", PAL.napkinHighlight, 1.5);
  brush.spline([[360, 884, 0.6], [378, 922, 0.9], [392, 956, 1.0], [368, 1002, 0.85], [348, 1042, 0.5]], 0.5);
  brush.spline([[245, 932, 0.5], [315, 945, 0.85], [392, 956, 0.9]], 0.5);

  brush.set("marker", PAL.napkinShadow, 1.25);
  brush.spline([[364, 886, 0.5], [384, 924, 0.8], [398, 958, 0.9], [374, 1004, 0.75], [354, 1040, 0.5]], 0.5);
  brush.spline([[395, 958, 0.8], [435, 952, 0.7], [468, 956, 0.8]], 0.5);

  // Fine paper-grain texture & waffle-embossed cocktail napkin margin
  brush.set("2H", PAL.napkinShadow, 0.42);
  for (let i = 0; i < 38; i++) {
    let t = i / 38;
    let x1 = lerp(230, 352, t);
    let y1 = lerp(936, 1036, t);
    let x2 = lerp(358, 462, t);
    let y2 = lerp(888, 998, t);
    // Clip line so it doesn't cross the burn notch
    if (y2 > 948 && y2 < 992) x2 = min(x2, 458);
    brush.line(x1, y1, x2, y2);
  }

  // Vintage 1970s Printed Border Stripes (Avocado Green & Harvest Mustard)
  // Parallel to the 4 outer edges of the cocktail napkin
  brush.set("cpencil", PAL.avocadoMid, 0.75);
  // Top-left border
  brush.line(238, 936, 360, 892);
  // Bottom-left border
  brush.line(238, 936, 350, 1028);
  // Top-right border
  brush.line(360, 892, 496, 936);
  // Bottom-right border (interrupted by the cigarette burn!)
  brush.line(496, 936, 484, 949);
  brush.line(462, 993, 350, 1028);

  brush.set("cpencil", PAL.rugMustard, 0.65);
  brush.line(245, 938, 360, 897);
  brush.line(245, 938, 351, 1022);
  brush.line(360, 897, 489, 939);
  brush.line(456, 991, 351, 1022);

  // Crisp lit left edge of the paper napkin
  brush.set("pen", PAL.napkinHighlight, 0.75);
  brush.line(220, 934, 360, 882);
  brush.line(220, 934, 348, 1044);

  // --- 3. THE CIGARETTE-BURNED EDGE (Hyperrealistic Singe, Char, Ash & Ember) ---
  // Burn arc center is roughly (482, 972), curving inward to x=461
  // Layer A: Outer toasted amber-sepia singed paper halo
  let haloOuterPts = [
    [504, 943], [494, 952],
    [479, 954], [467, 960], [461, 969], [464, 979], [472, 986], [478, 992],
    [464, 1004], [448, 994], [442, 978], [442, 962], [454, 946], [478, 938]
  ];
  fillPoly(haloOuterPts, PAL.amberMid, 165, 0.18, 0.35, 0.2);

  // Layer B: Darker roasted-umber scorch zone closer to the edge
  let haloInnerPts = [
    [498, 948], [494, 952],
    [479, 954], [467, 960], [461, 969], [464, 979], [472, 986], [478, 992],
    [470, 998], [455, 986], [451, 972], [454, 956], [470, 946]
  ];
  fillPoly(haloInnerPts, PAL.chocBrown, 210, 0.12, 0.35, 0.25);

  // Colored pencil shading for the toasted brown paper gradient
  brush.set("cpencil", PAL.teakMid, 0.85);
  strokeEllipseArc(484, 971, 34, 24, 115, 255, 18);
  brush.set("cpencil", PAL.darkChoc, 0.95);
  strokeEllipseArc(484, 971, 26, 19, 112, 258, 18);

  // Layer C: Brittle, ragged carbon-black charred edge
  let burnEdgePts = [
    [495, 951, 0.9], [484, 953, 1.0], [473, 957, 1.1],
    [464, 964, 1.2], [461, 971, 1.2], [464, 979, 1.1],
    [471, 986, 1.0], [478, 992, 0.9]
  ];
  brush.set("2B", PAL.voidUmber, 1.85);
  brush.spline(burnEdgePts, 0.45);
  brush.set("rotring", "#050302", 1.15);
  brush.spline(burnEdgePts, 0.45);

  // Jagged micro-fissures and curled char flakes along the burned lip
  brush.set("rotring", PAL.voidUmber, 0.65);
  for (let i = 0; i < 28; i++) {
    let a = map(i, 0, 27, 112, 255);
    let bx = 483 + cos(a) * 22 + random(-2, 2);
    let by = 971 + sin(a) * 18 + random(-2, 2);
    brush.line(bx, by, bx - cos(a) * random(3, 7), by - sin(a) * random(2, 5));
  }

  // Layer D: Flaky Pale-Grey & White Cigarette Ash Crumbles on Edge and Carpet Below
  brush.set("cpencil", PAL.ashGrey, 0.85);
  for (let i = 0; i < 32; i++) {
    let a = random(118, 250);
    let r = random(19, 25);
    let ax = 483 + cos(a) * r + random(-4, 10);
    let ay = 971 + sin(a) * (r * 0.8) + random(-2, 16);
    brush.line(ax, ay, ax + random(-2.5, 2.5), ay + random(-1.5, 1.5));
  }
  brush.set("pen", PAL.ashLight, 0.65);
  for (let i = 0; i < 20; i++) {
    let a = random(125, 245);
    let ax = 482 + cos(a) * 21.5 + random(-2, 8);
    let ay = 971 + sin(a) * 17 + random(-1, 12);
    brush.line(ax, ay, ax + random(-1.5, 1.5), ay + random(-1, 1));
  }

  // Tiny black char crumbs scattered into the golden shag tufts right under the burn notch
  brush.set("2B", PAL.voidUmber, 0.75);
  for (let i = 0; i < 24; i++) {
    let cxAsh = random(464, 504);
    let cyAsh = random(962, 1002);
    brush.line(cxAsh, cyAsh, cxAsh + random(-2, 2), cyAsh + random(-1.5, 1.5));
  }

  // Layer E: Tiny Smoldering Orange-Red Ember Pinprick on the Charred Edge (462, 969)
  brush.set("marker", PAL.enamelVivid, 1.1);
  brush.line(461, 968, 463, 971);
  brush.set("pen", PAL.enamelFlame, 0.9);
  brush.line(461.5, 968.5, 462.5, 970);
  brush.set("pen", PAL.specWhite, 0.65);
  brush.line(462, 969, 462.3, 969.3);

  // Foreground carpet strands curling slightly over the bottom edges of the napkin
  drawLocalShagTufts(225, 348, 1036, 18, 1.15);
  drawLocalShagTufts(352, 455, 1028, 16, 1.15);
}

// =========================================================================
// 8. HANGING TASSELLED LAMP & WARM, SMOKY, HAZY ATMOSPHERE
// =========================================================================

function drawTasselledLamp() {
  let lx = 265;
  let shadeTopY = 18;
  let shadeBotY = 136;
  let rxTop = 105;
  let rxBot = 178;

  // 1. Warm Incandescent Halo Behind & Under the Lamp Shade
  fillPoly(makeEllipsePts(lx, 148, 245, 95), PAL.amberMid, 90, 0.4, 0.25, 0.05);
  fillPoly(makeEllipsePts(lx, 146, 168, 52), PAL.rugGold, 130, 0.35, 0.2, 0.05);

  // Brass swag chain at very top (y = 0..22)
  brush.set("marker", PAL.chocBrown, 1.5);
  brush.line(lx, 0, lx, 22);
  brush.set("pen", PAL.amberHoney, 0.85);
  brush.line(lx - 2, 0, lx - 2, 22);

  // 2. Inside Under-Glow of the Shade Opening (visible through the ellipse at y = 136)
  fillPoly(makeEllipsePts(lx, shadeBotY + 4, rxBot - 6, 30), PAL.amberBright, 220, 0.15, 0.2, 0.1);
  fillPoly(makeEllipsePts(lx, shadeBotY + 2, 115, 20), PAL.rugSunlit, 235, 0.15, 0.15, 0.1);
  fillPoly(makeEllipsePts(lx, shadeBotY, 64, 12), PAL.specWhite, 245, 0.12, 0.1, 0.05);

  // 3. Back-Row Fringe Tassels (hanging from the far side of the shade rim, y = 138..212)
  let backTassels = 16;
  for (let i = 1; i < backTassels; i++) {
    let a = map(i, 0, backTassels, 192, 348);
    let tx = lx + cos(a) * (rxBot - 4);
    let ty = shadeBotY + sin(a) * 28 + 16;
    let tLen = 58 + sin(i * 37) * 4;

    brush.set("marker", PAL.chocBrown, 1.35);
    brush.line(tx, ty, tx + random(-2, 2), ty + tLen);
    brush.set("cpencil", PAL.amberBright, 0.65);
    brush.line(tx + 2, ty + 6, tx + 2, ty + tLen - 4);
  }

  // 4. Pleated Mustard & Amber-Gold Fabric Lamp Shade Body (y = 18..136)
  let shadePts = [
    [lx - rxTop, shadeTopY], [lx + rxTop, shadeTopY],
    ...makeEllipsePts(lx, shadeBotY, rxBot, 28, 32).slice(0, 17)
  ];
  washPoly(shadePts, PAL.teakMid, 245);
  fillPoly(shadePts, PAL.rugMustard, 185, 0.08, 0.3, 0.2);

  // Internal warm light glow transmitting through the lower center of the fabric shade
  fillPoly(makeEllipsePts(lx, 102, 132, 38), PAL.amberHoney, 145, 0.25, 0.25, 0.1);

  // Vertical Pleated Ribs on the Shade
  let numPleats = 19;
  for (let p = 0; p <= numPleats; p++) {
    let t = p / numPleats;
    let a = map(t, 0, 1, 180, 0);
    let xT = lx + cos(a) * rxTop;
    let yT = shadeTopY + sin(a) * 14;
    let xB = lx + cos(a) * rxBot;
    let yB = shadeBotY + sin(a) * 28;

    let distCenter = abs(t - 0.5) * 2;
    let ribCol = distCenter < 0.45 ? PAL.rugSunlit : (distCenter < 0.75 ? PAL.rugGold : PAL.teakDark);
    brush.set("marker", ribCol, 1.45);
    brush.line(xT, yT, xB, yB);

    // Shadow crease between pleats
    brush.set("cpencil", PAL.chocBrown, 0.65);
    brush.line(xT + 3, yT, xB + 4, yB);
  }

  // Decorative Braided Gimp Trim Band along Bottom Rim (Avocado, Mustard & Burnt Orange)
  brush.set("marker", PAL.chocBrown, 2.1);
  strokeEllipseArc(lx, shadeBotY - 2, rxBot + 1, 28, 4, 176, 28);
  brush.set("marker", PAL.avocadoMid, 1.3);
  strokeEllipseArc(lx, shadeBotY - 4, rxBot + 1, 28, 8, 172, 26);
  brush.set("cpencil", PAL.enamelVivid, 0.85);
  strokeEllipseArc(lx, shadeBotY, rxBot + 1, 28, 10, 170, 26);
  brush.set("pen", PAL.rugTip, 0.75);
  strokeEllipseArc(lx, shadeBotY - 6, rxBot, 27, 25, 155, 22);

  // 5. Front-Row Hanging Bullion Fringe Tassels (25 detailed tassels along the front arc)
  let frontTassels = 25;
  for (let i = 0; i <= frontTassels; i++) {
    let t = i / frontTassels;
    let a = map(t, 0, 1, 176, 4);
    let tx = lx + cos(a) * rxBot;
    let ty = shadeBotY + sin(a) * 28;
    let tLen = 68 + sin(a) * 10;

    // Illumination from the bulb directly behind the front tassels
    let rimGlow = sin(t * 180);

    // Tassel shadow core
    brush.set("marker", PAL.warmWalnut, 1.4);
    brush.spline([
      [tx, ty, 0.95],
      [tx + sin(i * 45) * 2, ty + tLen * 0.5, 1.1],
      [tx + cos(i * 30) * 2.5, ty + tLen, 0.7]
    ], 0.4);

    // Golden-mustard & burnt-orange braided yarn strands on each tassel
    let strandCol = (i % 4 === 0) ? PAL.enamelBurnt : (rimGlow > 0.5 ? PAL.rugGold : PAL.rugMustard);
    brush.set("cpencil", strandCol, 0.85);
    brush.line(tx - 2, ty + 4, tx - 2.5, ty + tLen - 2);
    brush.line(tx + 2, ty + 4, tx + 2.5, ty + tLen - 2);

    // Bright backlit golden-cream rim light on each tassel
    if (rimGlow > 0.25) {
      brush.set("pen", PAL.rugTip, 0.65);
      brush.line(tx - 3.2, ty + 10, tx - 3, ty + tLen);
    }

    // Little tied bullion knot at neck of tassel (y = ty + 11)
    brush.set("rotring", PAL.darkChoc, 0.75);
    brush.line(tx - 3.5, ty + 11, tx + 3.5, ty + 11);
    brush.set("pen", PAL.amberHoney, 0.65);
    brush.line(tx - 3, ty + 9.5, tx + 3, ty + 9.5);
  }
}

