function drawPastelGround() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);

  const washes = [
    { x: 600, y: 120, w: 1120, h: 220, col: PALETTE.pastelRose, op: 65 },
    { x: 140, y: 600, w: 260, h: 1050, col: PALETTE.pastelSage, op: 70 },
    { x: 1060, y: 620, w: 260, h: 1050, col: PALETTE.pastelLilac, op: 65 },
    { x: 600, y: 1080, w: 1120, h: 240, col: PALETTE.pastelPeach, op: 70 }
  ];

  for (let w of washes) {
    brush.fill(w.col, w.op);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }
  brush.noFill();
}

// ============================================================================
// 2. VIENNA SECESSION MOSAIC (FLAT KLIMT ORNAMENT)
// ============================================================================

function drawSecessionMosaic() {
  brush.noField();

  // Define rectilinear Secessionist robe/frieze panels around the canvas
  const panels = [
    // Top frieze panels
    { x: 40, y: 40, w: 480, h: 135, type: "gold_squares", bg: PALETTE.pastelCream },
    { x: 520, y: 40, w: 360, h: 135, type: "spiral_eyes", bg: PALETTE.pastelRose },
    { x: 880, y: 40, w: 280, h: 230, type: "gold_squares", bg: PALETTE.goldLight },

    // Left vertical panels
    { x: 40, y: 175, w: 210, h: 340, type: "spiral_eyes", bg: PALETTE.pastelSage },
    { x: 40, y: 515, w: 165, h: 365, type: "gold_squares", bg: PALETTE.pastelPeach },
    { x: 40, y: 880, w: 250, h: 280, type: "spiral_eyes", bg: PALETTE.pastelLilac },

    // Right vertical panels
    { x: 975, y: 270, w: 185, h: 390, type: "spiral_eyes", bg: PALETTE.pastelSage },
    { x: 975, y: 660, w: 185, h: 305, type: "gold_squares", bg: PALETTE.pastelRose },

    // Bottom ceremonial frieze panels
    { x: 290, y: 965, w: 350, h: 195, type: "gold_squares", bg: PALETTE.goldLight },
    { x: 640, y: 965, w: 335, h: 195, type: "spiral_eyes", bg: PALETTE.pastelPeach },
    { x: 975, y: 965, w: 185, h: 195, type: "gold_squares", bg: PALETTE.pastelSage },

    // Seeping inner corners that step into the slate perimeter
    { x: 205, y: 175, w: 95, h: 95, type: "chequer", bg: PALETTE.secIvory },
    { x: 860, y: 175, w: 115, h: 110, type: "chequer", bg: PALETTE.secIvory },
    { x: 835, y: 845, w: 140, h: 120, type: "gold_squares", bg: PALETTE.goldLight },
    { x: 205, y: 845, w: 110, h: 120, type: "chequer", bg: PALETTE.secIvory }
  ];

  // Base flat wash for each panel
  for (let p of panels) {
    brush.noStroke();
    brush.wash(p.bg, 220);
    brush.rect(p.x, p.y, p.w, p.h, "corner");
    brush.noWash();
  }

  // Populate each panel with flat graphic motifs
  for (let p of panels) {
    if (p.type === "gold_squares") {
      drawGoldSquareMosaic(p.x, p.y, p.w, p.h);
    } else if (p.type === "spiral_eyes") {
      drawSpiralEyeMosaic(p.x, p.y, p.w, p.h);
    } else if (p.type === "chequer") {
      drawChequerBand(p.x, p.y, p.w, p.h, 18);
    }
  }

  // Long Klimt-style black-and-white chequerboard ribbons bridging the panels
  drawChequerBand(40, 163, 840, 24, 12);
  drawChequerBand(40, 503, 165, 24, 12);
  drawChequerBand(975, 258, 185, 24, 12);
  drawChequerBand(975, 648, 185, 24, 12);
  drawChequerBand(290, 965, 685, 26, 13);
  drawChequerBand(628, 991, 24, 169, 12);
  drawChequerBand(508, 40, 24, 123, 12);

  // Outer architectural Secessionist border around the whole 1200x1200 canvas
  brush.set("rotring", PALETTE.secBlack, 1.4);
  brush.noFill();
  brush.rect(40, 40, 1120, 1120, "corner");
  brush.set("marker", PALETTE.goldRich, 1.6);
  brush.rect(46, 46, 1108, 1108, "corner");
}

function drawGoldSquareMosaic(rx, ry, rw, rh) {
  const step = 36;
  const cols = floor(rw / step);
  const rows = floor(rh / step);
  const padX = (rw - cols * step) * 0.5;
  const padY = (rh - rows * step) * 0.5;

  const goldTones = [
    PALETTE.goldLight,
    PALETTE.goldMid,
    PALETTE.goldRich,
    PALETTE.pastelPeach,
    PALETTE.pastelRose
  ];
  const innerTones = [
    PALETTE.goldDeep,
    PALETTE.pastelSageDeep,
    PALETTE.pastelRoseDeep,
    PALETTE.pastelLilac,
    PALETTE.secIvory
  ];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let tx = rx + padX + c * step;
      let ty = ry + padY + r * step;

      // Outer gold marker square
      let gCol = random(goldTones);
      brush.noStroke();
      brush.wash(gCol, 235);
      brush.rect(tx + 2, ty + 2, step - 4, step - 4, "corner");
      brush.noWash();

      // Marker hatch texture for metallic leaf sheen
      brush.set("gold_leaf", PALETTE.goldMid, 0.9);
      brush.line(tx + 5, ty + step * 0.35, tx + step - 5, ty + step * 0.35);
      brush.line(tx + 5, ty + step * 0.68, tx + step - 5, ty + step * 0.68);

      // Crisp square outline
      brush.set("rotring", PALETTE.goldBronze, 0.65);
      brush.noFill();
      brush.rect(tx + 2, ty + 2, step - 4, step - 4, "corner");

      // Concentric inner gem square or ring
      let mode = (r + c) % 3;
      if (mode === 0) {
        brush.noStroke();
        brush.wash(random(innerTones), 240);
        brush.rect(tx + 10, ty + 10, step - 20, step - 20, "corner");
        brush.noWash();
        brush.set("rotring", PALETTE.secBlack, 0.55);
        brush.rect(tx + 10, ty + 10, step - 20, step - 20, "corner");
      } else if (mode === 1) {
        // Four tiny corner squares
        brush.noStroke();
        brush.wash(PALETTE.secIvory, 235);
        brush.rect(tx + 7, ty + 7, 8, 8, "corner");
        brush.rect(tx + step - 15, ty + 7, 8, 8, "corner");
        brush.rect(tx + 7, ty + step - 15, 8, 8, "corner");
        brush.rect(tx + step - 15, ty + step - 15, 8, 8, "corner");
        brush.noWash();
      } else {
        // Small golden spiral inside the square
        drawTinySpiral(tx + step * 0.5, ty + step * 0.5, step * 0.34, PALETTE.secCharcoal, 0.65);
      }
    }
  }
}

function drawSpiralEyeMosaic(rx, ry, rw, rh) {
  const stepX = 56;
  const stepY = 46;
  const cols = floor(rw / stepX);
  const rows = floor(rh / stepY);
  const padX = (rw - cols * stepX) * 0.5;
  const padY = (rh - rows * stepY) * 0.5;

  const pastelBgs = [
    PALETTE.pastelRose,
    PALETTE.pastelSage,
    PALETTE.pastelLilac,
    PALETTE.pastelCream,
    PALETTE.goldLight
  ];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let cx = rx + padX + (c + 0.5) * stepX;
      let cy = ry + padY + (r + 0.5) * stepY;

      // Tile frame
      brush.noStroke();
      brush.wash( pastelBgs[(r + c) % pastelBgs.length], 210);
      brush.rect(cx - stepX * 0.46, cy - stepY * 0.45, stepX * 0.92, stepY * 0.9, "corner");
      brush.noWash();

      brush.set("rotring", PALETTE.goldRich, 0.7);
      brush.noFill();
      brush.rect(cx - stepX * 0.46, cy - stepY * 0.45, stepX * 0.92, stepY * 0.9, "corner");

      // Draw Secessionist almond eye + spiral pupil
      drawSecessionEye(cx, cy, stepX * 0.38, stepY * 0.28);
    }
  }
}

function drawSecessionEye(cx, cy, rx, ry) {
  // White/ivory sclera almond
  let pts = [];
  const steps = 14;
  for (let i = 0; i < steps; i++) {
    let a = map(i, 0, steps, 0, 360);
    let px = cx + cos(a) * rx;
    let py = cy + sin(a) * ry * (1 - 0.25 * pow(cos(a), 2));
    pts.push([px, py]);
  }
  brush.noStroke();
  brush.wash(PALETTE.secIvory, 240);
  drawBrushPoly(pts, 0.3);
  brush.noWash();

  // Golden iris disk
  brush.wash(PALETTE.goldMid, 240);
  brush.circle(cx, cy, ry * 0.72, 0.05);
  brush.noWash();

  // Crisp almond contour
  brush.set("rotring", PALETTE.secBlack, 0.85);
  brush.noFill();
  drawBrushPoly(pts, 0.3);

  // Spiralling pupil inside the eye
  drawTinySpiral(cx, cy, ry * 0.75, PALETTE.secBlack, 0.75);

  // Brow curl above the eye
  brush.set("pen", PALETTE.goldDeep, 0.8);
  brush.arc(cx, cy - ry * 0.15, rx * 0.95, 205, 335);
}

function drawTinySpiral(cx, cy, maxR, col, w) {
  let pts = [];
  let turns = 2.25;
  let totalSteps = 22;
  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    let ang = t * turns * 360;
    let r = t * maxR;
    pts.push([cx + cos(ang) * r, cy + sin(ang) * r]);
  }
  brush.set("rotring", col, w);
  brush.spline(pts, 0.4);
}

function drawChequerBand(rx, ry, rw, rh, tileSize) {
  const cols = max(1, floor(rw / tileSize));
  const rows = max(1, floor(rh / tileSize));
  const cw = rw / cols;
  const ch = rh / rows;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let isBlack = (r + c) % 2 === 0;
      brush.noStroke();
      brush.wash(isBlack ? PALETTE.secBlack : PALETTE.secIvory, 245);
      brush.rect(rx + c * cw, ry + r * ch, cw + 0.4, ch + 0.4, "corner");
      brush.noWash();
    }
  }
  brush.set("rotring", PALETTE.goldRich, 0.85);
  brush.noFill();
