// ============================================================================
// 5. 3D BROKEN SLAB OF COMB HONEY
// ============================================================================

function drawHoneycombSlab() {
  // Main slab boundary & a smaller broken chunk down-left
  const mainSlabPoly = [
    [355, 415],
    [475, 325],
    [655, 315],
    [795, 395],
    [825, 535],
    [775, 695],
    [645, 765],
    [485, 745],
    [375, 645],
    [335, 520]
  ];

  const chunkPoly = [
    [335, 725],
    [435, 705],
    [485, 775],
    [445, 855],
    [355, 845],
    [315, 785]
  ];

  const hexR = 23; // Radius of each hexagonal wax cell
  const dx = hexR * 1.732; // sqrt(3) * R
  const dy = hexR * 1.5;

  let cells = [];
  for (let row = 10; row <= 39; row++) {
    for (let col = 10; col <= 30; col++) {
      let cx = col * dx + (row % 2 === 1 ? dx * 0.5 : 0);
      let cy = row * dy;

      let inMain = pointInPoly(cx, cy, mainSlabPoly);
      let inChunk = pointInPoly(cx, cy, chunkPoly);

      if (inMain || inChunk) {
        // Determine if this cell is on the broken perimeter
        let nCount = 0;
        const dirs = [
          [dx, 0], [-dx, 0],
          [dx * 0.5, dy], [-dx * 0.5, dy],
          [dx * 0.5, -dy], [-dx * 0.5, -dy]
        ];
        for (let d of dirs) {
          if (
            pointInPoly(cx + d[0], cy + d[1], mainSlabPoly) ||
            pointInPoly(cx + d[0], cy + d[1], chunkPoly)
          ) {
            nCount++;
          }
        }
        let isEdge = nCount < 6;
        let isFrontWall =
          !pointInPoly(cx, cy + dy, mainSlabPoly) &&
          !pointInPoly(cx, cy + dy, chunkPoly);

        // Assign cell state: capped wax, amber pool, sienna pool, or deep burnt honey
        let nVal = noise(col * 0.28, row * 0.28);
        let state = "amber";
        if (isEdge) {
          state = random() < 0.6 ? "burnt" : "sienna";
        } else if (nVal < 0.34) {
          state = "capped";
        } else if (nVal < 0.56) {
          state = "amber";
        } else if (nVal < 0.78) {
          state = "sienna";
        } else {
          state = "burnt";
        }

        cells.push({
          cx,
          cy,
          r: hexR,
          isEdge,
          isFrontWall,
          state,
          chunk: inChunk
        });
      }
    }
  }

  // Sort cells top-to-bottom for authentic 3D overlapping extrusion
  cells.sort((a, b) => a.cy - b.cy);

  // 5A. Draw the thick 3D vertical extruded wax side-walls along front/bottom edges
  const wallDepth = 46;
  for (let c of cells) {
    if (c.isFrontWall || c.isEdge) {
      drawCellExtrusion(c.cx, c.cy, c.r, wallDepth);
    }
  }

  // 5B. Warm watercolor under-glaze across the slab interior
  brush.noStroke();
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.4, 0.3);
  brush.fill(PALETTE.honeyAmber, 130);
  drawBrushPoly(mainSlabPoly, 0.15);
  brush.fill(PALETTE.honeySienna, 135);
  drawBrushPoly(chunkPoly, 0.15);
  brush.noFill();

  // 5C. Render each hexagonal cell's 3D interior, pooled honey or wax cap, and wet gloss
  for (let c of cells) {
    drawHexCell(c);
  }

  // 5D. Draw viscous golden honey bridges stretching between the main slab and broken chunk
  drawHoneyBridges();
}

function getHexPts(cx, cy, r, jitter = 0) {
  let pts = [];
  for (let i = 0; i < 6; i++) {
    let ang = 30 + i * 60;
    let jr = r + (jitter ? random(-jitter, jitter) : 0);
    pts.push([cx + cos(ang) * jr, cy + sin(ang) * jr]);
  }
  return pts;
}

function drawCellExtrusion(cx, cy, r, depth) {
  let topPts = getHexPts(cx, cy, r);
  // Visible lower faces of the hexagonal prism (vertices 0 -> 1 -> 2 -> 3)
  for (let i = 0; i < 3; i++) {
    let p1 = topPts[i];
    let p2 = topPts[i + 1];
    let quadPts = [
      [p1[0], p1[1]],
      [p2[0], p2[1]],
      [p2[0] + 4, p2[1] + depth],
      [p1[0] + 4, p1[1] + depth]
    ];

    let faceCols = [PALETTE.honeySienna, PALETTE.honeyBurnt, PALETTE.honeyDark];
    brush.noStroke();
    brush.wash(faceCols[i], 235);
    drawBrushPoly(quadPts, 0);
    brush.noWash();

    // Vertical wet honey streak down the prism wall
    brush.set("glaze_soft", PALETTE.honeyAmber, 0.65);
    brush.line(
      (p1[0] + p2[0]) * 0.5,
      (p1[1] + p2[1]) * 0.5,
      (p1[0] + p2[0]) * 0.5 + 3,
      (p1[1] + p2[1]) * 0.5 + depth
    );

    if (i === 1 && random() < 0.75) {
      // Specular vertical drip highlight on the front cell wall
      brush.set("wet_gloss", PALETTE.highlight, 0.55);
      brush.line(
        p1[0] * 0.6 + p2[0] * 0.4,
        p1[1] + 6,
        p1[0] * 0.6 + p2[0] * 0.4 + 2,
        p1[1] + depth - 6
      );
    }
  }
}

function drawHexCell(c) {
  const { cx, cy, r, state, isEdge } = c;
  const outerPts = getHexPts(cx, cy, r, 0.6);
  const innerPts = getHexPts(cx, cy, r * 0.82, 0.4);

  if (state === "capped") {
    // Creamy pastel beeswax cap over the cell
    brush.noStroke();
    brush.wash(PALETTE.waxCream, 240);
    drawBrushPoly(outerPts, 0.05);
    brush.noWash();

    // Soft warm sunken center of the wax cap
    brush.wash( random() < 0.5 ? PALETTE.waxWarm : PALETTE.pastelPeach, 190);
    drawBrushPoly(innerPts, 0.15);
    brush.noWash();

    // Delicate dry-brush wax texture
    brush.set("cpencil", PALETTE.waxShadow, 0.65);
    brush.circle(cx, cy, r * 0.48, 0.25);

    // Bright wax ridge rim
    brush.set("pen", PALETTE.highlight, 0.8);
    brush.noFill();
    drawBrushPoly(outerPts, 0.08);
  } else {
    // Open cell brimming with 3D pooled honey
    let baseCol = PALETTE.honeyAmber;
    let deepCol = PALETTE.honeySienna;
    let coreCol = PALETTE.honeyBurnt;

    if (state === "sienna") {
      baseCol = PALETTE.honeySienna;
      deepCol = PALETTE.honeyBurnt;
      coreCol = PALETTE.honeyDark;
    } else if (state === "burnt") {
      baseCol = PALETTE.honeyBurnt;
      deepCol = PALETTE.honeyDark;
      coreCol = "#260900";
    }

    // 1. Cell wax wall base
    brush.noStroke();
    brush.wash(PALETTE.waxGold, 235);
    drawBrushPoly(outerPts, 0.05);
    brush.noWash();

    // 2. Deep shadow inside upper-left of hexagonal cavity (3D depth)
    let shadowPts = getHexPts(cx - 2.2, cy - 2.5, r * 0.78);
    brush.wash(coreCol, 240);
    drawBrushPoly(shadowPts, 0.1);
    brush.noWash();

    // 3. Translucent glowing honey pool shifted slightly lower-right (refraction)
    let poolPts = getHexPts(cx + 1.5, cy + 1.8, r * 0.72);
    brush.wash(baseCol, 225);
    drawBrushPoly(poolPts, 0.2);
    brush.noWash();

    // 4. Rich mid-pool glaze drop
    brush.wash(deepCol, 190);
    brush.circle(cx - 1, cy - 1, r * 0.46, 0.12);
    brush.noWash();

    // 5. Internal golden caustic glow at bottom-right of cell
    brush.set("glaze_soft", PALETTE.honeyPale, 0.75);
    brush.arc(cx + 1, cy + 1, r * 0.52, 15, 135);

    // 6. Top hexagonal beeswax walls between cells
    brush.set("cpencil", isEdge ? PALETTE.waxGold : PALETTE.waxWarm, 1.35);
    brush.noFill();
    drawBrushPoly(outerPts, 0.08);

    // 7. Crisp wet meniscus crescent highlight inside the honey pool
    brush.set("wet_gloss", PALETTE.highlight, 0.7);
    brush.arc(cx - 1, cy - 1, r * 0.54, 200, 315);

    // Secondary tiny pin-prick specular glint
    if (random() < 0.65) {
      brush.set("wet_gloss", PALETTE.highlight, 0.9);
      brush.line(cx + r * 0.25, cy - r * 0.22, cx + r * 0.31, cy - r * 0.18);
    }
  }
}

