function drawSingleGlossyDrip(x, y1, y2, stemW, bulbR) {
  // Build organic teardrop contour
  let midY = lerp(y1, y2, 0.62);
  let neckY = y2 - bulbR * 1.35;

  let dripPts = [
    [x - stemW * 0.9, y1],
    [x - stemW * 0.55, midY],
    [x - stemW * 0.38, neckY],
    [x - bulbR * 0.68, y2 - bulbR * 0.45],
    [x, y2 + bulbR * 0.25],
    [x + bulbR * 0.68, y2 - bulbR * 0.45],
    [x + stemW * 0.38, neckY],
    [x + stemW * 0.55, midY],
    [x + stemW * 0.9, y1]
  ];

  // Shadow cast onto the slate ledge & flat mosaic behind the drip
  let shadowPts = dripPts.map((p) => [p[0] + 6, p[1] + 7]);
  brush.noStroke();
  brush.wash("#1f0c02", 145);
  drawBrushPoly(shadowPts, 0.35);
  brush.noWash();

  // Translucent amber-sienna watercolor body of the drip
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.25, 0.35);
  brush.fill(PALETTE.honeyAmber, 195);
  drawBrushPoly(dripPts, 0.35);
  brush.noFill();

  // Deeper burnt-honey core inside the drip stem and upper bulb
  let corePts = [
    [x - stemW * 0.45, y1 + 10],
    [x - stemW * 0.22, neckY],
    [x - bulbR * 0.42, y2 - bulbR * 0.5],
    [x, y2 - bulbR * 0.05],
    [x + bulbR * 0.42, y2 - bulbR * 0.5],
    [x + stemW * 0.22, neckY],
    [x + stemW * 0.45, y1 + 10]
  ];
  brush.noStroke();
  brush.wash(PALETTE.honeySienna, 210);
  drawBrushPoly(corePts, 0.35);
  brush.noWash();

  // Dark burnt honey refraction ring near top of bulb
  brush.wash(PALETTE.honeyBurnt, 215);
  brush.circle(x + 1, y2 - bulbR * 0.52, bulbR * 0.42, 0.1);
  brush.noWash();

  // Bright golden caustic glow at the bottom tip of the hanging bulb
  brush.wash(PALETTE.honeyPale, 225);
  brush.circle(x - 1, y2 - bulbR * 0.18, bulbR * 0.34, 0.08);
  brush.noWash();

  // Long continuous white specular highlight down the left curve of the drip
  let glossSpline = [
    [x - stemW * 0.45, y1 + 14],
    [x - stemW * 0.28, midY],
    [x - stemW * 0.22, neckY],
    [x - bulbR * 0.42, y2 - bulbR * 0.42],
    [x - bulbR * 0.15, y2 - bulbR * 0.05]
  ];
  brush.set("wet_gloss", PALETTE.highlight, 0.85);
  brush.spline(glossSpline, 0.45);

  // Secondary crisp glint on right shoulder of bulb
  brush.set("wet_gloss", PALETTE.highlight, 0.6);
  brush.arc(x, y2 - bulbR * 0.4, bulbR * 0.48, 310, 30);
}

