function drawStuckBeeWing(wx, wy, angleDeg) {
  push();
  translate(wx, wy);
  rotate(angleDeg);

  const L = 128; // Forewing length
  const W = 46;  // Forewing width

  // Forewing contour (anatomical Apis mellifera silhouette)
  const wingContour = [
    [0, 0],
    [L * 0.25, -W * 0.32],
    [L * 0.62, -W * 0.48],
    [L * 0.92, -W * 0.36],
    [L * 1.0, -W * 0.12],
    [L * 0.94, W * 0.18],
    [L * 0.72, W * 0.42],
    [L * 0.42, W * 0.46],
    [L * 0.16, W * 0.26]
  ];

  // Subtle amber shadow under the un-submerged portion of the wing
  let wingShadow = wingContour.map((p) => [p[0] + 3, p[1] + 5]);
  brush.noStroke();
  brush.wash(PALETTE.honeyBurnt, 140);
  drawBrushPoly(wingShadow, 0.3);
  brush.noWash();

  // Translucent iridescent pastel membrane (ice-lilac, rose, & champagne)
  brush.wash(PALETTE.pastelLilac, 155);
  drawBrushPoly(wingContour, 0.3);

  let innerIridescence = [
    [L * 0.28, -W * 0.22],
    [L * 0.78, -W * 0.32],
    [L * 0.88, W * 0.05],
    [L * 0.52, W * 0.32],
    [L * 0.22, W * 0.14]
  ];
  brush.wash(PALETTE.secIvory, 175);
  drawBrushPoly(innerIridescence, 0.3);
  brush.noWash();

  // Delicate pastel rose/cyan interference sheen lines
  brush.set("cpencil", PALETTE.pastelRose, 0.65);
  brush.line(L * 0.35, -W * 0.12, L * 0.78, -W * 0.18);
  brush.set("cpencil", PALETTE.pastelSage, 0.65);
  brush.line(L * 0.32, W * 0.06, L * 0.74, W * 0.12);

  // Leading edge thickened costal & subcostal veins + pterostigma
  brush.set("rotring", PALETTE.honeyDark, 1.35);
  brush.spline([
    [0, 0],
    [L * 0.35, -W * 0.35],
    [L * 0.68, -W * 0.46],
    [L * 0.95, -W * 0.28]
  ], 0.3);

  // Pterostigma (dark amber stigma spot on leading edge)
  brush.noStroke();
  brush.wash(PALETTE.honeyBurnt, 235);
  drawBrushPoly([
    [L * 0.56, -W * 0.42],
    [L * 0.70, -W * 0.46],
    [L * 0.68, -W * 0.36],
    [L * 0.55, -W * 0.34]
  ], 0.1);
  brush.noWash();

  // Trailing margin delicate membrane edge
  brush.set("rotring", PALETTE.honeySienna, 0.65);
  brush.noFill();
  drawBrushPoly(wingContour, 0.3);

  // Internal anatomical wing venation (radial, cubital, submarginal & discoidal cells)
  const veins = [
    // Radial / marginal cell
    [[L * 0.64, -W * 0.38], [L * 0.78, -W * 0.16], [L * 0.94, -W * 0.18]],
    // Media-cubital basal stem
    [[0, 0], [L * 0.32, -W * 0.06], [L * 0.54, -W * 0.12], [L * 0.82, -W * 0.02]],
    // Submarginal cross-veins
    [[L * 0.44, -W * 0.34], [L * 0.42, -W * 0.09]],
    [[L * 0.56, -W * 0.35], [L * 0.54, -W * 0.12]],
    [[L * 0.70, -W * 0.24], [L * 0.68, -W * 0.06]],
    // Discoidal cells (lower wing)
    [[L * 0.18, W * 0.08], [L * 0.42, W * 0.18], [L * 0.68, W * 0.22]],
    [[L * 0.32, -W * 0.06], [L * 0.38, W * 0.16]],
    [[L * 0.54, -W * 0.12], [L * 0.52, W * 0.20]],
    [[L * 0.68, -W * 0.06], [L * 0.66, W * 0.22]],
    // Anal vein
    [[L * 0.08, W * 0.06], [L * 0.28, W * 0.26], [L * 0.46, W * 0.38]]
  ];

  brush.set("rotring", PALETTE.honeyBurnt, 0.7);
  for (let v of veins) {
    brush.spline(v, 0.25);
  }

  // Sticky amber honey meniscus overlapping the trapped base & lower edge of the wing
  const stickyOverlap = [
    [-12, -14],
    [L * 0.28, -W * 0.25],
    [L * 0.36, -W * 0.02],
    [L * 0.48, W * 0.28],
    [L * 0.25, W * 0.48],
    [-10, W * 0.25]
  ];
  brush.noStroke();
  brush.wash(PALETTE.honeyAmber, 210);
  drawBrushPoly(stickyOverlap, 0.35);
  brush.wash(PALETTE.honeySienna, 165);
  brush.circle(L * 0.12, W * 0.08, 22, 0.15);
  brush.noWash();

  // Wet specular highlight where the honey crawls onto the wing membrane
  brush.set("wet_gloss", PALETTE.highlight, 0.75);
  brush.spline([
    [L * 0.18, -W * 0.16],
    [L * 0.31, -W * 0.02],
    [L * 0.39, W * 0.20]
  ], 0.45);

  // Specular glint along the dry arched upper tip of the wing
  brush.set("wet_gloss", PALETTE.highlight, 0.65);
  brush.spline([
    [L * 0.58, -W * 0.28],
    [L * 0.76, -W * 0.26],
    [L * 0.90, -W * 0.14]
  ], 0.4);

  pop();
}

// Hyperrealist study: Lost suede work glove on a raw board-marked concrete stair
// Compressed charcoal mass, dragged timber-grain relief, graphite pinholes & cracks, burnt umber wash

const LIP_Y0 = 830;
const LIP_Y1 = 350;
const LIP_DX = 1200;
const LIP_DY = LIP_Y1 - LIP_Y0; // -480
const LIP_LEN = Math.hypot(LIP_DX, LIP_DY); // 1292.44
const UX = LIP_DX / LIP_LEN; // 0.92847669
const UY = LIP_DY / LIP_LEN; // -0.37139068
// Normal pointing up-left (into upper tread)
const NX = -UY; // 0.37139068
const NY = UX;  // 0.92847669
const STAIR_ANGLE = -21.8014;

// Map plank coordinates (s along stair lip, d perpendicular into upper tread) to canvas (x, y)
function toCanvas(s, d) {
  return [
    s * UX - d * NX,
    LIP_Y0 + s * UY - d * NY
  ];
}

// Inverse mapping from canvas (x, y) to (s, d)
function toPlank(x, y) {
  let dy = y - LIP_Y0;
  let s = x * UX + dy * UY;
  let d = -(x * NX + dy * NY);
  return [s, d];
}

function inBounds(x, y, pad = 60) {
  return x >= -pad && x <= 1200 + pad && y >= -pad && y <= 1200 + pad;
}

// Helper to draw a closed or open shape with p5.brush vertices
function drawPoly(pts, curvature = 0.12, closed = true) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Resample polygon/polyline for organic hand-drawn edge variation
function subdividePoly(pts, stepsPerSeg = 3, jitter = 1.5, closed = true) {
  let out = [];
  let count = closed ? pts.length : pts.length - 1;
  for (let i = 0; i < count; i++) {
    let p0 = pts[i];
    let p1 = pts[(i + 1) % pts.length];
    for (let s = 0; s < stepsPerSeg; s++) {
      let t = s / stepsPerSeg;
      let x = lerp(p0[0], p1[0], t);
      let y = lerp(p0[1], p1[1], t);
      let n = (noise(x * 0.015, y * 0.015, i * 0.3) - 0.5) * 2 * jitter;
      out.push([x + n, y - n * 0.8]);
    }
  }
  if (!closed) out.push(pts[pts.length - 1]);
  return out;
}

// Approximate glove bounding check to keep heavy concrete cracks from muddying the burnt umber wash
function insideGloveCore(x, y) {
  // Transformed ellipse test around the main glove body
  let dx = x - 585;
  let dy = y - 535;
  let ca = Math.cos(0.35), sa = Math.sin(0.35);
  let rx = dx * ca + dy * sa;
  let ry = -dx * sa + dy * ca;
  if ((rx * rx) / (245 * 245) + (ry * ry) / (135 * 135) < 0.88) return true;
  // Cuff extension
  let dx2 = x - 410;
  let dy2 = y - 615;
  if ((dx2 * dx2) / (105 * 105) + (dy2 * dy2) / (95 * 95) < 0.85) return true;
  return false;
}

