function draw() {
  translate(-width / 2, -height / 2);

  // Ensure a brush is always set before any operations
  brush.set("HB", "#2b2d2b", 1);

  // 1. PAPER GROUND & ARCHITECTURAL CONCRETE PLANES
  background("#dadcd6");
  renderConcretePlanes();

  // 2. BOARD-MARKED CONCRETE: DRAGGED CHARCOAL MASS & CATHEDRAL TIMBER GRAIN
  renderBoardMarkedGrain();

  // 3. FORMWORK BOARD SEAMS & THE DIAGONAL STAIR LIP (NOSING)
  renderBoardSeamsAndLip();

  // 4. GRAPHITE PENCIL MICRO-DETAIL: PINHOLES, AGGREGATE PEBBLES, HAIRLINE CRACKS
  renderGraphiteConcreteDetails();

  // 5. AMBIENT OCCLUSION IN THE RISER & AROUND THE GLOVE
  renderAmbientOcclusion();

  // 6. THE LOST SUEDE WORK GLOVE (BURNT UMBER WASH, SUEDE NAP, CREASES & STITCHING)
  renderSuedeWorkGlove();

  // 7. FINAL HIGH-CONTRAST GRAPHITE & CHARCOAL ACCENTS
  renderFinalAccents();

  noLoop();
}

// ============================================================================
// 1. ARCHITECTURAL CONCRETE PLANES (UPPER TREAD, RISER, LOWER TREAD)
// ============================================================================
function renderConcretePlanes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Upper Tread polygon: d from 0 to 1250
  let upperTread = [
    [0, 0],
    [1200, 0],
    [1200, LIP_Y1],
    [0, LIP_Y0]
  ];

  // Riser polygon: between lip (d = 0) and riser base (d = -440)
  // At d = -440: (0, 830 + 474) = (0, 1304), (1200, 350 + 474) = (1200, 824)
  let riserPoly = [
    [0, LIP_Y0],
    [1200, LIP_Y1],
    [1200, 824],
    [260, 1200],
    [0, 1200]
  ];

  // Lower Tread polygon: below riser base
  let lowerTread = [
    [260, 1200],
    [1200, 824],
    [1200, 1200]
  ];

  // Base washes for Upper Tread (cool overcast ash and pale slate)
  brush.wash("#c8cbc4", 150);
  drawPoly(upperTread, 0.02, true);
  brush.noWash();

  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.65, 0.35);
  brush.fill("#a5a9a2", 95);
  drawPoly(upperTread, 0.02, true);

  // Darker slate patches toward top-left and right corners for heavy cropped feel
  brush.fill("#7f837c", 85);
  drawPoly([[0, 0], [820, 0], [520, 380], [0, 590]], 0.1, true);
  drawPoly([[750, 0], [1200, 0], [1200, 350], [920, 260]], 0.1, true);
  brush.noFill();

  // Compressed charcoal mass passes across Upper Tread planks
  let plankBoundsUpper = [0, 215, 445, 680, 920, 1260];
  let plankColorsUpper = ["#949891", "#858982", "#9ea29b", "#7c8079", "#8c9089"];
  for (let p = 0; p < plankBoundsUpper.length - 1; p++) {
    let d0 = plankBoundsUpper[p];
    let d1 = plankBoundsUpper[p + 1];
    let poly = [
      toCanvas(-200, d0),
      toCanvas(1500, d0),
      toCanvas(1500, d1),
      toCanvas(-200, d1)
    ];
    brush.mass("charcoal", plankColorsUpper[p], {
      precision: 0.35,
      strength: 0.45,
      gradient: 0.25,
      outline: false
    });
    drawPoly(poly, 0.02, true);
    brush.noMass();
  }

  // Base washes for Riser (deep high-contrast compressed charcoal & dark slate)
  brush.wash("#212422", 225);
  drawPoly(riserPoly, 0.02, true);
  brush.noWash();

  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.75, 0.5);
  brush.fill("#141615", 170);
  drawPoly(riserPoly, 0.02, true);
  brush.noFill();

  // Dense compressed charcoal mass on the Riser
  brush.mass("charcoal", "#121413", {
    precision: 0.25,
    strength: 0.85,
    gradient: 0.35,
    outline: false
  });
  drawPoly(riserPoly, 0.02, true);
  brush.noMass();

  // Upper half of Riser: extra deep ambient occlusion band directly beneath the stair lip
  let riserAO = [
    toCanvas(-100, -14),
    toCanvas(1450, -14),
    toCanvas(1450, -175),
    toCanvas(-100, -175)
  ];
  brush.fillBleed(0.28, "out");
  brush.fill("#0b0c0c", 190);
  drawPoly(riserAO, 0.05, true);
  brush.noFill();

  // Lower Tread base washes & charcoal mass
  brush.wash("#585c56", 205);
  drawPoly(lowerTread, 0.02, true);
  brush.noWash();

  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.65, 0.4);
  brush.fill("#3c3f3b", 135);
  drawPoly(lowerTread, 0.02, true);
  brush.noFill();

  brush.mass("charcoal", "#484b47", {
    precision: 0.3,
    strength: 0.65,
    gradient: 0.3,
    outline: false
  });
  drawPoly(lowerTread, 0.02, true);
  brush.noMass();

  // Deep ambient occlusion crease where Riser meets Lower Tread (around d = -440)
  let creaseAO = [
    toCanvas(200, -405),
    toCanvas(1450, -405),
    toCanvas(1450, -510),
    toCanvas(200, -510)
  ];
  brush.fillBleed(0.25, "out");
  brush.fill("#0e100f", 200);
  drawPoly(creaseAO, 0.05, true);
  brush.noFill();
}

// ============================================================================
// 2. DRAGGED CHARCOAL MASS & CATHEDRAL TIMBER GRAIN
// ============================================================================
function renderBoardMarkedGrain() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // Define each formwork plank across Upper Tread, Riser, and Lower Tread
  const planks = [
    // Upper Tread planks
    { dMin: 12,   dMax: 215,  zone: "upper", knots: [{ s: 310, d: 95,  dir: 1 }, { s: 1020, d: 155, dir: -1 }] },
    { dMin: 215,  dMax: 445,  zone: "upper", knots: [{ s: 760, d: 310, dir: 1 }, { s: 120,  d: 370, dir: -1 }] },
    { dMin: 445,  dMax: 680,  zone: "upper", knots: [{ s: 440, d: 575, dir: -1 }, { s: 1120, d: 510, dir: 1 }] },
    { dMin: 680,  dMax: 920,  zone: "upper", knots: [{ s: 820, d: 790, dir: 1 }] },
    { dMin: 920,  dMax: 1220, zone: "upper", knots: [{ s: 520, d: 1040, dir: -1 }] },
    // Riser planks
    { dMin: -230, dMax: -18,  zone: "riser", knots: [{ s: 480, d: -115, dir: 1 }, { s: 1080, d: -140, dir: -1 }] },
    { dMin: -440, dMax: -230, zone: "riser", knots: [{ s: 860, d: -330, dir: 1 }, { s: 290,  d: -310, dir: -1 }] },
    // Lower Tread planks
    { dMin: -665, dMax: -440, zone: "lower", knots: [{ s: 920, d: -545, dir: 1 }] },
    { dMin: -920, dMax: -665, zone: "lower", knots: [{ s: 1050, d: -770, dir: -1 }] }
  ];

  // Pass 2A: Broad dragged charcoal streaks along the plank fibers
  for (let p of planks) {
    let numStreaks = p.zone === "upper" ? 28 : (p.zone === "riser" ? 24 : 18);
    for (let i = 0; i < numStreaks; i++) {
      let t = (i + 0.5) / numStreaks;
      let dBase = lerp(p.dMin + 6, p.dMax - 6, t);
      let pts = [];
      for (let s = -160; s <= 1480; s += 55) {
        let wobble = (noise(s * 0.004, dBase * 0.02, i * 0.1) - 0.5) * 14;
        let d = constrain(dBase + wobble, p.dMin + 3, p.dMax - 3);
        let pt = toCanvas(s, d);
        if (inBounds(pt[0], pt[1], 100)) {
          pts.push([pt[0], pt[1], random(0.5, 1.25)]);
        }
      }
      if (pts.length >= 3) {
        if (p.zone === "upper") {
          let col = i % 3 === 0 ? "#4a4e49" : (i % 3 === 1 ? "#6e726c" : "#dcded8");
          let br = i % 4 === 0 ? "charcoal_broad" : "charcoal_drag";
          brush.set(br, col, random(0.7, 1.35));
        } else if (p.zone === "riser") {
          let col = i % 3 === 0 ? "#0a0b0b" : (i % 3 === 1 ? "#1a1d1b" : "#343835");
          brush.set("charcoal_drag", col, random(0.8, 1.4));
        } else {
          let col = i % 3 === 0 ? "#242725" : (i % 3 === 1 ? "#383b38" : "#6c706a");
          brush.set("charcoal_drag", col, random(0.75, 1.3));
        }
        brush.spline(pts, 0.25);
      }
    }
  }

  // Pass 2B: Cathedral timber growth-ring contours cast into the concrete
  for (let p of planks) {
    let plankH = p.dMax - p.dMin;
    for (let knot of p.knots) {
      let numRings = p.zone === "upper" ? 26 : 18;
      for (let rIdx = 1; rIdx <= numRings; rIdx++) {
        let r0 = rIdx * 7.2 + random(-1.2, 1.2);
        // Trace both upper (+1) and lower (-1) arches of the cathedral ring
        for (let sign of [-1, 1]) {
          let segPts = [];
          let segLightPts = [];
          for (let s = -140; s <= 1460; s += 26) {
            let ds = (s - knot.s) * 0.135;
            let radSq = r0 * r0 - ds * ds;
            if (radSq >= 0) {
              let dOffset = Math.sqrt(radSq) * 0.85 * sign;
              // Add natural wood fiber undulation
              let fiberNoise = (noise(s * 0.006, (knot.d + dOffset) * 0.025, rIdx * 0.17) - 0.5) * 16;
              let d = knot.d + dOffset + fiberNoise;

              if (d >= p.dMin + 3 && d <= p.dMax - 3) {
                let pt = toCanvas(s, d);
                let ptLight = toCanvas(s, d + 2.2);
                if (inBounds(pt[0], pt[1], 45)) {
                  let press = map(Math.abs(s - knot.s), 0, 500, 1.15, 0.55, true);
                  segPts.push([pt[0], pt[1], press]);
                  segLightPts.push([ptLight[0], ptLight[1], press * 0.85]);
                } else {
                  flushGrainSegment(segPts, segLightPts, p.zone, rIdx);
                  segPts = [];
                  segLightPts = [];
                }
              } else {
                flushGrainSegment(segPts, segLightPts, p.zone, rIdx);
                segPts = [];
                segLightPts = [];
              }
            } else {
              flushGrainSegment(segPts, segLightPts, p.zone, rIdx);
              segPts = [];
              segLightPts = [];
            }
          }
          flushGrainSegment(segPts, segLightPts, p.zone, rIdx);
        }
      }

      // Draw dark compressed charcoal knot heart at (knot.s, knot.d) if in canvas and outside glove
      let kPt = toCanvas(knot.s, knot.d);
      if (inBounds(kPt[0], kPt[1], -20) && !insideGloveCore(kPt[0], kPt[1])) {
        let knotDark = p.zone === "upper" ? "#282b28" : "#080909";
        let knotMid = p.zone === "upper" ? "#4e524d" : "#1c1f1d";
        brush.set("charcoal", knotDark, 1.1);
        for (let a = 0; a < 5; a++) {
          let rx = 14 + a * 7;
          let ry = 4 + a * 2.2;
          let ringPts = [];
          for (let deg = 0; deg <= 360; deg += 30) {
            let ds = Math.cos(deg * Math.PI / 180) * rx;
            let dd = Math.sin(deg * Math.PI / 180) * ry;
            let pRing = toCanvas(knot.s + ds, constrain(knot.d + dd, p.dMin + 2, p.dMax - 2));
            ringPts.push([pRing[0], pRing[1], random(0.6, 1.2)]);
          }
          brush.set(a < 2 ? "2B" : "charcoal", a < 2 ? knotDark : knotMid, random(0.65, 1.15));
          brush.spline(ringPts, 0.35);
        }
      }
    }
  }
}

function flushGrainSegment(segPts, segLightPts, zone, rIdx) {
  if (segPts.length < 3) return;

  if (zone === "upper") {
    // Dark charcoal grain recess
    let darkCol = rIdx % 3 === 0 ? "#2c2f2c" : (rIdx % 2 === 0 ? "#434742" : "#5b5f59");
    let useDrag = rIdx % 2 === 0;
    brush.set(useDrag ? "charcoal_drag" : "charcoal", darkCol, useDrag ? random(0.55, 0.95) : random(0.65, 1.15));
    brush.spline(segPts, 0.28);

    // Fine 2B graphite definition along every second grain ridge
    if (rIdx % 2 === 0) {
      brush.set("2B", "#323532", random(0.6, 0.95));
      brush.spline(segPts, 0.28);
    }

    // Raised pale ash cement ridge catching flat overcast light
    if (segLightPts.length >= 3 && rIdx % 2 === 1) {
      brush.set("charcoal", "#e1e4dd", random(0.55, 0.9));
      brush.spline(segLightPts, 0.28);
    }
  } else if (zone === "riser") {
    let darkCol = rIdx % 2 === 0 ? "#090a0a" : "#141716";
    brush.set("charcoal", darkCol, random(0.7, 1.2));
    brush.spline(segPts, 0.28);

    if (segLightPts.length >= 3 && rIdx % 2 === 0) {
      brush.set("2B", "#3c403c", random(0.55, 0.85));
      brush.spline(segLightPts, 0.28);
    }
  } else {
    let darkCol = rIdx % 2 === 0 ? "#1f2220" : "#2f3330";
    brush.set("charcoal", darkCol, random(0.65, 1.1));
    brush.spline(segPts, 0.28);

    if (segLightPts.length >= 3 && rIdx % 2 === 1) {
      brush.set("charcoal", "#787c75", random(0.5, 0.85));
      brush.spline(segLightPts, 0.28);
    }
  }
}

// ============================================================================
// 3. FORMWORK BOARD SEAMS & THE DIAGONAL STAIR LIP (NOSING)
// ============================================================================
function renderBoardSeamsAndLip() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // 3A. Formwork Board Seams (where wet concrete squeezed between planks)
  const seamPositions = [
    { d: 215,  zone: "upper" },
    { d: 445,  zone: "upper" },
    { d: 680,  zone: "upper" },
    { d: 920,  zone: "upper" },
    { d: -230, zone: "riser" },
    { d: -665, zone: "lower" }
  ];

  for (let seam of seamPositions) {
    let darkPts = [];
    let finPts = [];
    let shadowPts = [];

    for (let s = -120; s <= 1450; s += 18) {
      let j = (noise(s * 0.018, seam.d * 0.1) - 0.5) * 3.8;
      let pDark = toCanvas(s, seam.d + j);
      let pFin = toCanvas(s, seam.d + j + 2.4);
      let pShad = toCanvas(s, seam.d + j - 2.6);

      if (inBounds(pDark[0], pDark[1], 30)) {
        darkPts.push([pDark[0], pDark[1], random(0.7, 1.35)]);
        finPts.push([pFin[0], pFin[1], random(0.6, 1.2)]);
        shadowPts.push([pShad[0], pShad[1], random(0.5, 1.1)]);
      }
    }

    if (seam.zone === "upper") {
      // Soft charcoal smudge along board joint
      brush.set("charcoal_drag", "#454944", 0.75);
      brush.spline(shadowPts, 0.2);

      // Raised pale cement fin squeezed between boards
      brush.set("charcoal", "#ebeee7", 0.85);
      brush.spline(finPts, 0.2);

      // Crisp dark graphite seam crevice
      brush.set("2B", "#1d201e", 1.1);
      brush.spline(darkPts, 0.18);
      brush.set("graphite_crisp", "#141615", 0.95);
      brush.spline(darkPts, 0.18);
    } else if (seam.zone === "riser") {
      brush.set("charcoal", "#070808", 1.15);
      brush.spline(darkPts, 0.2);
      brush.set("2B", "#464a46", 0.75);
      brush.spline(finPts, 0.2);
    } else {
      brush.set("charcoal", "#1a1d1b", 1.0);
      brush.spline(darkPts, 0.2);
      brush.set("2B", "#858982", 0.75);
      brush.spline(finPts, 0.2);
    }
  }

  // 3B. The Main Stair Lip / Chamfered Concrete Nosing (d = -20 to d = +12)
  // Upper chamfer highlight band (d = 0 to d = +10)
  let lipHighlightPoly = [];
  for (let s = -60; s <= 1360; s += 25) {
    let n = (noise(s * 0.015, 11.3) - 0.5) * 4.5;
    lipHighlightPoly.push(toCanvas(s, 9 + n));
  }
  for (let s = 1360; s >= -60; s -= 25) {
    let n = (noise(s * 0.018, 23.7) - 0.5) * 5.0;
    lipHighlightPoly.push(toCanvas(s, -3 + n));
  }
  brush.noStroke();
  brush.wash("#e6e9e2", 185);
  drawPoly(lipHighlightPoly, 0.08, true);
  brush.noWash();

  // Bevel face (d = -3 to d = -19): mid-tone weathered concrete facet
  let bevelPoly = [];
  for (let s = -60; s <= 1360; s += 25) {
    let n = (noise(s * 0.018, 23.7) - 0.5) * 5.0;
    bevelPoly.push(toCanvas(s, -3 + n));
  }
  for (let s = 1360; s >= -60; s -= 25) {
    let n = (noise(s * 0.022, 41.2) - 0.5) * 6.5;
    bevelPoly.push(toCanvas(s, -19 + n));
  }
  brush.wash("#8c9089", 175);
  drawPoly(bevelPoly, 0.08, true);
  brush.noWash();

  // Dragged chalk/ash highlight and chipped graphite edges along the stair lip
  for (let pass = 0; pass < 4; pass++) {
    let upperRidgePts = [];
    let lowerArrisPts = [];
    for (let s = -40; s <= 1340; s += 16) {
      let chip = (noise(s * 0.025, pass * 7.1) - 0.5) * 5.5;
      // Add extra concrete spall/chipping at a few spots along the stair lip
      if (Math.abs(s - 210) < 38 || Math.abs(s - 980) < 45 || Math.abs(s - 1140) < 30) {
        chip += (noise(s * 0.08, pass) - 0.3) * 9.0;
      }
      let pUp = toCanvas(s, 3 + chip * 0.6 + pass * 1.4);
      let pLo = toCanvas(s, -17 + chip - pass * 1.2);
      upperRidgePts.push([pUp[0], pUp[1], random(0.65, 1.35)]);
      lowerArrisPts.push([pLo[0], pLo[1], random(0.7, 1.4)]);
    }

    // Bright ash highlight along upper ridge of nosing
    brush.set("charcoal", pass % 2 === 0 ? "#eff2eb" : "#d8dcd4", random(0.8, 1.3));
    brush.spline(upperRidgePts, 0.2);

    // Sharp dark charcoal & 2B undercut along lower arris where lip meets riser
    brush.set(pass < 2 ? "charcoal" : "2B", pass === 0 ? "#070808" : "#181a19", random(0.9, 1.45));
    brush.spline(lowerArrisPts, 0.18);
  }

  // Chipped spall pockets along the concrete nosing
  const spallLocations = [145, 215, 330, 895, 985, 1135];
  for (let sLoc of spallLocations) {
    let spallPts = [];
    let w = random(18, 36);
    let h = random(8, 15);
    for (let a = 0; a < 10; a++) {
      let ang = (a / 10) * 360;
      let ds = Math.cos(ang * Math.PI / 180) * w * random(0.75, 1.25);
      let dd = Math.sin(ang * Math.PI / 180) * h * random(0.75, 1.25);
      spallPts.push(toCanvas(sLoc + ds, -7 + dd));
    }
    brush.noStroke();
    brush.wash("#5c605a", 190);
    drawPoly(spallPts, 0.15, true);
    brush.noWash();

    // Dark upper rim inside the chipped concrete pocket, pale lower edge
    brush.set("graphite_crisp", "#161817", 1.1);
    drawPoly(spallPts, 0.15, true);
    let pRim1 = toCanvas(sLoc - w * 0.7, -7 + h * 0.6);
    let pRim2 = toCanvas(sLoc + w * 0.7, -7 + h * 0.5);
    brush.set("HB", "#ebeee7", 0.9);
    brush.line(pRim1[0], pRim1[1], pRim2[0], pRim2[1]);
  }
}

// ============================================================================
// 4. GRAPHITE PENCIL MICRO-DETAIL: PINHOLES, AGGREGATE PEBBLES, HAIRLINE CRACKS
// ============================================================================
function renderGraphiteConcreteDetails() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // 4A. Pinholes / Bug-holes (cast air bubble voids in raw board-formed concrete)
  const numPinholes = 420;
  for (let i = 0; i < numPinholes; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    if (insideGloveCore(x, y)) continue;

    let [s, d] = toPlank(x, y);
    let isRiser = d < -18 && d > -440;
    let isLower = d <= -440;

    // Cluster some bug-holes near board seams and along the lip
    if (random() < 0.35) {
      let seamDs = [10, 215, 445, 680, 920, -40, -230, -455];
      let baseD = random(seamDs) + randomGaussian(0, 22);
      let pt = toCanvas(random(-20, 1280), baseD);
      x = pt[0];
      y = pt[1];
      if (!inBounds(x, y, -10) || insideGloveCore(x, y)) continue;
      d = baseD;
      isRiser = d < -18 && d > -440;
      isLower = d <= -440;
    }

    let r = random() < 0.78 ? random(1.2, 3.2) : random(3.4, 6.8);

    // Pinhole interior shadow
    let pitDark = isRiser ? "#050606" : (isLower ? "#141615" : "#1c1f1d");
    let rimLight = isRiser ? "#454945" : (isLower ? "#8a8e87" : "#ebeee7");

    brush.set("graphite_crisp", pitDark, map(r, 1.2, 6.8, 0.75, 1.35));
    brush.circle(x, y, r, 0.35);

    // Fill larger bug-holes with dark graphite hatching
    if (r > 2.4) {
      brush.set("2B", pitDark, 0.85);
      brush.line(x - r * 0.65, y - r * 0.25, x + r * 0.65, y - r * 0.15);
      brush.line(x - r * 0.45, y + r * 0.15, x + r * 0.45, y + r * 0.2);
      // Lower crescent highlight where overcast light catches the bottom edge of the void
      brush.set("HB", rimLight, 0.8);
      brush.arc(x, y + r * 0.15, r * 0.95, 25, 155);
    }
  }

  // 4B. Exposed Aggregate Pebbles (small stones breaking through the cement laitance)
  const numPebbles = 145;
  for (let i = 0; i < numPebbles; i++) {
    // Concentrate aggregate near the worn stair lip, seams, and weathered patches
    let s = random(-20, 1280);
    let d;
    let roll = random();
    if (roll < 0.48) {
      d = random(-24, 55); // Near the worn stair lip
    } else if (roll < 0.82) {
      d = random(55, 1150); // Upper tread
    } else {
      d = random(-850, -24); // Riser and lower tread
    }

    let [x, y] = toCanvas(s, d);
    if (!inBounds(x, y, -12) || insideGloveCore(x, y)) continue;

    let rx = random(2.8, 8.5);
    let ry = rx * random(0.55, 0.92);
    let rot = random(0, 180) * Math.PI / 180;
    let pts = [];
    let sides = int(random(5, 8));
    for (let k = 0; k < sides; k++) {
      let a = (k / sides) * Math.PI * 2;
      let lx = Math.cos(a) * rx * random(0.8, 1.18);
      let ly = Math.sin(a) * ry * random(0.8, 1.18);
      let px = x + lx * Math.cos(rot) - ly * Math.sin(rot);
      let py = y + lx * Math.sin(rot) + ly * Math.cos(rot);
      pts.push([px, py]);
    }

    // Pebble tone: quartz light, slate mid, or basalt dark
    let isDarkZone = d < -18;
    let pebbleTone;
    let tRoll = random();
    if (isDarkZone) {
      pebbleTone = tRoll < 0.4 ? "#4e524d" : (tRoll < 0.75 ? "#2e312e" : "#161817");
    } else {
      pebbleTone = tRoll < 0.35 ? "#e2e5de" : (tRoll < 0.7 ? "#767a73" : "#383b38");
    }

    brush.noStroke();
    brush.wash(pebbleTone, 185);
    drawPoly(pts, 0.12, true);
    brush.noWash();

    // Crisp graphite socket line around the pebble
    brush.set("graphite_crisp", isDarkZone ? "#080909" : "#222523", 0.85);
    drawPoly(pts, 0.12, true);

    // Top facet highlight on the pebble
    if (!isDarkZone && rx > 4.2) {
      brush.set("2H", "#f0f3ec", 0.75);
      brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    }
  }

  // 4C. Hairline Shrinkage Cracks in Sharp Graphite Pencil ("graphite_crisp", "2H", "HB")
  const cracks = [
    // Crack 1: Starts on upper tread left, fractures across the stair lip and down the riser
    { sStart: 185, dStart: 380, sEnd: 235, dEnd: -210, steps: 42, branchAt: 18 },
    // Crack 2: Upper tread center-left, wandering from top edge toward the glove cuff
    { sStart: 95,  dStart: 980, sEnd: 265, dEnd: 460,  steps: 38, branchAt: 22 },
    // Crack 3: Right of the glove, slicing across the lip at s = 920 and down into riser
    { sStart: 885, dStart: 310, sEnd: 945, dEnd: -290, steps: 46, branchAt: 15 },
    // Crack 4: Far right upper tread crazing near board seam
    { sStart: 1090, dStart: 520, sEnd: 1185, dEnd: 120, steps: 32, branchAt: 14 },
    // Crack 5: Upper-center hairline fracture above the glove fingers
    { sStart: 590, dStart: 860, sEnd: 675, dEnd: 455,  steps: 34, branchAt: 16 },
    // Crack 6: Lower tread shrinkage crack emerging from the riser corner
    { sStart: 780, dStart: -445, sEnd: 895, dEnd: -760, steps: 28, branchAt: 12 }
  ];

  for (let cIdx = 0; cIdx < cracks.length; cIdx++) {
    let c = cracks[cIdx];
    let mainPts = [];
    let highlightPts = [];
    let branchPts = [];

    let curS = c.sStart;
    let curD = c.dStart;
    let dsStep = (c.sEnd - c.sStart) / c.steps;
    let ddStep = (c.dEnd - c.dStart) / c.steps;

    for (let i = 0; i <= c.steps; i++) {
      let jitterS = (noise(i * 0.35, cIdx * 9.3) - 0.5) * 18;
      let jitterD = (noise(i * 0.35 + 40, cIdx * 9.3) - 0.5) * 10;
      let s = curS + jitterS;
      let d = curD + jitterD;
      let pt = toCanvas(s, d);
      let ptHi = toCanvas(s + 1.4, d + 1.2);

      if (inBounds(pt[0], pt[1], 10) && !insideGloveCore(pt[0], pt[1])) {
        let press = map(Math.sin((i / c.steps) * Math.PI), 0, 1, 0.45, 1.25);
        mainPts.push([pt[0], pt[1], press]);
        highlightPts.push([ptHi[0], ptHi[1], press * 0.7]);
      }

      // Secondary micro-branch fork
      if (i === c.branchAt) {
        let bS = s;
        let bD = d;
        for (let b = 0; b < 14; b++) {
          bS += dsStep * 0.8 + (noise(b * 0.5, cIdx * 3.1) - 0.35) * 14;
          bD += ddStep * 0.65 + (noise(b * 0.5 + 20, cIdx * 3.1) - 0.5) * 9;
          let bPt = toCanvas(bS, bD);
          if (inBounds(bPt[0], bPt[1], 10) && !insideGloveCore(bPt[0], bPt[1])) {
            branchPts.push([bPt[0], bPt[1], map(b, 0, 14, 0.9, 0.3)]);
          }
        }
      }

      curS += dsStep;
      curD += ddStep;
    }

    if (mainPts.length >= 3) {
      // Faint pale edge catch alongside the fracture
      brush.set("2H", "#e6e9e2", 0.75);
      brush.spline(highlightPts, 0.1);

      // Sharp dark graphite crack core
      brush.set("graphite_crisp", "#161817", 1.05);
      brush.spline(mainPts, 0.1);

      // Slightly wider 2B spalling at the middle of the crack
      if (mainPts.length > 10) {
        let midSlice = mainPts.slice(int(mainPts.length * 0.25), int(mainPts.length * 0.75));
        brush.set("2B", "#2b2e2c", 0.7);
        brush.spline(midSlice, 0.1);
      }
    }

    if (branchPts.length >= 3) {
      brush.set("graphite_crisp", "#282b29", 0.75);
      brush.spline(branchPts, 0.1);
    }
  }
}

// ============================================================================
// 5. AMBIENT OCCLUSION IN THE RISER & CONTACT OCCLUSION UNDER THE GLOVE
// ============================================================================
function renderAmbientOcclusion() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // 5A. Deep smudged charcoal ambient occlusion pooling directly under the stair lip in the riser
  for (let pass = 0; pass < 6; pass++) {
    let dDepth = -22 - pass * 18;
    let aoPts = [];
    for (let s = -60; s <= 1360; s += 40) {
      let wobble = (noise(s * 0.008, pass * 3.7) - 0.5) * 16;
      let pt = toCanvas(s, dDepth + wobble);
      aoPts.push([pt[0], pt[1], random(0.7, 1.3)]);
    }
    brush.set("charcoal_smudge", pass < 3 ? "#080909" : "#141716", map(pass, 0, 5, 1.45, 0.75));
    brush.spline(aoPts, 0.3);
  }

  // Vertical dampness / concrete tie-rod streaks down the riser face
  for (let i = 0; i < 34; i++) {
    let s = random(20, 1260);
    let dStart = random(-20, -60);
    let dEnd = dStart - random(90, 320);
    let p0 = toCanvas(s, dStart);
    let p1 = toCanvas(s + random(-12, 12), dEnd);
    if (inBounds(p0[0], p0[1], 20) && inBounds(p1[0], p1[1], 20)) {
      brush.set("charcoal_drag", i % 2 === 0 ? "#0c0e0d" : "#1c1f1e", random(0.6, 1.15));
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Deep ambient occlusion in the lower riser crease (d = -440)
  for (let pass = 0; pass < 4; pass++) {
    let dCrease = -435 + (pass - 1.5) * 14;
    let cPts = [];
    for (let s = 220; s <= 1360; s += 40) {
      let pt = toCanvas(s, dCrease + (noise(s * 0.01, pass) - 0.5) * 12);
      cPts.push([pt[0], pt[1], random(0.8, 1.3)]);
    }
    brush.set("charcoal_smudge", "#090a0a", 1.25 - pass * 0.18);
    brush.spline(cPts, 0.3);
  }

  // 5B. Contact Ambient Occlusion directly around and beneath the lost suede work glove
  // (No directional cast shadow — flat overcast light pools darkness only in tight contact crevices
  // and beneath the thumb and curled fingers overhanging the stair lip!)
  const aoZones = [
    // Deepest occlusion under the overhanging thumb and pinky on the riser face
    {
      pts: [[510, 650], [585, 635], [695, 610], [795, 565], [815, 600], [720, 685], [610, 720], [505, 695]],
      col: "#070808", alpha: 215, bleed: 0.32
    },
    // Tight contact crevice beneath the gauntlet cuff on the upper tread and lip
    {
      pts: [[305, 625], [345, 535], [470, 485], [525, 590], [455, 725], [345, 745]],
      col: "#161513", alpha: 185, bleed: 0.28
    },
    // Soft ambient halo around the upper curled fingers on the concrete tread
    {
      pts: [[560, 435], [665, 360], [785, 385], [848, 455], [842, 545], [775, 600], [615, 520]],
      col: "#24221f", alpha: 155, bleed: 0.3
    }
  ];

  brush.noStroke();
  for (let z of aoZones) {
    brush.fillBleed(z.bleed, "out");
    brush.fillTexture(0.7, 0.35);
    brush.fill(z.col, z.alpha);
    drawPoly(z.pts, 0.22, true);
  }
  brush.noFill();

  // Smudge charcoal tightly around the glove contact boundary
  const contactCurves = [
    // Under cuff bottom edge
    [[318, 665], [365, 728], [435, 718], [505, 662]],
    // Under thumb overhanging the stair lip
    [[510, 662], [585, 698], [668, 678], [712, 625]],
    // Under curled pinky and ring finger over the riser
    [[705, 622], [765, 610], [810, 578], [838, 520], [835, 445]],
    // Along top of index finger and back of wrist
    [[455, 500], [545, 442], [655, 372], [755, 388]]
  ];
  for (let crv of contactCurves) {
    let pts = crv.map(p => [p[0], p[1], 1.1]);
    brush.set("charcoal_smudge", "#0b0a09", 1.25);
    brush.spline(pts, 0.3);
    brush.set("charcoal", "#12100e", 1.1);
    brush.spline(pts, 0.3);
  }
}

