// Helper to draw directional cross-contour suede nap along a curved tube (finger/thumb)
function renderSuedeTubeNap(spine, radius, colLight, colMid, colDark) {
  // Sample points densely along spine
  for (let i = 0; i < spine.length - 1; i++) {
    let p0 = spine[i];
    let p1 = spine[i + 1];
    let dx = p1[0] - p0[0];
    let dy = p1[1] - p0[1];
    let segLen = Math.hypot(dx, dy);
    let tx = dx / segLen;
    let ty = dy / segLen;
    // Normal pointing toward top-left (light side) vs bottom-right (shadow side)
    let nx = ty;
    let ny = -tx;
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }

    let steps = int(segLen / 3.5);
    for (let s = 0; s <= steps; s++) {
      let t = s / max(1, steps);
      let cx = lerp(p0[0], p1[0], t);
      let cy = lerp(p0[1], p1[1], t);

      // Place 5 fibrous nap strokes across the width of the finger cylinder
      for (let k = -2; k <= 2; k++) {
        let frac = k / 2.2 + random(-0.18, 0.18);
        let offset = frac * radius;
        let sx = cx + nx * offset;
        let sy = cy + ny * offset;

        let strokeCol = frac > 0.25 ? colLight : (frac > -0.35 ? colMid : colDark);
        let napLen = random(5, 11);
        let ang = Math.atan2(ty, tx) + random(-0.45, 0.45);

        brush.set("suede_nap", strokeCol, random(0.55, 1.1));
        brush.line(
          sx - Math.cos(ang) * napLen * 0.5,
          sy - Math.sin(ang) * napLen * 0.5,
          sx + Math.cos(ang) * napLen * 0.5,
          sy + Math.sin(ang) * napLen * 0.5
        );
      }
    }
  }
}

// Helper to draw a recessed leather seam line and individual dashed nylon thread stitches
function drawStitchedSeam(pts, stitchSpacing = 8.5, doubleRow = false) {
  // First draw the dark recessed seam groove
  let groovePts = pts.map(p => [p[0], p[1], 0.95]);
  brush.set("2B", "#2e1607", 0.9);
  brush.spline(groovePts, 0.22);

  let offsets = doubleRow ? [-2.2, 2.2] : [0];
  for (let off of offsets) {
    for (let i = 0; i < pts.length - 1; i++) {
      let p0 = pts[i];
      let p1 = pts[i + 1];
      let dx = p1[0] - p0[0];
      let dy = p1[1] - p0[1];
      let len = Math.hypot(dx, dy);
      let tx = dx / len;
      let ty = dy / len;
      let nx = -ty;
      let ny = tx;

      let numStitches = max(1, int(len / stitchSpacing));
      for (let s = 0; s < numStitches; s++) {
        let t0 = (s + 0.18) / numStitches;
        let t1 = (s + 0.74) / numStitches;
        let x0 = lerp(p0[0], p1[0], t0) + nx * off;
        let y0 = lerp(p0[1], p1[1], t0) + ny * off;
        let x1 = lerp(p0[0], p1[0], t1) + nx * off;
        let y1 = lerp(p0[1], p1[1], t1) + ny * off;

        // Needle hole shadow at start and end of stitch
        brush.set("graphite_crisp", "#1c0c03", 0.9);
        brush.circle(x0, y0, 0.8, 0.1);
        brush.circle(x1, y1, 0.8, 0.1);

        // Raised warm cream-tan heavy nylon thread stitch
        brush.set("HB", "#f2dfc4", 1.05);
        brush.line(x0, y0, x1, y1);
      }
    }
  }
}

// ============================================================================
// 7. FINAL HIGH-CONTRAST GRAPHITE & CHARCOAL ACCENTS
// ============================================================================
function renderFinalAccents() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // Re-intensify the stair lip segments on the left and right of the glove
  // Left segment of lip: s from -20 to 325 (before cuff)
  let leftLipHi = [];
  let leftLipLo = [];
  for (let s = -20; s <= 325; s += 15) {
    let n = (noise(s * 0.02, 91.2) - 0.5) * 4.0;
    let pHi = toCanvas(s, 3 + n);
    let pLo = toCanvas(s, -17 + n);
    leftLipHi.push([pHi[0], pHi[1], 1.15]);
    leftLipLo.push([pLo[0], pLo[1], 1.25]);
  }
  brush.set("charcoal", "#f2f5ee", 1.05);
  brush.spline(leftLipHi, 0.18);
  brush.set("charcoal", "#060707", 1.25);
  brush.spline(leftLipLo, 0.18);

  // Right segment of lip: s from 835 to 1320 (to the right of the curled fingers)
  let rightLipHi = [];
  let rightLipLo = [];
  for (let s = 835; s <= 1320; s += 15) {
    let n = (noise(s * 0.02, 91.2) - 0.5) * 4.0;
    let pHi = toCanvas(s, 3 + n);
    let pLo = toCanvas(s, -17 + n);
    rightLipHi.push([pHi[0], pHi[1], 1.15]);
    rightLipLo.push([pLo[0], pLo[1], 1.25]);
  }
  brush.set("charcoal", "#f2f5ee", 1.05);
  brush.spline(rightLipHi, 0.18);
  brush.set("charcoal", "#060707", 1.25);
  brush.spline(rightLipLo, 0.18);

  // Stray suede fibers / frayed thread ends along the worn fingertips and cuff rim
  const fraySpots = [
    [768, 412, -25], [772, 438, 15], [832, 448, -10], [826, 485, 25],
    [832, 518, 10],  [804, 572, 35], [705, 608, 45],  [345, 535, -140],
    [322, 645, 175], [362, 722, 110]
  ];
  for (let f of fraySpots) {
    for (let k = 0; k < 4; k++) {
      let a = (f[2] + random(-30, 30)) * Math.PI / 180;
      let len = random(4, 9);
      brush.set("graphite_crisp", k % 2 === 0 ? "#e8c89e" : "#4a250d", 0.75);
      brush.line(f[0], f[1], f[0] + Math.cos(a) * len, f[1] + Math.sin(a) * len);
    }
  }

  // Fine charcoal dust and atmospheric grain across the heavy corners of the sheet
  brush.set("charcoal_smudge", "#141615", 0.9);
  for (let i = 0; i < 28; i++) {
    let x = random(0, 1200);
    let y = random(0, 1200);
    if (x > 160 && x < 1040 && y > 160 && y < 1040) continue;
    let ang = STAIR_ANGLE * Math.PI / 180;
    brush.line(x, y, x + Math.cos(ang) * 45, y + Math.sin(ang) * 45);
  }
}

