// ============================================================================
// 1. DOORSTEP FLOOR, THRESHOLD SILL & STONE TEXTURE
// ============================================================================
function drawDoorstepFloor() {
  // Base warm stone washes with raking morning light (brighter top-left, deeper bottom-right)
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.25);

  // Upper-left sunlit stone zone
  brush.fill(PAL.stoneLight, 140);
  brush.rect(0, 0, 850, 750, "corner");

  // Mid-tone diagonal stone transitions
  brush.fill(PAL.stoneMid, 125);
  brush.rect(250, 200, 950, 1000, "corner");

  // Deeper warm-grey stone toward bottom-right & right
  brush.fill(PAL.stoneDark, 110);
  brush.rect(520, 420, 680, 780, "corner");

  // Subtle shadow vignette at far right & bottom-right
  brush.fill(PAL.stoneDeep, 85);
  brush.rect(780, 620, 420, 580, "corner");
  brush.noFill();

  // Fine stone directional grain hatch (dressed Kota/sandstone slabs)
  brush.hatchStyle("2H", PAL.stoneDark, 0.65);
  brush.hatch(14, 18, { rand: 0.12, gradient: 0.35 });
  brush.noStroke();
  brush.rect(0, 110, 1200, 1090, "corner");
  brush.noHatch();

  brush.hatchStyle("HB", PAL.stoneDeep, 0.55);
  brush.hatch(22, -72, { rand: 0.15, gradient: 0.5 });
  brush.noStroke();
  brush.rect(400, 110, 800, 1090, "corner");
  brush.noHatch();

  // Mineral speckle across floor slabs
  for (let i = 0; i < 160; i++) {
    let sx = random(20, 1180);
    let sy = random(120, 1180);
    let len = random(15, 65);
    let ang = random(-15, 35);
    brush.set("powder_mist", i % 3 === 0 ? PAL.stoneLight : PAL.stoneDeep, random(0.4, 0.9));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // Carved Stone Threshold Sill (Chaukhat) along top edge (y: 0 -> ~135 on left, ~92 on right)
  let sillPts = [[0, 0], [1200, 0], [1200, 92], [0, 138]];
  brush.noStroke();
  brush.wash(PAL.stoneMid, 210);
  brush.beginShape(0);
  for (let p of sillPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Raking cast shadow right below the doorstep sill drop-off
  brush.noStroke();
  brush.wash(PAL.stoneShadow, 175);
  brush.beginShape(0.1);
  brush.vertex(0, 138);
  brush.vertex(1200, 92);
  brush.vertex(1200, 112);
  brush.vertex(0, 162);
  brush.endShape(true);
  brush.noWash();

  // Chiseled grooves and tool marks on the stone sill
  for (let x = 8; x < 1200; x += 9) {
    let yBottom = map(x, 0, 1200, 138, 92);
    let wobble = random(-1.5, 1.5);
    brush.set("2B", PAL.stoneDeep, random(0.5, 0.9));
    brush.line(x + wobble, 0, x - 3 + wobble, yBottom - 12);
    if (x % 18 === 8) {
      brush.set("cpencil", PAL.stoneLight, 0.8);
      brush.line(x + 2, 10, x, yBottom - 6);
    }
  }

  // Chamfer highlight & shadow line along the threshold lip
  brush.set("cpencil", PAL.chalkSun, 1.3);
  brush.line(0, 128, 1200, 83);
  brush.set("rotring", PAL.abyssShadow, 1.2);
  brush.line(0, 138, 1200, 92);
  brush.set("charcoal", PAL.stoneShadow, 1.4);
  brush.line(0, 145, 1200, 98);

  // Traditional faded auspicious Haldi-Kumkum threshold dab marks on the stone sill
  let sillMarks = [140, 320, 510, 690, 880, 1060];
  for (let mx of sillMarks) {
    let my = map(mx, 0, 1200, 102, 66);
    brush.set("powder_dense", PAL.turmBright, 0.65);
    brush.circle(mx - 6, my, 8, 0.3);
    brush.set("powder_dense", PAL.vermMid, 0.7);
    brush.circle(mx + 6, my + 1, 7, 0.3);
  }

  // Stone Slab Mortar Joints across the floor
  drawStoneJoint(0, 585, 1200, 495);
  drawStoneJoint(705, 111, 775, 1200);
}

function drawStoneJoint(x1, y1, x2, y2) {
  let steps = 45;
  let ptsShadow = [];
  let ptsLight = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t) + (noise(t * 8, y1 * 0.01) - 0.5) * 6;
    let y = lerp(y1, y2, t) + (noise(t * 8 + 20, x1 * 0.01) - 0.5) * 6;
    ptsShadow.push([x, y, random(0.6, 1.2)]);
    ptsLight.push([x + LX * 3.2, y + LY * 3.2, random(0.5, 1.0)]);
  }
  brush.set("2B", PAL.stoneShadow, 1.15);
  brush.spline(ptsShadow, 0.3);
  brush.set("rotring", PAL.abyssShadow, 0.75);
  brush.spline(ptsShadow, 0.3);
  brush.set("cpencil", PAL.stoneLight, 0.95);
  brush.spline(ptsLight, 0.3);
}

// ============================================================================
// 2. HALF-FINISHED SYMMETRIC RANGOLI AT BOTTOM-LEFT CORNER
// ============================================================================
function drawCornerRangoli(cx, cy) {
  // Faint rubbed chalk under-guideline circles on the stone
  brush.set("cpencil", PAL.chalkMid, 0.55);
  brush.circle(cx, cy, 88, 0.15);
  brush.circle(cx, cy, 185, 0.15);
  brush.circle(cx, cy, 295, 0.15);
  brush.circle(cx, cy, 385, 0.15);

  // Pulli (dot grid) extending into the unfinished upper-right quadrant of the corner pattern
  for (let ring = 1; ring <= 6; ring++) {
    let r = ring * 68;
    let count = ring * 6;
    for (let k = 0; k < count; k++) {
      let ang = -170 + (k / count) * 360;
      let px = cx + cos(ang) * r;
      let py = cy + sin(ang) * r;
      if (px > -20 && px < 680 && py > 540 && py < 1220) {
        drawPinchedDot(px, py, random(3.2, 5.0), PAL.chalkSun, PAL.stoneShadow);
      }
    }
  }

  // 12-fold symmetric lotus & geometric star sectors
  // Sectors 0..7 are finished; Sectors 8..9 are half-finished; Sectors 10..11 are bare guide dots!
  let numSectors = 12;
  for (let s = 0; s < numSectors; s++) {
    let a1 = -180 + s * (360 / numSectors);
    let aMid = a1 + 15;
    let a2 = a1 + 30;

    // Check if sector is on canvas
    let testX = cx + cos(aMid) * 180;
    let testY = cy + sin(aMid) * 180;
    if (testX < -120 || testY > 1320) continue;

    // Determine completion stage:
    // angles between -45 and +45 (pointing towards center-right of canvas) are unfinished!
    let isUnfinished = (aMid > -38 && aMid < 48);
    let isHalfFinished = (aMid >= -75 && aMid <= -38) || (aMid >= 48 && aMid <= 78);

    // A. INNER LOTUS PETAL (r: 28 -> 96) — Blazing Vermilion fill
    if (!isUnfinished) {
      let fillSteps = isHalfFinished ? 9 : 18;
      for (let i = 0; i < fillSteps; i++) {
        let rr = map(i, 0, 18, 32, 92);
        let spread = sin(map(rr, 28, 96, 0, 180)) * 12;
        let p1x = cx + cos(aMid - spread) * rr;
        let p1y = cy + sin(aMid - spread) * rr;
        let p2x = cx + cos(aMid + spread) * rr;
        let p2y = cy + sin(aMid + spread) * rr;
        brush.set("powder_dense", i % 2 === 0 ? PAL.vermMid : PAL.vermBright, 0.75);
        brush.line(p1x, p1y, p2x, p2y);
      }
    }

    // B. MIDDLE INTERLOCKING STAR DIAMOND (r: 100 -> 195) — Alternating Turmeric & Magenta
    if (!isUnfinished) {
      let useTurm = (s % 2 === 0);
      let cDark = useTurm ? PAL.turmDark : PAL.magDark;
      let cBright = useTurm ? PAL.turmBright : PAL.magBright;
      let maxI = isHalfFinished ? 7 : 15;
      for (let i = 0; i < maxI; i++) {
        let rr = map(i, 0, 15, 106, 186);
        let spread = (1 - abs(rr - 146) / 45) * 11;
        let p1x = cx + cos(aMid - spread) * rr;
        let p1y = cy + sin(aMid - spread) * rr;
        let p2x = cx + cos(aMid + spread) * rr;
        let p2y = cy + sin(aMid + spread) * rr;
        brush.set("powder_dense", i % 2 === 0 ? cDark : cBright, 0.7);
        brush.line(p1x, p1y, p2x, p2y);
      }
    }

    // C. OUTER SCALLOP PETAL (r: 205 -> 305) — Parrot slate & Vermilion tips
    if (!isUnfinished && !isHalfFinished) {
      for (let i = 0; i < 14; i++) {
        let rr = map(i, 0, 14, 210, 292);
        let spread = sin(map(rr, 205, 298, 0, 180)) * 10.5;
        let col = rr > 258 ? PAL.vermMid : (i % 2 === 0 ? PAL.parMid : PAL.parBright);
        brush.set("powder_dense", col, 0.68);
        brush.line(
          cx + cos(aMid - spread) * rr, cy + sin(aMid - spread) * rr,
          cx + cos(aMid + spread) * rr, cy + sin(aMid + spread) * rr
        );
      }
    }

    // D. WOBBLY FINGER-PINCHED CHALK WHITE OUTLINES (with miniature raking shadows!)
    if (!isUnfinished) {
      // Inner petal left & right pinched ridges
      drawPinchedPetalOutline(cx, cy, aMid, 28, 96, 13, false);
      // Middle diamond outline
      drawPinchedDiamondOutline(cx, cy, aMid, 98, 146, 194, 12.5, isHalfFinished);

      if (!isHalfFinished) {
        // Outer scallop double-line petal + spiral curl
        drawPinchedPetalOutline(cx, cy, aMid, 200, 302, 11.5, true);
        // Vermilion bindu dot at tip of outer petal
        let tipX = cx + cos(aMid) * 326;
        let tipY = cy + sin(aMid) * 326;
        drawPinchedDot(tipX, tipY, 8.5, PAL.vermBright, PAL.vermShadow);
        drawPinchedDot(tipX, tipY, 3.5, PAL.chalkSun, PAL.vermDark);
      } else {
        // Half-finished wobbling line that stops abruptly mid-stroke with a tiny pinch heap!
        let stopPts = [];
        for (let t = 0; t <= 0.55; t += 0.08) {
          let rr = lerp(200, 302, t);
          let ang = aMid - sin(t * 180) * 11.5;
          stopPts.push([cx + cos(ang) * rr, cy + sin(ang) * rr]);
        }
        drawWobblyPinchLine(stopPts, 1.05);
        let lastP = stopPts[stopPts.length - 1];
        // Tiny conical heap where the artist's thumb & forefinger stopped releasing chalk
        drawPinchedDot(lastP[0], lastP[1], 7.5, PAL.chalkPeak, PAL.stoneShadow);
        for (let g = 0; g < 18; g++) {
          let ga = random(360);
          let gd = random(2, 18);
          drawMicroGrain(lastP[0] + cos(ga) * gd, lastP[1] + sin(ga) * gd, PAL.chalkSun, PAL.stoneShadow, random(1.2, 2.6));
        }
      }
    }
  }

  // Central Mandala Medallion at (cx, cy)
  drawPinchedDot(cx, cy, 26, PAL.vermMid, PAL.vermShadow);
  drawPinchedDot(cx, cy, 16, PAL.turmSun, PAL.turmShadow);
  drawPinchedDot(cx, cy, 7, PAL.chalkPeak, PAL.stoneShadow);
}

function drawPinchedPetalOutline(cx, cy, aMid, rIn, rOut, maxSpread, doubleLine) {
  for (let side of [-1, 1]) {
    let pts = [];
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let rr = lerp(rIn, rOut, t);
      let ang = aMid + side * sin(t * 180) * maxSpread;
      pts.push([cx + cos(ang) * rr, cy + sin(ang) * rr]);
    }
    drawWobblyPinchLine(pts, 0.95);

    if (doubleLine) {
      let pts2 = [];
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let rr = lerp(rIn - 4, rOut + 10, t);
        let ang = aMid + side * sin(t * 180) * (maxSpread + 3.2);
        pts2.push([cx + cos(ang) * rr, cy + sin(ang) * rr]);
      }
      drawWobblyPinchLine(pts2, 0.78);
    }
  }
}

function drawPinchedDiamondOutline(cx, cy, aMid, rIn, rMid, rOut, spread, partial) {
  let sides = partial ? [-1] : [-1, 1];
  for (let side of sides) {
    let p1 = [cx + cos(aMid) * rIn, cy + sin(aMid) * rIn];
    let p2 = [cx + cos(aMid + side * spread) * rMid, cy + sin(aMid + side * spread) * rMid];
    let p3 = [cx + cos(aMid) * rOut, cy + sin(aMid) * rOut];
    drawWobblyPinchSegment(p1[0], p1[1], p2[0], p2[1], 7);
    if (!partial || side === -1) {
      drawWobblyPinchSegment(p2[0], p2[1], p3[0], p3[1], 7);
    }
  }
}

function drawWobblyPinchSegment(x1, y1, x2, y2, steps) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    pts.push([lerp(x1, x2, t), lerp(y1, y2, t)]);
  }
  drawWobblyPinchLine(pts, 0.9);
}

// Renders a finger-released powder line: wobbly trajectory + pulsing pinch thickness + raking shadow
function drawWobblyPinchLine(pts, weightScale) {
  if (pts.length < 2) return;
  let shadowPts = [];
  let mainPts = [];
  let crestPts = [];

  for (let i = 0; i < pts.length; i++) {
    let wobX = (noise(pts[i][0] * 0.06, pts[i][1] * 0.06) - 0.5) * 4.5;
    let wobY = (noise(pts[i][0] * 0.06 + 50, pts[i][1] * 0.06 + 50) - 0.5) * 4.5;
    let px = pts[i][0] + wobX;
    let py = pts[i][1] + wobY;
    // Finger-pinch pulse pressure along the line
    let pinchPressure = (0.7 + 0.55 * sin(i * 75) + random(-0.15, 0.15)) * weightScale;
    shadowPts.push([px + LX * 3.0, py + LY * 3.0, pinchPressure * 0.9]);
    mainPts.push([px, py, pinchPressure]);
    crestPts.push([px - LX * 0.8, py - LY * 0.8, pinchPressure * 0.65]);
  }

  // 1. Miniature raking ridge shadow on bottom-right
  brush.set("2B", PAL.stoneShadow, 1.35 * weightScale);
  brush.spline(shadowPts, 0.45);

  // 2. Soft stray grain halo
  brush.set("powder_dense", PAL.chalkMid, 0.42 * weightScale);
  brush.spline(mainPts, 0.45);

  // 3. Dense matte chalk ridge body
  brush.set("pinch_chalk", PAL.chalkSun, 0.95 * weightScale);
  brush.spline(mainPts, 0.45);

  // 4. Sunlit top-left crest highlight
  brush.set("cpencil", PAL.chalkPeak, 0.85 * weightScale);
  brush.spline(crestPts, 0.45);
}

function drawPinchedDot(x, y, radius, colMain, colShadow) {
  brush.set("2B", colShadow, 1.1);
  brush.circle(x + LX * 2.5, y + LY * 2.5, radius * 0.95, 0.35);
  brush.set("powder_dense", colMain, 0.65);
  brush.circle(x, y, radius, 0.35);
  brush.set("pinch_chalk", colMain, 0.75);
  brush.circle(x - LX * 0.7, y - LY * 0.7, radius * 0.55, 0.4);
}

// ============================================================================
// 3. LAYERED GRANULAR POWDER CONES & SPILLS
// ============================================================================

// THE HERO ACCENT: Knocked-over Vermilion Tin fanning cone
function drawVermilionHeroCone(ox, oy, dirAngle) {
  let coneLen = 430;
  let spreadAngle = 39;

  // 1. Deep shadow rim along the down-light (bottom-right) edge of the thick powder pile
  drawPowderFanBase(ox + LX * 7, oy + LY * 7, dirAngle + 2, coneLen * 0.96, spreadAngle, PAL.vermShadow, 185);

  // 2. Rich deep crimson base wash of the cone
  drawPowderFanBase(ox, oy, dirAngle, coneLen * 0.93, spreadAngle, PAL.vermDeep, 210);
  drawPowderFanBase(ox, oy, dirAngle - 2, coneLen * 0.78, spreadAngle * 0.85, PAL.vermDark, 195);

  // 3. Dense layered granular spray passes building matte 3D volume
  // Up-light flank (top-left of cone, angles dirAngle - spread .. dirAngle) catches blazing late-morning sun
  // Down-light flank (bottom-right of cone, angles dirAngle .. dirAngle + spread) falls into deep velvet crimson
  let rays = 115;
  for (let i = 0; i < rays; i++) {
    let u = i / (rays - 1); // 0 = top-left sunlit flank, 1 = bottom-right shadowed flank
    let ang = dirAngle + map(u, 0, 1, -spreadAngle * 1.12, spreadAngle * 1.12) + random(-2.5, 2.5);
    let edgeFactor = 1 - pow(abs(u - 0.48) * 1.95, 1.7);
    let maxR = coneLen * max(0.18, edgeFactor) * random(0.78, 1.08);

    // Choose color by surface normal relative to raking light
    let col;
    if (u < 0.25) col = random() < 0.55 ? PAL.vermSun : PAL.vermBright;
    else if (u < 0.52) col = random() < 0.6 ? PAL.vermBright : PAL.vermMid;
    else if (u < 0.78) col = random() < 0.65 ? PAL.vermMid : PAL.vermDark;
    else col = random() < 0.6 ? PAL.vermDark : PAL.vermDeep;

    let rStart = random(4, 45);
    let x1 = ox + cos(ang) * rStart;
    let y1 = oy + sin(ang) * rStart;
    let x2 = ox + cos(ang) * maxR;
    let y2 = oy + sin(ang) * maxR;

    brush.set(i % 3 === 0 ? "powder_mist" : "powder_dense", col, random(0.65, 1.35));
    brush.line(x1, y1, x2, y2);
  }

  // 4. Concentrated incandescent sunlit core & spine near the tin mouth
  for (let i = 0; i < 45; i++) {
    let ang = dirAngle + random(-spreadAngle * 0.65, spreadAngle * 0.15);
    let r1 = random(2, 30);
    let r2 = random(70, 275);
    brush.set("powder_dense", i % 4 === 0 ? PAL.vermPeak : PAL.vermSun, random(0.7, 1.2));
    brush.line(ox + cos(ang) * r1, oy + sin(ang) * r1, ox + cos(ang) * r2, oy + sin(ang) * r2);
  }

  // 5. Parabolic Avalanche Slump Ridges (tiny terraced waves inside the poured cone casting miniature shadows!)
  let numRidges = 22;
  for (let rIdx = 0; rIdx < numRidges; rIdx++) {
    let dist = map(rIdx, 0, numRidges - 1, 32, coneLen * 0.92) + random(-8, 8);
    let arcSpan = map(dist, 30, coneLen, spreadAngle * 0.55, spreadAngle * 0.92);
    let aCenter = dirAngle + random(-arcSpan * 0.28, arcSpan * 0.28);
    let aSpan = random(arcSpan * 0.35, arcSpan * 0.85);

    drawPowderAvalancheRidge(
      ox, oy, dist, aCenter - aSpan * 0.5, aCenter + aSpan * 0.5,
      PAL.vermShadow, PAL.vermDeep, PAL.vermSun, PAL.vermPeak,
      map(dist, 30, coneLen, 1.35, 0.65)
    );
  }

  // 6. Peripheral feathered dust & scattered vermilion granules fanned out by impact
  scatterConeEdgeGrains(ox, oy, dirAngle, coneLen, spreadAngle, PAL.vermMid, PAL.vermSun, PAL.vermShadow, 180);
}

// Knocked-over Chalk White Tin fanning cone (overlaps upper edge of vermilion!)
function drawChalkCone(ox, oy, dirAngle) {
  let coneLen = 320;
  let spreadAngle = 36;

  drawPowderFanBase(ox + LX * 5, oy + LY * 5, dirAngle, coneLen * 0.92, spreadAngle, PAL.chalkShadow, 165);
  drawPowderFanBase(ox, oy, dirAngle, coneLen * 0.88, spreadAngle, PAL.chalkMid, 195);
  drawPowderFanBase(ox, oy, dirAngle - 3, coneLen * 0.72, spreadAngle * 0.8, PAL.chalkBright, 190);

  let rays = 85;
  for (let i = 0; i < rays; i++) {
    let u = i / (rays - 1);
    let ang = dirAngle + map(u, 0, 1, -spreadAngle * 1.1, spreadAngle * 1.1) + random(-2, 2);
    let edgeFactor = 1 - pow(abs(u - 0.5) * 1.9, 1.6);
    let maxR = coneLen * max(0.2, edgeFactor) * random(0.8, 1.08);

    // Since dirAngle is ~144 deg (down-left), higher angles (top-left side) face the light
    let col;
    if (u > 0.65) col = random() < 0.6 ? PAL.chalkPeak : PAL.chalkSun;
    else if (u > 0.35) col = random() < 0.6 ? PAL.chalkSun : PAL.chalkBright;
    else col = random() < 0.6 ? PAL.chalkMid : PAL.chalkDark;

    brush.set(i % 3 === 0 ? "powder_mist" : "powder_dense", col, random(0.6, 1.25));
    brush.line(
      ox + cos(ang) * random(5, 30), oy + sin(ang) * random(5, 30),
      ox + cos(ang) * maxR, oy + sin(ang) * maxR
    );
  }

  // Avalanche slump ridges in the chalk cone
  for (let rIdx = 0; rIdx < 16; rIdx++) {
    let dist = map(rIdx, 0, 15, 28, coneLen * 0.88) + random(-6, 6);
    let span = map(dist, 28, coneLen, 16, 32);
    let aCenter = dirAngle + random(-10, 10);
    drawPowderAvalancheRidge(
      ox, oy, dist, aCenter - span * 0.5, aCenter + span * 0.5,
      PAL.stoneShadow, PAL.chalkShadow, PAL.chalkSun, PAL.chalkPeak,
      map(dist, 28, coneLen, 1.2, 0.6)
    );
  }

  scatterConeEdgeGrains(ox, oy, dirAngle, coneLen, spreadAngle, PAL.chalkBright, PAL.chalkPeak, PAL.stoneShadow, 120);
}

