  brush.circle(lx, ly, lidR * 0.86, 0.05);
  brush.circle(lx, ly, lidR * 0.52, 0.05);
  brush.set("cpencil", PAL.metalSpec, 1.15);
  brush.arc(lx, ly, lidR * 0.98, 155, 335);
  brush.arc(lx, ly, lidR * 0.86, 160, 330);

