  drawCurvedTextOnArc(lx, ly, lidR * 0.68, lidR * 0.68, 0, "RANGOLI", 195, 345, 9, PAL.metalDark);

  // Parrot powder spilling from the upright tin (tx, ty) right across the edge of the fallen lid!
