// Helper: Soft teardrop/fan base wash for a poured powder cone
function drawPowderFanBase(ox, oy, dirAngle, len, spreadAngle, col, alphaVal) {
  brush.noStroke();
  brush.wash(col, alphaVal);
  brush.beginShape(0.25);
  brush.vertex(ox, oy);
  let steps = 18;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let ang = dirAngle + map(u, 0, 1, -spreadAngle, spreadAngle);
    let profile = sin(u * 180);
    let r = len * (0.35 + 0.65 * pow(profile, 0.65)) * (0.94 + 0.12 * noise(u * 6, ox * 0.02));
    brush.vertex(ox + cos(ang) * r, oy + sin(ang) * r);
  }
  brush.endShape(true);
  brush.noWash();
}

// Helper: Draws a single miniature crescent ridge inside a powder cone with raking shadow & sunlit crest
function drawPowderAvalancheRidge(ox, oy, radius, aStart, aEnd, colShadow, colDark, colSun, colPeak, wScale) {
  let steps = 10;
  let ptsShadow = [];
  let ptsDark = [];
  let ptsCrest = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = lerp(aStart, aEnd, t);
    let bulge = sin(t * 180) * (radius * 0.08);
    let wob = (noise(t * 5, radius * 0.05) - 0.5) * 6;
    let r = radius + bulge + wob;
    let px = ox + cos(ang) * r;
    let py = oy + sin(ang) * r;
    let press = sin(t * 180) * wScale;

    ptsShadow.push([px + LX * 3.4 * wScale, py + LY * 3.4 * wScale, press]);
    ptsDark.push([px + LX * 1.6 * wScale, py + LY * 1.6 * wScale, press * 1.1]);
    ptsCrest.push([px, py, press]);
  }

  // Miniature shadow cast by the powder ridge
  brush.set("2B", colShadow, 1.3 * wScale);
  brush.spline(ptsShadow, 0.45);
  brush.set("powder_ridge", colDark, 0.85 * wScale);
  brush.spline(ptsDark, 0.45);

  // Sunlit granular crest of the ridge
  brush.set("powder_ridge", colSun, 0.95 * wScale);
  brush.spline(ptsCrest, 0.45);
  brush.set("cpencil", colPeak, 0.9 * wScale);
  brush.spline(ptsCrest, 0.45);
}

// Helper: Scatters realistic clumped powder crumbs & dust around a cone perimeter
function scatterConeEdgeGrains(ox, oy, dirAngle, coneLen, spreadAngle, colMid, colBright, colShadow, count) {
  for (let i = 0; i < count; i++) {
    let ang = dirAngle + random(-spreadAngle * 1.45, spreadAngle * 1.45);
    let d = random(coneLen * 0.35, coneLen * 1.28);
    let gx = ox + cos(ang) * d + random(-18, 18);
    let gy = oy + sin(ang) * d + random(-18, 18);
    let sz = random(1.1, 3.8);
    drawMicroGrain(gx, gy, random() < 0.55 ? colBright : colMid, colShadow, sz);
  }
}

function drawMicroGrain(x, y, colLight, colShadow, sz) {
  // Tiny shadow dot on down-light side
  brush.set("2B", colShadow, sz * 0.52);
  brush.line(x + LX * sz * 0.85, y + LY * sz * 0.85, x + LX * sz * 1.35, y + LY * sz * 1.35);
  // Tiny sunlit powder granule on up-light side
  brush.set("cpencil", colLight, sz * 0.65);
  brush.line(x, y, x + 0.8, y + 0.5);
}

// ============================================================================
// 4. FOOTPRINT-SMUDGED DRIFTS & FINGER WIPES
// ============================================================================
function drawSmudgedFootprint(fx, fy, rotAngle, isDeepInPowder) {
  let ca = cos(rotAngle);
  let sa = sin(rotAngle);
  function toWorld(lx, ly) {
    return [fx + lx * ca - ly * sa, fy + lx * sa + ly * ca];
  }

  // Anatomical bare foot pads in local space (x along step direction -95..+95, y across width -42..+42)
  // 1. Heel & lateral arch & ball of foot contour
  let soleLocal = [
    [-92, 0], [-86, -24], [-60, -28], [-20, -22], [18, -32],
    [52, -40], [74, -32], [80, -10], [76, 16], [64, 36],
    [35, 38], [0, 18], [-38, 16], [-72, 24], [-88, 14]
  ];
  let soleWorld = soleLocal.map(p => toWorld(p[0], p[1]));

  if (isDeepInPowder) {
    // A. Compressed interior of the footprint where the sole crushed & smeared the vermilion/chalk drift
    brush.noStroke();
    brush.wash(PAL.vermDark, 170);
    brush.beginShape(0.35);
    for (let p of soleWorld) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noWash();

    // Smeared skin-friction drag lines inside the compressed sole
    for (let i = 0; i < 42; i++) {
      let lx1 = random(-82, 55);
      let ly1 = random(-24, 24) * (lx1 > 0 ? 1.2 : 0.85);
      let dragLen = random(18, 42);
      let p1 = toWorld(lx1, ly1);
      let p2 = toWorld(lx1 + dragLen, ly1 + random(-3, 3));
      let col = i % 5 === 0 ? PAL.chalkMid : (i % 2 === 0 ? PAL.vermMid : PAL.stoneDark);
      brush.set(i % 3 === 0 ? "cpencil" : "powder_ridge", col, random(0.55, 1.0));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // B. Squeezed-up miniature powder ridge all around the perimeter of the sole!
    for (let i = 0; i < soleWorld.length; i++) {
      let pA = soleWorld[i];
      let pB = soleWorld[(i + 1) % soleWorld.length];
      let mid = [(pA[0] + pB[0]) * 0.5, (pA[1] + pB[1]) * 0.5];
      let pts = [pA, mid, pB];

      // Raking shadow on the bottom-right of the squeezed-up rim
      let shPts = pts.map(p => [p[0] + LX * 3.8, p[1] + LY * 3.8, 1.1]);
      let hiPts = pts.map(p => [p[0] - LX * 1.2, p[1] - LY * 1.2, 1.1]);

      brush.set("2B", PAL.vermShadow, 1.45);
      brush.spline(shPts, 0.4);
      brush.set("powder_ridge", PAL.vermBright, 1.1);
      brush.spline(pts.map(p => [p[0], p[1], 1.0]), 0.4);
      brush.set("cpencil", i < 6 ? PAL.chalkSun : PAL.vermPeak, 0.95);
      brush.spline(hiPts, 0.4);
    }
  } else {
    // Secondary tracked footprint on bare stone: dusty ghost imprint of ball, heel, and toes
    for (let i = 0; i < 55; i++) {
      let isHeel = random() < 0.38;
      let lx = isHeel ? random(-86, -42) : random(12, 74);
      let ly = isHeel ? random(-22, 20) : random(-36, 32);
      let p1 = toWorld(lx, ly);
      let p2 = toWorld(lx + random(8, 22), ly + random(-4, 4));
      let col = random() < 0.25 ? PAL.chalkBright : (random() < 0.6 ? PAL.vermMid : PAL.vermBright);
      brush.set(i % 2 === 0 ? "powder_dense" : "powder_mist", col, random(0.45, 0.85));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // C. Five Toe Imprints + Squeezed Toe Ridges in front of the ball of the foot
  let toes = [
    { x: 102, y: -28, r: 14 }, // Big toe
    { x: 105, y: -8,  r: 10.5 },
    { x: 100, y: 10,  r: 9.5 },
    { x: 92,  y: 25,  r: 8.5 },
    { x: 80,  y: 38,  r: 7.5 }  // Little toe
  ];

  for (let t of toes) {
    let tp = toWorld(t.x, t.y);
    if (isDeepInPowder) {
      // Compressed toe hollow
      brush.set("powder_dense", PAL.vermDark, 0.75);
      brush.circle(tp[0], tp[1], t.r * 0.9, 0.25);
      // Squeezed ridge shadow on down-light side
      brush.set("2B", PAL.vermShadow, 1.35);
      brush.arc(tp[0] + LX * 2.5, tp[1] + LY * 2.5, t.r, -40, 140);
      // Sunlit displaced ridge crest around toe
      brush.set("powder_ridge", PAL.vermSun, 0.95);
      brush.arc(tp[0], tp[1], t.r, 120, 320);
      brush.set("cpencil", PAL.vermPeak, 0.85);
      brush.arc(tp[0] - LX, tp[1] - LY, t.r * 0.95, 140, 300);
    } else {
      // Dusty tracked toe pad
      brush.set("powder_dense", PAL.vermMid, 0.65);
      brush.circle(tp[0], tp[1], t.r * 0.85, 0.35);
      brush.set("powder_mist", PAL.chalkBright, 0.45);
      brush.circle(tp[0] - 3, tp[1] - 2, t.r * 0.7, 0.4);
    }
  }
}

// Three-finger accidental wipe/scoop marks near the rangoli edge
function drawFingerSmudges(x, y, ang) {
  for (let f = -1; f <= 1; f++) {
    let ox = x + f * 18 * sin(ang);
    let oy = y - f * 18 * cos(ang);
    let pts = [];
    for (let i = 0; i <= 8; i++) {
      let d = i * 14;
      let curve = sin(i * 22) * 6;
      pts.push([
        ox + cos(ang) * d - sin(ang) * curve,
        oy + sin(ang) * d + cos(ang) * curve,
        sin((i / 8) * 180)
      ]);
    }
    brush.set("powder_dense", f === 0 ? PAL.vermMid : PAL.chalkMid, 0.65);
    brush.spline(pts, 0.4);
    // Tiny ridge along edge of finger groove
    let ridgePts = pts.map(p => [p[0] + LX * 2.5, p[1] + LY * 2.5, p[2] * 0.8]);
    brush.set("2B", PAL.stoneShadow, 0.95);
    brush.spline(ridgePts, 0.4);
  }
}

// ============================================================================
