// ============================================================================
// 6. PEN-CRISP, DENTED & LETTERED TIN CANS
// ============================================================================

// Upright open tin seen from overhead (with dented double rim, interior shadow & heaped powder)
function drawUprightTin(cfg) {
  let { cx, cy, r, powderPal, label, dentAngles, scoopAngle } = cfg;

  // 1. Long raking cast shadow on the floor to bottom-right
  for (let s = 1; s <= 16; s++) {
    let off = s * 2.6;
    brush.set("charcoal", s < 8 ? PAL.abyssShadow : PAL.stoneShadow, map(s, 1, 16, 1.8, 0.6));
    brush.circle(cx + LX * off, cy + LY * off, r * map(s, 1, 16, 1.01, 0.94), 0.12);
  }

  // Helper to compute dented radius at angle a
  function dentedR(a, baseR) {
    let dr = 0;
    for (let da of dentAngles) {
      let diff = abs(((a - da + 540) % 360) - 180);
      if (diff < 24) {
        dr -= cos((diff / 24) * 90) * (baseR * 0.085);
      }
    }
    return baseR + dr + (noise(cos(a) * 2 + cx * 0.01, sin(a) * 2 + cy * 0.01) - 0.5) * 2.2;
  }

  // 2. Outer tin wall collar (slight foreshortening shift along light vector)
  let outerPts = [];
  let innerPts = [];
  let steps = 48;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let ro = dentedR(a, r);
    let ri = dentedR(a, r * 0.91);
    outerPts.push([cx + cos(a) * ro, cy + sin(a) * ro, 1.0]);
    innerPts.push([cx + cos(a) * ri, cy + sin(a) * ri, 1.0]);
  }
  outerPts.push(outerPts[0]);
  innerPts.push(innerPts[0]);

  // Base fill inside tin
  brush.noStroke();
  brush.wash(powderPal[1], 235);
  brush.circle(cx, cy, r * 0.92, 0.1);
  brush.noWash();

  // 3. Heaped granular powder mound inside the open tin
  let moundX = cx - cos(scoopAngle) * (r * 0.18);
  let moundY = cy - sin(scoopAngle) * (r * 0.18);
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let d = random(4, r * 0.84);
    let px = cx + cos(a) * d;
    let py = cy + sin(a) * d;
    // Check if point is on the sunlit side of the internal mound
    let dotLight = ((px - moundX) * (-LX) + (py - moundY) * (-LY)) / r;
    let col = dotLight > 0.15 ? powderPal[4] : (dotLight > -0.15 ? powderPal[3] : powderPal[2]);
    brush.set(i % 2 === 0 ? "powder_dense" : "powder_mist", col, random(0.55, 1.05));
    brush.line(px, py, px + cos(a + 90) * random(8, 22), py + sin(a + 90) * random(8, 22));
  }

  // Finger-scoop hollow & miniature internal ridges inside the tin
  for (let k = 0; k < 5; k++) {
    let rad = map(k, 0, 4, r * 0.22, r * 0.72);
    drawPowderAvalancheRidge(
      moundX, moundY, rad, scoopAngle - 55, scoopAngle + 55,
      powderPal[0], powderPal[1], powderPal[4], powderPal[5], 0.78
    );
  }

  // 4. Crescent interior shadow cast by the tin's upper-left wall onto the powder inside
  for (let s = 1; s <= 7; s++) {
    let shArcPts = [];
    for (let a = 125; a <= 305; a += 8) {
      let ri = dentedR(a, r * 0.9) - s * 2.2;
      shArcPts.push([cx + cos(a) * ri + LX * s * 1.8, cy + sin(a) * ri + LY * s * 1.8, sin(map(a, 125, 305, 0, 180))]);
    }
    brush.set("2B", powderPal[0], 1.15);
    brush.spline(shArcPts, 0.35);
  }

  // 5. Metallic rim collar shading & stenciled rim lettering
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let isSunlit = cos(a - (LIGHT_ANGLE + 180)) > 0.1;
    brush.set("rotring", isSunlit ? PAL.metalLight : PAL.metalDark, 0.85);
    brush.line(outerPts[i][0], outerPts[i][1], innerPts[i][0], innerPts[i][1]);
  }

  // Stenciled text along the top rim collar
  drawCurvedTextOnArc(cx, cy, r * 0.955, r * 0.955, 0, label, 200, 310, 6.5, PAL.abyssShadow);

  // 6. Pen-crisp dented double metal rim + bright specular wire highlight
  brush.set("tin_pen", PAL.abyssShadow, 1.35);
  brush.spline(outerPts, 0.35);
  brush.set("tin_pen", PAL.abyssShadow, 1.15);
  brush.spline(innerPts, 0.35);

  // Bright specular highlight along the top-left sunlit rim bead & dent corners
  let specPts = [];
  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * 360;
    if (a >= 135 && a <= 325) {
      let rm = dentedR(a, r * 0.96);
      specPts.push([cx + cos(a) * rm, cy + sin(a) * rm, 1.1]);
    }
  }
  brush.set("cpencil", PAL.metalSpec, 1.35);
  brush.spline(specPts, 0.35);
}

// Knocked-over cylindrical tin lying on its side in 3/4 overhead foreshortening
function drawKnockedTin(cfg) {
  let { mx, my, axisAngle, len, rx, ry, labelMain, labelSub, accentCol, powderPal, dentPhase } = cfg;

  // Unit vectors: U = along cylinder axis (from back base to open mouth), V = perpendicular across cylinder width
  // Since mouth is at (mx, my) pointing in direction axisAngle, the back base is at (mx - U*len, my - U*len)
  let ux = cos(axisAngle);
  let uy = sin(axisAngle);
  let vx = -sin(axisAngle);
  let vy = cos(axisAngle);

  let bx = mx - ux * len;
  let by = my - uy * len;

  // Helper: Point on elliptical cross-section at axial position s (0 = back base, 1 = open mouth) and angle theta (0..360)
  // theta = -90 is one side wall, theta = +90 is the opposite side wall, theta = 0 is top of cylinder facing viewer!
  function cylPt(s, theta, addDent) {
    let cx = lerp(bx, mx, s);
    let cy = lerp(by, my, s);
    let localRx = rx;
    let localRy = ry;

    if (addDent) {
      // Realistic radial crimp/dent on the open tin mouth & body ribs
      let d1 = sin(theta * 3 + dentPhase * 57) * (s > 0.7 ? 4.2 : 1.5);
      let d2 = exp(-pow((theta - 28) / 22, 2)) * (s > 0.65 ? -6.5 : -2.0);
      localRx += (d1 + d2) * 0.55;
      localRy += (d1 + d2);
    }

    let alongU = sin(theta + 90) * localRx * 0.35; // Foreshortened ellipse depth
    let acrossV = sin(theta) * localRy;
    // Wait: let's parameterize clean ellipse in (U, V) plane:
    // uOffset = cos(theta) * localRx, vOffset = sin(theta) * localRy
    let uOff = cos(theta) * localRx;
    let vOff = sin(theta) * localRy;
    return [cx + ux * uOff + vx * vOff, cy + uy * uOff + vy * vOff];
  }

  // 1. Cast shadow of the cylindrical tin on the doorstep floor (offset along raking light LX, LY)
  brush.noStroke();
  brush.wash(PAL.abyssShadow, 185);
  brush.beginShape(0.15);
  let shOff = 18;
  for (let th = 90; th <= 270; th += 18) {
    let p = cylPt(0, th, false);
    brush.vertex(p[0] + LX * shOff, p[1] + LY * shOff);
  }
  for (let th = -90; th <= 90; th += 18) {
    let p = cylPt(1, th, false);
    brush.vertex(p[0] + LX * (shOff * 0.75), p[1] + LY * (shOff * 0.75));
  }
  brush.endShape(true);
  brush.noWash();

  // Soft penumbra hatch around cast shadow edge
  for (let s = 0.05; s <= 0.95; s += 0.06) {
    let pEdge = cylPt(s, 90, false);
    let pEdge2 = cylPt(s, -90, false);
    // Pick whichever side is further down-light
    let d1 = (pEdge[0] - mx) * LX + (pEdge[1] - my) * LY;
    let d2 = (pEdge2[0] - mx) * LX + (pEdge2[1] - my) * LY;
    let pDown = d1 > d2 ? pEdge : pEdge2;
    brush.set("charcoal", PAL.stoneShadow, 1.35);
    brush.line(pDown[0], pDown[1], pDown[0] + LX * 22, pDown[1] + LY * 22);
  }

  // 2. Cylinder metal body base wash
  brush.noStroke();
  brush.wash(PAL.metalMid, 235);
  brush.beginShape(0.08);
  for (let th = 90; th <= 270; th += 15) {
    let p = cylPt(0, th, false);
    brush.vertex(p[0], p[1]);
  }
  for (let th = 270; th >= 90; th -= 15) {
    let p = cylPt(1, th, true);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Cylindrical metallic shading (longitudinal strokes from s=0 to s=1 across visible top half theta: -90..+90)
  // Determine which side (theta < 0 or theta > 0) faces the top-left raking light (-LX, -LY)
  let vDotLight = vx * (-LX) + vy * (-LY);

  for (let th = -90; th <= 90; th += 4.5) {
    let p0 = cylPt(0.02, th, false);
    let pMid = cylPt(0.5, th, true);
    let p1 = cylPt(0.98, th, true);

    // Surface normal in V direction is sin(th)
    let normalLight = sin(th) * (vDotLight >= 0 ? 1 : -1) + cos(th) * 0.35;

    let col, brName, w;
    if (normalLight > 0.52 && normalLight < 0.78) {
      // Bright specular reflection band along the cylinder!
      col = PAL.metalSpec;
      brName = "cpencil";
      w = 1.25;
    } else if (normalLight > 0.15) {
      col = PAL.metalLight;
      brName = "2H";
      w = 0.9;
    } else if (normalLight > -0.25) {
      col = PAL.metalWarm;
      brName = "HB";
      w = 0.85;
    } else if (normalLight > -0.62) {
      col = PAL.metalDark;
      brName = "2B";
      w = 0.95;
    } else {
      col = PAL.abyssShadow;
      brName = "rotring";
      w = 0.85;
    }

    brush.set(brName, col, w);
    brush.spline([[p0[0], p0[1], 0.9], [pMid[0], pMid[1], 1.1], [p1[0], p1[1], 0.9]], 0.25);
  }

  // 4. Painted/Printed Label Band wrapped around middle of tin body (s: 0.24 .. 0.74)
  for (let th = -84; th <= 84; th += 3.5) {
    let pA = cylPt(0.24, th, false);
    let pB = cylPt(0.74, th, false);
    let normalLight = sin(th) * (vDotLight >= 0 ? 1 : -1);
    let lCol = normalLight > 0.1 ? PAL.stoneLight : (normalLight > -0.35 ? PAL.stoneMid : PAL.stoneDark);
    brush.set("cpencil", lCol, 1.05);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Colored decorative border stripes on the label (s = 0.26 and s = 0.72)
  for (let sStripe of [0.26, 0.72]) {
    let stripePts = [];
    for (let th = -85; th <= 85; th += 10) {
      let p = cylPt(sStripe, th, false);
      stripePts.push([p[0], p[1], 1.0]);
    }
    brush.set("rotring", accentCol, 1.45);
    brush.spline(stripePts, 0.35);
  }

  // 5. Crisp Lettered Text wrapped onto the 3D cylinder label!
  drawCylinderLabelText(cylPt, labelMain, 0.43, -62, 62, 0.16, PAL.abyssShadow, vDotLight);
  drawCylinderLabelText(cylPt, labelSub, 0.62, -38, 38, 0.11, accentCol, vDotLight);

  // 6. Corrugated stiffening ribs (beads) & longitudinal solder seam on the tin body
  for (let sRib of [0.14, 0.84]) {
    let ribDark = [];
    let ribLight = [];
    for (let th = -90; th <= 90; th += 10) {
      let pD = cylPt(sRib, th, true);
      let pL = cylPt(sRib - 0.018, th, true);
      ribDark.push([pD[0], pD[1], 1.0]);
      ribLight.push([pL[0], pL[1], 1.0]);
    }
    brush.set("tin_pen", PAL.abyssShadow, 1.15);
    brush.spline(ribDark, 0.35);
    brush.set("cpencil", PAL.metalSpec, 1.05);
    brush.spline(ribLight, 0.35);
  }

  // Back rim (s = 0, visible arc theta: 90..270) and outer side walls
  let backArc = [];
  for (let th = 90; th <= 270; th += 12) {
    let p = cylPt(0, th, false);
    backArc.push([p[0], p[1], 1.1]);
  }
  brush.set("tin_pen", PAL.abyssShadow, 1.35);
  brush.spline(backArc, 0.35);

  // Double rolled seam at back base
  let backArc2 = [];
  for (let th = 100; th <= 260; th += 12) {
    let p = cylPt(0.03, th, false);
    backArc2.push([p[0], p[1], 0.9]);
  }
  brush.set("tin_pen", PAL.metalDark, 0.95);
  brush.spline(backArc2, 0.35);

  // Crisp side-wall轮廓 lines from s=0 to s=1 at theta = -90 and +90
  for (let thSide of [-90, 90]) {
    let sidePts = [];
    for (let s = 0; s <= 1; s += 0.125) {
      let p = cylPt(s, thSide, true);
      sidePts.push([p[0], p[1], 1.15]);
    }
    brush.set("tin_pen", PAL.abyssShadow, 1.4);
    brush.spline(sidePts, 0.25);
  }

  // 7. Open Mouth Interior (s = 1): Dark shadowed metal cavity + caked residual powder inside
  let mouthOuter = [];
  let mouthInner = [];
  for (let th = 0; th <= 360; th += 10) {
    let pO = cylPt(1.0, th, true);
    let pI = cylPt(0.96, th, true);
    // Shrink inner rim slightly toward center (mx, my)
    pI = [lerp(pO[0], mx, 0.08), lerp(pO[1], my, 0.08)];
    mouthOuter.push([pO[0], pO[1], 1.15]);
    mouthInner.push([pI[0], pI[1], 1.0]);
  }

  // Dark interior cavity wash
  brush.noStroke();
  brush.wash(PAL.abyssShadow, 215);
  brush.beginShape(0.2);
  for (let p of mouthInner) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Interior curved metal cross-hatching inside the upper roof of the tin cavity
  for (let i = 0; i < 24; i++) {
    let th = random(0, 360);
    let pRim = cylPt(1.0, th, true);
    let depth = random(0.18, 0.45);
    let pDeep = cylPt(1.0 - depth, th + random(-12, 12), false);
    brush.set("rotring", PAL.metalDark, 0.75);
    brush.line(pRim[0], pRim[1], lerp(pRim[0], pDeep[0], 0.65), lerp(pRim[1], pDeep[1], 0.65));
  }

  // Caked powder mound spilling right out of the lower half of the tin mouth
  for (let i = 0; i < 38; i++) {
    let th = random(-75, 255);
    let rad = random(0.15, 0.88);
    let pRim = cylPt(1.0, th, true);
    let px = lerp(mx, pRim[0], rad);
    let py = lerp(my, pRim[1], rad);
    let col = i % 3 === 0 ? powderPal[5] : (i % 2 === 0 ? powderPal[4] : powderPal[3]);
    brush.set("powder_dense", col, random(0.65, 1.15));
    brush.line(px - ux * 16, py - uy * 16, px + ux * 26, py + uy * 26);
  }

  // 8. Pen-crisp Dented Double Metal Rim at the open mouth (s = 1)
  brush.set("tin_pen", PAL.abyssShadow, 1.45);
  brush.spline(mouthOuter, 0.35);
  brush.set("tin_pen", PAL.abyssShadow, 1.15);
  brush.spline(mouthInner, 0.35);

  // Intense white metallic specular wire highlight along the sunlit half of the dented mouth rim
  let mouthSpec = [];
  for (let th = -110; th <= 110; th += 10) {
    let pO = cylPt(1.0, th, true);
    mouthSpec.push([pO[0] - LX * 0.8, pO[1] - LY * 0.8, 1.2]);
  }
  brush.set("cpencil", PAL.metalSpec, 1.45);
  brush.spline(mouthSpec, 0.35);

  // Dusting of powder grains clinging to the outer rim and dented lip of the tin
  for (let i = 0; i < 22; i++) {
    let th = random(360);
    let pO = cylPt(random(0.88, 1.02), th, true);
    drawMicroGrain(pO[0], pO[1], powderPal[4], powderPal[0], random(1.0, 2.2));
  }
}

// ============================================================================
// 7. LETTERING HELPERS FOR 3D CYLINDER LABELS & CIRCULAR RIMS
// ============================================================================

// Projects stroke glyphs onto a 3D knocked-over cylinder between axial sCenter and angular span [thStart..thEnd]
function drawCylinderLabelText(cylPtFn, textStr, sCenter, thStart, thEnd, sHeight, col, vDotLight) {
  let n = textStr.length;
  if (n === 0) return;

  // Ensure text reads left-to-right from viewer's overhead perspective
  let pStart = cylPtFn(sCenter, thStart, false);
  let pEnd = cylPtFn(sCenter, thEnd, false);
  let flipTheta = (pStart[0] > pEnd[0]);

  for (let idx = 0; idx < n; idx++) {
    let ch = textStr[idx].toUpperCase();
    let strokes = GLYPHS[ch];
    if (!strokes) continue;

    let u0 = (idx + 0.12) / n;
    let u1 = (idx + 0.88) / n;
    let charTh0 = flipTheta ? lerp(thEnd, thStart, u0) : lerp(thStart, thEnd, u0);
    let charTh1 = flipTheta ? lerp(thEnd, thStart, u1) : lerp(thStart, thEnd, u1);

    for (let poly of strokes) {
      let pts = [];
      for (let gp of poly) {
        let gx = gp[0];
        let gy = gp[1];
        let th = lerp(charTh0, charTh1, gx);
        let s = sCenter + (gy - 0.5) * sHeight * (flipTheta ? -1 : 1);
        let wp = cylPtFn(s, th, false);
        pts.push(wp);
      }
      for (let k = 0; k < pts.length - 1; k++) {
        brush.set("tin_pen", col, 1.1);
        brush.line(pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1]);
      }
    }
  }
}

// Projects stroke glyphs along a circular/elliptical arc on an upright tin rim or fallen lid
function drawCurvedTextOnArc(cx, cy, rx, ry, rotAngle, textStr, aStart, aEnd, charHeight, col) {
  let n = textStr.length;
  if (n === 0) return;

  for (let idx = 0; idx < n; idx++) {
    let ch = textStr[idx].toUpperCase();
    let strokes = GLYPHS[ch];
    if (!strokes) continue;

    let u0 = (idx + 0.15) / n;
    let u1 = (idx + 0.85) / n;
    let ang0 = lerp(aStart, aEnd, u0);
    let ang1 = lerp(aStart, aEnd, u1);

    for (let poly of strokes) {
      let pts = [];
      for (let gp of poly) {
        let ang = lerp(ang0, ang1, gp[0]);
        let rOff = (0.5 - gp[1]) * charHeight;
        let px = cx + cos(ang + rotAngle) * (rx + rOff);
        let py = cy + sin(ang + rotAngle) * (ry + rOff);
        pts.push([px, py]);
      }
      for (let k = 0; k < pts.length - 1; k++) {
        brush.set("tin_pen", col, 0.95);
        brush.line(pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1]);
      }
    }
  }
}

// =============================================================================
// ANTIQUE CAST-IRON SEWING MACHINE — PRUSSIAN BLUE CYANOTYPE WATERCOLOUR
// Hyperrealist study in three-quarter view with inverted sun-print tonality,
// reserved paper-white highlights & filigree decals, trailing linen drapery,
// and hand-brushed sensitizer emulsion margins on heavy cotton rag.
// =============================================================================

const PAL = {
  rag:        "#F5F2E8", // Heavy cotton rag base (reserved white)
  ragWarm:    "#EBE6D8", // Warm rag fiber undertone
  ragBright:  "#FAF8F2", // Purest highlight reserve
  ice:        "#DCEAF4", // Pale chemical halation bleed
  frost:      "#B8D3E6", // Very light cyanotype wash
  sky:        "#84B0D0", // Soft cyan-blue transition
  cerulean:   "#4E83B0", // Mid-light Prussian wash
  prussian:   "#24588A", // Classic cyanotype Prussian blue
  deepBlue:   "#123B68", // Deep ferric ferrocyanide blue
  indigo:     "#092446", // Dark solarized shadow-light
  abyss:      "#04142C", // Deepest Prussian blue (where light falls hardest)
  inkBlack:   "#020B1A"  // Ultimate velvet Prussian core
};

// Camera & 3/4 Projection Parameters
const CAM = {
  cx: 625,
  cy: 535,
  scale: 1.44,
  yaw: 28 * Math.PI / 180,
  pitch: 22 * Math.PI / 180,
  focal: 1900
};

function proj(x, y, z) {
  const cy = Math.cos(CAM.yaw), sy = Math.sin(CAM.yaw);
  const cp = Math.cos(CAM.pitch), sp = Math.sin(CAM.pitch);

  const xRot = x * cy - z * sy;
  const zRot = x * sy + z * cy;

  const yRot = y * cp + zRot * sp;
  const zDepth = zRot * cp - y * sp;

  const persp = CAM.focal / (CAM.focal - zDepth);
  return [
    CAM.cx + xRot * persp * CAM.scale,
    CAM.cy + yRot * persp * CAM.scale,
    persp
  ];
}

// Helper to draw a filled watercolor polygon from 2D points
function washPoly(pts, col, alpha, bleed = 0.22, tex = 0.65, border = 0.38) {
  if (pts.length < 3) return;
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0.15);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Helper to draw a 3D polygon projected to 2D as watercolor wash
function washPoly3D(pts3D, col, alpha, bleed = 0.22, tex = 0.65, border = 0.38) {
  const pts2D = pts3D.map(p => proj(p[0], p[1], p[2]));
  washPoly(pts2D, col, alpha, bleed, tex, border);
}

// Helper to draw a 3D spline with current brush
function spline3D(pts3D, curv = 0.5) {
  if (pts3D.length < 2) return;
  const pts2D = pts3D.map(p => {
    const pr = proj(p[0], p[1], p[2]);
    return p.length > 3 ? [pr[0], pr[1], p[3]] : [pr[0], pr[1]];
  });
  if (pts2D.length === 2) {
    brush.line(pts2D[0][0], pts2D[0][1], pts2D[1][0], pts2D[1][1]);
  } else {
    brush.spline(pts2D, curv);
  }
}

function line3D(x1, y1, z1, x2, y2, z2) {
  const a = proj(x1, y1, z1);
  const b = proj(x2, y2, z2);
  brush.line(a[0], a[1], b[0], b[1]);
}

// Rounded rectangle points in 3D horizontal plane (y = const)
function bedRect3D(x1, x2, z1, z2, y, r, stepsPerCorner = 6) {
  const pts = [];
  const corners = [
    { cx: x2 - r, cz: z2 - r, a0: 0, a1: Math.PI / 2 },
    { cx: x1 + r, cz: z2 - r, a0: Math.PI / 2, a1: Math.PI },
    { cx: x1 + r, cz: z1 + r, a0: Math.PI, a1: 3 * Math.PI / 2 },
    { cx: x2 - r, cz: z1 + r, a0: 3 * Math.PI / 2, a1: 2 * Math.PI }
  ];
  for (let c of corners) {
    for (let i = 0; i <= stepsPerCorner; i++) {
      const a = c.a0 + (c.a1 - c.a0) * (i / stepsPerCorner);
      pts.push([c.cx + Math.cos(a) * r, y, c.cz + Math.sin(a) * r]);
    }
  }
  return pts;
}

// Parametric spine & cross-section of the cast-iron pillar and overhanging arm
// t in [0, 1]: 0 = pillar base on bed, 0.42 = pillar shoulder, 0.72 = arm crown, 1.0 = left needle head
function armSpine(t) {
  if (t <= 0.42) {
    const u = t / 0.42; // 0 to 1 up the vertical pillar
    const ease = u * u * (3 - 2 * u);
    const x = 148 - 10 * Math.pow(u, 2.2);
    const y = -205 * u;
    const z = 0;
    // Radius flares at base, narrows at waist, swells at shoulder
    const waist = Math.sin(u * Math.PI);
    const rx = 52 * (1 - 0.35 * u) - 10 * waist + 8 * Math.pow(u, 3);
    const ry = 36;
    const rz = 48 * (1 - 0.32 * u) - 9 * waist + 6 * Math.pow(u, 3);
    // Tangent vector (roughly vertical, curving left at top)
    const tx = -24 * Math.pow(u, 1.5);
    const ty = -205;
    const len = Math.hypot(tx, ty);
    return { x, y, z, rx, ry, rz, tx: tx / len, ty: ty / len };
  } else {
    const u = (t - 0.42) / 0.58; // 0 to 1 from right shoulder across arch to left head
    const x = 138 - 310 * u;
    // Graceful over-arm arch: rises to y = -234 at u = 0.35, then descends to -188 at u = 1.0
    const arch = Math.sin(u * Math.PI) * 32 + Math.sin(u * Math.PI * 0.5) * 14;
    const y = -205 - arch + 28 * Math.pow(u, 1.7);
    const z = 0;
    // Radius tapers gracefully toward the neck, then swells slightly into head collar
    const neck = Math.sin(u * Math.PI);
    const ry = 36 * (1 - 0.25 * neck) + 4 * Math.pow(u, 4);
    const rz = 34 * (1 - 0.22 * neck) + 3 * Math.pow(u, 4);
    const rx = 28;
    const dx = -310;
    const dy = -Math.cos(u * Math.PI) * 32 * Math.PI - Math.cos(u * Math.PI * 0.5) * 7 * Math.PI + 47.6 * Math.pow(u, 0.7);
    const len = Math.hypot(dx, dy);
    return { x, y, z, rx, ry, rz, tx: dx / len, ty: dy / len };
  }
}

// Point on the 3D surface of the arm/pillar given spine parameter t in [0,1] and angle theta (radians)
// theta = 0 is directly in front (+z), theta = PI/2 is top/outer normal, theta = -PI/2 is bottom/inner harp
function armSurfacePt(t, theta) {
  const s = armSpine(t);
  // Normal in the X-Y plane perpendicular to tangent (tx, ty)
  // Since tangent moves up (-y) then left (-x), outward/upward normal is (-ty, tx)
  // Wait: when moving up (tx=0, ty=-1), (ty, -tx) = (-1, 0) [left], (-ty, tx) = (+1, 0) [right].
  // When moving left (tx=-1, ty=0), (-ty, tx) = (0, -1) [up]!
  // So nXY = (-s.ty, s.tx) smoothly rotates from pointing RIGHT (+x) on the pillar to pointing UP (-y) on the arm!
  const nx = -s.ty;
  const ny = s.tx;
  const radXY = (t <= 0.42) ? s.rx : s.ry;
  const c = Math.cos(theta);
  const sn = Math.sin(theta);
  return [
    s.x + nx * radXY * sn,
    s.y + ny * radXY * sn,
    s.z + s.rz * c
  ];
}

// Parametric 3D surface for the trailing fabric
// u in [0, 1] along the length of cloth from behind presser foot (u=0) -> bed edge (u=0.34) -> out of frame (u=1)
// v in [-1, 1] across the width of the cloth
function clothSurfacePt(u, v) {
  const edgeU = 0.33;
  let x, y, z;
  if (u <= edgeU) {
    // On the sewing machine bed
    const t = u / edgeU;
    const width = 46 + 48 * t;
    x = -178 + (v * width) - 18 * t + 12 * Math.sin(t * Math.PI) * v;
    z = -48 + 150 * t + 8 * Math.pow(v, 2) * t;
    // Slight loft over throat plate and subtle ripples on the bed
    const ripple = Math.sin(v * 4.5 + t * 2.0) * (1.5 + 3.5 * t) * (1 - Math.exp(-t * 5));
    y = -1.8 - Math.max(0, ripple);
  } else {
    // Cascading over the front-left beveled edge of the bed and down out of frame
    const s = (u - edgeU) / (1 - edgeU); // 0 to 1 down the waterfall of cloth
    const width = 94 + 135 * Math.pow(s, 1.15);
    // Flows toward lower-left
    const centerShiftX = -196 - 115 * Math.pow(s, 1.1);
    const centerShiftZ = 102 + 28 * Math.sin(s * 1.4) + 65 * s;

    // 5 rich sculptural drapery folds that amplify as s increases
    const foldEnv = Math.pow(s, 0.75);
    const foldWave =
      Math.sin(v * 3.8 - s * 1.6 + 0.3) * 26 * foldEnv +
      Math.cos(v * 7.2 + s * 2.1) * 11 * foldEnv +
      Math.sin(v * 1.8 - s * 0.8) * 16 * foldEnv;

    const foldDepthZ =
      Math.cos(v * 3.8 - s * 1.6 + 0.3) * 24 * foldEnv +
      Math.sin(v * 7.2 + s * 2.1) * 9 * foldEnv;

    x = centerShiftX + v * width + foldWave * 0.45;
    z = centerShiftZ + foldDepthZ + 12 * Math.pow(v, 2);
    // Smooth roll over the bed lip (s near 0) then steep vertical cascade
    const lipRoll = (1 - Math.exp(-s * 9)) * 18;
    y = -1.8 + lipRoll + 430 * Math.pow(s, 1.08) - foldDepthZ * 0.35;
  }
  return [x, y, z];
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1894);
  noiseSeed(1894);
  background(PAL.rag);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Heavy Cotton Rag Paper Texture & Emulsion Margins
  drawCottonRagAndEmulsionField();

  // 2. Trailing Fabric Under-Layers (Part hanging below the bed)
  drawTrailingFabricBase();

  // 3. Cast-Iron Machine Bed (Inverted Prussian Blue Washes, Bevels & Perimeter Decals)
  drawMachineBed();

  // 4. Trailing Fabric Over-Bed & Full Drapery Detail (Inverted Folds, Weave & Seam)
  drawTrailingFabricDetails();

  // 5. Pillar, Overhanging Arched Arm & Left Head (3D Shaded Tubes & Harp Glow)
  drawPillarAndArm();

  // 6. Obsessive Victorian Filigree Decals on Arm & Pillar (Reserved Paper White)
  drawArmAndPillarDecals();

  // 7. Needle Head, Embossed Faceplate, Tension Assembly, Needle Bar & Presser Foot
  drawHeadAndNeedleMechanism();

  // 8. Balance Wheel (Handwheel), Curved Spokes, Bobbin Winder, Stitch Regulator & Belt
  drawBalanceWheelAndRightSide();

  // 9. Wooden Thread Spool & Continuous Tensile Thread Path
  drawSpoolAndThreadPath();

  // 10. Chemical Edge Bleeds, Salt Blooms & Archival Sun-Print Finishing
  drawChemicalFinishingTouches();

  noLoop();
}

// =============================================================================
// 1. COTTON RAG PAPER & HAND-BRUSHED CYANOTYPE EMULSION FIELD
// =============================================================================
function drawCottonRagAndEmulsionField() {
  // Subtle cotton rag fibers across entire sheet
  brush.noField();
  for (let i = 0; i < 160; i++) {
    const x = random(20, 1180);
    const y = random(20, 1180);
    const len = random(25, 110);
    const ang = random(-8, 8) + (random() < 0.5 ? 0 : 90);
    brush.set("2H", i % 2 === 0 ? PAL.ragWarm : PAL.ragBright, random(0.25, 0.55));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Hand-coated sensitizer emulsion field (approx 95..1105 x 95..1105)
  // Painted with wide horizontal & vertical hake-brush passes at the margins
  const leftM = 105, rightM = 1095, topM = 100, botM = 1105;

  // Base pale cyanotype sensitizer wash inside the coated rectangle
  const mainField = [
    [leftM + 10, topM + 10],
    [rightM - 10, topM + 15],
    [rightM - 8, botM - 15],
    [leftM + 12, botM - 10]
  ];
  washPoly(mainField, PAL.frost, 85, 0.38, 0.72, 0.45);

  // Deeper atmospheric Prussian blue clouds in the upper and mid background
  // to make the reserved white spool, thread, and outer rim halos sing
  const bgZones = [
    { cx: 610, cy: 360, rx: 430, ry: 230, col: PAL.cerulean, a: 75, b: 0.42 },
    { cx: 740, cy: 310, rx: 310, ry: 185, col: PAL.prussian, a: 80, b: 0.40 },
    { cx: 430, cy: 380, rx: 280, ry: 190, col: PAL.prussian, a: 70, b: 0.40 },
    { cx: 620, cy: 560, rx: 440, ry: 260, col: PAL.deepBlue, a: 65, b: 0.45 },
    { cx: 830, cy: 680, rx: 250, ry: 190, col: PAL.cerulean, a: 70, b: 0.38 }
  ];
  for (let z of bgZones) {
    const pts = [];
    const n = 20;
    for (let i = 0; i < n; i++) {
      const ang = (i / n) * 360;
      const radMod = 0.88 + 0.24 * noise(i * 0.4, z.cx * 0.01);
      pts.push([
        z.cx + cos(ang) * z.rx * radMod,
        z.cy + sin(ang) * z.ry * radMod
      ]);
    }
    washPoly(pts, z.col, z.a, z.b, 0.75, 0.45);
  }

  // Luminous pale sun-print aura directly inside the harp (under the arm)
  const harpAura = [];
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * 360;
    const p = proj(-10 + Math.cos(a * Math.PI / 180) * 145, -105 + Math.sin(a * Math.PI / 180) * 85, 0);
    harpAura.push([p[0], p[1]]);
  }
  washPoly(harpAura, PAL.rag, 145, 0.42, 0.55, 0.25);
  washPoly(harpAura, PAL.ice, 95, 0.35, 0.5, 0.3);

  // FAINT BRUSH-COATED STREAKS AT THE MARGINS (Revealing hand-applied emulsion)
  // Top and Bottom horizontal hake-brush strokes extending unevenly past leftM..rightM
  const marginStrokesH = [
    // Top edge bristle streaks
    { y: 78, x1: 165, x2: 1020, h: 16, col: PAL.frost, a: 75 },
    { y: 92, x1: 88,  x2: 1118, h: 22, col: PAL.sky, a: 90 },
    { y: 110, x1: 68, x2: 1135, h: 26, col: PAL.cerulean, a: 80 },
    { y: 128, x1: 95, x2: 1108, h: 20, col: PAL.prussian, a: 60 },
    // Bottom edge bristle streaks
    { y: 1082, x1: 82,  x2: 1115, h: 24, col: PAL.cerulean, a: 75 },
    { y: 1102, x1: 64,  x2: 1128, h: 22, col: PAL.sky, a: 85 },
    { y: 1120, x1: 115, x2: 1065, h: 16, col: PAL.frost, a: 75 },
    { y: 1134, x1: 190, x2: 960,  h: 11, col: PAL.ice, a: 70 }
  ];
  for (let s of marginStrokesH) {
    const pts = [];
    for (let x = s.x1; x <= s.x2; x += 45) {
      pts.push([x, s.y - s.h * 0.5 + random(-3, 3)]);
    }
    for (let x = s.x2; x >= s.x1; x -= 45) {
      pts.push([x, s.y + s.h * 0.5 + random(-3, 3)]);
    }
    washPoly(pts, s.col, s.a, 0.25, 0.8, 0.55);
  }

  // Left and Right vertical brush-coated sensitizer streaks
  const marginStrokesV = [
    { x: 76,  y1: 170, y2: 1030, w: 14, col: PAL.frost, a: 70 },
    { x: 92,  y1: 95,  y2: 1110, w: 22, col: PAL.sky, a: 85 },
    { x: 110, y1: 85,  y2: 1118, w: 24, col: PAL.cerulean, a: 75 },
    { x: 1090, y1: 90,  y2: 1105, w: 24, col: PAL.cerulean, a: 75 },
    { x: 1108, y1: 105, y2: 1095, w: 20, col: PAL.sky, a: 85 },
    { x: 1124, y1: 185, y2: 990,  w: 14, col: PAL.frost, a: 65 }
  ];
  for (let s of marginStrokesV) {
    const pts = [];
    for (let y = s.y1; y <= s.y2; y += 45) {
      pts.push([s.x - s.w * 0.5 + random(-3, 3), y]);
    }
    for (let y = s.y2; y >= s.y1; y -= 45) {
      pts.push([s.x + s.w * 0.5 + random(-3, 3), y]);
    }
    washPoly(pts, s.col, s.a, 0.25, 0.8, 0.55);
  }

  // Dry-brush bristle tracks at the ends of the emulsion strokes (top, bottom, left, right)
  const bristleColors = [PAL.sky, PAL.cerulean, PAL.prussian, PAL.frost];
  for (let i = 0; i < 220; i++) {
    const side = i % 4;
    const col = bristleColors[i % bristleColors.length];
    brush.set(i % 3 === 0 ? "charcoal" : "2B", col, random(0.35, 0.95));
    if (side === 0) {
      // Left margin horizontal bristle ends
      const y = random(72, 1132);
      const xStart = random(52, 95) + noise(y * 0.02) * 35;
      const xEnd = xStart + random(35, 110);
      brush.line(xStart, y, xEnd, y + random(-2, 2));
    } else if (side === 1) {
      // Right margin horizontal bristle ends
      const y = random(72, 1132);
      const xEnd = random(1105, 1148) - noise(y * 0.02 + 5) * 35;
      const xStart = xEnd - random(35, 110);
      brush.line(xStart, y + random(-2, 2), xEnd, y);
    } else if (side === 2) {
      // Top margin vertical/horizontal bristle tracks
      const x = random(75, 1125);
      const yStart = random(55, 95) + noise(x * 0.02) * 30;
      const yEnd = yStart + random(30, 95);
      brush.line(x, yStart, x + random(-2, 2), yEnd);
    } else {
      // Bottom margin bristle tracks
      const x = random(75, 1125);
      const yEnd = random(1105, 1152) - noise(x * 0.02 + 9) * 30;
      const yStart = yEnd - random(30, 95);
      brush.line(x + random(-2, 2), yStart, x, yEnd);
    }
  }
}

// =============================================================================
// 2. TRAILING FABRIC BASE (DRAPERY CASCADE BELOW BED)
// =============================================================================
function drawTrailingFabricBase() {
  // Reserve the entire trailing fabric silhouette in crisp cotton-rag white first
  // so it cuts across the lower emulsion field and trails right out of frame!
  const uSteps = 28;
  const silPts = [];
  for (let i = 0; i <= uSteps; i++) {
    const p = clothSurfacePt(i / uSteps, -1.0);
    silPts.push(proj(p[0], p[1], p[2]));
  }
  for (let i = uSteps; i >= 0; i--) {
    const p = clothSurfacePt(i / uSteps, 1.0);
    silPts.push(proj(p[0], p[1], p[2]));
  }
  washPoly(silPts, PAL.rag, 245, 0.18, 0.45, 0.25);
}

// =============================================================================
// 3. CAST-IRON MACHINE BED (THREE-QUARTER VIEW, INVERTED TONALITY & DECALS)
// =============================================================================
function drawMachineBed() {
  const xL = -238, xR = 228, zB = -104, zF = 104, rC = 24;

  // Inverted Sun-Print Contact Halo underneath the bed (y = +48..+64)
  // In a negative/solarized print, the deep cast shadow under the machine glows pale cyan-white
  // while the immediate contact rim has a rich Prussian bleed
  const haloPts = bedRect3D(xL - 16, xR + 18, zB - 12, zF + 18, 52, rC + 8, 5);
  washPoly3D(haloPts, PAL.ice, 160, 0.42, 0.6, 0.3);
  const contactPts = bedRect3D(xL - 4, xR + 6, zB - 2, zF + 6, 46, rC + 2, 5);
  washPoly3D(contactPts, PAL.deepBlue, 150, 0.28, 0.65, 0.4);

  // Lower Cast-Iron Skirt / Moulded Plinth (y = 0 down to y = 44)
  // Front skirt face (z = zF) and Right skirt face (x = xR)
  const skirtFront = [
    [xL + rC, 0, zF], [xR - rC * 0.3, 0, zF],
    [xR - rC * 0.3, 44, zF], [xL + rC, 44, zF]
  ];
  // Underside of skirt is in shadow -> luminous pale cyan-white in inverted feel!
  washPoly3D(skirtFront, PAL.frost, 180, 0.2, 0.55, 0.3);

  const skirtRight = [
    [xR, 0, zF - rC * 0.3], [xR, 0, zB + rC],
    [xR, 44, zB + rC], [xR, 44, zF - rC * 0.3]
  ];
  washPoly3D(skirtRight, PAL.sky, 170, 0.2, 0.55, 0.3);

  // Upper sunlit lip of the bed edge (y = 0..14) gets darkest Prussian blue!
  const lipFront = [
    [xL + 10, 0, zF], [xR, 0, zF - 6],
    [xR, 15, zF - 6], [xL + 10, 15, zF]
  ];
  washPoly3D(lipFront, PAL.abyss, 210, 0.16, 0.6, 0.4);

  const lipRight = [
    [xR, 0, zF - 6], [xR, 0, zB + 12],
    [xR, 15, zB + 12], [xR, 15, zF - 6]
  ];
  washPoly3D(lipRight, PAL.indigo, 200, 0.16, 0.6, 0.4);

  // Bottom flanged foot rim at y = 36..44
  const footFront = [
    [xL + 12, 35, zF + 2], [xR + 2, 35, zF - 4],
    [xR + 2, 44, zF - 4], [xL + 12, 44, zF + 2]
  ];
  washPoly3D(footFront, PAL.prussian, 185, 0.18, 0.6, 0.35);

  // TOP DECK OF THE BED (y = 0)
  // Because light falls directly onto the flat horizontal bed from above,
  // in our tonally inverted cyanotype, the exposed bed surface is the DARKEST PRUSSIAN BLUE!
  const topDeck = bedRect3D(xL, xR, zB, zF, 0, rC, 6);
  washPoly3D(topDeck, PAL.deepBlue, 220, 0.22, 0.68, 0.42);

  const topDeckInner = bedRect3D(xL + 6, xR - 6, zB + 6, zF - 6, 0, rC - 4, 6);
  washPoly3D(topDeckInner, PAL.indigo, 225, 0.18, 0.65, 0.4);

  // Intense solarized Prussian blue where light hits the center-front and right of the bed hardest
  const litBedZone1 = bedRect3D(-120, 210, -85, 92, 0, 14, 4);
  washPoly3D(litBedZone1, PAL.abyss, 215, 0.22, 0.6, 0.35);

  const litBedZone2 = bedRect3D(-60, 150, -55, 78, 0, 10, 4);
  washPoly3D(litBedZone2, PAL.inkBlack, 190, 0.2, 0.55, 0.3);

  // Inverted "Shadow" cast by the overhanging arm onto the middle of the bed:
  // Because the arm blocks the direct overhead light along z in [-28, +18], x in [-130, +120],
  // that sheltered strip on the bed glows with a soft cyan-white chemical bleed!
  const armShadowStrip = [
    [-135, 0, -24], [125, 0, -24],
    [135, 0, 18],  [-135, 0, 18]
  ];
  washPoly3D(armShadowStrip, PAL.sky, 110, 0.35, 0.65, 0.3);
  const armShadowCore = [
    [-115, 0, -12], [105, 0, -12],
    [110, 0, 8],    [-115, 0, 8]
  ];
  washPoly3D(armShadowCore, PAL.frost, 95, 0.35, 0.6, 0.25);

  // Reserved Paper-White Specular Rim around the beveled edge of the bed
  brush.set("2H", PAL.rag, 1.15);
  spline3D(topDeck.concat([topDeck[0]]), 0.2);
  brush.set("cpencil", PAL.ice, 0.8);
  spline3D(topDeckInner.concat([topDeckInner[0]]), 0.2);

  // Cove moulding highlight lines along front and right skirts
  brush.set("2H", PAL.rag, 1.0);
  line3D(xL + 16, 16, zF + 1, xR - 8, 16, zF + 1);
  line3D(xR + 1, 16, zF - 8, xR + 1, 16, zB + 16);
  brush.set("pen", PAL.frost, 0.65);
  line3D(xL + 16, 34, zF + 2, xR - 6, 34, zF + 2);
  line3D(xR + 2, 34, zF - 6, xR + 2, 34, zB + 16);
  brush.set("rotring", PAL.abyss, 0.85);
  line3D(xL + 14, 44, zF + 2, xR, 44, zF + 2);
  line3D(xR + 2, 44, zF - 4, xR + 2, 44, zB + 14);

  // THROAT PLATE & SLIDE PLATE (Left side of bed, around x = -178, z = 0)
  // Rendered with obsessive accuracy in high-contrast reserved white & Prussian blue
  const tpPts = [];
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    tpPts.push([-178 + Math.cos(a) * 32, -0.5, Math.sin(a) * 32]);
  }
  washPoly3D(tpPts, PAL.rag, 210, 0.14, 0.4, 0.3);
  const tpInner = [];
  for (let i = 0; i < 20; i++) {
    const a = (i / 20) * Math.PI * 2;
    tpInner.push([-178 + Math.cos(a) * 25, -0.6, Math.sin(a) * 25]);
  }
  washPoly3D(tpInner, PAL.prussian, 165, 0.15, 0.5, 0.35);

  // Rectangular Slide Plate extending forward from the throat plate
  const slidePlate = [
    [-198, -0.5, 18], [-158, -0.5, 18],
    [-158, -0.5, 84], [-198, -0.5, 84]
  ];
  washPoly3D(slidePlate, PAL.frost, 190, 0.14, 0.45, 0.3);

  brush.set("rotring", PAL.rag, 0.9);
  spline3D(tpPts.concat([tpPts[0]]), 0.3);
  spline3D(slidePlate.concat([slidePlate[0]]), 0.1);

  // Feed dogs & needle hole in throat plate
  brush.set("rotring", PAL.abyss, 1.1);
  line3D(-186, -0.8, -10, -170, -0.8, -10);
  line3D(-186, -0.8, -4,  -170, -0.8, -4);
  line3D(-186, -0.8, 5,   -170, -0.8, 5);
  line3D(-186, -0.8, 11,  -170, -0.8, 11);

  //OBSESSIVE VICTORIAN PERIMETER DECALS ON THE BED
  drawBedDecals(xL, xR, zB, zF);
}

function drawBedDecals(xL, xR, zB, zF) {
  // Double-fillet border rules around the bed perimeter in reserved paper white
  const m1 = 16, m2 = 22, m3 = 36;
  const r1 = bedRect3D(xL + m1, xR - m1, zB + m1, zF - m1, -0.3, 14, 4);
  const r2 = bedRect3D(xL + m2, xR - m2, zB + m2, zF - m2, -0.3, 11, 4);
  const r3 = bedRect3D(xL + m3, xR - m3, zB + m3, zF - m3, -0.3, 8, 4);

  brush.set("rotring", PAL.rag, 0.85);
  spline3D(r1.concat([r1[0]]), 0.15);
  brush.set("rotring", PAL.ice, 0.55);
  spline3D(r2.concat([r2[0]]), 0.15);
  brush.set("rotring", PAL.rag, 0.65);
  spline3D(r3.concat([r3[0]]), 0.15);

  // Scrolling Victorian vine & acanthus motif along the front border (z between zF-35 and zF-18)
  // and back border (z between zB+18 and zB+35) and right border (x between xR-35 and xR-18)
  const zFrontMid = zF - 26;
  const zBackMid = zB + 26;
  const xRightMid = xR - 26;

  // Front border scrolling arabesque wave (from x = -90 to x = +195)
  for (let x = -85; x <= 185; x += 22) {
    const wavePts = [];
    for (let s = 0; s <= 1; s += 0.2) {
      const xx = x + s * 22;
      const zz = zFrontMid + Math.sin(s * Math.PI * 2) * 5.5;
      wavePts.push([xx, -0.4, zz]);
    }
    brush.set("pen", PAL.rag, 0.85);
    spline3D(wavePts, 0.5);

    // Companion leaf curls & florets in reserved white
    const curl1 = [
      [x + 5, -0.4, zFrontMid + 2],
      [x + 9, -0.4, zFrontMid + 6.5],
      [x + 13, -0.4, zFrontMid + 3.5],
      [x + 10, -0.4, zFrontMid + 1]
    ];
    const curl2 = [
      [x + 16, -0.4, zFrontMid - 2],
      [x + 20, -0.4, zFrontMid - 6.5],
      [x + 23, -0.4, zFrontMid - 3.5],
      [x + 19, -0.4, zFrontMid - 1]
    ];
    brush.set("rotring", PAL.ragBright, 0.7);
    spline3D(curl1, 0.6);
    spline3D(curl2, 0.6);

    // Tiny trefoil berry dots
    const d1 = proj(x + 11, -0.4, zFrontMid - 5);
    const d2 = proj(x + 21, -0.4, zFrontMid + 5);
    brush.set("rotring", PAL.rag, 1.1);
    brush.circle(d1[0], d1[1], 1.6);
    brush.circle(d2[0], d2[1], 1.6);
  }

  // Back border scrolling vine
  for (let x = -195; x <= 185; x += 24) {
    const wavePts = [];
    for (let s = 0; s <= 1; s += 0.25) {
      wavePts.push([x + s * 24, -0.4, zBackMid + Math.sin(s * Math.PI * 2) * 4.8]);
    }
    brush.set("rotring", PAL.ice, 0.65);
    spline3D(wavePts, 0.5);
    brush.set("rotring", PAL.rag, 0.55);
    line3D(x + 6, -0.4, zBackMid - 3, x + 12, -0.4, zBackMid + 4);
    line3D(x + 18, -0.4, zBackMid + 3, x + 22, -0.4, zBackMid - 4);
  }

  // Right border scrolling vine (behind pillar/wheel)
  for (let z = -68; z <= 68; z += 22) {
    const wavePts = [];
    for (let s = 0; s <= 1; s += 0.25) {
      wavePts.push([xRightMid + Math.sin(s * Math.PI * 2) * 5.0, -0.4, z + s * 22]);
    }
    brush.set("pen", PAL.rag, 0.75);
    spline3D(wavePts, 0.5);
  }

  // Ornate Corner Medallions (Sphinx / Victorian fan cartouches at the 4 corners)
  const corners = [
    [xR - 28, zF - 28],
    [xR - 28, zB + 28],
    [xL + 28, zB + 28]
  ];
  for (let [cx, cz] of corners) {
    for (let r = 4; r <= 12; r += 4) {
      const ring = [];
      for (let i = 0; i <= 12; i++) {
        const a = (i / 12) * Math.PI * 2;
        ring.push([cx + Math.cos(a) * r, -0.4, cz + Math.sin(a) * r]);
      }
      brush.set("rotring", r === 8 ? PAL.ragBright : PAL.ice, 0.75);
      spline3D(ring, 0.3);
    }
    // Diagonal fan petals
    for (let a = 0; a < 8; a++) {
      const ang = (a / 8) * Math.PI * 2;
      brush.set("rotring", PAL.rag, 0.65);
      line3D(cx + Math.cos(ang) * 3, -0.4, cz + Math.sin(ang) * 3,
             cx + Math.cos(ang) * 14, -0.4, cz + Math.sin(ang) * 14);
    }
  }

  // Central Bed Cartouche Decal (in front of the pillar, x in [-45, +75], z in [+15, +58])
  const cX = 15, cZ = 38;
  for (let k = 0; k < 2; k++) {
    const rx = k === 0 ? 52 : 44;
    const rz = k === 0 ? 18 : 13;
    const oval = [];
    for (let i = 0; i <= 24; i++) {
      const a = (i / 24) * Math.PI * 2;
      oval.push([cX + Math.cos(a) * rx, -0.4, cZ + Math.sin(a) * rz * (1 + 0.25 * Math.cos(a * 2))]);
    }
    brush.set("pen", k === 0 ? PAL.rag : PAL.frost, k === 0 ? 0.85 : 0.6);
    spline3D(oval, 0.4);
  }
  // Symmetrical acanthus scrollwork inside the bed cartouche
  for (let dir of [-1, 1]) {
    for (let loop = 1; loop <= 3; loop++) {
      const sPts = [];
      for (let t = 0; t <= 1; t += 0.15) {
        const ang = t * Math.PI * 2.4;
        const rad = (14 - loop * 3) * (1 - t * 0.45);
        sPts.push([
          cX + dir * (10 + loop * 9 + Math.cos(ang) * rad),
          -0.4,
          cZ + Math.sin(ang) * rad * 0.55
        ]);
      }
      brush.set("rotring", PAL.ragBright, 0.7);
      spline3D(sPts, 0.5);
    }
  }
}

// =============================================================================
// 4. TRAILING FABRIC OVER-BED & FULL DRAPERY DETAIL
// =============================================================================
function drawTrailingFabricDetails() {
  // Reserve the portion of the cloth lying ON the bed (u in [0, 0.36])
  const bedClothPts = [];
  for (let i = 0; i <= 14; i++) {
    const p = clothSurfacePt((i / 14) * 0.38, -1.0);
    bedClothPts.push(proj(p[0], p[1], p[2]));
  }
  for (let i = 14; i >= 0; i--) {
    const p = clothSurfacePt((i / 14) * 0.38, 1.0);
    bedClothPts.push(proj(p[0], p[1], p[2]));
  }
  washPoly(bedClothPts, PAL.rag, 240, 0.16, 0.45, 0.25);

  // Now render the TONALLY INVERTED FOLD WASHES along the cascading drapery:
  // Where light hits the high crests of the folds hardest -> Deepest Prussian Blue!
  // Where the cloth recesses into deep shadow valleys or selvedge edges -> Reserved Paper White!
  // Let's trace 5 main longitudinal crest ribbons along v in [-0.75, -0.38, 0.0, 0.38, 0.72]
  const foldRibbons = [
    { vMid: -0.74, vHalf: 0.13, u0: 0.08, u1: 0.98, col1: PAL.prussian, col2: PAL.abyss },
    { vMid: -0.36, vHalf: 0.14, u0: 0.04, u1: 1.00, col1: PAL.deepBlue, col2: PAL.inkBlack },
    { vMid:  0.04, vHalf: 0.15, u0: 0.02, u1: 1.00, col1: PAL.prussian, col2: PAL.abyss },
    { vMid:  0.44, vHalf: 0.13, u0: 0.10, u1: 0.98, col1: PAL.cerulean, col2: PAL.indigo },
    { vMid:  0.78, vHalf: 0.11, u0: 0.18, u1: 0.95, col1: PAL.sky,      col2: PAL.deepBlue }
  ];

  for (let f of foldRibbons) {
    // Soft outer chemical bleed of the fold
    const outerPts = [];
    for (let u = f.u0; u <= f.u1; u += 0.06) {
      const p = clothSurfacePt(u, f.vMid - f.vHalf * (0.5 + 0.6 * u));
      outerPts.push(proj(p[0], p[1], p[2]));
    }
    for (let u = f.u1; u >= f.u0; u -= 0.06) {
      const p = clothSurfacePt(u, f.vMid + f.vHalf * (0.5 + 0.6 * u));
      outerPts.push(proj(p[0], p[1], p[2]));
    }
    washPoly(outerPts, PAL.sky, 95, 0.32, 0.68, 0.35);

    // Mid Prussian wash along the sunlit slope of the fold
    const midPts = [];
    for (let u = f.u0 + 0.03; u <= f.u1; u += 0.06) {
      const p = clothSurfacePt(u, f.vMid - f.vHalf * 0.55 * (0.4 + 0.6 * u));
      midPts.push(proj(p[0], p[1], p[2]));
    }
    for (let u = f.u1; u >= f.u0 + 0.03; u -= 0.06) {
      const p = clothSurfacePt(u, f.vMid + f.vHalf * 0.35 * (0.4 + 0.6 * u));
      midPts.push(proj(p[0], p[1], p[2]));
    }
    washPoly(midPts, f.col1, 145, 0.25, 0.65, 0.4);

    // Intense dark Prussian core right on the sunlit crest where light hits hardest
    const corePts = [];
    for (let u = f.u0 + 0.12; u <= f.u1 - 0.02; u += 0.06) {
      const p = clothSurfacePt(u, f.vMid - f.vHalf * 0.28 * u);
      corePts.push(proj(p[0], p[1], p[2]));
    }
    for (let u = f.u1 - 0.02; u >= f.u0 + 0.12; u -= 0.06) {
      const p = clothSurfacePt(u, f.vMid + f.vHalf * 0.12 * u);
      corePts.push(proj(p[0], p[1], p[2]));
    }
    washPoly(corePts, f.col2, 185, 0.2, 0.6, 0.42);
  }

  // High-exposure Prussian blue band right where the cloth bends over the front-left bed lip (u in [0.24, 0.42])
  const lipBendPts = [];
  for (let v = -0.95; v <= 0.95; v += 0.15) {
    lipBendPts.push(clothSurfacePt(0.24, v));
  }
  for (let v = 0.95; v >= -0.95; v -= 0.15) {
    lipBendPts.push(clothSurfacePt(0.40, v));
  }
  washPoly3D(lipBendPts, PAL.indigo, 135, 0.3, 0.65, 0.35);

  // Obsessive Linen Warp & Weft Contour Lines across the cloth surface
  // Longitudinal warp lines (following u)
  for (let v = -0.96; v <= 0.96; v += 0.04) {
    const warpPts = [];
    for (let u = 0; u <= 1.0; u += 0.05) {
      warpPts.push(clothSurfacePt(u, v));
    }
    // Alternate between reserved white lines in the dark ridges and fine Prussian lines in the light valleys
    const nearCrest = Math.abs(Math.sin((v + 0.74) * 8.2)) < 0.45;
    if (nearCrest) {
      brush.set("2H", PAL.rag, 0.48);
    } else {
      brush.set("2H", PAL.prussian, 0.42);
    }
    spline3D(warpPts, 0.45);
  }

  // Transverse weft contour lines (following v across the folds, showing 3D cloth topography)
  for (let u = 0.02; u <= 0.98; u += 0.032) {
    const weftPts = [];
    for (let v = -0.98; v <= 0.98; v += 0.08) {
      weftPts.push(clothSurfacePt(u, v));
    }
    brush.set("2H", u > 0.28 && u < 0.42 ? PAL.ice : PAL.cerulean, 0.38);
    spline3D(weftPts, 0.5);
  }

  // Crisp Reserved Paper-White Selvedge Edges & Frayed Fringe Threads on Left and Right Cloth Borders
  for (let side of [-1.0, 1.0]) {
    const edgePts = [];
    for (let u = 0; u <= 1.0; u += 0.04) {
      edgePts.push(clothSurfacePt(u, side));
    }
    brush.set("pen", PAL.ragBright, 1.15);
    spline3D(edgePts, 0.45);
    brush.set("rotring", PAL.deepBlue, 0.65);
    const innerEdge = [];
    for (let u = 0; u <= 1.0; u += 0.04) {
      innerEdge.push(clothSurfacePt(u, side * 0.95));
    }
    spline3D(innerEdge, 0.45);
  }

  // Freshly Sewn Lockstitch Seam Line trailing from the needle (u = 0.12) backward and forward along v = 0.02
  for (let u = 0.0; u <= 0.92; u += 0.014) {
    const p1 = clothSurfacePt(u, 0.02);
    const p2 = clothSurfacePt(u + 0.008, 0.02);
    // Dark Prussian seam groove + bright reserved paper-white thread stitch!
    brush.set("rotring", PAL.abyss, 0.95);
    line3D(p1[0] + 1.2, p1[1], p1[2], p2[0] + 1.2, p2[1], p2[2]);
    brush.set("rotring", PAL.ragBright, 0.95);
    line3D(p1[0], p1[1] - 0.3, p1[2], p2[0], p2[1] - 0.3, p2[2]);
  }
}

// =============================================================================
// 5. PILLAR, OVERHANGING ARCHED ARM & LEFT HEAD (3D TUBULAR VOLUMES)
// =============================================================================
function drawPillarAndArm() {
  const tSteps = 32;

  // Step A: Reserve the full silhouette of the Pillar & Arm in Cotton Rag White
  // so no background wash muddies the crisp reserved undersides and decals!
  const armOuterSil = [];
  for (let i = 0; i <= tSteps; i++) {
    armOuterSil.push(armSurfacePt(i / tSteps, Math.PI / 2)); // Top/outer contour
  }
  for (let i = tSteps; i >= 0; i--) {
    armOuterSil.push(armSurfacePt(i / tSteps, -Math.PI / 2)); // Bottom/inner harp contour
  }
  washPoly3D(armOuterSil, PAL.rag, 250, 0.16, 0.45, 0.25);

  // Also reserve the Pillar Base Flange on the bed (around x = 148, y = 0, z = 0)
  const baseFlange = [];
  for (let i = 0; i <= 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    baseFlange.push([148 + Math.cos(a) * 58, -1, Math.sin(a) * 54]);
  }
  washPoly3D(baseFlange, PAL.rag, 235, 0.18, 0.45, 0.25);

  // Step B: Paint longitudinal 3D bands along the Pillar & Arm following TONAL INVERSION:
  // theta in [-PI/2, +PI/2]:
  // - Near theta = +PI/2 (Top of arm & right/front-top shoulder of pillar where light falls hardest):
  //   Deepest Velvet Prussian Blue (PAL.abyss & PAL.inkBlack)!
  // - Near theta = 0 (Front face where the ornate decals sit):
  //   Rich Prussian Blue (PAL.indigo & PAL.deepBlue) so the reserved paper-white decals pop with high contrast!
  // - Near theta = -PI/2 (Underside of the arched harp arm & shadowed base recess):
  //   Reserved Paper White (PAL.rag) bleeding softly through PAL.ice and PAL.sky!
  const longitudinalBands = [
    { th0: -1.35, th1: -0.75, col: PAL.ice,      alpha: 130, bleed: 0.30 },
    { th0: -0.95, th1: -0.35, col: PAL.sky,      alpha: 150, bleed: 0.28 },
    { th0: -0.55, th1:  0.15, col: PAL.cerulean, alpha: 175, bleed: 0.25 },
    { th0: -0.25, th1:  0.55, col: PAL.prussian, alpha: 200, bleed: 0.22 },
    { th0:  0.00, th1:  0.85, col: PAL.deepBlue, alpha: 215, bleed: 0.20 },
    { th0:  0.22, th1:  1.18, col: PAL.indigo,   alpha: 225, bleed: 0.18 },
    { th0:  0.48, th1:  1.42, col: PAL.abyss,    alpha: 235, bleed: 0.16 },
    { th0:  0.72, th1:  1.32, col: PAL.inkBlack, alpha: 210, bleed: 0.14 }
  ];

  for (let b of longitudinalBands) {
    const bandPts = [];
    for (let i = 0; i <= tSteps; i++) {
      bandPts.push(armSurfacePt(i / tSteps, b.th1));
    }
    for (let i = tSteps; i >= 0; i--) {
      bandPts.push(armSurfacePt(i / tSteps, b.th0));
    }
    washPoly3D(bandPts, b.col, b.alpha, b.bleed, 0.65, 0.38);
  }

  // Step C: Reserved Paper-White Specular Highlight Ribbon running right along the upper-front ridge
  // ("Highlights are reserved paper white, like a sun print")
  const specRibbon = [];
  for (let i = 1; i < tSteps; i++) {
    specRibbon.push(armSurfacePt(i / tSteps, 0.92));
  }
  for (let i = tSteps - 1; i >= 1; i--) {
    specRibbon.push(armSurfacePt(i / tSteps, 0.78));
  }
  washPoly3D(specRibbon, PAL.rag, 235, 0.14, 0.35, 0.2);

  // Crisp reserved white lines along the specular ribbon and the glowing underside of the harp arch
  const specLine1 = [], specLine2 = [], harpRim = [], topContour = [];
  for (let i = 0; i <= tSteps; i++) {
    const t = i / tSteps;
    specLine1.push(armSurfacePt(t, 0.85));
    specLine2.push(armSurfacePt(t, 0.80));
    harpRim.push(armSurfacePt(t, -Math.PI / 2));
    topContour.push(armSurfacePt(t, Math.PI / 2));
  }
  brush.set("pen", PAL.ragBright, 1.3);
  spline3D(specLine1, 0.5);
  brush.set("2H", PAL.ice, 0.9);
  spline3D(specLine2, 0.5);

  // Glowing white underside contour of the harp arch
  brush.set("pen", PAL.ragBright, 1.45);
  spline3D(harpRim, 0.5);
  brush.set("rotring", PAL.prussian, 0.75);
  spline3D(topContour, 0.5);

  // Step D: Fine 3D Cross-Contour Cast-Iron Form Hatching over the Pillar & Arm
  for (let i = 1; i < tSteps; i++) {
    const t = i / tSteps;
    const ringPts = [];
    for (let k = 0; k <= 12; k++) {
      const th = -Math.PI * 0.48 + (k / 12) * Math.PI * 0.96;
      ringPts.push(armSurfacePt(t, th));
    }
    brush.set("2H", i % 2 === 0 ? PAL.deepBlue : PAL.sky, 0.42);
    spline3D(ringPts, 0.5);
  }

  // Moulded Cast-Iron Pillar Base Collar on the Bed
  for (let ring = 0; ring < 3; ring++) {
    const rAdd = ring * 4;
    const yy = -2 - ring * 5;
    const collar = [];
    for (let i = 0; i <= 20; i++) {
      const a = -0.3 + (i / 20) * (Math.PI + 0.6);
      collar.push([148 + Math.cos(a) * (54 + rAdd), yy, Math.sin(a) * (50 + rAdd)]);
    }
    brush.set("pen", ring === 1 ? PAL.ragBright : PAL.abyss, 1.0);
    spline3D(collar, 0.4);
  }

  // Circular Inspection Boss / Medallion Badge on the upper-front pillar (t = 0.34, theta = 0)
  const badgeCenter = armSurfacePt(0.33, 0.05);
  const badgeRim = [];
  for (let i = 0; i <= 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    badgeRim.push([
      badgeCenter[0] + Math.cos(a) * 12,
      badgeCenter[1] + Math.sin(a) * 14,
      badgeCenter[2] + 4
    ]);
  }
  washPoly3D(badgeRim, PAL.rag, 225, 0.12, 0.4, 0.3);
  brush.set("rotring", PAL.abyss, 0.85);
  spline3D(badgeRim, 0.4);
  const bc2D = proj(badgeCenter[0], badgeCenter[1], badgeCenter[2] + 4);
  brush.set("rotring", PAL.prussian, 0.7);
  brush.circle(bc2D[0], bc2D[1], 9);
}

// =============================================================================
// 6. OBSESSIVE VICTORIAN FILIGREE DECALS ON THE ARM & PILLAR
// =============================================================================
function drawArmAndPillarDecals() {
  // All decals are mapped directly onto armSurfacePt(t, theta) so they wrap in true 3D!

  // 1. Framing Double-Fillet Cartouche around the horizontal arm (t in [0.46, 0.94], theta in [-0.42, +0.48])
  for (let pass = 0; pass < 2; pass++) {
    const dt = pass * 0.015;
    const dth = pass * 0.05;
    const topFillet = [], botFillet = [];
    for (let t = 0.46 + dt; t <= 0.94 - dt; t += 0.025) {
      topFillet.push(armSurfacePt(t, 0.48 - dth));
      botFillet.push(armSurfacePt(t, -0.40 + dth));
    }
    brush.set("rotring", pass === 0 ? PAL.ragBright : PAL.ice, pass === 0 ? 0.9 : 0.6);
    spline3D(topFillet, 0.4);
    spline3D(botFillet, 0.4);
  }

  // 2. Central Arm Scrollwork & Oval Medallion (t in [0.60, 0.82], theta around 0.05)
  const medPts = [], medInner = [];
  for (let i = 0; i <= 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    const t = 0.71 + Math.cos(a) * 0.095;
    const th = 0.06 + Math.sin(a) * 0.24;
    medPts.push(armSurfacePt(t, th));
    medInner.push(armSurfacePt(0.71 + Math.cos(a) * 0.08, 0.06 + Math.sin(a) * 0.19));
  }
  // Soft pale chemical halo behind the central arm decal
  washPoly3D(medPts, PAL.ice, 130, 0.2, 0.5, 0.25);

  brush.set("pen", PAL.ragBright, 1.05);
  spline3D(medPts, 0.4);
  brush.set("rotring", PAL.rag, 0.75);
  spline3D(medInner, 0.4);

  // Faux Victorian Serif Lettering / Arabesque inside the central arm medallion
  // (7 crisp vertical/arched glyph strokes in reserved white)
  for (let k = -3; k <= 3; k++) {
    const tChar = 0.71 + k * 0.018;
    const pTop = armSurfacePt(tChar, 0.14);
    const pBot = armSurfacePt(tChar, -0.02);
    const pMid = armSurfacePt(tChar + 0.006, 0.06);
    brush.set("rotring", PAL.ragBright, 0.95);
    line3D(pTop[0], pTop[1], pTop[2], pBot[0], pBot[1], pBot[2]);
    line3D(pTop[0] - 2, pTop[1], pTop[2], pTop[0] + 2, pTop[1], pTop[2]);
    line3D(pBot[0] - 2, pBot[1], pBot[2], pBot[0] + 2, pBot[1], pBot[2]);
    if (k % 2 === 0) {
      line3D(pTop[0], pTop[1], pTop[2], pMid[0], pMid[1], pMid[2]);
    }
  }

  // 3. Symmetrical Acanthus Spirals flanking the central arm medallion (t in [0.47..0.61] and [0.81..0.94])
  const scrollZones = [
    { tCenter: 0.53, dir: -1 },
    { tCenter: 0.57, dir:  1 },
    { tCenter: 0.85, dir: -1 },
    { tCenter: 0.89, dir:  1 }
  ];
  for (let sz of scrollZones) {
    for (let branch = -1; branch <= 1; branch += 2) {
      const spiral = [];
      for (let s = 0; s <= 1; s += 0.1) {
        const ang = s * Math.PI * 2.6 * sz.dir;
        const rT = 0.038 * (1 - s * 0.65);
        const rTh = 0.26 * (1 - s * 0.65);
        const t = sz.tCenter + Math.cos(ang) * rT;
        const th = 0.05 + branch * 0.08 + Math.sin(ang) * rTh * branch;
        spiral.push(armSurfacePt(t, th));
      }
      brush.set("pen", PAL.ragBright, 0.95);
      spline3D(spiral, 0.55);

      // Tiny inner Prussian detail etching inside the white acanthus leaf
      brush.set("rotring", PAL.abyss, 0.5);
      spline3D(spiral.slice(0, 6), 0.5);
    }
    // Rosette blossom at scroll center
    const rc = proj(...armSurfacePt(sz.tCenter, 0.05));
    brush.set("rotring", PAL.ragBright, 1.15);
    brush.circle(rc[0], rc[1], 2.5);
  }

  // 4. Vertical Candelabrum & Winged Sphinx Filigree rising up the Pillar (t in [0.05, 0.40])
  for (let pass = 0; pass < 2; pass++) {
    const dth = pass * 0.05;
    const leftRule = [], rightRule = [];
    for (let t = 0.05; t <= 0.39; t += 0.025) {
      leftRule.push(armSurfacePt(t, -0.36 + dth));
      rightRule.push(armSurfacePt(t, 0.42 - dth));
    }
    brush.set("rotring", pass === 0 ? PAL.ragBright : PAL.ice, 0.8);
    spline3D(leftRule, 0.4);
    spline3D(rightRule, 0.4);
  }

  // Interlocking figure-eight botanical scrolls up the pillar spine
  for (let level = 0; level < 5; level++) {
    const tBase = 0.07 + level * 0.052;
    for (let side of [-1, 1]) {
      const leafPts = [];
      for (let s = 0; s <= 1; s += 0.12) {
        const a = s * Math.PI * 2.1;
        const t = tBase + s * 0.048;
        const th = 0.03 + side * Math.sin(a) * 0.28;
        leafPts.push(armSurfacePt(t, th));
      }
      brush.set("pen", PAL.ragBright, 0.9);
      spline3D(leafPts, 0.55);

      // Feathered calyx ticks
      const pMid = armSurfacePt(tBase + 0.024, 0.03 + side * 0.22);
      const pTip = armSurfacePt(tBase + 0.036, 0.03 + side * 0.34);
      brush.set("rotring", PAL.rag, 0.75);
      line3D(pMid[0], pMid[1], pMid[2], pTip[0], pTip[1], pTip[2]);
    }
  }
}

// =============================================================================
// 7. LEFT HEAD, EMBOSSED FACEPLATE, TENSION ASSEMBLY, NEEDLE BAR & PRESSER FOOT
// =============================================================================
function drawHeadAndNeedleMechanism() {
  const xH1 = -164, xH2 = -196;
  const yHTop = -218, yHBot = -82;
  const zHB = -28, zHF = 28;

  // Reserve the Head block in cotton rag white first
  const headFront = [
    [xH2, yHTop, zHF], [xH1, yHTop, zHF],
    [xH1, yHBot, zHF], [xH2, yHBot, zHF]
  ];
  const headLeft = [
    [xH2, yHTop, zHB], [xH2, yHTop, zHF],
    [xH2, yHBot, zHF], [xH2, yHBot, zHB]
  ];
  const headTop = [
    [xH2, yHTop, zHB], [xH1, yHTop, zHB],
    [xH1, yHTop, zHF], [xH2, yHTop, zHF]
  ];
  washPoly3D(headFront, PAL.rag, 240, 0.14, 0.4, 0.25);
  washPoly3D(headLeft, PAL.rag, 240, 0.14, 0.4, 0.25);
  washPoly3D(headTop, PAL.rag, 240, 0.14, 0.4, 0.25);

  // Shade the Head with inverted tonality:
  // Top cap & upper front receive direct light -> Deepest Prussian blue!
  washPoly3D(headTop, PAL.abyss, 225, 0.15, 0.55, 0.35);
  const headFrontUpper = [
    [xH2 + 3, yHTop + 3, zHF], [xH1 - 3, yHTop + 3, zHF],
    [xH1 - 3, -125, zHF],      [xH2 + 3, -125, zHF]
  ];
  washPoly3D(headFrontUpper, PAL.indigo, 215, 0.16, 0.6, 0.35);
  const headFrontLower = [
    [xH2 + 3, -125, zHF], [xH1 - 3, -125, zHF],
    [xH1 - 3, yHBot - 4, zHF], [xH2 + 3, yHBot - 4, zHF]
  ];
  washPoly3D(headFrontLower, PAL.prussian, 185, 0.18, 0.6, 0.35);

  // Ornate Embossed Nickel Faceplate on the left side (x = xH2)
  // Painted in alternating bands of deep Prussian blue and crisp reserved paper white
  washPoly3D(headLeft, PAL.deepBlue, 195, 0.16, 0.55, 0.35);
  brush.set("pen", PAL.ragBright, 1.15);
  spline3D(headLeft.concat([headLeft[0]]), 0.1);
  spline3D(headFront.concat([headFront[0]]), 0.1);

  // Embossed scrolling relief lines on the left faceplate
  for (let yy = yHTop + 12; yy <= yHBot - 12; yy += 14) {
    const wave = [];
    for (let s = 0; s <= 1; s += 0.25) {
      const zz = zHB + 6 + s * (zHF - zHB - 12);
      wave.push([xH2 - 0.5, yy + Math.sin(s * Math.PI * 2) * 4, zz]);
    }
    brush.set("rotring", PAL.ragBright, 0.8);
    spline3D(wave, 0.5);
  }

  // Front Head Filigree Frame
  const hfInset = [
    [xH2 + 6, yHTop + 8, zHF + 0.5], [xH1 - 6, yHTop + 8, zHF + 0.5],
    [xH1 - 6, yHBot - 8, zHF + 0.5], [xH2 + 6, yHBot - 8, zHF + 0.5]
  ];
  brush.set("rotring", PAL.ragBright, 0.85);
  spline3D(hfInset.concat([hfInset[0]]), 0.1);

  // UPPER TENSION ASSEMBLY on the front of the head (x = -178, y = -148, z = zHF..zHF+24)
  for (let d = 0; d <= 18; d += 4) {
    const r = d < 8 ? 13 : (d < 14 ? 8 : 5);
    const disc = [];
    for (let i = 0; i <= 16; i++) {
      const a = (i / 16) * Math.PI * 2;
      disc.push([-178 + Math.cos(a) * r, -148 + Math.sin(a) * r, zHF + 2 + d]);
    }
    if (d === 0) washPoly3D(disc, PAL.rag, 230, 0.12, 0.4, 0.25);
    if (d === 4) washPoly3D(disc, PAL.abyss, 210, 0.12, 0.4, 0.25);
    brush.set("rotring", d % 8 === 0 ? PAL.ragBright : PAL.abyss, 0.9);
    spline3D(disc, 0.35);
  }

  // THREAD TAKE-UP LEVER rising from the upper front of the head
  const takeUpPts = [
    [-175, -188, zHF + 2],
    [-172, -212, zHF + 14],
    [-168, -228, zHF + 22]
  ];
  brush.set("pen", PAL.abyss, 2.2);
  spline3D(takeUpPts, 0.4);
  brush.set("rotring", PAL.ragBright, 1.15);
  spline3D(takeUpPts, 0.4);
  const eye2D = proj(-168, -228, zHF + 22);
  brush.set("rotring", PAL.ragBright, 1.1);
  brush.circle(eye2D[0], eye2D[1], 3.2);

  // TOP NEEDLE-BAR CAP & BUSHING protruding above the head (y = -218..-268)
  for (let xBar of [-184, -172]) {
    const hTop = xBar === -184 ? -268 : -244;
    brush.set("pen", PAL.abyss, 2.4);
    line3D(xBar, yHTop, 0, xBar, hTop, 0);
    brush.set("rotring", PAL.ragBright, 1.1);
    line3D(xBar - 2, yHTop, 2, xBar - 2, hTop, 2);
    const cap = proj(xBar, hTop, 0);
    brush.set("rotring", PAL.ragBright, 1.0);
    brush.circle(cap[0], cap[1], 4);
  }

  // LOWER NEEDLE BAR, PRESSER BAR, NEEDLE CLAMP, NEEDLE & PRESSER FOOT (y = -82 down to y = 0)
  // Presser bar (x = -172, z = -6) and Lifter Lever
  brush.set("pen", PAL.abyss, 2.2);
  line3D(-172, yHBot, -6, -172, -8, -6);
  brush.set("rotring", PAL.ragBright, 1.05);
  line3D(-174, yHBot, -4, -174, -8, -4);

  // Presser bar lifter lever at y = -68
  brush.set("pen", PAL.ragBright, 1.1);
  line3D(-172, -68, -6, -154, -74, -18);

  // Needle bar (x = -180, z = +2) descending to needle clamp at y = -36
  brush.set("pen", PAL.abyss, 2.4);
  line3D(-180, yHBot, 2, -180, -34, 2);
  brush.set("rotring", PAL.ragBright, 1.15);
  line3D(-182, yHBot, 4, -182, -34, 4);

  // Needle clamp & thumbscrew at y = -36
  const clampPts = [
    [-186, -40, 6], [-172, -40, 6],
    [-172, -30, 6], [-186, -30, 6]
  ];
  washPoly3D(clampPts, PAL.abyss, 220, 0.1, 0.4, 0.3);
  brush.set("rotring", PAL.ragBright, 0.95);
  spline3D(clampPts.concat([clampPts[0]]), 0.1);
  // Thumbscrew head
  const ts = proj(-168, -35, 8);
  brush.set("rotring", PAL.ragBright, 1.1);
  brush.circle(ts[0], ts[1], 3.5);

  // THE FINE STEEL SEWING NEEDLE (from y = -30 straight into the throat plate hole at y = 0)
  brush.set("rotring", PAL.abyss, 1.3);
  line3D(-179, -30, 2, -179, 0, 2);
  brush.set("rotring", PAL.ragBright, 0.95);
  line3D(-180.5, -30, 3, -180.5, 0, 3);

  // THE HINGED PRESSER FOOT resting on the cloth at (-178, -2, 0)
  const footToe1 = [
    [-172, -8, -6], [-172, -2, -2], [-184, -2, 16], [-190, -5, 22]
  ];
  const footToe2 = [
    [-172, -8, -6], [-168, -2, -2], [-174, -2, 16], [-178, -5, 22]
  ];
  brush.set("pen", PAL.abyss, 1.8);
  spline3D(footToe1, 0.3);
  spline3D(footToe2, 0.3);
  brush.set("rotring", PAL.ragBright, 1.05);
  spline3D(footToe1, 0.3);
  spline3D(footToe2, 0.3);
}

// =============================================================================
// 8. BALANCE WHEEL (HANDWHEEL), CURVED SPOKES, BOBBIN WINDER & DRIVE BELT
// =============================================================================
function drawBalanceWheelAndRightSide() {
  const wx = 216;       // X plane of the balance wheel
  const wy = -178;      // Y center of the wheel
  const wz = 0;         // Z center of the wheel
  const rOuter = 94;    // Outer radius of cast-iron rim
  const rInner = 74;    // Inner radius of rim
  const rHub = 23;      // Central hub radius

  // 1. Reserve the Outer Rim Torus in Cotton Rag White first
  const rimOuter2D = [], rimInner2D = [], rimBack2D = [];
  const nRim = 36;
  for (let i = 0; i <= nRim; i++) {
    const a = (i / nRim) * Math.PI * 2;
    const yy = wy + Math.sin(a) * rOuter;
    const zz = wz + Math.cos(a) * rOuter;
    rimOuter2D.push(proj(wx + 8, yy, zz));
    rimBack2D.push(proj(wx - 12, yy, zz));
    rimInner2D.push(proj(wx + 6, wy + Math.sin(a) * rInner, wz + Math.cos(a) * rInner));
  }

  // Draw the wheel rim in 12 arc segments so we can shade it with 3D inverted tonality!
  for (let s = 0; s < 12; s++) {
    const a0 = (s / 12) * Math.PI * 2;
    const a1 = ((s + 1) / 12) * Math.PI * 2;
    const segPts = [];
    for (let k = 0; k <= 3; k++) {
      const a = a0 + (a1 - a0) * (k / 3);
      segPts.push([wx - 10, wy + Math.sin(a) * rOuter, wz + Math.cos(a) * rOuter]);
    }
    for (let k = 3; k >= 0; k--) {
      const a = a0 + (a1 - a0) * (k / 3);
      segPts.push([wx + 8, wy + Math.sin(a) * rInner, wz + Math.cos(a) * rInner]);
    }
    // First reserve white
    washPoly3D(segPts, PAL.rag, 235, 0.14, 0.4, 0.25);

    // Inverted sun-print shading: top arc (sin(a) < 0) & front-right face get darkest Prussian blue;
    // lower arc (sin(a) > 0) stays luminous pale cyan & reserved white!
    const midA = (a0 + a1) * 0.5;
    const lightHit = -Math.sin(midA) * 0.65 + Math.cos(midA) * 0.35;
    let col = PAL.sky;
    let alpha = 150;
    if (lightHit > 0.45) { col = PAL.inkBlack; alpha = 225; }
    else if (lightHit > 0.15) { col = PAL.abyss; alpha = 215; }
    else if (lightHit > -0.15) { col = PAL.deepBlue; alpha = 195; }
    else if (lightHit > -0.45) { col = PAL.prussian; alpha = 175; }
    washPoly3D(segPts, col, alpha, 0.18, 0.55, 0.35);
  }

  // 2. SIX CURVED S-SPOKES OF THE BALANCE WHEEL ("Rendered with Obsessive Accuracy")
  const numSpokes = 6;
  for (let k = 0; k < numSpokes; k++) {
    const baseAngle = (k / numSpokes) * Math.PI * 2 + 0.22;
    const spokeLeft = [], spokeRight = [], spokeCenter = [];
    const steps = 10;
    for (let i = 0; i <= steps; i++) {
      const u = i / steps; // 0 at hub, 1 at inner rim
      const r = rHub - 2 + u * (rInner - rHub + 4);
      // Classic Victorian S-curve deflection angle
      const sCurve = Math.sin(u * Math.PI * 1.35) * 0.28;
      const a = baseAngle + sCurve;
      // Spoke width tapers from hub to rim
      const wAng = (0.14 * (1 - 0.45 * u));
      spokeLeft.push([
        wx + 2,
        wy + Math.sin(a - wAng) * r,
        wz + Math.cos(a - wAng) * r
      ]);
      spokeRight.push([
        wx - 4,
        wy + Math.sin(a + wAng) * r,
        wz + Math.cos(a + wAng) * r
      ]);
      spokeCenter.push([
        wx + 4,
        wy + Math.sin(a) * r,
        wz + Math.cos(a) * r
      ]);
    }
    const spokePoly = spokeLeft.concat(spokeRight.slice().reverse());
    // Reserve paper white first, then shade with deep Prussian core and reserved white edge!
    washPoly3D(spokePoly, PAL.rag, 240, 0.12, 0.4, 0.25);
    washPoly3D(spokePoly, PAL.indigo, 195, 0.14, 0.5, 0.35);

    brush.set("pen", PAL.abyss, 1.5);
    spline3D(spokeRight, 0.45);
    brush.set("pen", PAL.ragBright, 1.35);
    spline3D(spokeLeft, 0.45);
    brush.set("rotring", PAL.ice, 0.8);
    spline3D(spokeCenter, 0.45);
  }

  // 3. Crisp Reserved Paper-White & Abyssal Blue Concentric Rim Bevels and Belt Groove
  const groovePts = [];
  for (let i = 0; i <= nRim; i++) {
    const a = (i / nRim) * Math.PI * 2;
    groovePts.push([wx - 2, wy + Math.sin(a) * (rOuter - 3), wz + Math.cos(a) * (rOuter - 3)]);
  }
  brush.set("pen", PAL.abyss, 1.8);
  spline3D(groovePts, 0.4);

  brush.set("pen", PAL.ragBright, 1.35);
  brush.spline(rimOuter2D.map(p => [p[0], p[1]]), 0.4);
  brush.set("rotring", PAL.ragBright, 1.15);
  brush.spline(rimInner2D.map(p => [p[0], p[1]]), 0.4);
  brush.set("rotring", PAL.deepBlue, 0.95);
  brush.spline(rimBack2D.map(p => [p[0], p[1]]), 0.4);

  // 4. Central Hub & Knurled Stop-Motion Clamp Screw (x = wx..wx+26)
  for (let d = -6; d <= 24; d += 5) {
    const r = d < 8 ? rHub : (d < 18 ? 16 : 12);
    const hubRing = [];
    for (let i = 0; i <= 20; i++) {
      const a = (i / 20) * Math.PI * 2;
      hubRing.push([wx + d, wy + Math.sin(a) * r, wz + Math.cos(a) * r]);
    }
    if (d === 4) washPoly3D(hubRing, PAL.rag, 240, 0.12, 0.4, 0.25);
    if (d === 9) washPoly3D(hubRing, PAL.abyss, 215, 0.12, 0.5, 0.3);
    if (d === 19) washPoly3D(hubRing, PAL.rag, 235, 0.1, 0.35, 0.2);
    brush.set("rotring", d >= 14 ? PAL.ragBright : PAL.abyss, 0.95);
    spline3D(hubRing, 0.35);
  }
  // Knurled edge ticks on the stop-motion clamp screw
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    brush.set("rotring", i % 2 === 0 ? PAL.ragBright : PAL.abyss, 0.7);
    line3D(wx + 16, wy + Math.sin(a) * 14, wz + Math.cos(a) * 14,
           wx + 24, wy + Math.sin(a) * 14, wz + Math.cos(a) * 14);
  }

  // 5. LEATHER DRIVE BELT descending from the balance wheel groove through two slots in the bed
  const beltZFront = rOuter - 8;
  const beltZBack = -(rOuter - 8);
  for (let bz of [beltZFront, beltZBack]) {
    // Belt from wheel to bed slot (y = 0)
    brush.set("pen", PAL.abyss, 2.5);
    line3D(wx - 2, wy + 18, bz, wx - 14, 0, bz * 0.72);
    brush.set("rotring", PAL.ragBright, 1.1);
    line3D(wx, wy + 18, bz + 1.5, wx - 12, 0, bz * 0.72 + 1.5);

    // Belt hole slot in the cast-iron bed
    const slot = proj(wx - 13, 0, bz * 0.72);
    brush.set("rotring", PAL.ragBright, 1.0);
    brush.circle(slot[0], slot[1], 4.5);

    // Continuation of belt below the bed skirt (y = 44..95)
    brush.set("pen", PAL.deepBlue, 1.8);
    line3D(wx - 16, 44, bz * 0.65, wx - 22, 92, bz * 0.58);
    brush.set("rotring", PAL.ice, 0.85);
    line3D(wx - 14, 44, bz * 0.65 + 1.5, wx - 20, 92, bz * 0.58 + 1.5);
  }

  // 6. BOBBIN WINDER ASSEMBLY & STITCH REGULATOR on lower-front pillar
  // Bobbin winder pulley wheel at (x = 196, y = -98, z = 54)
  const bwWheel = [];
  for (let i = 0; i <= 18; i++) {
    const a = (i / 18) * Math.PI * 2;
    bwWheel.push([196, -98 + Math.sin(a) * 20, 54 + Math.cos(a) * 20]);
  }
  washPoly3D(bwWheel, PAL.rag, 225, 0.12, 0.4, 0.25);
  washPoly3D(bwWheel, PAL.prussian, 165, 0.14, 0.5, 0.3);
  brush.set("rotring", PAL.ragBright, 1.0);
  spline3D(bwWheel, 0.35);
  // Bobbin winder bracket arm connecting to pillar
  brush.set("pen", PAL.abyss, 1.9);
  line3D(168, -72, 36, 196, -98, 54);
  brush.set("rotring", PAL.ragBright, 1.0);
  line3D(168, -74, 38, 196, -100, 56);

  // Stitch Regulator thumbscrew & graduated slot on front-right of pillar (x = 162, y = -92, z = 44)
  const srPlate = [
    [154, -114, 45], [170, -114, 42],
    [170, -68, 42],  [154, -68, 45]
  ];
  washPoly3D(srPlate, PAL.rag, 220, 0.12, 0.4, 0.25);
  brush.set("rotring", PAL.abyss, 0.85);
  spline3D(srPlate.concat([srPlate[0]]), 0.1);
  const srKnob = proj(162, -90, 50);
  brush.set("pen", PAL.abyss, 1.4);
  brush.circle(srKnob[0], srKnob[1], 6.5);
  brush.set("rotring", PAL.ragBright, 1.0);
  brush.circle(srKnob[0], srKnob[1], 4.2);
}

// =============================================================================
// 9. WOODEN THREAD SPOOL & CONTINUOUS TENSILE THREAD PATH
// =============================================================================
function drawSpoolAndThreadPath() {
  // Spool sits atop the right shoulder of the arm at (sx = 82, sz = 0)
  // Arm top surface here is around y = -234
  const sx = 82, sz = 0;
  const yBase = -232;
  const yBotFlange = -239;
  const yTopFlange = -269;
  const ySpoolTop = -276;
  const rFlange = 23;
  const rThread = 17.5;

  // 1. Reserve the Spool Silhouette in Cotton Rag White
  const spoolSil = [
    [sx - rFlange, yBase, sz],
    [sx - rFlange, ySpoolTop, sz],
    [sx + rFlange, ySpoolTop, sz],
    [sx + rFlange, yBase, sz]
  ];
  washPoly3D(spoolSil, PAL.rag, 248, 0.14, 0.4, 0.2);

  // 2. Bottom Wooden Flange (y = -232..-239)
  for (let yy of [yBase, yBotFlange]) {
    const disc = [];
    for (let i = 0; i <= 20; i++) {
      const a = (i / 20) * Math.PI * 2;
      disc.push([sx + Math.cos(a) * rFlange, yy, sz + Math.sin(a) * rFlange]);
    }
    if (yy === yBase) washPoly3D(disc, PAL.deepBlue, 195, 0.14, 0.5, 0.3);
    brush.set("rotring", yy === yBotFlange ? PAL.ragBright : PAL.abyss, 0.9);
    spline3D(disc, 0.35);
  }

  // 3. Wound Thread Cylinder (y = -239..-269)
  // Shaded with inverted Prussian blue on the lit side and obsessed horizontal wound-thread strands!
  const cylLit = [
    [sx - rThread, yBotFlange, sz + 4],
    [sx - rThread, yTopFlange, sz + 4],
    [sx + rThread * 0.4, yTopFlange, sz + rThread],
    [sx + rThread * 0.4, yBotFlange, sz + rThread]
  ];
  washPoly3D(cylLit, PAL.abyss, 215, 0.14, 0.5, 0.35);

  const cylRight = [
    [sx + rThread * 0.2, yBotFlange, sz + rThread * 0.8],
    [sx + rThread * 0.2, yTopFlange, sz + rThread * 0.8],
    [sx + rThread, yTopFlange, sz - 4],
    [sx + rThread, yBotFlange, sz - 4]
  ];
  washPoly3D(cylRight, PAL.prussian, 175, 0.14, 0.5, 0.3);

  // Dozens of ultra-fine wound thread rings along the cylinder height
  for (let yy = yBotFlange; yy >= yTopFlange; yy -= 1.6) {
    const arcPts = [];
    for (let i = 0; i <= 10; i++) {
      const a = -0.3 + (i / 10) * (Math.PI + 0.6);
      arcPts.push([sx + Math.cos(a) * rThread, yy, sz + Math.sin(a) * rThread]);
    }
    const isHighlight = Math.abs((yy * 10) % 3.2) < 1.6;
    brush.set("rotring", isHighlight ? PAL.ragBright : PAL.abyss, 0.65);
    spline3D(arcPts, 0.4);
  }

  // 4. Top Wooden Flange & Printed Spool Label (y = -269..-276)
  const topFlangeBot = [], topFlangeTop = [], labelRing = [];
  for (let i = 0; i <= 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    topFlangeBot.push([sx + Math.cos(a) * rFlange, yTopFlange, sz + Math.sin(a) * rFlange]);
    topFlangeTop.push([sx + Math.cos(a) * rFlange, ySpoolTop, sz + Math.sin(a) * rFlange]);
    labelRing.push([sx + Math.cos(a) * (rFlange * 0.62), ySpoolTop - 0.3, sz + Math.sin(a) * (rFlange * 0.62)]);
  }
  // Top flat face receives direct overhead sunlight -> Deepest Prussian blue rim with reserved white label!
  washPoly3D(topFlangeTop, PAL.abyss, 230, 0.12, 0.45, 0.3);
  washPoly3D(labelRing, PAL.rag, 240, 0.1, 0.35, 0.2);

  brush.set("rotring", PAL.ragBright, 1.05);
  spline3D(topFlangeBot, 0.35);
  spline3D(topFlangeTop, 0.35);
  brush.set("rotring", PAL.abyss, 0.85);
  spline3D(labelRing, 0.35);

  // Spool Pin protruding from the center hole of the spool (y = -276..-292)
  brush.set("pen", PAL.abyss, 2.2);
  line3D(sx, ySpoolTop, sz, sx, -292, sz);
  brush.set("rotring", PAL.ragBright, 1.15);
  line3D(sx - 1.5, ySpoolTop, sz + 1.5, sx - 1.5, -292, sz + 1.5);

  // 5. THE CONTINUOUS TENSILE THREAD PATH
  // From spool -> top arm guide -> front tension discs -> take-up lever eye -> head wire guide -> needle eye!
  const threadSeg1 = [
    [sx - rThread, -254, sz + 6],
    [15, -252, 10],
    [-48, -238, 16] // Top arm thread guide
  ];
  const threadSeg2 = [
    [-48, -238, 16],
    [-115, -198, 28],
    [-178, -142, 36] // Under the front tension discs
  ];
  const threadSeg3 = [
    [-178, -142, 36],
    [-174, -186, 42],
    [-168, -228, 50] // Through the eye of the take-up lever
  ];
  const threadSeg4 = [
    [-168, -228, 50],
    [-175, -162, 34],
    [-180, -92, 14], // Head lower wire guide
    [-180, -6, 3]    // Straight into the eye of the needle!
  ];

  // Draw dark Prussian companion shadow first, then luminous reserved paper-white thread!
  for (let seg of [threadSeg1, threadSeg2, threadSeg3, threadSeg4]) {
    const shadowSeg = seg.map(p => [p[0] + 1.5, p[1] + 1.8, p[2]]);
    brush.set("rotring", PAL.abyss, 1.05);
    spline3D(shadowSeg, 0.35);
    brush.set("rotring", PAL.ragBright, 1.15);
    spline3D(seg, 0.35);
  }
}

// =============================================================================
// 10. CHEMICAL EDGE BLEEDS, SALT BLOOMS & ARCHIVAL SUN-PRINT FINISHING
// =============================================================================
function drawChemicalFinishingTouches() {
  // Subtle ferric-salt stipple and micro-blooms along high-contrast boundaries
  // to emphasize "every edge has the soft bleed of chemistry rather than a lens"
  const bloomCenters = [
    proj(148, -185, 0),    // Pillar shoulder
    proj(-10, -228, 0),    // Arm crown
    proj(216, -255, 45),   // Upper balance wheel rim
    proj(216, -105, -45),  // Lower balance wheel rim
    proj(-190, 80, 120),   // Cascading fabric fold
    proj(-240, 220, 150),  // Lower drapery
    proj(82, -265, 0)      // Around thread spool
  ];

  for (let b of bloomCenters) {
    // Soft translucent chemical water-bloom
    const pts = [];
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * 360;
      const r = random(18, 42);
      pts.push([b[0] + cos(a) * r, b[1] + sin(a) * r]);
    }
    washPoly(pts, PAL.sky, 38, 0.45, 0.8, 0.5);
  }

  // Fine cyanotype granulation & crystalline salt stipple in the Prussian washes
  for (let i = 0; i < 180; i++) {
    const x = random(110, 1090);
    const y = random(110, 1095);
    const col = i % 3 === 0 ? PAL.rag : (i % 3 === 1 ? PAL.prussian : PAL.abyss);
    brush.set("spray", col, random(0.25, 0.55));
    brush.line(x, y, x + random(-8, 8), y + random(-8, 8));
  }

  // Archival Registration Tick Marks & Faint Plate Number in the Lower Right Emulsion Margin
  brush.set("rotring", PAL.prussian, 0.55);
  brush.line(1055, 1118, 1092, 1118);
  brush.line(1085, 1108, 1085, 1130);
  brush.set("2H", PAL.cerulean, 0.5);
  brush.line(115, 1118, 148, 1118);
  brush.line(122, 1108, 122, 1130);
}

// Hyperrealism in p5.brush: Cracked CD Jewel Case on a Pale Terrazzo Floor
// "A mall at closing time" — Cold showroom fluorescence, pastel airbrush gradient,
// razor-thin diffraction arcs in lilac, seafoam & Miami pink, technical pen fractures.

let camYaw = 21;
let camPitch = 38;
let camDist = 1120;
let sceneScale = 3.68;
let originX = 500;
let originY = 838;

// 3D to 2D perspective projection (X, Y on floor in mm, Z height in mm)
function proj(X, Y, Z = 0) {
  let cy = cos(camYaw), sy = sin(camYaw);
  let cp = cos(camPitch), sp = sin(camPitch);
  let rx = X * cy - Y * sy;
  let ry = X * sy + Y * cy;
  let depth = camDist - ry * cp + Z * sp;
  let f = (camDist / depth) * sceneScale;
  return [
    originX + rx * f,
    originY + (ry * sp - Z * cp) * f
  ];
}

// Lid height plane (slightly propped from 11.5mm at spine to 13.0mm at right opening)
function lidZ(X, Y) {
  return 11.5 + ((X + 71) / 142) * 1.5;
}

// Liang-Barsky 2D segment clipper in local (X, Y) space
function clipSegment(x1, y1, x2, y2, xmin, ymin, xmax, ymax) {
  let t0 = 0, t1 = 1;
  let dx = x2 - x1, dy = y2 - y1;
  let p = [-dx, dx, -dy, dy];
  let q = [x1 - xmin, xmax - x1, y1 - ymin, ymax - y1];
  for (let i = 0; i < 4; i++) {
    if (abs(p[i]) < 1e-6) {
      if (q[i] < 0) return null;
    } else {
      let t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return null;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return null;
        if (t < t1) t1 = t;
      }
    }
  }
  if (t0 > t1) return null;
  return [
    x1 + t0 * dx, y1 + t0 * dy,
    x1 + t1 * dx, y1 + t1 * dy
  ];
}

function drawPoly(pts, curv = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curv);
  }
}

function draw3DLine(x1, y1, z1, x2, y2, z2) {
  let p1 = proj(x1, y1, z1);
  let p2 = proj(x2, y2, z2);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

function draw3DBoxPoly(pts3D, curv = 0) {
  let pts2D = pts3D.map(p => proj(p[0], p[1], p[2]));
  drawPoly(pts2D, curv);
}

// Sample a 3D circular arc in local space and project to 2D spline points with tapered pressure
function getArc3DPoints(cx, cy, cz, r, startDeg, endDeg, steps = 16, taper = true) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(startDeg, endDeg, t);
    let X = cx + r * cos(a);
    let Y = cy + r * sin(a);
    let p = proj(X, Y, cz);
    let pr = taper ? (0.2 + 0.85 * sin(t * 180)) : 1.0;
    pts.push([p[0], p[1], pr]);
  }
  return pts;
}

