function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // =========================================================================
  // 1. EMPTY PASTEL SKY & SYNTHETIC AIRBRUSHED GROUND GRADIENT
  // =========================================================================
  renderSkyAndAirbrushGround();

  // =========================================================================
  // 2. PALE TERRAZZO FLOOR, EXPANSION JOINTS & FLUORESCENT FLOOR SHEEN
  // =========================================================================
  renderTerrazzoFloor();

  // =========================================================================
  // 3. FLOOR CAST SHADOWS, CAUSTICS & REFLECTED RAINBOW DIFFRACTION
  // =========================================================================
  renderFloorShadowsAndCaustics();

  // =========================================================================
  // 4. JEWEL CASE BOTTOM TRAY, RIBBED SPINE & EXPOSED ROSETTE HUB
  // =========================================================================
  renderJewelCaseTray();

  // =========================================================================
  // 5. THE HALF-SLID-OUT COMPACT DISC & RAZOR-THIN RAINBOW DIFFRACTION ARCS
  // =========================================================================
  renderCompactDisc();

  // =========================================================================
  // 6. CLEAR JEWEL CASE LID, FLUORESCENT TUBES, FRACTURES, SCUFFS & GLINTS
  // =========================================================================
  renderCrackedLid();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. SKY & GRAINLESS SYNTHETIC AIRBRUSHED GROUND
// ---------------------------------------------------------------------------
function renderSkyAndAirbrushGround() {
  brush.noStroke();

  // Dissolving pastel sky (y = 0 to 500)
  let skyStops = [
    [0, "#fbfafd"],
    [0.18, "#f7f3fa"],
    [0.42, "#efe6f6"],
    [0.68, "#f2e2ef"],
    [0.88, "#e6edf5"],
    [1.0, "#dff0f5"]
  ];

  let skyBands = 48;
  for (let i = 0; i < skyBands; i++) {
    let t = i / (skyBands - 1);
    let col = sampleGradient(skyStops, t);
    let y0 = lerp(-20, 485, t) - 18;
    let h = 38;
    brush.wash(col, map(t, 0, 1, 55, 95));
    drawPoly([
      [-20, y0], [1220, y0 - 8 * sin(t * 180)],
      [1220, y0 + h], [-20, y0 + h + 8 * sin(t * 180)]
    ]);
  }

  // Dissolve top edge into pure luminous pale air
  for (let i = 0; i < 12; i++) {
    let h = map(i, 0, 11, 220, 25);
    brush.wash("#fbfafd", 28);
    drawPoly([[-10, -10], [1210, -10], [1210, h], [-10, h + 15]]);
  }

  // Synthetic grainless airbrushed ground gradient (y = 450 to 1200)
  // Running diagonally from dusty magenta (left/lower-left) to soft cyan (right/upper-right)
  let groundHorizontalSlices = 54;
  let groundCols = 8;

  let leftMagentaStops = [
    [0.0, "#e5c5d8"],
    [0.25, "#dca8c4"],
    [0.55, "#cf8eb2"],
    [0.82, "#c47aa3"],
    [1.0, "#b96d98"]
  ];
  let midLilacStops = [
    [0.0, "#e2d9f0"],
    [0.3, "#d5c6eb"],
    [0.6, "#c9b5e4"],
    [0.85, "#beaadf"],
    [1.0, "#b5a0d9"]
  ];
  let rightCyanStops = [
    [0.0, "#def5f8"],
    [0.25, "#c5eef4"],
    [0.55, "#a6e4ed"],
    [0.82, "#8cd9e5"],
    [1.0, "#7bcfe0"]
  ];

  for (let r = 0; r < groundHorizontalSlices; r++) {
    let ty = r / (groundHorizontalSlices - 1);
    let yTop = lerp(455, 1190, ty) - 16;
    let yBot = yTop + 36;

    let colLeft = sampleGradient(leftMagentaStops, ty);
    let colMid = sampleGradient(midLilacStops, ty);
    let colRight = sampleGradient(rightCyanStops, ty);

    for (let c = 0; c < groundCols; c++) {
      let tx = c / (groundCols - 1);
      // Diagonal shift so dusty magenta dominates lower-left and cyan dominates right/mid-right
      let diagT = constrain(tx * 0.82 + (1 - ty) * 0.24 - 0.04, 0, 1);
      let cellCol;
      if (diagT < 0.48) {
        cellCol = lerpColor(color(colLeft), color(colMid), diagT / 0.48);
      } else {
        cellCol = lerpColor(color(colMid), color(colRight), (diagT - 0.48) / 0.52);
      }

      let xL = lerp(-60, 1060, c / groundCols) - 45;
      let xR = lerp(140, 1260, (c + 1) / groundCols) + 45;
      let tilt = (tx - 0.5) * 22;

      brush.wash(cellCol, 58);
      drawPoly([
        [xL, yTop + tilt],
        [xR, yTop - tilt],
        [xR + 20, yBot - tilt],
        [xL - 20, yBot + tilt]
      ]);
    }
  }

  // Smooth grainless airbrush blending passes across the ground and horizon
  let airPasses = [
    { x1: -50, y1: 1080, x2: 650, y2: 680, col: "#d186ad", w: 2.2 },
    { x1: -50, y1: 920, x2: 580, y2: 560, col: "#dfa6c4", w: 2.0 },
    { x1: 220, y1: 1150, x2: 980, y2: 620, col: "#cbb8e4", w: 2.2 },
    { x1: 520, y1: 1050, x2: 1250, y2: 540, col: "#99e0ea", w: 2.4 },
    { x1: 680, y1: 1180, x2: 1250, y2: 740, col: "#85d5e2", w: 2.2 },
    { x1: -50, y1: 475, x2: 1250, y2: 465, col: "#edf4f8", w: 1.8 },
    { x1: -50, y1: 495, x2: 1250, y2: 488, col: "#e9e2f2", w: 1.5 }
  ];
  for (let p of airPasses) {
    brush.set("synth_air", p.col, p.w);
    for (let k = -2; k <= 2; k++) {
      brush.line(p.x1, p.y1 + k * 24, p.x2, p.y2 + k * 24);
    }
  }
  brush.noStroke();
  brush.noWash();
}

function sampleGradient(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let localT = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(color(stops[i][1]), color(stops[i + 1][1]), localT);
    }
  }
  return color(stops[stops.length - 1][1]);
}

// ---------------------------------------------------------------------------
// 2. PALE TERRAZZO FLOOR, PERSPECTIVE JOINTS & FLUORESCENT REFLECTIONS
// ---------------------------------------------------------------------------
function renderTerrazzoFloor() {
  brush.noStroke();

  // Cold showroom overhead fluorescent tube reflections on the polished floor
  let tubeBands = [
    // Tube pair 1 (upper-left to mid-right)
    [[-40, 620], [820, 475], [880, 505], [-40, 680], 18],
    [[-40, 635], [835, 483], [865, 498], [-40, 665], 26],
    // Tube pair 2 (sweeping right under the jewel case & CD)
    [[60, 1180], [1180, 640], [1240, 695], [170, 1210], 16],
    [[90, 1185], [1200, 655], [1225, 680], [140, 1200], 24]
  ];
  for (let b of tubeBands) {
    brush.wash("#f2fcff", b[4]);
    drawPoly([b[0], b[1], b[2], b[3]]);
  }
  brush.noWash();

  // Perspective terrazzo brass/zinc divider strips (mall showroom floor grid)
  let vpX = 640, vpY = 395;
  let rayTargets = [-420, -40, 340, 720, 1100, 1480];
  for (let tx of rayTargets) {
    let tStart = (475 - vpY) / (1200 - vpY);
    let xStart = lerp(vpX, tx, tStart);
    brush.set("tech_needle", "#8f7fa3", 0.32);
    brush.line(xStart, 475, tx, 1200);
    brush.set("glint_pen", "#f7fcff", 0.28);
    brush.line(xStart + 1.2, 475, tx + 1.5, 1200);
  }

  let rowYs = [512, 568, 645, 755, 915, 1135];
  for (let ry of rowYs) {
    let w = map(ry, 500, 1200, 0.24, 0.44);
    brush.set("tech_needle", "#8b7ca0", w);
    brush.line(0, ry + 14, 1200, ry - 18);
    brush.set("glint_pen", "#f7fcff", w * 0.85);
    brush.line(0, ry + 15.2, 1200, ry - 16.8);
  }
  brush.noStroke();

  // Terrazzo aggregate chips (batched by color for fast wash rendering)
  let chipPalette = [
    { col: "#fcfbfe", alpha: 185, count: 155, minR: 2.2, maxR: 8.5 }, // Marble white
    { col: "#f5d4e4", alpha: 165, count: 115, minR: 2.0, maxR: 7.5 }, // Shell rose
    { col: "#d59bb8", alpha: 155, count: 95,  minR: 2.0, maxR: 7.0 }, // Dusty magenta chip
    { col: "#b6a4d4", alpha: 160, count: 105, minR: 2.0, maxR: 7.5 }, // Pale lilac chip
    { col: "#9ce3e8", alpha: 165, count: 105, minR: 2.0, maxR: 7.5 }, // Seafoam chip
    { col: "#857c9e", alpha: 135, count: 70,  minR: 1.6, maxR: 5.5 }, // Cool slate-violet chip
    { col: "#ffffff", alpha: 235, count: 85,  minR: 1.2, maxR: 3.4 }  // Specular mica glint
  ];

  for (let group of chipPalette) {
    brush.wash(group.col, group.alpha);
    for (let i = 0; i < group.count; i++) {
      // Bias distribution slightly toward mid/foreground with perspective scaling
      let u = random();
      let depthT = pow(u, 1.35);
      let cy = lerp(478, 1192, depthT);
      let cx = random(8, 1192);

      let perspScale = lerp(0.32, 1.28, depthT);
      let aspectY = lerp(0.32, 0.58, depthT); // Foreshortened on floor plane
      let baseR = random(group.minR, group.maxR) * perspScale;

      let sides = int(random(4, 7));
      let pts = [];
      let rot = random(360);
      for (let s = 0; s < sides; s++) {
        let ang = rot + (s / sides) * 360 + random(-18, 18);
        let rad = baseR * random(0.68, 1.22);
        pts.push([
          cx + cos(ang) * rad,
          cy + sin(ang) * rad * aspectY
        ]);
      }
      drawPoly(pts);
    }
  }
  brush.noWash();

  // Subtle hairline rim glints on larger foreground terrazzo chips
  brush.set("tech_needle", "#ffffff", 0.25);
  for (let i = 0; i < 65; i++) {
    let cy = random(650, 1180);
    let cx = random(40, 1160);
    let len = map(cy, 650, 1180, 3, 9);
    let ang = random(-25, 25);
    brush.line(cx, cy, cx + cos(ang) * len, cy + sin(ang) * len * 0.4);
  }
  brush.noStroke();
}

// ---------------------------------------------------------------------------
// 3. FLOOR CAST SHADOWS, CAUSTICS & REFLECTED RAINBOW DIFFRACTION
// ---------------------------------------------------------------------------
function renderFloorShadowsAndCaustics() {
  brush.noStroke();

  // Reflected rainbow diffraction glow on the terrazzo floor under the slid-out CD
  let cdX = 62, cdY = 4;
  let floorReflectArcs = [
    { r1: 28, r2: 58, a1: -38, a2: 24, col: "#f482bc", alpha: 34 },
    { r1: 26, r2: 56, a1: -12, a2: 46, col: "#7ae8dc", alpha: 36 },
    { r1: 24, r2: 55, a1: 18,  a2: 68, col: "#caa6f7", alpha: 36 },
    { r1: 30, r2: 54, a1: -55, a2: -15, col: "#d2b0fa", alpha: 30 }
  ];
  for (let fa of floorReflectArcs) {
    brush.wash(fa.col, fa.alpha);
    let pts = [];
    for (let a = fa.a1; a <= fa.a2; a += 6) {
      pts.push(proj(cdX + 8 + fa.r2 * cos(a), cdY + 12 + fa.r2 * sin(a), 0));
    }
    for (let a = fa.a2; a >= fa.a1; a -= 6) {
      pts.push(proj(cdX + 8 + fa.r1 * cos(a), cdY + 12 + fa.r1 * sin(a), 0));
    }
    drawPoly(pts);
  }

  // Dual-tube fluorescent cast shadows beneath the floating jewel case (z_base = 3mm)
  // Soft ambient penumbra
  let shadowOffsets = [
    { dx: 11, dy: 14, col: "#857098", alpha: 32 },
    { dx: 7,  dy: 9,  col: "#705d85", alpha: 42 },
    { dx: 3.5, dy: 4.5, col: "#5b4970", alpha: 52 }
  ];

  for (let sh of shadowOffsets) {
    brush.wash(sh.col, sh.alpha);
    // Jewel case footprint shadow
    draw3DBoxPoly([
      [-71 + sh.dx, -62.5 + sh.dy, 0],
      [71 + sh.dx, -62.5 + sh.dy, 0],
      [71 + sh.dx, 62.5 + sh.dy, 0],
      [-71 + sh.dx, 62.5 + sh.dy, 0]
    ]);

    // Slid-out CD footprint shadow
    let cdShadowPts = [];
    for (let a = -95; a <= 95; a += 8) {
      let X = cdX + sh.dx * 1.15 + 60 * cos(a);
      let Y = cdY + sh.dy * 1.15 + 60 * sin(a);
      cdShadowPts.push(proj(X, Y, 0));
    }
    drawPoly(cdShadowPts);
  }

  // Bright refractive caustic bands focused onto the terrazzo floor under the clear case walls
  let causticStrips = [
    // Front edge caustic
    [[-65, 65, 0], [68, 65, 0], [68, 69.5, 0], [-65, 69.5, 0], "#e8fcff", 85],
    [[-60, 66.2, 0], [64, 66.2, 0], [64, 68.0, 0], [-60, 68.0, 0], "#ffffff", 130],
    // Right edge caustic
    [[72.5, -58, 0], [76.5, -58, 0], [76.5, 64, 0], [72.5, 64, 0], "#ffe3f2", 75],
    // Internal tray circle caustic ring on floor under the case
    [[-52, -59, 0], [65, -59, 0], [65, -55, 0], [-52, -55, 0], "#dffaff", 65]
  ];
  for (let cs of causticStrips) {
    brush.wash(cs[4], cs[5]);
    draw3DBoxPoly([cs[0], cs[1], cs[2], cs[3]]);
  }
  brush.noWash();

  // Razor-thin caustic light lines on floor
  brush.set("glint_pen", "#ffffff", 0.55);
  draw3DLine(-64, 66.8, 0, 66, 66.8, 0);
  draw3DLine(74.2, -56, 0, 74.2, 62, 0);
  brush.noStroke();
}

// ---------------------------------------------------------------------------
// 4. JEWEL CASE BOTTOM TRAY, RIBBED SPINE & EXPOSED ROSETTE HUB
// ---------------------------------------------------------------------------
function renderJewelCaseTray() {
  let zBot = 3.0;
  let zTrayBed = 5.0;
  let zTrayRim = 8.5;

  brush.noStroke();

  // Translucent polystyrene body wash of the tray
  brush.wash("#e4edf7", 52);
  draw3DBoxPoly([
    [-71, -62.5, zTrayBed],
    [71, -62.5, zTrayBed],
    [71, 62.5, zTrayBed],
    [-71, 62.5, zTrayBed]
  ]);

  // Ribbed Spine section on left (X from -71 to -59)
  brush.wash("#d6e4f2", 82);
  draw3DBoxPoly([
    [-71, -62.5, zTrayRim],
    [-59, -62.5, zTrayRim],
    [-59, 62.5, zTrayRim],
    [-71, 62.5, zTrayRim]
  ]);

  // Left outer wall thickness (X = -71, Z from zBot to 11.5)
  brush.wash("#b8c8dc", 110);
  draw3DBoxPoly([
    [-71, -62.5, zBot],
    [-71, 62.5, zBot],
    [-71, 62.5, 11.5],
    [-71, -62.5, 11.5]
  ]);

  // Front outer wall thickness (Y = 62.5, Z from zBot to 12.2)
  brush.wash("#c8d8ea", 98);
  draw3DBoxPoly([
    [-71, 62.5, zBot],
    [71, 62.5, zBot],
    [71, 62.5, 12.2],
    [-71, 62.5, 11.5]
  ]);

  // Circular recessed disc well in the tray (centered at X = 6, Y = 0, radius = 60.5)
  let wellPts = [];
  for (let a = 0; a < 360; a += 6) {
    wellPts.push(proj(6 + 60.5 * cos(a), 60.5 * sin(a), zTrayBed));
  }
  brush.wash("#cdd9e8", 55);
  drawPoly(wellPts);
  brush.noWash();

  // Precision molded ribs along the spine (X from -70 to -60)
  for (let rx = -70; rx <= -60; rx += 1.25) {
    brush.set("tech_needle", "#7d8ba3", 0.28);
    draw3DLine(rx, -61.5, zTrayRim, rx, 61.5, zTrayRim);
    brush.set("glint_pen", "#ffffff", 0.32);
    draw3DLine(rx + 0.35, -61.5, zTrayRim + 0.2, rx + 0.35, 61.5, zTrayRim + 0.2);
  }

  // Tray recessed circle rim & diagonal corner mold ribs
  brush.set("tech_needle", "#7b88a1", 0.38);
  safeSpline(getArc3DPoints(6, 0, zTrayBed, 60.5, 0, 360, 48, false), 0.5);
  brush.set("glint_pen", "#ffffff", 0.42);
  safeSpline(getArc3DPoints(6, 0, zTrayBed + 0.3, 61.0, 115, 295, 28, true), 0.5);

  // Finger cutouts at top and bottom of tray well (Y = -58 and Y = +58)
  brush.set("tech_needle", "#6d7a94", 0.36);
  safeSpline(getArc3DPoints(6, -59, zTrayBed, 15, 20, 160, 14, false), 0.5);
  safeSpline(getArc3DPoints(6, 59, zTrayBed, 15, 200, 340, 14, false), 0.5);
  brush.set("glint_pen", "#ffffff", 0.4);
  safeSpline(getArc3DPoints(6, -59, zTrayBed + 0.3, 15.4, 30, 150, 12, true), 0.5);
  safeSpline(getArc3DPoints(6, 59, zTrayBed + 0.3, 15.4, 210, 330, 12, true), 0.5);

  // Diagonal tray mold vents in the 4 corners of the square tray
  let cornerVents = [
    [-55, -58, -38, -42],
    [66, -58, 50, -42],
    [-55, 58, -38, 42],
    [66, 58, 50, 42]
  ];
  for (let cv of cornerVents) {
    brush.set("tech_needle", "#8290a8", 0.32);
    draw3DLine(cv[0], cv[1], zTrayBed, cv[2], cv[3], zTrayBed);
    brush.set("glint_pen", "#ffffff", 0.34);
    draw3DLine(cv[0] + 0.5, cv[1], zTrayBed + 0.2, cv[2] + 0.5, cv[3], zTrayBed + 0.2);
  }

  // EXPOSED CENTRAL ROSETTE HUB at (X = 6, Y = 0, Z = 6.2)
  // Because the CD has slid halfway out to X = 62, the tray's center spindle rosette is completely exposed!
  let hubX = 6, hubY = 0, hubZ = 6.2;
  brush.noStroke();
  brush.wash("#bdcce0", 125);
  let hubBasePts = [];
  for (let a = 0; a < 360; a += 12) {
    hubBasePts.push(proj(hubX + 15.5 * cos(a), hubY + 15.5 * sin(a), hubZ));
  }
  drawPoly(hubBasePts);
  brush.noWash();

  // Concentric rings of the rosette hub
  brush.set("tech_needle", "#5c6882", 0.38);
  safeSpline(getArc3DPoints(hubX, hubY, hubZ, 15.5, 0, 360, 28, false), 0.5);
  safeSpline(getArc3DPoints(hubX, hubY, hubZ + 0.8, 7.6, 0, 360, 24, false), 0.5);
  safeSpline(getArc3DPoints(hubX, hubY, hubZ + 0.8, 4.2, 0, 360, 18, false), 0.5);

  // 12 radial clip teeth of the jewel case rosette
  for (let i = 0; i < 12; i++) {
    let a = i * 30;
    brush.set("tech_needle", "#535f78", 0.34);
    draw3DLine(
      hubX + 4.5 * cos(a), hubY + 4.5 * sin(a), hubZ + 0.9,
      hubX + 12.5 * cos(a), hubY + 12.5 * sin(a), hubZ + 0.4
    );
    brush.set("glint_pen", "#ffffff", 0.38);
    draw3DLine(
      hubX + 4.8 * cos(a + 4), hubY + 4.8 * sin(a + 4), hubZ + 1.1,
      hubX + 12.2 * cos(a + 4), hubY + 12.2 * sin(a + 4), hubZ + 0.6
    );
  }
  brush.set("glint_pen", "#ffffff", 0.48);
  safeSpline(getArc3DPoints(hubX, hubY, hubZ + 1.1, 7.6, -45, 165, 18, true), 0.5);

  // Tray bottom perimeter technical lines
  brush.set("tech_needle", "#5f6b85", 0.42);
  draw3DLine(-71, 62.5, zBot, 71, 62.5, zBot);
  draw3DLine(-71, -62.5, zBot, -71, 62.5, zBot);
  draw3DLine(71, -62.5, zBot, 71, 62.5, zBot);
  draw3DLine(-59, -62.5, zBot, -59, 62.5, zBot);

  brush.set("glint_pen", "#e6faff", 0.45);
  draw3DLine(-71, 62.5, zBot + 0.6, 71, 62.5, zBot + 0.6);
  draw3DLine(-71, -62.5, zBot + 0.6, -71, 62.5, zBot + 0.6);
  brush.noStroke();
}

// ---------------------------------------------------------------------------
// 5. THE HALF-SLID-OUT COMPACT DISC & RAZOR-THIN RAINBOW DIFFRACTION ARCS
// ---------------------------------------------------------------------------
function renderCompactDisc() {
  let cdX = 62, cdY = 4, cdZ = 7.6;
  let rOuter = 60.0;
  let rDataOut = 58.6;
  let rDataIn = 22.5;
  let rMirrorIn = 16.5;
  let rClampIn = 7.5;

  brush.noStroke();

  // 5A. Shadow cast by the CD onto the inner tray bed (for X <= 71)
  brush.wash("#6c5e82", 52);
  let trayShadowPts = [];
  for (let a = 95; a <= 275; a += 6) {
    let X = min(71, cdX + 2.5 + rOuter * cos(a));
    let Y = cdY + 3.2 + rOuter * sin(a);
    trayShadowPts.push(proj(X, Y, 5.1));
  }
  drawPoly(trayShadowPts);

  // 5B. Polycarbonate 1.2mm thickness rim of the CD along the front/bottom half
  brush.wash("#8fa4bd", 160);
  let rimPts = [];
  for (let a = -20; a <= 200; a += 6) {
    rimPts.push(proj(cdX + rOuter * cos(a), cdY + rOuter * sin(a), cdZ));
  }
  for (let a = 200; a >= -20; a -= 6) {
    rimPts.push(proj(cdX + rOuter * cos(a), cdY + rOuter * sin(a), cdZ - 1.3));
  }
  drawPoly(rimPts);

  // 5C. Base Mirrored Metallic Face of the CD (annulus from rMirrorIn to rOuter)
  // Drawn in angular sectors so we can build realistic showroom ceiling & fluorescent mirror tonalities
  let numSectors = 36;
  for (let s = 0; s < numSectors; s++) {
    let a1 = (s / numSectors) * 360;
    let a2 = ((s + 1.05) / numSectors) * 360;
    let aMid = (a1 + a2) * 0.5;

    // Metallic mirror base tone: alternating dark showroom ceiling reflection & bright cold chrome
    let wave = sin(aMid * 2 + 35) * 0.5 + 0.5;
    let cDark = color("#757f99");
    let cMid = color("#b8c4d8");
    let cBright = color("#e6eef8");
    let secCol = wave < 0.5
      ? lerpColor(cDark, cMid, wave * 2)
      : lerpColor(cMid, cBright, (wave - 0.5) * 2);

    brush.wash(secCol, 225);
    let quad = [
      proj(cdX + rMirrorIn * cos(a1), cdY + rMirrorIn * sin(a1), cdZ),
      proj(cdX + rOuter * cos(a1), cdY + rOuter * sin(a1), cdZ),
      proj(cdX + rOuter * cos(a2), cdY + rOuter * sin(a2), cdZ),
      proj(cdX + rMirrorIn * cos(a2), cdY + rMirrorIn * sin(a2), cdZ)
    ];
    drawPoly(quad);
  }

  // 5D. Soft Luminous Under-Washes for the Rainbow Diffraction Wedges
  let wedgeDefs = [
    // Primary butterfly fan (right/lower-right exposed side & upper-left under-lid side)
    { aStart: -62, aEnd: -34, col: "#cfa4fc", alpha: 95 }, // Lilac
    { aStart: -40, aEnd: -8,  col: "#6ee7d8", alpha: 105 }, // Seafoam
    { aStart: -14, aEnd: 22,  col: "#ff7eb8", alpha: 105 }, // Miami pink
    { aStart: 16,  aEnd: 42,  col: "#d8b4fe", alpha: 85 },  // Soft lilac edge

    // Opposite butterfly fan (180 deg across the disc)
    { aStart: 118, aEnd: 146, col: "#c99bf8", alpha: 85 }, // Lilac
    { aStart: 140, aEnd: 172, col: "#72e5d8", alpha: 90 }, // Seafoam
    { aStart: 166, aEnd: 202, col: "#f77cb6", alpha: 90 }, // Miami pink
    { aStart: 196, aEnd: 222, col: "#d5b0fa", alpha: 75 }, // Lilac

    // Secondary narrow showroom fixture fan
    { aStart: 58,  aEnd: 78,  col: "#8cebe0", alpha: 75 },
    { aStart: 72,  aEnd: 92,  col: "#f992c5", alpha: 75 },
    { aStart: 238, aEnd: 258, col: "#8cebe0", alpha: 70 },
    { aStart: 252, aEnd: 272, col: "#f992c5", alpha: 70 }
  ];

  for (let w of wedgeDefs) {
    brush.wash(w.col, w.alpha);
    let pts = [];
    for (let a = w.aStart; a <= w.aEnd; a += 5) {
      pts.push(proj(cdX + rDataOut * cos(a), cdY + rDataOut * sin(a), cdZ));
    }
    for (let a = w.aEnd; a >= w.aStart; a -= 5) {
      pts.push(proj(cdX + rDataIn * cos(a), cdY + rDataIn * sin(a), cdZ));
    }
    drawPoly(pts);
  }

  // Transparent Polycarbonate Clamping Ring (rClampIn = 7.5 to rMirrorIn = 16.5)
  // Because this inner ring is clear plastic, we see the terrazzo & tray edge right through it!
  for (let s = 0; s < 24; s++) {
    let a1 = s * 15, a2 = (s + 1.05) * 15;
    brush.wash("#d8e6f4", 115);
    drawPoly([
      proj(cdX + rClampIn * cos(a1), cdY + rClampIn * sin(a1), cdZ),
      proj(cdX + rMirrorIn * cos(a1), cdY + rMirrorIn * sin(a1), cdZ),
      proj(cdX + rMirrorIn * cos(a2), cdY + rMirrorIn * sin(a2), cdZ),
      proj(cdX + rClampIn * cos(a2), cdY + rClampIn * sin(a2), cdZ)
    ]);
  }
  brush.noWash();

  // Through the CD's center hole (r < 7.5) and clear clamping ring (r < 16.5),
  // draw the jewel case's right tray wall (X = 71) passing directly underneath the disc!
  brush.set("tech_needle", "#6d7b96", 0.42);
  draw3DLine(71, cdY - 15, 5.0, 71, cdY + 15, 5.0);
  draw3DLine(71, cdY - 15, 8.2, 71, cdY + 15, 8.2);
  brush.set("glint_pen", "#e6faff", 0.45);
  draw3DLine(71, cdY - 15, 8.0, 71, cdY + 15, 8.0);

  // -------------------------------------------------------------------------
  // 5E. RAZOR-THIN RAINBOW DIFFRACTION ARCS IN LILAC, SEAFOAM & MIAMI PINK
  // -------------------------------------------------------------------------
  // High-density concentric & precessing optical track arcs across the mirrored surface
  let lilacShades = ["#d8b4fe", "#c084fc", "#e9d5ff", "#b678f5"];
  let seafoamShades = ["#5eead4", "#6ee7b7", "#99f6e4", "#67e8f9", "#a7f3d0"];
  let miamiPinkShades = ["#f472b6", "#ff63b1", "#fb7185", "#f9a8d4", "#ff85c2"];

  // Fine base micro-groove tracks across the entire disc
  for (let r = rDataIn + 0.8; r <= rDataOut; r += 1.15) {
    let baseCol = (int(r * 2) % 2 === 0) ? "#9aa8c0" : "#eef4fc";
    brush.set("tech_needle", baseCol, 0.2);
    let a0 = random(0, 60);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, a0, a0 + 135, 16, true), 0.5);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, a0 + 180, a0 + 315, 16, true), 0.5);
  }

  // Razor-sharp spectral diffraction arcs along the primary & secondary optical wedges
  let numTracks = 62;
  for (let i = 0; i < numTracks; i++) {
    let tr = i / (numTracks - 1);
    let r = lerp(rDataIn + 0.6, rDataOut - 0.6, tr);
    // Slight spiral precession of diffraction phase with radius (realistic optical curvature!)
    let precess = sin(tr * 180) * 14 + (tr - 0.5) * 18;

    let lilCol = lilacShades[i % lilacShades.length];
    let seaCol = seafoamShades[i % seafoamShades.length];
    let pnkCol = miamiPinkShades[i % miamiPinkShades.length];
    let w = (i % 3 === 0) ? 0.44 : 0.3;

    // --- Wedge 1 (Exposed lower-right face of the half-slid-out CD: -68° to +48°) ---
    // Lilac sub-arc
    brush.set("laser_arc", lilCol, w);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, -64 + precess, -28 + precess, 12, true), 0.5);

    // Seafoam sub-arc
    brush.set("laser_arc", seaCol, w * 1.05);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, -36 + precess, 2 + precess, 12, true), 0.5);

    // Miami Pink sub-arc
    brush.set("laser_arc", pnkCol, w * 1.05);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, -6 + precess, 32 + precess, 12, true), 0.5);

    // Outer Lilac/Rose tail
    if (i % 2 === 0) {
      brush.set("laser_arc", "#e2b8ff", w * 0.85);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 24 + precess, 48 + precess, 8, true), 0.5);
    }

    // --- Wedge 2 (Opposite upper-left side under the cracked lid: 116° to 228°) ---
    brush.set("laser_arc", lilCol, w * 0.9);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 116 + precess, 150 + precess, 12, true), 0.5);

    brush.set("laser_arc", seaCol, w * 0.95);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 144 + precess, 180 + precess, 12, true), 0.5);

    brush.set("laser_arc", pnkCol, w * 0.95);
    safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 174 + precess, 210 + precess, 12, true), 0.5);

    // --- Secondary Cross-Wedges (55° to 98° and 235° to 278°) ---
    if (i % 2 === 0) {
      let p2 = -precess * 0.65;
      brush.set("laser_arc", seaCol, w * 0.82);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 54 + p2, 78 + p2, 9, true), 0.5);
      brush.set("laser_arc", pnkCol, w * 0.82);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 72 + p2, 96 + p2, 9, true), 0.5);
      brush.set("laser_arc", lilCol, w * 0.78);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 236 + p2, 260 + p2, 9, true), 0.5);
      brush.set("laser_arc", seaCol, w * 0.78);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 254 + p2, 278 + p2, 9, true), 0.5);
    }

    // Blinding cold fluorescent white core glints along the specular spine of the rainbow
    if (i % 3 === 0) {
      brush.set("glint_pen", "#ffffff", 0.42);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, -22 + precess * 0.8, -8 + precess * 0.8, 7, true), 0.5);
      safeSpline(getArc3DPoints(cdX, cdY, cdZ, r, 158 + precess * 0.8, 172 + precess * 0.8, 7, true), 0.5);
    }
  }

  // Razor-thin radial specular streaks across the diffraction sectors
  let radialGlintAngles = [-48, -32, -16, -4, 12, 26, 74, 132, 148, 164, 178, 194, 254];
  for (let ang of radialGlintAngles) {
    brush.set("glint_pen", "#ffffff", 0.28);
    draw3DLine(
      cdX + (rDataIn + 1) * cos(ang), cdY + (rDataIn + 1) * sin(ang), cdZ,
      cdX + (rDataOut - 1) * cos(ang), cdY + (rDataOut - 1) * sin(ang), cdZ
    );
  }

  // -------------------------------------------------------------------------
  // 5F. CD INNER MIRROR BAND, MATRIX BARCODE & CENTER HOLE BEVELS
  // -------------------------------------------------------------------------
  // Outer protective polycarbonate rim (rDataOut to rOuter)
  brush.set("tech_needle", "#53607a", 0.48);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rOuter, 0, 360, 48, false), 0.5);
  brush.set("tech_needle", "#899bb5", 0.32);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rDataOut, 0, 360, 48, false), 0.5);

  // Lower edge of the 1.2mm CD thickness rim
  brush.set("tech_needle", "#465169", 0.42);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ - 1.3, rOuter, -25, 205, 32, false), 0.5);

  // Bright cyan & white edge-piping highlight around the CD perimeter
  brush.set("laser_arc", "#80f5ff", 0.48);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ - 0.4, rOuter, -45, 95, 24, true), 0.5);
  brush.set("glint_pen", "#ffffff", 0.62);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rOuter, -38, 72, 22, true), 0.5);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rOuter, 140, 215, 16, true), 0.5);

  // Inner data boundary & mirror band (rMirrorIn = 16.5 to rDataIn = 22.5)
  brush.set("tech_needle", "#5b6782", 0.36);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rDataIn, 0, 360, 36, false), 0.5);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rMirrorIn, 0, 360, 32, false), 0.5);

  // Micro-etched IFPI matrix barcode ring (r = 18.8 to 20.6)
  for (let a = 0; a < 360; a += 5) {
    if (noise(a * 0.15) > 0.32) {
      brush.set("tech_needle", "#4a556e", 0.28);
      draw3DLine(
        cdX + 18.6 * cos(a), cdY + 18.6 * sin(a), cdZ,
        cdX + 20.4 * cos(a + 2), cdY + 20.4 * sin(a + 2), cdZ
      );
    }
  }

  // Molded stamper ridge on the clear clamping ring (r = 12.2)
  brush.set("tech_needle", "#7f91ab", 0.32);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, 12.2, 0, 360, 28, false), 0.5);
  brush.set("glint_pen", "#ffffff", 0.44);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, 12.4, -50, 110, 18, true), 0.5);

  // Center spindle hole (rClampIn = 7.5) with 1.2mm thickness bevel
  brush.set("tech_needle", "#424c63", 0.48);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rClampIn, 0, 360, 28, false), 0.5);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ - 1.2, rClampIn, 110, 310, 18, false), 0.5);
  brush.set("glint_pen", "#ffffff", 0.58);
  safeSpline(getArc3DPoints(cdX, cdY, cdZ, rClampIn, 125, 290, 18, true), 0.5);
  brush.noStroke();
}

// ---------------------------------------------------------------------------
// 6. CLEAR JEWEL CASE LID, FLUORESCENT TUBES, FRACTURES, SCUFFS & GLINTS
// ---------------------------------------------------------------------------
function renderCrackedLid() {
  brush.noStroke();

  // 6A. Optical step where the right edge of the top lid (X = 71) crosses the half-slid-out CD
  // Thin shadow cast by the lid's right edge directly onto the mirrored face of the CD
  brush.wash("#4f4669", 58);
  draw3DBoxPoly([
    [70.2, -55, 7.7],
    [73.8, -55, 7.7],
    [73.8, 60, 7.7],
    [70.2, 60, 7.7]
  ]);

  // Subtle milky-cool specular veil of the clear plastic lid (X from -59 to 71, Y from -62.5 to 62.5)
  // This optical veil slightly softens the left half of the CD underneath the lid!
  brush.wash("#e8f0fa", 32);
  draw3DBoxPoly([
    [-59, -62.5, lidZ(-59, -62.5)],
    [71, -62.5, lidZ(71, -62.5)],
    [71, 62.5, lidZ(71, 62.5)],
    [-59, 62.5, lidZ(-59, 62.5)]
  ]);

  // 6B. Cold Showroom Fluorescent Tube Reflections on the Clear Plastic Lid
  // Notice how the reflection bands shift slightly where they cross the major crack lines!
  let lidReflectPolys = [
    // Tube 1 reflection (upper-left to mid-top) — split into two slightly offset facets across the crack!
    {
      pts: [[-58, -18], [-12, -62.5], [14, -62.5], [-58, 8]],
      col: "#ffffff", alpha: 48
    },
    {
      pts: [[-58, 10], [16, -62.5], [32, -62.5], [-58, 25]],
      col: "#dffaff", alpha: 35
    },
    // Tube 2 reflection (sweeping diagonally across the center of the cracked lid)
    {
      pts: [[-42, 62.5], [-8, 12], [18, 14], [-14, 62.5]],
      col: "#ffffff", alpha: 52
    },
    {
      // Slightly refracted/jogged continuation on the upper-right facet of the crack!
      pts: [[-5, 10], [58, -62.5], [71, -62.5], [71, -44], [21, 12]],
      col: "#ffffff", alpha: 58
    },
    {
      pts: [[24, 14], [71, -40], [71, -24], [38, 16]],
      col: "#e2f8ff", alpha: 36
    }
  ];

  for (let rp of lidReflectPolys) {
    brush.wash(rp.col, rp.alpha);
    let pts3D = rp.pts.map(p => [p[0], p[1], lidZ(p[0], p[1])]);
    draw3DBoxPoly(pts3D);
  }

  // Booklet holder stopper tabs along the top & bottom edges of the clear lid (6 tabs)
  let tabXs = [-38, 6, 50];
  let tabYs = [-62.5, 62.5];
  for (let tx of tabXs) {
    for (let ty of tabYs) {
      let yIn = ty < 0 ? ty + 4.2 : ty - 4.2;
      let zT = lidZ(tx, ty);
      brush.wash("#d8e8f8", 115);
      draw3DBoxPoly([
        [tx - 4.5, ty, zT],
        [tx + 4.5, ty, zT],
        [tx + 3.8, yIn, zT],
        [tx - 3.8, yIn, zT]
      ]);
      brush.set("tech_needle", "#5f6d87", 0.34);
      draw3DLine(tx - 4.5, yIn, zT, tx + 4.5, yIn, zT);
      draw3DLine(tx - 4.5, ty, zT, tx - 4.5, yIn, zT);
      draw3DLine(tx + 4.5, ty, zT, tx + 4.5, yIn, zT);
      brush.set("glint_pen", "#ffffff", 0.45);
      draw3DLine(tx - 4.2, yIn, zT + 0.2, tx + 4.2, yIn, zT + 0.2);
      brush.noStroke();
    }
  }
  brush.noWash();

  // -------------------------------------------------------------------------
  // 6C. LID PERIMETER WALLS, BEVELS & INTERNAL LIGHT PIPING
  // -------------------------------------------------------------------------
  let zL = 11.5, zR = 13.0;
  // Outer lid contour in fine technical pen
  brush.set("tech_needle", "#4f5c78", 0.46);
  draw3DLine(-71, -62.5, zL, 71, -62.5, zR);
  draw3DLine(71, -62.5, zR, 71, 62.5, zR);
  draw3DLine(71, 62.5, zR, -71, 62.5, zL);
  draw3DLine(-71, 62.5, zL, -71, -62.5, zL);
  // Spine hinge line at X = -59
  draw3DLine(-59, -62.5, lidZ(-59, 0), -59, 62.5, lidZ(-59, 0));

  // Lid 1.5mm thickness lower bevel lines
  brush.set("tech_needle", "#6d7b96", 0.36);
  draw3DLine(-71, 62.5, zL - 1.5, 71, 62.5, zR - 1.5);
  draw3DLine(71, -62.5, zR - 1.5, 71, 62.5, zR - 1.5);
  draw3DLine(-59, -62.5, lidZ(-59, 0) - 1.2, -59, 62.5, lidZ(-59, 0) - 1.2);

  // Pastel cyan & pink internal refraction piping along the clear plastic lid edges
  brush.set("laser_arc", "#8cf6ff", 0.45);
  draw3DLine(-59, 62.5, zL - 0.5, 71, 62.5, zR - 0.5);
  draw3DLine(71, -62.5, zR - 0.5, 71, 62.5, zR - 0.5);
  brush.set("laser_arc", "#ff9ed2", 0.38);
  draw3DLine(-59, -62.5, zL - 0.4, 71, -62.5, zR - 0.4);

  // Hard white specular glints on the lid bevels
  brush.set("glint_pen", "#ffffff", 0.65);
  draw3DLine(-71, 62.5, zL, 71, 62.5, zR);
  draw3DLine(71, -62.5, zR, 71, 62.5, zR);
  draw3DLine(-71, -62.5, zL, 71, -62.5, zR);
  draw3DLine(-59, -62.5, lidZ(-59, 0), -59, 62.5, lidZ(-59, 0));

  // -------------------------------------------------------------------------
  // 6D. HAIRLINE FRACTURES & BRITTLE STRESS CRACKS IN TECHNICAL PEN
  // -------------------------------------------------------------------------
  // Primary impact point at (-8, 10) on the clear lid, plus secondary stress network
  let crackPaths = [
    // Primary radial fracture 1 (to upper-left spine)
    [[-8, 10], [-22, -2], [-39, -19], [-52, -31], [-59, -41]],
    // Primary radial fracture 2 (to top edge)
    [[-8, 10], [-6, -9], [-1, -28], [2, -46], [8, -62.5]],
    // Primary radial fracture 3 (long diagonal crack to upper-right corner)
    [[-8, 10], [9, -2], [27, -18], [46, -33], [63, -51], [71, -58]],
    // Primary radial fracture 4 (across the CD face to the right opening edge!)
    [[-8, 10], [12, 13], [31, 11], [52, 16], [71, 19]],
    // Primary radial fracture 5 (down-right to front edge, crossing over the CD!)
    [[-8, 10], [6, 24], [22, 38], [35, 52], [47, 62.5]],
    // Primary radial fracture 6 (down-left to front edge)
    [[-8, 10], [-16, 26], [-23, 44], [-31, 62.5]],
    // Primary radial fracture 7 (left to spine)
    [[-8, 10], [-26, 12], [-44, 17], [-59, 21]],

    // Secondary branched stress fractures & conchoidal step-forks
    [[-22, -2], [-34, 3], [-49, 2], [-59, 4]],
    [[-1, -28], [-15, -42], [-26, -62.5]],
    [[27, -18], [39, -8], [56, -12], [71, -9]],
    [[27, -18], [24, -38], [31, -62.5]],
    [[31, 11], [44, 2], [61, -2], [71, -4]],
    [[31, 11], [48, 28], [64, 35], [71, 39]],
    [[6, 24], [-4, 39], [-8, 62.5]],
    [[-16, 26], [-35, 34], [-51, 46], [-59, 52]],

    // Cross-web ring fractures around the impact star (-8, 10)
    [[-22, -2], [-6, -9], [9, -2], [12, 13], [6, 24], [-16, 26], [-26, 12], [-22, -2]],
    [[-39, -19], [-15, -42], [24, -38], [46, -33]],
    [[22, 38], [48, 28], [52, 16]],

    // Secondary corner impact fracture near upper-right hinge/corner
    [[54, -62.5], [58, -44], [65, -29], [71, -18]],
    [[58, -44], [71, -41]]
  ];

  // Draw internal cleavage refraction ribbons first (the 1.2mm wall thickness of the crack)
  brush.noStroke();
  for (let path of crackPaths) {
    for (let i = 0; i < path.length - 1; i++) {
      let c = clipSegment(
        path[i][0], path[i][1],
        path[i + 1][0], path[i + 1][1],
        -59, -62.5, 71, 62.5
      );
      if (!c) continue;
      let z1 = lidZ(c[0], c[1]), z2 = lidZ(c[2], c[3]);
      let p1Top = proj(c[0], c[1], z1);
      let p2Top = proj(c[2], c[3], z2);
      let p2Bot = proj(c[2], c[3], z2 - 1.15);
      let p1Bot = proj(c[0], c[1], z1 - 1.15);

      let ribCol = (i % 2 === 0) ? "#bdf6ff" : "#f2d6ff";
      brush.wash(ribCol, 95);
      drawPoly([p1Top, p2Top, p2Bot, p1Bot]);
    }
  }
  brush.noWash();

  // Draw technical pen dark hairline fractures + bottom-surface twin line + hard white glints
  for (let pIdx = 0; pIdx < crackPaths.length; pIdx++) {
    let path = crackPaths[pIdx];
    let isMajor = pIdx < 7;

    for (let i = 0; i < path.length - 1; i++) {
      let c = clipSegment(
        path[i][0], path[i][1],
        path[i + 1][0], path[i + 1][1],
        -59, -62.5, 71, 62.5
      );
      if (!c) continue;
      let z1 = lidZ(c[0], c[1]);
      let z2 = lidZ(c[2], c[3]);

      // 1. Bottom surface cleavage shadow line (Z - 1.1mm)
      brush.set("tech_needle", "#51486b", isMajor ? 0.34 : 0.24);
      draw3DLine(c[0], c[1], z1 - 1.1, c[2], c[3], z2 - 1.1);

      // 2. Top surface dark technical pen fracture line
      brush.set("tech_needle", "#2e2640", isMajor ? 0.44 : 0.3);
      draw3DLine(c[0], c[1], z1, c[2], c[3], z2);

      // 3. Hard white fluorescent glint along the upper bevel of the crack
      brush.set("glint_pen", "#ffffff", isMajor ? 0.62 : 0.42);
      draw3DLine(c[0] + 0.35, c[1] - 0.35, z1 + 0.15, c[2] + 0.35, c[3] - 0.35, z2 + 0.15);
    }

    // Bright specular star-glints at fracture vertices and bifurcations
    for (let v of path) {
      if (v[0] >= -59 && v[0] <= 71 && v[1] >= -62.5 && v[1] <= 62.5) {
        let zv = lidZ(v[0], v[1]) + 0.2;
        brush.set("glint_pen", "#ffffff", 0.58);
        draw3DLine(v[0] - 1.4, v[1] - 0.4, zv, v[0] + 1.4, v[1] + 0.4, zv);
        draw3DLine(v[0] - 0.4, v[1] - 1.4, zv, v[0] + 0.4, v[1] + 1.4, zv);
      }
    }
  }

  // Crushed micro-splinter crazing at the primary impact center (-8, 10)
  for (let i = 0; i < 28; i++) {
    let a = i * (360 / 28) + random(-6, 6);
    let r1 = random(0.8, 3.5);
    let r2 = r1 + random(2.5, 8.5);
    let x1 = -8 + cos(a) * r1, y1 = 10 + sin(a) * r1;
    let x2 = -8 + cos(a) * r2, y2 = 10 + sin(a) * r2;
    let z = lidZ(-8, 10);
    brush.set("tech_needle", "#3b3252", 0.26);
    draw3DLine(x1, y1, z, x2, y2, z);
    brush.set("glint_pen", "#ffffff", 0.45);
    draw3DLine(x1 + 0.2, y1 - 0.2, z + 0.15, x2 + 0.2, y2 - 0.2, z + 0.15);
  }

  // Parallel stress crazing hairlines along major fractures
  for (let i = 0; i < 36; i++) {
    let baseX = random(-45, 58);
    let baseY = random(-50, 50);
    let len = random(4, 14);
    let ang = random([-38, 12, 42, -72]) + random(-6, 6);
    let x2 = baseX + cos(ang) * len;
    let y2 = baseY + sin(ang) * len;
    let c = clipSegment(baseX, baseY, x2, y2, -58, -61, 70, 61);
    if (c) {
      let z = lidZ(c[0], c[1]);
      brush.set("tech_needle", "#7785a0", 0.2);
      draw3DLine(c[0], c[1], z, c[2], c[3], z);
      brush.set("glint_pen", "#ffffff", 0.28);
      draw3DLine(c[0] + 0.25, c[1] - 0.25, z + 0.1, c[2] + 0.25, c[3] - 0.25, z + 0.1);
    }
  }

  // -------------------------------------------------------------------------
  // 6E. SURFACE SCUFFS, SWIRL SCRATCHES & SPECULAR DUST GLINTS ON CLEAR PLASTIC
  // -------------------------------------------------------------------------
  // Linear shelf-wear scuffs (drawn in fine technical pen catching cold white glints)
  for (let i = 0; i < 85; i++) {
    let sx = random(-66, 66);
    let sy = random(-59, 59);
    // Cluster scuffs realistically along the high-wear middle and edges
    let ang = (i % 4 === 0) ? random(-15, 15) : random(75, 105);
    let len = random(5, 26);
    let ex = sx + cos(ang) * len;
    let ey = sy + sin(ang) * len;
    let c = clipSegment(sx, sy, ex, ey, -69, -61, 69, 61);
    if (!c) continue;

    let z1 = lidZ(c[0], c[1]);
    let z2 = lidZ(c[2], c[3]);

    brush.set("tech_needle", "#8c9ab3", 0.18);
    draw3DLine(c[0], c[1], z1, c[2], c[3], z2);

    // Scuffs crossing the fluorescent reflection zones catch hard white glints
    if (noise(c[0] * 0.05, c[1] * 0.05) > 0.35) {
      brush.set("glint_pen", "#ffffff", random(0.22, 0.38));
      draw3DLine(c[0] + 0.2, c[1] - 0.2, z1 + 0.08, c[2] + 0.2, c[3] - 0.2, z2 + 0.08);
    }
  }

  // Fine arcuate cleaning/handling swirl scratches on the plastic lid
  for (let i = 0; i < 28; i++) {
    let cx = random(-42, 52);
    let cy = random(-42, 42);
    let r = random(6, 22);
    let aStart = random(0, 360);
    let aSpan = random(25, 65);
    if (cx - r > -58 && cx + r < 69 && cy - r > -60 && cy + r < 60) {
      let z = lidZ(cx, cy);
      brush.set("glint_pen", "#ffffff", 0.24);
      safeSpline(getArc3DPoints(cx, cy, z, r, aStart, aStart + aSpan, 8, true), 0.5);
    }
  }

  // Tiny pinpoint white glints on plastic corners, fractures & dust motes
  let keyGlints = [
    [-8, 10, lidZ(-8, 10) + 0.3, 2.6],
    [27, -18, lidZ(27, -18) + 0.2, 2.0],
    [31, 11, lidZ(31, 11) + 0.2, 2.0],
    [-22, -2, lidZ(-22, -2) + 0.2, 1.8],
    [71, 19, lidZ(71, 19) + 0.2, 2.2],
    [71, 62.5, lidZ(71, 62.5) + 0.2, 2.5],
    [-71, 62.5, lidZ(-71, 62.5) + 0.2, 2.0],
    [62 + 60 * cos(-18), 4 + 60 * sin(-18), 7.7, 2.6],
    [62 + 42 * cos(-14), 4 + 42 * sin(-14), 7.7, 2.2]
  ];
  for (let g of keyGlints) {
    let p = proj(g[0], g[1], g[2]);
    let s = g[3] * 3.2;
    brush.set("glint_pen", "#ffffff", 0.65);
    brush.line(p[0] - s, p[1], p[0] + s, p[1]);
    brush.line(p[0], p[1] - s, p[0], p[1] + s);
    brush.set("glint_pen", "#e6faff", 0.42);
    brush.line(p[0] - s * 0.65, p[1] - s * 0.65, p[0] + s * 0.65, p[1] + s * 0.65);
    brush.line(p[0] - s * 0.65, p[1] + s * 0.65, p[0] + s * 0.65, p[1] - s * 0.65);
  }

  brush.noStroke();
}

