function draw() {
  translate(-width / 2, -height / 2);

  // Bone-white warm archival paper ground; zero washes or fills anywhere
  background("#f3eee3");
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noField();

  const INK_DEEP = "#0c0a09";
  const INK_MAIN = "#13110e";
  const INK_FINE = "#1a1714";
  const INK_WHISPER = "#241f1b";

  // =========================================================================
  // 1. BUILD 3D / 2D STACK GEOMETRY (Disk 0 = Top Askew Record, Disks 1..65 = Stack)
  // =========================================================================
  const discs = [];

  // Disk 0: The top record sitting askew, tilted toward the viewer to expose its grooved face
  discs.push(createDisc({
    index: 0,
    cx: 572,
    cy: 384,
    rx: 438,
    ry: 438 * 0.612, // 268.0 px minor radius
    rotDeg: -8.6,
    thick: 8.2,
    isTop: true,
    grooveSeed: 100
  }));

  // Disks 1..65: Tall vertical stack seen edge-on and slightly from above
  const numStack = 65;
  let curY = 410;
  let baseStackX = 620;
  let clusterOffsetX = 0;
  let clusterOffsetY = 0;

  for (let i = 1; i <= numStack; i++) {
    const t = (i - 1) / (numStack - 1);

    // Natural sub-clusters + occasional dramatic protruding records ("ledges")
    if (i % 5 === 1) {
      clusterOffsetX = random(-12, 14);
      clusterOffsetY = random(-3, 4);
    }

    let jutX = 0;
    let jutY = 0;
    // Curated dramatic juts so several records expose wider grooved crescent lips
    if (i === 4 || i === 11 || i === 19 || i === 27 || i === 36 || i === 44 || i === 53 || i === 60) {
      jutX = (i % 2 === 0 ? 1 : -1) * random(16, 31);
      jutY = random(5, 11);
    } else if (i === 15 || i === 31 || i === 48) {
      jutX = random(-24, -14);
      jutY = random(4, 9);
    }

    const microX = (noise(i * 0.35, 1.2) - 0.5) * 18;
    const microY = (noise(i * 0.45, 5.7) - 0.5) * 5;

    const cx = baseStackX + clusterOffsetX + jutX + microX;
    const cy = curY + clusterOffsetY * 0.35 + jutY + microY;

    // Slight perspective steepening from top to bottom of the tall stack
    const aspect = 0.376 + t * 0.044 + (noise(i * 0.2, 9.1) - 0.5) * 0.008;
    const rx = 432 + random(-2.5, 2.5);
    const ry = rx * aspect;

    // Subtle per-record tilt variation in the stack
    const rotDeg = (noise(i * 0.28, 3.4) - 0.5) * 2.2 + (jutX * 0.025);

    // Varying 140g vs 180g vinyl thicknesses
    const isHeavy = (i % 7 === 0 || i === 19 || i === 36);
    const thick = isHeavy ? 8.3 : random(6.7, 7.6);

    discs.push(createDisc({
      index: i,
      cx,
      cy,
      rx,
      ry,
      rotDeg,
      thick,
      isTop: false,
      grooveSeed: i * 37 + 11
    }));

    curY += thick + random(0.55, 1.35);
  }

  // Helper to construct a disc with precomputed trig and bounding box
  function createDisc(params) {
    const rad = (params.rotDeg * Math.PI) / 180;
    const cosR = Math.cos(rad);
    const sinR = Math.sin(rad);
    const rx = params.rx;
    const ry = params.ry;
    // Exact bounding box of rotated ellipse + thickness
    const extX = Math.sqrt(rx * rx * cosR * cosR + ry * ry * sinR * sinR);
    const extY = Math.sqrt(rx * rx * sinR * sinR + ry * ry * cosR * cosR);
    return {
      ...params,
      rad,
      cosR,
      sinR,
      minX: params.cx - extX - 2,
      maxX: params.cx + extX + 2,
      minY: params.cy - extY - 2,
      maxY: params.cy + extY + params.thick + 2
    };
  }

  // =========================================================================
  // 2. EXACT ANALYTICAL OCCLUSION & SHADOW ENGINE
  // =========================================================================
  // Maps local disc polar coordinates (r, thetaRad, zOffset) to screen (x, y)
  function discPoint(d, r, theta, zOff = 0) {
    const u = r * Math.cos(theta);
    const v = r * (d.ry / d.rx) * Math.sin(theta);
    const x = d.cx + u * d.cosR - v * d.sinR;
    const y = d.cy + u * d.sinR + v * d.cosR + zOff;
    return [x, y];
  }

  // Fast test: is screen point (x, y) inside the 3D silhouette of disc d?
  function isInsideDisc(x, y, d, pad = 0) {
    if (
      y < d.minY - pad ||
      y > d.maxY + pad ||
      x < d.minX - pad ||
      x > d.maxX + pad
    ) {
      return false;
    }
    const dx = x - d.cx;
    const dy = y - d.cy;
    const u = dx * d.cosR + dy * d.sinR;
    const v = -dx * d.sinR + dy * d.cosR;
    const rx = d.rx + pad;
    const ry = d.ry + pad;
    if (Math.abs(u) > rx) return false;

    const uNorm2 = (u * u) / (rx * rx);
    if (v <= 0) {
      return uNorm2 + (v * v) / (ry * ry) <= 1.0;
    }
    const dyBot = y - (d.cy + d.thick);
    const uBot = dx * d.cosR + dyBot * d.sinR;
    const vBot = -dx * d.sinR + dyBot * d.cosR;
    if (vBot >= 0) {
      return (uBot * uBot) / (rx * rx) + (vBot * vBot) / (ry * ry) <= 1.0;
    }
    return true;
  }

  // Test if (x, y) on disc `maxIdx` is occluded by any disc `0 <= k < maxIdx`
  function isOccluded(x, y, maxIdx, pad = -0.15) {
    if (maxIdx <= 0) return false;
    // Check Disk 0 (top askew record) first since it covers the largest area
    if (isInsideDisc(x, y, discs[0], pad)) return true;
    // Then check immediate neighbors above maxIdx downwards
    for (let k = maxIdx - 1; k >= 1; k--) {
      if (isInsideDisc(x, y, discs[k], pad)) return true;
    }
    return false;
  }

  // Test how deeply (x, y) on disc `idx` is inside a cast shadow from discs above it
  // Returns shadow factor 0.0 (lit) to 1.0 (deep overhang shadow)
  function getCastShadow(x, y, idx) {
    if (idx <= 0) return 0.0;
    let shadow = 0.0;

    // 1. Cast shadow from the askew top record (Disk 0) onto the upper stack
    const d0 = discs[0];
    const dz0 = Math.max(0, y - d0.cy);
    if (dz0 > 0 && dz0 < 310) {
      // Directional light from upper-right-front casts shadow downward and slightly left
      const sx0 = x + dz0 * 0.14;
      const sy0 = y - dz0 * 0.26;
      if (isInsideDisc(sx0, sy0, d0, -2.0)) {
        shadow = Math.max(shadow, mapConstrain(dz0, 0, 260, 0.95, 0.45));
      } else if (isInsideDisc(sx0, sy0, d0, 8.0)) {
        shadow = Math.max(shadow, 0.35);
      }
    }

    // 2. Local overhang cast shadow from discs immediately above `idx` (e.g. idx-1, idx-2, idx-3)
    const startK = Math.max(1, idx - 5);
    for (let k = idx - 1; k >= startK; k--) {
      const dk = discs[k];
      const dzk = (idx - k) * 7.8;
      const sx = x + dzk * 0.18;
      const sy = y - dzk * 0.48;
      if (isInsideDisc(sx, sy, dk, 1.5)) {
        const sVal = k === idx - 1 ? 0.92 : 0.65;
        shadow = Math.max(shadow, sVal);
      }
    }
    return shadow;
  }

  function mapConstrain(val, inMin, inMax, outMin, outMax) {
    const t = Math.max(0, Math.min(1, (val - inMin) / (inMax - inMin)));
    return outMin + t * (outMax - outMin);
  }

  // Safely render a polyline of [x, y, pressure] clipped against discs[0 .. occluderIdx - 1]
  function drawClippedCurve(pts, occluderIdx, curvature = 0.35) {
    let currentSeg = [];

    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      const x = p[0];
      const y = p[1];
      const pr = p[2] !== undefined ? p[2] : 1.0;

      const vis = pr > 0.04 && !isOccluded(x, y, occluderIdx);

      if (vis) {
        // If emerging from occlusion, refine boundary point via midpoint bisection
        if (currentSeg.length === 0 && i > 0) {
          const prev = pts[i - 1];
          const prevPr = prev[2] !== undefined ? prev[2] : 1.0;
          if (prevPr > 0.04) {
            const mx = 0.5 * (prev[0] + x);
            const my = 0.5 * (prev[1] + y);
            if (!isOccluded(mx, my, occluderIdx)) {
              currentSeg.push([mx, my, (prevPr + pr) * 0.5]);
            }
          }
        }
        currentSeg.push([x, y, pr]);
      } else {
        if (currentSeg.length > 0) {
          // If entering occlusion, refine exit boundary point
          const last = currentSeg[currentSeg.length - 1];
          if (pr > 0.04) {
            const mx = 0.5 * (last[0] + x);
            const my = 0.5 * (last[1] + y);
            if (!isOccluded(mx, my, occluderIdx)) {
              currentSeg.push([mx, my, (last[2] + pr) * 0.5]);
            }
          }
          flushSegment(currentSeg, curvature);
          currentSeg = [];
        }
      }
    }
    if (currentSeg.length > 0) {
      flushSegment(currentSeg, curvature);
    }
  }

  function flushSegment(seg, curvature) {
    // Filter out points too close together to prevent spline artifacts
    const clean = [seg[0]];
    for (let i = 1; i < seg.length; i++) {
      const dx = seg[i][0] - clean[clean.length - 1][0];
      const dy = seg[i][1] - clean[clean.length - 1][1];
      if (dx * dx + dy * dy >= 1.2) {
        clean.push(seg[i]);
      }
    }
    if (clean.length < 2) return;
    if (clean.length === 2) {
      brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    } else {
      brush.spline(clean, curvature);
    }
  }

  // Shortest angular distance in radians between a and b
  function angleDiff(a, b) {
    let d = (a - b) % (Math.PI * 2);
    if (d > Math.PI) d -= Math.PI * 2;
    if (d < -Math.PI) d += Math.PI * 2;
    return Math.abs(d);
  }

  // =========================================================================
  // 3. RENDER THE TOP ASKEW RECORD (DISK 0): BRIDGET RILEY MOIRÉ & SPECULAR FAN
  // =========================================================================
  const d0 = discs[0];
  const R_OUTER = d0.rx;          // 438 px
  const R_RIM_INNER = 429.5;      // Outer raised rim guard
  const R_MUSIC_MAX = 421.0;      // Start of recorded grooves
  const R_MUSIC_MIN = 186.0;      // End of recorded grooves
  const R_LABEL = 140.0;          // Blank cream paper label radius
  const R_HOLE = 15.2;            // Crisp center spindle hole radius

  // Track gap intervals (the 5 narrow smooth scrolls separating the 6 tracks)
  const trackGaps = [
    [383.0, 386.2],
    [341.5, 344.5],
    [295.0, 298.4],
    [253.0, 256.0],
    [217.0, 220.0]
  ];

  function isInTrackGap(r) {
    for (let i = 0; i < trackGaps.length; i++) {
      if (r >= trackGaps[i][0] && r <= trackGaps[i][1]) return true;
    }
    return false;
  }

  // Bridget Riley phase-modulated radial wave displacement
  // Smooth angular harmonics whose phase shifts continuously with radius r,
  // causing adjacent concentric hairlines to rhythmically compress and expand.
  function rileyOffset(r, theta) {
    const w1 = Math.sin(4 * theta + r * 0.148) * 1.38;
    const w2 = Math.cos(8 * theta - r * 0.215) * 0.86;
    const w3 = Math.sin(12 * theta + r * 0.092) * 0.52;
    const w4 = Math.cos(2 * theta - r * 0.175) * 0.92;
    return w1 + w2 + w3 + w4;
  }

  // Local radial derivative of rileyOffset with respect to r:
  // negative = lines compressing together (dark moiré crest); positive = lines opening up
  function rileyCompression(r, theta) {
    const dw1 = 0.148 * 1.38 * Math.cos(4 * theta + r * 0.148);
    const dw2 = 0.215 * 0.86 * Math.sin(8 * theta - r * 0.215);
    const dw3 = 0.092 * 0.52 * Math.cos(12 * theta + r * 0.092);
    const dw4 = 0.175 * 0.92 * Math.sin(2 * theta - r * 0.175);
    return -(dw1 + dw2 + dw3 + dw4); // Positive when compressed
  }

  // Specular light model on the grooved face:
  // Broad radial bowtie band along theta = 56° (0.977 rad) and -124° (-2.164 rad)
  // plus secondary narrower radial sheen along theta = -26° (-0.454 rad) and +154° (2.688 rad)
  const LIGHT_PRIMARY_1 = (56 * Math.PI) / 180;
  const LIGHT_PRIMARY_2 = (-124 * Math.PI) / 180;
  const LIGHT_SECOND_1 = (-26 * Math.PI) / 180;
  const LIGHT_SECOND_2 = (154 * Math.PI) / 180;

  function evaluateTopGrooveLight(r, theta, ringIdx) {
    // Subtle per-track and per-groove angular feathering of the specular highlight
    const trackWave = Math.sin(r * 0.19 + ringIdx * 0.7) * 0.032 + Math.cos(r * 0.07) * 0.025;
    // Slight curvature of the radial highlight band across the tilted disc
    const radialCurve = ((r - 280) / 300) * 0.065;
    const effTheta = theta + trackWave + radialCurve;

    const dP1 = angleDiff(effTheta, LIGHT_PRIMARY_1);
    const dP2 = angleDiff(effTheta, LIGHT_PRIMARY_2);
    const dPrimary = Math.min(dP1, dP2);

    const dS1 = angleDiff(effTheta, LIGHT_SECOND_1);
    const dS2 = angleDiff(effTheta, LIGHT_SECOND_2);
    const dSecond = Math.min(dS1, dS2);

    // Core dropout half-width (~11.5 degrees = 0.20 rad), modulated slightly by groove audio energy
    const audioMod = (noise(r * 0.12, ringIdx * 0.15) - 0.5) * 0.055;
    const coreWidth = 0.195 + audioMod;
    const featherWidth = 0.52 + audioMod * 0.6;

    if (dPrimary < coreWidth) {
      return 0.0; // Lines thin to nothing inside the broad radial light band
    }

    let lightAtten = 1.0;
    if (dPrimary < featherWidth) {
      const t = (dPrimary - coreWidth) / (featherWidth - coreWidth);
      lightAtten = t * t * (3 - 2 * t); // Smoothstep from 0 at core edge to 1 outside
    }

    // Secondary narrow radial glint thins the lines to a delicate whisper
    if (dSecond < 0.24) {
      const sT = dSecond / 0.24;
      const secAtten = 0.14 + 0.86 * (sT * sT);
      lightAtten = Math.min(lightAtten, secAtten);
    }

    return lightAtten;
  }

  // --- 3A. Draw the dense concentric microgrooves on Disk 0 ---
  let rCur = R_MUSIC_MIN;
  let ringIdx = 0;
  const N_SAMPLES = 180;

  while (rCur <= R_MUSIC_MAX) {
    // Modulate base radial spacing between 0.82px and 1.68px for radial frequency shimmer
    const spacingMod = 0.5 + 0.5 * Math.sin(rCur * 0.24) * Math.cos(rCur * 0.09);
    const dr = 0.84 + spacingMod * 0.78;

    if (!isInTrackGap(rCur)) {
      // Choose pen weight tier based on track modulation & ring harmonic
      const trackDarkness = 0.85 + 0.25 * Math.sin(rCur * 0.085);
      const isAccentRing = ringIdx % 3 === 0;
      if (isAccentRing) {
        brush.set("tech_fine", INK_MAIN, 0.92);
      } else {
        brush.set("tech_hair", INK_FINE, 0.88);
      }

      const ptsMain = [];
      const ptsWhisper = [];
      const ptsCompression = [];

      for (let s = 0; s <= N_SAMPLES; s++) {
        const theta = (s / N_SAMPLES) * Math.PI * 2;
        const rDisp = rCur + rileyOffset(rCur, theta);
        const [x, y] = discPoint(d0, rDisp, theta, 0);

        const lightAtten = evaluateTopGrooveLight(rCur, theta, ringIdx);
        const comp = rileyCompression(rCur, theta); // ~ -0.6 to +0.6

        if (lightAtten <= 0.02) {
          ptsMain.push([x, y, 0]);
          ptsWhisper.push([x, y, 0]);
          ptsCompression.push([x, y, 0]);
        } else if (lightAtten < 0.34) {
          // Feather edge of the radial highlight band: ultra-thin whisper pen only
          const wPr = mapConstrain(lightAtten, 0.02, 0.34, 0.18, 0.78);
          ptsWhisper.push([x, y, wPr]);
          ptsMain.push([x, y, 0]);
          ptsCompression.push([x, y, 0]);
        } else {
          // Main groove body with Bridget Riley compression pressure boost
          const basePr = (0.62 + comp * 0.45) * trackDarkness * lightAtten;
          const pr = Math.max(0.18, Math.min(1.38, basePr));
          ptsMain.push([x, y, pr]);

          // Overlap slightly into whisper pen for seamless transition
          if (lightAtten < 0.44) {
            ptsWhisper.push([x, y, 0.55]);
          } else {
            ptsWhisper.push([x, y, 0]);
          }

          // In intense Bridget Riley compression zones, add an interleaved dark shadow doublet
          if (comp > 0.16 && lightAtten > 0.62 && ringIdx % 2 === 0) {
            const [cx2, cy2] = discPoint(d0, rDisp + 0.42, theta, 0);
            const cPr = mapConstrain(comp, 0.16, 0.58, 0.25, 1.05) * lightAtten;
            ptsCompression.push([cx2, cy2, cPr]);
          } else {
            ptsCompression.push([x, y, 0]);
          }
        }
      }

      drawClippedCurve(ptsMain, 0, 0.4);

      brush.set("tech_whisper", INK_WHISPER, 0.82);
      drawClippedCurve(ptsWhisper, 0, 0.4);

      if (ringIdx % 2 === 0) {
        brush.set("tech_hair", INK_DEEP, 0.95);
        drawClippedCurve(ptsCompression, 0, 0.4);
      }
    } else {
      // Inside a narrow track gap: sparse unmodulated mirror sheen hairlines in dark sectors only
      brush.set("tech_whisper", INK_WHISPER, 0.72);
      const ptsGap = [];
      for (let s = 0; s <= N_SAMPLES; s++) {
        const theta = (s / N_SAMPLES) * Math.PI * 2;
        const [x, y] = discPoint(d0, rCur, theta, 0);
        const lightAtten = evaluateTopGrooveLight(rCur, theta, ringIdx);
        // Track gaps reflect a slightly broader specular band than modulated grooves
        const pr = lightAtten > 0.55 ? (lightAtten - 0.55) * 1.15 : 0;
        ptsGap.push([x, y, pr]);
      }
      drawClippedCurve(ptsGap, 0, 0.4);
      rCur += 0.95; // Slightly wider step across track gap
    }

    rCur += dr;
    ringIdx++;
  }

  // --- 3B. Spiraling inter-track connector grooves across the 5 track gaps ---
  brush.set("tech_fine", INK_MAIN, 0.9);
  for (let g = 0; g < trackGaps.length; g++) {
    const rStart = trackGaps[g][1] + 0.6;
    const rEnd = trackGaps[g][0] - 0.6;
    const startAngle = g * 1.35 + 0.4;
    const spiralPts = [];
    const steps = 110;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const theta = startAngle + t * Math.PI * 1.85;
      const r = rStart + (rEnd - rStart) * t;
      const [x, y] = discPoint(d0, r, theta, 0);
      const lightAtten = evaluateTopGrooveLight(r, theta, g * 10);
      spiralPts.push([x, y, lightAtten > 0.15 ? 0.45 + 0.55 * lightAtten : 0]);
    }
    drawClippedCurve(spiralPts, 0, 0.4);
  }

  // --- 3C. Outer Beveled Rim & Lead-In Collar (r = 421 .. 438) ---
  // Lead-in mirror collar fine lines (r = 421.5 .. 429)
  for (let r = R_MUSIC_MAX + 1.2; r <= R_RIM_INNER; r += 1.65) {
    brush.set("tech_whisper", INK_FINE, 0.82);
    const pts = [];
    for (let s = 0; s <= N_SAMPLES; s++) {
      const theta = (s / N_SAMPLES) * Math.PI * 2;
      const [x, y] = discPoint(d0, r, theta, 0);
      const lightAtten = evaluateTopGrooveLight(r, theta, 999);
      pts.push([x, y, lightAtten > 0.35 ? (lightAtten - 0.3) * 0.95 : 0]);
    }
    drawClippedCurve(pts, 0, 0.4);
  }

  // Crisp lead-in spiral groove sweeping from outer rim guard into Track 1
  brush.set("tech_fine", INK_DEEP, 0.95);
  const leadInPts = [];
  for (let s = 0; s <= 90; s++) {
    const t = s / 90;
    const theta = -0.6 + t * Math.PI * 1.35;
    const r = R_RIM_INNER - t * (R_RIM_INNER - R_MUSIC_MAX);
    const [x, y] = discPoint(d0, r, theta, 0);
    const lightAtten = evaluateTopGrooveLight(r, theta, 500);
    leadInPts.push([x, y, lightAtten > 0.12 ? 0.5 + 0.5 * lightAtten : 0]);
  }
  drawClippedCurve(leadInPts, 0, 0.4);

  // Raised outer guard rim (r = 429.5 .. 438)
  for (let r = R_RIM_INNER + 0.8; r <= R_OUTER; r += 1.1) {
    const isOuterLip = r >= R_OUTER - 1.2;
    brush.set(isOuterLip ? "tech_med" : "tech_hair", isOuterLip ? INK_DEEP : INK_MAIN, 0.95);
    const pts = [];
    for (let s = 0; s <= N_SAMPLES; s++) {
      const theta = (s / N_SAMPLES) * Math.PI * 2;
      const [x, y] = discPoint(d0, r, theta, 0);
      const lightAtten = evaluateTopGrooveLight(r, theta, 888);
      // Outer contour stays faintly visible even across highlight; inner rim bevel leaves highlight ridge
      const minPr = isOuterLip ? 0.25 : 0.0;
      const pr = Math.max(minPr, lightAtten * (isOuterLip ? 1.15 : 0.9));
      pts.push([x, y, pr]);
    }
    drawClippedCurve(pts, 0, 0.4);
  }

  // --- 3D. Run-Out Dead-Wax Area (r = 140 .. 186) ---
  // Smooth glossy dead-wax mirror lines (wider spacing, wider specular reflection)
  for (let r = R_LABEL + 1.5; r < R_MUSIC_MIN; r += 2.15) {
    const isLockedGroove = Math.abs(r - (R_LABEL + 4.2)) < 1.2;
    brush.set(isLockedGroove ? "tech_fine" : "tech_whisper", isLockedGroove ? INK_MAIN : INK_WHISPER, 0.82);
    const pts = [];
    for (let s = 0; s <= 150; s++) {
      const theta = (s / 150) * Math.PI * 2;
      const [x, y] = discPoint(d0, r, theta, 0);
      const lightAtten = evaluateTopGrooveLight(r, theta, 300);
      const threshold = isLockedGroove ? 0.12 : 0.42;
      const pr = lightAtten > threshold
        ? mapConstrain(lightAtten, threshold, 1.0, 0.18, isLockedGroove ? 1.05 : 0.72)
        : 0;
      pts.push([x, y, pr]);
    }
    drawClippedCurve(pts, 0, 0.4);
  }

  // Lead-out spiral groove sweeping across dead wax into the locked groove (4.2 turns)
  brush.set("tech_fine", INK_DEEP, 0.95);
  const leadOutPts = [];
  const totalSpiralSteps = 260;
  for (let s = 0; s <= totalSpiralSteps; s++) {
    const t = s / totalSpiralSteps;
    const theta = 0.8 + t * Math.PI * 2 * 4.15;
    const r = R_MUSIC_MIN - Math.pow(t, 0.88) * (R_MUSIC_MIN - (R_LABEL + 4.2));
    const [x, y] = discPoint(d0, r, theta, 0);
    const lightAtten = evaluateTopGrooveLight(r, theta, 700);
    leadOutPts.push([x, y, lightAtten > 0.10 ? 0.38 + 0.68 * lightAtten : 0]);
  }
  drawClippedCurve(leadOutPts, 0, 0.4);

  // Tiny hand-etched matrix numbers in the dead-wax collar (r ~ 160)
  brush.set("tech_whisper", INK_FINE, 0.75);
  const matrixAngles = [1.45, 1.52, 1.58, 1.65, 1.74, 1.80, 1.86, 1.93, 2.02, 2.08];
  for (let m = 0; m < matrixAngles.length; m++) {
    const a = matrixAngles[m];
    const rM = 158 + (m % 2) * 1.5;
    const [x1, y1] = discPoint(d0, rM - 3.2, a, 0);
    const [x2, y2] = discPoint(d0, rM + 3.2, a + 0.018, 0);
    const [x3, y3] = discPoint(d0, rM, a - 0.015, 0);
    brush.line(x1, y1, x2, y2);
    if (m % 2 === 0) brush.line(x2, y2, x3, y3);
  }

  // --- 3E. Blank Cream Paper Label (r = 15.2 .. 140) & Crisp Spindle Hole ---
  // Delicate edge contour where the blank cream paper label meets the black vinyl
  brush.set("tech_hair", INK_MAIN, 0.85);
  const labelBorderPts = [];
  for (let s = 0; s <= 120; s++) {
    const theta = (s / 120) * Math.PI * 2;
    const [x, y] = discPoint(d0, R_LABEL, theta, 0);
    const lightAtten = evaluateTopGrooveLight(R_LABEL, theta, 0);
    labelBorderPts.push([x, y, 0.25 + 0.65 * lightAtten]);
  }
  drawClippedCurve(labelBorderPts, 0, 0.4);

  // Subtle circular stamper pressing ridge on the blank cream label at r = 68 (broken whisper arc)
  brush.set("tech_whisper", INK_WHISPER, 0.60);
  const stamperPts = [];
  for (let s = 0; s <= 100; s++) {
    const theta = (s / 100) * Math.PI * 2;
    const [x, y] = discPoint(d0, 68, theta, 0);
    const dShadow = angleDiff(theta, -0.55);
    const pr = dShadow < 1.1 ? (1.1 - dShadow) * 0.42 : 0;
    stamperPts.push([x, y, pr]);
  }
  drawClippedCurve(stamperPts, 0, 0.4);

  // Crisp Spindle Hole at Center (r = 15.2):
  // 1. Dark abyss inside the hole rendered purely through multi-angle tight cross-hatching
  const holeRx = R_HOLE;
  const holeRy = R_HOLE * (d0.ry / d0.rx);
  const wallDepth = 5.4; // Visible thickness of top record inside the spindle hole

  function isInsideSpindleTop(x, y) {
    const dx = x - d0.cx;
    const dy = y - d0.cy;
    const u = dx * d0.cosR + dy * d0.sinR;
    const v = -dx * d0.sinR + dy * d0.cosR;
    return (u * u) / (holeRx * holeRx) + (v * v) / (holeRy * holeRy) <= 0.96;
  }

  function isInsideSpindleShaft(x, y) {
    const dx = x - d0.cx;
    const dy = y - (d0.cy + wallDepth);
    const u = dx * d0.cosR + dy * d0.sinR;
    const v = -dx * d0.sinR + dy * d0.cosR;
    return (u * u) / (holeRx * holeRx) + (v * v) / (holeRy * holeRy) <= 1.0;
  }

  // Vertical contour shading on the inner cylindrical wall of the spindle hole
  brush.set("tech_hair", INK_MAIN, 0.85);
  for (let s = 0; s < 64; s++) {
    const theta = (s / 64) * Math.PI * 2;
    // Top rim of hole casts shadow onto upper wall (sin(theta) < 0 in screen space)
    const [x1, y1] = discPoint(d0, R_HOLE - 0.4, theta, 0.5);
    const [x2, y2] = discPoint(d0, R_HOLE - 0.4, theta, wallDepth);
    if (y1 < d0.cy + 2) {
      // Leave a tiny 1.2px white paper label edge at top, ink the vinyl wall below
      constlightWall = angleDiff(theta, -1.1) < 0.45;
      if (!constlightWall) {
        brush.line(x1, y1 + 1.1, x2, y2);
      }
    }
  }

  // Deep cross-hatched interior of the spindle hole shaft (3 dense directional passes)
  const hatchAngles = [0.22, -0.45, 1.15];
  for (let pass = 0; pass < hatchAngles.length; pass++) {
    brush.set(pass === 0 ? "tech_med" : "tech_fine", INK_DEEP, 0.95);
    const ang = hatchAngles[pass];
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const step = pass === 0 ? 1.05 : 1.25;
    for (let d = -holeRx - 4; d <= holeRx + 4; d += step) {
      let inRun = false;
      let sx = 0, sy = 0, ex = 0, ey = 0;
      for (let t = -holeRx - 4; t <= holeRx + 4; t += 0.6) {
        const px = d0.cx + d * ca - t * sa;
        const py = d0.cy + d * sa + t * ca;
        // Shaft interior is where point is inside top hole opening AND inside bottom shaft ellipse
        const inside = isInsideSpindleTop(px, py) && (pass === 0 ? isInsideSpindleShaft(px, py) : true);
        if (inside) {
          if (!inRun) {
            inRun = true;
            sx = px;
            sy = py;
          }
          ex = px;
          ey = py;
        } else if (inRun) {
          inRun = false;
          if ((ex - sx) * (ex - sx) + (ey - sy) * (ey - sy) > 1.0) {
            brush.line(sx, sy, ex, ey);
          }
        }
      }
      if (inRun && (ex - sx) * (ex - sx) + (ey - sy) * (ey - sy) > 1.0) {
        brush.line(sx, sy, ex, ey);
      }
    }
  }

  // Crisp inner bottom lip of the spindle hole
  brush.set("tech_fine", INK_DEEP, 0.95);
  const holeBotPts = [];
  for (let s = 0; s <= 60; s++) {
    const theta = (s / 60) * Math.PI * 2;
    const [x, y] = discPoint(d0, R_HOLE, theta, wallDepth);
    if (isInsideSpindleTop(x, y)) {
      holeBotPts.push([x, y, 0.95]);
    } else {
      holeBotPts.push([x, y, 0]);
    }
  }
  drawClippedCurve(holeBotPts, 0, 0.35);

  // Razor-sharp top rim contour of the spindle hole
  brush.set("tech_med", INK_DEEP, 1.0);
  const holeTopPts = [];
  for (let s = 0; s <= 72; s++) {
    const theta = (s / 72) * Math.PI * 2;
    const [x, y] = discPoint(d0, R_HOLE, theta, 0);
    holeTopPts.push([x, y, 1.05]);
  }
  drawClippedCurve(holeTopPts, 0, 0.35);

  // --- 3F. 3D Cylindrical Outer Rim of Disk 0 ---
  renderDiscRim(d0, 0);

  // =========================================================================
  // 4. RENDER THE TALL STACK OF VINYL RECORDS (DISKS 1..65)
  // =========================================================================
  for (let idx = 1; idx < discs.length; idx++) {
    const d = discs[idx];

    // --- 4A. Exposed Top Grooved Crescent of Stack Disc `idx` ---
    // Determine how far inward from the rim this disc might be visible
    // (Upper stack discs 1..15 stick out widely on the right shoulder from under Disk 0)
    const maxInward = idx <= 16 ? 135 : 52;
    const rStart = d.rx - maxInward;
    const rStep = 1.55;

    let stackRing = 0;
    for (let r = rStart; r <= d.rx - 1.2; r += rStep) {
      const isRimGuard = r > d.rx - 8.5;
      brush.set(
        isRimGuard ? "tech_fine" : "tech_hair",
        isRimGuard ? INK_DEEP : INK_MAIN,
        0.88
      );

      const pts = [];
      const steps = 140;
      for (let s = 0; s <= steps; s++) {
        const theta = (s / steps) * Math.PI * 2;
        const rWave = r + Math.sin(6 * theta + r * 0.16 + idx) * 0.85;
        const [x, y] = discPoint(d, rWave, theta, 0);

        if (isOccluded(x, y, idx)) {
          pts.push([x, y, 0]);
          continue;
        }

        const shadow = getCastShadow(x, y, idx);
        const lightAtten = evaluateStackLight(theta, idx, r, shadow);

        if (lightAtten <= 0.04) {
          pts.push([x, y, 0]);
        } else {
          const pr = Math.min(1.35, (0.55 + shadow * 0.65) * lightAtten);
          pts.push([x, y, pr]);
        }
      }
      drawClippedCurve(pts, idx, 0.38);
      stackRing++;
    }

    // Add dense radial cross-hatching on exposed top crescents that lie inside overhang cast shadows
    brush.set("tech_hair", INK_DEEP, 0.9);
    const numShadowHatches = idx <= 16 ? 180 : 90;
    for (let h = 0; h < numShadowHatches; h++) {
      const theta = (h / numShadowHatches) * Math.PI * 2;
      const [xTest, yTest] = discPoint(d, d.rx - 4, theta, 0);
      if (isOccluded(xTest, yTest, idx)) continue;
      const sh = getCastShadow(xTest, yTest, idx);
      if (sh > 0.35) {
        const hatchPts = [];
        for (let r = d.rx - maxInward; r <= d.rx - 1; r += 4) {
          const [hx, hy] = discPoint(d, r, theta + (r - d.rx) * 0.002, 0);
          const localSh = getCastShadow(hx, hy, idx);
          hatchPts.push([hx, hy, localSh > 0.3 ? 0.55 + localSh * 0.55 : 0]);
        }
        drawClippedCurve(hatchPts, idx, 0.2);
      }
    }

    // --- 4B. 3D Cylindrical Outer Rim of Stack Disc `idx` ---
    renderDiscRim(d, idx);
  }

  // =========================================================================
  // 5. RIM RENDERER (Horizontal Striations, Specular Dropout & Vertical Cross-Hatching)
  // =========================================================================
  function evaluateStackLight(theta, idx, r, shadow) {
    // Primary vertical/radial highlight ribbon down the front-right of the stack (~57 deg)
    // with subtle Bridget Riley wave modulation down the vertical column
    const waveShift = Math.sin(idx * 0.38 + r * 0.05) * 0.055;
    const dP1 = angleDiff(theta + waveShift, LIGHT_PRIMARY_1);
    const dP2 = angleDiff(theta + waveShift, LIGHT_PRIMARY_2);
    const dPrimary = Math.min(dP1, dP2);

    const dS1 = angleDiff(theta - waveShift, LIGHT_SECOND_1);
    const dS2 = angleDiff(theta - waveShift, LIGHT_SECOND_2);
    const dSecond = Math.min(dS1, dS2);

    // Overhang shadow suppresses the specular highlight dropout
    const coreWidth = Math.max(0, 0.175 * (1.0 - shadow * 1.15));
    const featherWidth = 0.48 * (1.0 - shadow * 0.55);

    if (dPrimary < coreWidth) return 0.0;

    let atten = 1.0;
    if (dPrimary < featherWidth) {
      const t = (dPrimary - coreWidth) / Math.max(0.01, featherWidth - coreWidth);
      atten = t * t * (3 - 2 * t);
    }
    if (dSecond < 0.22 && shadow < 0.5) {
      const sT = dSecond / 0.22;
      atten = Math.min(atten, 0.18 + 0.82 * sT * sT);
    }
    return atten;
  }

  function renderDiscRim(d, idx) {
    // Front visible arc of the ellipse in local polar angle theta:
    // Because sin(theta) > 0 is the front half, we sweep from -0.25 to PI + 0.25
    const tStart = -0.22;
    const tEnd = Math.PI + 0.22;
    const rimSteps = 120;

    // 1. Top lip contour of the rim
    brush.set("tech_fine", INK_MAIN, 0.92);
    const topLipPts = [];
    for (let s = 0; s <= rimSteps; s++) {
      const theta = tStart + (s / rimSteps) * (tEnd - tStart);
      const [x, y] = discPoint(d, d.rx, theta, 0);
      const shadow = getCastShadow(x, y, idx);
      const light = evaluateStackLight(theta, idx, d.rx, shadow);
      // Taper at the far left/right tangents
      const tangentFade = Math.sin( mapConstrain(theta, tStart, tEnd, 0, Math.PI) );
      const pr = Math.max(0.12, light * 0.95 + shadow * 0.45) * tangentFade;
      topLipPts.push([x, y, pr]);
    }
    drawClippedCurve(topLipPts, idx, 0.35);

    // 2. Interior horizontal contour striations along the beveled vinyl edge (5 layers)
    const numStriations = 5;
    for (let L = 1; L <= numStriations; L++) {
      const zFrac = L / (numStriations + 1);
      const zOff = zFrac * d.thick;
      // Slight barrel bevel curve of a vinyl edge
      const bevelR = d.rx + Math.sin(zFrac * Math.PI) * 0.9;

      const isMidLine = L === 2 || L === 4;
      brush.set(isMidLine ? "tech_hair" : "tech_fine", isMidLine ? INK_FINE : INK_DEEP, 0.9);

      const linePts = [];
      for (let s = 0; s <= rimSteps; s++) {
        const theta = tStart + (s / rimSteps) * (tEnd - tStart);
        const [x, y] = discPoint(d, bevelR, theta, zOff);
        const shadow = getCastShadow(x, y, idx);
        const light = evaluateStackLight(theta, idx, bevelR, shadow);
        const tangentFade = Math.sin(mapConstrain(theta, tStart, tEnd, 0, Math.PI));

        // Cylindrical shading: darker toward left/right flanks and bottom of bevel
        const cylShade = 0.65 + 0.45 * Math.abs(Math.cos(theta)) + 0.25 * zFrac;
        let pr = light * cylShade * (0.75 + shadow * 0.55) * tangentFade;

        // Alternate striations drop out slightly earlier around the highlight for smooth gradation
        if (isMidLine && light < 0.48 && shadow < 0.4) {
          pr = 0;
        }
        linePts.push([x, y, pr]);
      }
      drawClippedCurve(linePts, idx, 0.35);
    }

    // 3. Crisp, dark bottom crevice line (under-shadow seam between this disc and the next)
    brush.set("tech_bold", INK_DEEP, 0.98);
    const botLipPts = [];
    for (let s = 0; s <= rimSteps; s++) {
      const theta = tStart + (s / rimSteps) * (tEnd - tStart);
      const [x, y] = discPoint(d, d.rx - 0.3, theta, d.thick);
      const shadow = getCastShadow(x, y, idx);
      const light = evaluateStackLight(theta, idx, d.rx, shadow);
      const tangentFade = Math.sin(mapConstrain(theta, tStart, tEnd, 0, Math.PI));
      // Bottom crevice remains continuous even across the highlight (thinning to a crisp hairline)
      const pr = (0.32 + 0.88 * Math.max(light, shadow * 0.85)) * tangentFade;
      botLipPts.push([x, y, pr]);
    }
    drawClippedCurve(botLipPts, idx, 0.35);

    // 4. Short vertical / oblique contour cross-hatching along the dark flanks & shadow zones of the rim
    brush.set("tech_hair", INK_DEEP, 0.88);
    const hatchCount = 115;
    for (let h = 0; h <= hatchCount; h++) {
      const theta = tStart + 0.08 + (h / hatchCount) * (tEnd - tStart - 0.16);
      const [xTop, yTop] = discPoint(d, d.rx, theta, 0.4);
      if (isOccluded(xTop, yTop, idx)) continue;

      const shadow = getCastShadow(xTop, yTop, idx);
      const light = evaluateStackLight(theta, idx, d.rx, shadow);
      const flankDarkness = Math.abs(Math.cos(theta)); // Strongest on left and right curving flanks

      // Draw vertical/oblique rim hatch if in flank shadow or cast shadow, and outside the specular highlight
      if (light > 0.55 && (flankDarkness > 0.32 || shadow > 0.38)) {
        const [xBot, yBot] = discPoint(d, d.rx, theta + 0.008, d.thick - 0.4);
        if (!isOccluded(xBot, yBot, idx)) {
          brush.line(xTop, yTop, xBot, yBot);
        }
      }
    }
  }

  // =========================================================================
  // 6. GROUNDING CONTACT SHADOW UNDER THE BOTTOM RECORD OF THE STACK
  // =========================================================================
  const dLast = discs[discs.length - 1];
  const lastIdx = discs.length;

  // Crisp horizontal and feathered oblique ink lines directly beneath Disk 65
  for (let layer = 1; layer <= 9; layer++) {
    const zOff = dLast.thick + layer * 1.35;
    brush.set(layer <= 3 ? "tech_med" : layer <= 6 ? "tech_fine" : "tech_whisper", INK_DEEP, 0.9);
    const pts = [];
    const steps = 100;
    for (let s = 0; s <= steps; s++) {
      const theta = 0.08 + (s / steps) * (Math.PI - 0.16);
      // Contact shadow shifts slightly left away from upper-right light
      const rSpread = dLast.rx + layer * 0.8;
      const [x, y] = discPoint(dLast, rSpread, theta, zOff);
      const sx = x - layer * 1.1;
      const fade = Math.sin(((theta - 0.08) / (Math.PI - 0.16)) * Math.PI);
      const layerFade = 1.0 - (layer - 1) / 9.5;
      const pr = fade * layerFade * (1.15 - 0.35 * Math.sin(theta));
      pts.push([sx, y, pr > 0.12 ? pr : 0]);
    }
    drawClippedCurve(pts, lastIdx, 0.35);
  }

  noLoop();
}

// Hyperrealism in p5.brush: Pawnshop Window at Twilight — Gold Signet Ring on Burgundy Velvet

const BX = 585;
const BY = 625;
const BANG = -14; // Tilt of the signet ring in degrees

function rad(deg) {
  return (deg * Math.PI) / 180;
}

// Transform from ring-local (u, v) coordinates to canvas (x, y)
// u: horizontal axis (pointing right toward the shank/band)
// v: vertical axis (tall axis of the heraldic bezel)
function ringPt(u, v) {
  const a = rad(BANG);
  const ca = Math.cos(a);
  const sa = Math.sin(a);
  return [BX + u * ca - v * sa, BY + u * sa + v * ca];
}

// Cushion-oval radius multiplier (classic aristocratic signet profile)
function cushionR(thetaDeg) {
  const t = rad(thetaDeg);
  const s2 = Math.sin(2 * t);
  return 1.0 + 0.055 * (s2 * s2);
}

// Point on a cushion-oval in ring-local (u, v) space, returned in canvas (x, y)
function bezelPt(thetaDeg, ru, rv, du = 0, dv = 0) {
  const t = rad(thetaDeg);
  const r = cushionR(thetaDeg);
  const u = du + ru * r * Math.cos(t);
  const v = dv + rv * r * Math.sin(t);
  return ringPt(u, v);
}

// Draw a closed polygon using beginShape/vertex/endShape
function drawShapePoly(pts, curvature = 0.05) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Check if a ring-local point (u, v) is inside the flat bezel table
function insideBezelTable(u, v, ru = 132, rv = 164) {
  const t = Math.atan2(v / rv, u / ru);
  const deg = (t * 180) / Math.PI;
  const rMax = cushionR(deg);
  const norm = Math.hypot(u / ru, v / rv);
  return norm <= rMax * 0.96;
}

// Spatial wear map across the bezel face (0 = crisp deep intaglio, 1 = heavily worn/rubbed smooth)
function bezelWear(u, v) {
  // Lower-left and lower-right edges of the signet face are worn from decades of wear
  const d1 = Math.exp(-((u + 58) * (u + 58) + (v - 62) * (v - 62)) / 4200);
  const d2 = Math.exp(-((u - 64) * (u - 64) + (v - 48) * (v - 48)) / 5000);
  const d3 = Math.max(0, (v - 55) / 110) * 0.55;
  return Math.min(0.92, d1 * 0.72 + d2 * 0.65 + d3);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7419);
  noiseSeed(7419);

  // Custom brush for out-of-focus foreground glass lettering & bokeh
  brush.add("blur_marker", {
    type: "default",
    weight: 13,
    scatter: 0.35,
    sharpness: 0.11,
    grain: 0.06,
    opacity: 30,
    spacing: 0.16,
    pressure: [0.85, 1.0, 0.85],
    rotate: "none",
    noise: 0.18
  });

  // Finer soft brush for out-of-focus serifs, outlines & twilight reflections
  brush.add("blur_fine", {
    type: "default",
    weight: 5.5,
    scatter: 0.25,
    sharpness: 0.16,
    grain: 0.08,
    opacity: 38,
    spacing: 0.16,
    pressure: [0.75, 1.0, 0.75],
    rotate: "none",
    noise: 0.22
  });

  // Crisp chisel-like marker for layered ochre, raw sienna & warm white gold flashes
  brush.add("gold_marker", {
    type: "marker",
    weight: 6.5,
    scatter: 0.05,
    opacity: 155,
    spacing: 0.18,
    pressure: [0.65, 1.1, 0.65],
    markerTip: false,
    noise: 0.12
  });

  // Plush dry brush for burgundy velvet pile
  brush.add("velvet_nap", {
    type: "default",
    weight: 3.2,
    scatter: 0.75,
    sharpness: 0.42,
    grain: 0.78,
    opacity: 52,
    spacing: 0.32,
    pressure: [0.35, 1.1, 0.3],
    rotate: "natural",
    noise: 0.55
  });

  // Vector field for velvet drapery flow
  brush.addField("velvet_drape", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const nx = col / field.length;
        const ny = row / field[0].length;
        const angle =
          -24 +
          38 * Math.sin(nx * 3.8 + ny * 2.6) +
          22 * Math.cos(nx * 2.1 - ny * 4.2);
        field[col][row] = angle;
      }
    }
    return field;
  });

  // Vector field for faint twilight window streaks
  brush.addField("twilight_glass", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const nx = col / field.length;
        const ny = row / field[0].length;
        field[col][row] = 74 + 6 * Math.sin(nx * 4.0 + ny * 3.0);
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep Burgundy Velvet Pad & Pile
  drawVelvetBackground();

  // 2. Vintage Pawnshop Tag & Knotted String (Commerce & Heirloom)
  drawPawnTagAndStringUnder();

  // 3. The Razor-Sharp Gold Signet Ring
  drawGoldSignetRing();

  // 4. Foreground Loop of the Pawn String on the Lower Shank
  drawPawnStringLoopOverRing();

  // 5. Ghostly Twilight Street & Passer-by Reflection on the Glass
  drawTwilightStreetAndPasserby();

  // 6. Foreground Glass: Mirror-Reversed Gilded Lettering (Cobalt Shadow & Black Outline, Out of Focus)
  drawBlurredGildedWindowSignage();

  // 7. Final Glass Surface Incidents, Dust & Twilight Vignette
  drawWindowGlassFinish();

  noLoop();
}

