    // Local ridge brightness
    const ridge =
      Math.sin(x * 0.0075 + y * 0.009) * Math.cos(x * 0.004 - y * 0.011);
    const inCaustic =
      dist(x, y, 475, 725) < 125 || dist(x, y, 650, 470) < 95;

