    } else if (ridge > 0.22) {
      fCol = random(["#a8324e", "#c44966", "#8c3b5a", "#b05875", "#7d1c36"]);
    } else if (ridge > -0.15) {
      fCol = random(["#5e1126", "#731730", "#4a0c1d", "#4c243d"]);
    } else {
      fCol = random(["#1f030b", "#2e0612", "#140207", "#210e24"]);
    }

    // Upright tiny velvet pile tuft
    const tuftLen = map(radDist, 115, 470, random(3.5, 7.5), random(6, 12));
    const tuftAng = -65 + 25 * Math.sin(x * 0.01 + y * 0.01) + random(-18, 18);
    const x2 = x + tuftLen * Math.cos(rad(tuftAng));
    const y2 = y + tuftLen * Math.sin(rad(tuftAng));

    const bName = radDist < 310 ? "cpencil" : "2B";
    const bWeight = map(radDist, 115, 470, random(0.32, 0.58), random(0.5, 0.85));
    brush.set(bName, fCol, bWeight);
    brush.line(x, y, x2, y2);
  }

  // Deep contact shadow directly beneath the ring bezel and shank
  brush.noStroke();
  const shadowPoly = [
    ringPt(-130, 125),
    ringPt(-45, 198),
    ringPt(95, 195),
    ringPt(255, 130),
    ringPt(305, 55),
    ringPt(275, -20),
    ringPt(130, -35),
    ringPt(-60, 40)
  ];
  brush.wash("#080103", 215);
  drawShapePoly(shadowPoly, 0.2);
  brush.noWash();

  // Soften contact shadow perimeter with dark charcoal hatching
  brush.set("charcoal", "#0d0105", 1.1);
  for (let i = 0; i < 95; i++) {
    const t = map(i, 0, 95, -20, 195);
    const p = bezelPt(t, 158, 192, 8, 16);
    const jitter = random(8, 28);
    const a = t + BANG + random(-15, 15);
    brush.line(
      p[0],
      p[1],
      p[0] + jitter * Math.cos(rad(a)),
      p[1] + jitter * Math.sin(rad(a))
    );
  }
}

