    stringPath.map((p) => [p[0] - 0.6, p[1] - 0.8]),
    0.45
  );
}

// ============================================================================
// 3. THE RAZOR-SHARP GOLD SIGNET RING (HERO OBJECT)
// ============================================================================
function drawGoldSignetRing() {
  // 3A. THE RING BAND / SHANK & INNER APERTURE (to the right of the bezel)
  drawRingShankAndAperture();

  // 3B. THE STEPPED BEZEL CHAMFER (BEVEL RIM)
  drawBezelChamferRim();

  // 3C. THE FLAT CUSHION-OVAL BEZEL TABLE (LAYERED MARKER + PEN)
  drawBezelTableSurface();

  // 3D. THE WORN ENGRAVED HERALDIC CREST (INTAGLIO)
  drawEngravedHeraldicCrest();

  // 3E. MICRO-SCRATCHES, RIM NICKS & HOT SPECULAR FLASHES
  drawRingScratchesAndSpeculars();
}

function drawRingShankAndAperture() {
  // Outer silhouette of the ring shank extending to (+u) in ring-local coordinates
  // Upper shoulder leaves bezel around (u=35, v=-184) and arches to back of band at (u=298, v=8)
  // Lower shoulder leaves bezel around (u=42, v=186) and arches to (u=298, v=8)
  const outerShankPts = [];
  const upperCurveLocal = [
    [25, -184],
    [78, -176],
    [135, -158],
    [192, -134],
    [244, -102],
    [282, -62],
    [299, -14],
    [298, 32],
    [276, 78],
    [235, 118],
    [182, 148],
    [122, 172],
    [55, 186],
    [20, 184]
  ];
  for (const pt of upperCurveLocal) {
    outerShankPts.push(ringPt(pt[0], pt[1]));
  }

  // Base bronze/raw sienna fill of the entire shank & shoulders
  brush.noStroke();
  brush.wash("#6b370b", 245);
  drawShapePoly(outerShankPts, 0.25);
  brush.noWash();

  // Concave interior wall of the far band visible through the finger hole
  // Bounded on the left by the bezel's back gallery (u ~ 142..155)
  // and on the right by the front-inner rim of the band (u ~ 248)
  const innerWallLocal = [
    [142, -92],
    [178, -96],
    [215, -82],
    [242, -52],
    [252, -8],
    [244, 38],
    [218, 74],
    [182, 92],
    [144, 88],
    [152, 0]
  ];
  const innerWallPts = innerWallLocal.map((p) => ringPt(p[0], p[1]));

  brush.noStroke();
  brush.wash("#4a2206", 250);
  drawShapePoly(innerWallPts, 0.25);
  brush.noWash();

  // Render the vertical concave metallic gradient inside the inner band wall
  // Using layered gold_marker strokes
  for (let v = -86; v <= 84; v += 4.5) {
    const tNorm = (v + 86) / 170; // 0 at top, 1 at bottom
    // Left and right u bounds at this v
    const nv = v / 94;
    if (Math.abs(nv) >= 1) continue;
    const uLeft = 144 + 12 * (1 - nv * nv);
    const uRight = 152 + 98 * Math.sqrt(Math.max(0, 1 - nv * nv));

    let col;
    if (tNorm < 0.22) {
      col = "#2b1203"; // Cast shadow under upper shoulder overhang
    } else if (tNorm < 0.42) {
      col = "#6e380d"; // Deep raw sienna
    } else if (tNorm < 0.62) {
      col = "#b8741e"; // Warm yellow ochre bounce
    } else if (tNorm < 0.78) {
      col = "#e6ae45"; // Bright inner curve highlight
    } else {
      col = "#592b09"; // Lower inner shadow
    }

    const p1 = ringPt(uLeft, v);
    const p2 = ringPt(uRight, v + 3);
    brush.set("gold_marker", col, 0.62);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Hot specular reflection band inside the concave inner shank around v = 18..42
  for (let v = 16; v <= 42; v += 3.5) {
    const p1 = ringPt(166, v);
    const p2 = ringPt(236, v + 2);
    const col = v > 24 && v < 34 ? "#fff6d6" : "#f2c86b";
    brush.set("gold_marker", col, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Small crescent of deep burgundy velvet visible at the left-bottom of the finger hole
  const holeVelvetLocal = [
    [142, -35],
    [164, -28],
    [172, 15],
    [162, 62],
    [138, 72],
    [146, 15]
  ];
  brush.noStroke();
  brush.wash("#170208", 245);
  drawShapePoly(
    holeVelvetLocal.map((p) => ringPt(p[0], p[1])),
    0.25
  );
  brush.noWash();

  // Tiny stamped hallmark cartouche inside the inner band wall: [ 750 ] and crown mark
  const hmtl = ringPt(186, -24);
  const hmtr = ringPt(222, -20);
  const hmbr = ringPt(221, -6);
  const hmbl = ringPt(185, -10);
  brush.set("rotring", "#240e02", 0.42);
  drawShapePoly([hmtl, hmtr, hmbr, hmbl], 0.02);
  brush.set("rotring", "#f5d378", 0.35);
  brush.line(hmbl[0], hmbl[1], hmbr[0], hmbr[1]);
  brush.line(hmtr[0], hmtr[1], hmbr[0], hmbr[1]);
  // Tiny "18K" characters inside hallmark
  const c1a = ringPt(193, -20),
    c1b = ringPt(193, -11);
  const c2a = ringPt(201, -18),
    c2b = ringPt(201, -13);
  const c3a = ringPt(209, -20),
    c3b = ringPt(209, -11),
    c3c = ringPt(215, -19),
    c3d = ringPt(215, -11);
  brush.set("rotring", "#240e02", 0.36);
  brush.line(c1a[0], c1a[1], c1b[0], c1b[1]);
  brush.circle(c2a[0], c2a[1], 2.2, 0.05);
  brush.circle(c2b[0], c2b[1], 2.4, 0.05);
  brush.line(c3a[0], c3a[1], c3b[0], c3b[1]);
  brush.line(c3c[0], c3c[1], c3a[0], (c3a[1] + c3b[1]) * 0.5);
  brush.line(c3d[0], c3d[1], c3a[0], (c3a[1] + c3b[1]) * 0.5);

  // Sculpting the UPPER SHOULDER, OUTER SHANK & LOWER SHOULDER with layered marker planes
  // Parameterize longitudinal ribs from the bezel outer rim to the back of the shank
  const numStrips = 48;
  for (let i = 0; i < numStrips; i++) {
    // Angle around the right half of the ring (-82 deg to +82 deg)
    const ang = map(i, 0, numStrips - 1, -82, 82);
    const radAng = rad(ang);

    // Start point on the bevel outer edge
    const rBev = cushionR(ang);
    const uStart = 4 + 154 * rBev * Math.cos(radAng);
    const vStart = 4 + 188 * rBev * Math.sin(radAng);

    // End point along the inner aperture rim or outer band crest
    // For top shoulder (-82 to -24) and bottom shoulder (+24 to +82), lines sweep all the way to the outer band
    // For middle (-24 to +24), the finger hole interrupts the surface between u~148 and u~248!
    const uOuter = 30 + 268 * Math.cos(radAng * 0.88);
    const vOuter = 8 + 184 * Math.sin(radAng) * (1 - 0.58 * Math.cos(radAng));

    // Determine metallic color based on surface normal (ang)
    let col, weightMult;
    if (ang < -58) {
      // Top-most ridge catching twilight sky + warm display light
      col = "#d99b2e";
      weightMult = 0.72;
    } else if (ang < -36) {
      // Blazing hot specular flash along the upper shoulder swell!
      col = ang > -50 && ang < -41 ? "#fffef5" : "#fae08c";
      weightMult = 0.78;
    } else if (ang < -18) {
      // Classic dark burnished core reflection on curved gold shoulder
      col = ang < -27 ? "#4a2206" : "#8c4a12";
      weightMult = 0.68;
    } else if (ang < 12) {
      // Mid-right band bridge (raw sienna + yellow ochre)
      col = ang < -4 ? "#c98624" : "#e3a838";
      weightMult = 0.65;
    } else if (ang < 44) {
      // Lower shoulder catching burgundy velvet reflection (#5e1522) and dark bronze
      col = ang < 28 ? "#521c0c" : "#611622";
      weightMult = 0.72;
    } else if (ang < 66) {
      // Lower shoulder warm gold bounce light from velvet caustic
      col = "#b8731e";
      weightMult = 0.68;
    } else {
      // Bottom rim shadow
      col = "#381805";
      weightMult = 0.65;
    }

    if (Math.abs(ang) > 25) {
      // Continuous shoulder sweep from bezel to back of band
      const uMid = (uStart + uOuter) * 0.5 + 14;
      const vMid = (vStart + vOuter) * 0.5 * 0.92;
      const p1 = ringPt(uStart, vStart);
      const p2 = ringPt(uMid, vMid);
      const p3 = ringPt(uOuter, vOuter);
      brush.set("gold_marker", col, weightMult);
      brush.spline([p1, p2, p3], 0.35);
    } else {
      // Split by the finger aperture:
      // 1) Short bridge between bezel and aperture left edge
      // 2) Far outer band wall (from u~246 to uOuter)
      const nv = Math.sin(radAng);
      const uHoleRight = 152 + 96 * Math.sqrt(Math.max(0, 1 - nv * nv));
      const vHoleRight = vOuter * 0.85;
      const pFar1 = ringPt(uHoleRight, vHoleRight);
      const pFar2 = ringPt(uOuter, vOuter);
      brush.set("gold_marker", col, weightMult);
      brush.line(pFar1[0], pFar1[1], pFar2[0], pFar2[1]);
    }
  }

  // Extra hot white marker specular flash on the upper shoulder & far band rim
  const flashPts1 = [
    ringPt(72, -162),
    ringPt(138, -142),
    ringPt(205, -112),
    ringPt(255, -75)
  ];
  brush.set("gold_marker", "#fffdf2", 0.85);
  brush.spline(flashPts1, 0.4);
  brush.set("pen", "#ffffff", 0.9);
  brush.spline(flashPts1, 0.4);

  // Burnished pen contours around the outer shank and inner finger aperture
  brush.set("pen", "#2b1203", 0.85);
  brush.spline(outerShankPts, 0.3);

  const innerRimContour = [
    ringPt(142, -92),
    ringPt(185, -95),
    ringPt(226, -74),
    ringPt(250, -32),
    ringPt(250, 18),
    ringPt(224, 66),
    ringPt(182, 90),
    ringPt(142, 86)
  ];
  brush.set("pen", "#361704", 0.75);
  brush.spline(innerRimContour, 0.35);

  // Bright gold rim highlight along the inner aperture lip
  const innerLipHighlight = [
    ringPt(185, -93),
    ringPt(228, -72),
    ringPt(252, -28),
    ringPt(251, 20),
    ringPt(225, 65)
  ];
  brush.set("rotring", "#fae294", 0.52);
  brush.spline(innerLipHighlight, 0.35);
}

// ============================================================================
// 3B. THE STEPPED BEZEL CHAMFER (BEVEL RIM)
// ============================================================================
function drawBezelChamferRim() {
  // Draw the 360-degree stepped chamfer around the cushion-oval bezel
  // Inner lip: (ru=135, rv=167, du=0, dv=0)
  // Outer lip: (ru=154, rv=189, du=4, dv=4)
  const steps = 140;
  for (let i = 0; i < steps; i++) {
    const a1 = (i * 360) / steps;
    const a2 = ((i + 1.3) * 360) / steps;

    const pIn1 = bezelPt(a1, 135, 167, 0, 0);
    const pIn2 = bezelPt(a2, 135, 167, 0, 0);
    const pOut1 = bezelPt(a1, 154, 189, 4, 4);
    const pOut2 = bezelPt(a2, 154, 189, 4, 4);

    // Metallic bevel color by angle around the cushion-oval
    let col;
    if (a1 >= 175 && a1 < 255) {
      // Upper-left chamfer: direct hot specular flash!
      col = a1 > 198 && a1 < 238 ? "#fffef6" : "#fae296";
    } else if (a1 >= 255 && a1 < 292) {
      // Top curve: bright yellow ochre to pale gold
      col = a1 < 274 ? "#f0c259" : "#d99829";
    } else if (a1 >= 292 && a1 < 332) {
      // Top-right corner: classic high-contrast dark reflection core in gold bevel
      col = a1 < 312 ? "#3b1a05" : "#80430f";
    } else if (a1 >= 332 || a1 < 28) {
      // Right edge (adjacent to shoulders/aperture): warm raw sienna & ochre
      col = "#b8741e";
    } else if (a1 >= 28 && a1 < 82) {
      // Lower-right bevel: burgundy velvet bounce (#5c1522) and deep bronze
      col = a1 < 55 ? "#4a2008" : "#5e1522";
    } else if (a1 >= 82 && a1 < 138) {
      // Bottom-left bevel: warm golden caustic reflection
      col = a1 < 110 ? "#8a4912" : "#cc8a28";
    } else {
      // Left curve (138..175): transition from raw sienna to blinding white flash
      col = a1 < 156 ? "#ab6518" : "#f5d376";
    }

    brush.set("gold_marker", col, 0.58);
    brush.line(
      (pIn1[0] + pIn2[0]) * 0.5,
      (pIn1[1] + pIn2[1]) * 0.5,
      (pOut1[0] + pOut2[0]) * 0.5,
      (pOut1[1] + pOut2[1]) * 0.5
    );
  }

  // Circumferential burnished pen contours defining the outer and inner bevel edges
  const outerBevelPts = [];
  const innerBevelPts = [];
  for (let a = 0; a < 360; a += 5) {
    outerBevelPts.push(bezelPt(a, 154, 189, 4, 4));
    innerBevelPts.push(bezelPt(a, 135, 167, 0, 0));
  }
  brush.set("pen", "#2e1303", 0.8);
  drawShapePoly(outerBevelPts, 0.15);

  brush.set("pen", "#3d1b05", 0.72);
  drawShapePoly(innerBevelPts, 0.15);

  // Hot white specular rim along the upper-left bevel lip (170° to 265°)
  const hotRimPts = [];
  for (let a = 168; a <= 268; a += 4) {
    hotRimPts.push(bezelPt(a, 136.5, 168.5, 0.5, 0.5));
  }
  brush.set("pen", "#fffef8", 1.05);
  brush.spline(hotRimPts, 0.35);

  // Secondary golden rim glint along the lower-right bevel lip (15° to 85°)
  const lowerGlintPts = [];
  for (let a = 15; a <= 85; a += 5) {
    lowerGlintPts.push(bezelPt(a, 152, 187, 3.5, 3.5));
  }
  brush.set("rotring", "#f2c663", 0.55);
  brush.spline(lowerGlintPts, 0.35);
}

// ============================================================================
// 3C. THE FLAT CUSHION-OVAL BEZEL TABLE (LAYERED MARKER + BURNISHED PEN)
// ============================================================================
function drawBezelTableSurface() {
  const tablePts = [];
  for (let a = 0; a < 360; a += 4) {
    tablePts.push(bezelPt(a, 134, 166, 0, 0));
  }

  // Solid base wash in warm yellow ochre / raw sienna
  brush.noStroke();
  brush.wash("#b5741e", 250);
  drawShapePoly(tablePts, 0.12);
  brush.noWash();

  // Layered diagonal marker strokes across the flat gold table at ~38 deg in ring-local space
  // Imitating gold leaf's hot specular flash over raw sienna and yellow ochre
  const dir = rad(38);
  const cosD = Math.cos(dir);
  const sinD = Math.sin(dir);
  const perpU = -sinD;
  const perpV = cosD;

  for (let s = -185; s <= 185; s += 3.6) {
    // Find chord endpoints across the cushion-oval table along line offset by s
    let tMin = null;
    let tMax = null;
    for (let t = -210; t <= 210; t += 3) {
      const u = s * perpU + t * cosD;
      const v = s * perpV + t * sinD;
      if (insideBezelTable(u, v, 133, 165)) {
        if (tMin === null) tMin = t;
        tMax = t;
      }
    }
    if (tMin === null || tMax - tMin < 8) continue;

    // Color bands across s (-185 = upper-left, +185 = lower-right)
    let col, wMult;
    if (s < -125) {
      // Upper-left edge: warm pale ochre approaching the flash
      col = "#e8b348";
      wMult = 0.68;
    } else if (s < -52) {
      // PRIMARY HOT SPECULAR FLASH ZONE (pale gold to pure warm white marker!)
      if (s > -102 && s < -72) {
        col = "#fffef5";
        wMult = 0.78;
      } else if (s > -115 && s < -58) {
        col = "#fae69e";
        wMult = 0.72;
      } else {
        col = "#f0c459";
        wMult = 0.68;
      }
    } else if (s < 8) {
      // Rich yellow ochre & raw sienna core
      col = s < -22 ? "#d49228" : "#a86016";
      wMult = 0.66;
    } else if (s < 58) {
      // Deep burnished raw sienna / bronze reflection band (twilight shadow across face)
      col = s > 22 && s < 42 ? "#783d0d" : "#965113";
      wMult = 0.68;
    } else if (s < 118) {
      // Secondary luminous golden reflection band across lower-right
      col = s > 78 && s < 98 ? "#f2c866" : "#d99a2b";
      wMult = 0.68;
    } else {
      // Lower-right margin: warm sienna & dark bronze edge
      col = s < 152 ? "#9e5815" : "#66320a";
      wMult = 0.64;
    }

    const u1 = s * perpU + tMin * cosD;
    const v1 = s * perpV + tMin * sinD;
    const u2 = s * perpU + tMax * cosD;
    const v2 = s * perpV + tMax * sinD;

    const p1 = ringPt(u1, v1);
    const p2 = ringPt(u2, v2);
    brush.set("gold_marker", col, wMult);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Second subtle cross-layer of warm white & yellow ochre marker in the hot flash zone
  // to create genuine marker overlap texture
  for (let s = -108; s <= -58; s += 5) {
    const u1 = s * perpU - 95 * cosD;
    const v1 = s * perpV - 95 * sinD;
    const u2 = s * perpU + 85 * cosD;
    const v2 = s * perpV + 85 * sinD;
    if (insideBezelTable(u1, v1, 130, 162) && insideBezelTable(u2, v2, 130, 162)) {
      const p1 = ringPt(u1, v1);
      const p2 = ringPt(u2, v2);
      brush.set("gold_marker", "#fffef7", 0.55);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 3D. THE WORN ENGRAVED HERALDIC CREST (INTAGLIO)
// ============================================================================

// Helper to render an intaglio (recessed) line segment/polyline in ring-local (u, v) space
// Top-left wall of groove is in deep umber shadow; bottom-right lip catches hot gold/white light
function drawIntaglioPath(localPts, depth = 1.0, closed = false) {
  if (!localPts || localPts.length < 2) return;

  // Subdivide path into small segments so we can modulate by bezelWear(u, v)
  for (let i = 0; i < localPts.length - (closed ? 0 : 1); i++) {
    const pA = localPts[i];
    const pB = localPts[(i + 1) % localPts.length];
    const distUV = Math.hypot(pB[0] - pA[0], pB[1] - pA[1]);
    const subs = Math.max(1, Math.ceil(distUV / 7));

    for (let s = 0; s < subs; s++) {
      const t1 = s / subs;
      const t2 = (s + 1) / subs;
      const u1 = lerp(pA[0], pB[0], t1);
      const v1 = lerp(pA[1], pB[1], t1);
      const u2 = lerp(pA[0], pB[0], t2);
      const v2 = lerp(pA[1], pB[1], t2);

      const um = (u1 + u2) * 0.5;
      const vm = (v1 + v2) * 0.5;
      const wear = bezelWear(um, vm);

      // If heavily worn, skip occasional micro-segments so the engraving dissolves into the metal
      if (wear > 0.68 && random() < (wear - 0.5) * 1.1) continue;

      const effDepth = depth * (1.0 - wear * 0.68);
      const off = 1.25 * effDepth;

      // 1. Warm bronze inner trench
      const cA = ringPt(u1, v1);
      const cB = ringPt(u2, v2);
      brush.set("pen", "#6e380b", 0.52 * effDepth);
      brush.line(cA[0], cA[1], cB[0], cB[1]);

      // 2. Deep burnt-umber shadow on the north-west wall of the groove
      const sA = ringPt(u1 - off * 0.75, v1 - off * 0.75);
      const sB = ringPt(u2 - off * 0.75, v2 - off * 0.75);
      const shadowCol = wear > 0.5 ? "#592b08" : "#240e02";
      brush.set("rotring", shadowCol, 0.48 * effDepth);
      brush.line(sA[0], sA[1], sB[0], sB[1]);

      // 3. Razor-sharp specular catch-light on the south-east lip of the groove
      const hA = ringPt(u1 + off * 0.85, v1 + off * 0.85);
      const hB = ringPt(u2 + off * 0.85, v2 + off * 0.85);
      const hiCol = um + vm < -20 ? "#fffef5" : "#fae08a";
      brush.set("rotring", hiCol, 0.44 * effDepth);
      brush.line(hA[0], hA[1], hB[0], hB[1]);
    }
  }
}

// Helper to carve an intaglio hollowed-out cavity (e.g. shield charges, helm, stars)
function drawIntaglioCavity(localPoly, depth = 1.0, hatchAngle = 35) {
  if (!localPoly || localPoly.length < 3) return;

  // Compute centroid for wear lookup
  let cu = 0,
    cv = 0;
  for (const p of localPoly) {
    cu += p[0];
    cv += p[1];
  }
  cu /= localPoly.length;
  cv /= localPoly.length;
  const wear = bezelWear(cu, cv);
  const eff = depth * (1 - wear * 0.6);

  // Dark recessed floor wash inside cavity
  const canvasPoly = localPoly.map((p) => ringPt(p[0], p[1]));
  brush.noStroke();
  brush.wash(wear > 0.5 ? "#7a4210" : "#3d1b05", 175 * eff);
  drawShapePoly(canvasPoly, 0.08);
  brush.noWash();

  // Fine heraldic intaglio hatching inside the cavity floor
  const polyObj = new brush.Polygon(canvasPoly);
  brush.hatchStyle("rotring", "#260f02", 0.32 * eff);
  brush.hatch(3.2, hatchAngle + BANG, { rand: 0.04 });
  polyObj.hatch(3.2, hatchAngle + BANG, { rand: 0.04 });
  brush.noHatch();

  // Carve the rim of the cavity
  drawIntaglioPath(localPoly, depth, true);
}

function drawEngravedHeraldicCrest() {
  // 1. Worn Beaded / Double-Hairline Border inset around the bezel perimeter
  // Notice how the bottom-left and bottom-right curves fade out from decades of wear
  const borderSteps = 96;
  for (let i = 0; i < borderSteps; i++) {
    const a1 = (i * 360) / borderSteps;
    const a2 = ((i + 0.7) * 360) / borderSteps;
    const r1 = cushionR(a1);
    const u1 = 117 * r1 * Math.cos(rad(a1));
    const v1 = 147 * r1 * Math.sin(rad(a1));
    const wear = bezelWear(u1, v1);

    if (wear > 0.62 && random() < 0.75) continue; // Worn smooth along bottom corners!

    const r2 = cushionR(a2);
    const u2 = 117 * r2 * Math.cos(rad(a2));
    const v2 = 147 * r2 * Math.sin(rad(a2));
    drawIntaglioPath(
      [
        [u1, v1],
        [u2, v2]
      ],
      0.85,
      false
    );

    // Inner hairline border 4.5px inside
    const u1b = 112 * r1 * Math.cos(rad(a1));
    const v1b = 141 * r1 * Math.sin(rad(a1));
    const u2b = 112 * r2 * Math.cos(rad(a2));
    const v2b = 141 * r2 * Math.sin(rad(a2));
    if (wear < 0.5) {
      drawIntaglioPath(
        [
          [u1b, v1b],
          [u2b, v2b]
