// ============================================================================
// 3E. MICRO-SCRATCHES, RIM NICKS & HOT SPECULAR FLASHES
// ============================================================================
function drawRingScratchesAndSpeculars() {
  // 1. ~260 razor-sharp hairline scratches across the flat gold bezel table
  for (let i = 0; i < 260; i++) {
    const u = random(-124, 124);
    const v = random(-154, 154);
    if (!insideBezelTable(u, v, 126, 156)) continue;

    const len = random(8, 44);
    const ang = random(0, 180);
    const du = len * 0.5 * Math.cos(rad(ang));
    const dv = len * 0.5 * Math.sin(rad(ang));

    const u1 = u - du,
      v1 = v - dv;
    const u2 = u + du,
      v2 = v + dv;
    if (!insideBezelTable(u1, v1, 130, 160) || !insideBezelTable(u2, v2, 130, 160))
      continue;

    const p1 = ringPt(u1, v1);
    const p2 = ringPt(u2, v2);

    // Scratches in the dark sienna zone glint pale gold/white;
    // scratches in the hot white zone register as fine raw sienna or pure white hairlines
    const inHotZone = u + v < -45;
    let sCol, sWeight;
    if (inHotZone) {
      sCol = random() < 0.6 ? "#b8741e" : "#ffffff";
      sWeight = random(0.18, 0.34);
    } else {
      sCol = random(["#fae296", "#fffef5", "#592b08", "#d99b2e"]);
      sWeight = random(0.18, 0.36);
    }

    const tool = random() < 0.7 ? "rotring" : "2H";
    brush.set(tool, sCol, sWeight);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Tiny wear nicks & micro-dings along the bevel rim (especially bottom-left and bottom-right)
  for (let i = 0; i < 85; i++) {
    const a = random(0, 360);
    const r = cushionR(a);
    const u = 135 * r * Math.cos(rad(a));
    const v = 167 * r * Math.sin(rad(a));
    const nickLen = random(2.5, 6.5);
    const na = a + random(-28, 28);
    const u2 = u + nickLen * Math.cos(rad(na));
    const v2 = v + nickLen * Math.sin(rad(na));

    const p1 = ringPt(u, v);
    const p2 = ringPt(u2, v2);
    const col = a > 160 && a < 275 ? "#ffffff" : random(["#fae08a", "#381804"]);
    brush.set("rotring", col, random(0.24, 0.42));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3. Scratches curving over the rounded upper and lower shoulders
  for (let i = 0; i < 95; i++) {
    const u = random(65, 255);
    const v = random(-155, 145);
    // Skip the finger aperture hole
    if (u > 140 && u < 245 && Math.abs(v) < 82) continue;
    // Stay inside outer shank envelope
    const maxV = 180 * (1 - (u - 40) / 310);
    if (Math.abs(v) > maxV) continue;

    const len = random(10, 28);
    const ang = random(-75, 75);
    const p1 = ringPt(u, v);
    const p2 = ringPt(u + len * Math.cos(rad(ang)), v + len * Math.sin(rad(ang)));
    const col = v < -30 ? random(["#fffef5", "#ab6418"]) : random(["#e8b348", "#3b1905"]);
    brush.set("rotring", col, random(0.18, 0.32));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 4. Final hot specular flash accents (pure warm white marker + pen along the upper-left bezel corner)
  const hotCornerArc = [];
  for (let a = 192; a <= 242; a += 4) {
    hotCornerArc.push(bezelPt(a, 134, 166, 0, 0));
  }
  brush.set("gold_marker", "#ffffff", 0.65);
  brush.spline(hotCornerArc, 0.35);
  brush.set("pen", "#fffef8", 0.85);
  brush.spline(hotCornerArc, 0.35);
}

