// 4. FOREGROUND LOOP OF THE PAWN STRING ON THE LOWER SHANK
// ============================================================================
function drawPawnStringLoopOverRing() {
  // The thin cotton price-tag string loops around the lower shank of the ring
  // entering at ringPt(155, 78) inside the aperture and wrapping across to ringPt(195, 145)
  const loopPts = [
    ringPt(156, 74),
    ringPt(168, 98),
    ringPt(182, 124),
    ringPt(194, 146),
    [755, 735]
  ];

  // Tiny cast shadow of the string on the lower gold shoulder
  brush.set("rotring", "#2b1102", 0.7);
  brush.spline(
    loopPts.map((p) => [p[0] + 1.8, p[1] + 2.2]),
    0.35
  );

  // Twisted cotton string body
  brush.set("cpencil", "#8c765e", 0.95);
  brush.spline(loopPts, 0.35);
  brush.set("rotring", "#dfd0bc", 0.38);
  brush.spline(
    loopPts.map((p) => [p[0] - 0.6, p[1] - 0.6]),
