  );

  // Small knot at [755, 735]
  brush.noStroke();
  brush.wash("#6e5a46", 230);
  brush.circle(755, 735, 4.5, 0.15);
  brush.noWash();
  brush.set("rotring", "#cbb9a1", 0.38);
  brush.circle(754, 734, 3.2, 0.2);
}

