// Transform a character's local point (cx, cy) onto an arched banner on the glass,
// WITH GENUINE HORIZONTAL MIRROR-REVERSAL across x = 600!
function mapArchMirrored(charIndex, numChars, lx, ly, charW, charH, archCfg) {
  // Normal (outside-facing) arc angle from left to right
  const t = numChars > 1 ? charIndex / (numChars - 1) - 0.5 : 0;
  const baseAng = t * archCfg.spanDeg;
  const localAng = baseAng + (lx * charW * 180) / (Math.PI * archCfg.radius);
  const r = archCfg.radius - ly * charH;

  // Normal coordinates
  const xNorm = archCfg.cx + r * Math.sin(rad(localAng));
  const yNorm = archCfg.cy - r * Math.cos(rad(localAng));

  // MIRROR-REVERSE horizontally across x = 600!
  return [1200 - xNorm, yNorm];
}

// Render a mirror-reversed, slightly out-of-focus gilded sign banner with cobalt drop shadow & black outline
function drawMirroredGildedBanner(textStr, charW, charH, archCfg, shadowOff) {
  const chars = textStr.split("");
  const n = chars.length;

  // Collect transformed segments for all characters
  const allSegs = [];
  for (let idx = 0; idx < n; idx++) {
    const ch = chars[idx];
    const strokes = SIGN_FONT[ch];
    if (!strokes) continue;

    for (const st of strokes) {
      const p1 = mapArchMirrored(idx, n, st[0], st[1], charW, charH, archCfg);
      const p2 = mapArchMirrored(idx, n, st[2], st[3], charW, charH, archCfg);
      // Tuscan median spur on thick vertical stems
      const pMid = mapArchMirrored(
        idx,
        n,
        (st[0] + st[2]) * 0.5,
        (st[1] + st[3]) * 0.5,
        charW,
        charH,
        archCfg
      );
      allSegs.push({ p1, p2, pMid, w: st[4] });
    }
  }

  // PASS 1: COBALT BLUE DROP SHADOW (slightly out of focus, offset by shadowOff)
  // Soft cobalt watercolor bleed behind the letters
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.3, 0.15);
  for (const seg of allSegs) {
    const sx = (seg.p1[0] + seg.p2[0]) * 0.5 + shadowOff[0];
    const sy = (seg.p1[1] + seg.p2[1]) * 0.5 + shadowOff[1];
    brush.fill("#12368a", 34);
    brush.circle(sx, sy, charW * 0.28 * seg.w, 0.2);
  }
  brush.noFill();

  // Concentric soft blur passes for the cobalt drop shadow
  const cobaltPasses = [
    { brushName: "blur_marker", col: "#0c2461", wMult: 1.45, dx: shadowOff[0] * 1.05, dy: shadowOff[1] * 1.05 },
    { brushName: "blur_marker", col: "#1843a8", wMult: 1.15, dx: shadowOff[0], dy: shadowOff[1] },
    { brushName: "blur_fine", col: "#2b62d9", wMult: 0.95, dx: shadowOff[0] * 0.85, dy: shadowOff[1] * 0.85 },
    // 3D shade block connecting letter to cobalt drop shadow
    { brushName: "blur_marker", col: "#14388c", wMult: 1.1, dx: shadowOff[0] * 0.5, dy: shadowOff[1] * 0.5 }
  ];

  for (const cp of cobaltPasses) {
    for (const seg of allSegs) {
      brush.set(cp.brushName, cp.col, cp.wMult * seg.w * (charW / 92));
      brush.line(
        seg.p1[0] + cp.dx,
        seg.p1[1] + cp.dy,
        seg.p2[0] + cp.dx,
        seg.p2[1] + cp.dy
      );
    }
  }

  // PASS 2: BLACK OUTLINE (diffused out-of-focus charcoal/black casing around letters & shadow)
  const blackPasses = [
    { brushName: "blur_marker", col: "#0d0f17", wMult: 1.48, dx: 0, dy: 0 },
    { brushName: "blur_marker", col: "#161926", wMult: 1.26, dx: 0, dy: 0 },
    { brushName: "blur_fine", col: "#0b0d14", wMult: 1.15, dx: shadowOff[0] * 0.3, dy: shadowOff[1] * 0.3 }
  ];

  for (const bp of blackPasses) {
    for (const seg of allSegs) {
      brush.set(bp.brushName, bp.col, bp.wMult * seg.w * (charW / 92));
      brush.line(
        seg.p1[0] + bp.dx,
        seg.p1[1] + bp.dy,
        seg.p2[0] + bp.dx,
        seg.p2[1] + bp.dy
      );
    }
  }

  // PASS 3: GILDED GOLD LEAF BODY (slightly out of focus, with horizontal burnish bands)
  const goldPasses = [
    { brushName: "blur_marker", col: "#7a5312", wMult: 1.02 },
    { brushName: "blur_marker", col: "#ab7a20", wMult: 0.82 },
    { brushName: "blur_fine", col: "#d9a538", wMult: 1.12 },
    { brushName: "blur_fine", col: "#f2cc68", wMult: 0.78 }
  ];

  for (const gp of goldPasses) {
    for (const seg of allSegs) {
      brush.set(gp.brushName, gp.col, gp.wMult * seg.w * (charW / 92));
      brush.line(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1]);
    }
  }

  // Soft hot specular gold-leaf glints where twilight catches the upper curves of the window leafing
  for (const seg of allSegs) {
    const ym = (seg.p1[1] + seg.p2[1]) * 0.5;
    const xm = (seg.p1[0] + seg.p2[0]) * 0.5;
    // Diagonal reflection band across the foreground glass lettering
    const band = Math.sin(xm * 0.008 + ym * 0.012);
    if (band > -0.1) {
      const hiCol = band > 0.45 ? "#fff6cc" : "#fae08c";
      brush.set("blur_fine", hiCol, 0.52 * seg.w * (charW / 92));
      brush.line(
        seg.p1[0],
        seg.p1[1],
        lerp(seg.p1[0], seg.p2[0], 0.65),
        lerp(seg.p1[1], seg.p2[1], 0.65)
      );
    }
  }
}

