// ============================================================================
// HELPER UTILITIES
// ============================================================================

function polyWash(pts, col, opacity) {
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
  return p;
}

function polyFill(pts, col, opacity, bleed = 0.08, tex = 0.35) {
  let p = new brush.Polygon(pts);
  p.fill(col, opacity, bleed, tex);
  return p;
}

function polyHatch(pts, brushName, col, weight, dist, angle, opts = { rand: 0.06 }) {
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, angle, opts);
  brush.noHatch();
  return p;
}

function makeEllipsePts(cx, cy, rx, ry, rotDeg = 0, steps = 36, jitter = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let jx = jitter ? random(-jitter, jitter) : 0;
    let jy = jitter ? random(-jitter, jitter) : 0;
    let lx = cos(a) * rx + jx;
    let ly = sin(a) * ry + jy;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function makeRibbonPts(centerPts, halfWidths) {
  let left = [];
  let right = [];
  for (let i = 0; i < centerPts.length; i++) {
    let p = centerPts[i];
    let prev = centerPts[max(0, i - 1)];
    let next = centerPts[min(centerPts.length - 1, i + 1)];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    let len = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / len;
    let ny = dx / len;
    let w = Array.isArray(halfWidths) ? halfWidths[i] : halfWidths;
    left.push([p[0] + nx * w, p[1] + ny * w]);
    right.push([p[0] - nx * w, p[1] - ny * w]);
  }
  return left.concat(right.reverse());
}

