// ============================================================================
// 2. PLOUGHED FIELD IN PERSPECTIVE
// ============================================================================

function drawPloughedField() {
  // Base earth wash across the field zone
  let fieldBg = [[60, 270], [1140, 270], [1140, 690], [60, 690]];
  polyWash(fieldBg, "#543f32", 245);
  polyFill(fieldBg, "#6b503e", 110, 0.1, 0.55);

  const vpX = 505;
  const vpY = 266;

  // Perspective ray angles/targets at y = 700
  const numFurrows = 28;
  let bottomXs = [];
  for (let i = 0; i <= numFurrows; i++) {
    let u = i / numFurrows;
    // Slight non-linear spread for wide-angle cab perspective
    let bx = map(u, 0, 1, -620, 1820);
    bottomXs.push(bx);
  }

  // Depth rows from horizon (t = 0.04) to foreground (t = 1.0)
  let tSteps = [];
  let tVal = 0.045;
  while (tVal < 1.0) {
    tSteps.push(tVal);
    tVal += 0.025 + pow(tVal, 1.45) * 0.12;
  }
  tSteps.push(1.02);

  function furrowPt(rayIdx, t, ridgeOffset = 0) {
    let bx = bottomXs[rayIdx];
    let x = lerp(vpX, bx, t);
    let y = lerp(vpY, 700, t);
    let wob = (noise(rayIdx * 0.7, t * 6.0) - 0.5) * 26 * t;
    return [x + wob, y + ridgeOffset * t];
  }

  // Render 3D furrow ridges: shadow trough, damp clay flank, sunlit mustard-ochre crest
  for (let r = 0; r < tSteps.length - 1; r++) {
    let t0 = tSteps[r];
    let t1 = tSteps[r + 1];
    let tMid = (t0 + t1) * 0.5;

    for (let i = 0; i < numFurrows; i++) {
      let p00 = furrowPt(i, t0, 0);
      let p10 = furrowPt(i + 1, t0, 0);
      let p11 = furrowPt(i + 1, t1, 0);
      let p01 = furrowPt(i, t1, 0);

      // Cull off-screen quads for performance
      let minX = min(min(p00[0], p10[0]), min(p11[0], p01[0]));
      let maxX = max(max(p00[0], p10[0]), max(p11[0], p01[0]));
      if (maxX < 50 || minX > 1150) continue;

      // Mid-ridge line along the furrow
      let m0 = [lerp(p00[0], p10[0], 0.52), lerp(p00[1], p10[1], 0.52) - 9 * t0];
      let m1 = [lerp(p01[0], p11[0], 0.52), lerp(p01[1], p11[1], 0.52) - 9 * t1];

      // Left slope of ridge (catches warm twilight mustard/clay light)
      let litSlope = [p00, m0, m1, p01];
      let litCol = (i + r) % 3 === 0 ? "#8f6c4b" : (i + r) % 3 === 1 ? "#a37d56" : "#785d47";
      polyWash(litSlope, litCol, 210);

      // Right slope of ridge (deep milky brown shadow & cool damp slate-clay sheen)
      let shdSlope = [m0, p10, p11, m1];
      let shdCol = (i * 3 + r) % 4 === 0 ? "#5c544e" : (i + r) % 2 === 0 ? "#423127" : "#4f3b2f";
      polyWash(shdSlope, shdCol, 225);

      // Clod and furrow crest strokes
      let strokeW = map(tMid, 0.04, 1.0, 0.3, 1.45);
      brush.set("soilBristle", "#3b2b22", strokeW * 0.9);
      brush.line(p10[0], p10[1], p11[0], p11[1]);

      // Warm twilight glint along the turned crest
      let crestCol = random() < 0.65 ? "#b89062" : "#cfa876";
      brush.set("cpencil", crestCol, strokeW * 0.75);
      brush.line(m0[0], m0[1], m1[0], m1[1]);

      // Damp sky-reflecting clay sheen in occasional troughs
      if (tMid > 0.18 && random() < 0.28) {
        let gx = lerp(m0[0], p10[0], 0.6);
        let gy = lerp(m0[1], p10[1], 0.6);
        let gx2 = lerp(m1[0], p11[0], 0.6);
        let gy2 = lerp(m1[1], p11[1], 0.6);
        brush.set("cpencil", "#8a857e", strokeW * 0.65);
        brush.line(gx, gy, gx2, gy2);
      }

      // Clumped earth clods and crop stubble in mid-to-near field
      if (tMid > 0.22) {
        let numClods = floor(map(tMid, 0.22, 1.0, 1, 5));
        for (let c = 0; c < numClods; c++) {
          let u = random(0.1, 0.9);
          let v = random(0.1, 0.9);
          let cx = lerp(lerp(p00[0], p10[0], u), lerp(p01[0], p11[0], u), v);
          let cy = lerp(lerp(p00[1], p10[1], u), lerp(p01[1], p11[1], u), v);
          let clodR = map(tMid, 0.2, 1.0, 2, 9) * random(0.6, 1.3);

          // Dark underside of clod
          brush.set("2B", "#38281f", strokeW * 1.1);
          brush.line(cx - clodR, cy + 1, cx + clodR, cy + 2);
          // Warm ochre/mustard top of clod
          brush.set("cpencil", random(["#b58b5c", "#9c744c", "#c9a171"]), strokeW * 0.85);
          brush.line(cx - clodR * 0.8, cy - 1.5, cx + clodR * 0.7, cy - 1);

          // Occasional dry golden stubble straw sticking out of turned sod
          if (random() < 0.32) {
            brush.set("2H", "#d4b075", 0.45);
            brush.line(cx, cy, cx + random(-8, 10) * tMid, cy - random(5, 14) * tMid);
          }
        }
      }
    }
  }
}

