// 4. DUSTY WINDSHIELD, WIPER ARC & WIPER BLADE
// ============================================================================

function drawWindshieldDustAndWiper() {
  const pivotX = 390;
  const pivotY = 668;
  const innerR = 140;
  const outerR = 575;
  const startA = -152;
  const endA = -24;

  // Heavy dust veil outside the wiper's cleared arc (upper corners and sides of glass)
  let topDustLeft = [[75, 55], [620, 55], [400, 115], [160, 260], [75, 450]];
  polyFill(topDustLeft, "#b89f80", 42, 0.25, 0.6);

  let topDustRight = [[580, 55], [1125, 55], [1125, 650], [935, 650], [890, 310], [720, 135]];
  polyFill(topDustRight, "#bda282", 48, 0.25, 0.6);

  // Fine arcuate wiper-sweep scratches and dust lines following the wiper's radius
  brush.noFill();
  for (let r = innerR; r <= outerR; r += 7) {
    let numArcs = floor(random(1, 4));
    for (let k = 0; k < numArcs; k++) {
      let a1 = random(startA, endA - 12);
      let a2 = min(endA, a1 + random(8, 34));
      let col = random() < 0.6 ? "#d4bc9b" : "#8f7a64";
      brush.set("2H", col, random(0.25, 0.5));
      brush.arc(pivotX, pivotY, r, a1, a2);
    }
  }

  // Distinct dust ridge along the outer boundary of the wiper sweep
  for (let i = 0; i < 8; i++) {
    let r = outerR + random(-6, 8);
    brush.set("cpencil", "#ccb391", random(0.35, 0.7));
    brush.arc(pivotX, pivotY, r, startA, endA);
  }
  // Right radial boundary of wiper sweep
  for (let i = 0; i < 6; i++) {
    let a = endA + random(-0.6, 0.6);
    brush.set("cpencil", "#c7ae8c", 0.45);
    brush.line(
      pivotX + cos(a) * innerR,
      pivotY + sin(a) * innerR,
      pivotX + cos(a) * outerR,
      pivotY + sin(a) * outerR
    );
  }

  // Backlit twilight dust specks, pollen, and dried mud droplets across the windshield
  for (let i = 0; i < 420; i++) {
    let x = random(85, 1110);
    let y = random(65, 650);
    let dx = x - pivotX;
    let dy = y - pivotY;
    let distP = sqrt(dx * dx + dy * dy);
    let ang = atan2(dy, dx);
    let inWiper = distP > innerR && distP < outerR && ang > startA && ang < endA;

    // Fewer specks inside the cleared wiper zone, denser outside
    if (inWiper && random() < 0.68) continue;

    let col = random(["#e6d2b5", "#c9ae89", "#8c745c", "#634f3f"]);
    brush.set("cpencil", col, random(0.35, 0.85));
    brush.line(x, y, x + random(-2, 2.5), y + random(-1.5, 2));
  }

  // Resting Windshield Wiper Arm & Blade on the lower-left glass
  // Wiper arm from pivot (390, 668) to blade hinge (235, 532)
  let armPts = [[386, 670], [395, 664], [240, 528], [233, 535]];
  polyWash(armPts, "#3e3027", 245);
  brush.set("cpencil", "#8c7b6b", 0.65);
  brush.line(392, 665, 238, 530);

  // Wiper blade assembly along angle ~ -148 deg
  let bladePts = [[128, 458], [338, 600], [333, 608], [123, 466]];
  polyWash(bladePts, "#362820", 250);
  brush.set("cpencil", "#7d6c5d", 0.6);
  brush.line(128, 458, 338, 600);
}

