function drawGauge(cx, cy, r, needleAng, isTach) {
  // Outer rusted chrome bezel
  let bezelPts = makeEllipsePts(cx, cy, r + 6, (r + 6) * 0.92, -6, 32);
  polyWash(bezelPts, "#3b2c23", 252);
  let innerBezel = makeEllipsePts(cx, cy, r + 2, (r + 2) * 0.92, -6, 32);
  polyWash(innerBezel, "#6e6254", 240);

  // Aged yellowed mustard-cream dial face
  let facePts = makeEllipsePts(cx, cy, r - 2, (r - 2) * 0.92, -6, 32);
  polyWash(facePts, "#bfa984", 240);
  polyFill(facePts, "#ab926c", 110, 0.1, 0.4);

  // Upper inner bezel shadow inside glass
  let rimShadow = makeEllipsePts(cx, cy - 2, r - 3, (r - 3) * 0.88, -6, 28);
  brush.set("2B", "#47362b", 0.7);
  brush.arc(cx, cy, r - 2, 185, 355);

  // Dial tick marks around arc
  for (let a = 150; a <= 390; a += isTach ? 18 : 28) {
    let r1 = r - 9;
    let r2 = r - 4;
    let x1 = cx + cos(a) * r1;
    let y1 = cy + sin(a) * r1 * 0.92;
    let x2 = cx + cos(a) * r2;
    let y2 = cy + sin(a) * r2 * 0.92;
    let col = a > 330 ? "#9e4132" : "#3d2e24";
    brush.set("rotring", col, 0.5);
    brush.line(x1, y1, x2, y2);
  }

  // Hour-meter drum window on tachometer
  if (isTach) {
    let drum = [[cx - 18, cy + 12], [cx + 18, cy + 13], [cx + 18, cy + 23], [cx - 18, cy + 22]];
    polyWash(drum, "#3a2c23", 240);
    brush.set("cpencil", "#d4be98", 0.45);
    brush.line(cx - 14, cy + 17, cx + 12, cy + 18);
  }

  // Gauge needle in faded orange-red
  let nx = cx + cos(needleAng) * (r - 8);
  let ny = cy + sin(needleAng) * (r - 8) * 0.92;
  brush.set("rotring", "#a64332", 0.85);
  brush.line(cx, cy, nx, ny);
  brush.set("2B", "#36281f", 1.1);
  brush.circle(cx, cy, 4);

  // Dusty glass glare streak across dial
  brush.set("cpencil", "#e3cfb0", 0.5);
  brush.line(cx - r * 0.5, cy - r * 0.35, cx + r * 0.35, cy - r * 0.55);
  brush.set("cpencil", "#9c8b75", 0.65);
  brush.arc(cx, cy, r + 4, 20, 155);
}

