// 7. STEERING WHEEL WITH COLOURED PENCIL CRACKS
// ============================================================================

function drawSteeringWheel() {
  const cx = 278;
  const cy = 985;
  const rx = 268;
  const ry = 136;
  const rot = -11;
  const rimThick = 34;

  // Steering column shaft descending into lower cab shadow
  let colShaft = [[248, 985], [312, 985], [285, 1200], [215, 1200]];
  polyWash(colShaft, "#30231b", 255);
  polyHatch(colShaft, "cpencil", "#4a382d", 0.6, 5, 76, { rand: 0.04 });

  // Three heavy spokes converging to center hub (cx, cy + 12)
  const spokeAngles = [196, 338, 86];
  for (let sa of spokeAngles) {
    let rad = sa * (PI / 180);
    let c = cos(rot);
    let s = sin(rot);
    let lx = cos(sa) * (rx - 14);
    let ly = sin(sa) * (ry - 8);
    let ex = cx + lx * c - ly * s;
    let ey = cy + lx * s + ly * c;

    let spokeCenter = [
      [cx, cy + 12],
      [lerp(cx, ex, 0.5), lerp(cy + 12, ey, 0.5) + 4],
      [ex, ey]
    ];
    let spokePoly = makeRibbonPts(spokeCenter, [22, 16, 18]);
    polyWash(spokePoly, "#382a21", 252);
    polyFill(spokePoly, "#4a382c", 140, 0.05, 0.4);
    polyHatch(spokePoly, "cpencil", "#665345", 0.55, 4.5, sa, { rand: 0.04 });

    // Spoke highlight edge
    brush.set("cpencil", "#8a7562", 0.7);
    brush.line(cx, cy + 8, ex, ey - 5);
  }

  // Center Steering Wheel Hub Cap
  let hubBase = makeEllipsePts(cx, cy + 12, 54, 34, rot, 32);
  polyWash(hubBase, "#33251d", 255);
  let hubTop = makeEllipsePts(cx, cy + 6, 46, 28, rot, 32);
  polyWash(hubTop, "#4a382d", 250);
  polyHatch(hubTop, "cpencil", "#6b5646", 0.5, 4, -12, { rand: 0.04 });

  // Faded tractor emblem ring in center of hub
  let hubEmblem = makeEllipsePts(cx, cy + 5, 22, 13, rot, 24);
  polyWash(hubEmblem, "#8c4334", 220);
  brush.set("cpencil", "#c79e63", 0.6);
  brush.arc(cx, cy + 5, 20, 0, 360);

  // Build the 3D toroidal steering wheel rim in segments around the ellipse
  const segs = 64;
  let outerPts = makeEllipsePts(cx, cy, rx + rimThick * 0.5, ry + rimThick * 0.5, rot, segs);
  let innerPts = makeEllipsePts(cx, cy + 4, rx - rimThick * 0.5, ry - rimThick * 0.5, rot, segs);
  let midPts = makeEllipsePts(cx, cy - 3, rx, ry, rot, segs);

  for (let i = 0; i < segs; i++) {
    let ni = (i + 1) % segs;
    let quad = [outerPts[i], outerPts[ni], innerPts[ni], innerPts[i]];
    let a = (i / segs) * 360;

    // Base bakelite/hard-rubber milky dark brown
    let baseCol = (a > 175 && a < 350) ? "#453429" : "#362820";
    polyWash(quad, baseCol, 252);

    // Top-half of each rim cross-section catches dusty twilight olive/mustard sky light
    let topQuad = [outerPts[i], outerPts[ni], midPts[ni], midPts[i]];
    let topCol = (a > 185 && a < 340) ? "#695a4c" : "#524135";
    polyWash(topQuad, topCol, 210);
  }

  // Continuous coloured pencil shading and specular sheen along the rim curve
  for (let rOff = -14; rOff <= 14; rOff += 3.5) {
    let ringPts = makeEllipsePts(cx, cy + rOff * 0.15, rx + rOff, ry + rOff * 0.55, rot, 48);
    let isHighlight = rOff > -6 && rOff < 4;
    let col = isHighlight ? "#8f7d6a" : rOff < -6 ? "#33251d" : "#574437";
    let w = isHighlight ? 0.75 : 0.55;
    brush.set("cpencil", col, w);
    brush.spline(ringPts.slice(18, 47), 0.5);
    brush.spline(ringPts.slice(0, 20), 0.5);
  }

  // COLOURED PENCIL CRACKS in the aged Bakelite steering wheel rim
  // Deep radial splits where old bakelite shrinks around the inner steel ring
  const crackAngles = [168, 192, 215, 238, 254, 276, 305, 328, 18, 46, 128, 148];
  let cRot = cos(rot);
  let sRot = sin(rot);
  for (let ca of crackAngles) {
    let lx1 = cos(ca) * (rx - rimThick * 0.52);
    let ly1 = sin(ca) * (ry - rimThick * 0.52);
    let lx2 = cos(ca + 1.2) * (rx + rimThick * 0.52);
    let ly2 = sin(ca + 1.2) * (ry + rimThick * 0.52);

    let x1 = cx + lx1 * cRot - ly1 * sRot;
    let y1 = cy + lx1 * sRot + ly1 * cRot;
    let x2 = cx + lx2 * cRot - ly2 * sRot;
    let y2 = cy + lx2 * sRot + ly2 * cRot;
    let mx = (x1 + x2) * 0.5 + random(-3, 3);
    let my = (y1 + y2) * 0.5 + random(-3, 3);

    // Dark split trench
    brush.set("cpencil", "#261a14", 0.95);
    brush.spline([[x1, y1, 0.7], [mx, my, 1.0], [x2, y2, 0.7]], 0.3);

    // Chipped pale amber/taupe edge catching light right beside the crack
    brush.set("cpencil", "#b89f82", 0.65);
    brush.spline([[x1 + 2, y1 + 1, 0.5], [mx + 2.5, my + 1, 0.9], [x2 + 2, y2 + 1, 0.5]], 0.3);

    // Secondary micro-fissures branching off the main crack
    brush.set("skinPencil", "#33241b", 0.45);
    brush.line(mx, my, mx + random(-12, 12), my + random(-6, 6));
  }
}

// ============================================================================
// 8. DENTED GREEN THERMOS CUP & RISING STEAM
// ============================================================================

function drawThermosCup() {
  const cupX = 875;
  const topY = 665;
  const botY = 935;
  const topRx = 86;
  const topRy = 23;
  const botRx = 76;
  const botRy = 24;

  // Cast shadow of the thermos cup across the dusty dashboard shelf
  let castShadow = makeEllipsePts(925, 938, 112, 32, 8, 32);
  polyWash(castShadow, "#36271f", 215);
  polyFill(castShadow, "#2e211a", 130, 0.22, 0.5);

  // Cup Handle on the right side (dark bakelite/olive metal bracket)
  let handleOuter = [
    [955, 708],
    [1018, 720],
    [1024, 855],
    [948, 875],
    [948, 852],
    [998, 838],
    [994, 738],
    [952, 728]
  ];
  polyWash(handleOuter, "#382b22", 252);
  polyHatch(handleOuter, "cpencil", "#544336", 0.55, 4, 82, { rand: 0.04 });
  brush.set("cpencil", "#8f7e6a", 0.65);
  brush.line(956, 709, 1016, 721);
  brush.line(1016, 721, 1022, 852);

  // Construct the cylindrical green thermos body with an explicit DENT on the left-front
  const rows = 26;
  const cols = 28;
  let grid = [];

  for (let r = 0; r <= rows; r++) {
    let v = r / rows;
    let yBase = lerp(topY, botY, v);
    let rx = lerp(topRx, botRx, v);
    let ry = lerp(topRy, botRy, v);
    let rowPts = [];

    for (let c = 0; c <= cols; c++) {
      let u = c / cols;
      // Front half of cylinder from angle 0 (right) to 180 (left)
      let ang = lerp(180, 0, u);
      let x = cupX + cos(ang) * rx;
      let y = yBase + sin(ang) * ry;

      // THE DENT: centered around u = 0.28 (left-front), v = 0.52 (mid-belly)
      let du = (u - 0.28) / 0.19;
      let dv = (v - 0.52) / 0.22;
      let d2 = du * du + dv * dv;
      if (d2 < 1.0) {
        let dentStrength = pow(1.0 - d2, 1.6);
        x += dentStrength * 14; // pushes left contour inward
        y -= dentStrength * 5;
      }

      rowPts.push([x, y, u, v, d2]);
    }
    grid.push(rowPts);
  }

  // Render thermos surface quads with hammertone olive green, stainless lip band, and dent shading
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let p00 = grid[r][c];
      let p10 = grid[r][c + 1];
      let p11 = grid[r + 1][c + 1];
      let p01 = grid[r + 1][c];
      let quad = [[p00[0], p00[1]], [p10[0], p10[1]], [p11[0], p11[1]], [p01[0], p01[1]]];

      let u = (p00[2] + p10[2]) * 0.5;
      let v = (p00[3] + p01[3]) * 0.5;
      let d2 = p00[4];

      // Top brushed stainless/aluminum rim band (v < 0.13)
      if (v < 0.13) {
        let rimCol = u < 0.22 ? "#b8b5a6" : u < 0.45 ? "#d9d2be" : u < 0.75 ? "#8a8577" : "#5e594f";
        polyWash(quad, rimCol, 245);
        continue;
      }

      // Hammertone olive green body shading
      let col = "#525e3f";
      if (u < 0.16) col = "#63704d";
      else if (u < 0.34) col = "#7e8c64"; // main twilight specular zone
      else if (u < 0.62) col = "#576343";
      else if (u < 0.84) col = "#444f35";
      else col = "#38402c"; // right shadow side

      // Modify shading inside the concave dent!
      if (d2 < 1.0) {
        let dv = (v - 0.52) / 0.22;
        if (dv < -0.05) {
          // Upper half of dent faces downward into shadow
          col = "#39422d";
        } else if (dv > 0.1) {
          // Lower ridge of dent faces upward toward twilight sky!
          col = "#9ca882";
        } else {
          // Center crease of dent with chipped paint / raw steel
          col = "#6e6b5e";
        }
      }

      polyWash(quad, col, 245);
    }
  }

  // Hammertone stipple, scratches, and chipped paint around the dent
  for (let i = 0; i < 240; i++) {
    let v = random(0.15, 0.96);
    let u = random(0.04, 0.96);
    let rIdx = floor(v * rows);
    let cIdx = floor(u * cols);
    let pt = grid[rIdx][cIdx];
    let col = u < 0.4 ? "#9aa680" : "#3a422d";
    brush.set("cpencil", col, random(0.4, 0.75));
    brush.line(pt[0], pt[1], pt[0] + random(-3, 3), pt[1] + random(2, 6));
  }

  // Crisp coloured pencil detailing inside the dent (crease, chipped olive edge, raw steel scratch)
  const dentCx = 828;
  const dentCy = 804;
  brush.set("2B", "#2e3323", 0.95);
  brush.spline([[802, 782, 0.4], [826, 796, 1.0], [858, 788, 0.4]], 0.35);
  brush.set("cpencil", "#c9c4a7", 0.85);
  brush.spline([[804, 808, 0.4], [829, 818, 1.0], [860, 806, 0.4]], 0.35);
  // Raw grey-brown steel exposed at impact center
  for (let i = 0; i < 18; i++) {
    brush.set("cpencil", i % 2 === 0 ? "#7a7568" : "#d9ceb2", 0.55);
    brush.line(
      dentCx + random(-18, 18),
      dentCy + random(-10, 10),
      dentCx + random(-10, 22),
      dentCy + random(-6, 12)
    );
  }

  // Horizontal ribbed grip rings near base of thermos cup
  for (let rv of [0.78, 0.83, 0.88]) {
    let rIdx = floor(rv * rows);
    let ring = grid[rIdx].map(p => [p[0], p[1]]);
    brush.set("2B", "#313826", 0.75);
    brush.spline(ring, 0.4);
    brush.set("cpencil", "#8d9973", 0.5);
    brush.spline(ring.slice(2, 14), 0.4);
  }

  // Cup Top Mouth Opening & Dark Hot Coffee Inside
  let outerLip = makeEllipsePts(cupX, topY, topRx, topRy, 0, 36);
  polyWash(outerLip, "#a8a393", 250);

  let innerCup = makeEllipsePts(cupX, topY + 2, topRx - 7, topRy - 3, 0, 36);
  polyWash(innerCup, "#45372d", 250);

  // Coffee liquid surface inside the cup
  let coffeeSurf = makeEllipsePts(cupX, topY + 6, topRx - 11, topRy - 5, 0, 36);
  polyWash(coffeeSurf, "#382419", 255);
  polyFill(coffeeSurf, "#4d3122", 140, 0.08, 0.35);

  // Golden-mustard coffee crema ring & twilight reflection on the liquid
  brush.set("cpencil", "#b88750", 0.85);
  brush.arc(cupX, topY + 5, topRx - 14, -170, -10);
  brush.set("cpencil", "#d9b584", 0.65);
  brush.line(cupX - 38, topY + 5, cupX + 22, topY + 4);
  brush.line(cupX - 24, topY + 9, cupX + 35, topY + 8);

  // Crisp metallic highlight around the front lip of the thermos cup
  brush.set("cpencil", "#ebe1cc", 0.9);
  brush.arc(cupX, topY, topRx - 2, 15, 165);
}

