function drawVerticalFilmScratch() {
  // A single hair-like vertical emulsion scratch running through the frame around x = 842
  const scratchX = 842;
  let y = 0;

  while (y < 1200) {
    let segLen = random(45, 155);
    let yNext = min(1200, y + segLen);
    let x1 = scratchX + (noise(y * 0.015) - 0.5) * 2.2;
    let xm = scratchX + (noise((y + segLen * 0.5) * 0.015) - 0.5) * 2.2;
