// Renders a flat, hard-edged marker polygon with vivid saturation and subtle
// chisel-marker streak texture, bordered by a thick black marker band.
function drawMarkerPoly(pts, fillCol, hatchAngle = 0, borderWeight = 10) {
  if (!pts || pts.length < 3) return;
  let poly = new brush.Polygon(pts);

  // Solid vivid marker pigment pass
  poly.wash(fillCol, 245);

  // Directional chisel marker streak pass for authentic flat marker surface
  brush.hatchStyle("marker", fillCol, 1.35);
  poly.hatch(7, hatchAngle, { rand: 0.015, continuous: true });
  brush.noHatch();

  // Thick black hand-painted Ndebele band outline
  if (borderWeight > 0) {
    drawBlackBandOutline(pts, borderWeight, true);
  }
}

function drawMarkerRect(x, y, w, h, fillCol, hatchAngle = 0, borderWeight = 10) {
  let pts = [
    [x, y],
    [x + w, y],
    [x + w, y + h],
    [x, y + h]
  ];
  drawMarkerPoly(pts, fillCol, hatchAngle, borderWeight);
}

function drawBlackBandOutline(pts, weight = 10, closed = true) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  // Double pass with marker + pen core for crisp yet handmade black band edges
  brush.set("marker", PAL.black, weight * 0.19);
  let n = pts.length;
  let limit = closed ? n : n - 1;
  for (let i = 0; i < limit; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("rotring", PAL.black, weight * 0.14);
  for (let i = 0; i < limit; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// Generates a stepped chevron band polygon (the signature Ndebele stair-step motif)
function buildSteppedSlantBand(xStart, yStart, steps, dxStep, dyStep, bandWidthX) {
  let leftSide = [];
  let rightSide = [];
  let cx = xStart;
  let cy = yStart;
  leftSide.push([cx, cy]);
  rightSide.push([cx + bandWidthX, cy]);

  for (let i = 0; i < steps; i++) {
    cy += dyStep;
    leftSide.push([cx, cy]);
    rightSide.push([cx + bandWidthX, cy]);
    cx += dxStep;
    leftSide.push([cx, cy]);
    rightSide.push([cx + bandWidthX, cy]);
  }
  return leftSide.concat(rightSide.reverse());
}

