    let dx1 = dx0 + dW;
    let colA = dadoPalette[i % 4];
    let colB = dadoPalette[(i + 1) % 4];
    let colC = dadoPalette[(i + 2) % 4];

    // Outer box
    drawMarkerRect(dx0, 910, dW, 102, colA, 0, 9);
    // Stepped inner frame
    drawMarkerPoly([
      [dx0 + 18, 926], [dx1 - 18, 926],
      [dx1 - 18, 996], [dx0 + 18, 996]
    ], PAL.whitewash, 0, 8);
    // Inner diamond
    drawMarkerPoly([
      [dxm, 928], [dx1 - 24, 961], [dxm, 994], [dx0 + 24, 961]
    ], colB, 45, 8);
    // Center eye rectangle
    drawMarkerRect(dxm - 14, 951, 28, 20, colC, 0, 7);
  }

  brush.noField();
}

function drawPilasterWing(x, y, w, h, mirror) {
  drawMarkerRect(x, y, w, h, PAL.whitewash, 0, 10);

  // Vertical inner border stripes
  let stripeW = 24;
  let innerX = mirror ? x + stripeW : x;
  let barX = mirror ? x : x + w - stripeW;

  // Vertical color-block ladder along the inner edge
  let segs = 10;
  let segH = h / segs;
  let ladderCols = [PAL.yellow, PAL.ultra, PAL.whitewash, PAL.rose, PAL.emerald];
  for (let i = 0; i < segs; i++) {
    drawMarkerRect(barX, y + i * segH, stripeW, segH, ladderCols[i % ladderCols.length], 90, 8);
  }

  // 3 stacked geometric stacked-chevron medallions inside the wing
  let boxW = w - stripeW;
  let boxH = h / 3;
  let wingCols = [
    [PAL.ultra, PAL.yellow, PAL.rose, PAL.emerald],
    [PAL.emerald, PAL.rose, PAL.yellow, PAL.ultra],
    [PAL.rose, PAL.ultra, PAL.emerald, PAL.yellow]
  ];

  for (let k = 0; k < 3; k++) {
    let by = y + k * boxH;
    let bcy = by + boxH * 0.5;
    let pal = wingCols[k];
    drawMarkerRect(innerX, by, boxW, boxH, pal[0], 0, 9);

    // Stepped chevron pointing inward toward center mural
    let tipX = mirror ? innerX + 22 : innerX + boxW - 22;
    let baseX = mirror ? innerX + boxW : innerX;
    let midX = (tipX + baseX) * 0.5;

    // Outer whitewash chevron
    drawMarkerPoly([
      [baseX, by + 12],
      [tipX, bcy],
      [baseX, by + boxH - 12],
      [baseX, by + boxH - 42],
      [(tipX + baseX) * 0.5, bcy],
      [baseX, by + 42]
    ], PAL.whitewash, 45, 8);

    // Mid yellow/rose chevron
    drawMarkerPoly([
      [baseX, by + 42],
      [midX, bcy],
      [baseX, by + boxH - 42]
    ], pal[1], -45, 8);

    // Corner stepped triangles
    let cX = mirror ? innerX : innerX + boxW;
    let cDir = mirror ? 1 : -1;
    drawMarkerPoly([
      [cX - cDir * boxW, by],
      [cX - cDir * (boxW - 68), by],
      [cX - cDir * boxW, by + 68]
    ], pal[2], 0, 8);
    drawMarkerPoly([
      [cX - cDir * boxW, by + boxH],
      [cX - cDir * (boxW - 68), by + boxH],
      [cX - cDir * boxW, by + boxH - 68]
    ], pal[3], 0, 8);
  }
}

function drawCentralSteppedPanel(x, y, w, h) {
  // Base background of central panel
  drawMarkerRect(x, y, w, h, PAL.whitewash, 0, 11);

  let cx = x + w * 0.5; // 600
  let cy = y + h * 0.5; // 576

  // Divide into 4 quadrants around the central cross/diamond axis
  // Each quadrant gets bold, authentic STEPPED CHEVRONS in Ultramarine, Egg-Yolk Yellow, Emerald, Rose, and Whitewash
  let qW = w * 0.5; // 356
  let qH = h * 0.5; // 310

  // Helper to draw a quadrant filled with stepped diagonal bands
  // qx, qy is the outer corner; cx, cy is the center of the mural
  let bandSequence = [
    PAL.ultra,
    PAL.whitewash,
    PAL.yellow,
    PAL.emerald,
    PAL.whitewash,
    PAL.rose,
    PAL.ultra,
    PAL.yellow,
    PAL.emerald,
    PAL.rose
  ];

  // Draw the 4 quadrants with crisp clipping-like stepped geometry inside each quadrant box
  drawSteppedQuadrant(x, y, qW, qH, -1, -1, bandSequence);
  drawSteppedQuadrant(cx, y, qW, qH, 1, -1, bandSequence);
  drawSteppedQuadrant(x, cy, qW, qH, -1, 1, bandSequence);
  drawSteppedQuadrant(cx, cy, qW, qH, 1, 1, bandSequence);

  // Central horizontal & vertical structural divider straps (Ndebele "spear/pillar" cross)
  drawMarkerRect(x, cy - 16, w, 32, PAL.whitewash, 0, 9);
  for (let sx = x + 18; sx < x + w - 40; sx += 56) {
    drawMarkerRect(sx, cy - 9, 28, 18, PAL.black, 0, 0);
  }

  drawMarkerRect(cx - 18, y, 36, h, PAL.whitewash, 90, 9);
  let vCols = [PAL.rose, PAL.yellow, PAL.emerald, PAL.ultra];
  for (let sy = y + 16, idx = 0; sy < y + h - 38; sy += 48, idx++) {
    drawMarkerRect(cx - 11, sy, 22, 28, vCols[idx % 4], 0, 6);
  }

  // Grand Central Stepped Diamond Medallion centered at (cx, cy)
  let dSteps = [
    { rx: 168, ry: 146, col: PAL.black },
    { rx: 152, ry: 132, col: PAL.whitewash },
    { rx: 126, ry: 108, col: PAL.ultra },
    { rx: 98,  ry: 84,  col: PAL.yellow },
    { rx: 70,  ry: 60,  col: PAL.rose },
    { rx: 42,  ry: 36,  col: PAL.emerald },
    { rx: 18,  ry: 16,  col: PAL.whitewash }
  ];

  for (let s = 0; s < dSteps.length; s++) {
    let st = dSteps[s];
    let pts = buildSteppedDiamond(cx, cy, st.rx, st.ry, 5);
    drawMarkerPoly(pts, st.col, s % 2 === 0 ? 0 : 90, 9);
  }
}

function buildSteppedDiamond(cx, cy, rx, ry, numSteps) {
  let pts = [];
  let dx = rx / numSteps;
  let dy = ry / numSteps;

  // Top to Right
  for (let i = 0; i < numSteps; i++) {
    pts.push([cx + i * dx, cy - ry + i * dy]);
    pts.push([cx + (i + 1) * dx, cy - ry + i * dy]);
  }
  // Right to Bottom
  for (let i = 0; i < numSteps; i++) {
    pts.push([cx + rx - i * dx, cy + i * dy]);
    pts.push([cx + rx - i * dx, cy + (i + 1) * dy]);
  }
  // Bottom to Left
  for (let i = 0; i < numSteps; i++) {
    pts.push([cx - i * dx, cy + ry - i * dy]);
    pts.push([cx - (i + 1) * dx, cy + ry - i * dy]);
  }
  // Left to Top
  for (let i = 0; i < numSteps; i++) {
    pts.push([cx - rx + i * dx, cy - i * dy]);
    pts.push([cx - rx + i * dx, cy - (i + 1) * dy]);
  }
  return pts;
}

// Draws nested stepped L-chevrons inside a quadrant of the central mural
function drawSteppedQuadrant(qx, qy, qw, qh, dirX, dirY, palette) {
  // Corner anchor is the outer corner of the quadrant
  let cornerX = dirX < 0 ? qx : qx + qw;
  let cornerY = dirY < 0 ? qy : qy + qh;
  let signX = dirX < 0 ? 1 : -1; // direction from outer corner toward center
  let signY = dirY < 0 ? 1 : -1;

  // Fill background of quadrant first
  drawMarkerRect(qx, qy, qw, qh, PAL.ultra, 0, 9);

  // Build concentric stepped chevron bands from largest to smallest
  let numBands = 7;
  for (let b = 0; b < numBands; b++) {
    let fracOuter = 1.0 - b * 0.135;
    let wSpan = qw * fracOuter;
    let hSpan = qh * fracOuter;
    let steps = Math.max(2, 7 - b);
    let dx = (wSpan / steps) * signX;
    let dy = (hSpan / steps) * signY;

    let pts = [];
    pts.push([cornerX, cornerY]);
    pts.push([cornerX + wSpan * signX, cornerY]);

    // Stair-step diagonal from (cornerX + wSpan*signX, cornerY) to (cornerX, cornerY + hSpan*signY)
    let curX = cornerX + wSpan * signX;
    let curY = cornerY;
    for (let s = 0; s < steps; s++) {
      curY += dy;
      pts.push([curX, curY]);
      curX -= dx;
      pts.push([curX, curY]);
    }
    pts.close = true;

    let col = palette[b % palette.length];
    drawMarkerPoly(pts, col, b % 2 === 0 ? 0 : 90, 9);
  }
}

