// ============================================================================
// 4. CRISP, DISTORTED MIDDAY SUN SHADOW BENDING OVER WALL GEOMETRY
// ============================================================================

// Maps a point (x, y) on the bicycle (with distance 'depth' from the wall)
// to its cast shadow coordinate (sx, sy), bending sharply over the wall's
// stepped relief bands, protruding dado ledge, and courtyard ground!
function projectShadowPt(x, y, depth = 1.0) {
  // Midday sun from high above & slightly left: casts shadow downward and slightly right.
  // Top of bicycle leans closer to the wall (smaller depth), bottom of wheels sits further out.
  let verticalFactor = constrain(map(y, 440, 1020, 0.48, 1.15), 0.35, 1.3);
  let d = depth * verticalFactor;

  let sx = x + 36 * d;
  let sy = y + 84 * d;

  // Architectural Relief Distortion #1: Central horizontal strap & diamond relief (y = 560..592)
  if (sy > 558 && sy < 596) {
    sx -= 9;
    sy -= 5;
  }

  // Architectural Relief Distortion #2: Stepped chevron mortar ridges in the central mural
  // Creates a subtle stair-stepped jog in the shadow across the painted bands
  if (sx > 244 && sx < 956 && sy > 266 && sy < 886) {
    let stepWave = Math.floor((sx + sy) / 48) % 2 === 0 ? 5 : -4;
    sx += stepWave;
  }

  // Architectural Relief Distortion #3: Protruding Dado Ledge at y = 886..1012
  // Because the dado plinth projects outward toward the bike, the shadow hits it EARLY
  // and shifts up/left on the top shelf (886..910) then drops vertically down the face!
  if (sy >= 886 && sy < 1012) {
    if (sy < 912) {
      // Top bevel of the ledge: shadow runs horizontally across the lip
      sx -= 18;
      sy = 886 + (sy - 886) * 0.45;
    } else {
      // Front face of the protruding dado: closer to bike, so shifted left & up
      sx -= 16;
      sy -= 14;
    }
  }

  // Architectural Relief Distortion #4: Courtyard Ground Plane (y >= 1012)
  // Shadow stretches foreshortened across the horizontal earth floor
  if (sy >= 1012) {
    let over = sy - 1012;
    sx += over * 0.42;
    sy = 1012 + over * 0.34;
  }

  return [sx, sy];
}

function drawShadowPolyline(pts3D, weight = 3.0) {
  let proj = pts3D.map(p => projectShadowPt(p[0], p[1], p[2] !== undefined ? p[2] : 1.0));
  brush.set("marker", PAL.shadowWash, weight * 0.38);
  for (let i = 0; i < proj.length - 1; i++) {
    brush.line(proj[i][0], proj[i][1], proj[i + 1][0], proj[i + 1][1]);
  }
  brush.set("rotring", PAL.shadowLine, weight * 0.25);
  for (let i = 0; i < proj.length - 1; i++) {
    brush.line(proj[i][0], proj[i][1], proj[i + 1][0], proj[i + 1][1]);
  }
}

function drawMiddayBicycleShadow() {
