}

function drawShadowSubdividedLine(pA, pB, steps, weight) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    pts.push([
      lerp(pA[0], pB[0], t),
      lerp(pA[1], pB[1], t),
      lerp(pA[2], pB[2], t)
    ]);
  }
  drawShadowPolyline(pts, weight);
}

function drawWheelShadow(cx, cy, r, depthBase, hasMudguard) {
  // Tire shadow ring subdivided into small angular segments so it kinks sharply over wall geometry
  let outerRing = [];
  let innerRing = [];
  let steps = 72;
  let tiltX = depthBase > 1.02 ? 0.92 : 1.0; // slight turn of front wheel

  for (let i = 0; i <= steps; i++) {
    let ang = (i / steps) * 360;
    let pxOut = cx + cos(ang) * r * tiltX;
    let pyOut = cy + sin(ang) * r;
    let pxIn = cx + cos(ang) * (r - 28) * tiltX;
    let pyIn = cy + sin(ang) * (r - 28);
    outerRing.push([pxOut, pyOut, depthBase]);
    innerRing.push([pxIn, pyIn, depthBase]);
  }

  // Thick shadow band for tire + rim
  for (let i = 0; i < steps; i++) {
    let p1 = projectShadowPt(outerRing[i][0], outerRing[i][1], depthBase);
    let p2 = projectShadowPt(outerRing[i + 1][0], outerRing[i + 1][1], depthBase);
    let p3 = projectShadowPt(innerRing[i + 1][0], innerRing[i + 1][1], depthBase);
    let p4 = projectShadowPt(innerRing[i][0], innerRing[i][1], depthBase);
    let segPoly = new brush.Polygon([p1, p2, p3, p4]);
    segPoly.wash(PAL.shadowWash, 145);
  }
  drawShadowPolyline(outerRing, 5.5);
  drawShadowPolyline(innerRing, 4.0);

  // Crisp distorted spoke shadows (36 tangential spokes bending across the stepped chevrons!)
  let numSpokes = 36;
  for (let s = 0; s < numSpokes; s++) {
    let aHub = s * (360 / numSpokes);
    let crossDir = s % 2 === 0 ? 1 : -1;
    let aRim = aHub + crossDir * 68;
    let hx = cx + cos(aHub) * 20 * tiltX;
    let hy = cy + sin(aHub) * 20;
    let rx = cx + cos(aRim) * (r - 26) * tiltX;
    let ry = cy + sin(aRim) * (r - 26);

    // Subdivide each spoke into 10 segments so it bends across every wall relief ridge
    let spokePts = [];
    for (let k = 0; k <= 10; k++) {
      let t = k / 10;
      spokePts.push(projectShadowPt(lerp(hx, rx, t), lerp(hy, ry, t), depthBase));
    }
    brush.set("rotring", PAL.shadowLine, 1.05);
    for (let k = 0; k < spokePts.length - 1; k++) {
      brush.line(spokePts[k][0], spokePts[k][1], spokePts[k + 1][0], spokePts[k + 1][1]);
    }
  }

  // Mudguard stay shadows
  drawShadowSubdividedLine([cx, cy, depthBase], [cx - r * 0.96, cy + 12, depthBase], 10, 3.5);
  drawShadowSubdividedLine([cx, cy, depthBase], [cx - r * 0.72, cy - r * 0.68, depthBase], 10, 3.5);
}

