function drawHyperrealBicycle() {
  // Ground contact shadow right under the two tires
  drawGroundContactPatch(BIKE.rearHub.x, BIKE.rearHub.y + BIKE.wheelR);
  drawGroundContactPatch(BIKE.frontHub.x, BIKE.frontHub.y + BIKE.wheelR);

  // 1. Rear & Front Wheels (perished rubber, Westwood steel rims, 36 tangential spokes, rusted hubs, mudguards)
  drawHyperrealWheel(BIKE.rearHub.x, BIKE.rearHub.y, BIKE.wheelR, 1.0, true);
  drawHyperrealWheel(BIKE.frontHub.x, BIKE.frontHub.y, BIKE.wheelR, 0.93, false);

  // 2. Rear Carrier Rack (under the sack)
  drawRearRackStructure();

  // 3. Double-Top-Tube Roadster Frame (black enamel, specular reflections, pitted rust blooms, ornate lugs)
  drawRoadsterFrame();

  // 4. Drivetrain: Greasy Roller Chain, Ornate Chainring, Battered Chain Guard & Pedals
  drawDrivetrainAndGrease();

  // 5. Steer Tube, Rod-Brake Linkages, North Road Handlebars, Brass Bell & Perished Grips
  drawHandlebarsAndRodBrakes();

  // 6. Sprung Leather Roadster Saddle
  drawSprungLeatherSaddle();

  // 7. Bulging Woven Burlap Sack & Frayed Sisal Rope on the Rear Rack
  drawBurlapSackAndFrayedRope();
}

function drawGroundContactPatch(x, y) {
  brush.noFill();
  brush.noWash();
  for (let i = 0; i < 35; i++) {
    let w = map(i, 0, 35, 95, 18);
    let dy = random(-4, 8);
    brush.set("charcoal", "#1A110B", random(0.8, 1.8));
    brush.line(x - w, y + dy, x + w, y + dy);
  }
}

// ----------------------------------------------------------------------------
// WHEELS: PERISHED RUBBER, 36 TANGENTIAL SPOKES, WESTWOOD RIMS & MUDGUARDS
// ----------------------------------------------------------------------------
function drawHyperrealWheel(cx, cy, rOuter, scaleX, isRear) {
  let rTireIn = rOuter - BIKE.tireThick; // 158
  let rRimIn = rTireIn - 10;             // 148
  let segs = 80;

  // --- A. 36 Tangential 3-Cross Spokes (drawn first so tire/rim overlap rim edge cleanly) ---
  let numSpokes = 36;
  for (let pass = 0; pass < 2; pass++) {
    for (let s = 0; s < numSpokes; s++) {
      if (s % 2 !== pass) continue;
      let aHub = s * (360 / numSpokes);
      let dir = s % 2 === 0 ? 1 : -1;
      let aRim = aHub + dir * 68;

      let hx = cx + cos(aHub) * 21 * scaleX;
      let hy = cy + sin(aHub) * 21;
      let rx = cx + cos(aRim) * (rRimIn + 2) * scaleX;
      let ry = cy + sin(aRim) * (rRimIn + 2);

      // Subtle bend on two damaged rear spokes for hyperreal life
      if (isRear && (s === 7 || s === 23)) {
        let mx = (hx + rx) * 0.5 + 6;
        let my = (hy + ry) * 0.5 - 5;
        brush.set("rotring", "#332922", 0.9);
        brush.line(hx, hy, mx, my);
        brush.line(mx, my, rx, ry);
      } else {
        // Metallic spoke with glinting highlight and rusty lower sections
        let isRusty = (s * 7) % 5 === 0;
        brush.set("2H", "#B8C4CE", 0.85);
        brush.line(hx + 0.8, hy, rx + 0.8, ry);
        brush.set("rotring", isRusty ? PAL.rustDark : "#22262C", 0.85);
        brush.line(hx, hy, rx, ry);
      }

      // Brass/steel spoke nipple at the rim
      let nx = cx + cos(aRim) * (rRimIn - 4) * scaleX;
      let ny = cy + sin(aRim) * (rRimIn - 4);
      brush.set("rotring", PAL.black, 1.4);
      brush.line(rx, ry, nx, ny);
    }
  }

  // --- B. Steel Westwood Rim ---
  for (let i = 0; i < segs; i++) {
    let a1 = (i / segs) * 360;
    let a2 = ((i + 1) / segs) * 360;
    let p1 = [cx + cos(a1) * rTireIn * scaleX, cy + sin(a1) * rTireIn];
    let p2 = [cx + cos(a2) * rTireIn * scaleX, cy + sin(a2) * rTireIn];
    let p3 = [cx + cos(a2) * rRimIn * scaleX, cy + sin(a2) * rRimIn];
    let p4 = [cx + cos(a1) * rRimIn * scaleX, cy + sin(a1) * rRimIn];

    let rimPoly = new brush.Polygon([p1, p2, p3, p4]);
    let rimCol = (i % 9 === 0) ? PAL.rustMid : ((i % 4 === 0) ? PAL.frameSteel : PAL.frameBlack);
    rimPoly.wash(rimCol, 235);
  }

  // Rim specular metallic ring & rust pitting
  drawEllipseStroke(cx, cy, (rTireIn - 3) * scaleX, rTireIn - 3, 0, 360, "2H", PAL.frameHi, 1.1);
  drawEllipseStroke(cx, cy, rRimIn * scaleX, rRimIn, 0, 360, "rotring", PAL.black, 1.3);

  // --- C. Perished Rubber Tire (Chalky Sun-Bleached Charcoal, Cracks, Worn Tread & Courtyard Dust) ---
  for (let i = 0; i < segs; i++) {
    let a1 = (i / segs) * 360;
    let a2 = ((i + 1) / segs) * 360;
    let p1 = [cx + cos(a1) * rOuter * scaleX, cy + sin(a1) * rOuter];
    let p2 = [cx + cos(a2) * rOuter * scaleX, cy + sin(a2) * rOuter];
    let p3 = [cx + cos(a2) * rTireIn * scaleX, cy + sin(a2) * rTireIn];
    let p4 = [cx + cos(a1) * rTireIn * scaleX, cy + sin(a1) * rTireIn];

    let tireSeg = new brush.Polygon([p1, p2, p3, p4]);
    // Bottom of tire is dusty ochre-grey from the earth floor; upper tire is sun-baked perished rubber
    let isBottom = sin(a1) > 0.55;
    let baseCol = isBottom ? PAL.rubberDry : (i % 3 === 0 ? PAL.rubberMid : PAL.rubberBase);
    tireSeg.wash(baseCol, 248);
  }

  // Perished rubber cross-contour pencil shading, dry rot sidewall cracks & tread blocks
  for (let i = 0; i < 180; i++) {
    let a = (i / 180) * 360;
    let rMid = lerp(rTireIn + 3, rOuter - 3, random(0.15, 0.85));
    let x1 = cx + cos(a) * rTireIn * scaleX;
    let y1 = cy + sin(a) * rTireIn;
    let x2 = cx + cos(a) * rOuter * scaleX;
    let y2 = cy + sin(a) * rOuter;

    // Fine graphite rubber grain
    brush.set("2B", sin(a) > 0.4 ? PAL.rubberDust : "#1B1B1A", 0.75);
    brush.line(x1, y1, x2, y2);

    // Perished sidewall cracks (ragged radial & jagged fissures in the dry vulcanized rubber)
    if (i % 4 === 0) {
      let ca = a + random(-1.5, 1.5);
      let cx1 = cx + cos(ca) * (rTireIn + 4) * scaleX;
      let cy1 = cy + sin(ca) * (rTireIn + 4);
      let cxm = cx + cos(ca + 1.4) * rMid * scaleX;
      let cym = cy + sin(ca + 1.4) * rMid;
      let cx2 = cx + cos(ca - 0.8) * (rOuter - 4) * scaleX;
      let cy2 = cy + sin(ca - 0.8) * (rOuter - 4);
      brush.set("rotring", "#0E0D0C", 0.95);
      brush.line(cx1, cy1, cxm, cym);
      brush.line(cxm, cym, cx2, cy2);
      // Pale dry-rot chalky edge beside each crack
      brush.set("cpencil", PAL.rubberDust, 0.65);
      brush.line(cx1 + 1, cy1, cxm + 1, cym);
    }

    // Outer tire tread notches
    if (i % 2 === 0) {
      let tx1 = cx + cos(a) * (rOuter - 4) * scaleX;
      let ty1 = cy + sin(a) * (rOuter - 4);
      let tx2 = cx + cos(a + 1.1) * (rOuter + 1.5) * scaleX;
      let ty2 = cy + sin(a + 1.1) * (rOuter + 1.5);
      brush.set("rotring", PAL.black, 1.2);
      brush.line(tx1, ty1, tx2, ty2);
    }
  }

  // Outer & Inner tire contour lines
  drawEllipseStroke(cx, cy, rOuter * scaleX, rOuter, 0, 360, "rotring", PAL.black, 1.4);
  drawEllipseStroke(cx, cy, rTireIn * scaleX, rTireIn, 0, 360, "rotring", PAL.black, 1.3);

  // Inner tube valve stem with missing cap
  let vAng = isRear ? 115 : 62;
  let vx1 = cx + cos(vAng) * rRimIn * scaleX;
  let vy1 = cy + sin(vAng) * rRimIn;
  let vx2 = cx + cos(vAng) * (rRimIn - 22) * scaleX;
  let vy2 = cy + sin(vAng) * (rRimIn - 22);
  brush.set("rotring", PAL.rustDark, 1.8);
  brush.line(vx1, vy1, vx2, vy2);
  brush.set("cpencil", "#D6B06A", 1.1);
  brush.line(vx1 + 1, vy1, vx2 + 1, vy2);

  // --- D. Rusted Steel Mudguard (Fender) & Wire Stays ---
  let mgR = rOuter + 10;
  let startA = isRear ? 158 : 142;
  let endA = isRear ? 322 : 286;

  // Mudguard body arc
  for (let a = startA; a < endA; a += 4) {
    let aNext = min(a + 4, endA);
    let m1 = [cx + cos(a) * (mgR + 9) * scaleX, cy + sin(a) * (mgR + 9)];
    let m2 = [cx + cos(aNext) * (mgR + 9) * scaleX, cy + sin(aNext) * (mgR + 9)];
    let m3 = [cx + cos(aNext) * (mgR - 3) * scaleX, cy + sin(aNext) * (mgR - 3)];
    let m4 = [cx + cos(a) * (mgR - 3) * scaleX, cy + sin(a) * (mgR - 3)];
    let mgPoly = new brush.Polygon([m1, m2, m3, m4]);

    // Classic British/African roadster detail: white-painted rear mudguard tail!
    let isWhiteTail = isRear && a < 188;
    let mgCol = isWhiteTail ? "#DFD9CA" : ((a % 24 === 0) ? PAL.rustMid : PAL.frameBlack);
    mgPoly.wash(mgCol, 245);
  }
  drawEllipseStroke(cx, cy, (mgR + 9) * scaleX, mgR + 9, startA, endA, "rotring", PAL.black, 1.5);
  drawEllipseStroke(cx, cy, (mgR - 3) * scaleX, mgR - 3, startA, endA, "rotring", PAL.black, 1.3);
  drawEllipseStroke(cx, cy, (mgR + 4) * scaleX, mgR + 4, startA + 8, endA - 8, "2H", PAL.frameHi, 0.9);

  // Rust patches on mudguard
  for (let a = startA + 10; a < endA - 5; a += 19) {
    let rx = cx + cos(a) * (mgR + 3) * scaleX;
    let ry = cy + sin(a) * (mgR + 3);
    drawRustBloom(rx, ry, 10, 6);
  }

  // Rear red glass reflector on the white tail of the rear mudguard
  if (isRear) {
    let refX = cx + cos(172) * (mgR + 12) * scaleX;
    let refY = cy + sin(172) * (mgR + 12);
    let refPoly = new brush.Polygon([
      [refX - 8, refY - 6], [refX + 4, refY - 8], [refX + 4, refY + 8], [refX - 8, refY + 6]
    ]);
    refPoly.wash("#B81428", 245);
    drawBlackBandOutline([[refX - 8, refY - 6], [refX + 4, refY - 8], [refX + 4, refY + 8], [refX - 8, refY + 6]], 3, true);
  }

  // Mudguard steel stays bolted to hub axle
  let stayAngles = isRear ? [170, 212] : [155, 198];
  for (let sa of stayAngles) {
    let sx = cx + cos(sa) * (mgR + 5) * scaleX;
    let sy = cy + sin(sa) * (mgR + 5);
    drawSteelTube(cx, cy, sx, sy, 3.2, true);
  }

  // --- E. Wheel Hub & Greasy Axle Nut ---
  let hubPoly = [];
  for (let a = 0; a < 360; a += 30) {
    hubPoly.push([cx + cos(a) * 22 * scaleX, cy + sin(a) * 22]);
  }
  new brush.Polygon(hubPoly).wash(PAL.frameBlack, 250);
  drawEllipseStroke(cx, cy, 22 * scaleX, 22, 0, 360, "rotring", PAL.black, 1.4);
  drawEllipseStroke(cx, cy, 11 * scaleX, 11, 0, 360, "2H", PAL.frameHi, 1.1);
  // Oily grease smudge around the hub shell
  brush.set("charcoal", PAL.grease, 1.4);
  brush.circle(cx, cy, 8, 0.25);
}

function drawEllipseStroke(cx, cy, rx, ry, aStart, aEnd, brushName, col, weight) {
  brush.set(brushName, col, weight);
  let step = 4;
  for (let a = aStart; a < aEnd; a += step) {
    let a2 = min(a + step, aEnd);
    brush.line(
      cx + cos(a) * rx, cy + sin(a) * ry,
      cx + cos(a2) * rx, cy + sin(a2) * ry
    );
  }
}

// ----------------------------------------------------------------------------
// ROADSTER FRAME: DOUBLE TOP-TUBE, LUGS, BLACK ENAMEL & PITTED RUST
// ----------------------------------------------------------------------------
function drawSteelTube(x1, y1, x2, y2, radius, rusty = true) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  let p1 = [x1 + nx * radius, y1 + ny * radius];
  let p2 = [x2 + nx * radius, y2 + ny * radius];
  let p3 = [x2 - nx * radius, y2 - ny * radius];
  let p4 = [x1 - nx * radius, y1 - ny * radius];

  // Base black enamel wash
  let tubePoly = new brush.Polygon([p1, p2, p3, p4]);
  tubePoly.wash(PAL.frameBlack, 250);

  // Longitudinal cylindrical shading in graphite & pen
  let slices = Math.max(3, Math.floor(radius * 1.2));
  for (let s = -slices; s <= slices; s++) {
    let t = s / slices; // -1 to 1 across tube radius
    let off = t * radius;
    let lx1 = x1 + nx * off;
    let ly1 = y1 + ny * off;
    let lx2 = x2 + nx * off;
    let ly2 = y2 + ny * off;

    if (t > -0.55 && t < -0.18) {
      // Crisp metallic cylinder highlight along upper-left edge
      brush.set("2H", PAL.frameHi, 0.9);
      brush.line(lx1, ly1, lx2, ly2);
    } else if (t > 0.35) {
      // Deep core shadow on underside of tube
      brush.set("rotring", PAL.frameDark, 1.1);
      brush.line(lx1, ly1, lx2, ly2);
    } else {
      brush.set("2B", "#232830", 0.8);
      brush.line(lx1, ly1, lx2, ly2);
    }
  }

  // Pitted rust patches & oxidized flaking enamel along the steel tube
  if (rusty) {
    let distLen = dist(x1, y1, x2, y2);
    let numRust = Math.floor(distLen / 42);
    for (let r = 0; r < numRust; r++) {
      let frac = random(0.12, 0.88);
      let rx = lerp(x1, x2, frac) + nx * random(-radius * 0.4, radius * 0.4);
      let ry = lerp(y1, y2, frac) + ny * random(-radius * 0.4, radius * 0.4);
      drawRustBloom(rx, ry, random(10, 24), radius * 1.4);
    }
  }

  // Razor-sharp outer contour lines in Rotring ink
  brush.set("rotring", PAL.black, 1.35);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  brush.line(p4[0], p4[1], p3[0], p3[1]);
}

function drawRustBloom(x, y, len, thick) {
  // Crusty layered rust: dark iron oxide edge, warm sienna core, bright orange pit stipple
  brush.set("cpencil", PAL.rustDark, 1.2);
  for (let i = 0; i < 6; i++) {
    let dx = random(-len * 0.5, len * 0.5);
    let dy = random(-thick * 0.4, thick * 0.4);
    brush.line(x + dx, y + dy, x + dx + random(-7, 7), y + dy + random(-4, 4));
  }
  brush.set("cpencil", PAL.rustMid, 1.1);
  for (let i = 0; i < 5; i++) {
    let dx = random(-len * 0.35, len * 0.35);
    let dy = random(-thick * 0.3, thick * 0.3);
    brush.line(x + dx, y + dy, x + dx + random(-5, 5), y + dy + random(-3, 3));
  }
  brush.set("rotring", PAL.rustBright, 0.85);
  for (let i = 0; i < 4; i++) {
    let px = x + random(-len * 0.3, len * 0.3);
    let py = y + random(-thick * 0.25, thick * 0.25);
    brush.line(px, py, px + 2, py + 1);
  }
}

function drawRoadsterFrame() {
  let sc = BIKE.seatCluster;
  let ht = BIKE.headTop;
  let hb = BIKE.headBot;
  let bb = BIKE.bb;
  let rh = BIKE.rearHub;
  let fh = BIKE.frontHub;
  let fc = BIKE.forkCrown;

  // Rear seatstays & chainstays
  drawSteelTube(sc.x, sc.y + 8, rh.x, rh.y, 6.2, true);
  drawSteelTube(bb.x, bb.y, rh.x, rh.y, 7.2, true);

  // Seat tube (with faded vintage gold/red band decal half-eaten by rust)
  drawSteelTube(sc.x, sc.y, bb.x, bb.y, 10.5, true);
  drawTubeDecalBand(lerp(sc.x, bb.x, 0.38), lerp(sc.y, bb.y, 0.38), atan2(bb.y - sc.y, bb.x - sc.x), 10.5, 28);

  // Down tube
  drawSteelTube(hb.x, hb.y, bb.x, bb.y, 11.0, true);

  // Twin parallel top tubes (heavy-duty African roadster)
  drawSteelTube(sc.x, sc.y, ht.x, ht.y, 10.0, true);
  drawSteelTube(sc.x + 15, sc.y + 48, hb.x - 5, hb.y - 20, 8.5, true);

  // Head tube
  drawSteelTube(ht.x, ht.y - 6, hb.x, hb.y + 8, 12.5, true);

  // Front Fork Crown & Twin Curved Blades
  drawLugCollar(fc.x, fc.y, 15, 12);
  // Fork blades curving slightly forward to front axle
  let fMidX = lerp(fc.x, fh.x, 0.55) + 12;
  let fMidY = lerp(fc.y, fh.y, 0.55);
  drawSteelTube(fc.x - 4, fc.y, fMidX - 4, fMidY, 7.5, true);
  drawSteelTube(fMidX - 4, fMidY, fh.x - 3, fh.y, 5.5, true);
  drawSteelTube(fc.x + 4, fc.y, fMidX + 4, fMidY, 8.2, true);
  drawSteelTube(fMidX + 4, fMidY, fh.x + 3, fh.y, 6.0, true);

  // Ornate steel frame lugs at the joints (classic gold-lined Raleigh/Humber style, weathered)
  drawLugCollar(sc.x, sc.y, 15, 15);
  drawLugCollar(ht.x, ht.y, 16, 15);
  drawLugCollar(hb.x, hb.y, 16, 15);
}

function drawLugCollar(x, y, w, h) {
  let pts = [
    [x - w, y - h], [x + w, y - h], [x + w, y + h], [x - w, y + h]
  ];
  new brush.Polygon(pts).wash(PAL.frameDark, 250);
  // Faded gold-leaf pinstripe on lug edge
  brush.set("cpencil", "#C99A42", 1.1);
  brush.line(x - w, y - h, x + w, y - h);
  brush.line(x - w, y + h, x + w, y + h);
  brush.set("rotring", PAL.black, 1.4);
  drawBlackBandOutline(pts, 2.5, true);
}

function drawTubeDecalBand(cx, cy, ang, r, len) {
  let dx = cos(ang) * len * 0.5;
  let dy = sin(ang) * len * 0.5;
  let nx = -sin(ang) * r;
  let ny = cos(ang) * r;
  let pts = [
    [cx - dx + nx, cy - dy + ny],
    [cx + dx + nx, cy + dy + ny],
    [cx + dx - nx, cy + dy - ny],
    [cx - dx - nx, cy - dy - ny]
  ];
  new brush.Polygon(pts).wash("#9E281B", 215);
  brush.set("cpencil", "#D9A74A", 1.2);
  brush.line(pts[0][0], pts[0][1], pts[3][0], pts[3][1]);
  brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
  drawRustBloom(cx, cy, 14, 12);
}

// ----------------------------------------------------------------------------
// DRIVETRAIN: CHAIN GREASE, CHAINRING, ROLLER CHAIN & PEDALS
// ----------------------------------------------------------------------------
function drawDrivetrainAndGrease() {
  let bb = BIKE.bb;
  let rh = BIKE.rearHub;
  let crR = 48;
  let cogR = 20;

  // --- A. Heavy Roller Chain (Top & Bottom Runs with Link Plates & Thick Black Grease) ---
  let topStart = [rh.x, rh.y - cogR];
  let topEnd = [bb.x, bb.y - crR];
  let botStart = [rh.x, rh.y + cogR];
  let botEnd = [bb.x, bb.y + crR];

  drawRollerChainRun(topStart[0], topStart[1], topEnd[0], topEnd[1], false);
  drawRollerChainRun(botStart[0], botStart[1], botEnd[0], botEnd[1], true);

  // --- B. Partial Hockey-Stick Steel Chain Guard (battered & rusted) ---
  let cgPts = [
    [bb.x - 12, bb.y - crR - 10],
    [bb.x + 36, bb.y - crR + 4],
    [bb.x + 52, bb.y - 6],
    [bb.x + 34, bb.y - 6],
    [bb.x + 8, bb.y - crR + 8],
    [rh.x + 38, rh.y - cogR - 2],
    [rh.x + 32, rh.y - cogR - 14]
  ];
  new brush.Polygon(cgPts).wash(PAL.frameBlack, 248);
  drawBlackBandOutline(cgPts, 2.5, true);
  drawRustBloom(bb.x - 45, bb.y - 42, 26, 10);
  drawRustBloom(bb.x + 15, bb.y - 44, 18, 10);

  // --- C. Ornate Roadster Chainring with Cut-Out Webs ---
  // Outer toothed ring
  for (let a = 0; a < 360; a += 10) {
    let tx1 = bb.x + cos(a) * (crR - 4);
    let ty1 = bb.y + sin(a) * (crR - 4);
    let tx2 = bb.x + cos(a + 4) * (crR + 5);
    let ty2 = bb.y + sin(a + 4) * (crR + 5);
    let tx3 = bb.x + cos(a + 8) * (crR - 4);
    let ty3 = bb.y + sin(a + 8) * (crR - 4);
    // Greasy black tooth
    new brush.Polygon([[tx1, ty1], [tx2, ty2], [tx3, ty3]]).wash(PAL.grease, 250);
    brush.set("rotring", PAL.black, 1.1);
    brush.line(tx1, ty1, tx2, ty2);
    brush.line(tx2, ty2, tx3, ty3);
  }

  drawEllipseStroke(bb.x, bb.y, crR - 4, crR - 4, 0, 360, "rotring", PAL.black, 2.4);
  drawEllipseStroke(bb.x, bb.y, crR - 9, crR - 9, 0, 360, "2H", PAL.frameSteel, 1.4);

  // 5 internal chainring spokes
  for (let k = 0; k < 5; k++) {
    let a = k * 72 + 18;
    drawSteelTube(bb.x, bb.y, bb.x + cos(a) * (crR - 7), bb.y + sin(a) * (crR - 7), 4.2, true);
  }

  // --- D. Viscous Black Chain Grease & Grime Buildup ---
  // Clumped oil, road grit, and black grease around the bottom bracket, chainring teeth, and chainstay
  brush.set("charcoal", PAL.grease, 1.8);
  for (let i = 0; i < 65; i++) {
    let ga = random(360);
    let gr = random(8, crR + 4);
    let gx = bb.x + cos(ga) * gr;
    let gy = bb.y + sin(ga) * gr;
    brush.line(gx, gy, gx + random(-5, 5), gy + random(-4, 4));
  }
  // Grease smudges along the right chainstay
  for (let i = 0; i < 40; i++) {
    let t = random(0.05, 0.85);
    let gx = lerp(bb.x, rh.x, t) + random(-6, 6);
    let gy = lerp(bb.y, rh.y, t) + random(-6, 8);
    brush.set("charcoal", PAL.grease, random(1.0, 2.1));
    brush.line(gx, gy, gx + random(-6, 6), gy + random(-2, 4));
  }
  // Slick graphite oil sheen on the grease
  brush.set("2B", "#525B66", 0.9);
  for (let i = 0; i < 18; i++) {
    let ga = random(360);
    let gx = bb.x + cos(ga) * (crR - 6);
    let gy = bb.y + sin(ga) * (crR - 6);
    brush.line(gx, gy, gx + 4, gy - 2);
  }

  // --- E. Crank Arms & Worn Rubber Block Pedals ---
  // Left crank (pointing up-left behind frame)
  drawSteelTube(bb.x, bb.y, bb.x - 20, bb.y - 72, 5.0, true);
  drawRubberPedal(bb.x - 20, bb.y - 72, 34, 13);

  // Right crank (pointing down-right in foreground)
  drawSteelTube(bb.x, bb.y, bb.x + 22, bb.y + 78, 5.8, true);
  drawRubberPedal(bb.x + 22, bb.y + 78, 40, 15);
}

function drawRollerChainRun(x1, y1, x2, y2, hasSag) {
  let numLinks = 26;
  let prevX = x1;
  let prevY = y1;

  for (let i = 1; i <= numLinks; i++) {
    let t = i / numLinks;
    let cx = lerp(x1, x2, t);
    let cy = lerp(y1, y2, t) + (hasSag ? sin(t * 180) * 8 : 0);

    // Figure-8 chain link plate with pitch-black grease & rusty pin
    brush.set("marker", PAL.grease, 1.4);
    brush.line(prevX, prevY, cx, cy);
    brush.set("rotring", i % 3 === 0 ? PAL.rustDark : PAL.black, 1.5);
    brush.line(prevX, prevY - 3, cx, cy - 3);
    brush.line(prevX, prevY + 3, cx, cy + 3);
    // Link rivet pin highlight
    brush.set("2H", "#9AA5B1", 0.9);
    brush.line(cx, cy - 2, cx + 1, cy + 2);

    prevX = cx;
    prevY = cy;
  }
}

function drawRubberPedal(cx, cy, w, h) {
  let pts = [
    [cx - w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy + h * 0.5],
    [cx - w * 0.5, cy + h * 0.5]
  ];
  new brush.Polygon(pts).wash(PAL.rubberBase, 250);
  // Worn rubber treads & steel endplates
  brush.set("rotring", PAL.black, 1.3);
  drawBlackBandOutline(pts, 2.5, true);
  brush.set("2H", PAL.frameHi, 1.0);
  brush.line(cx - w * 0.45, cy, cx + w * 0.45, cy);
  drawRustBloom(cx + w * 0.35, cy, 8, 6);
}

// ----------------------------------------------------------------------------
// HANDLEBARS, ROD-BRAKES, BRASS BELL & PERISHED GRIPS
// ----------------------------------------------------------------------------
function drawHandlebarsAndRodBrakes() {
  let ht = BIKE.headTop;
  let fc = BIKE.forkCrown;

  // Gooseneck stem rising from head tube
  let stemTop = { x: ht.x - 16, y: ht.y - 68 };
  drawSteelTube(ht.x, ht.y, stemTop.x, stemTop.y, 7.5, true);

  // Far handlebar wing (curving right-back)
  let farBar = { x: stemTop.x + 48, y: stemTop.y + 18 };
  drawSteelTube(stemTop.x, stemTop.y, farBar.x, farBar.y, 6.2, true);
  drawPerishedGrip(farBar.x - 6, farBar.y - 2, farBar.x + 32, farBar.y + 14, 7.5);

  // Near handlebar wing (sweeping back toward saddle in North Road curve)
  let nearMid = { x: stemTop.x - 36, y: stemTop.y - 4 };
  let nearGripStart = { x: stemTop.x - 68, y: stemTop.y + 12 };
  let nearGripEnd = { x: stemTop.x - 112, y: stemTop.y + 28 };
  drawSteelTube(stemTop.x, stemTop.y, nearMid.x, nearMid.y, 6.8, true);
  drawSteelTube(nearMid.x, nearMid.y, nearGripStart.x, nearGripStart.y, 6.8, true);

  // Perished, split black rubber grip (showing rusted steel bar protruding at the tip!)
  drawPerishedGrip(nearGripStart.x, nearGripStart.y, nearGripEnd.x, nearGripEnd.y, 8.8);

