function drawFrayedRopeStrand(x1, y1, x2, y2, thick) {
  let steps = 18;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  for (let i = 0; i < steps; i++) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    let sx1 = lerp(x1, x2, t1);
    let sy1 = lerp(y1, y2, t1);
    let sx2 = lerp(x1, x2, t2);
    let sy2 = lerp(y1, y2, t2);

    // Individual twisted sisal ply segment
    let plyPts = [
      [sx1 + nx * thick * 0.5, sy1 + ny * thick * 0.5],
      [sx2 + nx * thick * 0.5, sy2 + ny * thick * 0.5],
      [sx2 - nx * thick * 0.5, sy2 - ny * thick * 0.5],
      [sx1 - nx * thick * 0.5, sy1 - ny * thick * 0.5]
    ];
    new brush.Polygon(plyPts).wash(i % 2 === 0 ? PAL.ropeLight : PAL.ropeMid, 248);

    // Diagonal twist groove between rope plies
    brush.set("rotring", PAL.ropeDark, 1.25);
    brush.line(
      sx1 + nx * thick * 0.5, sy1 + ny * thick * 0.5,
      sx2 - nx * thick * 0.5, sy2 - ny * thick * 0.5
    );
    brush.set("cpencil", "#FFF3D6", 0.95);
    brush.line(sx1, sy1, sx2, sy2);

    // Tiny stray sisal hairs poking out all along the rope
    if (i % 2 === 0) {
      let side = (i % 4 === 0) ? 1 : -1;
      let hx = sx1 + nx * thick * 0.5 * side;
      let hy = sy1 + ny * thick * 0.5 * side;
      brush.set("rotring", PAL.ropeDark, 0.7);
      brush.line(hx, hy, hx + random(-8, 8), hy + random(-7, 7));
      brush.set("cpencil", PAL.ropeLight, 0.7);
      brush.line(hx, hy, hx + random(-9, 9), hy + random(-8, 8));
    }
  }

  // Outer edges of rope
  brush.set("rotring", PAL.sackDeep, 1.2);
  brush.line(x1 + nx * thick * 0.5, y1 + ny * thick * 0.5, x2 + nx * thick * 0.5, y2 + ny * thick * 0.5);
  brush.line(x1 - nx * thick * 0.5, y1 - ny * thick * 0.5, x2 - nx * thick * 0.5, y2 - ny * thick * 0.5);
}

function drawRopeKnotAndFray(kx, ky, baseDirDeg, frayLen) {
  // Knot bulb
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    brush.set("marker", i % 2 === 0 ? PAL.ropeMid : PAL.ropeDark, 1.4);
    brush.line(kx - cos(a) * 7, ky - sin(a) * 6, kx + cos(a) * 7, ky + sin(a) * 6);
  }
  brush.set("rotring", PAL.sackDeep, 1.3);
  brush.circle(kx, ky, 7, 0.2);

  // Unraveled cordage & splayed individual sisal fibers at the cut end
  let numFibers = 24;
  for (let f = 0; f < numFibers; f++) {
    let spread = map(f, 0, numFibers - 1, -34, 34) + random(-5, 5);
    let a1 = baseDirDeg - spread * 0.4;
    let a2 = baseDirDeg - spread * 0.95;
    let len1 = frayLen * random(0.35, 0.55);
    let len2 = frayLen * random(0.45, 0.75);

    let mx = kx + cos(a1) * len1;
    let my = ky - sin(a1) * len1;
    let ex = mx + cos(a2) * len2;
    let ey = my - sin(a2) * len2;

    // Dark shadow fiber + bright sunlit sisal fiber
    brush.set("rotring", f % 3 === 0 ? PAL.sackDeep : PAL.ropeDark, random(0.65, 1.1));
    brush.line(kx, ky, mx, my);
    brush.line(mx, my, ex, ey);

    brush.set("cpencil", f % 2 === 0 ? PAL.ropeLight : "#FFF5DC", random(0.6, 1.0));
    brush.line(kx + 1, ky, mx + 1, my);
    brush.line(mx + 1, my, ex + 1, ey);
  }
}

// Hyperrealist Watercolor Still Life:
// Savoury Aspic with Quail Eggs, Carrot Coins & Parsley on a Cut-Glass Platter

const CX = 535;
const CY = 575;
const YAW = -14 * Math.PI / 180;
const PITCH = 37.5 * Math.PI / 180;
const N_RIBS = 14;
const H_ASPIC = 248;
const R_ASPIC = 268;
const R_PLATTER = 418;

// Safe state helpers to guarantee brush.set() and clean fill/wash states
function setWatercolorFill(col, opacity, bleed = 0.16, tex = 0.42, border = 0.32) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

function setWatercolorFillIn(col, opacity, bleed = 0.14, tex = 0.38, border = 0.35) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "in");
  brush.fillTexture(tex, border);
}

function setSolidWash(col, opacity) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
}

function setCleanStroke(name, col, weight) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function drawPoly(pts, curvature = 0.22) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// 3D to 2D perspective projection
function proj(x, y, z) {
  const rx = x * Math.cos(YAW) - y * Math.sin(YAW);
  const ry = x * Math.sin(YAW) + y * Math.cos(YAW);
  const depth = -ry * Math.cos(PITCH) - z * Math.sin(PITCH);
  const focal = 2650;
  const s = focal / (focal + depth * 0.32);
  const sx = CX + rx * s;
  const sy = CY + (ry * Math.sin(PITCH) - z * Math.cos(PITCH)) * s;
  return [sx, sy, depth, s];
}

// Parametric 3D surface of the 14-ribbed vintage Savarin/Charlotte aspic mould
// u in [0, 1]: 0 = platter base, 0.72 = vintage waist collar, 0.90 = crown rim, 1.0 = top well
function aspicPoint3D(u, theta) {
  const uc = Math.max(0, Math.min(1, u));

  // Height profile with a slightly sunken central crown well
  let z;
  if (uc <= 0.89) {
    const t = uc / 0.89;
    z = H_ASPIC * Math.pow(Math.sin(t * Math.PI * 0.5), 0.92);
  } else {
    const t = (uc - 0.89) / 0.11;
    z = H_ASPIC - 24 * Math.sin(t * Math.PI * 0.5);
  }

  // Base radial silhouette
  let rBase;
  if (uc <= 0.89) {
    const t = uc / 0.89;
    rBase = R_ASPIC * Math.pow(1 - Math.pow(t, 2.05), 0.46) + 74 * Math.pow(t, 2.2);
  } else {
    const t = (uc - 0.89) / 0.11;
    rBase = 112 * (1 - 0.58 * t);
  }

  // Flared basal foot where unmoulded jelly slumps slightly onto the glass
  const footFlare = 14 * Math.exp(-Math.pow((uc - 0.03) / 0.045, 2));
  // Classic horizontal waist groove at u = 0.71
  const waistGroove = -13 * Math.exp(-Math.pow((uc - 0.71) / 0.055, 2));
  // Upper crown gadroon bulge around u = 0.82
  const crownBulge = 8 * Math.exp(-Math.pow((uc - 0.82) / 0.05, 2));

  // 14 plump rounded ribs separated by crisp V-shaped creases
  const phase = N_RIBS * theta;
  const ribShape = Math.pow(Math.max(0, 0.5 + 0.5 * Math.cos(phase)), 0.62);
  const ribAmp = (16 + 24 * Math.sin(Math.pow(uc, 0.58) * Math.PI * 0.94)) * (1 - 0.55 * Math.pow(uc, 4));

  // Subtle trembling gel tension harmonic
  const tremble = 2.2 * Math.sin(3 * theta + uc * 5.0) * Math.sin(uc * Math.PI);

  const r = rBase + footFlare + waistGroove + crownBulge + ribAmp * ribShape + tremble;
  const x = r * Math.cos(theta);
  const y = r * Math.sin(theta);
  return [x, y, z, r, ribShape];
}

function aspicProj(u, theta) {
  const p3 = aspicPoint3D(u, theta);
  return proj(p3[0], p3[1], p3[2]);
}

// Optical refraction & lens magnification for objects suspended inside the gel
function refractProject(x, y, z, magBoost = 1.08) {
  // Radial magnification from dome curvature
  const rHoriz = Math.hypot(x, y);
  const theta = Math.atan2(y, x);

  // Determine the front rib phase along the line of sight
  // Camera views from roughly -YAW (+y direction rotated by YAW)
  const rx = x * Math.cos(YAW) - y * Math.sin(YAW);
  const approxFrontTheta = Math.atan2(Math.sqrt(Math.max(10, R_ASPIC * R_ASPIC - rx * rx)), rx) + YAW;
  const ribPhase = N_RIBS * approxFrontTheta;

  // Snell's law deflection through the undulating flute lens in front of the point
  const tangentShift = 10.5 * Math.sin(ribPhase);
  const radialBulge = 7.5 * (0.5 + 0.5 * Math.cos(ribPhase));
  const gelTremble = 2.4 * Math.sin(x * 0.05 + z * 0.07) * Math.cos(y * 0.05);

  const tx = -Math.sin(theta);
  const ty = Math.cos(theta);

  const mx = x * magBoost + tx * tangentShift + Math.cos(theta) * radialBulge + gelTremble;
  const my = y * magBoost + ty * tangentShift + Math.sin(theta) * radialBulge;
  const mz = z * 1.03 + 4.5 * Math.cos(ribPhase) * (1 - z / H_ASPIC);

  return proj(mx, my, mz);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4278);
  noiseSeed(4278);

  // Custom brushes for soft watercolor transitions and razor-sharp wet highlights
  brush.add("glaze_soft", {
    type: "default",
    weight: 10,
    scatter: 0.32,
    sharpness: 0.14,
    grain: 0.22,
    opacity: 36,
    spacing: 0.24,
    pressure: [0.35, 1.15, 0.35],
    rotate: "natural"
  });

  brush.add("specular_blade", {
    type: "marker",
    weight: 2.6,
    scatter: 0.01,
    opacity: 245,
    spacing: 0.12,
    pressure: [0.15, 1.25, 0.15],
