  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm starched cotton-rag watercolor paper ground
  background("#fbf8ef");

  // 1. High-contrast retro background & starched tablecloth
  drawTableclothAndBackground();

  // 2. Coloured transparent shadows & golden jelly caustics on the tablecloth
  drawColouredShadowsAndCaustics();

  // 3. Back half of the cut-glass platter
  drawCutGlassPlatter(false);

  // 4. Aspic under-glazes (pale amber & celadon) and back-wall rib refractions
  drawAspicUnderGlazes();

  // 5. Deep & mid-depth suspended ingredients (veiled in amber-celadon gel)
  drawSubmergedIngredientsDeep();

  // 6. Mid-body gelatin glazes (building optical thickness & golden-celadon tint)
  drawAspicMidGlazes();

  // 7. Hero near-surface ingredients (quail eggs, carrot coins, parsley, bubbles)
  drawSubmergedIngredientsHero();

  // 8. Front surface glazes, rib valley internal reflections & wet darks
  drawAspicSurfaceGlazesAndReflections();

  // 9. Front half of the cut-glass platter overlapping the aspic base
  drawCutGlassPlatter(true);

  // 10. Prismatic rainbow sparks thrown by the platter facets onto the tablecloth
  drawPrismaticSparks();

  // 11. Razor-white reserved specular highlights along the ribbed curves & crown
  drawRazorWhiteSpeculars();

  noLoop();
}

