    [820, 245],
    [1220, 205],
    [1220, 395],
    [910, 355]
  ], 0.04);

  // Subtle woven damask check bands on the starched linen
  setWatercolorFill("#e6e2d6", 65, 0.05, 0.22, 0.25);
  drawPoly([
    [40, 920],
    [290, 810],
    [345, 865],
    [95, 985]
  ], 0.02);
  drawPoly([
    [380, 1020],
    [660, 885],
    [725, 945],
    [445, 1090]
  ], 0.02);

  // Fine graphite & colored pencil lines for the starched ironed creases
  setCleanStroke("2H", "#b5b0a1", 0.65);
  brush.line(-10, 745, 345, 614);
  brush.line(185, 1210, 500, 862);
  brush.line(820, 245, 1210, 340);
