}

// ============================================================================
// 2. COLOURED TRANSPARENT SHADOWS & GOLDEN CAUSTICS
// ============================================================================
function drawColouredShadowsAndCaustics() {
  // Sunlight from upper-left casts a long elliptical shadow to the lower-right.
  // 1) Outer shadow of the cut-glass platter: transparent cobalt-violet & slate-blue
  const platterShadowOuter = [];
  const nPts = 48;
  for (let i = 0; i < nPts; i++) {
    const a = (i / nPts) * Math.PI * 2;
    const saw = (i % 2 === 0) ? 10 : -4;
    const sx3 = 185 + (R_PLATTER * 1.06 + saw) * Math.cos(a) * 1.12;
    const sy3 = 115 + (R_PLATTER * 0.98 + saw) * Math.sin(a) * 0.95;
    const p = proj(sx3, sy3, 0);
    platterShadowOuter.push([p[0], p[1]]);
  }
  setWatercolorFill("#3c4669", 92, 0.14, 0.42, 0.45);
  drawPoly(platterShadowOuter, 0.18);

  // Second glaze of cool violet-indigo around the shadow rim (where glass blocks light)
  const aspicShadowOuter = [];
  for (let i = 0; i < 42; i++) {
    const a = (i / 42) * Math.PI * 2;
    const ribMod = 14 * Math.cos(N_RIBS * a);
    const sx3 = 275 + (355 + ribMod) * Math.cos(a) * 1.18;
    const sy3 = 165 + (295 + ribMod) * Math.sin(a) * 0.92;
    const p = proj(sx3, sy3, 0);
    aspicShadowOuter.push([p[0], p[1]]);
  }
  setWatercolorFill("#2b3454", 118, 0.18, 0.48, 0.48);
  drawPoly(aspicShadowOuter, 0.25);

  // Darker Prussian-violet penumbra band around the caustic heart
  const penumbraRing = [];
  for (let i = 0; i < 36; i++) {
    const a = (i / 36) * Math.PI * 2;
    const sx3 = 310 + 285 * Math.cos(a) * 1.15;
    const sy3 = 185 + 235 * Math.sin(a) * 0.9;
    const p = proj(sx3, sy3, 0);
    penumbraRing.push([p[0], p[1]]);
  }
  setWatercolorFill("#1f2742", 110, 0.16, 0.45, 0.4);
  drawPoly(penumbraRing, 0.25);

  // 2) GOLDEN & CELADON CAUSTIC HEART inside the shadow ("tinted gold where light passes through the jelly")
  // First lift/warm the core with luminous pale amber wash
  const causticOuter = [];
  for (let i = 0; i < 36; i++) {
    const a = (i / 36) * Math.PI * 2;
    const ribW = 16 * Math.cos(N_RIBS * a);
    const sx3 = 295 + (235 + ribW) * Math.cos(a) * 1.12;
    const sy3 = 175 + (188 + ribW) * Math.sin(a) * 0.88;
    const p = proj(sx3, sy3, 0);
    causticOuter.push([p[0], p[1]]);
  }
  setSolidWash("#f7d56e", 145);
  drawPoly(causticOuter, 0.25);

  // Layered transparent watercolor glazes of golden amber, saffron, and pale celadon in the shadow core
  setWatercolorFill("#f2b429", 135, 0.24, 0.45, 0.35);
  drawPoly(causticOuter, 0.25);

  // Inner concentrated golden-honey caustic lens
  const causticInner = [];
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    const ribW = 18 * Math.cos(N_RIBS * a * 0.5);
    const sx3 = 315 + (165 + ribW) * Math.cos(a) * 1.1;
    const sy3 = 190 + (130 + ribW) * Math.sin(a) * 0.85;
    const p = proj(sx3, sy3, 0);
    causticInner.push([p[0], p[1]]);
  }
  setWatercolorFill("#ffcf4d", 150, 0.22, 0.38, 0.3);
  drawPoly(causticInner, 0.28);

  // Pale celadon-chartreuse caustic patches (where light passed through parsley & celadon gel)
  const celadonCaustic1 = [];
  const celadonCaustic2 = [];
  for (let i = 0; i < 20; i++) {
    const a = (i / 20) * Math.PI * 2;
    const p1 = proj(245 + 95 * Math.cos(a), 145 + 70 * Math.sin(a), 0);
    const p2 = proj(375 + 85 * Math.cos(a), 225 + 65 * Math.sin(a), 0);
    celadonCaustic1.push([p1[0], p1[1]]);
    celadonCaustic2.push([p2[0], p2[1]]);
  }
  setWatercolorFill("#a3c97f", 115, 0.26, 0.4, 0.28);
  drawPoly(celadonCaustic1, 0.25);
  drawPoly(celadonCaustic2, 0.25);

  // Deep burnt-gold / amber shadow rings where internal eggs/carrots cast tinted shadows inside the caustic
  for (let k = 0; k < 5; k++) {
    const ang = -0.5 + k * 0.52;
    const ex = 290 + 115 * Math.cos(ang);
    const ey = 175 + 90 * Math.sin(ang);
    const eggShad = [];
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * Math.PI * 2;
      const p = proj(ex + 38 * Math.cos(a), ey + 28 * Math.sin(a), 0);
      eggShad.push([p[0], p[1]]);
    }
    setWatercolorFill("#b86b11", 95, 0.2, 0.4, 0.3);
    drawPoly(eggShad, 0.25);
  }

  // Bright focused caustic rib-lines curving through the golden shadow
  for (let r = 0; r < 9; r++) {
    const frac = (r - 4) / 4.2;
    const arcPts = [];
    for (let s = 0; s <= 10; s++) {
      const t = s / 10;
      const cx3 = 185 + t * 320 + Math.sin(t * Math.PI) * 35 * frac;
      const cy3 = 110 + t * 185 + frac * (95 + t * 75);
      const p = proj(cx3, cy3, 0);
      arcPts.push([p[0], p[1], 0.4 + 0.8 * Math.sin(t * Math.PI)]);
    }
    setCleanStroke("glaze_soft", "#fff2a6", 0.9);
    brush.spline(arcPts, 0.35);
    setCleanStroke("cpencil", "#fffbe0", 1.1);
    brush.spline(arcPts, 0.35);
  }

  // 3) Dark contact occlusion shadow right beneath the platter base
  const contactShadow = [];
  for (let i = 0; i < 40; i++) {
    const a = (i / 40) * Math.PI * 2;
    const p = proj(22 + (R_PLATTER * 0.96) * Math.cos(a), 18 + (R_PLATTER * 0.96) * Math.sin(a), -24);
    contactShadow.push([p[0], p[1]]);
  }
  setWatercolorFill("#141829", 175, 0.12, 0.45, 0.45);
  drawPoly(contactShadow, 0.22);
}

// ============================================================================
// 3 & 9. THE CUT-GLASS PLATTER (BACK AND FRONT HALVES)
// ============================================================================
function drawCutGlassPlatter(isFront) {
  const startIdx = isFront ? 0 : 36;
  const endIdx = isFront ? 36 : 72;
  const totalTeeth = 72;

  // Base rim undertone for back half
  if (!isFront) {
    const platterBase = [];
    for (let i = 0; i < 60; i++) {
      const a = (i / 60) * Math.PI * 2;
      const p = proj(R_PLATTER * Math.cos(a), R_PLATTER * Math.sin(a), -8);
      platterBase.push([p[0], p[1]]);
    }
    setWatercolorFill("#d9e6e3", 75, 0.08, 0.3, 0.25);
    drawPoly(platterBase, 0.2);

    // Golden-amber reflection halo on the center of the platter directly under the aspic
    const underAspicGlow = [];
    for (let i = 0; i < 40; i++) {
      const a = (i / 40) * Math.PI * 2;
      const p = proj((R_ASPIC + 22) * Math.cos(a), (R_ASPIC + 22) * Math.sin(a), -2);
      underAspicGlow.push([p[0], p[1]]);
    }
    setWatercolorFill("#e8b038", 115, 0.18, 0.4, 0.35);
    drawPoly(underAspicGlow, 0.22);
  }

  // Batch 1: Dark slate-indigo & deep teal cut-glass facets (high-contrast refraction)
  setWatercolorFill("#1e2f42", 145, 0.06, 0.35, 0.45);
  for (let i = startIdx; i < endIdx; i += 2) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.5) / totalTeeth) * Math.PI * 2;
    const a2 = ((i + 1.0) / totalTeeth) * Math.PI * 2;

    // Outer sawtooth fan bevel
    const p0 = proj(355 * Math.cos(a0), 355 * Math.sin(a0), -4);
    const p1 = proj((R_PLATTER + 8) * Math.cos(a1), (R_PLATTER + 8) * Math.sin(a1), 2);
    const p2 = proj(355 * Math.cos(a2), 355 * Math.sin(a2), -4);
    const p3 = proj(385 * Math.cos(a1), 385 * Math.sin(a1), -14);
    drawPoly([p0, p1, p2, p3], 0.04);

    // Inner diamond-cut crystal facet
    if (i % 4 === 0) {
      const d0 = proj(288 * Math.cos(a0), 288 * Math.sin(a0), -2);
      const d1 = proj(322 * Math.cos(a1), 322 * Math.sin(a1), -1);
      const d2 = proj(355 * Math.cos(a0), 355 * Math.sin(a0), -4);
      const d3 = proj(322 * Math.cos(a0 - 0.04), 322 * Math.sin(a0 - 0.04), -1);
      drawPoly([d0, d1, d2, d3], 0.02);
    }
  }

  // Batch 2: Golden-amber & celadon refracted facets (picking up the jelly color in the crystal)
  setWatercolorFill("#d99522", 130, 0.08, 0.35, 0.4);
  for (let i = startIdx + 1; i < endIdx; i += 3) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.8) / totalTeeth) * Math.PI * 2;
    const a2 = ((i + 1.6) / totalTeeth) * Math.PI * 2;
    const d0 = proj(276 * Math.cos(a1), 276 * Math.sin(a1), -1);
    const d1 = proj(318 * Math.cos(a2), 318 * Math.sin(a2), -2);
    const d2 = proj(352 * Math.cos(a1), 352 * Math.sin(a1), -3);
    const d3 = proj(318 * Math.cos(a0), 318 * Math.sin(a0), -2);
    drawPoly([d0, d1, d2, d3], 0.03);
  }

  setWatercolorFill("#7db09e", 120, 0.08, 0.35, 0.38);
  for (let i = startIdx + 2; i < endIdx; i += 3) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.7) / totalTeeth) * Math.PI * 2;
    const a2 = ((i + 1.4) / totalTeeth) * Math.PI * 2;
    const d0 = proj(315 * Math.cos(a1), 315 * Math.sin(a1), -2);
    const d1 = proj(362 * Math.cos(a2), 362 * Math.sin(a2), -3);
    const d2 = proj(405 * Math.cos(a1), 405 * Math.sin(a1), 0);
    const d3 = proj(362 * Math.cos(a0), 362 * Math.sin(a0), -3);
    drawPoly([d0, d1, d2, d3], 0.03);
  }

  // Batch 3: Crisp geometric cut-glass linework & diamond cross-hatching
  for (let i = startIdx; i < endIdx; i++) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.5) / totalTeeth) * Math.PI * 2;
    const a2 = ((i + 1.0) / totalTeeth) * Math.PI * 2;

    const pIn = proj(275 * Math.cos(a0), 275 * Math.sin(a0), 0);
    const pMid1 = proj(335 * Math.cos(a1), 335 * Math.sin(a1), -2);
    const pMid2 = proj(335 * Math.cos(a0), 335 * Math.sin(a0), -2);
    const pTip = proj((R_PLATTER + 7) * Math.cos(a1), (R_PLATTER + 7) * Math.sin(a1), 2);
    const pVal = proj((R_PLATTER - 6) * Math.cos(a2), (R_PLATTER - 6) * Math.sin(a2), -5);
    const pBot = proj((R_PLATTER + 2) * Math.cos(a1), (R_PLATTER + 2) * Math.sin(a1), -18);

    // Dark crystal bevel line
    setCleanStroke("rotring", "#1b2b3a", 0.75);
    brush.line(pIn[0], pIn[1], pMid1[0], pMid1[1]);
    brush.line(pMid1[0], pMid1[1], pTip[0], pTip[1]);
    brush.line(pTip[0], pTip[1], pVal[0], pVal[1]);
    brush.line(pTip[0], pTip[1], pBot[0], pBot[1]);

    // Refracted amber/celadon internal bevel line
    if (i % 2 === 0) {
      setCleanStroke("2H", "#85520d", 0.65);
      brush.line(pIn[0], pIn[1], pMid2[0], pMid2[1]);
    }
  }

  // Batch 4: Razor-white cut-glass facet flashes
  setSolidWash("#ffffff", 245);
  for (let i = startIdx; i < endIdx; i++) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.45) / totalTeeth) * Math.PI * 2;
    const a2 = ((i + 0.9) / totalTeeth) * Math.PI * 2;

    // Outer sawtooth white flash
    if (i % 2 === 0) {
      const p0 = proj(362 * Math.cos(a0), 362 * Math.sin(a0), -2);
      const p1 = proj((R_PLATTER + 7) * Math.cos(a1), (R_PLATTER + 7) * Math.sin(a1), 2);
      const p2 = proj(382 * Math.cos(a2), 382 * Math.sin(a2), -1);
      drawPoly([p0, p1, p2], 0.01);
    }

    // Diamond-cut white spark on the glass collar
    if (i % 3 === 0) {
      const d0 = proj(296 * Math.cos(a0), 296 * Math.sin(a0), 0);
      const d1 = proj(326 * Math.cos(a1), 326 * Math.sin(a1), 0);
      const d2 = proj(348 * Math.cos(a0), 348 * Math.sin(a0), -1);
      const d3 = proj(320 * Math.cos(a0 - 0.03), 320 * Math.sin(a0 - 0.03), 0);
      drawPoly([d0, d1, d2, d3], 0.01);
    }
  }

  // Crisp pure white edge sparkles along the cut-glass facets
  setCleanStroke("rotring", "#ffffff", 1.15);
  for (let i = startIdx; i < endIdx; i += 2) {
    const a0 = (i / totalTeeth) * Math.PI * 2;
    const a1 = ((i + 0.5) / totalTeeth) * Math.PI * 2;
    const p0 = proj(310 * Math.cos(a0), 310 * Math.sin(a0), 0);
    const p1 = proj((R_PLATTER + 7) * Math.cos(a1), (R_PLATTER + 7) * Math.sin(a1), 2);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

// ============================================================================
// 4. ASPIC UNDER-GLAZES (PALE AMBER & CELADON)
// ============================================================================
function drawAspicUnderGlazes() {
  // First build the luminous translucent base of the dome in thin watercolor washes
  // leaving the sunlit rib ridges lighter.

  // 1) Overall pale lemon-amber and celadon-cream foundation glazes per rib
  const uSteps = 16;

  // Pale Amber under-glaze batch across all 14 ribs
  setWatercolorFill("#f7df8b", 95, 0.22, 0.42, 0.3);
  for (let r = 0; r < N_RIBS; r++) {
    const th0 = (r / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.85) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 0; j <= uSteps; j++) {
      const u = j / uSteps;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 0; j--) {
      const u = j / uSteps;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.15);
  }

  // Pale Celadon under-glaze batch (stronger in the upper dome, valleys, and cool side)
  setWatercolorFill("#b8d9be", 92, 0.24, 0.44, 0.32);
  for (let r = 0; r < N_RIBS; r++) {
    const th0 = ((r - 0.35) / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.35) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 1; j <= uSteps; j++) {
      const u = j / uSteps;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 1; j--) {
      const u = j / uSteps;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.15);
  }

  // Back-wall ribs seen refracted through the dome interior (theta in [PI, 2*PI])
  setWatercolorFill("#e3ac3c", 85, 0.2, 0.38, 0.35);
  for (let r = 7; r < 14; r++) {
    const thMid = ((r + 0.5) / N_RIBS) * Math.PI * 2;
    const backRib = [];
    for (let j = 1; j <= 10; j++) {
      const u = (j / 10) * 0.85;
      const p3 = aspicPoint3D(u, thMid - 0.08);
      const pr = refractProject(p3[0] * 0.88, p3[1] * 0.88, p3[2] * 0.92, 1.0);
      backRib.push([pr[0], pr[1]]);
    }
    for (let j = 10; j >= 1; j--) {
      const u = (j / 10) * 0.85;
      const p3 = aspicPoint3D(u, thMid + 0.08);
      const pr = refractProject(p3[0] * 0.88, p3[1] * 0.88, p3[2] * 0.92, 1.0);
      backRib.push([pr[0], pr[1]]);
    }
    drawPoly(backRib, 0.2);
  }
}

// ============================================================================
// HELPER FUNCTIONS FOR REFRACTED INTERNAL INGREDIENTS
// ============================================================================
function getRefractedDiskPts(cx, cy, cz, rx, ry, tiltX, tiltY, n = 24, mag = 1.08) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const lx = rx * Math.cos(a);
    const ly = ry * Math.sin(a);
    // Orient disk facing outward/upward in 3D
    const wx = cx + lx * Math.cos(tiltY) - ly * Math.sin(tiltX) * Math.sin(tiltY);
    const wy = cy + lx * Math.sin(tiltY) + ly * Math.sin(tiltX) * Math.cos(tiltY);
    const wz = cz + ly * Math.cos(tiltX);
    const p = refractProject(wx, wy, wz, mag);
    pts.push([p[0], p[1]]);
  }
  return pts;
}

function getRefractedCarrotPts(cx, cy, cz, rad, tiltX, tiltY, crinkle = true, mag = 1.09) {
  const pts = [];
  const n = 32;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const rMod = crinkle ? rad * (1 + 0.075 * Math.cos(16 * a)) : rad;
    const lx = rMod * Math.cos(a);
    const ly = rMod * Math.sin(a);
    const wx = cx + lx * Math.cos(tiltY) - ly * Math.sin(tiltX) * Math.sin(tiltY);
    const wy = cy + lx * Math.sin(tiltY) + ly * Math.sin(tiltX) * Math.cos(tiltY);
    const wz = cz + ly * Math.cos(tiltX);
    const p = refractProject(wx, wy, wz, mag);
    pts.push([p[0], p[1]]);
  }
  return pts;
}

function drawParsleyLeaflet(cx, cy, cz, size, angleZ, isDeep) {
  // 3-lobed serrated flat-leaf Italian parsley leaflet warped by gel refraction
  const lobes = [-0.65, 0, 0.65];
  for (let l = 0; l < lobes.length; l++) {
    const la = angleZ + lobes[l];
    const lobeLen = (l === 1) ? size * 1.15 : size * 0.9;
    const pts = [];
    const steps = 10;
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const serrate = (i > 1 && i < steps - 1) ? (1 + 0.18 * ((i % 2 === 0) ? 1 : -1)) : 1;
      const lx = (lobeLen * 0.5 + lobeLen * 0.5 * Math.cos(a)) * serrate;
      const ly = (size * 0.36 * Math.sin(a)) * serrate;
      const wx = cx + lx * Math.cos(la) - ly * Math.sin(la);
      const wy = cy + (lx * Math.sin(la) + ly * Math.cos(la)) * 0.65;
      const wz = cz + (lx * Math.sin(la) + ly * Math.cos(la)) * 0.75;
      const p = refractProject(wx, wy, wz, isDeep ? 1.03 : 1.09);
      pts.push([p[0], p[1]]);
    }
    drawPoly(pts, 0.15);
  }
}

// ============================================================================
// 5. DEEP & MID-DEPTH SUSPENDED INGREDIENTS
// ============================================================================
function drawSubmergedIngredientsDeep() {
  // 1) Deep parsley clouds (bleeding celadon and viridian softly into the amber jelly)
  const deepParsley = [
    [-95, -45, 145, 34, 0.4],
    [25, -75, 165, 38, -0.3],
    [110, -20, 130, 36, 0.8],
    [-145, 35, 95, 32, -0.5],
    [135, 55, 85, 35, 0.2],
    [-35, 25, 185, 30, 1.1],
    [55, 10, 175, 32, -0.7]
  ];

  setWatercolorFill("#5b8f62", 115, 0.38, 0.48, 0.25);
  for (let i = 0; i < deepParsley.length; i++) {
    const d = deepParsley[i];
    drawParsleyLeaflet(d[0], d[1], d[2], d[3], d[4], true);
  }

  setWatercolorFill("#2e5938", 125, 0.32, 0.45, 0.3);
  for (let i = 0; i < deepParsley.length; i++) {
    const d = deepParsley[i];
    drawParsleyLeaflet(d[0] + 10, d[1] + 8, d[2] - 8, d[3] * 0.78, d[4] + 0.5, true);
  }

  // 2) Deep carrot coins (softened and shifted toward golden-tangerine by the gel)
  const deepCarrots = [
    [-135, -30, 125, 28, 0.4, 0.6],
    [125, -35, 135, 27, -0.3, -0.5],
    [0, -85, 155, 26, 0.2, 0.1],
    [-65, 35, 178, 25, 0.8, 0.3],
    [75, 30, 172, 26, -0.7, -0.3]
  ];

  setWatercolorFill("#e0671b", 135, 0.28, 0.42, 0.35);
  for (let i = 0; i < deepCarrots.length; i++) {
    const c = deepCarrots[i];
    drawPoly(getRefractedCarrotPts(c[0], c[1], c[2], c[3], c[4], c[5], true, 1.04), 0.22);
  }

  // 3) Two deeper/upper halved quail eggs seen through thicker amber-celadon jelly
  const deepEggs = [
    [-78, -18, 152, 42, 31, 0.45, 0.4],
    [82, -12, 148, 42, 31, 0.45, -0.45]
  ];

  // Albumen (egg white tinted warm amber-celadon by surrounding gel)
  setWatercolorFill("#e5dbb4", 155, 0.22, 0.38, 0.35);
  for (let i = 0; i < deepEggs.length; i++) {
    const e = deepEggs[i];
    drawPoly(getRefractedDiskPts(e[0], e[1], e[2], e[3], e[4], e[5], e[6], 24, 1.05), 0.25);
  }
  // Yolk (warm saffron-ochre)
  setWatercolorFill("#e07c16", 165, 0.2, 0.4, 0.38);
  for (let i = 0; i < deepEggs.length; i++) {
