  }
}

// ============================================================================
// 6. MID-BODY GELATIN GLAZES (AMBER & CELADON LAYERING)
// ============================================================================
function drawAspicMidGlazes() {
  // Now veil the deep ingredients with translucent glazes of pale amber, golden honey,
  // and celadon so they genuinely recede into the trembling gelatin volume.
  const uSteps = 14;

  // Golden-amber glaze along the lower and mid flanks of each rib
  setWatercolorFill("#eba934", 78, 0.24, 0.45, 0.32);
  for (let r = 0; r < N_RIBS; r++) {
    const th0 = ((r + 0.12) / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.88) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 0; j <= uSteps; j++) {
      const u = (j / uSteps) * 0.78;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 0; j--) {
      const u = (j / uSteps) * 0.78;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.18);
  }

  // Cool celadon glaze along the rib valleys and upper crown (optical path length effect)
  setWatercolorFill("#8ebf99", 82, 0.22, 0.42, 0.34);
  for (let r = 0; r < N_RIBS; r++) {
    const th0 = ((r - 0.22) / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.22) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 1; j <= uSteps; j++) {
      const u = j / uSteps;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 1; j--) {
      const u = j / uSteps;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.16);
  }
}

