// ============================================================================
// 8. FRONT SURFACE GLAZES, RIB VALLEY REFLECTIONS & WET HIGH-CONTRAST DARKS
// ============================================================================
function drawAspicSurfaceGlazesAndReflections() {
  const uSteps = 18;

  // 1) Thin surface glaze of pale amber over the front ribs (so hero ingredients sit INSIDE the gel)
  setWatercolorFill("#f2bd46", 58, 0.2, 0.38, 0.28);
  for (let r = 0; r < 8; r++) {
    const th0 = ((r + 0.18) / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.82) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 0; j <= uSteps; j++) {
      const u = (j / uSteps) * 0.92;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 0; j--) {
      const u = (j / uSteps) * 0.92;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.16);
  }

  // 2) Thin surface glaze of pale celadon on the cool flanks of each rib
  setWatercolorFill("#9ec9a6", 62, 0.18, 0.38, 0.3);
  for (let r = 0; r < 8; r++) {
    const th0 = ((r + 0.58) / N_RIBS) * Math.PI * 2;
    const th1 = ((r + 0.96) / N_RIBS) * Math.PI * 2;
    const strip = [];
    for (let j = 0; j <= uSteps; j++) {
      const u = (j / uSteps) * 0.94;
      const p = aspicProj(u, th0);
      strip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 0; j--) {
      const u = (j / uSteps) * 0.94;
      const p = aspicProj(u, th1);
      strip.push([p[0], p[1]]);
    }
    drawPoly(strip, 0.16);
  }

  // 3) HIGH-CONTRAST INTERNAL FRESNEL REFLECTIONS IN THE RIB VALLEYS
  // In hyperrealism, glossy gelatin has sharp dark-amber and deep-viridian bands right in the
  // valleys between ribs and immediately adjacent to the razor-white highlights!
  setWatercolorFillIn("#6e3e08", 138, 0.12, 0.45, 0.48);
  for (let r = 0; r < N_RIBS; r++) {
    const thVal = (r / N_RIBS) * Math.PI * 2;
    const valleyStrip = [];
    for (let j = 1; j <= uSteps; j++) {
      const u = (j / uSteps) * 0.92;
      const p = aspicProj(u, thVal - 0.032);
      valleyStrip.push([p[0], p[1]]);
    }
    for (let j = uSteps; j >= 1; j--) {
      const u = (j / uSteps) * 0.92;
      const p = aspicProj(u, thVal + 0.032);
      valleyStrip.push([p[0], p[1]]);
    }
    drawPoly(valleyStrip, 0.14);
  }

  // Deep celadon-olive internal reflection strips on the shadow side of each rib
  setWatercolorFillIn("#24452e", 125, 0.12, 0.42, 0.45);
  for (let r = 0; r < 9; r++) {
    const thShad = ((r + 0.78) / N_RIBS) * Math.PI * 2;
    const shadStrip = [];
    for (let j = 2; j <= 14; j++) {
      const u = (j / 16) * 0.85;
      const p = aspicProj(u, thShad - 0.028);
      shadStrip.push([p[0], p[1]]);
    }
    for (let j = 14; j >= 2; j--) {
      const u = (j / 16) * 0.85;
      const p = aspicProj(u, thShad + 0.028);
      shadStrip.push([p[0], p[1]]);
    }
    drawPoly(shadStrip, 0.14);
  }

  // 4) Horizontal waist-collar amber & olive refraction ring at u = 0.71
  const waistRing = [];
  for (let i = 0; i <= 42; i++) {
    const th = (i / 42) * Math.PI * 1.15 - 0.1;
    const p = aspicProj(0.69, th);
    waistRing.push([p[0], p[1]]);
  }
  for (let i = 42; i >= 0; i--) {
    const th = (i / 42) * Math.PI * 1.15 - 0.1;
    const p = aspicProj(0.735, th);
    waistRing.push([p[0], p[1]]);
  }
  setWatercolorFill("#8a4f0b", 125, 0.12, 0.4, 0.42);
  drawPoly(waistRing, 0.18);

  // 5) Scalloped top crown well (golden amber pool in the top dimple of the aspic)
  const topWellOuter = [];
  const topWellInner = [];
  for (let i = 0; i < 42; i++) {
    const th = (i / 42) * Math.PI * 2;
    const pOut = aspicProj(0.90, th);
    const pIn = aspicProj(0.98, th);
    topWellOuter.push([pOut[0], pOut[1]]);
    topWellInner.push([pIn[0], pIn[1]]);
  }
  setWatercolorFill("#d9921e", 130, 0.18, 0.42, 0.38);
  drawPoly(topWellOuter, 0.22);
  setWatercolorFill("#688c65", 115, 0.2, 0.4, 0.35);
  drawPoly(topWellInner, 0.22);

  // 6) Wet dark amber-umber basal meniscus where the scalloped jelly foot meets the glass platter
  const meniscusStrip = [];
  for (let i = 0; i <= 48; i++) {
    const th = (i / 48) * Math.PI * 1.08 - 0.04;
    const p = aspicProj(0.0, th);
    meniscusStrip.push([p[0], p[1]]);
  }
  for (let i = 48; i >= 0; i--) {
    const th = (i / 48) * Math.PI * 1.08 - 0.04;
    const p = aspicProj(0.035, th);
    meniscusStrip.push([p[0], p[1]]);
  }
  setWatercolorFill("#4d2905", 165, 0.1, 0.45, 0.48);
  drawPoly(meniscusStrip, 0.18);

  // Fine crisp rib crease lines in dark amber and viridian for hyperreal optical snap
  for (let r = 0; r < N_RIBS; r++) {
    const thVal = (r / N_RIBS) * Math.PI * 2;
    const pts = [];
    for (let j = 0; j <= 16; j++) {
      const u = (j / 16) * 0.92;
      const p = aspicProj(u, thVal);
      pts.push([p[0], p[1], 0.5 + 0.6 * Math.sin((j / 16) * Math.PI)]);
    }
    setCleanStroke("cpencil", "#542f06", 0.85);
    brush.spline(pts, 0.3);
  }
}

