    [-95, 455, 34, 10, 1.75],
    [45, 475, 36, 11, 1.35],
    [155, 445, 32, 10, 0.95],
    [-245, 415, 32, 10, 2.15],
    [-365, 325, 30, 9, 2.45],
    [-445, 195, 28, 9, 2.75]
  ];

  const spectralColors = [
    ["#e61e54", 185], // Crimson-magenta
    ["#ff9914", 195], // Cadmium orange-gold
    ["#7ae582", 185], // Chartreuse-emerald
    ["#00b4d8", 190], // Electric cyan
    ["#7209b7", 175]  // Dioxazine violet
  ];

  // Draw spectral bands in color batches for performance
  for (let cIdx = 0; cIdx < spectralColors.length; cIdx++) {
    const col = spectralColors[cIdx][0];
    const opac = spectralColors[cIdx][1];
    setWatercolorFill(col, opac, 0.14, 0.35, 0.3);

    const offsetFrac = (cIdx - 2) * 0.38;
    for (let i = 0; i < sparks.length; i++) {
      const sp = sparks[i];
      const ca = Math.cos(sp[4]);
      const sa = Math.sin(sp[4]);
      const nx = -sa;
      const ny = ca;

      const cx = sp[0] + nx * sp[3] * offsetFrac;
      const cy = sp[1] + ny * sp[3] * offsetFrac;
      const hl = sp[2] * 0.52;
      const hw = sp[3] * 0.32;

      const p0 = proj(cx - ca * hl, cy - sa * hl, 0);
      const p1 = proj(cx + nx * hw, cy + ny * hw, 0);
      const p2 = proj(cx + ca * hl, cy + sa * hl, 0);
      const p3 = proj(cx - nx * hw, cy - ny * hw, 0);
      drawPoly([p0, p1, p2, p3], 0.12);
    }
  }

  // Blinding razor-white core inside every prismatic spark
  setSolidWash("#ffffff", 250);
  for (let i = 0; i < sparks.length; i++) {
    const sp = sparks[i];
    const ca = Math.cos(sp[4]);
    const sa = Math.sin(sp[4]);
    const nx = -sa;
    const ny = ca;
    const hl = sp[2] * 0.42;
    const hw = sp[3] * 0.18;

    const p0 = proj(sp[0] - ca * hl, sp[1] - sa * hl, 0);
    const p1 = proj(sp[0] + nx * hw, sp[1] + ny * hw, 0);
    const p2 = proj(sp[0] + ca * hl, sp[1] + sa * hl, 0);
    const p3 = proj(sp[0] - nx * hw, sp[1] - ny * hw, 0);
    drawPoly([p0, p1, p2, p3], 0.05);
  }

  setCleanStroke("rotring", "#ffffff", 1.1);
  for (let i = 0; i < sparks.length; i++) {
    const sp = sparks[i];
    const ca = Math.cos(sp[4]);
    const sa = Math.sin(sp[4]);
    const p0 = proj(sp[0] - ca * sp[2] * 0.38, sp[1] - sa * sp[2] * 0.38, 0);
    const p1 = proj(sp[0] + ca * sp[2] * 0.38, sp[1] + sa * sp[2] * 0.38, 0);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

// ============================================================================
// 11. RAZOR-WHITE RESERVED SPECULAR HIGHLIGHTS ON THE RIBBED CURVES
// ============================================================================
function drawRazorWhiteSpeculars() {
  // "Specular highlights sit as razor-white reserved shapes along the ribbed curves."
  // First draw a crisp amber/celadon watercolor watermark border right around each highlight,
  // then fill the reserved shapes with pure, opaque razor-white (#ffffff).

  const ribHighlightShapes = [];
  const crownHighlightShapes = [];
  const waistHighlightShapes = [];
  const baseHighlightShapes = [];

  for (let r = 0; r < N_RIBS; r++) {
    // Sunlit side of each rib is around r + 0.36
    const thLight = ((r + 0.36) / N_RIBS) * Math.PI * 2;
    // Visibility & intensity higher on the front and left ribs, thinner rim-lights on back-right ribs
    const isFrontOrLeft = (r <= 8 || r >= 12);
    const widthScale = isFrontOrLeft ? 0.022 : 0.012;

    // 1) Main lower-to-waist vertical rib highlight ribbon (u = 0.07 to 0.67)
    const mainRib = [];
    const steps = 14;
    for (let j = 0; j <= steps; j++) {
      const t = j / steps;
      const u = 0.07 + t * 0.60;
      const w = widthScale * Math.sin(t * Math.PI);
      const p = aspicProj(u, thLight - w);
      mainRib.push([p[0], p[1]]);
    }
    for (let j = steps; j >= 0; j--) {
      const t = j / steps;
      const u = 0.07 + t * 0.60;
      const w = widthScale * Math.sin(t * Math.PI);
      const p = aspicProj(u, thLight + w);
      mainRib.push([p[0], p[1]]);
    }
    ribHighlightShapes.push(mainRib);

    // 2) Upper shoulder gadroon highlight above the waist collar (u = 0.74 to 0.89)
    const upperRib = [];
    for (let j = 0; j <= 8; j++) {
      const t = j / 8;
      const u = 0.74 + t * 0.15;
      const w = (widthScale * 1.15) * Math.sin(t * Math.PI);
      const p = aspicProj(u, thLight - w);
      upperRib.push([p[0], p[1]]);
    }
    for (let j = 8; j >= 0; j--) {
      const t = j / 8;
      const u = 0.74 + t * 0.15;
      const w = (widthScale * 1.15) * Math.sin(t * Math.PI);
      const p = aspicProj(u, thLight + w);
      upperRib.push([p[0], p[1]]);
    }
    crownHighlightShapes.push(upperRib);

    // 3) Horizontal crescent specular at the waist collar (u = 0.70..0.725)
    if (isFrontOrLeft) {
      const waistCres = [];
      for (let j = 0; j <= 6; j++) {
        const t = j / 6;
        const th = thLight - 0.055 + t * 0.11;
        const p = aspicProj(0.705, th);
        waistCres.push([p[0], p[1]]);
      }
      for (let j = 6; j >= 0; j--) {
        const t = j / 6;
        const th = thLight - 0.055 + t * 0.11;
        const p = aspicProj(0.725, th);
        waistCres.push([p[0], p[1]]);
      }
      waistHighlightShapes.push(waistCres);
    }

    // 4) Wet basal meniscus highlight along the scalloped foot (u = 0.01..0.04)
    if (r <= 7) {
      const baseCres = [];
      for (let j = 0; j <= 6; j++) {
        const t = j / 6;
        const th = thLight - 0.06 + t * 0.12;
        const p = aspicProj(0.012, th);
        baseCres.push([p[0], p[1]]);
      }
      for (let j = 6; j >= 0; j--) {
        const t = j / 6;
        const th = thLight - 0.06 + t * 0.12;
        const p = aspicProj(0.032, th);
        baseCres.push([p[0], p[1]]);
      }
      baseHighlightShapes.push(baseCres);
    }
  }

  // Top crown rim scalloped specular ring (u = 0.89..0.92)
  for (let r = 0; r < N_RIBS; r++) {
    const th0 = ((r + 0.15) / N_RIBS) * Math.PI * 2;
    const crownBead = [];
    for (let j = 0; j <= 6; j++) {
      const t = j / 6;
      const th = th0 + t * 0.16;
      const p = aspicProj(0.885, th);
      crownBead.push([p[0], p[1]]);
    }
    for (let j = 6; j >= 0; j--) {
      const t = j / 6;
      const th = th0 + t * 0.16;
      const p = aspicProj(0.912, th);
      crownBead.push([p[0], p[1]]);
    }
    crownHighlightShapes.push(crownBead);
  }

  // Step A: Crisp amber-gold watermark border around the reserved white shapes
  setCleanStroke("2H", "#c98418", 0.75);
  for (let i = 0; i < ribHighlightShapes.length; i++) drawPoly(ribHighlightShapes[i], 0.12);
  for (let i = 0; i < crownHighlightShapes.length; i++) drawPoly(crownHighlightShapes[i], 0.12);

  // Step B: Pure razor-white solid wash inside all reserved specular shapes
  setSolidWash("#ffffff", 255);
  for (let i = 0; i < ribHighlightShapes.length; i++) drawPoly(ribHighlightShapes[i], 0.12);
  for (let i = 0; i < crownHighlightShapes.length; i++) drawPoly(crownHighlightShapes[i], 0.12);
  for (let i = 0; i < waistHighlightShapes.length; i++) drawPoly(waistHighlightShapes[i], 0.12);
  for (let i = 0; i < baseHighlightShapes.length; i++) drawPoly(baseHighlightShapes[i], 0.12);

  // Step C: Reinforce the spine and razor-sharp edges of every specular highlight with pure white strokes
  for (let r = 0; r < N_RIBS; r++) {
    const thLight = ((r + 0.36) / N_RIBS) * Math.PI * 2;
    const isFrontOrLeft = (r <= 8 || r >= 12);

    const spine1 = [];
    for (let j = 0; j <= 10; j++) {
      const t = j / 10;
      const u = 0.08 + t * 0.58;
      const p = aspicProj(u, thLight);
      spine1.push([p[0], p[1], isFrontOrLeft ? (0.4 + 1.1 * Math.sin(t * Math.PI)) : 0.55]);
    }
    setCleanStroke("specular_blade", "#ffffff", isFrontOrLeft ? 1.35 : 0.75);
    brush.spline(spine1, 0.25);

    const spine2 = [];
    for (let j = 0; j <= 6; j++) {
      const t = j / 6;
      const u = 0.745 + t * 0.14;
      const p = aspicProj(u, thLight);
      spine2.push([p[0], p[1], isFrontOrLeft ? 1.15 : 0.6]);
    }
    setCleanStroke("specular_blade", "#ffffff", isFrontOrLeft ? 1.25 : 0.7);
    brush.spline(spine2, 0.25);
  }

  // Secondary thin wet reflection threads along the opposite edge of the front ribs
  setCleanStroke("rotring", "#ffffff", 0.95);
  for (let r = 0; r <= 7; r++) {
    const thSec = ((r + 0.68) / N_RIBS) * Math.PI * 2;
    const secPts = [];
    for (let j = 0; j <= 8; j++) {
      const u = 0.18 + (j / 8) * 0.44;
      const p = aspicProj(u, thSec);
      secPts.push([p[0], p[1], 0.3 + 0.6 * Math.sin((j / 8) * Math.PI)]);
    }
    brush.spline(secPts, 0.25);
  }
}

