    let tx = vDot(toBall, camRight);
    let ty = vDot(toBall, camUp);

    let rawCx = (tx / tz) * focalLength;
    let rawCy = -(ty / tz) * focalLength;
    let rawCr = (R / tz) * focalLength;

    minX = Math.min(minX, rawCx - rawCr);
    maxX = Math.max(maxX, rawCx + rawCr);
    minY = Math.min(minY, rawCy - rawCr);
    maxY = Math.max(maxY, rawCy + rawCr);

    // Build ball-local camera basis (bForward points from ball toward camera)
    let bForward = vNorm(vSub(camPos, pos));
    let bRight = vNorm(vCross(v3(0, 1, 0), bForward));
    let bUp = vNorm(vCross(bForward, bRight));

    // Specular normal for overhead lamp
    let toLamp = vNorm(vSub(lampPos, pos));
    let starNorm = vNorm(vAdd(bForward, toLamp));

    // Number disc normal in world space
    let dU = spec.discTilt[0];
    let dV = spec.discTilt[1];
    let dW = Math.sqrt(Math.max(0.1, 1 - dU * dU - dV * dV));
    let discNorm = vNorm(vAdd(vAdd(vScale(bRight, dU), vScale(bUp, dV)), vScale(bForward, dW)));

    balls.push({
      ...spec,
      pos,
      tz,
      rawCx,
      rawCy,
      rawCr,
      bForward,
      bRight,
      bUp,
      starNorm,
      discNorm
    });
  }

  // Frame the 15-ball rack inside [75, 1125] x [165, 1075]
  let spanX = maxX - minX;
  let spanY = maxY - minY;
  projScale = Math.min(1050 / spanX, 900 / spanY);
  projOffsetX = 600 - ((minX + maxX) * 0.5) * projScale;
  projOffsetY = 625 - ((minY + maxY) * 0.5) * projScale;

  for (let b of balls) {
    b.cx = b.rawCx * projScale + projOffsetX;
    b.cy = b.rawCy * projScale + projOffsetY;
    b.cr = b.rawCr * projScale;
  }

  // Sort back-to-front (largest tz first)
  balls.sort((a, b) => b.tz - a.tz);
}

// Project any 3D world point to 2D canvas coordinates
function projectWorldPoint(pt) {
  let toPt = vSub(pt, camPos);
  let tz = Math.max(0.5, vDot(toPt, camForward));
  let tx = vDot(toPt, camRight);
  let ty = vDot(toPt, camUp);
  let rawX = (tx / tz) * focalLength;
  let rawY = -(ty / tz) * focalLength;
  return [
    rawX * projScale + projOffsetX,
    rawY * projScale + projOffsetY,
    tz
  ];
}

// Project a unit normal N on ball b to 2D screen coordinates inside (b.cx, b.cy, b.cr)
function ballNormalToScreen(b, nVec) {
  let u = vDot(nVec, b.bRight);
  let v = vDot(nVec, b.bUp);
  let w = vDot(nVec, b.bForward);
  return {
    x: b.cx + u * b.cr,
    y: b.cy - v * b.cr,
    u,
    v,
    w
  };
}

// Build orthonormal tangent basis (t1, t2) on the sphere around unit axisVec
function buildSphericalBasis(axisVec, refUp) {
  let up = refUp || v3(0, 1, 0);
  if (Math.abs(vDot(axisVec, up)) > 0.95) up = v3(1, 0, 0);
  let t1 = vNorm(vCross(up, axisVec));
  let t2 = vNorm(vCross(axisVec, t1));
  return { t1, t2 };
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep viridian baize foundation & directional felt nap
  drawViridianBaize();

  // 2. Contact & cast shadows + glowing colored lacquer bounces on the baize
  drawRackShadowsAndBounces();

  // 3. Render all 15 spheres back-to-front with Delaunay rings, neighbour reflections,
  //    slightly misregistered white number discs, and the chorus of hard white stars
  brush.noField();
  for (let i = 0; i < balls.length; i++) {
    drawBilliardBall(balls[i]);
  }

  // 4. Foreground directional felt nap overlaps & subtle chromatic dust
  drawForegroundBaizeNap();

  noLoop();
}

// ============================================================================
// 1. DEEP VIRIDIAN BAIZE & FELT NAP
// ============================================================================
function drawViridianBaize() {
  background(PALETTE.baizeDeep);
  brush.noField();
  brush.noStroke();

  // Broad atmospheric washes on the viridian baize
  // Deep shadow vignette corners
  brush.wash(PALETTE.baizeShadowBlue, 120);
  brush.rect(0, 0, 1200, 320, "corner");
  brush.rect(0, 940, 1200, 260, "corner");

  // Lit emerald-viridian pool under the overhead lamp
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  brush.fill(PALETTE.baizeMid, 130);
  brush.circle(600, 560, 580, 0.15);

  brush.fill(PALETTE.baizeLit, 95);
  brush.circle(590, 510, 420, 0.15);

  brush.fill(PALETTE.baizePastel, 45);
  brush.circle(580, 460, 270, 0.15);
  brush.noFill();
  brush.noWash();

  // Fine directional felt nap strokes across the table plane
  brush.wiggle(1.1);

  const napColors = [
    { col: PALETTE.baizeDark, wt: 0.42, count: 950, yMin: 0, yMax: 1200, xSpread: 600 },
    { col: PALETTE.baizeMid, wt: 0.38, count: 950, yMin: 40, yMax: 1180, xSpread: 580 },
    { col: PALETTE.baizeShadowBlue, wt: 0.40, count: 520, yMin: 0, yMax: 1200, xSpread: 600 },
    { col: PALETTE.baizeShadowViolet, wt: 0.36, count: 360, yMin: 450, yMax: 1200, xSpread: 580 },
    { col: PALETTE.baizeLit, wt: 0.34, count: 720, yMin: 60, yMax: 980, xSpread: 520 },
    { col: PALETTE.baizePastel, wt: 0.30, count: 480, yMin: 90, yMax: 860, xSpread: 460 },
    { col: PALETTE.baizeMint, wt: 0.26, count: 240, yMin: 120, yMax: 740, xSpread: 380 }
  ];

  for (let layer of napColors) {
    brush.set("nap_fiber", layer.col, layer.wt);
    for (let i = 0; i < layer.count; i++) {
      let y = random(layer.yMin, layer.yMax);
      let xCenter = 600 + random(-layer.xSpread, layer.xSpread);
      // Perspective convergence of table nap grain + subtle brushed wave
      let perspSlope = ((xCenter - 600) / 600) * 0.055;
      let napLen = map(y, 0, 1200, 18, 46) * random(0.65, 1.35);
      let dy = napLen * perspSlope + (noise(xCenter * 0.005, y * 0.005) - 0.5) * 4.5;
      brush.line(xCenter - napLen * 0.5, y - dy * 0.5, xCenter + napLen * 0.5, y + dy * 0.5);
    }
  }

  brush.noField();
}

// ============================================================================
// 2. CAST SHADOWS & LACQUER BOUNCE CAUSTICS ON THE BAIZE
// ============================================================================
function drawRackShadowsAndBounces() {
  brush.noField();

  for (let b of balls) {
    // Contact point on table directly under ball (y = 0)
    let contactPt = v3(b.pos.x, 0, b.pos.z);
    let [sx, sy] = projectWorldPoint(contactPt);
    let rx = b.cr * 1.06;
    let ry = b.cr * 0.44;

    // Shift shadow slightly away from lamp position
    let dxLamp = (b.pos.x - lampPos.x) * b.cr * 0.045;
    let dzLamp = (b.pos.z - lampPos.z) * b.cr * 0.025;
    let shX = sx + dxLamp;
    let shY = sy + dzLamp + b.cr * 0.08;

    // 1. Colored caustic/bounce halo on the viridian baize around the shadow
    brush.set("nap_fiber", b.bounceCol, 0.34);
    for (let i = 0; i < 65; i++) {
      let ang = random(180, 360) + random(-25, 25);
      let rad = random(0.75, 1.35);
      let px = shX + Math.cos(ang * Math.PI / 180) * rx * rad;
      let py = shY - Math.sin(ang * Math.PI / 180) * ry * rad;
      let len = b.cr * random(0.08, 0.18);
      brush.line(px - len * 0.5, py, px + len * 0.5, py + random(-1.5, 1.5));
    }

    // Simultaneous contrast edge ticks in the shadow (ultramarine & violet)
    let contrastShadowCol = (b.ringOuter === PALETTE.ultraVivid) ? PALETTE.ultraVivid : PALETTE.violetVivid;
    brush.set("nap_fiber", contrastShadowCol, 0.32);
    for (let i = 0; i < 45; i++) {
      let ang = random(0, 360);
      let rad = random(0.55, 1.05);
      let px = shX + Math.cos(ang * Math.PI / 180) * rx * rad;
      let py = shY + Math.sin(ang * Math.PI / 180) * ry * rad;
      let len = b.cr * random(0.07, 0.15);
      brush.line(px - len * 0.5, py, px + len * 0.5, py);
    }

    // 2. Deep core contact shadow (ultramarine-black & dioxazine purple)
    brush.set("cp_vivid", "#06101f", 0.55);
    for (let i = 0; i < 75; i++) {
      let t = random(0, 1);
      let ang = random(0, 360);
      let rFrac = Math.pow(t, 0.65) * 0.88;
      let px = shX + Math.cos(ang * Math.PI / 180) * rx * rFrac;
      let py = shY + Math.sin(ang * Math.PI / 180) * ry * rFrac;
      let len = b.cr * (1 - rFrac * 0.5) * random(0.08, 0.18);
      brush.line(px - len * 0.5, py, px + len * 0.5, py);
    }

    // 3. Crevice ambient occlusion right under the ball's bottom tangent
    brush.set("cp_detail", "#030712", 0.62);
    for (let i = 0; i < 40; i++) {
      let u = random(-0.55, 0.55);
      let px = sx + u * rx * 0.9;
      let py = sy + (1 - u * u) * ry * 0.18 + random(-2, 3);
      let len = b.cr * random(0.06, 0.13);
      brush.line(px - len * 0.5, py, px + len * 0.5, py);
    }
  }
}

// ============================================================================
// 3. HYPERREAL BILLIARD BALL WITH DELAUNAY RINGS & BURNISHED COLOURED PENCIL
// ============================================================================
function drawBilliardBall(b) {
  // Step A: Solid opaque base wash so the viridian baize never shows through
  drawSphereBaseWash(b);

  // Step B: Concentric & Sectored Delaunay Simultaneous-Contrast Rings
  drawDelaunaySimultaneousRings(b);

  // Step C: Equatorial Stripe & Polar Ivory Caps (for striped balls #9-#15)
  if (b.striped) {
    drawStripedBallPolarCaps(b);
  }

  // Step D: Reflections of the Viridian Baize & Adjacent Neighbour Balls
  drawBaizeAndNeighbourReflections(b);

  // Step E: Perfect Numbered White Disc with Slight Print Misregistration
  drawNumberedWhiteDisc(b);

  // Step F: High-Gloss Burnished Coloured Pencil Sheen & Lamp Halo Rings
  drawLampHaloAndBurnish(b);

  // Step G: The Chorus — Single Hard White Star on Every Sphere
  drawHardWhiteStar(b);
}

// Helper: Draw a closed circle/polygon using brush.beginShape(0)
function drawCleanCircleShape(cx, cy, r, steps = 48) {
  brush.beginShape(0);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    brush.vertex(
      cx + Math.cos(a * Math.PI / 180) * r,
      cy + Math.sin(a * Math.PI / 180) * r
    );
  }
  brush.endShape(true);
}

function drawSphereBaseWash(b) {
  brush.noStroke();
  brush.noFill();

  // Opaque underpainting wash
  let baseCol = b.striped ? PALETTE.ivoryBase : b.bodyDark;
  brush.wash(baseCol, 250);
  drawCleanCircleShape(b.cx, b.cy, b.cr * 0.992, 56);

  // Midtone body wash shifted toward upper crown
  brush.wash(b.bodyMid, b.striped ? 185 : 225);
  drawCleanCircleShape(b.cx - b.cr * 0.03, b.cy - b.cr * 0.05, b.cr * 0.86, 48);

  // Soft pastel crown wash
  brush.wash(b.bodyPastel, 165);
  drawCleanCircleShape(b.cx - b.cr * 0.06, b.cy - b.cr * 0.18, b.cr * 0.56, 40);

  brush.noWash();
}

// Helper: Draw a circular arc inside the sphere using smooth spline segments
function drawSphereArc(cx, cy, r, degStart, degEnd, brushName, col, weight) {
  if (r <= 1.5) return;
  let span = Math.abs(degEnd - degStart);
  let steps = Math.max(5, Math.min(28, Math.ceil((span / 360) * (r * 0.45))));
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = (degStart + (degEnd - degStart) * (i / steps)) * Math.PI / 180;
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  brush.set(brushName, col, weight);
  brush.spline(pts, 0.4);
}

function drawDelaunaySimultaneousRings(b) {
  // Concentric ring bands from outer grazing edge (0.99 * cr) inward to core
  // In Delaunay's simultaneous contrast discs, rings split into angular sectors
  // where Orange vibrates against Ultramarine and Violet halos sit against Lemon.
  const sectorOffset = (b.num * 37) % 360;

  const ringBands = [
    // Grazing outer rim: sharpest simultaneous contrast
    {
      rMin: 0.91, rMax: 0.992, steps: 6,
      sectors: [
        { a0: 0, a1: 115, col: b.ringOuter },
        { a0: 115, a1: 215, col: b.ringAltA },
        { a0: 215, a1: 305, col: b.ringOuter },
        { a0: 305, a1: 360, col: b.ringAltB }
      ],
      brushName: "cp_vivid", wt: 0.58
    },
    // Second simultaneous contrast band (direct complement of outer rim!)
    {
      rMin: 0.79, rMax: 0.915, steps: 6,
      sectors: [
        { a0: 0, a1: 115, col: b.ringInner },
        { a0: 115, a1: 215, col: b.ringAltB },
        { a0: 215, a1: 305, col: b.ringInner },
        { a0: 305, a1: 360, col: b.ringAltA }
      ],
      brushName: "cp_vivid", wt: 0.62
    },
    // Third band: local body dark & mid blended with violet/lemon or orange/ultra chords
    {
      rMin: 0.62, rMax: 0.80, steps: 7,
      sectors: [
        { a0: 0, a1: 140, col: b.bodyMid },
        { a0: 140, a1: 230, col: b.ringOuter },
        { a0: 230, a1: 360, col: b.bodyDark }
      ],
      brushName: "cp_burnish", wt: 0.68
    },
    // Fourth band: burnished pastel body glow + Delaunay inner halo
    {
      rMin: 0.40, rMax: 0.64, steps: 7,
      sectors: [
        { a0: 0, a1: 165, col: b.bodyPastel },
        { a0: 165, a1: 265, col: b.ringInner },
        { a0: 265, a1: 360, col: b.bodyMid }
      ],
      brushName: "cp_burnish", wt: 0.72
    },
    // Inner core: high-gloss pastel burnishing
    {
      rMin: 0.12, rMax: 0.42, steps: 6,
      sectors: [
        { a0: 0, a1: 190, col: b.bodyGleam },
        { a0: 190, a1: 360, col: b.bodyPastel }
      ],
      brushName: "cp_burnish", wt: 0.75
    }
  ];

  // 1. Concentric pencil arc pass
  for (let band of ringBands) {
    for (let s = 0; s < band.steps; s++) {
      let t = s / Math.max(1, band.steps - 1);
      let r = b.cr * (band.rMin + (band.rMax - band.rMin) * t);
      for (let sec of band.sectors) {
        let aStart = sec.a0 + sectorOffset + random(-4, 4);
        let aEnd = sec.a1 + sectorOffset + random(-4, 4);
        drawSphereArc(b.cx, b.cy, r, aStart, aEnd, band.brushName, sec.col, band.wt);
      }
    }
  }

  // 2. Radial cross-contour coloured-pencil burnishing ticks that knit the rings together
  let radialCount = Math.floor(b.cr * 0.95);
  for (let i = 0; i < radialCount; i++) {
    let angDeg = (i / radialCount) * 360 + random(-1.5, 1.5);
    let angRad = angDeg * Math.PI / 180;
    let r0 = b.cr * random(0.45, 0.84);
    let r1 = Math.min(b.cr * 0.985, r0 + b.cr * random(0.08, 0.16));

    // Curve the stroke slightly along the sphere's meridian
    let midR = (r0 + r1) * 0.5;
    let curveAng = angRad + 0.06;

    let colChoice;
    let relAng = ((angDeg - sectorOffset) % 360 + 360) % 360;
    if (r0 > b.cr * 0.78) {
      colChoice = (relAng < 180) ? b.ringOuter : b.ringAltA;
    } else {
      colChoice = (relAng < 180) ? b.bodyPastel : b.ringInner;
    }

    brush.set("cp_detail", colChoice, 0.36);
    brush.spline([
      [b.cx + Math.cos(angRad) * r0, b.cy + Math.sin(angRad) * r0],
      [b.cx + Math.cos(curveAng) * midR, b.cy + Math.sin(curveAng) * midR],
      [b.cx + Math.cos(angRad) * r1, b.cy + Math.sin(angRad) * r1]
    ], 0.35);
  }

  // 3. Vibrating simultaneous-contrast rim contour (Orange vs Ultramarine, Violet vs Lemon)
  drawSphereArc(b.cx, b.cy, b.cr * 0.988, sectorOffset, sectorOffset + 180, "cp_detail", b.ringOuter, 0.52);
  drawSphereArc(b.cx, b.cy, b.cr * 0.988, sectorOffset + 180, sectorOffset + 360, "cp_detail", b.ringAltA, 0.52);
  drawSphereArc(b.cx, b.cy, b.cr * 0.958, sectorOffset, sectorOffset + 180, "cp_detail", b.ringInner, 0.46);
  drawSphereArc(b.cx, b.cy, b.cr * 0.958, sectorOffset + 180, sectorOffset + 360, "cp_detail", b.ringAltB, 0.46);
}

// ============================================================================
// STRIPED BALLS (#9 - #15): POLAR IVORY CAPS & SIMULTANEOUS CONTRAST BORDERS
// ============================================================================
function drawStripedBallPolarCaps(b) {
  // Stripe equator contains b.discNorm; the pole axis is perpendicular to b.discNorm
  let yawRad = (b.stripeYaw || 0) * Math.PI / 180;
  let tiltRef = vNorm(vAdd(vScale(b.bUp, Math.cos(yawRad)), vScale(b.bRight, Math.sin(yawRad))));
  let poleAxis = vNorm(vCross(b.discNorm, vCross(tiltRef, b.discNorm)));
  let basis = buildSphericalBasis(poleAxis, b.bForward);

  // Draw both polar caps (sign = +1 and sign = -1) where |dot(N, poleAxis)| > 0.50
  for (let sign of [1, -1]) {
    let pAxis = vScale(poleAxis, sign);

    // Latitude circles from border (lat = 30 deg from equator, i.e. alpha = 60 deg from pole) to pole
    let latSteps = 14;
    for (let s = 0; s < latSteps; s++) {
      let t = s / (latSteps - 1);
      let alpha = (0.04 + (1 - t) * 0.96) * 0.98; // angular distance from pole in radians

      let strokeCol;
      let brushName = "cp_burnish";
      let wt = 0.68;

      if (s === 0) {
        // Simultaneous contrast border halo right against the colored stripe!
        strokeCol = b.ringOuter;
        brushName = "cp_vivid";
        wt = 0.55;
      } else if (s === 1) {
        strokeCol = b.ringInner;
        brushName = "cp_vivid";
        wt = 0.52;
      } else if (s < 5) {
        strokeCol = PALETTE.ivoryShadow;
      } else if (s < 10) {
        strokeCol = PALETTE.ivoryBase;
      } else {
        strokeCol = PALETTE.ivoryCream;
      }

      drawSphericalCircleOnBall(b, pAxis, basis.t1, basis.t2, alpha, brushName, strokeCol, wt, 36);
    }
  }
}

// Trace a circle on the 3D sphere around axisVec of angular radius alphaRad
// and draw all visible segments (w > 0.02) clipped naturally to the sphere's horizon!
function drawSphericalCircleOnBall(b, axisVec, t1, t2, alphaRad, brushName, col, weight, numPts = 40, fillWashCol = null, fillAlpha = 230) {
  let sinA = Math.sin(alphaRad);
  let cosA = Math.cos(alphaRad);

  let currentRun = [];
  let runs = [];
  let fillPoly = [];

  for (let i = 0; i <= numPts; i++) {
    let phi = (i / numPts) * Math.PI * 2;
    let cosP = Math.cos(phi);
    let sinP = Math.sin(phi);

    let nVec = vAdd(
      vScale(axisVec, cosA),
      vAdd(vScale(t1, sinA * cosP), vScale(t2, sinA * sinP))
    );
    let proj = ballNormalToScreen(b, nVec);

    if (proj.w > 0.015) {
      currentRun.push([proj.x, proj.y]);
      if (i < numPts) fillPoly.push([proj.x, proj.y]);
    } else {
      if (currentRun.length >= 2) runs.push(currentRun);
      currentRun = [];
    }
  }
  if (currentRun.length >= 2) runs.push(currentRun);

  if (fillWashCol && fillPoly.length >= 4) {
    brush.noStroke();
    brush.wash(fillWashCol, fillAlpha);
    brush.beginShape(0);
    for (let pt of fillPoly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noWash();
  }

  if (col && weight > 0) {
    brush.set(brushName, col, weight);
    for (let run of runs) {
      if (run.length === 2) {
        brush.line(run[0][0], run[0][1], run[1][0], run[1][1]);
      } else if (run.length > 2) {
        brush.spline(run, 0.35);
      }
    }
  }
}

// ============================================================================
// 4. REFLECTIONS OF VIRIDIAN BAIZE & NEIGHBOUR BALLS (DELAUNAY TARGETS)
// ============================================================================
function drawBaizeAndNeighbourReflections(b) {
  // A. Lower hemisphere reflection of the deep viridian baize & dark table chasm
  let downNormal = vNorm(vAdd(vScale(b.bUp, -0.78), vScale(b.bForward, 0.62)));
  let downBasis = buildSphericalBasis(downNormal, b.bRight);

  const baizeReflRings = [
    { alpha: 0.56, col: PALETTE.baizePastel, brush: "cp_vivid", wt: 0.45 },
    { alpha: 0.48, col: PALETTE.baizeLit, brush: "cp_vivid", wt: 0.50 },
    { alpha: 0.40, col: PALETTE.baizeMid, brush: "cp_burnish", wt: 0.55 },
    { alpha: 0.31, col: PALETTE.baizeDark, brush: "cp_burnish", wt: 0.58 },
    { alpha: 0.21, col: PALETTE.baizeShadowBlue, brush: "cp_vivid", wt: 0.52 },
    { alpha: 0.11, col: PALETTE.baizeShadowViolet, brush: "cp_detail", wt: 0.48 }
  ];

  for (let rr of baizeReflRings) {
    drawSphericalCircleOnBall(b, downNormal, downBasis.t1, downBasis.t2, rr.alpha, rr.brush, rr.col, rr.wt, 32);
  }

  // B. Mutual reflections of every neighbouring ball in the rack!
  for (let other of balls) {
    if (other.num === b.num) continue;
    let diff = vSub(other.pos, b.pos);
    let dist = vLen(diff);
    if (dist > 4.35) continue; // Direct and diagonal neighbours

    let dirToOther = vNorm(diff);
    // Optical reflection normal on sphere b: half-vector between view (bForward) and neighbour direction
    let reflNorm = vNorm(vAdd(b.bForward, dirToOther));
    let projCenter = ballNormalToScreen(b, reflNorm);
    if (projCenter.w < 0.08) continue;

    let basis = buildSphericalBasis(reflNorm, b.bUp);
    // Angular radius of the reflected neighbour sphere
    let baseAlpha = (dist < 2.25) ? 0.36 : (dist < 3.6 ? 0.23 : 0.15);

    // Delaunay simultaneous-contrast rings around each neighbour reflection:
    // Orange vibrates against Ultramarine; Violet halos sit against Lemon!
    let haloOuter = other.ringOuter;
    let haloInner = other.ringInner;
    let coreMid = other.bodyMid;
    let corePastel = other.bodyPastel;

    const targetRings = [
      { frac: 1.15, col: haloOuter, brush: "cp_vivid", wt: 0.48, wash: null },
      { frac: 0.94, col: haloInner, brush: "cp_vivid", wt: 0.52, wash: null },
      { frac: 0.74, col: coreMid, brush: "cp_burnish", wt: 0.56, wash: coreMid, washAlpha: 135 },
      { frac: 0.50, col: corePastel, brush: "cp_burnish", wt: 0.54, wash: corePastel, washAlpha: 150 },
      { frac: 0.25, col: other.bodyGleam, brush: "cp_detail", wt: 0.46, wash: null }
    ];

    for (let tr of targetRings) {
      drawSphericalCircleOnBall(
        b, reflNorm, basis.t1, basis.t2,
        baseAlpha * tr.frac, tr.brush, tr.col, tr.wt, 28,
        tr.wash, tr.washAlpha
      );
    }

    // Secondary reflected specular star pip inside the reflected neighbour!
    if (projCenter.w > 0.22) {
      brush.set("star_spike", "#ffffff", 0.35);
      let pipLen = b.cr * 0.032 * projCenter.w;
      brush.line(projCenter.x - pipLen, projCenter.y, projCenter.x + pipLen, projCenter.y);
      brush.line(projCenter.x, projCenter.y - pipLen, projCenter.x, projCenter.y + pipLen);
    }
  }
}

// ============================================================================
// 5. PERFECT NUMBERED WHITE DISC WITH SLIGHT PRINT MISREGISTRATION
// ============================================================================
function drawNumberedWhiteDisc(b) {
  let basis = buildSphericalBasis(b.discNorm, b.bUp);
  // Ensure t1 points right and t2 points down on screen for upright numbers
  if (vDot(basis.t1, b.bRight) < 0) basis.t1 = vScale(basis.t1, -1);
  if (vDot(basis.t2, b.bUp) > 0) basis.t2 = vScale(basis.t2, -1);

  const discAlpha = 0.43; // Angular radius of the circular white inlay disc

  // 1. Slight print misregistration on the white disc's outer boundary!
  // Shift axis slightly in two complementary directions before drawing the main white disc
  let misAxisUltra = vNorm(vAdd(b.discNorm, vAdd(vScale(basis.t1, 0.032), vScale(basis.t2, -0.025))));
  let misAxisOrange = vNorm(vAdd(b.discNorm, vAdd(vScale(basis.t1, -0.030), vScale(basis.t2, 0.024))));

  drawSphericalCircleOnBall(b, misAxisUltra, basis.t1, basis.t2, discAlpha * 1.02, "cp_detail", PALETTE.ultraVivid, 0.44, 36);
  drawSphericalCircleOnBall(b, misAxisOrange, basis.t1, basis.t2, discAlpha * 1.02, "cp_detail", PALETTE.orangeVivid, 0.44, 36);

  // 2. Main perfect circular white disc (opaque warm ivory wash + burnished pencil rings)
  drawSphericalCircleOnBall(
    b, b.discNorm, basis.t1, basis.t2,
    discAlpha, "cp_burnish", PALETTE.ivoryCream, 0.55, 42,
    PALETTE.ivoryBase, 248
  );

  // Concentric burnished ivory, pale lemon, and soft lavender pencil shading inside the disc
  drawSphericalCircleOnBall(b, b.discNorm, basis.t1, basis.t2, discAlpha * 0.84, "cp_burnish", PALETTE.ivoryCream, 0.58, 34);
  drawSphericalCircleOnBall(b, b.discNorm, basis.t1, basis.t2, discAlpha * 0.65, "cp_burnish", PALETTE.lemonCream, 0.55, 28);
  drawSphericalCircleOnBall(b, b.discNorm, basis.t1, basis.t2, discAlpha * 0.42, "cp_burnish", "#ffffff", 0.52, 22);

  // For striped balls, tournament discs often feature a thin inner print ring (also slightly misregistered)
  if (b.striped) {
    drawSphericalCircleOnBall(b, misAxisOrange, basis.t1, basis.t2, discAlpha * 0.90, "cp_detail", PALETTE.orangeVivid, 0.32, 32);
    drawSphericalCircleOnBall(b, b.discNorm, basis.t1, basis.t2, discAlpha * 0.90, "cp_detail", PALETTE.inkDark, 0.36, 32);
  }

  // 3. Draw the numeral (1..15) projected onto the 3D sphere with slight print misregistration
  drawSphericalNumber(b, b.discNorm, basis.t1, basis.t2, b.num, discAlpha * 0.54);
}

// Vector stroke glyphs for digits 0-9 in normalized [-1, 1] x [-1, 1] coordinates
function getDigitStrokes(digitChar) {
  switch (digitChar) {
    case "0":
      return [[
        [0, -0.95], [0.68, -0.72], [0.82, 0], [0.68, 0.72],
        [0, 0.95], [-0.68, 0.72], [-0.82, 0], [-0.68, -0.72], [0, -0.95]
      ]];
    case "1":
      return [
        [[-0.45, -0.52], [0.08, -0.95], [0.08, 0.92]],
        [[-0.48, 0.92], [0.58, 0.92]]
      ];
    case "2":
      return [[
        [-0.72, -0.48], [-0.42, -0.92], [0.35, -0.92], [0.76, -0.52],
        [0.58, 0.02], [-0.76, 0.92], [0.80, 0.92]
      ]];
    case "3":
      return [[
        [-0.70, -0.68], [-0.25, -0.95], [0.45, -0.90], [0.74, -0.48],
        [0.32, -0.05], [-0.15, -0.05], [0.42, -0.02], [0.80, 0.45],
        [0.42, 0.92], [-0.32, 0.95], [-0.76, 0.62]
      ]];
    case "4":
      return [
        [[0.36, 0.95], [0.36, -0.95], [-0.80, 0.38], [0.82, 0.38]]
      ];
    case "5":
      return [[
        [0.72, -0.92], [-0.62, -0.92], [-0.70, -0.08], [-0.10, -0.22],
        [0.58, -0.08], [0.80, 0.42], [0.42, 0.92], [-0.35, 0.94], [-0.76, 0.62]
      ]];
    case "6":
      return [
        [[0.62, -0.72], [0.15, -0.95], [-0.52, -0.72], [-0.78, 0.08],
         [-0.58, 0.78], [0.05, 0.95], [0.65, 0.75], [0.76, 0.25],
         [0.42, -0.15], [-0.25, -0.15], [-0.72, 0.18]],
        [[-0.52, 1.22], [0.52, 1.22]] // classic underline bar for 6
      ];
    case "7":
      return [[
        [-0.76, -0.92], [0.78, -0.92], [0.22, 0.02], [-0.22, 0.95]
      ]];
    case "8":
      return [
        [[0, -0.05], [-0.58, -0.25], [-0.68, -0.62], [-0.32, -0.94],
         [0.32, -0.94], [0.68, -0.62], [0.58, -0.25], [0, -0.05],
         [-0.68, 0.25], [-0.78, 0.65], [-0.38, 0.95], [0.38, 0.95],
         [0.78, 0.65], [0.68, 0.25], [0, -0.05]]
      ];
    case "9":
      return [
        [[-0.62, 0.72], [-0.15, 0.95], [0.52, 0.72], [0.78, -0.08],
         [0.58, -0.78], [-0.05, -0.95], [-0.65, -0.75], [-0.76, -0.25],
         [-0.42, 0.15], [0.25, 0.15], [0.72, -0.18]],
        [[-0.52, 1.22], [0.52, 1.22]] // classic underline bar for 9
      ];
    default:
      return [];
  }
}

function drawSphericalNumber(b, discAxis, t1, t2, numVal, scaleAlpha) {
  let str = String(numVal);
  let digits = str.split("");
  let isDouble = digits.length === 2;

  // Map a 2D point (gx, gy) on the number plane to 2D canvas coordinates on the sphere
  function mapGlyphPt(gx, gy) {
    let nPt = vNorm(vAdd(
      discAxis,
      vAdd(vScale(t1, gx * scaleAlpha), vScale(t2, gy * scaleAlpha))
    ));
    let proj = ballNormalToScreen(b, nPt);
    return [proj.x, proj.y];
  }

  // Print registration passes:
  // 1. Ultramarine ghost plate (+dx, -dy)
  // 2. Mandarin Orange ghost plate (-dx, +dy)
  // 3. Violet halo plate (+dx*0.5, +dy*0.8)
  // 4. Crisp Dark Lacquer Ink passes (centered, boldened with multi-offsets)
  const passes = [
    { dx: 0.11, dy: -0.08, col: PALETTE.ultraVivid, wt: 0.48 },
    { dx: -0.10, dy: 0.08, col: PALETTE.orangeVivid, wt: 0.48 },
    { dx: 0.06, dy: 0.07, col: PALETTE.violetVivid, wt: 0.44 },
    { dx: 0.0, dy: 0.0, col: PALETTE.inkDark, wt: 0.62 },
    { dx: 0.032, dy: 0.0, col: PALETTE.inkDark, wt: 0.56 },
    { dx: -0.032, dy: 0.0, col: PALETTE.inkDark, wt: 0.56 },
    { dx: 0.0, dy: 0.030, col: PALETTE.inkDark, wt: 0.52 }
  ];

  let weightScale = map(b.cr, 95, 225, 0.72, 1.25, true);

  for (let pass of passes) {
    brush.set("cp_detail", pass.col, pass.wt * weightScale);

    for (let dIdx = 0; dIdx < digits.length; dIdx++) {
      let ch = digits[dIdx];
      let strokes = getDigitStrokes(ch);
      let xOffset = isDouble ? (dIdx === 0 ? -0.52 : 0.48) : 0.0;
      let xScale = isDouble ? 0.48 : 0.66;
      let yScale = isDouble ? 0.64 : 0.72;

      for (let poly of strokes) {
        let screenPts = [];
        for (let pt of poly) {
          let gx = xOffset + pt[0] * xScale + pass.dx;
          let gy = pt[1] * yScale + pass.dy;
          screenPts.push(mapGlyphPt(gx, gy));
        }
        if (screenPts.length === 2) {
          brush.line(screenPts[0][0], screenPts[0][1], screenPts[1][0], screenPts[1][1]);
        } else if (screenPts.length > 2) {
          brush.spline(screenPts, 0.25);
        }
      }
    }
  }
}

// ============================================================================
// 6. HIGH-GLOSS BURNISHED SHEEN & DELAUNAY HALO RINGS AROUND THE LAMP STAR
// ============================================================================
function drawLampHaloAndBurnish(b) {
  let basis = buildSphericalBasis(b.starNorm, b.bUp);

  // Concentric Delaunay simultaneous-contrast corona around the overhead lamp reflection:
  // "violet halos sit against lemon" and "orange edges vibrate against ultramarine"
  const coronaRings = [
    { alpha: 0.42, col: PALETTE.ultraPastel, brush: "cp_vivid", wt: 0.48 },
    { alpha: 0.35, col: PALETTE.orangePastel, brush: "cp_vivid", wt: 0.50 },
    { alpha: 0.28, col: PALETTE.violetPastel, brush: "cp_burnish", wt: 0.58 },
    { alpha: 0.20, col: PALETTE.lemonPastel, brush: "cp_burnish", wt: 0.64 },
    { alpha: 0.13, col: PALETTE.lemonCream, brush: "cp_burnish", wt: 0.68 },
    { alpha: 0.07, col: "#ffffff", brush: "cp_burnish", wt: 0.72 }
  ];

  for (let cr of coronaRings) {
    drawSphericalCircleOnBall(b, b.starNorm, basis.t1, basis.t2, cr.alpha, cr.brush, cr.col, cr.wt, 30);
  }

  // High-gloss coloured-pencil burnishing sweeps across the upper hemisphere
  // ( seals the numbered disc and rings beneath a mirror-like clear coat )
  let starScreen = ballNormalToScreen(b, b.starNorm);
  brush.set("cp_burnish", "#ffffff", 0.52);
  for (let i = 0; i < 16; i++) {
    let r = b.cr * map(i, 0, 15, 0.18, 0.88);
    let a0 = -135 + random(-12, 12);
    let a1 = -45 + random(-12, 12);
    drawSphereArc(b.cx, b.cy, r, a0, a1, "cp_burnish", (i % 2 === 0) ? "#ffffff" : b.bodyGleam, 0.46);
  }

  // Secondary rim glint on the lower-right lacquer edge
  drawSphereArc(b.cx, b.cy, b.cr * 0.94, 20, 82, "cp_detail", PALETTE.lemonCream, 0.42);
}

// ============================================================================
// 7. THE CHORUS: SINGLE HARD WHITE STAR ON EVERY SPHERE
// ============================================================================
function drawHardWhiteStar(b) {
  let starPt = ballNormalToScreen(b, b.starNorm);
  let sx = starPt.x;
  let sy = starPt.y;
  let sScale = b.cr / 150;

  // 1. Chromatic dispersion ring right at the star's waist (violet against lemon)
  drawSphereArc(sx, sy, 14 * sScale, -20, 160, "cp_detail", PALETTE.violetPastel, 0.42);
  drawSphereArc(sx, sy, 14 * sScale, 160, 340, "cp_detail", PALETTE.lemonVivid, 0.42);
  drawSphereArc(sx, sy, 10 * sScale, 0, 360, "cp_burnish", PALETTE.lemonCream, 0.55);

  // 2. Solid blazing white core
  brush.noStroke();
  brush.wash("#ffffff", 255);
  drawCleanCircleShape(sx, sy, 6.8 * sScale, 24);
  brush.noWash();

  // 3. Hard white optical star spikes — repeated at a rhythmic chorus angle across all 15 balls!
  const chorusAngle = -14; // Consistent optical diffraction angle from the overhead lamp
  const spikes = [
    // Primary long cross spikes
    { ang: chorusAngle, len: 36 * sScale, wt: 0.72 },
    { ang: chorusAngle + 180, len: 36 * sScale, wt: 0.72 },
    { ang: chorusAngle + 90, len: 31 * sScale, wt: 0.68 },
    { ang: chorusAngle + 270, len: 31 * sScale, wt: 0.68 },
    // Secondary diagonal star rays
    { ang: chorusAngle + 45, len: 20 * sScale, wt: 0.52 },
    { ang: chorusAngle + 225, len: 20 * sScale, wt: 0.52 },
    { ang: chorusAngle + 135, len: 20 * sScale, wt: 0.52 },
    { ang: chorusAngle + 315, len: 20 * sScale, wt: 0.52 },
    // Fine tertiary diffraction needles
    { ang: chorusAngle + 22.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 67.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 112.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 157.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 202.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 247.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 292.5, len: 12 * sScale, wt: 0.36 },
    { ang: chorusAngle + 337.5, len: 12 * sScale, wt: 0.36 }
  ];

  for (let sp of spikes) {
    let rad = sp.ang * Math.PI / 180;
    let ex = sx + Math.cos(rad) * sp.len;
    let ey = sy + Math.sin(rad) * sp.len;
    brush.set("star_spike", "#ffffff", sp.wt);
    brush.line(sx, sy, ex, ey);
  }

  // Extra dense white center burnish knot
  brush.set("star_spike", "#ffffff", 0.85);
  for (let a = 0; a < 180; a += 30) {
    let rad = (a + chorusAngle) * Math.PI / 180;
    let r = 6.2 * sScale;
    brush.line(sx - Math.cos(rad) * r, sy - Math.sin(rad) * r, sx + Math.cos(rad) * r, sy + Math.sin(rad) * r);
  }
}

// ============================================================================
// 8. FOREGROUND BAIZE NAP DETAILS & CHROMATIC FELT FIBERS
// ============================================================================
function drawForegroundBaizeNap() {
  brush.wiggle(1.0);

  // Helper to check if a point on the canvas is outside all 15 spheres
  function isOutsideBalls(px, py, pad = 2) {
    for (let b of balls) {
      let dx = px - b.cx;
      let dy = py - b.cy;
      if (dx * dx + dy * dy < (b.cr + pad) * (b.cr + pad)) return false;
    }
    return true;
  }

  // Crisp foreground wool nap hairs and subtle pastel simultaneous-contrast flecks in the baize
  const fgLayers = [
    { col: PALETTE.baizeMint, wt: 0.28, count: 220 },
    { col: PALETTE.baizePastel, wt: 0.32, count: 280 },
    { col: PALETTE.baizeDark, wt: 0.36, count: 320 },
    { col: PALETTE.ultraPastel, wt: 0.24, count: 85 },
    { col: PALETTE.orangePastel, wt: 0.22, count: 65 },
    { col: PALETTE.lemonPastel, wt: 0.22, count: 70 },
    { col: PALETTE.violetPastel, wt: 0.24, count: 80 }
  ];

  for (let layer of fgLayers) {
    brush.set("nap_fiber", layer.col, layer.wt);
    for (let i = 0; i < layer.count; i++) {
      let x = random(30, 1170);
      let y = random(30, 1170);
      if (!isOutsideBalls(x, y, 4)) continue;

      let len = map(y, 0, 1200, 14, 38) * random(0.7, 1.3);
      let x2 = x + len;
      let y2 = y + ((x - 600) / 600) * len * 0.05 + random(-1.5, 1.5);
      if (!isOutsideBalls(x2, y2, 4)) continue;

      brush.line(x, y, x2, y2);
    }
  }

  // Subtle fuzz overlap right where the front balls nestle into the deep viridian baize
  for (let b of balls) {
    let contactPt = v3(b.pos.x, 0, b.pos.z);
    let [sx, sy] = projectWorldPoint(contactPt);
    // Only draw where the contact point is visible in front of other balls
    let visible = true;
    for (let other of balls) {
      if (other.num === b.num) continue;
      if (other.tz < b.tz) {
        let dx = sx - other.cx;
        let dy = sy - other.cy;
        if (dx * dx + dy * dy < other.cr * other.cr) {
          visible = false;
          break;
        }
      }
    }
    if (!visible) continue;

    brush.set("nap_fiber", PALETTE.baizeDark, 0.32);
    for (let k = 0; k < 18; k++) {
      let ang = random(70, 110) * Math.PI / 180;
      let px = b.cx + Math.cos(ang) * b.cr * 0.995;
      let py = b.cy + Math.sin(ang) * b.cr * 0.995;
      let len = b.cr * random(0.05, 0.11);
      brush.line(px - len * 0.5, py, px + len * 0.5, py + random(-1, 1));
    }
  }

  brush.noField();
}

