  const leftFist = createFistConfig("left");
  const rightFist = createFistConfig("right");

  // 2. Reserved terracotta orange base silhouettes (fists + meander ground strip)
  drawReservedTerracottaBase(leftFist, rightFist);

  // 3. Diluted golden-brown glaze washes (volumetric shading of skin, knuckles, and wraps)
  drawGlazeWashes(leftFist, rightFist);

