  drawKnucklesAndFingers(leftFist);
  drawKnucklesAndFingers(rightFist);

  // 7. Primary raised black relief lines and negative-space black slip cut-ins
  drawPrimaryReliefContours(leftFist);
  drawPrimaryReliefContours(rightFist);

  // 8. Frayed tape fibres spilling over skin and black slip ground
  drawFrayedFibres(leftFist);
