  drawFinalPotSurfaceSheen();

  noLoop();
}

// ============================================================================
// 1. BLACK SLIP GROUND & RADIAL POT SHEEN
// ============================================================================
function drawBlackSlipGround() {
  background(PAL.slipDeep);
  brush.noField();

  // Subtle warm bronze-black wash zones simulating light on a convex amphora belly
  const sheenCenter = { x: 580, y: 440 };
  brush.noStroke();

  for (let r = 920; r >= 160; r -= 95) {
    let alpha = map(r, 160, 920, 26, 8);
    brush.wash(r < 520 ? PAL.sheenBronze : PAL.slipWarm, alpha);
    drawPolyCircle(sheenCenter.x, sheenCenter.y, r, 44, 1.12, 0.92);
  }
  brush.noWash();

  // Radial sheen rays across the curved black slip ground
  for (let i = 0; i < 240; i++) {
    let ang = random(0, 360);
    let rad = ang * (Math.PI / 180);
    // Stronger lustre along an upper-left to lower-right diagonal axis
    let lobe = Math.pow(Math.cos((ang - 32) * Math.PI / 180), 2) * 0.7 +
               Math.pow(Math.cos((ang - 140) * Math.PI / 180), 2) * 0.4;
    let rStart = random(180, 480);
    let rLen = random(140, 440) * (0.5 + lobe * 0.6);
    let x1 = sheenCenter.x + Math.cos(rad) * rStart * 1.06;
    let y1 = sheenCenter.y + Math.sin(rad) * rStart * 0.96;
    let x2 = sheenCenter.x + Math.cos(rad) * (rStart + rLen) * 1.06;
    let y2 = sheenCenter.y + Math.sin(rad) * (rStart + rLen) * 0.96;

    if (y1 > 1030 && y2 > 1030) continue;
    let col = lobe > 0.45 ? PAL.sheenLight : (lobe > 0.22 ? PAL.sheenBronze : PAL.slipWarm);
    brush.set("pot_lustre", col, random(0.6, 1.5));
    brush.line(x1, y1, x2, y2);
  }

  // Wheel-turned concentric burnishing arcs (potter's wheel striations)
  const wheelApex = { x: 600, y: -950 };
  for (let r = 1020; r <= 2120; r += 9) {
    let span = 34;
    let steps = 7;
    for (let s = 0; s < steps; s++) {
      let a1 = 90 - span + (s / steps) * (span * 2) + random(-0.8, 0.8);
      let a2 = a1 + (span * 2 / steps) * random(0.55, 0.92);
      let midA = (a1 + a2) * 0.5;
      let distFromHighlight = Math.abs(midA - 92);
      let col = distFromHighlight < 11 ? PAL.sheenLight :
                (distFromHighlight < 20 ? PAL.sheenBronze : PAL.slipWarm);
      let w = map(distFromHighlight, 0, 35, 0.9, 0.35) * random(0.6, 1.25);
      brush.set("pot_lustre", col, w);
      brush.arc(wheelApex.x, wheelApex.y, r + random(-3, 3), a1, a2);
    }
  }

  // Fine dark slip burnish & micro-texture around the outer edges
  for (let i = 0; i < 140; i++) {
    let ang = random(0, 360) * Math.PI / 180;
    let dist = random(460, 760);
    let px = 600 + Math.cos(ang) * dist;
    let py = 540 + Math.sin(ang) * dist;
    if (px < 0 || px > 1200 || py < 0 || py > 1030) continue;
    brush.set("cpencil", PAL.slipDeep, random(0.5, 1.2));
    brush.line(px - 25, py + random(-6, 6), px + 25, py + random(-6, 6));
  }
}

// ============================================================================
// 2. ANATOMICAL CONFIGURATION FOR LEFT & RIGHT FISTS
// ============================================================================
function createFistConfig(side) {
  const isLeft = side === "left";
  // s = +1 for left fist, -1 for right fist (horizontal mirror relative to center 600)
  const s = isLeft ? 1 : -1;
  const dy = isLeft ? 8 : -6; // Slight vertical asymmetry for athletic tension

  // Helper to convert anatomical coordinates (defined for left fist) to either side
  const pt = (x, y) => ({
    x: isLeft ? x : 1200 - x + (isLeft ? 0 : 4),
    y: y + dy
  });

  // 4 MCP Knuckles (Pinky -> Ring -> Middle -> Index)
  const mcp = [
    { ...pt(166, 376), rx: 40, ry: 33, name: "pinky", split: false },
    { ...pt(258, 338), rx: 45, ry: 37, name: "ring", split: !isLeft },
    { ...pt(364, 304), rx: 52, ry: 42, name: "middle", split: true },
    { ...pt(474, 318), rx: 49, ry: 40, name: "index", split: true }
  ];

  // 4 PIP Knuckles (upper curled finger ridge)
  const pip = [
    { ...pt(178, 224), rx: 38, ry: 28, topY: 194 + dy },
    { ...pt(266, 182), rx: 43, ry: 32, topY: 148 + dy },
    { ...pt(368, 158), rx: 48, ry: 35, topY: 122 + dy },
    { ...pt(472, 174), rx: 46, ry: 33, topY: 138 + dy }
