  // Interdigital clefts between fingers (Pinky-Ring, Ring-Middle, Middle-Index)
  const clefts = [
    { top: pt(218, 182), mid: pt(214, 255), bot: pt(210, 344) },
    { top: pt(314, 150), mid: pt(312, 232), bot: pt(310, 314) },
    { top: pt(422, 156), mid: pt(422, 238), bot: pt(422, 308) }
  ];

  // Thumb landmarks (on the inner/medial edge of each fist)
  const thumb = {
    wristBase: pt(496, 635),
    cmcJoint: pt(538, 540),
    mcpKnuckle: pt(580, 428),
    ipJoint: pt(566, 286),
    tipLock: pt(482, 244),
    innerWeb: pt(484, 368),
    lowerFold: pt(462, 515)
  };

  // Full outer silhouette polygon of the fist and forearm
  const silhouette = [
    pt(164, 1026), // Ulnar forearm base at meander border
    pt(158, 920),
    pt(152, 810),
    pt(146, 715),  // Ulnar styloid / wrist
    pt(144, 640),
    pt(130, 545),  // Outer hypothenar wrap edge
    pt(118, 445),  // 5th metacarpal flare
    pt(124, 370),  // Outer pinky MCP contour
    pt(132, 295),  // Outer pinky proximal phalanx
    pt(142, 224),  // Outer pinky PIP
    pt(160, 198),
    pt(184, 194),  // Pinky PIP dome crest
    pt(206, 200),
    pt(218, 184),  // Cleft 1
    pt(238, 156),
    pt(266, 148),  // Ring PIP dome crest
    pt(294, 154),
    pt(314, 150),  // Cleft 2
    pt(338, 128),
    pt(368, 122),  // Middle PIP dome crest
    pt(398, 128),
    pt(422, 154),  // Cleft 3
    pt(446, 140),
    pt(474, 138),  // Index PIP dome crest
    pt(502, 146),
    pt(522, 174),  // Inner index PIP corner
    pt(530, 222),  // Inner index shaft
    pt(552, 250),  // Thumb IP overhang
    pt(568, 286),  // Thumb IP joint
    pt(576, 355),  // Thumb proximal shaft
    pt(582, 428),  // Thumb MCP knuckle prominence
    pt(568, 492),  // Thumb metacarpal slope
    pt(542, 555),  // Thenar base wrap
    pt(514, 625),  // Radial wrist
    pt(502, 710),
    pt(496, 815),
    pt(490, 925),
    pt(486, 1026)  // Radial forearm base at meander border
  ];

  // Wrap bands configuration (from wrist/forearm up to the knuckle pad)
  const wrapBands = [
    // Band 1: Lowest forearm turn entering meander border
    {
      pts: [pt(162, 1026), pt(488, 1026), pt(493, 945), pt(156, 922)],
      angle: isLeft ? 5 : -5, shade: 0.35
    },
    // Band 2: Lower-mid forearm spiral turn
    {
      pts: [pt(155, 932), pt(494, 956), pt(498, 862), pt(150, 832)],
      angle: isLeft ? 7 : -7, shade: 0.25
    },
    // Band 3: Mid forearm diagonal wrap
    {
      pts: [pt(149, 842), pt(499, 872), pt(504, 772), pt(145, 745)],
      angle: isLeft ? 6 : -6, shade: 0.3
    },
    // Band 4: Wrist stabilizing horizontal-angled turn
    {
      pts: [pt(144, 755), pt(505, 782), pt(514, 686), pt(142, 665)],
      angle: isLeft ? 4 : -4, shade: 0.22
    },
    // Band 5: Upper wrist / retinaculum strap
    {
      pts: [pt(141, 672), pt(515, 694), pt(530, 608), pt(132, 588)],
      angle: isLeft ? 5 : -5, shade: 0.28
    },
    // Band 6: Thumb-locking strap (sweeps from ulnar wrist across lower dorsum around thumb base)
    {
      pts: [pt(134, 605), pt(330, 560), pt(558, 495), pt(578, 434), pt(536, 405), pt(315, 488), pt(124, 528)],
      angle: isLeft ? -18 : 18, shade: 0.24
    },
    // Band 7: Figure-8 X-strap A (from radial wrist diagonally up to pinky/ring side)
    {
      pts: [pt(522, 622), pt(544, 552), pt(268, 396), pt(120, 418), pt(126, 498), pt(348, 566)],
      angle: isLeft ? -28 : 28, shade: 0.26
