    // Band 9: Shifted & frayed knuckle pad roll sitting just behind/around the MCP knuckles
    {
      pts: [
        pt(122, 422), pt(150, 384), pt(226, 362), pt(302, 344),
        pt(368, 346), pt(430, 352), pt(518, 356), pt(552, 396),
        pt(465, 424), pt(335, 422), pt(210, 434), pt(120, 455)
      ],
      angle: isLeft ? -6 : 6, shade: 0.2, isPad: true
