  ];

  return { side, isLeft, s, dy, pt, mcp, pip, clefts, thumb, silhouette, wrapBands };
}

// ============================================================================
// 3. RESERVED TERRACOTTA BASE SILHOUETTES
// ============================================================================
function drawReservedTerracottaBase(leftFist, rightFist) {
  brush.noStroke();

  // Base terracotta clay wash for both fists (2 opaque passes for solid reserved clay)
  for (let pass = 0; pass < 2; pass++) {
    brush.wash(pass === 0 ? PAL.clayBase : PAL.clayWarm, 255);
    drawShapeFromPoints(leftFist.silhouette, 0.15, true);
    drawShapeFromPoints(rightFist.silhouette, 0.15, true);

    // Reserved terracotta ground strip for the meander border at bottom
    brush.rect(0, 1024, 1200, 138, "corner");
  }
  brush.noWash();

  // Subtle clay body texture & warm watercolor glaze across the reserved terracotta
  brush.fill(PAL.clayDeep, 38);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.45, 0.25);
  drawShapeFromPoints(leftFist.silhouette, 0.15, true);
  drawShapeFromPoints(rightFist.silhouette, 0.15, true);
  brush.noFill();

  // Fine wheel-smoothed terracotta grain across both fists
  for (let fist of [leftFist, rightFist]) {
    brush.hatchStyle("2H", PAL.clayLight, 0.55);
    brush.hatch(9, fist.isLeft ? 14 : -14, { rand: 0.08 });
    drawShapeFromPoints(fist.silhouette, 0.15, true);
    brush.noHatch();
  }
}

// ============================================================================
// 4. DILUTED GOLDEN-BROWN GLAZE WASHES (VOLUMETRIC MODELING)
// ============================================================================
function drawGlazeWashes(leftFist, rightFist) {
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.5, 0.35);

  const fists = [leftFist, rightFist];

  // Batch 1: Light golden-brown glaze wash (overall peripheral rounding & wrap recessed planes)
  brush.fill(PAL.glazeLight, 58);
  for (let f of fists) {
    const p = f.pt;
    // Ulnar (outer) border rounding of forearm and hand
    drawShapeFromPoints([
      p(164, 1024), p(245, 1024), p(235, 700), p(215, 420),
      p(185, 210), p(142, 224), p(118, 445), p(146, 715)
    ], 0.25, true);

    // Radial (inner) border rounding of forearm and thumb base
    drawShapeFromPoints([
      p(415, 1024), p(486, 1024), p(502, 710), p(542, 555),
      p(582, 428), p(568, 286), p(495, 310), p(445, 580), p(420, 800)
    ], 0.25, true);

    // Foreshortened shadow trough just behind the MCP knuckles (upper dorsum window)
    drawShapeFromPoints([
      p(150, 385), p(260, 342), p(370, 315), p(485, 330),
      p(505, 388), p(365, 378), p(225, 398)
    ], 0.3, true);

    // Lower slope of the 4 proximal fingers just above the MCP ridge
    drawShapeFromPoints([
      p(148, 345), p(260, 305), p(368, 275), p(488, 290),
      p(498, 240), p(368, 222), p(255, 245), p(155, 285)
    ], 0.3, true);
  }

  // Batch 2: Medium diluted golden-brown glaze (deepening wrap shadows, tendon valleys, thumb crease)
  brush.fill(PAL.glazeMid, 72);
  for (let f of fists) {
    const p = f.pt;
    // Deep ulnar margin shadow
    drawShapeFromPoints([
      p(164, 1024), p(205, 1024), p(192, 680), p(168, 420),
      p(152, 220), p(132, 295), p(118, 445), p(148, 750)
    ], 0.2, true);

    // Thumb web and inner lock shadow
    drawShapeFromPoints([
      p(472, 240), p(535, 245), p(555, 325), p(515, 425),
      p(465, 395), p(468, 305)
    ], 0.3, true);

    // Shadow under each overlapping wrap band
    for (let b of f.wrapBands) {
      let n = b.pts.length;
      if (n >= 4) {
        let shadowPts = [
          b.pts[0],
          b.pts[1],
          lerpPt(b.pts[1], b.pts[2], 0.28),
          lerpPt(b.pts[0], b.pts[n - 1], 0.28)
        ];
        drawShapeFromPoints(shadowPts, 0.15, true);
      }
    }

    // Knuckle valley shadows between the 4 MCP domes
    for (let c of f.clefts) {
      drawPolyCircle(c.bot.x, c.bot.y + 8, 24, 16, 0.9, 1.3);
      drawPolyCircle(c.mid.x, c.mid.y, 16, 14, 0.65, 1.8);
    }
  }

  // Batch 3: Dark burnt-umber glaze wash (deepest anatomical crevices & knuckle bruising)
  brush.fill(PAL.glazeDark, 85);
  for (let f of fists) {
    const p = f.pt;
    // Bruised peri-articular swelling around Index and Middle MCP knuckles
    drawPolyCircle(f.mcp[2].x, f.mcp[2].y + 4, 42, 20, 1.15, 0.82);
    drawPolyCircle(f.mcp[3].x, f.mcp[3].y + 4, 38, 20, 1.12, 0.82);
    if (!f.isLeft) {
      drawPolyCircle(f.mcp[1].x, f.mcp[1].y + 4, 34, 18, 1.1, 0.82);
    }

    // Deep pocket where thumb tip locks under index & middle fingers
    drawShapeFromPoints([
      p(458, 232), p(518, 238), p(526, 278), p(470, 295)
    ], 0.25, true);
  }

  brush.noFill();
}

// ============================================================================
// 5. DORSAL TENDONS & BRANCHING VEIN ANATOMY
// ============================================================================
function drawTendonsAndVeins(fist) {
  const p = fist.pt;

  // Exposed dorsal skin windows and subcutaneous relief under tight wraps
  // Draw the 4 extensor digitorum tendons converging from the wrist toward the 4 MCP knuckles
  const wristCenter = p(325, 655);
  for (let i = 0; i < 4; i++) {
    let k = fist.mcp[i];
    let startPt = lerpPt(wristCenter, k, 0.18);
    let endPt = { x: k.x, y: k.y + 12 };

    // Tendon flanking troughs in diluted golden-brown glaze
    for (let sideOff of [-9, 9]) {
      let mid = lerpPt(startPt, endPt, 0.52);
      mid.x += sideOff * 1.15;
      brush.set("glaze_liner", PAL.glazeMid, 1.15);
      brush.spline([
        [startPt.x + sideOff * 0.6, startPt.y, 0.4],
        [mid.x, mid.y, 1.1],
        [endPt.x + sideOff * 0.8, endPt.y, 0.6]
      ], 0.35);
    }

    // Lit terracotta crest of the taut extensor tendon
    for (let s = -2; s <= 2; s += 2) {
      let mid = lerpPt(startPt, endPt, 0.5);
      brush.set("clay_ridge", PAL.clayLight, 1.1);
      brush.spline([
        [startPt.x + s, startPt.y, 0.3],
        [mid.x + s, mid.y, 1.0],
        [endPt.x + s, endPt.y, 0.8]
      ], 0.3);
    }
  }

  // Hyperrealistic branching dorsal venous network
  // Defined in local hand coordinates so both hands have organic, distinct vein paths
  const veinPaths = fist.isLeft ? [
    // Main cephalic / dorsal metacarpal vein trunk between Index and Middle
    [p(418, 318), p(408, 368), p(392, 435), p(415, 515), p(438, 610), p(446, 725), p(432, 860)],
    // Anastomosing arch branching to Middle-Ring valley
    [p(392, 435), p(348, 412), p(312, 345), p(298, 315)],
    // Branch from central arch down toward ulnar wrist
    [p(348, 412), p(318, 478), p(275, 558), p(242, 665), p(228, 795)],
    // Outer ring-pinky dorsal tributary
    [p(215, 348), p(232, 405), p(262, 468), p(275, 558)],
    // Thumb / radial tributary snake
    [p(498, 342), p(515, 410), p(488, 478), p(415, 515)],
    // Distal knuckle capillary forks
    [p(408, 368), p(448, 342), p(468, 322)],
    [p(318, 478), p(365, 525), p(382, 625)]
  ] : [
    // Right hand unique venous network
    [p(412, 314), p(395, 372), p(372, 448), p(398, 535), p(425, 640), p(418, 770), p(435, 900)],
    [p(395, 372), p(332, 392), p(305, 338), p(286, 308)],
    [p(332, 392), p(292, 465), p(258, 545), p(235, 650), p(215, 780)],
    [p(212, 342), p(228, 398), p(258, 462), p(292, 465)],
    [p(485, 335), p(508, 398), p(472, 468), p(398, 535)],
    [p(372, 448), p(342, 522), p(355, 615)],
    [p(258, 545), p(308, 595), p(318, 705)]
  ];

  for (let vIdx = 0; vIdx < veinPaths.length; vIdx++) {
    let path = veinPaths[vIdx];
    let isMain = vIdx < 3;
    let offset = isMain ? 4.2 : 2.8;

    // 1. Diluted golden-brown shadow edges along both sides of the raised vein
    for (let side of [-1, 1]) {
      let shifted = offsetPolyline(path, side * offset);
      brush.set("glaze_liner", PAL.glazeDark, isMain ? 1.05 : 0.75);
      brush.spline(shifted.map(pt => [pt.x, pt.y, 0.85]), 0.45);
    }

    // 2. Warm terracotta-amber raised ridge along the vein center
    brush.set("clay_ridge", PAL.clayBright, isMain ? 1.35 : 0.95);
    brush.spline(path.map(pt => [pt.x, pt.y, 1.0]), 0.45);

    // 3. Fine black relief micro-lines accentuating the shadow side of the vein
    let shadowEdge = offsetPolyline(path, (fist.isLeft ? 1 : -1) * (offset * 0.85));
    brush.set("relief_micro", PAL.reliefBlack, isMain ? 0.95 : 0.7);
    brush.spline(shadowEdge.map(pt => [pt.x, pt.y, 0.75]), 0.45);
  }
}

// ============================================================================
// 6. THUMB ANATOMY (LOCKED MEDIAL THUMB & SKIN CREASES)
// ============================================================================
function drawThumbAnatomy(fist) {
  const p = fist.pt;

  // Sculpt the locked thumb segments with golden-brown glaze & clay highlights
  // Lit ridge along the radial border of the thumb shaft and MCP dome
  brush.set("clay_ridge", PAL.clayLight, 1.4);
  brush.spline([
    [p(525, 535).x, p(525, 535).y, 0.5],
    [p(568, 432).x, p(568, 432).y, 1.2],
    [p(556, 295).x, p(556, 295).y, 1.0],
    [p(495, 252).x, p(495, 252).y, 0.5]
  ], 0.4);

  // Concentric skin wrinkles over the Thumb MCP knuckle (pt(580, 428)) and IP joint (pt(566, 286))
  const mcpPt = p(565, 428);
  for (let i = -3; i <= 3; i++) {
    let wy = mcpPt.y + i * 7;
    let curve = i * 2.5;
    brush.set("glaze_liner", PAL.glazeMid, 0.75);
    brush.spline([
      [mcpPt.x - 28 * fist.s, wy + 4, 0.3],
      [mcpPt.x - 6 * fist.s, wy + curve, 1.0],
      [mcpPt.x + 12 * fist.s, wy + 3, 0.4]
    ], 0.4);
    if (Math.abs(i) <= 1) {
      brush.set("relief_micro", PAL.reliefBlack, 0.8);
      brush.spline([
        [mcpPt.x - 22 * fist.s, wy + 3, 0.3],
        [mcpPt.x - 5 * fist.s, wy + curve, 0.95],
        [mcpPt.x + 10 * fist.s, wy + 2, 0.3]
      ], 0.4);
    }
  }

  // Thumb IP joint creases (pt(566, 286))
  const ipPt = p(554, 286);
  for (let i = -2; i <= 2; i++) {
    let wy = ipPt.y + i * 6;
    brush.set("relief_micro", i === 0 ? PAL.reliefBlack : PAL.glazeDark, 0.85);
    brush.spline([
      [ipPt.x - 26 * fist.s, wy + 5, 0.3],
      [ipPt.x - 6 * fist.s, wy - 2, 1.0],
      [ipPt.x + 11 * fist.s, wy + 4, 0.4]
    ], 0.4);
  }

  // Compressed skin folds in the thumb web (between thumb and index finger)
  const webBase = p(484, 368);
  for (let f = 0; f < 5; f++) {
    let yOff = f * 12;
    brush.set("relief", PAL.reliefBlack, 0.85 - f * 0.08);
    brush.spline([
      [webBase.x - 18 * fist.s, webBase.y + yOff - 8, 0.4],
      [webBase.x + 8 * fist.s, webBase.y + yOff, 1.1],
      [webBase.x + 32 * fist.s, webBase.y + yOff + 14, 0.3]
    ], 0.35);
  }
}

// ============================================================================
// 7. BOXING HAND WRAPS (WOVEN CLOTH BANDS, INTERDIGITAL STRAPS & KNUCKLE PAD)
// ============================================================================
function drawHandWraps(fist) {
  const p = fist.pt;

  for (let bIdx = 0; bIdx < fist.wrapBands.length; bIdx++) {
    const band = fist.wrapBands[bIdx];

    // 1. Subtle cloth tone wash to separate each wrap layer
    brush.noStroke();
    brush.fill(PAL.glazeLight, Math.round(band.shade * 120));
    brush.fillBleed(0.02, "in");
    drawShapeFromPoints(band.pts, 0.12, true);
    brush.noFill();

    // 2. Woven cotton gauze / cloth warp hatching along the band direction
    brush.hatchStyle("glaze_liner", PAL.glazeLight, 0.58);
    brush.hatch(5.5, band.angle, { rand: 0.06 });
    drawShapeFromPoints(band.pts, 0.12, true);
    brush.noHatch();

    // 3. Fine cross-weft weave texture perpendicular to the band
    brush.hatchStyle("relief_micro", PAL.clayShadow, 0.45);
    brush.hatch(11, band.angle + 88, { rand: 0.09 });
    drawShapeFromPoints(band.pts, 0.12, true);
    brush.noHatch();

    // 4. Longitudinal tension folds & lit cloth ridges across the wrap band
    let n = band.pts.length;
    if (n === 4) {
      for (let t = 0.2; t <= 0.82; t += 0.2) {
        let leftPt = lerpPt(band.pts[0], band.pts[3], t);
        let rightPt = lerpPt(band.pts[1], band.pts[2], t);
        let midPt = lerpPt(leftPt, rightPt, 0.5);
        midPt.y -= 7; // Arch over the convex wrist/dorsum

        // Golden-brown fold crease
        brush.set("glaze_liner", PAL.glazeMid, 0.8);
        brush.spline([
          [leftPt.x, leftPt.y, 0.3],
          [midPt.x, midPt.y, 1.0],
          [rightPt.x, rightPt.y, 0.3]
        ], 0.35);

        // Bright clay highlight along upper edge of the cloth fold
        brush.set("clay_ridge", PAL.clayLight, 0.85);
        brush.spline([
          [leftPt.x, leftPt.y - 2.5, 0.2],
          [midPt.x, midPt.y - 2.5, 0.9],
          [rightPt.x, rightPt.y - 2.5, 0.2]
        ], 0.35);
      }
    }

    // 5. Crisp raised black relief lines along the upper & lower seam edges of each wrap band
    if (!band.isPad) {
      // Top seam of the band
      let topSeam = n === 4 ? [band.pts[3], lerpPt(band.pts[3], band.pts[2], 0.5), band.pts[2]]
                            : band.pts.slice(Math.floor(n / 2));
      if (topSeam.length === 3) {
        topSeam[1].y -= 6;
      }
      brush.set("relief", PAL.reliefBlack, 1.05);
      brush.spline(topSeam.map(pt => [pt.x, pt.y, 0.95]), 0.32);

      // Bottom seam of the band
      let botSeam = n === 4 ? [band.pts[0], lerpPt(band.pts[0], band.pts[1], 0.5), band.pts[1]]
                            : band.pts.slice(0, Math.floor(n / 2) + 1);
      if (botSeam.length === 3) {
        botSeam[1].y -= 5;
      }
      brush.set("relief", PAL.reliefBlack, 0.95);
      brush.spline(botSeam.map(pt => [pt.x, pt.y, 0.9]), 0.32);
    } else {
      // Special multi-ply folded gauze texture for the shifted knuckle pad (Band 9)
      for (let ply = 0; ply < 4; ply++) {
        let yShift = ply * 8;
        let plyPts = [
          p(124, 418 + yShift),
          p(215, 368 + yShift),
          p(315, 348 + yShift),
          p(420, 352 + yShift),
          p(538, 382 + yShift)
        ];
        brush.set("glaze_liner", PAL.glazeDark, 0.95);
        brush.spline(plyPts.map(pt => [pt.x, pt.y + 2, 0.9]), 0.38);

        brush.set("clay_ridge", PAL.clayBright, 0.9);
        brush.spline(plyPts.map(pt => [pt.x, pt.y - 1.5, 0.85]), 0.38);

        brush.set("relief", PAL.reliefBlack, 0.95);
        brush.spline(plyPts.map(pt => [pt.x, pt.y, 0.95]), 0.38);
      }
    }
  }

  // Interdigital cloth wrap straps passing through the 3 valleys between the fingers
  for (let cIdx = 0; cIdx < fist.clefts.length; cIdx++) {
    const c = fist.clefts[cIdx];
    const strapW = 13;
    const strapPoly = [
      { x: c.mid.x - strapW, y: c.mid.y + 12 },
      { x: c.mid.x + strapW, y: c.mid.y + 12 },
      { x: c.bot.x + strapW * 1.4, y: c.bot.y + 42 },
      { x: c.bot.x - strapW * 1.4, y: c.bot.y + 42 }
    ];

    // Cloth fill and weave
    brush.noStroke();
    brush.fill(PAL.glazeLight, 45);
    drawShapeFromPoints(strapPoly, 0.15, true);
    brush.noFill();

    brush.hatchStyle("glaze_liner", PAL.glazeMid, 0.55);
    brush.hatch(4, 85, { rand: 0.05 });
    drawShapeFromPoints(strapPoly, 0.15, true);
    brush.noHatch();

    // Relief borders of the interdigital strap
    brush.set("relief", PAL.reliefBlack, 0.95);
    brush.spline([
      [strapPoly[0].x, strapPoly[0].y, 0.5],
      [c.bot.x - strapW * 1.1, c.bot.y + 10, 1.0],
      [strapPoly[3].x, strapPoly[3].y, 0.7]
    ], 0.35);
    brush.spline([
      [strapPoly[1].x, strapPoly[1].y, 0.5],
      [c.bot.x + strapW * 1.1, c.bot.y + 10, 1.0],
      [strapPoly[2].x, strapPoly[2].y, 0.7]
    ], 0.35);
  }
}

// ============================================================================
// 8. KNUCKLES, FORESHORTENED FINGERS, PIP CREST & SPLIT KNUCKLE TRAUMA
// ============================================================================
function drawKnucklesAndFingers(fist) {
  // 1. Model the 4 Foreshortened Proximal Phalanges (between PIP and MCP domes)
  for (let i = 0; i < 4; i++) {
    const m = fist.mcp[i];
    const p = fist.pip[i];

    // Cylindrical highlight down the center of each proximal finger shaft
    for (let s = -6; s <= 6; s += 4) {
      brush.set("clay_ridge", PAL.clayLight, 1.1);
      brush.line(p.x + s, p.y + 18, m.x + s, m.y - 24);
    }

    // Transverse skin tension creases across the middle of the proximal phalanx
    let midY = (p.y + m.y) * 0.5;
    let midX = (p.x + m.x) * 0.5;
    for (let r = -1; r <= 1; r++) {
      let cy = midY + r * 9;
      brush.set("glaze_liner", PAL.glazeMid, 0.75);
      brush.spline([
        [midX - m.rx * 0.65, cy + 4, 0.3],
        [midX, cy - 3, 0.9],
        [midX + m.rx * 0.65, cy + 4, 0.3]
      ], 0.4);
    }

    // 2. PIP Knuckle Dome (upper crest of each curled finger)
    // Concentric elliptical skin folds over the flexed PIP joint
    for (let ring = 1; ring <= 4; ring++) {
      let rx = p.rx * (0.35 + ring * 0.16);
      let ry = p.ry * (0.32 + ring * 0.16);
      // Upper arc of skin wrinkle
      brush.set(ring % 2 === 0 ? "relief_micro" : "glaze_liner",
                ring === 2 ? PAL.reliefBlack : PAL.glazeDark, 0.8);
      brush.spline([
        [p.x - rx, p.y + 4, 0.3],
        [p.x - rx * 0.5, p.y - ry, 0.95],
        [p.x + rx * 0.5, p.y - ry, 0.95],
        [p.x + rx, p.y + 4, 0.3]
      ], 0.45);

      // Lower arc of PIP skin wrinkle
      brush.set("glaze_liner", PAL.glazeMid, 0.7);
      brush.spline([
        [p.x - rx * 0.9, p.y + 6, 0.3],
        [p.x, p.y + ry * 0.95, 0.9],
        [p.x + rx * 0.9, p.y + 6, 0.3]
      ], 0.45);
    }

    // Bright terracotta highlight on the PIP knuckle crown
    brush.set("clay_ridge", PAL.clayBright, 1.3);
    brush.spline([
      [p.x - p.rx * 0.45, p.y - 4, 0.4],
      [p.x, p.y - p.ry * 0.55, 1.1],
      [p.x + p.rx * 0.45, p.y - 4, 0.4]
    ], 0.4);

    // Subtle abrasion on the Middle PIP knuckle
    if (i === 2) {
      drawSplitKnuckleDetail(p.x, p.y - 2, p.rx * 0.55, p.ry * 0.45, false, fist.isLeft);
    }

    // 3. MCP Striking Knuckle Dome (main bony prominence)
    // Concentric skin wrinkles encircling the MCP knuckle
    for (let ring = 1; ring <= 5; ring++) {
      let rx = m.rx * (0.3 + ring * 0.14);
      let ry = m.ry * (0.28 + ring * 0.14);
      brush.set(ring === 2 || ring === 4 ? "relief_micro" : "glaze_liner",
                ring === 2 ? PAL.reliefBlack : PAL.glazeDark, 0.85);
      brush.spline([
        [m.x - rx, m.y + 2, 0.3],
        [m.x - rx * 0.45, m.y - ry, 1.0],
        [m.x + rx * 0.45, m.y - ry, 1.0],
        [m.x + rx, m.y + 2, 0.3]
      ], 0.45);

      brush.set(ring === 3 ? "relief_micro" : "glaze_liner",
                ring === 3 ? PAL.reliefBlack : PAL.glazeMid, 0.8);
      brush.spline([
        [m.x - rx * 0.92, m.y + 5, 0.3],
        [m.x, m.y + ry * 1.05, 0.95],
        [m.x + rx * 0.92, m.y + 5, 0.3]
      ], 0.45);
    }

    // Bony prominence highlight on un-split or surrounding knuckle rim
    brush.set("clay_ridge", PAL.clayBright, 1.45);
    brush.spline([
      [m.x - m.rx * 0.5, m.y - 6, 0.4],
      [m.x, m.y - m.ry * 0.48, 1.2],
      [m.x + m.rx * 0.5, m.y - 6, 0.4]
    ], 0.4);

    // 4. Split Knuckle Trauma (raw split skin, jagged fissure, crusted dark glaze)
    if (m.split) {
      drawSplitKnuckleDetail(m.x, m.y, m.rx, m.ry, true, fist.isLeft);
    }
  }
}

function drawSplitKnuckleDetail(cx, cy, rx, ry, isMajor, isLeft) {
  const dir = isLeft ? 1 : -1;

  // Dark bruised & raw dermal bed in concentrated umber glaze
  brush.noStroke();
  brush.fill(PAL.glazeUmber, isMajor ? 135 : 95);
  brush.fillBleed(0.03, "in");
  drawPolyCircle(cx, cy, rx * 0.52, 16, 1.2, 0.72);
  brush.noFill();

  // Peeled / curled raw epidermis rims in bright terracotta-amber above and below the split
  const span = rx * (isMajor ? 0.58 : 0.42);
  brush.set("clay_ridge", PAL.clayBright, isMajor ? 1.5 : 1.0);
  brush.spline([
    [cx - span, cy - 3 * dir, 0.4],
    [cx - span * 0.3, cy - 6, 1.2],
    [cx + span * 0.35, cy - 4, 1.1],
    [cx + span, cy + 2 * dir, 0.4]
  ], 0.35);

  brush.spline([
    [cx - span * 0.85, cy + 4, 0.4],
    [cx, cy + 7, 1.1],
    [cx + span * 0.85, cy + 5, 0.4]
  ], 0.35);

  // Jagged central split fissure in thick raised black relief & blood-umber glaze
  const fissurePts = [
    [cx - span, cy - 1 * dir, 0.5],
    [cx - span * 0.45, cy + 2, 1.25],
    [cx - span * 0.1, cy - 2, 1.4],
    [cx + span * 0.3, cy + 3, 1.35],
    [cx + span * 0.7, cy - 1, 1.0],
    [cx + span * 1.05, cy + 2 * dir, 0.4]
  ];
  brush.set("glaze_liner", PAL.glazeUmber, isMajor ? 1.5 : 1.0);
  brush.spline(fissurePts, 0.2);

  brush.set("relief_bold", PAL.reliefBlack, isMajor ? 1.35 : 0.9);
  brush.spline(fissurePts, 0.2);

  // Secondary radiating micro-fissures (star-cracks in the split knuckle skin)
  if (isMajor) {
    const cracks = [
      [[cx - span * 0.4, cy + 1], [cx - span * 0.65, cy - 11], [cx - span * 0.8, cy - 16]],
      [[cx - span * 0.08, cy - 2], [cx + span * 0.05, cy - 13], [cx + span * 0.18, cy - 19]],
      [[cx + span * 0.28, cy + 3], [cx + span * 0.42, cy + 14], [cx + span * 0.6, cy + 19]],
      [[cx - span * 0.25, cy + 2], [cx - span * 0.38, cy + 12], [cx - span * 0.52, cy + 17]]
    ];
    for (let cr of cracks) {
      brush.set("relief_micro", PAL.reliefBlack, 0.95);
      brush.spline(cr.map((pt, idx) => [pt[0], pt[1], 1.0 - idx * 0.3]), 0.25);
    }

    // Coagulated dark glaze/blood droplet at the corner of the split knuckle
    brush.noStroke();
    brush.wash(PAL.reliefBlack, 235);
    drawPolyCircle(cx + span * 0.15, cy + 4, 4.2, 10, 1.1, 0.85);
    brush.noWash();
    brush.set("clay_ridge", PAL.claySpecular, 0.9);
    brush.line(cx + span * 0.15 - 1.5, cy + 2.5, cx + span * 0.15 + 0.5, cy + 2.5);
  }
}

// ============================================================================
// 9. PRIMARY RAISED BLACK RELIEF LINES & CONTOUR REFINEMENT
// ============================================================================
function drawPrimaryReliefContours(fist) {
  const p = fist.pt;

  // 1. Deep interdigital finger clefts (razor-sharp Attic black relief lines)
  for (let c of fist.clefts) {
    // Dark glaze halo along the finger separation
    brush.set("glaze_liner", PAL.glazeDark, 1.3);
    brush.spline([
      [c.top.x, c.top.y, 0.7],
      [c.mid.x, c.mid.y, 1.2],
      [c.bot.x, c.bot.y, 0.9]
    ], 0.25);

    // Bold raised black relief line separating the clenched proximal fingers
    brush.set("relief_bold", PAL.reliefBlack, 1.35);
    brush.spline([
      [c.top.x, c.top.y, 0.85],
      [c.mid.x, c.mid.y, 1.35],
      [c.bot.x, c.bot.y, 1.05]
    ], 0.25);

    // Y-fork skin fold at the top and bottom of each interdigital cleft
    brush.set("relief", PAL.reliefBlack, 0.9);
    brush.line(c.top.x, c.top.y, c.top.x - 9, c.top.y + 12);
    brush.line(c.top.x, c.top.y, c.top.x + 9, c.top.y + 12);
  }

  // 2. Thumb lock contour (where the thumb presses tightly against the index finger)
  brush.set("relief_bold", PAL.reliefBlack, 1.3);
  brush.spline([
    [p(522, 220).x, p(522, 220).y, 0.6],
    [p(498, 240).x, p(498, 240).y, 1.2],
    [p(474, 255).x, p(474, 255).y, 1.3],
    [p(485, 315).x, p(485, 315).y, 1.1],
    [p(496, 378).x, p(496, 378).y, 0.7]
  ], 0.35);

  // Thumbnail edge tucked at the inner tip of the thumb
  brush.set("relief", PAL.reliefBlack, 0.9);
  brush.spline([
    [p(508, 246).x, p(508, 246).y, 0.5],
    [p(490, 264).x, p(490, 264).y, 1.0],
    [p(514, 274).x, p(514, 274).y, 0.6]
  ], 0.35);

  // 3. Full outer silhouette contour in raised black relief line
  const sil = fist.silhouette;
  brush.set("relief_bold", PAL.reliefBlack, 1.4);
  const closedSil = [...sil, sil[0]];
  brush.spline(closedSil.map(pt => [pt.x, pt.y, 1.0]), 0.25);
}

// ============================================================================
// 10. FRAYED TAPE FIBRES & UNRAVELING GAUZE THREADS
// ============================================================================
function drawFrayedFibres(fist) {
  const s = fist.s;

  // 1. Frayed cotton filaments along the outer ulnar & radial wrap edges (spilling onto black slip)
  for (let b of fist.wrapBands) {
    const leftEdge = b.pts[0];
    const rightEdge = b.pts[1];

    // Outer edge frayed tuft
    drawFibreCluster(leftEdge.x, leftEdge.y - 25, -s, 14, true);
    // Inner edge frayed tuft
    drawFibreCluster(rightEdge.x, rightEdge.y - 25, s, 12, true);

    // Loose frayed threads along the upper seam of each wrap band (over terracotta skin/cloth)
    let n = b.pts.length;
    let pA = b.pts[n - 1];
    let pB = b.pts[Math.floor(n / 2)];
    for (let k = 0; k < 22; k++) {
      let t = random(0.06, 0.94);
      let base = lerpPt(pA, pB, t);
      base.y -= 4;
      let len = random(8, 28);
      let ang = (b.angle + random(-55, 55)) * Math.PI / 180;
      let midX = base.x + Math.cos(ang) * len * 0.5 + random(-4, 4);
      let midY = base.y + Math.sin(ang) * len * 0.5 - random(2, 7);
      let endX = base.x + Math.cos(ang) * len + random(-6, 6);
      let endY = base.y + Math.sin(ang) * len + random(-6, 6);

      // Thread cast shadow in relief micro-line
      brush.set("relief_micro", PAL.reliefBlack, random(0.55, 0.9));
      brush.spline([
        [base.x, base.y + 1.2, 0.8],
        [midX, midY + 1.2, 0.6],
        [endX, endY + 1.2, 0.2]
      ], 0.5);

      // Lit terracotta-amber thread filament
      brush.set("clay_ridge", k % 3 === 0 ? PAL.clayBright : PAL.clayLight, random(0.65, 1.05));
      brush.spline([
        [base.x, base.y, 0.9],
        [midX, midY, 0.7],
        [endX, endY, 0.2]
      ], 0.5);
    }
  }

  // 2. Heavy battle-frayed gauze tufts around the shifted knuckle pad and interdigital straps
  for (let i = 0; i < 4; i++) {
    let m = fist.mcp[i];
    drawFibreCluster(m.x + random(-18, 18), m.y + 34, random([-1, 1]), 18, false);
  }
}

function drawFibreCluster(cx, cy, outDir, count, onDarkGround) {
  for (let i = 0; i < count; i++) {
    let sy = cy + random(-24, 24);
    let sx = cx + random(-4, 4);
    let len = random(10, 34);
    let baseAng = outDir > 0 ? random(-55, 55) : random(125, 235);
    let rad = baseAng * Math.PI / 180;
    let curl = random(-0.6, 0.6);

    let p1x = sx + Math.cos(rad) * (len * 0.5);
    let p1y = sy + Math.sin(rad) * (len * 0.5);
    let p2x = p1x + Math.cos(rad + curl) * (len * 0.5);
    let p2y = p1y + Math.sin(rad + curl) * (len * 0.5);

    if (onDarkGround) {
      // Terracotta frayed thread standing out sharply against the lustrous black slip
      brush.set("clay_ridge", i % 3 === 0 ? PAL.clayBright : PAL.clayBase, random(0.6, 1.1));
      brush.spline([
        [sx, sy, 0.95],
        [p1x, p1y, 0.7],
        [p2x, p2y, 0.2]
      ], 0.55);
    } else {
      // Dark relief shadow + bright clay filament over the hand
      brush.set("relief_micro", PAL.reliefBlack, random(0.55, 0.85));
      brush.spline([
        [sx, sy + 1.2, 0.8],
        [p1x, p1y + 1.2, 0.6],
        [p2x, p2y + 1.2, 0.2]
      ], 0.55);

      brush.set("clay_ridge", PAL.clayBright, random(0.65, 1.0));
      brush.spline([
        [sx, sy, 0.9],
        [p1x, p1y, 0.7],
        [p2x, p2y, 0.2]
      ], 0.55);
    }
  }
}

// ============================================================================
// 11. HYPERREALISTIC SWEAT BEADS & TRICKLES
// ============================================================================
function drawSweatBeads(fist) {
  const p = fist.pt;

  // Curated anatomical sweat bead placements (knuckle brows, proximal fingers, dorsal skin, thumb, wrist)
  const drops = [
    // Proximal fingers & PIP slopes
    { pt: p(188, 255), r: 4.5, trickle: 16 },
    { pt: p(165, 285), r: 3.2, trickle: 0 },
    { pt: p(252, 215), r: 5.2, trickle: 24 },
    { pt: p(284, 248), r: 3.8, trickle: 0 },
    { pt: p(245, 272), r: 2.8, trickle: 0 },
    { pt: p(352, 188), r: 6.2, trickle: 32 },
    { pt: p(386, 212), r: 4.4, trickle: 14 },
    { pt: p(342, 245), r: 3.5, trickle: 0 },
    { pt: p(395, 262), r: 3.0, trickle: 0 },
    { pt: p(458, 202), r: 5.6, trickle: 28 },
    { pt: p(492, 232), r: 4.0, trickle: 0 },
    { pt: p(448, 258), r: 3.3, trickle: 0 },

    // Around MCP striking knuckles
    { pt: p(152, 348), r: 4.2, trickle: 0 },
    { pt: p(235, 316), r: 5.0, trickle: 18 },
    { pt: p(288, 348), r: 3.6, trickle: 0 },
    { pt: p(338, 286), r: 4.8, trickle: 0 },
    { pt: p(402, 326), r: 5.8, trickle: 22 },
    { pt: p(452, 294), r: 4.5, trickle: 0 },
    { pt: p(506, 338), r: 5.2, trickle: 20 },

    // Exposed dorsal venous windows & thumb
    { pt: p(376, 392), r: 6.4, trickle: 35 },
    { pt: p(325, 428), r: 4.6, trickle: 0 },
    { pt: p(418, 435), r: 3.8, trickle: 0 },
    { pt: p(282, 465), r: 5.0, trickle: 22 },
    { pt: p(362, 495), r: 4.0, trickle: 0 },
    { pt: p(552, 335), r: 5.4, trickle: 26 },
    { pt: p(562, 405), r: 4.8, trickle: 0 },
    { pt: p(532, 468), r: 6.0, trickle: 30 },
    { pt: p(488, 525), r: 4.2, trickle: 0 },

    // Lower wrist & forearm wrap edges (sweat soaking through and beading)
    { pt: p(235, 635), r: 5.2, trickle: 28 },
    { pt: p(385, 658), r: 4.5, trickle: 0 },
    { pt: p(295, 735), r: 5.8, trickle: 34 },
    { pt: p(432, 765), r: 4.2, trickle: 18 },
    { pt: p(218, 845), r: 4.8, trickle: 25 },
    { pt: p(358, 895), r: 5.5, trickle: 30 },
    { pt: p(445, 955), r: 4.0, trickle: 0 }
  ];

  // Add a cluster of fine micro-perspiration pores/beads across the knuckles and dorsum
  for (let m = 0; m < 28; m++) {
    let bx = random(165, 535);
    let by = random(175, 560);
    drops.push({ pt: p(bx, by), r: random(1.8, 3.1), trickle: 0 });
  }

  for (let d of drops) {
    const cx = d.pt.x;
    const cy = d.pt.y;
    const r = d.r;

    // 1. Sweat trickle trail above/below large droplets
    if (d.trickle > 0) {
      let trStart = { x: cx + random(-2, 2), y: cy - d.trickle };
      let trMid = { x: cx + random(-3, 3), y: cy - d.trickle * 0.45 };
      brush.set("glaze_liner", PAL.glazeDark, 0.65);
      brush.spline([
        [trStart.x + 1.2, trStart.y, 0.2],
        [trMid.x + 1.2, trMid.y, 0.7],
        [cx + 1.2, cy - r * 0.8, 0.9]
      ], 0.4);
      brush.set("clay_ridge", PAL.clayBright, 0.75);
      brush.spline([
        [trStart.x, trStart.y, 0.2],
        [trMid.x, trMid.y, 0.8],
        [cx, cy - r * 0.8, 1.0]
      ], 0.4);
    }

    // 2. Cast shadow crescent beneath the sweat bead
    brush.noStroke();
    brush.wash(PAL.glazeUmber, 185);
    drawPolyCircle(cx + 0.8, cy + r * 0.48, r * 0.92, 12, 1.0, 0.85);

    // 3. Internal upper hemisphere shadow of the transparent droplet
    brush.wash(PAL.glazeDark, 155);
    drawPolyCircle(cx, cy - r * 0.15, r * 0.88, 12, 1.0, 0.95);

    // 4. Refracted lower warm terracotta-amber caustic glow inside the droplet
    brush.wash(PAL.clayBright, 215);
    drawPolyCircle(cx + 0.4, cy + r * 0.28, r * 0.65, 10, 1.05, 0.72);
    brush.noWash();

    // 5. Crisp relief micro-line rim around the bead
    brush.set("relief_micro", PAL.reliefBlack, r > 3.5 ? 0.85 : 0.6);
    brush.circle(cx, cy, r * 0.92, 0.08);

    // 6. Razor-sharp specular highlight at the upper-left of the sweat bead
    brush.noStroke();
    brush.wash(PAL.claySpecular, 250);
    drawPolyCircle(cx - r * 0.28, cy - r * 0.32, Math.max(1.3, r * 0.32), 8, 1.0, 0.9);
    brush.noWash();
  }
}

// ============================================================================
// 12. ATTIC MEANDER (GREEK KEY) BORDER FRAMING THE BOTTOM EDGE
// ============================================================================
function drawMeanderBorder() {
  const yTop = 1024;
  const yBot = 1162;

  // Black slip apron below the meander border to bottom of canvas
  brush.noStroke();
  brush.wash(PAL.slipDeep, 255);
  brush.rect(0, yBot, 1200, 1200 - yBot, "corner");

  // Black slip framing bands at top and bottom of the meander frieze
  brush.rect(0, yTop, 1200, 8, "corner");
  brush.rect(0, yTop + 16, 1200, 106, "corner"); // Black channel background for the meander keys
  brush.rect(0, yBot - 8, 1200, 8, "corner");
  brush.noWash();

  // Draw continuous interlocking Attic meander units & saltire cross squares in reserved terracotta
  const bandY = yTop + 22;
  const bandH = 94;
  const unitW = 100;
  const s = bandH / 9; // 9-grid subdivision for authentic 5-turn Greek key + channels

  brush.noStroke();
  for (let u = 0; u < 12; u++) {
    const ux = u * unitW;
    const isSaltire = (u % 4 === 2); // Every 4th panel is an Attic stopped saltire cross square

    // Upper and lower continuous terracotta rails of the meander
    brush.wash(PAL.clayBase, 255);
    brush.rect(ux, bandY, unitW, s, "corner");
    brush.rect(ux, bandY + 8 * s, unitW, s, "corner");

    if (!isSaltire) {
      // Classic Attic Greek key spiral labyrinth in reserved terracotta
      // Left vertical riser from bottom rail up to row 2
      brush.rect(ux, bandY + 2 * s, s, 6 * s, "corner");
      // Top inner horizontal bar (row 2)
      brush.rect(ux + s, bandY + 2 * s, 6 * s, s, "corner");
      // Right inner vertical drop (col 6, rows 2..6)
      brush.rect(ux + 6 * s, bandY + 2 * s, s, 5 * s, "corner");
      // Bottom inner hook (row 6, cols 2..6)
      brush.rect(ux + 2 * s, bandY + 6 * s, 4 * s, s, "corner");
      // Innermost upward turn (col 2, rows 4..6)
      brush.rect(ux + 2 * s, bandY + 4 * s, s, 2 * s, "corner");
      // Center terminal bar (row 4, cols 2..4.6)
      brush.rect(ux + 2 * s, bandY + 4 * s, 2.6 * s, s, "corner");

      // Rightmost outer drop from top rail down to row 8
      brush.rect(ux + 8 * s, bandY + s, s, 6 * s, "corner");
      // Bridge connecting into next unit
      brush.rect(ux + 8 * s, bandY + 6 * s, unitW - 8 * s, s, "corner");
    } else {
      // Attic Saltire Cross-in-Square metope panel
      // Side framing vertical bars
      brush.rect(ux + 0.6 * s, bandY + s, s, 7 * s, "corner");
      brush.rect(ux + unitW - 1.6 * s, bandY + s, s, 7 * s, "corner");

      // Reserved terracotta inner square with diagonal saltire cross
      const bx = ux + 2.4 * s;
      const by = bandY + 1.8 * s;
      const bw = unitW - 4.8 * s;
      const bh = 5.4 * s;

      // Diagonal bar 1
      drawShapeFromPoints([
        { x: bx, y: by },
        { x: bx + 10, y: by },
        { x: bx + bw, y: by + bh },
        { x: bx + bw - 10, y: by + bh }
      ], 0.02, true);

      // Diagonal bar 2
      drawShapeFromPoints([
        { x: bx + bw - 10, y: by },
        { x: bx + bw, y: by },
        { x: bx + 10, y: by + bh },
        { x: bx, y: by + bh }
      ], 0.02, true);

      // 4 reserved terracotta pellets in the saltire quadrants
      drawPolyCircle(bx + bw * 0.5, by + bh * 0.18, 4.5, 10, 1, 1);
      drawPolyCircle(bx + bw * 0.5, by + bh * 0.82, 4.5, 10, 1, 1);
      drawPolyCircle(bx + bw * 0.18, by + bh * 0.5, 4.5, 10, 1, 1);
      drawPolyCircle(bx + bw * 0.82, by + bh * 0.5, 4.5, 10, 1, 1);
    }
  }
  brush.noWash();

  // Hand-drawn Attic relief lines & diluted golden-brown glaze along the meander border
  brush.set("relief_bold", PAL.reliefBlack, 1.15);
  brush.line(0, yTop + 8, 1200, yTop + 8);
  brush.line(0, yTop + 16, 1200, yTop + 16);
  brush.line(0, yBot - 16, 1200, yBot - 16);
  brush.line(0, yBot - 8, 1200, yBot - 8);

  // Subtle diluted glaze aging along the outer edges of the meander strip
  brush.noStroke();
  brush.fill(PAL.glazeDark, 65);
  brush.fillBleed(0.03, "in");
  brush.rect(0, yTop, 180, 138, "corner");
  brush.rect(1020, yTop, 180, 138, "corner");
  brush.noFill();
}

