// ============================================================================
// GEOMETRY HELPERS
// ============================================================================
function lerpPt(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t
  };
}

function drawShapeFromPoints(pts, curvature = 0.15, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(closed);
}

function drawPolyCircle(cx, cy, r, steps = 20, scaleX = 1.0, scaleY = 1.0) {
  brush.beginShape(0.35);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let vx = cx + Math.cos(a) * r * scaleX;
    let vy = cy + Math.sin(a) * r * scaleY;
    brush.vertex(vx, vy);
  }
  brush.endShape(true);
}

function offsetPolyline(pts, dist) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    let prev = pts[Math.max(0, i - 1)];
    let next = pts[Math.min(pts.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    out.push({
      x: pts[i].x + nx * dist,
      y: pts[i].y + ny * dist
    });
  }
  return out;
}

