function buildCrescentCapPolygon() {
  let pts = [];
  // Outer arc along upper-left perimeter of slab
  for (let i = 0; i <= 45; i++) {
    let t = i / 45;
    let ang = lerp(172, 322, t);
    let radX = 382 + 18 * sin(t * 180) + 8 * sin(t * 720);
    let radY = 238 + 14 * cos(t * 180) + 6 * cos(t * 540);
    let x = 602 + radX * cos(ang);
    let y = 552 + radY * sin(ang);
    pts.push([x, y]);
  }
  // Inner arc bordering the intermuscular fat seam
  for (let i = 45; i >= 0; i--) {
    let t = i / 45;
    let ang = lerp(176, 316, t);
    let thickness = 88 + 32 * sin(t * 180) + 12 * sin(t * 540 + 40);
    let radX = 382 - thickness;
    let radY = 238 - thickness * 0.72;
    let x = 608 + radX * cos(ang);
    let y = 558 + radY * sin(ang);
    pts.push([x, y]);
  }
  return pts;
}

function buildSideWallPolygon(topPoly, startAngleDeg, depthPx) {
  let lowerArc = [];
  for (let pt of topPoly) {
    let dx = pt[0] - SCENE.cx;
    let dy = pt[1] - SCENE.cy;
    let ang = atan2(dy, dx);
    if (ang < 0) ang += 360;
    if (ang >= 8 && ang <= 172) {
      lowerArc.push({ pt, ang });
    }
  }
  lowerArc.sort((a, b) => a.ang - b.ang);
  let poly = [];
  for (let item of lowerArc) {
    poly.push([item.pt[0], item.pt[1] - 4]);
  }
  for (let i = lowerArc.length - 1; i >= 0; i--) {
    let item = lowerArc[i];
    let s = sin(map(item.ang, 8, 172, 0, 180));
    let drop = depthPx * pow(max(0, s), 0.65) + 6 * sin(item.ang * 4);
    let shiftX = 8 * cos(item.ang);
    poly.push([item.pt[0] + shiftX, item.pt[1] + drop]);
  }
  return poly;
}

function buildOffsetShadowPolygon(basePoly, dx, dy, scaleF) {
  let poly = [];
  for (let pt of basePoly) {
    let nx = SCENE.cx + (pt[0] - SCENE.cx) * scaleF + dx;
    let ny = SCENE.cy + (pt[1] - SCENE.cy) * scaleF + dy;
    poly.push([nx, ny]);
  }
  return poly;
}

function generateFatLobules() {
  // Populate fat lobules along the seam between Eye, Cap, Complexus, Tail, and outer rind
  for (let i = 0; i < 210; i++) {
    let x = random(195, 995);
    let y = random(295, 835);
    if (!pointInPoly(x, y, SCENE.polySlabOuter)) continue;
    let inMuscle =
      pointInPoly(x, y, SCENE.polyEye) ||
      pointInPoly(x, y, SCENE.polyCap) ||
      pointInPoly(x, y, SCENE.polyComplexus) ||
      pointInPoly(x, y, SCENE.polyTail);
    let inKernel = pointInPoly(x, y, SCENE.polyFatKernel);

    if (!inMuscle || inKernel) {
      let rx = random(8, 24);
      let ry = random(6, 17);
      let rot = random(-45, 45);
      let lPoly = makeOrganicContour(x, y, rx, ry, 18, (a) => 1 + 0.12 * sin(a * 3 + i * 20), rot);
      computeBBox(lPoly);
      let shade = random(["#fdf8f6", "#f8eae6", "#f2dcd6", "#ebd0c9", "#fcf3f0"]);
      SCENE.fatLobules.push({ x, y, rx, ry, poly: lPoly, col: shade });
    }
  }
}

function generateMarblingNetwork() {
  // Primary & secondary branching veins inside Eye, Cap, Complexus, and Tail
  const muscles = [
    { poly: SCENE.polyEye, count: 44, baseAng: 28, lenRange: [45, 135], wRange: [2.8, 7.5] },
    { poly: SCENE.polyCap, count: 32, baseAng: -22, lenRange: [38, 105], wRange: [3.2, 8.2] },
    { poly: SCENE.polyComplexus, count: 10, baseAng: -15, lenRange: [28, 65], wRange: [2.4, 5.5] },
    { poly: SCENE.polyTail, count: 14, baseAng: 45, lenRange: [32, 80], wRange: [2.5, 6.2] }
  ];

  for (let m of muscles) {
    let created = 0;
    let attempts = 0;
    while (created < m.count && attempts < m.count * 8) {
      attempts++;
      let sx = random(m.poly.bbox.minX + 10, m.poly.bbox.maxX - 10);
      let sy = random(m.poly.bbox.minY + 10, m.poly.bbox.maxY - 10);
      if (!pointInPoly(sx, sy, m.poly)) continue;

      let len = random(m.lenRange[0], m.lenRange[1]);
      let width0 = random(m.wRange[0], m.wRange[1]);
      let dir = getMuscleFiberAngle(sx, sy) + random(-35, 35);

      let vein = traceMarblingVein(sx, sy, dir, len, width0, m.poly);
      if (vein) {
        SCENE.marblingVeins.push(vein);
        created++;

        // Spawn 1-2 secondary fork branches
        let branches = floor(random(1, 3.2));
        for (let b = 0; b < branches; b++) {
          let idx = floor(random(2, vein.pts.length - 2));
          let bp = vein.pts[idx];
          let bDir = dir + (random() < 0.5 ? 1 : -1) * random(24, 52);
          let bVein = traceMarblingVein(bp[0], bp[1], bDir, len * random(0.4, 0.68), width0 * 0.62, m.poly);
          if (bVein) SCENE.marblingVeins.push(bVein);
        }
      }
    }
  }

  // Fine tertiary marbling flecks
  for (let i = 0; i < 650; i++) {
    let x = random(200, 990);
    let y = random(290, 830);
    let inM =
      pointInPoly(x, y, SCENE.polyEye) ||
      pointInPoly(x, y, SCENE.polyCap) ||
      pointInPoly(x, y, SCENE.polyComplexus) ||
      pointInPoly(x, y, SCENE.polyTail);
    if (!inM) continue;
    let ang = getMuscleFiberAngle(x, y) + random(-20, 20);
    let l = random(6, 22);
    let w = random(0.8, 2.2);
    let x2 = x + cos(ang) * l;
    let y2 = y + sin(ang) * l;
    let xm = (x + x2) * 0.5 + cos(ang + 90) * random(-3, 3);
    let ym = (y + y2) * 0.5 + sin(ang + 90) * random(-3, 3);
    SCENE.marblingFlecks.push({
      pts: [[x, y], [xm, ym], [x2, y2]],
      w,
      col: random(["#fbf1ee", "#f5dcd8", "#edd0cc", "#e5b8b4"]),
      minY: min(y, ym, y2) - 3,
      maxY: max(y, ym, y2) + 3,
      minX: min(x, xm, x2) - 3,
      maxX: max(x, xm, x2) + 3
    });
  }
}

function traceMarblingVein(sx, sy, startDir, totalLen, maxW, boundaryPoly) {
  let steps = 12;
  let stepLen = totalLen / steps;
  let pts = [[sx, sy]];
  let cx = sx;
  let cy = sy;
  let ang = startDir;

  for (let i = 0; i < steps; i++) {
    ang += (noise(cx * 0.015, cy * 0.015, i * 0.3) - 0.5) * 48;
    let nx = cx + cos(ang) * stepLen;
    let ny = cy + sin(ang) * stepLen;
    if (!pointInPoly(nx, ny, boundaryPoly)) break;
    pts.push([nx, ny]);
    cx = nx;
    cy = ny;
  }
  if (pts.length < 4) return null;

  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i < pts.length; i++) {
    let t = i / (pts.length - 1);
    let profile = sin(t * 180);
    let w = max(0.8, maxW * pow(profile, 0.65) * (0.75 + 0.5 * noise(i * 0.7, sx * 0.1)));
    let p0 = pts[max(0, i - 1)];
    let p1 = pts[min(pts.length - 1, i + 1)];
    let tang = atan2(p1[1] - p0[1], p1[0] - p0[0]);
    let nx = cos(tang + 90) * w;
    let ny = sin(tang + 90) * w;
    leftSide.push([pts[i][0] + nx, pts[i][1] + ny]);
    rightSide.unshift([pts[i][0] - nx, pts[i][1] - ny]);
  }
  let poly = leftSide.concat(rightSide);
  computeBBox(poly);
  return { pts, poly, maxW };
}

function generateGlossPoints() {
  for (let i = 0; i < 480; i++) {
    let x = random(200, 995);
    let y = random(295, 865);
    if (!pointInPoly(x, y, SCENE.polySlabOuter) && !pointInPoly(x, y, SCENE.polySideWall)) continue;
    let ang = getMuscleFiberAngle(x, y) + random(-15, 15);
    let len = random(4, 18);
    let w = random(0.7, 1.9);
    SCENE.glossPoints.push({ x, y, ang, len, w, bright: random() > 0.25 });
  }
}

function getMuscleFiberAngle(x, y) {
  if (pointInPoly(x, y, SCENE.polyCap)) {
    let angToCenter = atan2(y - 560, x - 600);
    return angToCenter + 92 + 12 * (noise(x * 0.008, y * 0.008) - 0.5);
  }
  if (pointInPoly(x, y, SCENE.polyComplexus)) {
    return -22 + 18 * (noise(x * 0.01, y * 0.01) - 0.5);
  }
  if (pointInPoly(x, y, SCENE.polyTail)) {
    return 48 + 20 * (noise(x * 0.01, y * 0.01) - 0.5);
  }
  // Default: Longissimus eye sweeping grain
  let base = map(x, 420, 960, 18, 44);
  return base + 22 * (noise(x * 0.007, y * 0.007) - 0.5);
}

// ============================================================================
// PASS 1: CREASED PINK BUTCHER PAPER & MOISTURE STAIN
// ============================================================================

function renderButcherPaper() {
  brush.noClip();
  brush.noField();

  // 1. Soft pastel pink paper crumple facets (batched watercolor washes)
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);
  for (let f of SCENE.paperFacets) {
    brush.fill(f.col, f.op);
    drawPoly(f.poly, 0.05);
  }
  brush.noFill();

  // 2. Subtle paper fiber grain across the entire butcher sheet
  brush.hatchStyle("2H", "#e2bbc5", 0.65);
  brush.hatch(14, 18, { rand: 0.12 });
  brush.noStroke();
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noHatch();

  // 3. Major paper fold creases (shadow wedge + graphite core + pastel highlight ridge)
  for (let c of SCENE.creases) {
    let mx = (c.x1 + c.x2) * 0.5 + c.bend;
    let my = (c.y1 + c.y2) * 0.5 - c.bend * 0.7;
    let ang = atan2(c.y2 - c.y1, c.x2 - c.x1);
    let nx = cos(ang + 90 * c.side) * c.sw;
    let ny = sin(ang + 90 * c.side) * c.sw;

    // Soft shadow plane along one side of the fold
    let shadowPoly = [
      [c.x1, c.y1],
      [mx, my],
      [c.x2, c.y2],
      [c.x2 + nx, c.y2 + ny],
      [mx + nx * 1.15, my + ny * 1.15],
      [c.x1 + nx, c.y1 + ny]
    ];
    brush.noStroke();
    brush.fill("#d4aab7", 65);
    brush.fillBleed(0.18, "out");
    brush.fillTexture(0.45, 0.3);
    drawPoly(shadowPoly, 0.1);
    brush.noFill();

    // Tighter core crease shadow
    brush.set("cpencil", "#c291a0", 1.3);
    brush.spline([
      [c.x1 + nx * 0.12, c.y1 + ny * 0.12, 0.4],
      [mx + nx * 0.12, my + ny * 0.12, 0.9],
      [c.x2 + nx * 0.12, c.y2 + ny * 0.12, 0.4]
    ], 0.25);

    // Crisp pastel highlight ridge on the lit edge of the fold
    brush.set("cpencil", "#fff6f8", 1.45);
    brush.spline([
      [c.x1 - nx * 0.08, c.y1 - ny * 0.08, 0.5],
      [mx - nx * 0.08, my - ny * 0.08, 1.1],
      [c.x2 - nx * 0.08, c.y2 - ny * 0.08, 0.5]
    ], 0.25);
  }

  // Secondary micro-crinkles on the butcher paper
  for (let i = 0; i < 38; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let ang = random(360);
    let len = random(45, 160);
    let x2 = x1 + cos(ang) * len;
    let y2 = y1 + sin(ang) * len;
    let xm = (x1 + x2) * 0.5 + random(-12, 12);
    let ym = (y1 + y2) * 0.5 + random(-12, 12);
    brush.set("2H", "#d4abb8", 0.75);
    brush.spline([[x1, y1, 0.3], [xm, ym, 0.8], [x2, y2, 0.3]], 0.3);
    brush.set("2H", "#fff5f7", 0.65);
    brush.spline([[x1 + 2, y1 - 2, 0.3], [xm + 2, ym - 2, 0.7], [x2 + 2, y2 - 2, 0.3]], 0.3);
  }

  // 4. Wet Myoglobin Purge Stain soaking into the pink butcher paper around the steak
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.72, 0.82);
  brush.fill("#e6a2b0", 95);
  drawPoly(SCENE.polyPurgeOuter, 0.25);

  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.68, 0.88);
  brush.fill("#d47486", 115);
  drawPoly(SCENE.polyPurgeInner, 0.25);
  brush.noFill();

  // Capillary bleed wisps along paper creases where they exit under the steak
  for (let c of SCENE.creases) {
    for (let t = 0.15; t <= 0.85; t += 0.05) {
      let px = lerp(c.x1, c.x2, t);
      let py = lerp(c.y1, c.y2, t);
      if (pointInPoly(px, py, SCENE.polyPurgeOuter) && !pointInPoly(px, py, SCENE.polySlabOuter)) {
        brush.set("cpencil", "#c7586d", 1.4);
        let ang = atan2(c.y2 - c.y1, c.x2 - c.x1);
        brush.line(px - cos(ang) * 24, py - sin(ang) * 24, px + cos(ang) * 24, py + sin(ang) * 24);
      }
    }
  }

  // 5. Cast Shadow of the thick ribeye slab on the lower-right butcher paper
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.5, 0.45);
  brush.fill("#8c4f5f", 125);
  drawPoly(SCENE.polyCastShadow, 0.25);

  let tightShadow = buildOffsetShadowPolygon(SCENE.polySlabOuter, 18, 36, 1.01);
  brush.fillBleed(0.12, "out");
  brush.fill("#592231", 150);
  drawPoly(tightShadow, 0.2);
  brush.noFill();
}

// ============================================================================
// PASS 2: HYPERREALISTIC RAW RIBEYE SLAB
// ============================================================================

function renderHyperrealRibeye() {
  brush.noClip();
  brush.noField();

  // 1. 3D Side Wall (Lower 2-inch thick cut edge of the steak)
  brush.noStroke();
  brush.wash("#6b1726", 225);
  drawPoly(SCENE.polySideWall, 0.15);
  brush.noWash();

  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.6);
  brush.fill("#4a0915", 160);
  drawPoly(SCENE.polySideWall, 0.15);
  brush.noFill();

  // Vertical/angled muscle & fat striations down the 3D side wall
  for (let i = 0; i < 360; i++) {
    let x = random(SCENE.polySideWall.bbox.minX, SCENE.polySideWall.bbox.maxX);
    let y = random(SCENE.polySideWall.bbox.minY, SCENE.polySideWall.bbox.maxY);
    if (!pointInPoly(x, y, SCENE.polySideWall)) continue;

    // Fat seam regions on side wall vs dark ruby muscle wall
    let isFatWall = (x > 490 && x < 640) || x < 260 || x > 920 || (x > 360 && x < 430);
    let col = isFatWall
      ? random(["#ead2cd", "#d9b5ae", "#c2928b", "#f4e2de"])
      : random(["#420611", "#610f1e", "#7d1b2c", "#962c3e", "#33030b"]);
    let ang = 82 + (x - 600) * 0.04 + random(-8, 8);
    let len = random(10, 26);
    brush.set("fiber", col, random(0.8, 1.4));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Dark contact occlusion line right where the bottom of the slab meets the wet paper
  brush.set("charcoal", "#2b040c", 1.3);
  for (let i = Math.floor(SCENE.polySideWall.length / 2); i < SCENE.polySideWall.length - 1; i++) {
    let p0 = SCENE.polySideWall[i];
    let p1 = SCENE.polySideWall[i + 1];
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // 2. Top Surface Base Slab (Creamy-blush intermuscular fat & connective tissue bed)
  brush.noStroke();
  brush.wash("#f6e4e0", 245);
  drawPoly(SCENE.polySlabOuter, 0.22);
  brush.noWash();

  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.55, 0.5);
  brush.fill("#ebd0cb", 140);
  drawPoly(SCENE.polySlabOuter, 0.22);
  brush.noFill();

  // 3. Muscle Group Base Layers (Opaque washes + textured watercolor fills)
  const muscleGroups = [
    { poly: SCENE.polyEye, washCol: "#991f32", fillCol: "#781021", massCol: "#b83548" },
    { poly: SCENE.polyCap, washCol: "#8f1a2c", fillCol: "#6b0c1b", massCol: "#ad2c3f" },
    { poly: SCENE.polyComplexus, washCol: "#941d2f", fillCol: "#730e1e", massCol: "#b33245" },
    { poly: SCENE.polyTail, washCol: "#9e2437", fillCol: "#7d1424", massCol: "#bd3b4e" }
  ];

  // Sub-surface pink-rose connective glow around each muscle group (recessed into fat)
  for (let mg of muscleGroups) {
    let halo = scalePolygonFromCentroid(mg.poly, 1.035);
    brush.noStroke();
    brush.wash("#e39aa6", 170);
    drawPoly(halo, 0.2);
    brush.noWash();
  }

  // Muscle base washes
  for (let mg of muscleGroups) {
    brush.noStroke();
    brush.wash(mg.washCol, 235);
    drawPoly(mg.poly, 0.2);
    brush.noWash();

    brush.fillBleed(0.15, "in");
    brush.fillTexture(0.75, 0.68);
    brush.fill(mg.fillCol, 155);
    drawPoly(mg.poly, 0.2);
    brush.noFill();
  }

  // 4. Central Fat Kernel & Outer Fat Rind Base
  brush.noStroke();
  brush.wash("#fbf3f0", 240);
  drawPoly(SCENE.polyFatKernel, 0.2);
  for (let rPoly of SCENE.fatRinds) {
    drawPoly(rPoly, 0.2);
  }
  brush.noWash();

  // 5. Pebbled Fat Lobules & Connective Tissue Membranes in the Fat Seams
  for (let lob of SCENE.fatLobules) {
    // Delicate rose connective membrane shadow around the fat lobule
    brush.set("fiber", "#d48793", 0.75);
    brush.wash(lob.col, 210);
    drawPoly(lob.poly, 0.25);
    brush.noWash();

    // Bright buttery crown inside each fat lobule
    let inner = scalePolygonFromCentroid(lob.poly, 0.62);
    brush.noStroke();
    brush.wash("#fffaf8", 180);
    drawPoly(inner, 0.2);
    brush.noWash();
  }

  // Pearlescent pastel blue-lavender silverskin (elastin) ribbon along the Eye/Fat boundary
  let silverskinPts = [
    [575, 395], [535, 445], [505, 505], [492, 565], [478, 625], [450, 680]
  ];
  brush.set("cpencil", "#ded6ec", 3.2);
  brush.spline(silverskinPts, 0.35);
  brush.set("fiber", "#f5f0ff", 1.6);
  brush.spline(silverskinPts, 0.35);

  // 6. Obsessive Fibrous Muscle Grain (2,400 directional fascicle strokes)
  const fiberPaletteDark = ["#470510", "#5e0a18", "#781223", "#8c1b2d"];
  const fiberPaletteMid  = ["#a62639", "#ba3448", "#cc475b", "#d95d70"];
  const fiberPaletteLit  = ["#e37889", "#ed95a4", "#f5b5c1", "#fad2da"];

  for (let i = 0; i < 2450; i++) {
    let x = random(200, 995);
    let y = random(295, 835);
    let inEye = pointInPoly(x, y, SCENE.polyEye);
    let inCap = !inEye && pointInPoly(x, y, SCENE.polyCap);
    let inComp = !inEye && !inCap && pointInPoly(x, y, SCENE.polyComplexus);
    let inTail = !inEye && !inCap && !inComp && pointInPoly(x, y, SCENE.polyTail);

    if (!inEye && !inCap && !inComp && !inTail) continue;
    if (pointInPoly(x, y, SCENE.polyFatKernel)) continue;

    let ang = getMuscleFiberAngle(x, y);
    let len = random(12, 34);
    let nVal = noise(x * 0.025, y * 0.025);

    let col;
    let w;
    if (nVal < 0.36) {
      col = random(fiberPaletteDark);
      w = random(0.65, 1.15);
    } else if (nVal < 0.72) {
      col = random(fiberPaletteMid);
      w = random(0.75, 1.35);
    } else {
      col = random(fiberPaletteLit);
      w = random(0.6, 1.1);
    }

    let x1 = x - cos(ang) * len * 0.5;
    let y1 = y - sin(ang) * len * 0.5;
    let x2 = x + cos(ang) * len * 0.5;
    let y2 = y + sin(ang) * len * 0.5;
    let perp = ang + 90;
    let curve = random(-3.5, 3.5);
    let xm = x + cos(perp) * curve;
    let ym = y + sin(perp) * curve;

    brush.set(i % 4 === 0 ? "cpencil" : "fiber", col, w);
    brush.spline([[x1, y1, 0.3], [xm, ym, 1.0], [x2, y2, 0.3]], 0.3);
  }

  // Deep intramuscular fascicle crevices (dark oxblood separation lines between muscle bundles)
  for (let i = 0; i < 160; i++) {
    let x = random(210, 980);
    let y = random(300, 820);
    if (!pointInPoly(x, y, SCENE.polyEye) && !pointInPoly(x, y, SCENE.polyCap)) continue;
    let ang = getMuscleFiberAngle(x, y) + random(-10, 10);
    let len = random(22, 55);
    let p1 = [x, y, 0.2];
    let p2 = [x + cos(ang) * len * 0.5 + random(-4, 4), y + sin(ang) * len * 0.5 + random(-4, 4), 1.0];
    let p3 = [x + cos(ang) * len, y + sin(ang) * len, 0.2];
    brush.set("2B", "#3d040e", random(0.6, 1.05));
    brush.spline([p1, p2, p3], 0.35);
  }

  // 7. Obsessive Dendritic Marbling (Intramuscular Fat Network)
  // First: soft pink-blush submerged transition edge for each marbling vein
  for (let v of SCENE.marblingVeins) {
    brush.set("cpencil", "#e89ca8", v.maxW * 0.42);
    brush.wash("#f4d5d2", 185);
    drawPoly(v.poly, 0.2);
    brush.noWash();
  }

  // Second: dense creamy-ivory fat core + perpendicular fibrils locking fat to muscle
  for (let v of SCENE.marblingVeins) {
    let corePoly = scalePolygonFromCentroid(v.poly, 0.72);
    brush.noStroke();
    brush.wash("#fcf4f2", 235);
    drawPoly(corePoly, 0.2);
    brush.noWash();

    brush.set("fiber", "#fffbfa", max(0.65, v.maxW * 0.24));
    brush.spline(v.pts, 0.3);

    // Tiny feathered fibrils branching into surrounding red muscle fibers
    for (let j = 1; j < v.pts.length - 1; j += 2) {
      let pt = v.pts[j];
      let fAng = getMuscleFiberAngle(pt[0], pt[1]);
      let fLen = random(5, 13);
      brush.set("fiber", "#f7dfdc", 0.6);
      brush.line(pt[0] - cos(fAng) * fLen, pt[1] - sin(fAng) * fLen, pt[0] + cos(fAng) * fLen, pt[1] + sin(fAng) * fLen);
    }
  }

  // Third: 650 fine tertiary marbling flecks
  for (let fl of SCENE.marblingFlecks) {
    brush.set("fiber", fl.col, fl.w);
    brush.spline(fl.pts, 0.25);
  }

  // 8. Wet Specular Gloss & Moisture Pinpoints
  for (let g of SCENE.glossPoints) {
    let x1 = g.x - cos(g.ang) * g.len * 0.5;
    let y1 = g.y - sin(g.ang) * g.len * 0.5;
    let x2 = g.x + cos(g.ang) * g.len * 0.5;
    let y2 = g.y + sin(g.ang) * g.len * 0.5;

    // Tiny dark wet micro-shadow immediately below the specular ridge
    brush.set("fiber", "#4d0714", g.w * 0.75);
    brush.line(x1, y1 + 1.8, x2, y2 + 1.8);

    // Razor-sharp wet gloss highlight
    brush.set("gloss", g.bright ? "#ffffff" : "#fff0f5", g.w);
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// PASS 3: VIOLENT HORIZONTAL GLITCH / CORRUPTION BANDS
// ============================================================================

function renderCorruptionBands() {
  brush.noField();

  for (let band of SCENE.bands) {
    if (band.type === "rgb_paper") {
      renderRGBPaperSlice(band.y1, band.y2, band.dx, band.cyanDx, band.limeDx);
    } else if (band.type === "rgb_slice") {
      renderRGBSteakSlice(0, 1200, band.y1, band.y2, band.dx, band.cyanDx, band.limeDx);
    } else if (band.type === "smear_right") {
      renderPixelSmearSlice(band.srcX, band.startX, band.endX, band.y1, band.y2);
    } else if (band.type === "repeat_and_smear") {
      // Repeat the same sliver of fat 4 times on the left/center, then smear flat colour to the right
      let repW = band.srcX2 - band.srcX1;
      for (let r = 0; r < band.reps; r++) {
        let dX1 = band.destX + r * repW;
        let dX2 = dX1 + repW;
        renderRepeatedSteakChunk(band.srcX1, band.srcX2, dX1, dX2, band.y1, band.y2, r);
      }
      let smearStart = band.destX + band.reps * repW;
      renderPixelSmearSlice(band.srcX2 - 4, smearStart, band.smearEndX, band.y1, band.y2);
    } else if (band.type === "smear_and_rgb") {
      // Left side smears into long pixel-dragged streaks; right side splits into RGB marker layers
      renderPixelSmearSlice(band.splitX, band.smearStartX, band.splitX, band.y1, band.y2);
      renderRGBSteakSlice(band.splitX, 1200, band.y1, band.y2, band.dx, band.cyanDx, band.limeDx);
    } else if (band.type === "repeat_and_rgb") {
      // Repeat lower fat sliver 3 times, then RGB-split the rest of the horizontal band
      let repW = band.srcX2 - band.srcX1;
      for (let r = 0; r < band.reps; r++) {
        let dX1 = band.destX + r * repW;
        let dX2 = dX1 + repW;
        renderRepeatedSteakChunk(band.srcX1, band.srcX2, dX1, dX2, band.y1, band.y2, r);
      }
      renderRGBSteakSlice(band.rgbStartX, 1200, band.y1, band.y2, band.dx, band.cyanDx, band.limeDx);
    }

    // Crisp digital scanline tear boundaries at y1 and y2
    drawBandEdgeArtifacts(band.y1, band.y2);
  }

  brush.noClip();
}

// --- CORRUPTION MECHANISM 1: RGB CHANNEL-SEPARATED DISPLACED SLICES ---

function renderRGBSteakSlice(xMin, xMax, y1, y2, dx, cyanDx, limeDx) {
  let clipBox = [xMin, y1, xMax, y2];
  brush.clip(clipBox);

  // 1. Overwrite band background with displaced pastel pink butcher paper base
  brush.noStroke();
  brush.wash("#f4dae0", 252);
  drawClippedPoly([[xMin, y1], [xMax, y1], [xMax, y2], [xMin, y2]], clipBox);
  brush.noWash();

  // Flat scanline tone variation on the displaced paper
  for (let y = y1 + 2; y < y2; y += 4.5) {
    let pCol = (floor(y) % 2 === 0) ? "#efd0d8" : "#fae8ec";
    brush.set("flat_pixel", pCol, 1.3);
    brush.line(xMin, y, xMax, y);
  }

  // Displaced paper creases split into Acid Cyan, Lime, and Crimson marker lines
  renderDisplacedCreasesInBand(clipBox, dx, cyanDx, limeDx);

  // Displaced shadow & purge stain in separated marker washes
  drawShiftedClippedWash(SCENE.polyCastShadow, dx + cyanDx, 0, clipBox, "#00e5ff", 70);
  drawShiftedClippedWash(SCENE.polyCastShadow, dx + limeDx, 0, clipBox, "#9dff00", 65);
  drawShiftedClippedWash(SCENE.polyCastShadow, dx, 0, clipBox, "#d9043d", 95);

  // 2. ACID CYAN CHANNEL LAYER (Offset Left)
  let cShift = dx + cyanDx;
  drawShiftedClippedWash(SCENE.polySlabOuter, cShift, 0, clipBox, "#00f0ff", 165);
  drawShiftedClippedWash(SCENE.polySideWall, cShift, 0, clipBox, "#00b8d4", 185);
  drawShiftedClippedHatch(SCENE.polySlabOuter, cShift, 0, clipBox, "marker", "#00d8f0", 1.1, 5, 0);

  // 3. ACID LIME CHANNEL LAYER (Offset Right)
  let lShift = dx + limeDx;
  drawShiftedClippedWash(SCENE.polySlabOuter, lShift, 0, clipBox, "#9dff00", 165);
  drawShiftedClippedWash(SCENE.polySideWall, lShift, 0, clipBox, "#76c700", 180);
  drawShiftedClippedHatch(SCENE.polySlabOuter, lShift, 0, clipBox, "marker", "#82e600", 1.1, 5, 0);

  // 4. CRIMSON CHANNEL LAYER (Center Displaced Position)
  let rShift = dx;
  const muscles = [SCENE.polyEye, SCENE.polyCap, SCENE.polyComplexus, SCENE.polyTail];
  for (let mPoly of muscles) {
    // Acid cyan & lime muscle ghosts
    drawShiftedClippedWash(mPoly, cShift, 0, clipBox, "#00d4eb", 130);
    drawShiftedClippedWash(mPoly, lShift, 0, clipBox, "#7ee600", 120);
    // Vivid Crimson marker muscle layer
    drawShiftedClippedWash(mPoly, rShift, 0, clipBox, "#ff0044", 195);
    drawShiftedClippedHatch(mPoly, rShift, 0, clipBox, "flat_pixel", "#b80030", 1.0, 4, 0);
  }
  drawShiftedClippedWash(SCENE.polySideWall, rShift, 0, clipBox, "#8f0026", 205);

  // 5. RGB-SPLIT CENTRAL FAT KERNEL, LOBULES & MARBLING VEINS
  // In an RGB split, bright white fat (R+G+B) separates into distinct Acid Cyan, Lime, and Crimson echoes,
  // while where all three overlap it stays bright pastel cream/white!
  const fatPolys = [SCENE.polyFatKernel, ...SCENE.fatRinds];
  for (let fp of fatPolys) {
    drawShiftedClippedWash(fp, cShift, 0, clipBox, "#29f4ff", 190);
    drawShiftedClippedWash(fp, lShift, 0, clipBox, "#aeff24", 190);
    drawShiftedClippedWash(fp, rShift, 0, clipBox, "#ff245e", 185);
    // Overlap core
    let core = scalePolygonFromCentroid(fp, 0.78);
    drawShiftedClippedWash(core, rShift, 0, clipBox, "#fff7f9", 215);
  }

  for (let lob of SCENE.fatLobules) {
    if (lob.poly.bbox.maxY < y1 || lob.poly.bbox.minY > y2) continue;
    drawShiftedClippedWash(lob.poly, cShift, 0, clipBox, "#00f0ff", 150);
    drawShiftedClippedWash(lob.poly, lShift, 0, clipBox, "#9dff00", 150);
    drawShiftedClippedWash(lob.poly, rShift, 0, clipBox, "#fff2f5", 195);
  }

  // Triple-echo RGB Marbling Veins inside the corrupted slice
  for (let v of SCENE.marblingVeins) {
    if (v.poly.bbox.maxY < y1 || v.poly.bbox.minY > y2) continue;
    drawShiftedClippedWash(v.poly, cShift, 0, clipBox, "#00f5ff", 215);
    drawShiftedClippedWash(v.poly, lShift, 0, clipBox, "#a6ff00", 215);
    drawShiftedClippedWash(v.poly, rShift, 0, clipBox, "#ff0a4e", 215);

    // Center white-pink core of the displaced marbling vein
    let core = scalePolygonFromCentroid(v.poly, 0.55);
    drawShiftedClippedWash(core, rShift, 0, clipBox, "#ffffff", 220);
  }

  // Crisp offset marker contour strokes for the 3 separated channels
  drawShiftedClippedOutline(SCENE.polySlabOuter, cShift, 0, clipBox, "flat_pixel", "#00d8f0", 1.1);
  drawShiftedClippedOutline(SCENE.polySlabOuter, lShift, 0, clipBox, "flat_pixel", "#84e800", 1.1);
  drawShiftedClippedOutline(SCENE.polySlabOuter, rShift, 0, clipBox, "flat_pixel", "#d9003a", 1.2);

  brush.noClip();
}

function renderRGBPaperSlice(y1, y2, dx, cyanDx, limeDx) {
