}

// --- CORRUPTION MECHANISM 2: REPEATED FAT SLIVER STUTTER ---

function renderRepeatedSteakChunk(srcX1, srcX2, destX1, destX2, y1, y2, repIndex) {
  let clipBox = [destX1, y1, destX2, y2];
  let dx = destX1 - srcX1;
  brush.clip(clipBox);

  // 1. Reset chunk background to soft pastel butcher paper
  brush.noStroke();
  brush.wash("#f5dce2", 252);
  drawClippedPoly([[destX1, y1], [destX2, y1], [destX2, y2], [destX1, y2]], clipBox);
  brush.noWash();

  // 2. Slight RGB channel fringe on alternating repetitions for authentic buffer stutter feel
  let fringeShift = (repIndex % 2 === 0) ? 6 : -6;
  drawShiftedClippedWash(SCENE.polySlabOuter, dx - fringeShift, 0, clipBox, "#00f0ff", 140);
  drawShiftedClippedWash(SCENE.polySlabOuter, dx + fringeShift, 0, clipBox, "#9dff00", 140);

  // 3. Render the displaced steak & fat slab in this repetition box
  drawShiftedClippedWash(SCENE.polySlabOuter, dx, 0, clipBox, "#f8e8e4", 248);
  drawShiftedClippedWash(SCENE.polySideWall, dx, 0, clipBox, "#631221", 240);

  const muscles = [
    { poly: SCENE.polyEye, col: "#9e1f33" },
    { poly: SCENE.polyCap, col: "#91192c" },
    { poly: SCENE.polyComplexus, col: "#961c2f" },
    { poly: SCENE.polyTail, col: "#a32438" }
  ];
  for (let m of muscles) {
    drawShiftedClippedWash(m.poly, dx, 0, clipBox, m.col, 240);
  }

  // Prominent repeated fat kernel & fat lobules (the signature repeated sliver of fat!)
  drawShiftedClippedWash(SCENE.polyFatKernel, dx - 5, 0, clipBox, "#00f0ff", 160);
  drawShiftedClippedWash(SCENE.polyFatKernel, dx + 5, 0, clipBox, "#a2ff00", 160);
  drawShiftedClippedWash(SCENE.polyFatKernel, dx, 0, clipBox, "#fdf6f4", 250);

  for (let rPoly of SCENE.fatRinds) {
    drawShiftedClippedWash(rPoly, dx, 0, clipBox, "#fbf2ef", 245);
  }

  for (let lob of SCENE.fatLobules) {
    if (lob.poly.bbox.maxY < y1 || lob.poly.bbox.minY > y2) continue;
    if (lob.poly.bbox.maxX < srcX1 - 15 || lob.poly.bbox.minX > srcX2 + 15) continue;
    drawShiftedClippedWash(lob.poly, dx, 0, clipBox, lob.col, 235);
    drawShiftedClippedOutline(lob.poly, dx, 0, clipBox, "fiber", "#d17785", 0.85);
  }

  // Muscle fibers inside the repeated sliver
  for (let i = 0; i < 140; i++) {
    let sx = random(srcX1, srcX2);
    let sy = random(y1, y2);
    let inM =
      pointInPoly(sx, sy, SCENE.polyEye) ||
      pointInPoly(sx, sy, SCENE.polyCap) ||
      pointInPoly(sx, sy, SCENE.polyComplexus) ||
      pointInPoly(sx, sy, SCENE.polyTail);
    if (!inM || pointInPoly(sx, sy, SCENE.polyFatKernel)) continue;

    let ang = getMuscleFiberAngle(sx, sy);
    let len = random(10, 24);
    let col = random(["#5c0a18", "#821527", "#ba3448", "#e37889", "#f2aab7"]);
    brush.set("fiber", col, random(0.75, 1.25));
    brush.line(
      sx + dx - cos(ang) * len * 0.5,
      sy - sin(ang) * len * 0.5,
      sx + dx + cos(ang) * len * 0.5,
      sy + sin(ang) * len * 0.5
    );
  }

  // Repeated marbling veins + specular highlights
  for (let v of SCENE.marblingVeins) {
    if (v.poly.bbox.maxY < y1 || v.poly.bbox.minY > y2) continue;
    if (v.poly.bbox.maxX < srcX1 - 20 || v.poly.bbox.minX > srcX2 + 20) continue;
    drawShiftedClippedWash(v.poly, dx - 3, 0, clipBox, "#ff004c", 160);
    drawShiftedClippedWash(v.poly, dx + 3, 0, clipBox, "#00f0ff", 160);
    drawShiftedClippedWash(v.poly, dx, 0, clipBox, "#fffaf8", 245);
  }

  // Crisp vertical digital buffer boundary seam between each repeated sliver of fat
  brush.set("flat_pixel", "#ff004c", 0.95);
  brush.line(destX1 + 1, y1, destX1 + 1, y2);
  brush.set("flat_pixel", "#00f0ff", 0.85);
  brush.line(destX1 + 3.5, y1, destX1 + 3.5, y2);
  brush.set("flat_pixel", "#ffffff", 0.8);
  brush.line(destX2 - 1, y1, destX2 - 1, y2);

  brush.noClip();
}

// --- CORRUPTION MECHANISM 3: PIXEL-DRAGGED FLAT COLOUR SMEARS ---

function renderPixelSmearSlice(sampleX, startX, endX, y1, y2) {
  let xLeft = min(startX, endX);
  let xRight = max(startX, endX);
  let clipBox = [xLeft, y1, xRight, y2];
  brush.clip(clipBox);

  // Step vertically down the band in tight scanline ribbons and drag the exact sampled colour horizontally
  let y = y1;
  let rowIdx = 0;
  while (y < y2) {
    let stripH = random([1.8, 2.4, 3.2, 4.2]);
    if (y + stripH > y2) stripH = y2 - y;
    let sampleY = y + stripH * 0.5;

    let col = sampleSceneColorAt(sampleX, sampleY, rowIdx);
    let rPoly = [
      [xLeft, y],
      [xRight, y],
      [xRight, y + stripH + 0.4],
      [xLeft, y + stripH + 0.4]
    ];

    brush.noStroke();
    brush.wash(col, 250);
    drawClippedPoly(rPoly, clipBox);
    brush.noWash();

    // Reinforce with zero-noise flat marker pass for authentic flat pixel-dragged streak texture
    brush.set("flat_pixel", col, max(0.75, stripH * 0.48));
    brush.line(xLeft, sampleY, xRight, sampleY);

    y += stripH;
    rowIdx++;
  }

  brush.noClip();
}

function sampleSceneColorAt(x, y, rowIdx) {
  // Occasional single-scanline RGB channel corruption streak (crimson, acid cyan, lime, pastel pink)
  if (rowIdx % 11 === 3) return "#00f0ff";
  if (rowIdx % 13 === 7) return "#9dff00";
  if (rowIdx % 9 === 5) return "#ff004c";

  // Check fat kernel and fat lobules first (creamy ivory & pastel blush)
  if (pointInPoly(x, y, SCENE.polyFatKernel)) {
    return (rowIdx % 2 === 0) ? "#fcf5f2" : "#f2dad4";
  }
  for (let rPoly of SCENE.fatRinds) {
    if (pointInPoly(x, y, rPoly)) return "#faf0ed";
  }
  for (let lob of SCENE.fatLobules) {
    if (pointInPoly(x, y, lob.poly)) return lob.col;
  }

  // Check marbling veins
  for (let v of SCENE.marblingVeins) {
    if (pointInPoly(x, y, v.poly)) return "#fff8f6";
  }
  for (let fl of SCENE.marblingFlecks) {
    if (y >= fl.minY && y <= fl.maxY && x >= fl.minX && x <= fl.maxX) {
      return fl.col;
    }
  }

  // Check muscle groups (rich raw beef shades + soft pastel rose highlights)
  let inMuscle =
    pointInPoly(x, y, SCENE.polyEye) ||
    pointInPoly(x, y, SCENE.polyCap) ||
    pointInPoly(x, y, SCENE.polyComplexus) ||
    pointInPoly(x, y, SCENE.polyTail);

  if (inMuscle) {
    let n = noise(x * 0.03, y * 0.08);
    if (n < 0.25) return "#540815";
    if (n < 0.48) return "#8f192c";
    if (n < 0.72) return "#bf364b";
    if (n < 0.88) return "#e37688";
    return "#f7bfc9";
  }

  // Check remaining outer slab (intermuscular seam fat)
  if (pointInPoly(x, y, SCENE.polySlabOuter)) {
    return (rowIdx % 2 === 0) ? "#f9ece8" : "#e8bfc6";
  }

  // Check 3D side wall
  if (pointInPoly(x, y, SCENE.polySideWall)) {
    return (rowIdx % 2 === 0) ? "#691222" : "#c99e99";
  }

  // Check cast shadow & wet myoglobin stain on paper
  if (pointInPoly(x, y, SCENE.polyCastShadow)) return "#753948";
  if (pointInPoly(x, y, SCENE.polyPurgeInner)) return "#d47284";
  if (pointInPoly(x, y, SCENE.polyPurgeOuter)) return "#e6a5b2";

  // Default: soft pastel pink butcher paper
  return (rowIdx % 2 === 0) ? "#f5dde3" : "#ebd0d7";
}

function drawBandEdgeArtifacts(y1, y2) {
  brush.noClip();
  // Razor-sharp horizontal tear lines & micro-glitches along y1 and y2
  for (let i = 0; i < 7; i++) {
    let sx = random(60, 980);
    let sw = random(45, 240);
    let ey = (i % 2 === 0) ? y1 : y2;
    let col = random(["#ff004c", "#00f0ff", "#9dff00", "#ffffff", "#4a0612", "#f7ccd4"]);
    brush.set("flat_pixel", col, random(0.65, 1.15));
    brush.line(sx, ey, sx + sw, ey);
  }
}

// ============================================================================
// GEOMETRIC & SUTHERLAND-HODGMAN CLIPPING HELPERS
// ============================================================================

function makeOrganicContour(cx, cy, rx, ry, numPts, radModFn, rotDeg = 0) {
  let pts = [];
  let cRot = cos(rotDeg);
  let sRot = sin(rotDeg);
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    let m = radModFn ? radModFn(ang) : 1.0;
    let lx = rx * m * cos(ang);
    let ly = ry * m * sin(ang);
    let gx = cx + lx * cRot - ly * sRot;
    let gy = cy + lx * sRot + ly * cRot;
    pts.push([gx, gy]);
  }
  return pts;
}

function scalePolygonFromCentroid(poly, scaleF) {
  let cx = 0;
  let cy = 0;
  for (let p of poly) {
    cx += p[0];
    cy += p[1];
  }
  cx /= poly.length;
  cy /= poly.length;
  return poly.map((p) => [cx + (p[0] - cx) * scaleF, cy + (p[1] - cy) * scaleF]);
}

function computeBBox(poly) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let p of poly) {
    if (p[0] < minX) minX = p[0];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[1] > maxY) maxY = p[1];
  }
  poly.bbox = { minX, minY, maxX, maxY };
  return poly.bbox;
}

function pointInPoly(x, y, poly) {
  if (poly.bbox) {
    if (x < poly.bbox.minX || x > poly.bbox.maxX || y < poly.bbox.minY || y > poly.bbox.maxY) {
      return false;
    }
  }
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function angWrap(a) {
  let d = a % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

// Sutherland-Hodgman Axis-Aligned Rectangle Polygon Clipper
function clipPolyToRect(poly, minX, minY, maxX, maxY) {
  if (!poly || poly.length < 3) return [];

  let out = poly;
  // 1. Left: x >= minX
  out = clipEdge(out, (p) => p[0] >= minX, (a, b) => [
    minX,
    a[1] + ((b[1] - a[1]) * (minX - a[0])) / (b[0] - a[0] + 1e-9)
  ]);
  if (out.length < 3) return [];

  // 2. Right: x <= maxX
  out = clipEdge(out, (p) => p[0] <= maxX, (a, b) => [
    maxX,
    a[1] + ((b[1] - a[1]) * (maxX - a[0])) / (b[0] - a[0] + 1e-9)
  ]);
  if (out.length < 3) return [];

  // 3. Top: y >= minY
  out = clipEdge(out, (p) => p[1] >= minY, (a, b) => [
    a[0] + ((b[0] - a[0]) * (minY - a[1])) / (b[1] - a[1] + 1e-9),
    minY
  ]);
  if (out.length < 3) return [];

  // 4. Bottom: y <= maxY
  out = clipEdge(out, (p) => p[1] <= maxY, (a, b) => [
    a[0] + ((b[0] - a[0]) * (maxY - a[1])) / (b[1] - a[1] + 1e-9),
    maxY
  ]);
  if (out.length < 3) return [];

  // Deduplicate near-coincident vertices to keep p5.brush beginShape clean
  let clean = [];
  for (let i = 0; i < out.length; i++) {
    let prev = clean.length > 0 ? clean[clean.length - 1] : out[out.length - 1];
    if ( hypot(out[i][0] - prev[0], out[i][1] - prev[1]) > 1.2 ) {
      clean.push(out[i]);
    }
  }
  return clean.length >= 3 ? clean : [];
}

function clipEdge(pts, insideFn, intersectFn) {
  let res = [];
  let len = pts.length;
  for (let i = 0; i < len; i++) {
    let curr = pts[i];
    let prev = pts[(i + len - 1) % len];
    let currIn = insideFn(curr);
    let prevIn = insideFn(prev);
    if (currIn) {
      if (!prevIn) res.push(intersectFn(prev, curr));
      res.push(curr);
    } else if (prevIn) {
      res.push(intersectFn(prev, curr));
    }
  }
  return res;
}

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function drawClippedPoly(pts, clipBox) {
  let clipped = clipPolyToRect(pts, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return;
  drawPoly(clipped, 0);
}

function drawShiftedClippedWash(poly, dx, dy, clipBox, col, opacity) {
  if (poly.bbox) {
    if (poly.bbox.maxY + dy < clipBox[1] || poly.bbox.minY + dy > clipBox[3]) return;
    if (poly.bbox.maxX + dx < clipBox[0] || poly.bbox.minX + dx > clipBox[2]) return;
  }
  let shifted = poly.map((p) => [p[0] + dx, p[1] + dy]);
  let clipped = clipPolyToRect(shifted, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return;
  brush.noStroke();
  brush.wash(col, opacity);
  drawPoly(clipped, 0);
  brush.noWash();
}

function drawShiftedClippedHatch(poly, dx, dy, clipBox, brushName, col, weight, spacing, angle) {
  if (poly.bbox) {
    if (poly.bbox.maxY + dy < clipBox[1] || poly.bbox.minY + dy > clipBox[3]) return;
    if (poly.bbox.maxX + dx < clipBox[0] || poly.bbox.minX + dx > clipBox[2]) return;
  }
  let shifted = poly.map((p) => [p[0] + dx, p[1] + dy]);
  let clipped = clipPolyToRect(shifted, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return;
  brush.noStroke();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(spacing, angle, { rand: 0.02 });
  drawPoly(clipped, 0);
  brush.noHatch();
}

function drawShiftedClippedOutline(poly, dx, dy, clipBox, brushName, col, weight) {
  if (poly.bbox) {
    if (poly.bbox.maxY + dy < clipBox[1] || poly.bbox.minY + dy > clipBox[3]) return;
    if (poly.bbox.maxX + dx < clipBox[0] || poly.bbox.minX + dx > clipBox[2]) return;
  }
  let shifted = poly.map((p) => [p[0] + dx, p[1] + dy]);
  let clipped = clipPolyToRect(shifted, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return;
  brush.set(brushName, col, weight);
  drawPoly(clipped, 0);
}

// Hyperreal Prickly Pear (Opuntia) with Ripe Tunas on Dark Amate Bark
// p5.js 2.x + p5.brush (WEBGL)

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom vector fields for pounded jonote bark fibers (amate paper)
  brush.addField("amate_h", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let n1 = noise(col * 0.11, row * 0.16, 1.7);
        let n2 = noise(col * 0.35, row * 0.35, 4.2);
        field[col][row] = map(n1, 0, 1, -18, 18) + map(n2, 0, 1, -8, 8);
      }
    }
    return field;
  });

  brush.addField("amate_v", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let n1 = noise(col * 0.16, row * 0.11, 7.3);
        let n2 = noise(col * 0.35, row * 0.35, 9.1);
        field[col][row] = 90 + map(n1, 0, 1, -18, 18) + map(n2, 0, 1, -8, 8);
      }
    }
    return field;
  });

  brush.addField("amate_knot", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let n = noise(col * 0.09, row * 0.09, 13.5);
        field[col][row] = 35 + map(n, 0, 1, -55, 55);
      }
    }
    return field;
  });
}

