// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function toWorld(cx, cy, ang, lx, ly) {
  let c = cos(ang);
  let s = sin(ang);
  return [cx + lx * c - ly * s, cy + lx * s + ly * c];
}

function drawPolyWash(pts, col, opacity, curvature = 0.25) {
  if (pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawPolyFill(pts, col, opacity, bleed = 0.15, tex = 0.4, border = 0.3, curvature = 0.25) {
  if (pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noWash();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Compute organic scalloped contour of a prickly pear cladode
function getCladodeContour(cx, cy, rx, ry, ang, scaleM = 1.0, offsetLx = 0, offsetLy = 0, numPts = 64) {
  let pts = [];
  for (let i = 0; i < numPts; i++) {
    let theta = map(i, 0, numPts, 0, 360);
    // Natural obovate shape: narrower at base (theta near 90), broader above middle (theta near 270)
    let sTheta = sin(theta);
    let cTheta = cos(theta);
    let obovateMod = 1.0 - 0.14 * sTheta - 0.05 * pow(cTheta, 2);
    // Marginal tubercle undulations (14 marginal areole bumps around perimeter)
    let undulation = 1.0 + 0.018 * cos(theta * 14) + 0.012 * (noise(cx * 0.01 + cTheta * 2, cy * 0.01 + sTheta * 2) - 0.5);
    let lx = offsetLx + cTheta * rx * scaleM * obovateMod * undulation;
    let ly = offsetLy + sTheta * ry * scaleM * undulation;
    pts.push(toWorld(cx, cy, ang, lx, ly));
  }
  return pts;
}

// Compute barrel/pear contour of a ripe tuna fruit
function getTunaContour(cx, cy, rx, ry, ang, scaleM = 1.0, offsetLx = 0, offsetLy = 0, numPts = 44) {
  let pts = [];
  for (let i = 0; i < numPts; i++) {
    let theta = map(i, 0, numPts, 0, 360);
    let sTheta = sin(theta);
    let cTheta = cos(theta);
    // Narrower tapered base at bottom (+y, theta=90), plump upper belly, flat/cupped crown at top (-y, theta=270)
    let shapeX = 1.0 - 0.18 * sTheta + 0.08 * sin(theta * 2);
    let shapeY = 1.0;
    if (sTheta < -0.75) {
      // Flattened crown rim for floral umbilicus
      shapeY = 0.93 + 0.05 * cos((theta - 270) * 4);
    }
    let bump = 1.0 + 0.014 * cos(theta * 10);
    let lx = offsetLx + cTheta * rx * scaleM * shapeX * bump;
    let ly = offsetLy + sTheta * ry * scaleM * shapeY * bump;
    pts.push(toWorld(cx, cy, ang, lx, ly));
  }
  return pts;
}

function drawJunctionShadow(cx, cy, rx, ry, ang) {
  let pts1 = getCladodeContour(cx, cy, rx, ry, ang, 1.0, 0, 0, 24);
  drawPolyWash(pts1, "#070403", 165, 0.3);
  let pts2 = getCladodeContour(cx, cy, rx * 0.75, ry * 0.75, ang, 1.0, 0, 0, 20);
  drawPolyWash(pts2, "#050302", 210, 0.3);
}

// ============================================================================
// 1. DARK AMATE BARK GROUND (Tobacco Brown & Charcoal Pounded Lattice)
// ============================================================================

function drawAmateBarkGround() {
  background("#0e0906");

  // A. Pounded lattice strips (horizontal and vertical bark ribbons beaten together)
  brush.noField();
  let stripColors = ["#1c110a", "#2b190f", "#3b2213", "#140c07", "#472916", "#23140b"];

  // Vertical jonote bark strips
  for (let x = -20; x < width + 20; x += 48) {
    let w = random(28, 46);
    let col = random(stripColors);
    let pts = [
      [x + random(-8, 8), -10],
      [x + w + random(-8, 8), -10],
      [x + w + random(-12, 12), height + 10],
      [x + random(-12, 12), height + 10]
    ];
    drawPolyWash(pts, col, random(70, 130), 0.1);
  }

  // Horizontal jonote bark strips interlocking with vertical strips
  for (let y = -20; y < height + 20; y += 52) {
    let h = random(26, 44);
    let col = random(stripColors);
    let pts = [
      [-10, y + random(-8, 8)],
      [width + 10, y + random(-8, 8)],
      [width + 10, y + h + random(-12, 12)],
      [-10, y + h + random(-12, 12)]
    ];
    drawPolyWash(pts, col, random(65, 120), 0.1);
  }

  // B. Pounded lattice grid crevices and stone-beater (muinto) impressions
  brush.wiggle(2.2);
  for (let x = 15; x < width; x += 24) {
    let isDark = (int(x / 24) % 2 === 0);
    brush.set("charcoal", isDark ? "#080504" : "#382011", random(0.6, 1.35));
    for (let y = 0; y < height; y += 140) {
      let y2 = min(height, y + random(90, 155));
      brush.line(x + random(-5, 5), y, x + random(-5, 5), y2);
    }
  }
  for (let y = 15; y < height; y += 26) {
    let isDark = (int(y / 26) % 2 === 0);
    brush.set("charcoal", isDark ? "#090604" : "#422614", random(0.55, 1.25));
    for (let x = 0; x < width; x += 140) {
      let x2 = min(width, x + random(90, 155));
      brush.line(x, y + random(-5, 5), x2, y + random(-5, 5));
    }
  }
  brush.noField();

  // C. Dense fibrous flow-field strokes in tobacco brown and charcoal
  const fiberBatchesH = [
    { col: "#120b07", count: 220, len: [70, 160], wt: [0.6, 1.4], brush: "charcoal" },
    { col: "#2e1a0e", count: 240, len: [65, 150], wt: [0.5, 1.2], brush: "charcoal" },
    { col: "#4a2b16", count: 220, len: [55, 135], wt: [0.45, 1.0], brush: "cpencil" },
    { col: "#61391e", count: 160, len: [45, 115], wt: [0.35, 0.85], brush: "cpencil" },
    { col: "#7d4c29", count: 95,  len: [35, 95],  wt: [0.28, 0.65], brush: "2B" },
    { col: "#9e663b", count: 55,  len: [30, 75],  wt: [0.22, 0.48], brush: "HB" }
  ];

  // Horizontal fibrous flow pass
  brush.field("amate_h");
  for (let b of fiberBatchesH) {
    for (let i = 0; i < b.count; i++) {
      brush.set(b.brush, b.col, random(b.wt[0], b.wt[1]));
      let x = random(-30, width + 30);
      let y = random(-20, height + 20);
      let dir = random() < 0.5 ? 0 : 180;
      brush.flowLine(x, y, random(b.len[0], b.len[1]), dir + random(-8, 8));
    }
  }

  // Vertical fibrous flow pass (creating the interlocking beaten lattice)
  brush.field("amate_v");
  for (let b of fiberBatchesH) {
    let vCount = int(b.count * 0.85);
    for (let i = 0; i < vCount; i++) {
      brush.set(b.brush, b.col, random(b.wt[0], b.wt[1]));
      let x = random(-20, width + 20);
      let y = random(-30, height + 30);
      let dir = random() < 0.5 ? 90 : 270;
      brush.flowLine(x, y, random(b.len[0], b.len[1]), dir + random(-8, 8));
    }
  }

  // Diagonal splayed bark bast knots and organic fiber tangles
  brush.field("amate_knot");
  const knotColors = ["#090604", "#3d2312", "#59341b", "#87532d", "#b07446"];
  for (let cIdx = 0; cIdx < knotColors.length; cIdx++) {
    let count = cIdx < 3 ? 110 : 50;
    for (let i = 0; i < count; i++) {
      brush.set(cIdx < 2 ? "charcoal" : "2B", knotColors[cIdx], random(0.25, 0.75));
      brush.flowLine(random(width), random(height), random(40, 110), random(360));
    }
  }
  brush.noField();

  // Subtle dark charcoal vignette & stone-pounded grain stipple
  for (let i = 0; i < 90; i++) {
    brush.set("spray", i % 2 === 0 ? "#080504" : "#3b2212", random(0.6, 1.3));
    let x = random(width);
    let y = random(height);
    brush.line(x, y, x + random(-35, 35), y + random(-35, 35));
  }
}

// ============================================================================
// 2. OTOMI WHITE CONTOUR FLICKS (Framing every form against raw dark bark)
// ============================================================================

function drawOtomiContourFlicks(contourPts, cx, cy, flickLenBase = 8.5, density = 1.0) {
  brush.noField();
  let n = contourPts.length;

  // 1. Subtle crisp inner ivory contour line broken into organic segments
  for (let i = 0; i < n; i++) {
    let p1 = contourPts[i];
    let p2 = contourPts[(i + 1) % n];
    let col = i % 3 === 0 ? "#ffffff" : "#fff6e6";
    brush.set("rotring", col, random(0.42, 0.72));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Fine outward-radiating white contour flicks along the entire perimeter
  for (let i = 0; i < n; i++) {
    let p1 = contourPts[i];
    let p2 = contourPts[(i + 1) % n];
    let segDist = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = max(2, int((segDist / 3.1) * density));

    // Tangent and outward normal
    let tx = (p2[0] - p1[0]) / (segDist || 1);
    let ty = (p2[1] - p1[1]) / (segDist || 1);
    let nx = ty;
    let ny = -tx;
    // Ensure normal points away from center (cx, cy)
    let midX = (p1[0] + p2[0]) * 0.5;
    let midY = (p1[1] + p2[1]) * 0.5;
    if ((midX - cx) * nx + (midY - cy) * ny < 0) {
      nx = -nx;
      ny = -ny;
    }
    let baseAng = atan2(ny, nx);

    for (let s = 0; s < steps; s++) {
      let t = (s + random(0.1, 0.9)) / steps;
      let sx = lerp(p1[0], p2[0], t);
      let sy = lerp(p1[1], p2[1], t);

      // Rhythmic Otomi flick angle (slightly raked along contour)
      let flickAng = baseAng + random(-24, 24);
      let fLen = flickLenBase * random(0.55, 1.38);
      let ex = sx + cos(flickAng) * fLen;
      let ey = sy + sin(flickAng) * fLen;

      // Primary bright white flick
      let isBright = random() < 0.72;
      brush.set("pen", isBright ? "#ffffff" : "#f5ead6", random(0.32, 0.62));
      brush.line(sx, sy, ex, ey);

      // Occasional secondary fine hair-flick for hyperreal crispness
      if (random() < 0.45) {
        let ang2 = baseAng + random(-35, 35);
        let len2 = fLen * random(0.45, 0.85);
        brush.set("rotring", "#fffdf7", random(0.24, 0.42));
        brush.line(sx, sy, sx + cos(ang2) * len2, sy + sin(ang2) * len2);
      }
    }
  }
}

// ============================================================================
// 3. HYPERREAL PRICKLY PEAR CLADODE (PAD) RENDERER
// ============================================================================

function drawCladode(pad) {
  const { cx, cy, rx, ry, angle, bevelDir, bevelWidth, woodyBase, warmBlush, palette } = pad;

  // A. 3D Side-Rim Thickness (Bevel) + Otomi White Contour Flicks on Outer Silhouette
  let faceContour = getCladodeContour(cx, cy, rx, ry, angle, 1.0, 0, 0, 68);
  let rimOffsetLx = bevelDir * bevelWidth;
  let rimOffsetLy = 5;
  let rimContour = getCladodeContour(cx, cy, rx, ry, angle, 1.0, rimOffsetLx, rimOffsetLy, 68);

  // Dark bark drop-shadow Halo just outside the white flicks for extreme high contrast
  let shadowContour = getCladodeContour(cx, cy, rx, ry, angle, 1.05, rimOffsetLx * 0.5, 6, 48);
  drawPolyWash(shadowContour, "#060403", 150, 0.25);

  // Draw white Otomi contour flicks around both the bevel edge and main contour
  drawOtomiContourFlicks(rimContour, cx, cy, 9.0, 0.95);
  drawOtomiContourFlicks(faceContour, cx, cy, 8.5, 1.05);

  // Render the 3D Side Bevel Rim
  drawPolyWash(rimContour, "#122b0e", 255, 0.25);
  // Rim lighting along upper bevel & deep viridian along lower bevel
  let rimLightPts = [];
  for (let i = 0; i < 68; i++) {
    let theta = map(i, 0, 68, 0, 360);
    if (theta > 165 && theta < 345) {
      rimLightPts.push(rimContour[i]);
    }
  }
  if (rimLightPts.length > 4) {
    for (let i = rimLightPts.length - 1; i >= 0; i--) {
      rimLightPts.push([
        rimLightPts[i][0] - bevelDir * bevelWidth * 0.7,
        rimLightPts[i][1]
      ]);
    }
    drawPolyWash(rimLightPts, bevelDir < 0 ? "#8fd419" : "#3a7012", 210, 0.2);
  }
  // Cross-wrinkles on the 3D bevel rim
  for (let i = 0; i < 68; i += 2) {
    let pA = faceContour[i];
    let pB = rimContour[i];
    let col = (i > 32 && i < 60) ? "#b8f028" : "#0b1f09";
    brush.set("cpencil", col, random(0.35, 0.65));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // B. Main Opaque Cladode Underpainting & 22-Layer Sculptural Volume
  drawPolyWash(faceContour, "#153610", 255, 0.25);

  // Tonal layers shifting toward upper-left key light (-lx, -ly)
  const volumeLayers = [
    { scX: 0.97, scY: 0.97, ox: 0,     oy: 0,     col: "#1d4713", op: 240 },
    { scX: 0.93, scY: 0.93, ox: -0.02, oy: -0.02, col: "#295c14", op: 225 },
    { scX: 0.88, scY: 0.89, ox: -0.04, oy: -0.04, col: "#397315", op: 215 },
    { scX: 0.82, scY: 0.84, ox: -0.06, oy: -0.06, col: "#4c8c15", op: 205 },
    { scX: 0.76, scY: 0.78, ox: -0.08, oy: -0.08, col: "#61a616", op: 195 },
    { scX: 0.69, scY: 0.72, ox: -0.10, oy: -0.10, col: "#78bf18", op: 185 },
    { scX: 0.62, scY: 0.65, ox: -0.13, oy: -0.12, col: "#91d61c", op: 175 },
    { scX: 0.54, scY: 0.57, ox: -0.16, oy: -0.15, col: "#abe824", op: 165 },
    { scX: 0.45, scY: 0.48, ox: -0.19, oy: -0.18, col: "#c4f533", op: 155 },
    { scX: 0.36, scY: 0.39, ox: -0.22, oy: -0.21, col: "#d9fc4c", op: 140 },
    { scX: 0.26, scY: 0.29, ox: -0.25, oy: -0.24, col: "#ebff75", op: 120 },
    { scX: 0.16, scY: 0.18, ox: -0.27, oy: -0.26, col: "#f7ffad", op: 95 }
  ];

  for (let lyr of volumeLayers) {
    let pts = [];
    let nPts = 40;
    for (let i = 0; i < nPts; i++) {
      let theta = map(i, 0, nPts, 0, 360);
      let sT = sin(theta);
      let cT = cos(theta);
      let obovate = 1.0 - 0.12 * sT;
      let lx = (lyr.ox + cT * lyr.scX * obovate) * rx;
      let ly = (lyr.oy + sT * lyr.scY) * ry;
      // Clamp inside pad boundary
      pts.push(toWorld(cx, cy, angle, lx, ly));
    }
    drawPolyWash(pts, lyr.col, lyr.op, 0.3);
  }

  // Deep core shadow crescent on lower-right belly
  let shadowCrescent = [];
  for (let i = 0; i <= 24; i++) {
    let a = map(i, 0, 24, -15, 135);
    shadowCrescent.push(toWorld(cx, cy, angle, cos(a) * rx * 0.92, sin(a) * ry * 0.92));
  }
  for (let i = 24; i >= 0; i--) {
    let a = map(i, 0, 24, -15, 135);
    shadowCrescent.push(toWorld(cx, cy, angle, cos(a) * rx * 0.58 + rx * 0.08, sin(a) * ry * 0.58 + ry * 0.08));
  }
  drawPolyWash(shadowCrescent, "#0d240a", 155, 0.3);

  // C. Otomi Saturated Vermilion & Magenta Rim Blush / Reflected Fruit Glow
  if (warmBlush > 0) {
    // Upper crest sun-stress flush (vermilion-gold to magenta)
    let crestFlush = [];
    for (let i = 0; i <= 22; i++) {
      let a = map(i, 0, 22, 195, 345);
      crestFlush.push(toWorld(cx, cy, angle, cos(a) * rx * 0.97, sin(a) * ry * 0.97));
    }
    for (let i = 22; i >= 0; i--) {
      let a = map(i, 0, 22, 195, 345);
      crestFlush.push(toWorld(cx, cy, angle, cos(a) * rx * 0.76, sin(a) * ry * 0.74));
    }
    drawPolyFill(crestFlush, "#ff4d17", int(75 * warmBlush), 0.22, 0.45, 0.25);

    let innerFlush = [];
    for (let i = 0; i <= 18; i++) {
      let a = map(i, 0, 18, 210, 330);
      innerFlush.push(toWorld(cx, cy, angle, cos(a) * rx * 0.98, sin(a) * ry * 0.98));
    }
    for (let i = 18; i >= 0; i--) {
      let a = map(i, 0, 18, 210, 330);
      innerFlush.push(toWorld(cx, cy, angle, cos(a) * rx * 0.87, sin(a) * ry * 0.86));
    }
    drawPolyWash(innerFlush, "#d91162", int(85 * warmBlush), 0.25);
  }

  // D. Woody Corking at Base (especially on Basal Pad 0)
  if (woodyBase > 0.1) {
    let corkRings = int(map(woodyBase, 0, 1, 2, 7));
    for (let r = 0; r < corkRings; r++) {
      let t = r / corkRings;
      let yStart = lerp(ry * 0.35, ry * 0.72, t);
      let corkPts = [];
      for (let i = 0; i <= 16; i++) {
        let a = map(i, 0, 16, 25, 155);
        let radY = lerp(ry * 0.96, yStart, noise(i * 0.4, r));
        corkPts.push(toWorld(cx, cy, angle, cos(a) * rx * 0.82, sin(a) * radY));
      }
      let corkColors = ["#4a2c14", "#6b421f", "#8c5b2b", "#331e0d", "#a67846"];
      drawPolyWash(corkPts, corkColors[r % corkColors.length], 150, 0.15);
    }
    // Striated woody bark lines at base
    for (let i = 0; i < int(75 * woodyBase); i++) {
      let a = random(35, 145);
      let r1 = random(0.55, 0.94);
      let r2 = r1 + random(0.05, 0.14);
      let p1 = toWorld(cx, cy, angle, cos(a) * rx * r1 * 0.82, sin(a) * ry * r1);
      let p2 = toWorld(cx, cy, angle, cos(a + random(-8, 8)) * rx * r2 * 0.82, sin(a + random(-8, 8)) * ry * r2);
      brush.set("cpencil", i % 2 === 0 ? "#2e1a0b" : "#b58955", random(0.35, 0.75));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // E. Cuticular Surface Texture & Waxy Epicuticular Sheen on Pad
  for (let i = 0; i < 160; i++) {
    let u = random(-0.88, 0.88);
    let v = random(-0.88, 0.88);
    if (u * u + v * v > 0.86) continue;
    let obovate = 1.0 - 0.14 * v;
    let lx = u * rx * obovate;
    let ly = v * ry;
    let lightVal = (-u * 0.6 - v * 0.65 + 0.5);
    let strokeCol = "#5da115";
    if (lightVal > 0.85) strokeCol = "#e8ff70";
    else if (lightVal > 0.6) strokeCol = "#b8eb26";
    else if (lightVal > 0.35) strokeCol = "#7ac218";
    else if (lightVal > 0.1) strokeCol = "#366e13";
    else strokeCol = "#14330c";

    let p1 = toWorld(cx, cy, angle, lx, ly);
    let p2 = toWorld(cx, cy, angle, lx + random(-14, 14), ly + random(-22, 22));
    brush.set("cpencil", strokeCol, random(0.35, 0.75));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Subtle dusty green-white cuticular wax bloom in midtones
  for (let i = 0; i < 28; i++) {
    let a = random(360);
    let rad = random(0.3, 0.82);
    let p1 = toWorld(cx, cy, angle, cos(a) * rx * rad * 0.85, sin(a) * ry * rad);
    brush.set("spray", "#d9f7b5", random(0.45, 0.85));
    brush.line(p1[0], p1[1], p1[0] + random(-18, 18), p1[1] + random(-18, 18));
  }

  // F. 3D Quilted Tubercles, Sunken Areoles, Spines & Minute Glochid Pen-Dot Tufts
  // Arranged in diagonal phyllotactic parastichies across the pad face
  let rows = 9;
  let cols = 7;
  for (let r = -rows; r <= rows; r++) {
    for (let c = -cols; c <= cols; c++) {
      if ((r + c) % 2 !== 0) continue; // Diamond parastichy lattice
      let u = c * 0.145 + (noise(r * 0.3, c * 0.3) - 0.5) * 0.03;
      let v = r * 0.115 + (noise(c * 0.3, r * 0.3 + 9) - 0.5) * 0.03;
      let radSq = u * u + v * v;
      if (radSq > 0.84) continue;

      // Project onto 3D ellipsoid pad surface (foreshortening near edges)
      let z = sqrt(max(0.05, 1.0 - radSq));
      let obovate = 1.0 - 0.14 * v;
      let lx = u * rx * obovate;
      let ly = v * ry;
      let centerPt = toWorld(cx, cy, angle, lx, ly);

      // 1. Sculpted 3D Tubercle Mound around the areole
      let moundR = lerp(11, 21, z) * (rx / 180);
      // Upper-left tubercle mound highlight arc
      let hlPts = [];
      for (let k = 0; k <= 8; k++) {
        let a = map(k, 0, 8, 185, 315);
        hlPts.push([
          centerPt[0] + cos(a) * moundR * 0.95,
          centerPt[1] + sin(a) * moundR * 0.85
        ]);
      }
      brush.set("cpencil", (-u - v > 0.1) ? "#e8ff6b" : "#96d11b", random(0.55, 0.95));
      brush.spline(hlPts, 0.4);

      // Lower-right tubercle crease shadow arc
      let shPts = [];
      for (let k = 0; k <= 8; k++) {
        let a = map(k, 0, 8, 10, 145);
        shPts.push([
          centerPt[0] + cos(a) * moundR * 1.05,
          centerPt[1] + sin(a) * moundR * 0.95
        ]);
      }
      brush.set("cpencil", "#112b0b", random(0.6, 1.05));
      brush.spline(shPts, 0.4);

      // 2. Sunken Dimple & Felted Areole Cushion
      let dimplePts = [];
      for (let k = 0; k < 10; k++) {
        let a = k * 36;
        dimplePts.push([
          centerPt[0] + cos(a) * (4.8 * z + 2.2),
          centerPt[1] + sin(a) * (4.2 * z + 2.0)
        ]);
      }
      drawPolyWash(dimplePts, "#10260a", 215, 0.25);

      let woolPts = [];
      for (let k = 0; k < 8; k++) {
        let a = k * 45;
        woolPts.push([
          centerPt[0] + cos(a) * (3.1 * z + 1.5),
          centerPt[1] + sin(a) * (2.7 * z + 1.3)
        ]);
      }
      drawPolyWash(woolPts, "#3b2718", 235, 0.2);

      // 3. Cast Shadow & Main Spines (longer near upper/outer margins)
      if (radSq > 0.28 && random() < 0.78) {
        let numSpines = radSq > 0.55 ? 2 : 1;
        let outAng = atan2(centerPt[1] - cy, centerPt[0] - cx);
        for (let sp = 0; sp < numSpines; sp++) {
          let spAng = outAng + (sp === 0 ? random(-22, 22) : random(20, 48));
          let spLen = map(radSq, 0.25, 0.85, 12, 28) * random(0.75, 1.25);
          let tipX = centerPt[0] + cos(spAng) * spLen;
          let tipY = centerPt[1] + sin(spAng) * spLen;

          // Cast shadow on pad surface
          brush.set("pen", "#0d2108", 0.42);
          brush.line(centerPt[0] + 2, centerPt[1] + 3, tipX + 4, tipY + 6);

          // Bone-ivory spine shaft with amber base & dark tip
          brush.set("rotring", "#f7efd9", random(0.45, 0.68));
          brush.line(centerPt[0], centerPt[1], tipX, tipY);
          brush.set("pen", "#ffffff", 0.32);
          brush.line(centerPt[0], centerPt[1], lerp(centerPt[0], tipX, 0.7), lerp(centerPt[1], tipY, 0.7));
          brush.set("rotring", "#593318", 0.35);
          brush.line(lerp(centerPt[0], tipX, 0.82), lerp(centerPt[1], tipY, 0.82), tipX, tipY);
        }
      }

      // 4. Glochid Tufts as Minute Pale Pen Dots (signature hyperreal detail)
      drawGlochidTuft(centerPt[0], centerPt[1], 4.5 * z + 2.5, 24);
    }
  }

  // Marginal areoles & glochid tufts right on the rim contour
  for (let i = 0; i < faceContour.length; i += 4) {
    let pt = faceContour[i];
    drawGlochidTuft(pt[0], pt[1], 4.2, 18);
  }
}

// Render a hyperreal tuft of barbed glochids as minute pale pen dots & micro-bristles
function drawGlochidTuft(x, y, radius, dotCount = 22) {
  brush.noField();
  const dotColors = ["#fff8d6", "#ffe380", "#ffffff", "#f5c249", "#fffdf5"];

  // Tiny short golden-ochre bristle ticks in core of cushion
  for (let i = 0; i < int(dotCount * 0.45); i++) {
    let a = random(360);
    let r1 = random(0, radius * 0.45);
    let r2 = r1 + random(1.8, 3.8);
    brush.set("rotring", "#d99b38", random(0.25, 0.42));
    brush.line(x + cos(a) * r1, y + sin(a) * r1, x + cos(a) * r2, y + sin(a) * r2);
  }

  // Dense rosette of minute pale pen dots (0.7px - 1.8px micro-dots)
  for (let i = 0; i < dotCount; i++) {
    let a = (i / dotCount) * 360 + random(-14, 14);
    let r = pow(random(), 0.65) * radius;
    let dx = x + cos(a) * r;
    let dy = y + sin(a) * r;
    let dotLen = random(0.7, 1.8);
    let col = dotColors[i % dotColors.length];
    brush.set(i % 2 === 0 ? "rotring" : "pen", col, random(0.32, 0.58));
    brush.line(dx, dy, dx + cos(a) * dotLen, dy + sin(a) * dotLen);
  }
}

// ============================================================================
// 4. HYPERREAL INTACT TUNA (RIPE PRICKLY PEAR FRUIT) RENDERER
// ============================================================================

function drawIntactTuna(tuna) {
  const { cx, cy, rx, ry, angle, style, bloom } = tuna;

  // A. Dark bark halo & Otomi White Contour Flicks
  let outerHalo = getTunaContour(cx, cy, rx, ry, angle, 1.07, 0, 3, 36);
  drawPolyWash(outerHalo, "#060403", 155, 0.25);

  let contour = getTunaContour(cx, cy, rx, ry, angle, 1.0, 0, 0, 48);
  drawOtomiContourFlicks(contour, cx, cy, 8.0, 1.05);

  // B. Opaque Saturated Pigment Volume (Vermilion, Magenta, Chartreuse)
  let baseCol = "#380219";
  if (style === "vermilion_dominant") baseCol = "#4a0808";
  if (style === "vermilion_chartreuse") baseCol = "#361808";
  drawPolyWash(contour, baseCol, 255, 0.25);

  // Define spherical/ovoid 3D volume palette based on fruit ripening stage
  let layers = [];
  if (style === "magenta_deep") {
    layers = [
      { scX: 0.95, scY: 0.95, ox: -0.02, oy: -0.01, col: "#590328", op: 240 },
      { scX: 0.89, scY: 0.90, ox: -0.04, oy: -0.02, col: "#7d063b", op: 225 },
      { scX: 0.82, scY: 0.84, ox: -0.07, oy: -0.04, col: "#a60850", op: 215 },
      { scX: 0.74, scY: 0.76, ox: -0.10, oy: -0.06, col: "#cf0e65", op: 205 },
      { scX: 0.64, scY: 0.67, ox: -0.14, oy: -0.08, col: "#f0197a", op: 190 },
      { scX: 0.53, scY: 0.56, ox: -0.18, oy: -0.11, col: "#ff2e69", op: 175 },
      { scX: 0.42, scY: 0.45, ox: -0.22, oy: -0.14, col: "#ff4d3b", op: 160 },
      { scX: 0.30, scY: 0.33, ox: -0.25, oy: -0.17, col: "#ff784f", op: 140 }
    ];
  } else if (style === "vermilion_dominant") {
    layers = [
      { scX: 0.95, scY: 0.95, ox: -0.02, oy: -0.01, col: "#6e0828", op: 240 },
      { scX: 0.89, scY: 0.90, ox: -0.04, oy: -0.02, col: "#9e1028", op: 225 },
      { scX: 0.82, scY: 0.84, ox: -0.07, oy: -0.04, col: "#c91c18", op: 215 },
      { scX: 0.74, scY: 0.76, ox: -0.10, oy: -0.06, col: "#eb2f15", op: 205 },
      { scX: 0.64, scY: 0.67, ox: -0.14, oy: -0.08, col: "#ff4417", op: 195 },
      { scX: 0.53, scY: 0.56, ox: -0.18, oy: -0.11, col: "#ff611f", op: 180 },
      { scX: 0.42, scY: 0.45, ox: -0.22, oy: -0.14, col: "#ff822e", op: 165 },
      { scX: 0.30, scY: 0.33, ox: -0.25, oy: -0.17, col: "#ffa64d", op: 140 }
    ];
  } else if (style === "vermilion_chartreuse") {
    layers = [
      { scX: 0.95, scY: 0.95, ox: -0.02, oy: -0.01, col: "#521c0d", op: 240 },
      { scX: 0.88, scY: 0.89, ox: -0.04, oy: -0.03, col: "#8c1d19", op: 225 },
      { scX: 0.80, scY: 0.82, ox: -0.07, oy: -0.05, col: "#c42428", op: 215 },
      { scX: 0.71, scY: 0.74, ox: -0.11, oy: -0.07, col: "#eb381c", op: 205 },
      { scX: 0.61, scY: 0.64, ox: -0.15, oy: -0.09, col: "#ff571c", op: 190 },
      { scX: 0.49, scY: 0.52, ox: -0.19, oy: -0.12, col: "#ff8524", op: 175 },
      { scX: 0.36, scY: 0.39, ox: -0.23, oy: -0.14, col: "#d4eb28", op: 150 }
    ];
  } else {
    // magenta_vermilion
    layers = [
      { scX: 0.95, scY: 0.95, ox: -0.02, oy: -0.01, col: "#4f0324", op: 240 },
      { scX: 0.89, scY: 0.90, ox: -0.04, oy: -0.02, col: "#82073c", op: 225 },
      { scX: 0.82, scY: 0.84, ox: -0.07, oy: -0.04, col: "#b50c53", op: 215 },
      { scX: 0.74, scY: 0.76, ox: -0.10, oy: -0.06, col: "#de1658", op: 205 },
      { scX: 0.64, scY: 0.67, ox: -0.14, oy: -0.08, col: "#ff293b", op: 195 },
      { scX: 0.53, scY: 0.56, ox: -0.18, oy: -0.11, col: "#ff4a21", op: 180 },
      { scX: 0.42, scY: 0.45, ox: -0.22, oy: -0.14, col: "#ff7129", op: 165 },
      { scX: 0.30, scY: 0.33, ox: -0.25, oy: -0.17, col: "#ff9b45", op: 140 }
