    let pts = getTunaContour(cx, cy, rx * lyr.scX, ry * lyr.scY, angle, 1.0, lyr.ox * rx, lyr.oy * ry, 32);
    drawPolyWash(pts, lyr.col, lyr.op, 0.3);
  }

  // C. Botanical Chartreuse Collar at Base of Fruit (where it joins the pad)
  let neckHeight = style === "vermilion_chartreuse" ? 0.48 : 0.72;
  let neckPts = [];
  for (let i = 0; i <= 16; i++) {
    let a = map(i, 0, 16, 20, 160);
    let shapeX = 1.0 - 0.18 * sin(a) + 0.08 * sin(a * 2);
    neckPts.push(toWorld(cx, cy, angle, cos(a) * rx * 0.94 * shapeX, sin(a) * ry * 0.95));
  }
  for (let i = 16; i >= 0; i--) {
    let a = map(i, 0, 16, 20, 160);
    neckPts.push(toWorld(cx, cy, angle, cos(a) * rx * 0.68, sin(a) * ry * neckHeight));
  }
  drawPolyWash(neckPts, "#7ec418", 175, 0.25);

  let neckHighlight = [];
  for (let i = 0; i <= 12; i++) {
    let a = map(i, 0, 12, 75, 155);
    let shapeX = 1.0 - 0.18 * sin(a) + 0.08 * sin(a * 2);
    neckHighlight.push(toWorld(cx, cy, angle, cos(a) * rx * 0.90 * shapeX, sin(a) * ry * 0.92));
  }
  for (let i = 12; i >= 0; i--) {
    let a = map(i, 0, 12, 75, 155);
    neckHighlight.push(toWorld(cx, cy, angle, cos(a) * rx * 0.45, sin(a) * ry * (neckHeight + 0.06)));
  }
  drawPolyWash(neckHighlight, "#c8f230", 160, 0.25);

  // D. Epicuticular Waxy Bloom (Pruina) — Powdery Lavender-Blue & Chalky Rose Veil
  if (bloom > 0) {
    // Midtone ring where waxy bloom is most visible
    let bloomBand1 = [];
    for (let i = 0; i <= 22; i++) {
      let a = map(i, 0, 22, -65, 215);
      bloomBand1.push(toWorld(cx, cy, angle, cos(a) * rx * 0.84, sin(a) * ry * 0.78));
    }
    for (let i = 22; i >= 0; i--) {
      let a = map(i, 0, 22, -65, 215);
      bloomBand1.push(toWorld(cx, cy, angle, cos(a) * rx * 0.32 - rx * 0.12, sin(a) * ry * 0.35 - ry * 0.08));
    }
    drawPolyFill(bloomBand1, "#d9c8f0", int(52 * bloom), 0.28, 0.55, 0.25);

    let bloomBand2 = getTunaContour(cx, cy, rx * 0.62, ry * 0.58, angle, 1.0, 0.06 * rx, -0.05 * ry, 24);
    drawPolyFill(bloomBand2, "#f0dff7", int(42 * bloom), 0.32, 0.5, 0.2);

    // Chalky dry-media bloom streaks and spray grain
    for (let i = 0; i < int(42 * bloom); i++) {
      let a = random(360);
      let rad = random(0.32, 0.86);
      let p1 = toWorld(cx, cy, angle, cos(a) * rx * rad * 0.85, sin(a) * ry * rad * 0.82);
      let p2 = toWorld(cx, cy, angle, cos(a + 14) * rx * rad * 0.85, sin(a + 14) * ry * rad * 0.82);
      brush.set(i % 3 === 0 ? "spray" : "cpencil", i % 2 === 0 ? "#e6d8f7" : "#f7e8f5", random(0.35, 0.75));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // E. Glossy Specular Highlight (where smooth skin breaks through the wax bloom)
  let spec1 = getTunaContour(cx, cy, rx * 0.20, ry * 0.22, angle, 1.0, -0.32 * rx, -0.22 * ry, 18);
  drawPolyWash(spec1, "#ffb5c8", 185, 0.3);

  let spec2 = getTunaContour(cx, cy, rx * 0.11, ry * 0.14, angle, 1.0, -0.35 * rx, -0.25 * ry, 16);
  drawPolyWash(spec2, "#fff2f6", 225, 0.3);

  let specCore = toWorld(cx, cy, angle, -0.36 * rx, -0.27 * ry);
  let specEnd = toWorld(cx, cy, angle, -0.31 * rx, -0.16 * ry);
  brush.set("pen", "#ffffff", 1.15);
  brush.line(specCore[0], specCore[1], specEnd[0], specEnd[1]);

  // F. Recessed Floral Umbilicus (Sunken Scar Cup at Fruit Apex)
  drawTunaUmbilicus(cx, cy, rx, ry, angle);

  // G. Fruit Areoles & Minute Glochid Pen-Dot Tufts
  const areoleCoords = [
    [-0.45, -0.45], [0.05, -0.48], [0.48, -0.42],
    [-0.62, -0.10], [-0.15, -0.12], [0.32, -0.10], [0.65, -0.05],
    [-0.52, 0.25],  [0.02, 0.24],   [0.50, 0.26],
    [-0.30, 0.56],  [0.25, 0.55]
  ];
  for (let ac of areoleCoords) {
    let pt = toWorld(cx, cy, angle, ac[0] * rx, ac[1] * ry);
    // Tiny dimple shadow
    brush.set("cpencil", "#2e0314", 0.65);
    brush.line(pt[0] - 2.5, pt[1] + 1.5, pt[0] + 2.5, pt[1] + 1.5);
    // Minute pale pen-dot glochid tuft
    drawGlochidTuft(pt[0], pt[1], 3.4, 15);
  }
}

// Render the sunken pleated umbilicus crater at the top of a tuna
function drawTunaUmbilicus(cx, cy, rx, ry, angle) {
  let uCenter = toWorld(cx, cy, angle, 0, -ry * 0.80);
  let uRx = rx * 0.46;
  let uRy = ry * 0.15;

  // Outer swollen crown lip highlight
  let lipPts = [];
  for (let i = 0; i <= 16; i++) {
    let a = map(i, 0, 16, -15, 195);
    lipPts.push(toWorld(uCenter[0], uCenter[1], angle, cos(a) * uRx * 1.18, sin(a) * uRy * 1.28));
  }
  brush.set("cpencil", "#ffa8bf", 0.85);
  brush.spline(lipPts, 0.4);

  // Deep crater shadow
  let craterPts = [];
  for (let i = 0; i < 20; i++) {
    let a = i * 18;
    craterPts.push(toWorld(uCenter[0], uCenter[1], angle, cos(a) * uRx, sin(a) * uRy));
  }
  drawPolyWash(craterPts, "#21030f", 240, 0.25);

  // Inner corky floral scar floor
  let scarPts = [];
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5;
    scarPts.push(toWorld(uCenter[0], uCenter[1], angle, cos(a) * uRx * 0.68, sin(a) * uRy * 0.62 + 1.5));
  }
  drawPolyWash(scarPts, "#785334", 220, 0.25);

  // Radial pleats around the umbilicus rim
  for (let i = 0; i < 12; i++) {
    let a = i * 30;
    let p1 = toWorld(uCenter[0], uCenter[1], angle, cos(a) * uRx * 0.55, sin(a) * uRy * 0.55);
    let p2 = toWorld(uCenter[0], uCenter[1], angle, cos(a) * uRx * 1.25, sin(a) * uRy * 1.25);
    brush.set("pen", i < 6 ? "#360518" : "#d9a87e", 0.38);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 5. HERO SPLIT-OPEN TUNA — WET SEEDED PULP CENTERPIECE
// ============================================================================

function drawSplitTuna(tuna) {
  const { cx, cy, rx, ry, angle, bloom } = tuna;

  // 1. Dark bark halo & Otomi White Contour Flicks around the split silhouette
  let outerHalo = getTunaContour(cx, cy, rx, ry, angle, 1.07, 0, 3, 40);
  drawPolyWash(outerHalo, "#060403", 165, 0.25);

  let contour = getTunaContour(cx, cy, rx, ry, angle, 1.0, 0, 0, 52);
  drawOtomiContourFlicks(contour, cx, cy, 9.0, 1.15);

  // 2. Outer Skin Volume (Saturated Magenta & Vermilion + Waxy Bloom on Left/Right Flanks)
  drawPolyWash(contour, "#3d021b", 255, 0.25);

  const skinLayers = [
    { scX: 0.96, scY: 0.96, ox: -0.02, oy: -0.01, col: "#6e0532", op: 245 },
    { scX: 0.90, scY: 0.91, ox: -0.04, oy: -0.02, col: "#a1094c", op: 230 },
    { scX: 0.83, scY: 0.85, ox: -0.07, oy: -0.04, col: "#d41166", op: 215 },
    { scX: 0.74, scY: 0.77, ox: -0.12, oy: -0.07, col: "#ff2459", op: 205 },
    { scX: 0.62, scY: 0.66, ox: -0.18, oy: -0.10, col: "#ff4721", op: 190 },
    { scX: 0.48, scY: 0.52, ox: -0.24, oy: -0.14, col: "#ff7329", op: 175 }
  ];
  for (let lyr of skinLayers) {
    let pts = getTunaContour(cx, cy, rx * lyr.scX, ry * lyr.scY, angle, 1.0, lyr.ox * rx, lyr.oy * ry, 36);
    drawPolyWash(pts, lyr.col, lyr.op, 0.3);
  }

  // Chartreuse basal collar at bottom of split tuna
  let neckPts = [];
  for (let i = 0; i <= 16; i++) {
    let a = map(i, 0, 16, 25, 155);
    let shapeX = 1.0 - 0.18 * sin(a) + 0.08 * sin(a * 2);
    neckPts.push(toWorld(cx, cy, angle, cos(a) * rx * 0.94 * shapeX, sin(a) * ry * 0.95));
  }
  for (let i = 16; i >= 0; i--) {
    let a = map(i, 0, 16, 25, 155);
    neckPts.push(toWorld(cx, cy, angle, cos(a) * rx * 0.65, sin(a) * ry * 0.72));
  }
  drawPolyWash(neckPts, "#96db1f", 180, 0.25);

  // Waxy lavender bloom on the intact outer flanks
  let leftBloom = [];
  for (let i = 0; i <= 14; i++) {
    let a = map(i, 0, 14, 125, 240);
    leftBloom.push(toWorld(cx, cy, angle, cos(a) * rx * 0.90, sin(a) * ry * 0.85));
  }
  for (let i = 14; i >= 0; i--) {
    let a = map(i, 0, 14, 125, 240);
    leftBloom.push(toWorld(cx, cy, angle, cos(a) * rx * 0.52, sin(a) * ry * 0.60));
  }
  drawPolyFill(leftBloom, "#e2d2f7", int(58 * bloom), 0.28, 0.5, 0.25);

  let rightBloom = [];
  for (let i = 0; i <= 14; i++) {
    let a = map(i, 0, 14, -55, 65);
    rightBloom.push(toWorld(cx, cy, angle, cos(a) * rx * 0.88, sin(a) * ry * 0.84));
  }
  for (let i = 14; i >= 0; i--) {
    let a = map(i, 0, 14, -55, 65);
    rightBloom.push(toWorld(cx, cy, angle, cos(a) * rx * 0.52, sin(a) * ry * 0.60));
  }
  drawPolyFill(rightBloom, "#d4c4eb", int(52 * bloom), 0.28, 0.5, 0.25);

  // Recessed umbilicus at top
  drawTunaUmbilicus(cx, cy, rx, ry, angle);

  // 3. THE SPLIT / FISSURE GEOMETRY (Peeled Rind & Wet Seeded Pulp Cavity)
  // Build jagged organic split boundary from top (-0.64*ry) to bottom (+0.78*ry)
  let outerRindPts = [];
  let midRindPts = [];
  let innerCavityPts = [];
  let splitSteps = 18;

  // Left side of split going down
  for (let i = 0; i <= splitSteps; i++) {
    let t = i / splitSteps;
    let ly = lerp(-0.64, 0.78, t) * ry;
    let widthProfile = sin(t * 180); // widest in middle belly
    let jag = (noise(i * 0.55, 2.1) - 0.5) * 0.09 * rx;
    let lxOuter = -(0.54 * widthProfile + 0.03) * rx + jag;
    let lxMid   = -(0.46 * widthProfile + 0.015) * rx + jag * 0.85;
    let lxInner = -(0.39 * widthProfile) * rx + jag * 0.7;

    outerRindPts.push(toWorld(cx, cy, angle, lxOuter, ly));
    midRindPts.push(toWorld(cx, cy, angle, lxMid, ly));
    innerCavityPts.push(toWorld(cx, cy, angle, lxInner, ly));
  }

  // Right side of split going back up
  for (let i = splitSteps; i >= 0; i--) {
    let t = i / splitSteps;
    let ly = lerp(-0.64, 0.78, t) * ry;
    let widthProfile = sin(t * 180);
    let jag = (noise(i * 0.55, 8.7) - 0.5) * 0.09 * rx;
    let lxOuter = (0.56 * widthProfile + 0.03) * rx + jag;
    let lxMid   = (0.47 * widthProfile + 0.015) * rx + jag * 0.85;
    let lxInner = (0.40 * widthProfile) * rx + jag * 0.7;

    outerRindPts.push(toWorld(cx, cy, angle, lxOuter, ly));
    midRindPts.push(toWorld(cx, cy, angle, lxMid, ly));
    innerCavityPts.push(toWorld(cx, cy, angle, lxInner, ly));
  }

  // A. Outer torn peel edge (chartreuse-lime subcuticle & pale cream pith)
  drawPolyWash(outerRindPts, "#d9f252", 240, 0.15);
  drawPolyWash(midRindPts, "#fff0cc", 245, 0.15);

  // Coral-pink inner rind transition
  let coralRindPts = [];
  for (let i = 0; i < midRindPts.length; i++) {
    coralRindPts.push([
      lerp(midRindPts[i][0], innerCavityPts[i][0], 0.55),
      lerp(midRindPts[i][1], innerCavityPts[i][1], 0.55)
    ]);
  }
  drawPolyWash(coralRindPts, "#ff786b", 235, 0.18);

  // Crisp torn peel edge shadow & cellular pith fibers
  for (let i = 0; i < outerRindPts.length; i++) {
    let pOut = outerRindPts[i];
    let pIn = innerCavityPts[i];
    brush.set("pen", i < splitSteps ? "#78052e" : "#ff3b5c", 0.42);
    brush.line(pOut[0], pOut[1], lerp(pOut[0], pIn[0], 0.35), lerp(pOut[1], pIn[1], 0.35));
  }

  // B. Deep Wet Pulp Cavity (Multi-layered Carmine, Ruby, Magenta & Electric Vermilion)
  drawPolyWash(innerCavityPts, "#2e010e", 255, 0.22);

  // Sculpted wet pulp mounds inside the cavity
  const pulpZones = [
    { scX: 0.90, scY: 0.92, ox: 0.02,  oy: 0.01,  col: "#57021b", op: 245 },
    { scX: 0.80, scY: 0.84, ox: 0.03,  oy: 0.00,  col: "#850529", op: 235 },
    { scX: 0.70, scY: 0.75, ox: 0.04,  oy: -0.01, col: "#b3093c", op: 225 },
    { scX: 0.58, scY: 0.65, ox: 0.03,  oy: -0.02, col: "#de1249", op: 215 },
    { scX: 0.46, scY: 0.54, ox: 0.01,  oy: -0.03, col: "#ff2424", op: 205 },
    { scX: 0.34, scY: 0.42, ox: -0.01, oy: -0.04, col: "#ff4829", op: 190 },
    { scX: 0.22, scY: 0.28, ox: -0.02, oy: -0.05, col: "#ff704d", op: 165 }
  ];

  for (let pz of pulpZones) {
    let pts = [];
    for (let i = 0; i <= 14; i++) {
      let t = i / 14;
      let ly = (lerp(-0.58, 0.72, t) * pz.scY + pz.oy) * ry;
      let w = sin(t * 180) * 0.38 * pz.scX * rx;
      pts.push(toWorld(cx, cy, angle, -w + pz.ox * rx, ly));
    }
    for (let i = 14; i >= 0; i--) {
      let t = i / 14;
      let ly = (lerp(-0.58, 0.72, t) * pz.scY + pz.oy) * ry;
      let w = sin(t * 180) * 0.38 * pz.scX * rx;
      pts.push(toWorld(cx, cy, angle, w + pz.ox * rx, ly));
    }
    drawPolyWash(pts, pz.col, pz.op, 0.3);
  }

  // Translucent wet watercolor bleed inside pulp
  drawPolyFill(innerCavityPts, "#e60b42", 55, 0.25, 0.65, 0.45);

  // Cellular wet pulp strands and glistening membrane folds
  for (let i = 0; i < 65; i++) {
    let t = random(0.08, 0.92);
    let ly = lerp(-0.56, 0.68, t) * ry;
    let maxW = sin(t * 180) * 0.35 * rx;
    let lx = random(-maxW, maxW);
    let p1 = toWorld(cx, cy, angle, lx, ly);
    let p2 = toWorld(cx, cy, angle, lx + random(-9, 9), ly + random(-12, 12));
    let strandCol = i % 3 === 0 ? "#ff6e82" : (i % 3 === 1 ? "#ff1f3d" : "#4a0115");
    brush.set("pen", strandCol, random(0.35, 0.65));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // C. Embedded Seeds in Wet Gelatinous Arils + Razor-Sharp Liquid Specular Highlights
  // Generate 72 seeds packed organically inside the exposed pulp cavity
  for (let s = 0; s < 72; s++) {
    let rowT = map(s, 0, 71, 0.08, 0.91) + random(-0.02, 0.02);
    let ly = lerp(-0.55, 0.68, rowT) * ry;
    let maxW = sin(rowT * 180) * 0.33 * rx;
    if (maxW < 4) continue;
    let lx = random(-maxW * 0.92, maxW * 0.92);
    let seedCenter = toWorld(cx, cy, angle, lx, ly);
    let sAng = angle + random(-55, 55);
    let sRx = random(2.6, 3.9);
    let sRy = random(1.8, 2.7);

    // 1. Dark ruby gelatinous aril socket around each seed
    let arilPts = [];
    for (let k = 0; k < 8; k++) {
      let a = k * 45;
      arilPts.push(toWorld(seedCenter[0], seedCenter[1], sAng, cos(a) * sRx * 1.45, sin(a) * sRy * 1.45));
    }
    drawPolyWash(arilPts, "#3b0112", 215, 0.25);

    // 2. Seed body (some submerged maroon-ruby, others exposed golden-ochre bone)
    let isSurfaceSeed = random() < 0.68;
    let seedPts = [];
    for (let k = 0; k < 8; k++) {
      let a = k * 45;
      seedPts.push(toWorld(seedCenter[0], seedCenter[1], sAng, cos(a) * sRx, sin(a) * sRy));
    }
    let seedCol = isSurfaceSeed
      ? (s % 2 === 0 ? "#f2c679" : "#dead5b")
      : "#660a22";
    drawPolyWash(seedPts, seedCol, 245, 0.25);

    // Translucent carmine juice glaze over half the seed
    if (isSurfaceSeed && random() < 0.65) {
      brush.set("pen", "#d90f45", 0.55);
      brush.line(seedCenter[0] - 1.5, seedCenter[1] + 1, seedCenter[0] + 2, seedCenter[1] + 1.5);
    }

    // 3. Wet liquid specular reflection crescent & pinpoint white glint on the aril
    let glint1 = toWorld(seedCenter[0], seedCenter[1], sAng, -sRx * 0.75, -sRy * 0.75);
    let glint2 = toWorld(seedCenter[0], seedCenter[1], sAng, sRx * 0.35, -sRy * 0.85);
    brush.set("rotring", "#ffffff", random(0.45, 0.78));
    brush.line(glint1[0], glint1[1], glint2[0], glint2[1]);

    if (s % 2 === 0) {
      let pinPt = toWorld(seedCenter[0], seedCenter[1], sAng, sRx * 0.6, sRy * 0.5);
      brush.set("pen", "#ffe3eb", 0.42);
      brush.line(pinPt[0], pinPt[1], pinPt[0] + 1.2, pinPt[1] + 0.8);
    }
  }

  // Larger wet specular reflection ribbons across the bulging central pulp
  for (let i = 0; i < 18; i++) {
    let t = random(0.18, 0.82);
    let ly = lerp(-0.48, 0.58, t) * ry;
    let maxW = sin(t * 180) * 0.26 * rx;
    let lx = random(-maxW, maxW);
    let p1 = toWorld(cx, cy, angle, lx, ly);
    let p2 = toWorld(cx, cy, angle, lx + random(-4, 4), ly + random(5, 13));
    brush.set("rotring", "#ffffff", random(0.55, 0.95));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // D. Sticky Translucent Ruby-Vermilion Juice Droplet Hanging at Bottom of Split
  let dripBase = toWorld(cx, cy, angle, 0.02 * rx, 0.78 * ry);
  let dripCenter = toWorld(cx, cy, angle, 0.03 * rx, 0.88 * ry);
  let dripPts = [];
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5;
    let dRx = 5.5 * (1.0 - 0.25 * sin(a));
    let dRy = 8.5;
    dripPts.push([
      dripCenter[0] + cos(a) * dRx,
      dripCenter[1] + sin(a) * dRy
    ]);
  }
  drawPolyWash(dripPts, "#4a0116", 240, 0.3);
  let dripInner = [];
  for (let i = 0; i < 12; i++) {
    let a = i * 30;
    dripInner.push([
      dripCenter[0] - 1.0 + cos(a) * 3.6,
      dripCenter[1] + 1.0 + sin(a) * 5.5
    ]);
  }
  drawPolyWash(dripInner, "#ff2638", 230, 0.3);
  brush.set("rotring", "#ffffff", 0.75);
  brush.line(dripCenter[0] - 2.2, dripCenter[1] - 2.5, dripCenter[0] - 1.5, dripCenter[1] + 2.0);
  brush.line(dripBase[0], dripBase[1], dripCenter[0], dripCenter[1] - 6);

  // E. Areoles & Minute Glochid Pen-Dot Tufts on the Outer Flanks of the Split Tuna
  const flankAreoles = [
    [-0.68, -0.35], [-0.78, 0.02], [-0.66, 0.38], [-0.45, 0.65],
    [0.68, -0.35],  [0.78, 0.02],  [0.68, 0.38],  [0.46, 0.65]
  ];
  for (let fa of flankAreoles) {
    let pt = toWorld(cx, cy, angle, fa[0] * rx, fa[1] * ry);
    brush.set("cpencil", "#2e0314", 0.65);
    brush.line(pt[0] - 2.5, pt[1] + 1.5, pt[0] + 2.5, pt[1] + 1.5);
    drawGlochidTuft(pt[0], pt[1], 3.8, 17);
  }
}

