// State helpers to guarantee clean transitions between fill and stroke
function onlyFill(col, opac, bleed = 0.12, tex = 0.42, border = 0.32) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opac);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

function onlyStroke(name, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, w);
}

// Organic local-to-canvas coordinate transform for the halved jackfruit
// u: transverse axis (-380 to +320), v: longitudinal axis (-400 top to +400 bottom)
function pt(u, v) {
  let nv = v / 390;
  // Subtle organic S/C-bend along length and pear-like lower belly swell
  let bend = 24 * (nv * nv - 0.28) - 8 * Math.sin(nv * Math.PI);
  let pear = 1.0 + 0.13 * Math.sin(nv * 1.55) + 0.05 * nv;
  let u2 = u * pear + bend;
  let v2 = v;

  // Tilted resting angle (-15 deg) centered on the 1200x1200 sheet
  let ang = -15 * (Math.PI / 180);
  let cx = 632;
  let cy = 628;
  let x = cx + u2 * Math.cos(ang) - v2 * Math.sin(ang);
  let y = cy + u2 * Math.sin(ang) + v2 * Math.cos(ang);
  return [x, y];
}

// Cut-face boundary in local (u, v) coordinates for angle a (in degrees) and radial scale rho
function cutRimUV(a, rho = 1.0) {
  let rad = a * (Math.PI / 180);
  // Subtle natural lobing of a large jackfruit syncarp
  let undul =
    1.0 +
    0.028 * Math.sin(3 * rad + 0.4) +
    0.016 * Math.cos(5 * rad - 0.7) -
    0.022 * Math.sin(rad);
  let rx = 242 * rho * undul;
  let ry = 378 * rho * undul;
  let u = 22 + rx * Math.cos(rad);
  let v = ry * Math.sin(rad);
  return [u, v];
}

function cutRimPt(a, rho = 1.0) {
  let [u, v] = cutRimUV(a, rho);
  return pt(u, v);
}

// Exterior 3D rind belly boundary on the left & bottom of the halved fruit (a in [55, 282])
function exteriorBellyUV(a, extFrac = 1.0) {
  let [u0, v0] = cutRimUV(a, 1.0);
  if (a < 55 || a > 282) return [u0, v0];
  let t = (a - 55) / (282 - 55); // 0 to 1
  let arch = Math.pow(Math.sin(t * Math.PI), 0.78);
  // Extra 3D rind bulge to the left (-u) and slightly down (+v)
  let du = -142 * arch * extFrac * (1 + 0.08 * Math.sin(t * Math.PI * 3));
  let dv = 34 * Math.sin(t * Math.PI) * extFrac * (1 - 0.55 * t);
  return [u0 + du, v0 + dv];
}

function exteriorBellyPt(a, extFrac = 1.0) {
  let [u, v] = exteriorBellyUV(a, extFrac);
  return pt(u, v);
}

// Core (rachis) spine position for longitudinal parameter s in [0 (top), 1 (bottom tip)]
function coreSpineUV(s) {
  let v = -368 + s * 505; // runs from v = -368 down to v = +137
  let u = 24 - 12 * Math.sin(s * Math.PI * 0.9);
  return [u, v];
}

function coreHalfWidth(s) {
  // Swells in the middle, tapers at stem neck and rounds to a blunt tip at s = 1
  if (s > 0.88) {
    let tipT = (1 - s) / 0.12;
    return 36 * Math.pow(Math.max(0, tipT), 0.55);
  }
  return 26 + 18 * Math.sin(s * Math.PI * 0.85);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Plain unprinted aged mill paper base
  background("#ebe1cd");

  drawMillPaperWear();
  drawGroundShadow();
  drawExteriorRind();
  drawStem();
  drawCutFaceRindAndCavity();
  drawBackgroundFibrousRags();
  drawCentralCore();
  drawAllArilsAndSeeds();
  drawForegroundFibrousRags();
  drawKalighatSweepingOutlines();
  drawLatexThreadsAndTinSilver();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. UNPRINTED MILL PAPER SOFT WEAR
// ---------------------------------------------------------------------------
function drawMillPaperWear() {
  // Soft peripheral age & dampness toning on mill paper
  const stains = [
    { x: 140, y: 120, rx: 280, ry: 210, col: "#dfd1b6", op: 24 },
    { x: 1080, y: 150, rx: 240, ry: 260, col: "#dccbb0", op: 20 },
    { x: 110, y: 1050, rx: 290, ry: 220, col: "#d9c7a9", op: 26 },
    { x: 1060, y: 1080, rx: 270, ry: 210, col: "#dfd1b6", op: 22 },
    { x: 600, y: 620, rx: 490, ry: 520, col: "#f3ead8", op: 18 }
  ];

  for (let s of stains) {
    onlyFill(s.col, s.op, 0.35, 0.55, 0.25);
    brush.beginShape(0.4);
    for (let a = 0; a < 360; a += 30) {
      let r1 = s.rx * (0.85 + 0.3 * noise(s.x * 0.01, a * 0.05));
      let r2 = s.ry * (0.85 + 0.3 * noise(s.y * 0.01, a * 0.05));
      brush.vertex(s.x + r1 * cos(a), s.y + r2 * sin(a));
    }
    brush.endShape(true);
  }

  // Faint laid-paper horizontal chain/wire lines & subtle handling creases
  onlyStroke("2H", "#d4c4a8", 0.32);
  for (let y = 36; y < height - 30; y += 16) {
    if (random() < 0.65) {
      let x1 = random(25, 220);
      let x2 = x1 + random(140, 420);
      brush.line(x1, y + random(-1, 1), x2, y + random(-1, 1));
    }
    if (random() < 0.65) {
      let x1 = random(640, 880);
      let x2 = min(width - 25, x1 + random(120, 320));
      brush.line(x1, y + random(-1, 1), x2, y + random(-1, 1));
    }
  }

  // Natural unbleached mill-paper hemp/husk inclusions & foxing specks
  for (let i = 0; i < 240; i++) {
    let px = random(30, width - 30);
    let py = random(30, height - 30);
    let col = random() < 0.5 ? "#c4b191" : random() < 0.7 ? "#a89171" : "#8c7252";
    onlyStroke("2B", col, random(0.25, 0.55));
    let ang = random(360);
    let len = random(1.5, 5.5);
    brush.line(px, py, px + len * cos(ang), py + len * sin(ang));
  }
}

// ---------------------------------------------------------------------------
// 2. TRANSPARENT GROUND CONTACT SHADOW
// ---------------------------------------------------------------------------
function drawGroundShadow() {
  // Subtle Kalighat grounding wash beneath the heavy lower curve of the fruit
  const layers = [
    { scaleX: 1.0, scaleY: 1.0, col: "#cbb99b", op: 34, bleed: 0.32 },
    { scaleX: 0.74, scaleY: 0.68, col: "#9e8665", op: 38, bleed: 0.24 },
    { scaleX: 0.48, scaleY: 0.42, col: "#573d22", op: 42, bleed: 0.16 }
  ];

  let [cx, cy] = pt(-45, 385);
  for (let L of layers) {
    onlyFill(L.col, L.op, L.bleed, 0.5, 0.3);
    brush.beginShape(0.45);
    for (let a = 0; a < 360; a += 24) {
      let rx = 250 * L.scaleX * (0.9 + 0.2 * noise(a * 0.04, L.scaleX));
      let ry = 44 * L.scaleY * (0.9 + 0.2 * noise(a * 0.04 + 10, L.scaleY));
      let x = cx + rx * cos(a) - 18 * sin(a);
      let y = cy + 16 + ry * sin(a) + 6 * cos(a);
      brush.vertex(x, y);
    }
    brush.endShape(true);
  }
}

// ---------------------------------------------------------------------------
// 3. EXTERIOR RIND BELLY (WATERCOLOUR ROLL + KNOBBLY GREEN-OCHRE TUBERCLES)
// ---------------------------------------------------------------------------
function drawExteriorRind() {
  // Base golden-olive watercolour wash across the visible 3D rind crescent
  onlyFill("#8c8832", 95, 0.16, 0.52, 0.4);
  brush.beginShape(0.35);
  for (let a = 56; a <= 280; a += 7) {
    let [x, y] = exteriorBellyPt(a, 1.0);
    brush.vertex(x, y);
  }
  for (let a = 280; a >= 56; a -= 7) {
    let [x, y] = cutRimPt(a, 0.98);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Kalighat volumetric shading: rolls hard toward the outer sepia outline
  const shadeBands = [
    { fromFrac: 0.45, toFrac: 1.0, col: "#5c591b", op: 68, bleed: 0.18 },
    { fromFrac: 0.68, toFrac: 1.0, col: "#38340e", op: 78, bleed: 0.14 },
    { fromFrac: 0.84, toFrac: 1.0, col: "#241909", op: 85, bleed: 0.1 }
  ];

  for (let band of shadeBands) {
    onlyFill(band.col, band.op, band.bleed, 0.58, 0.45);
    brush.beginShape(0.35);
    for (let a = 60; a <= 276; a += 7) {
      let [x, y] = exteriorBellyPt(a, band.toFrac);
      brush.vertex(x, y);
    }
    for (let a = 276; a >= 60; a -= 7) {
      let [x, y] = exteriorBellyPt(a, band.fromFrac);
      brush.vertex(x, y);
    }
    brush.endShape(true);
  }

  // Warm ochre reflected-light glow along the middle-inner turn of the rind
  onlyFill("#b89e30", 52, 0.2, 0.4, 0.25);
  brush.beginShape(0.35);
  for (let a = 78; a <= 255; a += 9) {
    let [x, y] = exteriorBellyPt(a, 0.48);
    brush.vertex(x, y);
  }
  for (let a = 255; a >= 78; a -= 9) {
    let [x, y] = exteriorBellyPt(a, 0.12);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Hyperreal knobbly green-ochre rind: staggered rows of conical hexagonal tubercles
  let rowIdx = 0;
  for (let f = 0.08; f <= 0.98; f += 0.1) {
    rowIdx++;
    let aStep = 2.6 + (1 - f) * 0.4;
    let aOffset = (rowIdx % 2) * (aStep * 0.5);
    for (let a = 62 + aOffset; a <= 274; a += aStep) {
      let t = (a - 55) / (282 - 55);
      let arch = Math.sin(t * Math.PI);
      if (arch < 0.14) continue;

      let [u, v] = exteriorBellyUV(a, f);
      let [cx, cy] = pt(u, v);

      // Outward normal direction toward the exterior outline
      let [uOut, vOut] = exteriorBellyUV(a, f + 0.09);
      let [ox, oy] = pt(uOut, vOut);
      let dx = ox - cx;
      let dy = oy - cy;
      let dLen = Math.hypot(dx, dy) || 1;
      let nx = dx / dLen;
      let ny = dy / dLen;
      let tx = -ny;
      let ty = nx;

      let knobSize = (5.5 + 4.5 * arch) * (0.82 + 0.32 * noise(a * 0.1, f * 5));
      let coneProjection = knobSize * (0.55 + 0.55 * f);

      // Apex of the conical tubercle
      let ax = cx + nx * coneProjection;
      let ay = cy + ny * coneProjection;

      // Dark sepia-olive trough around the hexagonal base of the knob
      let darkCol = f > 0.65 ? "#1f1808" : f > 0.35 ? "#332c0f" : "#4a4316";
      onlyStroke("2B", darkCol, 0.85);
      brush.spline(
        [
          [cx - tx * knobSize * 0.85, cy - ty * knobSize * 0.85, 0.4],
          [ax, ay, 1.1],
          [cx + tx * knobSize * 0.85, cy + ty * knobSize * 0.85, 0.4]
        ],
        0.45
      );

      // Lit green-ochre / yellow-ochre facet on the upper-inner side of the cone
      let litCol =
        f > 0.78
          ? "#6e6822"
          : f > 0.48
          ? "#998f2b"
          : random() < 0.5
          ? "#baa834"
          : "#cfa93a";
      onlyStroke("aril_glaze", litCol, 0.52);
      brush.line(
        cx - tx * knobSize * 0.45 - nx * knobSize * 0.2,
        cy - ty * knobSize * 0.45 - ny * knobSize * 0.2,
        ax - nx * 1.2,
        ay - ny * 1.2
      );

      // Bright ochre-citron highlight ridge on prominent central knobs
      if (f < 0.72 && random() < 0.75) {
        onlyStroke("cpencil", "#e0c552", 0.55);
        brush.line(
          cx - tx * knobSize * 0.25,
          cy - ty * knobSize * 0.25,
          ax - nx * 1.5,
          ay - ny * 1.5
        );
      }

      // Crisp dark brown-black carpel point at the very tip of each tubercle
      onlyStroke("rotring", "#1a1106", 0.75);
      brush.line(ax, ay, ax + nx * 1.6, ay + ny * 1.6);
    }
  }
}

// ---------------------------------------------------------------------------
// 4. THICK CURVED WOODEN STEM (PEDUNCLE) AT TOP
// ---------------------------------------------------------------------------
function drawStem() {
  // Stem curves up and slightly left from the top neck of the jackfruit
  const leftEdge = [
    pt(-22, -372),
    pt(-32, -412),
    pt(-54, -455),
    pt(-88, -492),
    pt(-126, -514)
  ];
  const rightEdge = [
    pt(46, -370),
    pt(34, -415),
    pt(8, -465),
    pt(-34, -508),
    pt(-86, -536)
  ];

  // Base woody olive-ochre wash
  onlyFill("#7a6b2e", 110, 0.12, 0.5, 0.4);
  brush.beginShape(0.35);
  for (let p of leftEdge) brush.vertex(p[0], p[1]);
  for (let i = rightEdge.length - 1; i >= 0; i--) {
    brush.vertex(rightEdge[i][0], rightEdge[i][1]);
  }
  brush.endShape(true);

  // Kalighat deep sepia shading roll along the left/under curve of the stem
  onlyFill("#362410", 95, 0.14, 0.55, 0.4);
  brush.beginShape(0.35);
  for (let p of leftEdge) brush.vertex(p[0], p[1]);
  for (let i = rightEdge.length - 1; i >= 0; i--) {
    let mx = lerp(leftEdge[i][0], rightEdge[i][0], 0.48);
    let my = lerp(leftEdge[i][1], rightEdge[i][1], 0.48);
    brush.vertex(mx, my);
  }
  brush.endShape(true);

  // Fibrous bark wrinkles and annular collar rings at the fruit attachment
  for (let t = 0.08; t < 0.92; t += 0.07) {
    let idx = Math.floor(t * (leftEdge.length - 1));
    let frac = t * (leftEdge.length - 1) - idx;
    let lx = lerp(leftEdge[idx][0], leftEdge[idx + 1][0], frac);
    let ly = lerp(leftEdge[idx][1], leftEdge[idx + 1][1], frac);
    let rx = lerp(rightEdge[idx][0], rightEdge[idx + 1][0], frac);
    let ry = lerp(rightEdge[idx][1], rightEdge[idx + 1][1], frac);

    onlyStroke("2B", "#2b1c0c", 0.65);
    brush.spline(
      [
        [lx, ly, 0.7],
        [(lx + rx) * 0.5 - 4, (ly + ry) * 0.5 + 5, 1.0],
        [rx, ry, 0.5]
      ],
      0.4
    );

    onlyStroke("cpencil", "#bfa858", 0.55);
    brush.line(
      lerp(lx, rx, 0.45),
      lerp(ly, ry, 0.45),
      lerp(lx, rx, 0.85),
      lerp(ly, ry, 0.85)
    );
  }

  // Cut woody end-grain oval at the top termination of the stem
  let [sx1, sy1] = leftEdge[leftEdge.length - 1];
  let [sx2, sy2] = rightEdge[rightEdge.length - 1];
  let scx = (sx1 + sx2) * 0.5;
  let scy = (sy1 + sy2) * 0.5;
  onlyFill("#c9b079", 140, 0.06, 0.4, 0.4);
  brush.circle(scx, scy, 18, 0.2);
  onlyStroke("rotring", "#2b190b", 0.8);
  brush.circle(scx, scy, 19, 0.18);
  brush.circle(scx, scy, 9, 0.15);
}

// ---------------------------------------------------------------------------
// 5. CUT-FACE RIND MARGIN, SAWTOOTH PIPS & HIGH-CONTRAST DARK CAVITY
// ---------------------------------------------------------------------------
function drawCutFaceRindAndCavity() {
  // 5A. Outer spiky sawtooth pips all around the cut perimeter
  for (let a = 0; a < 360; a += 2.2) {
    let [ux, uy] = cutRimUV(a, 0.985);
    let [ox, oy] = cutRimUV(a, 1.038 + 0.014 * Math.sin(a * 17));
    let [ux2, uy2] = cutRimUV(a + 2.0, 0.985);

    let p1 = pt(ux, uy);
    let tip = pt(ox, oy);
    let p2 = pt(ux2, uy2);

    let pipCol = (a > 65 && a < 270) ? "#615c1b" : "#7d7824";
    onlyStroke("aril_glaze", pipCol, 0.65);
    brush.line((p1[0] + p2[0]) * 0.5, (p1[1] + p2[1]) * 0.5, tip[0], tip[1]);

    // Crisp sepia spike edge
    onlyStroke("rotring", "#241709", 0.6);
    brush.line(p1[0], p1[1], tip[0], tip[1]);
    brush.line(tip[0], tip[1], p2[0], p2[1]);
  }

  // 5B. Creamy greenish-ochre cut rind cortex ring (rho = 0.88 to 1.0)
  onlyFill("#e6dbb8", 150, 0.08, 0.38, 0.35);
  brush.beginShape(0.32);
  for (let a = 0; a < 360; a += 6) {
    let [x, y] = cutRimPt(a, 0.99);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Kalighat olive-ochre & sepia wash rolling inside the cut rind margin
  onlyFill("#b5a459", 72, 0.14, 0.45, 0.35);
  brush.beginShape(0.32);
  for (let a = 0; a < 360; a += 8) {
    let [x, y] = cutRimPt(a, 0.995);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // 5C. Deep high-contrast bistre-sepia interior recess where the arils sit (rho < 0.885)
  onlyFill("#261205", 175, 0.12, 0.52, 0.45);
  brush.beginShape(0.32);
  for (let a = 0; a < 360; a += 6) {
    let [x, y] = cutRimPt(a, 0.885);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Second inner recess pass for intense dark contrast in the deep crevices
  onlyFill("#170a02", 145, 0.1, 0.48, 0.4);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 8) {
    let [x, y] = cutRimPt(a, 0.83);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // 5D. Hyperreal radial vascular fibres & oxidised latex dots across the cut rind ring
  for (let a = 0; a < 360; a += 1.6) {
    let pIn = cutRimPt(a, 0.88);
    let pMid = cutRimPt(a + random(-0.4, 0.4), 0.94);
    let pOut = cutRimPt(a, 0.992);

    let fibCol = random() < 0.45 ? "#8f7e3d" : random() < 0.7 ? "#634c20" : "#f5edd6";
    onlyStroke("rag_fibre", fibCol, random(0.45, 0.85));
    brush.spline([pIn, pMid, pOut], 0.3);

    // Tiny brown latex oxidation specks along the inner cortex ring
    if (random() < 0.55) {
      let rDot = random(0.89, 0.975);
      let pDot = cutRimPt(a + random(-0.5, 0.5), rDot);
      onlyStroke("rotring", "#472a0e", random(0.45, 0.8));
      brush.line(pDot[0], pDot[1], pDot[0] + 1.2, pDot[1] + 1.2);
    }
  }
}

// ---------------------------------------------------------------------------
// 6. BACKGROUND FIBROUS RAGS (PERIANTH STRANDS IN DEEP CREVICES)
// ---------------------------------------------------------------------------
function drawBackgroundFibrousRags() {
  // Hundreds of ribbon-like pale & amber fibrous rags radiating from core to rind wall
  for (let i = 0; i < 340; i++) {
    let a = random(360);
    let sCore = map(Math.sin(a * (Math.PI / 180)), -1, 1, 0.04, 0.98);
    sCore = constrain(sCore + random(-0.08, 0.08), 0.02, 0.99);

    let [cu, cv] = coreSpineUV(sCore);
    let [ru, rv] = cutRimUV(a, random(0.84, 0.90));

    let r0 = random(0.12, 0.32);
    let r1 = random(0.78, 0.98);
    let uStart = lerp(cu, ru, r0);
    let vStart = lerp(cv, rv, r0);
    let uEnd = lerp(cu, ru, r1);
    let vEnd = lerp(cv, rv, r1);

    let uMid1 = lerp(uStart, uEnd, 0.35) + random(-18, 18);
    let vMid1 = lerp(vStart, vEnd, 0.35) + random(-14, 14);
    let uMid2 = lerp(uStart, uEnd, 0.7) + random(-18, 18);
    let vMid2 = lerp(vStart, vEnd, 0.7) + random(-14, 14);

    let p0 = pt(uStart, vStart);
    let p1 = pt(uMid1, vMid1);
    let p2 = pt(uMid2, vMid2);
    let p3 = pt(uEnd, vEnd);

    // Stratified tones: deep amber-brown first, warm ochre mid, pale cream highlights
    let col, w;
    if (i < 130) {
      col = random(["#59310c", "#754414", "#8c561b"]);
      w = random(0.9, 1.5);
    } else if (i < 250) {
      col = random(["#b58236", "#cfa051", "#dec078"]);
      w = random(0.75, 1.25);
    } else {
      col = random(["#ebd9a7", "#f5ebd0", "#fff7e3"]);
      w = random(0.55, 0.95);
    }

    onlyStroke("rag_fibre", col, w);
    brush.spline(
      [
        [p0[0], p0[1], 0.5],
        [p1[0], p1[1], 1.1],
        [p2[0], p2[1], 0.95],
        [p3[0], p3[1], 0.3]
      ],
      0.55
    );
  }
}

// ---------------------------------------------------------------------------
// 7. CENTRAL CORE (PITH / RACHIS)
// ---------------------------------------------------------------------------
function drawCentralCore() {
  const leftCore = [];
  const rightCore = [];
  for (let s = 0; s <= 1.0; s += 0.05) {
    let [cu, cv] = coreSpineUV(s);
    let hw = coreHalfWidth(s);
    leftCore.push(pt(cu - hw, cv));
    rightCore.push(pt(cu + hw, cv));
  }

  // Base creamy yellow-ochre pith fill
  onlyFill("#ebddb8", 165, 0.08, 0.4, 0.35);
  brush.beginShape(0.32);
  for (let p of leftCore) brush.vertex(p[0], p[1]);
  for (let i = rightCore.length - 1; i >= 0; i--) {
    brush.vertex(rightCore[i][0], rightCore[i][1]);
  }
  brush.endShape(true);

  // Kalighat-style rolling warm ochre-sepia shading along both edges of the core
  onlyFill("#a88444", 75, 0.14, 0.48, 0.4);
  brush.beginShape(0.32);
  for (let p of leftCore) brush.vertex(p[0], p[1]);
  for (let i = leftCore.length - 1; i >= 0; i--) {
    let mx = lerp(leftCore[i][0], rightCore[i][0], 0.34);
    let my = lerp(leftCore[i][1], rightCore[i][1], 0.34);
    brush.vertex(mx, my);
  }
  brush.endShape(true);

  onlyFill("#946e31", 72, 0.14, 0.48, 0.4);
  brush.beginShape(0.32);
  for (let p of rightCore) brush.vertex(p[0], p[1]);
  for (let i = rightCore.length - 1; i >= 0; i--) {
    let mx = lerp(rightCore[i][0], leftCore[i][0], 0.32);
    let my = lerp(rightCore[i][1], leftCore[i][1], 0.32);
    brush.vertex(mx, my);
  }
  brush.endShape(true);

  // Bright ivory-cream central pith highlight strip
  onlyFill("#faf3e1", 95, 0.1, 0.3, 0.2);
  brush.beginShape(0.35);
  for (let i = 0; i < leftCore.length; i++) {
    brush.vertex(
      lerp(leftCore[i][0], rightCore[i][0], 0.36),
      lerp(leftCore[i][1], rightCore[i][1], 0.36)
    );
  }
  for (let i = rightCore.length - 1; i >= 0; i--) {
    brush.vertex(
      lerp(leftCore[i][0], rightCore[i][0], 0.64),
      lerp(leftCore[i][1], rightCore[i][1], 0.64)
    );
  }
  brush.endShape(true);

  // Fine transverse knife-cut striations & fibrovascular pores across the core
  for (let s = 0.02; s < 0.96; s += 0.016) {
    let [cu, cv] = coreSpineUV(s);
    let hw = coreHalfWidth(s);
    let pL = pt(cu - hw * 0.92, cv);
    let pM = pt(cu, cv + random(-3, 3));
    let pR = pt(cu + hw * 0.92, cv);

    onlyStroke("2H", "#bfa46b", 0.45);
    brush.spline([pL, pM, pR], 0.3);

    // Vascular pore dots & rust-colored oxidation specks
    for (let k = 0; k < 3; k++) {
      let uDot = cu + random(-hw * 0.8, hw * 0.8);
      let vDot = cv + random(-4, 4);
      let [dx, dy] = pt(uDot, vDot);
      let dotCol = random() < 0.6 ? "#85622a" : "#593812";
      onlyStroke("rotring", dotCol, random(0.4, 0.75));
      brush.line(dx, dy, dx + 1.1, dy + 0.8);
    }
  }
}

