// Helper to compute point in an aril's local coordinate frame
// s in [0 (base at core), 1 (outer apex)], t in [-1 (upper/left edge), +1 (lower/right edge)]
function arilFramePt(aril, s, t) {
  let du = aril.u1 - aril.u0;
  let dv = aril.v1 - aril.v0;
  let len = Math.hypot(du, dv) || 1;
  let ux = du / len;
  let uy = dv / len;
  let nx = -uy;
  let ny = ux;

  // Plump bulbous profile: narrower at core attachment (s=0), fullest around s=0.62, rounded at tip
  let profile =
    Math.pow(Math.sin(s * Math.PI), 0.58) * (0.72 + 0.42 * Math.sin(s * Math.PI * 0.85));
  let camber = aril.bend * Math.sin(s * Math.PI);

  let u = aril.u0 + ux * (s * len) + nx * (camber + t * aril.width * 0.5 * profile);
  let v = aril.v0 + uy * (s * len) + ny * (camber + t * aril.width * 0.5 * profile);
  return pt(u, v);
}

function drawSingleAril(aril) {
  let isBack = aril.mode === "back";

  // 1. Deep sepia crevice shadow beneath the bulb
  onlyFill("#210d02", isBack ? 110 : 135, 0.14, 0.5, 0.4);
  brush.beginShape(0.38);
  for (let s = 0.02; s <= 0.98; s += 0.12) {
    let p = arilFramePt(aril, s, 1.12);
    brush.vertex(p[0], p[1]);
  }
  for (let s = 0.98; s >= 0.02; s -= 0.12) {
    let p = arilFramePt(aril, s, -1.08);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 2. Main golden-saffron watercolour body of the aril
  let baseCol = isBack ? "#b85206" : random(["#e07408", "#eb820c", "#f28f11"]);
  onlyFill(baseCol, isBack ? 145 : 175, 0.1, 0.42, 0.35);
  brush.beginShape(0.36);
  for (let s = 0.0; s <= 1.0; s += 0.1) {
    let p = arilFramePt(aril, s, 1.0);
    brush.vertex(p[0], p[1]);
  }
  for (let s = 1.0; s >= 0.0; s -= 0.1) {
    let p = arilFramePt(aril, s, -1.0);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 3. Kalighat burnt-orange & sepia shading roll along the lower/outer belly of the bulb
  let shadeCol = isBack ? "#6e2903" : "#9c3b04";
  onlyFill(shadeCol, 95, 0.14, 0.48, 0.38);
  brush.beginShape(0.36);
  for (let s = 0.05; s <= 0.96; s += 0.12) {
    let p = arilFramePt(aril, s, 1.0);
    brush.vertex(p[0], p[1]);
  }
  for (let s = 0.96; s >= 0.05; s -= 0.12) {
    let p = arilFramePt(aril, s, 0.22);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  if (isBack) {
    // Subtle fold lines on background arils and return
    onlyStroke("aril_glaze", "#ffa719", 0.55);
    let pA = arilFramePt(aril, 0.15, -0.2);
    let pB = arilFramePt(aril, 0.55, -0.25);
    let pC = arilFramePt(aril, 0.88, -0.1);
    brush.spline([pA, pB, pC], 0.45);
    return;
  }

  // 4. Luminous saffron-yellow crown highlight on the upper dome of the aril
  onlyFill("#ffbe24", 125, 0.12, 0.35, 0.25);
  brush.beginShape(0.38);
  for (let s = 0.12; s <= 0.88; s += 0.12) {
    let p = arilFramePt(aril, s, 0.2);
    brush.vertex(p[0], p[1]);
  }
  for (let s = 0.88; s >= 0.12; s -= 0.12) {
    let p = arilFramePt(aril, s, -0.78);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 5. Hyperreal longitudinal turgid folds, cellular gloss & lobes
  for (let t = -0.82; t <= 0.82; t += 0.16) {
    let p0 = arilFramePt(aril, 0.08, t * 0.7);
    let p1 = arilFramePt(aril, 0.38, t);
    let p2 = arilFramePt(aril, 0.7, t * 1.04);
    let p3 = arilFramePt(aril, 0.93, t * 0.65);

    let strokeCol =
      t < -0.15 ? "#ffe066" : t < 0.25 ? "#ffb71b" : t < 0.55 ? "#c95806" : "#6e2602";
    onlyStroke("aril_glaze", strokeCol, 0.52);
    brush.spline(
      [
        [p0[0], p0[1], 0.3],
        [p1[0], p1[1], 1.1],
        [p2[0], p2[1], 1.0],
        [p3[0], p3[1], 0.25]
      ],
      0.45
    );
  }

  // Deep longitudinal crease dividing the fleshy bulb into natural lobes
  for (let creaseT of [-0.28, 0.26]) {
    let c0 = arilFramePt(aril, 0.12, creaseT);
    let c1 = arilFramePt(aril, 0.48, creaseT + random(-0.06, 0.06));
    let c2 = arilFramePt(aril, 0.85, creaseT * 0.75);

    onlyStroke("2B", "#853103", 0.72);
    brush.spline(
      [
        [c0[0], c0[1], 0.2],
        [c1[0], c1[1], 1.15],
        [c2[0], c2[1], 0.2]
      ],
      0.45
    );

    // Adjacent bright saffron ridge catching the light next to the crease
    let r0 = arilFramePt(aril, 0.16, creaseT - 0.1);
    let r1 = arilFramePt(aril, 0.5, creaseT - 0.11);
    let r2 = arilFramePt(aril, 0.82, creaseT - 0.08);
    onlyStroke("cpencil", "#ffe680", 0.65);
    brush.spline([r0, r1, r2], 0.45);
  }

  // 6. If this aril is sliced open by the knife, render the cut fleshy wall, endocarp & seed
  if (aril.mode === "cut_whole_seed" || aril.mode === "cut_halved_seed") {
    // Bright golden-yellow knife-cut bevel rim of the fleshy pod wall
    onlyFill("#ffd24c", 145, 0.06, 0.28, 0.25);
    brush.beginShape(0.35);
    for (let s = 0.16; s <= 0.86; s += 0.1) {
      let p = arilFramePt(aril, s, 0.68);
      brush.vertex(p[0], p[1]);
    }
    for (let s = 0.86; s >= 0.16; s -= 0.1) {
      let p = arilFramePt(aril, s, -0.68);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);

    // Translucent pale cream papery seed-coat membrane (endocarp) lining the cavity
    onlyFill("#f2e5c4", 155, 0.05, 0.32, 0.3);
    brush.beginShape(0.35);
    for (let s = 0.24; s <= 0.79; s += 0.09) {
      let p = arilFramePt(aril, s, 0.46);
      brush.vertex(p[0], p[1]);
    }
    for (let s = 0.79; s >= 0.24; s -= 0.09) {
      let p = arilFramePt(aril, s, -0.46);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);

    // Dark chestnut-brown seed nestled inside the cavity
    onlyFill("#3b1a09", 195, 0.05, 0.4, 0.4);
    brush.beginShape(0.36);
    for (let s = 0.28; s <= 0.75; s += 0.08) {
      let p = arilFramePt(aril, s, 0.37);
      brush.vertex(p[0], p[1]);
    }
    for (let s = 0.75; s >= 0.28; s -= 0.08) {
      let p = arilFramePt(aril, s, -0.37);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);

    if (aril.mode === "cut_whole_seed") {
      // Glossy rounded mahogany dome on the uncut chestnut seed
      let s0 = arilFramePt(aril, 0.34, -0.12);
      let s1 = arilFramePt(aril, 0.52, -0.16);
      let s2 = arilFramePt(aril, 0.68, -0.08);
      onlyStroke("aril_glaze", "#8a4924", 0.75);
      brush.spline([s0, s1, s2], 0.45);

      onlyStroke("cpencil", "#c78556", 0.65);
      brush.spline([s0, s1, s2], 0.45);
    } else {
      // Sliced seed showing firm ivory-cream inner cotyledon bordered by dark brown testa
      onlyFill("#f5ede0", 190, 0.04, 0.25, 0.25);
      brush.beginShape(0.35);
      for (let s = 0.32; s <= 0.71; s += 0.08) {
        let p = arilFramePt(aril, s, 0.28);
        brush.vertex(p[0], p[1]);
      }
      for (let s = 0.71; s >= 0.32; s -= 0.08) {
        let p = arilFramePt(aril, s, -0.28);
        brush.vertex(p[0], p[1]);
      }
      brush.endShape(true);

      // Subtle central cotyledon parting line inside the halved seed
      let k0 = arilFramePt(aril, 0.34, 0.0);
      let k1 = arilFramePt(aril, 0.52, 0.03);
      let k2 = arilFramePt(aril, 0.68, -0.02);
      onlyStroke("2H", "#b89c72", 0.55);
      brush.spline([k0, k1, k2], 0.4);
    }
  }

  // 7. Confident sepia contour accent hugging the shaded side of the aril
  let o0 = arilFramePt(aril, 0.06, 0.96);
  let o1 = arilFramePt(aril, 0.48, 1.02);
  let o2 = arilFramePt(aril, 0.88, 0.92);
  let o3 = arilFramePt(aril, 0.99, 0.0);
  onlyStroke("kalighat_ink", "#2b1305", 0.52);
  brush.spline(
    [
      [o0[0], o0[1], 0.3],
      [o1[0], o1[1], 1.0],
      [o2[0], o2[1], 0.85],
      [o3[0], o3[1], 0.25]
    ],
    0.45
  );
}

