// 9. FOREGROUND FIBROUS RAGS WEAVING BETWEEN & OVER ARILS
// ---------------------------------------------------------------------------
function drawForegroundFibrousRags() {
  // Crisp pale cream, straw, and golden-ochre perianth ribbons packed between bulbs
  for (let i = 0; i < 165; i++) {
    let a = random(360);
    let sCore = map(Math.sin(a * (Math.PI / 180)), -1, 1, 0.05, 0.96);
    sCore = constrain(sCore + random(-0.06, 0.06), 0.02, 0.98);

    let [cu, cv] = coreSpineUV(sCore);
    let [ru, rv] = cutRimUV(a, random(0.84, 0.91));

    let tStart = random(0.05, 0.45);
    let tEnd = min(0.98, tStart + random(0.28, 0.58));

    let u0 = lerp(cu, ru, tStart);
    let v0 = lerp(cv, rv, tStart);
    let u3 = lerp(cu, ru, tEnd);
    let v3 = lerp(cv, rv, tEnd);

    // S-curving around adjacent aril bellies
    let wave = random(12, 28) * (random() < 0.5 ? 1 : -1);
    let u1 = lerp(u0, u3, 0.35) + wave * 0.7;
    let v1 = lerp(v0, v3, 0.35) - wave * 0.5;
    let u2 = lerp(u0, u3, 0.7) - wave * 0.5;
    let v2 = lerp(v0, v3, 0.7) + wave * 0.4;

    let p0 = pt(u0, v0);
    let p1 = pt(u1, v1);
    let p2 = pt(u2, v2);
    let p3 = pt(u3, v3);

    // Dark sepia micro-shadow right next to the rag ribbon
    if (random() < 0.55) {
      onlyStroke("2B", "#2e1606", 0.5);
      brush.spline(
        [
          [p0[0] + 1.8, p0[1] + 2.0, 0.3],
          [p1[0] + 1.8, p1[1] + 2.0, 0.9],
          [p2[0] + 1.8, p2[1] + 2.0, 0.8],
          [p3[0] + 1.8, p3[1] + 2.0, 0.2]
        ],
