// ===========================================================================
// OCCLUSION ENGINE — KEEPS FOREGROUND SHADOWS AS PURE UNTOUCHED BLUE
// ===========================================================================
function addCylinderOccluder(x1, y1, x2, y2, r1, r2, z) {
  occluders.push({ type: "capsule", x1, y1, x2, y2, r1, r2, z });
}

function addBoxOccluder(xc, y1, y2, rx, ryCap, z) {
  occluders.push({ type: "vcyl", xc, y1, y2, rx, ryCap, z });
}

function addTorusOccluder(cx, cy, rMaj, rTube, aStart, aEnd, z) {
  occluders.push({ type: "torus", cx, cy, rMaj, rTube, aStart, aEnd, z });
}

function isOccluded(x, y, myZ) {
  for (let i = 0; i < occluders.length; i++) {
    let o = occluders[i];
    if (o.z >= myZ - 0.05) continue;

    if (o.type === "vcyl") {
      if (x < o.xc - o.rx || x > o.xc + o.rx) continue;
      let u = (x - o.xc) / o.rx;
      let dyEll = o.ryCap * sqrt(max(0, 1 - u * u));
      if (y >= o.y1 - dyEll && y <= o.y2 + dyEll) return true;
    } else if (o.type === "capsule") {
      let dx = o.x2 - o.x1;
      let dy = o.y2 - o.y1;
      let len2 = dx * dx + dy * dy;
      let t = len2 > 0 ? constrain(((x - o.x1) * dx + (y - o.y1) * dy) / len2, 0, 1) : 0;
      let px = o.x1 + t * dx;
      let py = o.y1 + t * dy;
      let r = lerp(o.r1, o.r2, t);
      if ((x - px) * (x - px) + (y - py) * (y - py) < (r - 0.6) * (r - 0.6)) return true;
    } else if (o.type === "torus") {
      let dx = x - o.cx;
      let dy = y - o.cy;
      let d = sqrt(dx * dx + dy * dy);
      if (abs(d - o.rMaj) < o.rTube - 0.6) {
        let ang = atan2(dy, dx);
        if (ang < o.aStart) ang += 360;
        if (ang >= o.aStart && ang <= o.aEnd) return true;
      }
    }
  }
  return false;
}

function buildOccluders() {
  occluders = [];
  // Z = 1.0: Foreground Leadpipe & Mouthpiece
  addCylinderOccluder(82, 478, 122, 478, 25, 14.5, 1.0);
  addCylinderOccluder(122, 478, 168, 478, 18.5, 18.5, 1.0);
  addCylinderOccluder(168, 478, 184, 478, 15, 18, 1.0);
  addCylinderOccluder(184, 478, 258, 478, 19.5, 19.5, 1.0);
