    { col: "#4c88ab", w: 0.7, n: 65 },
    { col: "#8db4c7", w: 0.55, n: 35 } // faint warm-cyan chemical salt speckle
  ];

  for (let sp of sprayPalette) {
    brush.set("spray", sp.col, sp.w);
    for (let i = 0; i < sp.n; i++) {
      let y = map(i, 0, sp.n, 18, 1182) + random(-18, 18);
