// ===========================================================================
// WARPED STUDIO ROOM REFLECTION ENVIRONMENT MAP ON POLISHED BRASS
// ===========================================================================
function computeBrassLight(nx, ny, worldX, worldY, seedOffset = 0) {
  let n2 = nx * nx + ny * ny;
  let nz = sqrt(max(0.02, 1.0 - n2));

  // Cylindrical reflection angle & vertical elevation warped by curvature
  let theta = atan2(nx, nz); // [-90, 90] in degrees
  let phi = atan2(ny, nz);

  // Anamorphic room distortion: vertical position shifts nonlinearly with nx^2 and ny
  let roomY = worldY + ny * 115 + (nx * nx) * 34 + sin(worldX * 0.45 + seedOffset) * 8;
  let roomX = theta + ny * 26 + sin(worldY * 0.55 + seedOffset) * 5;

  let lum = 0.08;

  // 1. Primary Sunlit Studio Window on Left-Front (theta in [-64, -13] deg)
  if (roomX > -66 && roomX < -11) {
    let winEnv = sin(map(roomX, -66, -11, 0, 180));
    let winLum = 0.35 + 0.65 * pow(max(0, winEnv), 0.55);

    // Warped window mullions (untouched-blue window sash bars curving across brass)
    let vMullion = abs( roomX + 38 );
    let hMullion1 = abs(((roomY + 600) % 135) - 67);
    if (vMullion < 2.6 || hMullion1 < 5.5) {
      winLum *= 0.28; // dark window muntin bar reflection
    }
    lum = max(lum, winLum);
  }

  // 2. Dark Core Shadow of Studio Interior (theta in [-11, +16] deg)
  // Left largely as untouched Prussian-cyan blueprint (< 0.20) except where horizontal bands cross
  if (roomX >= -11 && roomX <= 16) {
    let tubeEcho = 0.16 * pow(max(0, sin(roomY * 1.4)), 6);
    lum = max(lum * 0.5, 0.05 + tubeEcho);
  }

  // 3. Secondary Studio Skylight / Reflector Panel on Right (theta in [+17, +52] deg)
  if (roomX > 17 && roomX < 54) {
    let secEnv = sin(map(roomX, 17, 54, 0, 180));
    let secLum = 0.25 + 0.58 * pow(max(0, secEnv), 0.7);
    let hBeam = abs(((roomY + 420) % 110) - 55);
    if (hBeam < 6.0) secLum *= 0.35;
    lum = max(lum, secLum);
  }

  // 4. Grazing Fresnel Rim Highlights at Extreme Left & Right Edges
  let absNx = abs(nx);
  if (absNx > 0.84) {
    let rim = map(absNx, 0.84, 0.99, 0, 1, true);
    if (nx < 0) {
      lum = max(lum, 0.45 + 0.52 * rim);
    } else {
      lum = max(lum, 0.36 + 0.46 * rim);
    }
  }

  // 5. Specular boost where vertical curvature (ny) faces ceiling light (ny < -0.15)
  if (ny < -0.12) {
    let topSpec = map(ny, -0.12, -0.85, 0, 0.48, true) * (0.4 + 0.6 * (1 - abs(nx + 0.35)));
    lum += topSpec;
  } else if (ny > 0.25) {
    // Downward-facing bevels catch bright floor bounce or drop into crisp blue shadow
    let botBounce = sin(theta * 3.0) > 0.1 ? 0.28 * map(ny, 0.25, 0.85, 0, 1, true) : -0.22;
    lum += botBounce;
  }

  // Subtle horizontal room horizon modulation (ceiling / wall / drafting table bands)
  let horizonWave = 0.12 * sin(roomY * 1.65) + 0.08 * cos(roomY * 3.3 + theta * 1.8);
  lum = constrain(lum + horizonWave, 0.0, 1.0);

  return lum;
}

// ===========================================================================
// HYPERREAL CYLINDER & TORUS WHITE-HATCHING RENDERERS
// ===========================================================================

// Renders a vertical cylinder (or shaped lathe revolution) with radius profile fnR(y) and normal fnNy(y)
function hatchVerticalLathe(xc, y1, y2, fnR, fnNy, eyRatio, myZ, seed = 0, stepY = 2.2) {
  // Pass 1: Longitudinal & helical white pencil base lines (L > 0.21)
  let numCols = 34;
  for (let pass = 0; pass < 3; pass++) {
    if (pass === 0) brush.set("cpencil", "#8fc2e3", 0.28);
    if (pass === 1) brush.set("white_pencil", "#d8ecf8", 0.30);
    if (pass === 2) brush.set("white_pencil", "#faeed7", 0.32); // warm ivory white pencil

    let thresh = pass === 0 ? 0.21 : pass === 1 ? 0.40 : 0.60;
    let colStep = pass === 0 ? 1 : 1;

    for (let c = 0; c <= numCols; c += colStep) {
      let u = map(c, 0, numCols, -0.96, 0.96);
      // Slight stagger per pass so strokes weave naturally
      u = constrain(u + (pass - 1) * 0.014, -0.97, 0.97);

      let inSeg = false;
      let sx = 0, sy = 0;

      for (let y = y1; y <= y2; y += 3.5) {
        let r = fnR(y);
        let ny = fnNy(y);
        let x = xc + u * r;
        let yEll = y + eyRatio * r * sqrt(max(0, 1 - u * u));

        if (!isOccluded(x, yEll, myZ)) {
          let lum = computeBrassLight(u * sqrt(max(0, 1 - ny * ny)), ny, x, yEll, seed);
          if (lum >= thresh) {
            if (!inSeg) {
              sx = x;
              sy = yEll;
              inSeg = true;
            }
          } else if (inSeg) {
            if (dist(sx, sy, x, yEll) > 1.8) brush.line(sx, sy, x, yEll);
            inSeg = false;
          }
        } else if (inSeg) {
          if (dist(sx, sy, x, yEll) > 1.8) brush.line(sx, sy, x, yEll);
          inSeg = false;
        }
      }
      if (inSeg) {
        let rEnd = fnR(y2);
        let xEnd = xc + u * rEnd;
        let yEnd = y2 + eyRatio * rEnd * sqrt(max(0, 1 - u * u));
        if (dist(sx, sy, xEnd, yEnd) > 1.8) brush.line(sx, sy, xEnd, yEnd);
      }
    }
  }

  // Pass 2: Elliptical cross-contour hatching + bright white gel-pen speculars
  for (let tier = 0; tier < 4; tier++) {
    let thresh = tier === 0 ? 0.27 : tier === 1 ? 0.46 : tier === 2 ? 0.66 : 0.81;
    let dy = tier === 0 ? stepY * 1.35 : tier === 1 ? stepY : tier === 2 ? stepY * 0.85 : stepY * 0.72;

    if (tier === 0) brush.set("cpencil", "#abd5f0", 0.26);
    if (tier === 1) brush.set("white_pencil", "#f2e9d5", 0.32);
    if (tier === 2) brush.set("HB", "#fff8ea", 0.34);
    if (tier === 3) brush.set("gelpen", "#ffffff", 0.42);

    for (let y = y1 + tier * 0.55; y <= y2; y += dy) {
      let r = fnR(y);
      let ny = fnNy(y);
      let nyScale = sqrt(max(0.05, 1 - ny * ny));

      let inSeg = false;
      let pts = [];
      let uSteps = max(18, floor(r * 0.42));

      for (let k = 0; k <= uSteps; k++) {
        let u = map(k, 0, uSteps, -0.97, 0.97);
        let x = xc + u * r;
        let yEll = y + eyRatio * r * sqrt(max(0, 1 - u * u));

        // Add subtle diagonal cross-hatch tilt on tier 2
        if (tier === 2) yEll += u * 3.8;

        let vis = !isOccluded(x, yEll, myZ);
        let lum = vis ? computeBrassLight(u * nyScale, ny, x, yEll, seed) : 0;

        if (vis && lum >= thresh) {
          pts.push([x, yEll]);
          inSeg = true;
        } else if (inSeg) {
          emitPolyline(pts);
          pts = [];
          inSeg = false;
        }
      }
      if (inSeg) emitPolyline(pts);
    }
  }
}

// Renders a horizontal or angled tube segment from (x1,y1) to (x2,y2) with radius r1..r2
function hatchTubeSegment(x1, y1, x2, y2, r1, r2, myZ, seed = 0, ringFreq = 0) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  let tx = dx / len;
  let ty = dy / len;
  let px = -ty; // perpendicular normal X
  let py = tx;  // perpendicular normal Y

  // Pass 1: Longitudinal strokes along tube axis
  for (let tier = 0; tier < 4; tier++) {
    let thresh = tier === 0 ? 0.20 : tier === 1 ? 0.40 : tier === 2 ? 0.62 : 0.80;
    let vCount = tier === 0 ? 18 : tier === 1 ? 22 : tier === 2 ? 26 : 30;

    if (tier === 0) brush.set("cpencil", "#8ec3e6", 0.26);
    if (tier === 1) brush.set("white_pencil", "#e8f0f5", 0.30);
    if (tier === 2) brush.set("white_pencil", "#fff4df", 0.34);
    if (tier === 3) brush.set("gelpen", "#ffffff", 0.42);

    for (let j = 0; j <= vCount; j++) {
      let v = map(j, 0, vCount, -0.96, 0.96);
      let inSeg = false;
      let sx = 0, sy = 0;
      let sStep = 3.5;

      for (let s = 0; s <= len; s += sStep) {
        let t = s / len;
        let r = lerp(r1, r2, t);
        let ringBump = ringFreq > 0 ? 0.22 * sin(s * ringFreq) : 0;
        let cx = lerp(x1, x2, t) + px * v * r;
        let cy = lerp(y1, y2, t) + py * v * r;

        let nx = px * v + tx * ringBump;
        let ny = py * v + ty * ringBump;

        if (!isOccluded(cx, cy, myZ)) {
          // For horizontal tubes, swap or blend normal axes so studio windows reflect along tube length AND circumference
          let lum = computeBrassLight(
            constrain(v * 0.72 + sin(s * 0.045 + seed) * 0.28, -0.98, 0.98),
            constrain(py * v * 0.65 + ringBump, -0.95, 0.95),
            cx,
            cy,
            seed
          );
          if (lum >= thresh) {
            if (!inSeg) {
              sx = cx;
              sy = cy;
              inSeg = true;
            }
          } else if (inSeg) {
            if (dist(sx, sy, cx, cy) > 1.5) brush.line(sx, sy, cx, cy);
            inSeg = false;
          }
        } else if (inSeg) {
          if (dist(sx, sy, cx, cy) > 1.5) brush.line(sx, sy, cx, cy);
          inSeg = false;
        }
      }
      if (inSeg) {
        let ex = x2 + px * v * r2;
        let ey = y2 + py * v * r2;
        if (dist(sx, sy, ex, ey) > 1.5) brush.line(sx, sy, ex, ey);
      }
    }
  }

  // Pass 2: Elliptical cross-contour rings wrapping around the tube
  let sInterval = 2.6;
  for (let tier = 0; tier < 3; tier++) {
    let thresh = tier === 0 ? 0.32 : tier === 1 ? 0.56 : 0.78;
    let ds = tier === 0 ? sInterval * 1.4 : tier === 1 ? sInterval : sInterval * 0.75;

    if (tier === 0) brush.set("cpencil", "#b8dcf2", 0.25);
    if (tier === 1) brush.set("white_pencil", "#f7eedb", 0.30);
    if (tier === 2) brush.set("gelpen", "#ffffff", 0.38);

    for (let s = tier * 0.8; s <= len; s += ds) {
      let t = s / len;
      let r = lerp(r1, r2, t);
      let bx = lerp(x1, x2, t);
      let by = lerp(y1, y2, t);
      let ringBump = ringFreq > 0 ? 0.22 * sin(s * ringFreq) : 0;

      let pts = [];
      let vSteps = max(12, floor(r * 0.65));
      for (let k = 0; k <= vSteps; k++) {
        let v = map(k, 0, vSteps, -0.96, 0.96);
        let ellBulge = 0.22 * r * sqrt(max(0, 1 - v * v));
        let cx = bx + px * v * r + tx * ellBulge;
        let cy = by + py * v * r + ty * ellBulge;

        let vis = !isOccluded(cx, cy, myZ);
        let lum = vis
          ? computeBrassLight(
              constrain(v * 0.72 + sin(s * 0.045 + seed) * 0.28, -0.98, 0.98),
              constrain(py * v * 0.65 + ringBump, -0.95, 0.95),
              cx,
              cy,
              seed
            )
          : 0;

        if (vis && lum >= thresh) {
          pts.push([cx, cy]);
        } else if (pts.length > 0) {
          emitPolyline(pts);
          pts = [];
        }
      }
      if (pts.length > 0) emitPolyline(pts);
    }
  }
}

// Renders a 3D Torus U-Crook bend with warped room reflections
function hatchTorusCrook(cx, cy, rMaj, rTube, aStart, aEnd, myZ, seed = 0) {
  // Pass 1: Curving longitudinal strokes following the bend
  for (let tier = 0; tier < 4; tier++) {
    let thresh = tier === 0 ? 0.21 : tier === 1 ? 0.42 : tier === 2 ? 0.64 : 0.81;
    let vCount = tier === 0 ? 16 : tier === 1 ? 20 : tier === 2 ? 24 : 28;

    if (tier === 0) brush.set("cpencil", "#8bc0e3", 0.26);
    if (tier === 1) brush.set("white_pencil", "#e3eef7", 0.30);
    if (tier === 2) brush.set("white_pencil", "#faefd9", 0.34);
    if (tier === 3) brush.set("gelpen", "#ffffff", 0.42);

    for (let j = 0; j <= vCount; j++) {
      let v = map(j, 0, vCount, -0.96, 0.96);
      let r = rMaj + v * rTube;
      let pts = [];

      for (let a = aStart; a <= aEnd; a += 2.5) {
        let px = cx + r * cos(a);
        let py = cy + r * sin(a);
        let nx = cos(a) * v;
        let ny = sin(a) * v;

        let vis = !isOccluded(px, py, myZ);
        let lum = vis
          ? computeBrassLight(
              constrain(nx * 0.85 + 0.22 * sin(a * 2.0 + seed), -0.98, 0.98),
              constrain(ny * 0.85, -0.95, 0.95),
              px,
              py,
              seed
            )
          : 0;

        if (vis && lum >= thresh) {
          pts.push([px, py]);
        } else if (pts.length > 0) {
          emitPolyline(pts);
          pts = [];
        }
      }
      if (pts.length > 0) emitPolyline(pts);
    }
  }

  // Pass 2: Radial cross-contour rings around the tube cross-section
  for (let tier = 0; tier < 3; tier++) {
    let thresh = tier === 0 ? 0.30 : tier === 1 ? 0.55 : 0.78;
    let da = tier === 0 ? 3.2 : tier === 1 ? 2.2 : 1.5;

    if (tier === 0) brush.set("cpencil", "#b2d8f0", 0.25);
    if (tier === 1) brush.set("white_pencil", "#f7edd8", 0.30);
    if (tier === 2) brush.set("gelpen", "#ffffff", 0.38);

    for (let a = aStart + tier * 0.6; a <= aEnd; a += da) {
      let ca = cos(a);
      let sa = sin(a);
      let tx = -sa;
      let ty = ca;
      let pts = [];

      for (let k = 0; k <= 14; k++) {
        let v = map(k, 0, 14, -0.95, 0.95);
        let r = rMaj + v * rTube;
        let bulge = 0.22 * rTube * sqrt(max(0, 1 - v * v));
        let px = cx + r * ca + tx * bulge;
        let py = cy + r * sa + ty * bulge;

        let nx = ca * v;
        let ny = sa * v;
        let vis = !isOccluded(px, py, myZ);
        let lum = vis
          ? computeBrassLight(
              constrain(nx * 0.85 + 0.22 * sin(a * 2.0 + seed), -0.98, 0.98),
              constrain(ny * 0.85, -0.95, 0.95),
              px,
              py,
              seed
            )
          : 0;

        if (vis && lum >= thresh) {
          pts.push([px, py]);
        } else if (pts.length > 0) {
          emitPolyline(pts);
          pts = [];
        }
      }
      if (pts.length > 0) emitPolyline(pts);
    }
  }
}

function emitPolyline(pts) {
  if (pts.length < 2) return;
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    let step = max(1, floor(pts.length / 4));
    for (let i = 0; i < pts.length - 1; i += step) {
      let j = min(pts.length - 1, i + step);
      brush.line(pts[i][0], pts[i][1], pts[j][0], pts[j][1]);
    }
  }
}

// ===========================================================================
// HYPERREAL KNURLING & CONCAVE NACRE PEARL BUTTON RENDERERS
// ===========================================================================
function renderKnurledBand(xc, y1, y2, r, eyRatio, teethCount, isDiamond, myZ, seed = 0) {
  // Base cylindrical shading underneath the knurl teeth
  hatchVerticalLathe(xc, y1, y2, () => r, () => 0, eyRatio, myZ, seed, 2.5);

  // Precision machined knurling facets
  for (let i = 0; i < teethCount; i++) {
    let ang1 = map(i, 0, teethCount, -86, 86);
    let ang2 = map(i + 0.55, 0, teethCount, -86, 86);
    let u1 = sin(ang1);
    let u2 = sin(ang2);
    let uMid = 0.5 * (u1 + u2);

    let x1 = xc + u1 * r;
    let x2 = xc + u2 * r;
    let xMid = xc + uMid * r;
    let dyEll = eyRatio * r * sqrt(max(0, 1 - uMid * uMid));
    let topY = y1 + dyEll;
    let botY = y2 + dyEll;

    if (isOccluded(xMid, 0.5 * (topY + botY), myZ)) continue;

    // Macro cylinder luminance at this tooth
    let macroLum = computeBrassLight(uMid, 0, xMid, 0.5 * (topY + botY), seed);

    if (isDiamond) {
      // Diamond knurling: crisp intersecting helical micro-facets
      let rows = 5;
      let rowH = (botY - topY) / rows;
      for (let rIdx = 0; rIdx < rows; rIdx++) {
        let ry1 = topY + rIdx * rowH;
        let ry2 = ry1 + rowH;
        let ryMid = 0.5 * (ry1 + ry2);

        let localLum = macroLum + ((i + rIdx) % 2 === 0 ? 0.14 : -0.06);
        if (localLum > 0.22) {
          if (localLum > 0.72) {
            brush.set("gelpen", "#ffffff", 0.38);
          } else if (localLum > 0.45) {
            brush.set("white_pencil", "#faeed7", 0.30);
          } else {
            brush.set("cpencil", "#95c6e6", 0.24);
          }
          // Lit left & top edges of each diamond pyramid
          brush.line(x1, ryMid, xMid, ry1);
          brush.line(x1, ryMid, xMid, ry2);
          if (localLum > 0.62) {
            brush.line(xMid, ry1, x2, ryMid);
          }
        }
      }
    } else {
      // Straight vertical knurling (e.g. bottom valve caps & ferrules)
      if (macroLum > 0.18) {
        if (macroLum > 0.70) {
          brush.set("gelpen", "#ffffff", 0.40);
          brush.line(x1, topY + 0.8, x1, botY - 0.8);
          brush.set("white_pencil", "#f7edd9", 0.28);
          brush.line(xMid, topY + 0.8, xMid, botY - 0.8);
        } else if (macroLum > 0.38) {
          brush.set("white_pencil", "#e6f0f7", 0.28);
          brush.line(x1, topY + 1.2, x1, botY - 1.2);
        } else {
          // In shadow zones, only the tiny top & bottom chamfers catch pinpricks of white light
          brush.set("cpencil", "#8ec0e0", 0.24);
          brush.line(x1, topY + 0.5, x1, topY + 3.2);
          brush.line(x1, botY - 3.2, x1, botY - 0.5);
        }
      }
    }

    // Top & bottom beveled tooth crowns
    if (macroLum > 0.32) {
      brush.set("gelpen", macroLum > 0.68 ? "#ffffff" : "#d9edf7", 0.32);
      brush.line(x1, topY, x2, topY);
      brush.line(x1, botY, x2, botY);
    }
  }
}

function renderFingerButtonAndPearl(xc, yc, rBtn, rPearl, myZ, seed = 0) {
  let ey = 0.21;
  // 1. Knurled outer brass rim of finger button
  renderKnurledBand(xc, yc + 2, yc + 18, rBtn, ey, 36, false, myZ, seed);

  // 2. Underside bevel of finger button tapering to valve stem
  hatchVerticalLathe(
    xc,
    yc + 18,
    yc + 28,
    (y) => map(y, yc + 18, yc + 28, rBtn, 12.5),
    () => 0.62,
    ey,
    myZ,
    seed,
    1.6
  );

  // 3. Top brass bezel ring between outer rim and concave pearl inlay
  for (let a = 0; a < 360; a += 4) {
    let ca = cos(a);
    let sa = sin(a);
    let xOut = xc + rBtn * ca;
    let yOut = yc + 2 + rBtn * ey * sa;
    let xIn = xc + rPearl * ca;
    let yIn = yc + 2 + rPearl * ey * sa;
    let bezelLum = 0.52 + 0.45 * cos(a + 45);
    if (bezelLum > 0.35) {
      brush.set(bezelLum > 0.78 ? "gelpen" : "white_pencil", bezelLum > 0.78 ? "#ffffff" : "#f7eedb", 0.32);
      brush.line(xIn, yIn, xOut, yOut);
    }
  }

  // 4. Concave Mother-of-Pearl (Nacre) Inlay on top ellipse
  // Iridescent swirling fine white hatching + bright crescent rim reflection
  for (let rFrac = 0.08; rFrac <= 1.0; rFrac += 0.065) {
    let rx = rPearl * rFrac;
    let ry = rPearl * ey * rFrac;
    let dishDip = 3.2 * (1 - rFrac * rFrac); // concave dip

    for (let a = 0; a < 360; a += 5) {
      let a1 = a;
      let a2 = a + 5;
      let p1x = xc + rx * cos(a1);
      let p1y = yc + 2 + dishDip + ry * sin(a1);
      let p2x = xc + rx * cos(a2);
      let p2y = yc + 2 + dishDip + ry * sin(a2);

      // Concave normal tilts inward: light pools on opposite crescent (bottom-right) + silky nacre clouds
      let nacreCloud = noise(p1x * 0.08 + seed, p1y * 0.18 + seed);
      let concaveSpec = pow(max(0, cos(a1 - 35)), 2.2) * rFrac;
      let softGlow = 0.32 + 0.42 * nacreCloud + 0.55 * concaveSpec;

      if (softGlow > 0.42) {
        if (softGlow > 0.84) {
          brush.set("gelpen", "#ffffff", 0.42);
        } else if (softGlow > 0.62) {
          brush.set("white_pencil", "#fff9eb", 0.32);
        } else {
          brush.set("cpencil", "#b5dcf2", 0.25);
        }
        brush.line(p1x, p1y, p2x, p2y);
      }
    }
  }
}

