function renderBalusterPillarBrace(xc, y1, y2, myZ) {
  let ym = 0.5 * (y1 + y2);
  let h = y2 - y1;
  hatchVerticalLathe(
    xc,
    y1,
    y2,
    (y) => {
      let t = (y - ym) / (0.5 * h); // [-1, 1]
      if (abs(t) > 0.82) return map(abs(t), 0.82, 1.0, 9.5, 18.0); // wide saddle flange feet
      if (abs(t) < 0.22) return 12.8; // central hexagonal/ringed barrel
      return 7.5 + 3.5 * pow(cos(t * 140), 2);
    },
    (y) => {
      let t = (y - ym) / (0.5 * h);
      return 0.45 * sin(t * 260);
    },
    0.20,
    myZ,
    xc,
    1.6
  );
}

