  for (let i = 0; i < 3; i++) {
    let xc = vx[i];
    let seed = (i + 1) * 77;

    // 1. Finger Button & Concave Pearl Inlay (y = 250..278)
    renderFingerButtonAndPearl(xc, 250, 37, 27, 2.9, seed);

    // 2. Machined Piston Valve Stem (y = 278..366)
    hatchVerticalLathe(
      xc,
      278,
      366,
      (y) => (y < 294 ? 9.0 : 12.2),
      (y) => (abs(y - 294) < 3 ? -0.55 : 0),
      ey,
      3.0,
      seed + 5,
      1.6
    );

    // 3. Felt Crown Washer (y = 365..372)
    hatchVerticalLathe(xc, 365, 372, () => 22.5, () => -0.25, ey, 3.0, seed + 9, 1.4);

    // 4. Top Valve Cap: Upper Collar + Concave Ogee Dome (y = 372..404)
    hatchVerticalLathe(
      xc,
      372,
      404,
      (y) => {
        if (y < 382) return 27.5;
        let t = map(y, 382, 404, 0, 1);
        return lerp(27.5, 59.0, pow(t, 1.35));
      },
      (y) => (y < 382 ? -0.15 : -0.58 * sin(map(y, 382, 404, 0, 180))),
      ey,
      2.9,
      seed + 14,
      1.6
    );

    // 5. Top Valve Cap: Diamond Knurled Collar Band (y = 404..425) + Lower Lip (425..433)
    renderKnurledBand(xc, 404, 425, 59.0, ey, 42, true, 2.9, seed + 20);
    hatchVerticalLathe(xc, 425, 433, () => 56.5, () => 0.45, ey, 2.9, seed + 25, 1.5);

    // 6. Upper Valve Casing Baluster Section (y = 433..544)
    hatchVerticalLathe(
      xc,
      433,
      544,
      (y) => {
        let groove1 = exp(-pow((y - 466) / 3.5, 2)) * 2.2;
        let groove2 = exp(-pow((y - 514) / 3.5, 2)) * 2.2;
        return 53.5 - groove1 - groove2;
      },
      (y) => {
        let d1 = ((y - 466) / 3.5) * exp(-pow((y - 466) / 3.5, 2)) * 0.45;
        let d2 = ((y - 514) / 3.5) * exp(-pow((y - 514) / 3.5, 2)) * 0.45;
        return constrain(d1 + d2, -0.75, 0.75);
      },
      ey,
      3.0,
      seed + 30,
      2.1
    );

    // 7. Center Casing Two-Piece Ferrule Ring (y = 544..558)
    hatchVerticalLathe(
      xc,
      544,
      558,
      (y) => 56.5 + 1.2 * sin(map(y, 544, 558, 0, 180)),
      (y) => -0.45 * cos(map(y, 544, 558, 0, 180)),
      ey,
      2.95,
      seed + 35,
      1.5
    );

    // 8. Lower Monel / Brass Valve Casing Cylinder (y = 558..818)
    hatchVerticalLathe(
      xc,
      558,
      818,
      (y) => {
        let ring = exp(-pow((y - 758) / 3.5, 2)) * 2.0;
        return 53.5 + ring;
      },
      (y) => {
        let dr = -((y - 758) / 3.5) * exp(-pow((y - 758) / 3.5, 2)) * 0.45;
        return constrain(dr, -0.7, 0.7);
      },
      ey,
      3.0,
      seed + 40,
      2.1
    );

    // 9. Bottom Valve Cap: Knurled Upper Band (y = 818..840) + Step + Lower Cup (y = 840..880)
    renderKnurledBand(xc, 818, 840, 57.5, ey, 42, false, 2.9, seed + 50);
    hatchVerticalLathe(
      xc,
      840,
      880,
      (y) => {
        if (y < 848) return map(y, 840, 848, 57.5, 44.0);
        if (y < 873) return 44.0;
        return map(y, 873, 880, 44.0, 12.0);
      },
      (y) => (y < 848 ? 0.65 : y > 873 ? 0.72 : 0.05),
      ey,
      2.9,
      seed + 55,
      1.7
    );
  }
}

