// 5. BRAZED SOLDER SEAMS & MENISCUS FILLETS (GEL PEN & FINE WHITE PENCIL)
// ===========================================================================
function renderAllSolderSeams() {
  // Helper to draw an elliptical or saddle solder fillet with double-rim meniscus highlights & bead texture
  function drawSolderEllipse(cx, cy, rx, ry, aStart, aEnd, myZ) {
    for (let a = aStart; a <= aEnd; a += 5) {
      let x1 = cx + rx * cos(a);
      let y1 = cy + ry * sin(a);
      let x2 = cx + rx * cos(a + 5);
      let y2 = cy + ry * sin(a + 5);
      if (isOccluded(x1, y1, myZ)) continue;

      let bead = 0.5 + 0.5 * sin(a * 9 + cx);
      let lum = 0.48 + 0.45 * cos(a - 35) + 0.18 * bead;

      if (lum > 0.35) {
        // Outer soft white pencil fillet halo
        brush.set("white_pencil", "#f2e8d5", 0.34);
        brush.line(x1, y1, x2, y2);

        // Inner bright white gel-pen meniscus bead
        if (lum > 0.65) {
          brush.set("gelpen", "#ffffff", 0.46);
          let nx = cos(a) * 1.6;
          let ny = sin(a) * 1.6;
          brush.line(x1 + nx, y1 + ny, x2 + nx, y2 + ny);
        }
      }
    }
  }

  // Helper to draw vertical ring solder seams around horizontal tubes & ferrules
  function drawVerticalSolderRing(x, yc, r, myZ) {
    for (let k = -10; k <= 10; k++) {
      let v1 = k / 10;
      let v2 = (k + 1) / 10;
      if (abs(v2) > 1) continue;
      let y1 = yc + v1 * r;
      let y2 = yc + v2 * r;
      let dx1 = 0.22 * r * sqrt(max(0, 1 - v1 * v1));
      let dx2 = 0.22 * r * sqrt(max(0, 1 - v2 * v2));
      if (isOccluded(x + dx1, y1, myZ)) continue;

      let lum = 0.5 + 0.45 * cos(v1 * 90 + 25);
      brush.set(lum > 0.68 ? "gelpen" : "white_pencil", lum > 0.68 ? "#ffffff" : "#f7eedb", lum > 0.68 ? 0.45 : 0.32);
      brush.line(x + dx1, y1, x + dx2, y2);
      if (lum > 0.72) {
        brush.line(x + dx1 + 1.8, y1, x + dx2 + 1.8, y2);
      }
    }
  }

  // 1. Leadpipe saddle mounts on Valve 1 (x = 445, y = 478) & Valve 3 (x = 755, y = 478)
  drawSolderEllipse(445, 478, 28, 16.5, 0, 360, 0.9);
  drawSolderEllipse(755, 478, 28, 17.8, 0, 360, 0.9);

  // 2. Main Tuning Slide 3rd-Valve Entry Knuckle Flange at (755, 665)
  drawSolderEllipse(755, 665, 26, 22, 0, 360, 1.1);

  // 3. 2nd Valve Short Slide Knuckle Flanges at (610, 584) & (610, 652)
  drawSolderEllipse(610, 584, 14, 17, -110, 110, 1.4);
  drawSolderEllipse(610, 652, 14, 17, -110, 110, 1.4);

  // 4. Inter-Valve Knuckle Port Solder Seams on Casings 1, 2, 3
  let knucklePorts = [
    [490, 542], [555, 542],
    [490, 629], [555, 642],
    [645, 553], [710, 539],
    [645, 695], [710, 695],
    [400, 568], [400, 702],
    [795, 578], [790, 746]
  ];
  for (let kp of knucklePorts) {
    drawVerticalSolderRing(kp[0], kp[1], 17.5, 2.0);
  }

  // 5. Ferrule Solder Seams across all slides & receiver
  let ferruleSeams = [
    [184, 478, 20], [258, 478, 19.5],
    [868, 478, 20.8], [908, 478, 20.8],
    [868, 665, 20.8], [908, 665, 20.8],
    [304, 568, 19.2], [338, 568, 19.2],
    [304, 702, 19.2], [338, 702, 19.2],
    [845, 578, 18.5], [876, 578, 18.5],
    [845, 746, 19.0], [876, 746, 19.0],
    [632, 584, 18.2], [648, 584, 18.2],
    [632, 652, 18.2], [648, 652, 18.2],
    [418, 335, 24.8], [452, 335, 24.8]
  ];
  for (let fs of ferruleSeams) {
    drawVerticalSolderRing(fs[0], fs[1], fs[2], 0.9);
  }

  // 6. Horizontal Two-Piece Casing Solder Seams on Valves 1, 2, 3 (y = 544 & y = 558)
  for (let xc of [445, 600, 755]) {
    drawSolderEllipse(xc, 544, 56.5, 56.5 * 0.19, 0, 180, 2.8);
    drawSolderEllipse(xc, 558, 56.5, 56.5 * 0.19, 0, 180, 2.8);
