function drawDashDotLine(x1, y1, x2, y2, dashLen = 22, gapLen = 7) {
  let d = dist(x1, y1, x2, y2);
  if (d < 1) return;
  let ux = (x2 - x1) / d;
  let uy = (y2 - y1) / d;
  let s = 0;
  while (s < d) {
    let e1 = min(d, s + dashLen);
    brush.line(x1 + ux * s, y1 + uy * s, x1 + ux * e1, y1 + uy * e1);
    s = e1 + gapLen;
    if (s + 2.5 < d) {
      brush.line(x1 + ux * s, y1 + uy * s, x1 + ux * (s + 2.5), y1 + uy * (s + 2.5));
    }
    s += 2.5 + gapLen;
  }
}

