function drawDimArrow(x, y, dirAngle, size = 7) {
  let a1 = dirAngle + 158;
  let a2 = dirAngle - 158;
  brush.line(x, y, x + size * cos(a1), y + size * sin(a1));
  brush.line(x, y, x + size * cos(a2), y + size * sin(a2));
}

function drawDimLineH(x1, x2, y, extY1, extY2, label) {
  brush.set("rotring", "#a9d4f0", 0.30);
  // Extension lines with small gap
  let dir1 = y < extY1 ? -1 : 1;
  let dir2 = y < extY2 ? -1 : 1;
  brush.line(x1, extY1 + dir1 * 6, x1, y + dir1 * 8);
  brush.line(x2, extY2 + dir2 * 6, x2, y + dir2 * 8);

  // Dimension line & architectural 45-degree ticks + arrowheads
  brush.set("gelpen", "#eaf5fc", 0.36);
  brush.line(x1, y, x2, y);
  drawDimArrow(x1, y, 0, 6.5);
  drawDimArrow(x2, y, 180, 6.5);
  // 45° architectural tick marks at datum intersections
  brush.line(x1 - 4.5, y + 4.5, x1 + 4.5, y - 4.5);
  brush.line(x2 - 4.5, y + 4.5, x2 + 4.5, y - 4.5);

  if (label) {
    let tw = label.length * 7.8;
    let tx = 0.5 * (x1 + x2) - 0.5 * tw;
    drawTechText(label, tx, y - 13, 8.5);
  }
}

function drawDimLineV(x, y1, y2, extX1, extX2, label) {
  brush.set("rotring", "#a9d4f0", 0.30);
  let dir1 = x < extX1 ? -1 : 1;
  let dir2 = x < extX2 ? -1 : 1;
  brush.line(extX1 + dir1 * 6, y1, x + dir1 * 8, y1);
  brush.line(extX2 + dir2 * 6, y2, x + dir2 * 8, y2);

  brush.set("gelpen", "#eaf5fc", 0.36);
  brush.line(x, y1, x, y2);
  drawDimArrow(x, y1, 90, 6.5);
  drawDimArrow(x, y2, -90, 6.5);
  brush.line(x - 4.5, y1 + 4.5, x + 4.5, y1 - 4.5);
  brush.line(x - 4.5, y2 + 4.5, x + 4.5, y2 - 4.5);

  if (label) {
    let my = 0.5 * (y1 + y2) - 4;
    let tx = x < 600 ? x + 8 : x - label.length * 8 - 8;
    drawTechText(label, tx, my, 8.2);
  }
}

function drawLeaderCallout(px, py, kx, ky, ex, label1, label2 = "") {
  brush.set("gelpen", "#f0f8ff", 0.36);
  let ang = atan2(ky - py, kx - px);
  drawDimArrow(px, py, ang, 7.5);
  brush.line(px, py, kx, ky);
  brush.line(kx, ky, ex, ky);

  let textX = ex > kx ? kx + 8 : ex + 4;
  drawTechText(label1, textX, ky - 12, 8.2);
  if (label2) {
    brush.set("rotring", "#b4daf2", 0.30);
    drawTechText(label2, textX, ky + 4, 7.2);
  }
}

