// Slight organic tilt and warp of the woven cotton cloth
function clothPt(u, v) {
  let cx = 600, cy = 600;
  let ang = -2.3 * (Math.PI / 180);
  let du = u - cx;
  let dv = v - cy;
  let rx = cx + du * Math.cos(ang) - dv * Math.sin(ang);
  let ry = cy + du * Math.sin(ang) + dv * Math.cos(ang);
  // Subtle fabric undulation
  let waveX = (noise(u * 0.003, v * 0.003) - 0.5) * 14;
  let waveY = (noise(u * 0.003 + 50, v * 0.003 + 50) - 0.5) * 14;
  return [rx + waveX, ry + waveY];
}

