  brush.noField();
  brush.noStroke();

  // Broad uneven ochre & tannin dye stains (batched by color for performance)
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.75, 0.35);

  brush.fill(PALETTE.ochreLight, 75);
  brush.rect(-40, -40, 1280, 360, "corner");
  brush.rect(-40, 620, 680, 620, "corner");

  brush.fill(PALETTE.ochreMid, 65);
  brush.rect(420, 220, 820, 460, "corner");
  brush.rect(380, 920, 860, 320, "corner");

  brush.fill(PALETTE.mudDry, 45);
  brush.rect(-40, 250, 520, 420, "corner");
  brush.rect(580, 580, 660, 400, "corner");

  brush.noFill();

  // Coarse strip-woven cotton warp & weft threads
  brush.wiggle(1.2);
  for (let v = -20; v <= 1220; v += 5) {
    let col = (v % 15 === 0) ? PALETTE.ochreDeep : ((v % 10 === 0) ? PALETTE.cottonWarm : PALETTE.cottonLight);
    let wt = random(0.3, 0.65);
    brush.set("2H", col, wt);
    let p1 = clothPt(-30, v);
    let p2 = clothPt(1230, v);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  for (let u = -20; u <= 1220; u += 6) {
    let col = (u % 18 === 0) ? PALETTE.mudDry : ((u % 12 === 0) ? PALETTE.ochreMid : PALETTE.cottonWarm);
    let wt = random(0.28, 0.55);
    brush.set("2H", col, wt);
    let p1 = clothPt(u, -30);
    let p2 = clothPt(u, 1230);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.noField();

  // Traditional finimugu strip seams (narrow hand-loomed strips sewn edge-to-edge)
  let seamUs = [395, 845];
  for (let su of seamUs) {
    // Seam valley shadow
    brush.set("charcoal", PALETTE.mudWarm, 1.1);
    let sTop = clothPt(su, -20);
    let sBot = clothPt(su, 1220);
    brush.line(sTop[0], sTop[1], sBot[0], sBot[1]);

    // Whip-stitched raw cotton thread marks across the seam
    for (let v = -10; v < 1210; v += 14) {
      let a = clothPt(su - 6 + random(-1, 1), v);
      let b = clothPt(su + 6 + random(-1, 1), v + 5);
      brush.set("cpencil", PALETTE.mudDeep, 0.7);
      brush.line(a[0], a[1], b[0], b[1]);
      brush.set("cpencil", PALETTE.cottonLight, 0.85);
      brush.line(a[0], a[1] - 1.5, b[0], b[1] - 1.5);
    }
  }
}

// ============================================================================
// 2. BÒGÒLANFINI HAND-RULED PANELS & RESIST MOTIFS
// ============================================================================
function clothLine(u1, v1, u2, v2, brName, col, wt) {
  let p1 = clothPt(u1, v1);
  let p2 = clothPt(u2, v2);
  brush.set(brName, col, wt);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

function clothSpline(uvPts, brName, col, wt, curv = 0.3) {
  let pts = uvPts.map(pt => {
    let p = clothPt(pt[0], pt[1]);
    return pt.length > 2 ? [p[0], p[1], pt[2]] : [p[0], p[1]];
  });
  brush.set(brName, col, wt);
  brush.spline(pts, curv);
}

// Draws a dark mud-filled rectangle with coarse hand-painted strokes, leaving resist shapes open
function fillMudBand(u1, v1, u2, v2, col = PALETTE.mudDeep, step = 4.5) {
  for (let v = v1; v <= v2; v += step) {
    let jit1 = random(-2, 2);
    let jit2 = random(-2, 2);
    let c = random() < 0.3 ? PALETTE.mudDarkest : (random() < 0.7 ? col : PALETTE.mudMid);
    clothLine(u1 + jit1, v + random(-1, 1), u2 + jit2, v + random(-1, 1), "mud_paste", c, random(0.9, 1.35));
  }
}

// Hand-painted resist dot on mud ground (pale ochre/cotton center with crusty dark mud rim)
function drawResistDot(u, v, rad, isBright = false) {
  let p = clothPt(u, v);
  let cx = p[0], cy = p[1];

  // Dark mud ring pooled around the resist wax/paste spot
  brush.set("mud_paste", PALETTE.mudDarkest, random(0.8, 1.2));
  brush.circle(cx, cy, rad + 2.5, 0.35);

  // Resist cotton interior (filled with radial/hatched dry strokes so it has woven texture)
  let baseCol = isBright ? PALETTE.cottonLight : PALETTE.cottonWarm;
  let ochreCol = isBright ? PALETTE.cottonBase : PALETTE.ochreLight;
  for (let dy = -rad + 1.5; dy <= rad - 1.5; dy += 2.6) {
    let halfW = Math.sqrt(Math.max(0, rad * rad - dy * dy)) * 0.92;
    brush.set("cpencil", random() < 0.5 ? baseCol : ochreCol, random(0.95, 1.35));
    brush.line(cx - halfW + random(-1, 1), cy + dy, cx + halfW + random(-1, 1), cy + dy + random(-0.8, 0.8));
  }

  // Tiny dark center pinpoint often seen in bògòlanfini resist dots
  if (rad > 7.5 && random() < 0.65) {
    brush.set("mud_paste", PALETTE.mudDeep, 0.65);
    brush.circle(cx + random(-1, 1), cy + random(-1, 1), 1.6, 0.2);
  }
}

function drawBogolanPanels() {
  // Horizontal structural divider bands
  let hBands = [-10, 255, 635, 965, 1215];

  for (let b of hBands) {
    fillMudBand(-30, b - 14, 1230, b + 14, PALETTE.mudDarkest, 4);
    // Double hand-ruled resist lines inside the border band
    clothLine(-30, b - 6, 1230, b - 6, "cpencil", PALETTE.cottonWarm, 1.35);
    clothLine(-30, b - 5, 1230, b - 5, "cpencil", PALETTE.ochreLight, 1.1);
    clothLine(-30, b + 6, 1230, b + 6, "cpencil", PALETTE.cottonWarm, 1.35);
    clothLine(-30, b + 7, 1230, b + 7, "cpencil", PALETTE.ochreLight, 1.1);
  }

  // --------------------------------------------------------------------------
  // BAND 1 (TOP: v = 10 .. 235):Bold Chevron Frieze & Resist Dot Columns
  // --------------------------------------------------------------------------
  fillMudBand(-30, 12, 1230, 236, PALETTE.mudDeep, 4.8);

  // Vertical compartments in Band 1
  for (let u = -10; u < 1220; u += 155) {
    // Double vertical resist divider lines
