    for (let v = 24; v < 230; v += 18) {
      drawResistDot(u + 4.5, v, 3.2, true);
    }

    // Inside compartment: stacked bold chevrons in raw ochre-cotton resist
    let uStart = u + 20;
    let uEnd = u + 143;
    let uMid = (uStart + uEnd) * 0.5;
    for (let v = 32; v <= 215; v += 36) {
      for (let off = -3.5; off <= 3.5; off += 2.2) {
        let col = Math.abs(off) < 1.5 ? PALETTE.cottonLight : PALETTE.ochreLight;
        clothLine(uStart, v + 22 + off, uMid, v + off, "cpencil", col, 1.25);
        clothLine(uMid, v + off, uEnd, v + 22 + off, "cpencil", col, 1.25);
      }
      // Row of resist dots nested under each chevron peak
      drawResistDot(uMid, v + 21, 5.5, false);
      drawResistDot(uMid - 24, v + 27, 4.2, false);
      drawResistDot(uMid + 24, v + 27, 4.2, false);
    }
  }

  // --------------------------------------------------------------------------
  // BAND 2 (UPPER-MID: v = 275 .. 615):
  //   Left (u < 395): Hand-ruled Grid of Crosses (X and +) with Mud Stipple
