  clothLine(404, 270, 404, 620, "cpencil", PALETTE.cottonWarm, 1.3);

  fillMudBand(830, 270, 862, 620, PALETTE.mudDarkest, 4.5);
  clothLine(838, 270, 838, 620, "cpencil", PALETTE.cottonWarm, 1.3);
  clothLine(854, 270, 854, 620, "cpencil", PALETTE.cottonWarm, 1.3);

  // Panel 2A (Left): Grid of crosses and saltires in thick dark earth pigment on ochre cloth
  let cellW = 68, cellH = 68;
