      clothLine(u, v, u, v2, "mud_paste", PALETTE.mudDarkest, 1.15);
      clothLine(u + 4, v + 4, u2 - 4, v + 4, "mud_paste", PALETTE.mudMid, 0.7);
      clothLine(u + 4, v + 4, u + 4, v2 - 4, "mud_paste", PALETTE.mudMid, 0.7);

