        clothLine(u + k, v + 62 - k * 0.9, u + 62 - k, v + 62 - k * 0.9, "mud_paste", PALETTE.mudDeep, 0.95);
      }
      // Resist dots in left and right open triangles
      drawResistDot(u + 13, v + 31, 4.5, true);
