  fillMudBand(-30, 982, 1230, 1215, PALETTE.mudDarkest, 4.6);

  // Triple chevron wave across the top of Band 4
  for (let u = -20; u < 1220; u += 48) {
    for (let row = 0; row < 3; row++) {
