  // Row of large resist dot medallions & crosses along the lower edge
  clothLine(-30, 1062, 1230, 1062, "cpencil", PALETTE.cottonWarm, 1.3);
  clothLine(-30, 1172, 1230, 1172, "cpencil", PALETTE.cottonWarm, 1.3);
  for (let u = 25; u < 1200; u += 92) {
