// ============================================================================
// 4. HYPERREALIST GUINEAFOWL FEATHER HEAP
// ============================================================================

// Mathematical spine and local coordinate frame for a curved 3D feather
function createFeatherGeometry(cfg) {
  let N = 80;
  let spine = [];
  let radAngle = cfg.angle * Math.PI / 180;
  let cosA = Math.cos(radAngle);
  let sinA = Math.sin(radAngle);
  let nxBase = -sinA;
  let nyBase = cosA;

  for (let i = 0; i <= N; i++) {
    let t = i / N;
    // Longitudinal progression with subtle natural S-bend or C-curve
    let along = t * cfg.length;
    let bendOffset = cfg.bend * cfg.length * Math.pow(t, 1.65) + cfg.sCurve * cfg.length * Math.sin(t * Math.PI * 2);
    let x = cfg.x + cosA * along + nxBase * bendOffset;
    let y = cfg.y + sinA * along + nyBase * bendOffset;

    // 3D arch height above the cotton cloth (quill touches cloth, mid-vane arches up, tip settles down)
    let archZ = cfg.arch * Math.sin(Math.pow(t, 0.85) * Math.PI * 0.92) + cfg.baseLift * (1 - t);
    spine.push({ t, x, y, archZ });
  }

  // Compute tangents and normals along spine
  for (let i = 0; i <= N; i++) {
    let pPrev = spine[Math.max(0, i - 1)];
    let pNext = spine[Math.min(N, i + 1)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let mag = Math.hypot(dx, dy) || 1;
    spine[i].tx = dx / mag;
    spine[i].ty = dy / mag;
    spine[i].nx = -spine[i].ty;
    spine[i].ny = spine[i].tx;
  }

  function sampleSpine(t) {
    let idx = Math.max(0, Math.min(N - 0.0001, t * N));
    let i0 = Math.floor(idx);
    let f = idx - i0;
    let a = spine[i0];
    let b = spine[i0 + 1];
    return {
      t,
      x: a.x + (b.x - a.x) * f,
      y: a.y + (b.y - a.y) * f,
      archZ: a.archZ + (b.archZ - a.archZ) * f,
      tx: a.tx + (b.tx - a.tx) * f,
      ty: a.ty + (b.ty - a.ty) * f,
      nx: a.nx + (b.nx - a.nx) * f,
      ny: a.ny + (b.ny - a.ny) * f
    };
  }

  // Envelope width of the left (side = -1) and right (side = +1) feather webs
  function webWidth(t, side) {
    if (t < 0.08) return 0;
    let u = (t - 0.08) / 0.92;
    let maxW = side < 0 ? cfg.widthLeft : cfg.widthRight;
    let profile;
    if (cfg.isWingFeather) {
      // Primary/covert asymmetrical wing feather: sleeker, longer taper
      profile = Math.pow(Math.sin(Math.pow(u, 0.65) * Math.PI), 0.72);
    } else {
      // Plump, rounded-ovate guineafowl flank/back contour feather
      if (u < 0.25) {
        profile = Math.pow(u / 0.25, 0.75) * 0.88;
      } else if (u < 0.78) {
        profile = 0.88 + 0.12 * Math.sin(((u - 0.25) / 0.53) * Math.PI);
      } else {
        // Broad rounded paddle tip
        let tipU = (u - 0.78) / 0.22;
        profile = Math.sqrt(Math.max(0, 1 - tipU * tipU));
      }
    }
    // Slight organic edge ruffling
    let ruffle = 1 + (noise(t * 9 + cfg.seed, side * 5) - 0.5) * 0.08;
    return maxW * profile * ruffle;
  }

  // Barb trajectory from rachis (s = 0) to outer margin (s = 1)
  function barbPoint(t0, side, s) {
    let w = webWidth(t0, side);
    // Barb insertion angle: wider near fluffy base, tighter toward tip
    let angleDeg = 54 - 26 * Math.pow(t0, 1.1) + (side < 0 ? cfg.leftAngleBias : cfg.rightAngleBias);
    if (t0 < 0.26) {
      angleDeg += (0.26 - t0) * 140; // Fan out in the downy plumulaceous base
    }
    let angleRad = angleDeg * Math.PI / 180;
    let reachAlong = w * (1 / Math.tan(angleRad)) * 0.68;

    // Barbs curve gracefully inward near the margin so the feather contour stays cohesive
    let tCurr = Math.min(0.998, t0 + (reachAlong / cfg.length) * Math.pow(s, 0.88));
    let sp = sampleSpine(tCurr);
    let lateralDist = w * Math.pow(s, 0.92) * (1 - 0.06 * s * s);

    // 3D transverse vaulting across the vane
    let vaultY = -Math.sin(s * Math.PI) * 3.5 * (side * 0.5);
    return {
      x: sp.x + sp.nx * side * lateralDist,
      y: sp.y + sp.ny * side * lateralDist + vaultY,
      t0,
      s,
      side,
      lateralDist,
      maxW: w,
      archZ: sp.archZ * (1 - 0.25 * s),
      tx: sp.tx,
      ty: sp.ty,
      nx: sp.nx,
      ny: sp.ny
    };
  }

  // Generate authentic staggered diagonal (quincunx) rows of pearl-white spots
  let spots = [];
  let rowStepT = cfg.spotSpacing / cfg.length;
  let rowIdx = 0;
  for (let tRow = 0.27; tRow <= 0.965; tRow += rowStepT * 0.82) {
    for (let side of [-1, 1]) {
      let w = webWidth(tRow, side);
      if (w < 12) continue;
      let numCols = Math.max(1, Math.floor((w - 5) / (cfg.spotSpacing * 0.88)));
      for (let col = 0; col < numCols; col++) {
        let stagger = ((rowIdx + (side > 0 ? 1 : 0)) % 2) * 0.48;
        let sNorm = ((col + 0.55 + stagger) * cfg.spotSpacing * 0.86) / w;
        if (sNorm < 0.14 || sNorm > 0.93) continue;

        let tSpot = tRow + (sNorm * 0.045) + (noise(col * 3.1, rowIdx * 2.7, cfg.seed) - 0.5) * 0.014;
        if (tSpot > 0.965) continue;

        let pt = barbPoint(tSpot - sNorm * 0.03, side, sNorm);
        // Spot radius is smaller near shaft and tip, fuller in mid-web
        let sizeFactor = Math.sin(Math.min(1, (tSpot - 0.24) / 0.72) * Math.PI * 0.85 + 0.15);
        let webFactor = 0.72 + 0.35 * Math.sin(sNorm * Math.PI);
        let rMajor = cfg.spotRadius * sizeFactor * webFactor * random(0.88, 1.12);
        let rMinor = rMajor * random(0.76, 0.92);

        // Local barb direction at spot for slight elliptical elongation
        let pt2 = barbPoint(tSpot - sNorm * 0.03, side, Math.min(1, sNorm + 0.08));
        let bAng = Math.atan2(pt2.y - pt.y, pt2.x - pt.x);

        spots.push({
          x: pt.x,
          y: pt.y,
          t: tSpot,
          s: sNorm,
          side,
          rMajor,
          rMinor,
          cosB: Math.cos(bAng),
          sinB: Math.sin(bAng),
          bAngDeg: bAng * 180 / Math.PI,
          isBarred: (tSpot < 0.36 && sNorm > 0.55 && cfg.hasBasalBars),
          brightness: cfg.brightness * (0.82 + 0.18 * Math.sin(tSpot * Math.PI)) * (side < 0 ? 1.04 : 0.92)
        });
      }
    }
    rowIdx++;
  }

  return { cfg, spine, sampleSpine, webWidth, barbPoint, spots };
}

// Fast spatial query to see if a point (x, y) on a barb falls inside any pearl spot or its dark melanin halo
function queryPearlSpot(spots, x, y, side) {
  for (let i = 0; i < spots.length; i++) {
    let sp = spots[i];
    if (sp.side !== side) continue;
    let dx = x - sp.x;
    let dy = y - sp.y;
    // Quick bounding box reject
    let bound = sp.rMajor + 4.5;
    if (dx > bound || dx < -bound || dy > bound || dy < -bound) continue;

    let lx = dx * sp.cosB + dy * sp.sinB;
    let ly = -dx * sp.sinB + dy * sp.cosB;
    let dNormSq = (lx * lx) / (sp.rMajor * sp.rMajor) + (ly * ly) / (sp.rMinor * sp.rMinor);

    if (dNormSq <= 1.0) {
      return { state: "inside", spot: sp, dNorm: Math.sqrt(dNormSq), lx, ly };
    } else if (dNormSq <= 1.55) {
      return { state: "halo", spot: sp, dNorm: Math.sqrt(dNormSq) };
    }
  }
  return null;
}

// Renders a single guineafowl feather with extreme hyperreal detail
function renderFeather(fg) {
  let { cfg, sampleSpine, webWidth, barbPoint, spots } = fg;

  // --------------------------------------------------------------------------
  // STEP A: MULTI-LAYER CAST SHADOW ON THE BÒGÒLANFINI CLOTH
  // --------------------------------------------------------------------------
  // Soft watercolor penumbra + directional charcoal contact shadow
  let shadowPoly = [];
  for (let t = 0.08; t <= 0.98; t += 0.045) {
    let pt = barbPoint(t, -1, 0.96);
    shadowPoly.push([pt.x + pt.archZ * 0.72 + 4, pt.y + pt.archZ * 0.95 + 6]);
  }
  for (let t = 0.98; t >= 0.08; t -= 0.045) {
    let pt = barbPoint(t, 1, 0.96);
    shadowPoly.push([pt.x + pt.archZ * 0.72 + 4, pt.y + pt.archZ * 0.95 + 6]);
  }

  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.25);
  brush.fill(PALETTE.mudDarkest, 92);
  brush.beginShape(0.35);
  for (let pt of shadowPoly) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noFill();

  // Tight charcoal shadow strokes under the quill and lower edge
  for (let t = 0.02; t <= 0.96; t += 0.016) {
    let sp = sampleSpine(t);
    let shX = sp.x + sp.archZ * 0.55 + 3;
    let shY = sp.y + sp.archZ * 0.75 + 4;
    let wR = webWidth(t, 1) * 0.92;
    let wL = webWidth(t, -1) * 0.75;
    brush.set("charcoal", PALETTE.charcoalBlack, random(0.8, 1.35));
    brush.line(
      shX - sp.nx * wL, shY - sp.ny * wL,
      shX + sp.nx * wR, shY + sp.ny * wR
    );
  }

  // --------------------------------------------------------------------------
  // STEP B: OPAQUE VANE UNDERCOAT (BLOCKS OUT MUD CLOTH BEHIND THE FEATHER)
  // --------------------------------------------------------------------------
  // Choose occasional natural zipper-splits in the barbs so the vane looks organic
  let splitsLeft = cfg.splitsLeft || [0.48, 0.77];
  let splitsRight = cfg.splitsRight || [0.39, 0.68, 0.85];

  function isInSplit(t0, side) {
    let arr = side < 0 ? splitsLeft : splitsRight;
    for (let st of arr) {
      if (Math.abs(t0 - st) < 0.011) return true;
    }
    return false;
  }

  // Dense charcoal foundation along the vane (t = 0.22 .. 0.99)
  for (let side of [-1, 1]) {
    for (let t0 = 0.21; t0 <= 0.985; t0 += 0.0055) {
      if (isInSplit(t0, side)) continue;
      let p0 = barbPoint(t0, side, 0.02);
      let p1 = barbPoint(t0, side, 0.48);
      let p2 = barbPoint(t0, side, 0.95);
      let baseCol = (side < 0 && cfg.brightness > 0.9) ? PALETTE.charcoalDeep : PALETTE.charcoalBlack;
      clothSplineRaw([
        [p0.x, p0.y, 1.0],
        [p1.x, p1.y, 0.95],
        [p2.x, p2.y, 0.35]
      ], "barb_velvet", baseCol, 1.35, 0.3);
    }
  }

  // --------------------------------------------------------------------------
  // STEP C: DOWNY PLUMULACEOUS BASE & IRIDESCENT BLUE-GREY QUILL ACCENT
  // --------------------------------------------------------------------------
  // Gossamer smoky-grey and iridescent slate-blue downy filaments at the base (t = 0.07 .. 0.33)
  for (let side of [-1, 1]) {
    for (let t0 = 0.075; t0 <= 0.34; t0 += 0.0038) {
      let sp = sampleSpine(t0);
      let downProgress = (t0 - 0.075) / 0.265;
      let len = (22 + 58 * Math.sin(downProgress * Math.PI)) * random(0.65, 1.28);
      let baseAng = Math.atan2(sp.ty, sp.tx) + side * (0.48 + (1 - downProgress) * 0.65) + random(-0.18, 0.18);

      let curl1 = baseAng + side * random(-0.28, 0.35);
      let curl2 = curl1 + side * random(-0.45, 0.45);

      let x0 = sp.x + sp.nx * side * 1.2;
      let y0 = sp.y + sp.ny * side * 1.2;
      let x1 = x0 + Math.cos( baseAng ) * (len * 0.42);
      let y1 = y0 + Math.sin( baseAng ) * (len * 0.42);
      let x2 = x1 + Math.cos( curl1 ) * (len * 0.36);
      let y2 = y1 + Math.sin( curl1 ) * (len * 0.36);
      let x3 = x2 + Math.cos( curl2 ) * (len * 0.28);
      let y3 = y2 + Math.sin( curl2 ) * (len * 0.28);

      // Select between smoky down-grey, charcoal, and the ONE accent: iridescent slate blue-grey
      let col;
      let rVal = random();
      if (t0 > 0.14 && rVal < 0.58) {
        // Iridescent blue-grey quill base sheen!
        if (side < 0 && random() < 0.45) {
          col = PALETTE.slateGlow;
        } else {
          col = random() < 0.55 ? PALETTE.slateBright : PALETTE.slateMid;
        }
      } else if (rVal < 0.82) {
        col = random() < 0.5 ? PALETTE.downGrey : PALETTE.graphiteMid;
      } else {
        col = random() < 0.6 ? PALETTE.downLight : PALETTE.slatePale;
      }

      clothSplineRaw([
        [x0, y0, 0.4],
        [x1, y1, 0.95],
        [x2, y2, 0.65],
        [x3, y3, 0.1]
      ], "down_wisp", col, random(0.75, 1.25), 0.45);
    }
  }

  // --------------------------------------------------------------------------
  // STEP D: INDIVIDUAL HYPERREAL BARBS & INTEGRATED PEARL-WHITE SPOTS
  // --------------------------------------------------------------------------
  // Each barb is traced from the rachis to the margin, changing pigment as it crosses
  // the iridescent blue-grey base zone, dark charcoal vane, melanin spot halo, and pearl-white spot!
  let barbStep = 0.0042;
  for (let side of [-1, 1]) {
    for (let t0 = 0.22; t0 <= 0.992; t0 += barbStep) {
      if (isInSplit(t0, side)) continue;

      let pStart = barbPoint(t0, side, 0.015);
      let pMid1  = barbPoint(t0, side, 0.33);
      let pMid2  = barbPoint(t0, side, 0.66);
      let pEnd   = barbPoint(t0, side, 0.99 + random(-0.02, 0.025));

      // 1. Continuous dark barb backbone
      let vaneCol;
      if (t0 < 0.36 && random() < 0.65) {
        // Iridescent slate-blue transition at the base of the coherent vane
        vaneCol = (side < 0) ? PALETTE.slateMid : PALETTE.slateDeep;
      } else {
        // Subtle 3D sheen across the curved matte charcoal vane
        let sheenZone = Math.sin(t0 * Math.PI * 1.3 + cfg.seed);
        if (side < 0 && sheenZone > 0.25 && random() < 0.45) {
          vaneCol = random() < 0.5 ? PALETTE.graphiteDark : PALETTE.charcoalWarm;
        } else {
          vaneCol = random() < 0.6 ? PALETTE.charcoalBlack : PALETTE.charcoalDeep;
        }
      }

      clothSplineRaw([
        [pStart.x, pStart.y, 1.0],
        [pMid1.x, pMid1.y, 0.85],
        [pMid2.x, pMid2.y, 0.65],
        [pEnd.x, pEnd.y, 0.15]
      ], "barb_silk", vaneCol, random(0.85, 1.2), 0.3);

      // 2. Iridescent blue-grey barbule glint near the quill base and inner web (t = 0.20 .. 0.44)
      if (t0 < 0.45) {
        let iridReach = map(t0, 0.22, 0.45, 0.78, 0.22);
        let pI0 = barbPoint(t0, side, 0.04);
        let pI1 = barbPoint(t0, side, iridReach * random(0.75, 1.15));
        let iridCol = (side < 0 && random() < 0.5) ? PALETTE.slateGlow : (random() < 0.6 ? PALETTE.slateBright : PALETTE.slateMid);
        brush.set("barb_silk", iridCol, random(0.65, 1.05));
        brush.line(pI0.x, pI0.y, pI1.x, pI1.y);
      }

      // 3. Sample along the barb to render integrated pearl-white segments & dark melanin halos
      let segSamples = 14;
      for (let k = 1; k < segSamples; k++) {
        let sA = k / segSamples;
        let sB = (k + 0.95) / segSamples;
        let ptA = barbPoint(t0, side, sA);
        let hit = queryPearlSpot(spots, ptA.x, ptA.y, side);
        if (!hit) continue;

        let ptB = barbPoint(t0, side, sB);
        if (hit.state === "halo") {
          // Crisp pitch-black melanin ring framing each white pearl
          brush.set("barb_silk", PALETTE.charcoalBlack, 1.25);
          brush.line(ptA.x, ptA.y, ptB.x, ptB.y);
        } else if (hit.state === "inside") {
          // Barb segment turns luminous pearl-white!
          let sp = hit.spot;
          let pCol;
          if (sp.isBarred) {
            pCol = random() < 0.5 ? PALETTE.slatePale : PALETTE.pearlShadow;
          } else if (hit.ly > sp.rMinor * 0.35 || sp.brightness < 0.8) {
            pCol = PALETTE.pearlShadow;
          } else if (hit.lx < 0 && hit.ly < 0 && sp.brightness > 0.92) {
            pCol = PALETTE.pearlPure;
          } else {
            pCol = random() < 0.6 ? PALETTE.pearlBright : PALETTE.pearlCream;
          }
          brush.set("pearl_chalk", pCol, random(0.85, 1.25));
          brush.line(ptA.x, ptA.y, ptB.x, ptB.y);
        }
      }
    }
  }

  // --------------------------------------------------------------------------
  // STEP E: HYPERREAL PEARL SPOT MICRO-FILAMENTS & LIGHT CATCHING
  // --------------------------------------------------------------------------
  // Reinforces each pearl spot so it gleams against the matte charcoal & echoes the mud-cloth dots
  for (let sp of spots) {
    // 1. Dark melanin surround micro-ticks
    let numTicks = 10;
    for (let i = 0; i < numTicks; i++) {
      let a = (i / numTicks) * Math.PI * 2 + random(-0.15, 0.15);
      let ca = Math.cos(a), sa = Math.sin(a);
      let rx0 = ca * sp.rMajor * 0.95;
      let ry0 = sa * sp.rMinor * 0.95;
      let rx1 = ca * sp.rMajor * 1.22;
      let ry1 = sa * sp.rMinor * 1.22;
      let x0 = sp.x + rx0 * sp.cosB - ry0 * sp.sinB;
      let y0 = sp.y + rx0 * sp.sinB + ry0 * sp.cosB;
      let x1 = sp.x + rx1 * sp.cosB - ry1 * sp.sinB;
      let y1 = sp.y + rx1 * sp.sinB + ry1 * sp.cosB;
      brush.set("barb_silk", PALETTE.charcoalBlack, 0.85);
      brush.line(x0, y0, x1, y1);
    }

    // 2. Dense barb-aligned pearl filaments inside the spot
    let stepY = 1.35;
    for (let ly = -sp.rMinor * 0.88; ly <= sp.rMinor * 0.88; ly += stepY) {
      let fracY = ly / sp.rMinor;
      let halfLx = sp.rMajor * Math.sqrt(Math.max(0, 1 - fracY * fracY)) * random(0.88, 1.06);

      let x0 = sp.x + (-halfLx) * sp.cosB - ly * sp.sinB;
      let y0 = sp.y + (-halfLx) * sp.sinB + ly * sp.cosB;
      let x1 = sp.x + (halfLx) * sp.cosB - ly * sp.sinB;
      let y1 = sp.y + (halfLx) * sp.sinB + ly * sp.cosB;

      // Shaded lower edge vs glowing upper-left crown of the pearl
      let col;
      if (sp.isBarred) {
        col = fracY > 0.2 ? PALETTE.slateMid : PALETTE.slatePale;
      } else if (fracY > 0.38) {
        col = sp.brightness < 0.82 ? PALETTE.pearlDeepShadow : PALETTE.pearlShadow;
      } else if (fracY < -0.15 && sp.brightness > 0.88) {
        col = PALETTE.pearlPure;
      } else {
        col = sp.brightness > 0.85 ? PALETTE.pearlBright : PALETTE.pearlCream;
      }

      brush.set("pearl_chalk", col, random(0.75, 1.1));
      brush.line(x0, y0, x1, y1);
    }

    // 3. Crisp specular barbule glint on light-catching pearls
    if (!sp.isBarred && sp.brightness > 0.84) {
      let gx0 = sp.x + (-sp.rMajor * 0.55) * sp.cosB - (-sp.rMinor * 0.22) * sp.sinB;
      let gy0 = sp.y + (-sp.rMajor * 0.55) * sp.sinB + (-sp.rMinor * 0.22) * sp.cosB;
      let gx1 = sp.x + (sp.rMajor * 0.45) * sp.cosB - (-sp.rMinor * 0.22) * sp.sinB;
      let gy1 = sp.y + (sp.rMajor * 0.45) * sp.sinB + (-sp.rMinor * 0.22) * sp.cosB;
      brush.set("rachis_gloss", PALETTE.pearlPure, 0.9);
      brush.line(gx0, gy0, gx1, gy1);
    }
  }

  // --------------------------------------------------------------------------
  // STEP F: THE RACHIS & CALAMUS — "THE ONLY SHEEN IS ON THE RACHIS"
  // --------------------------------------------------------------------------
  // Rendered as a tapered, smooth, glossy keratin cylinder catching a sharp specular highlight
  let rachisSegs = 45;
  for (let i = 0; i < rachisSegs; i++) {
    let tA = i / rachisSegs;
    let tB = (i + 1) / rachisSegs;
    let spA = sampleSpine(tA);
    let spB = sampleSpine(tB);

    // Taper from thick hollow calamus barrel (3.6px) to hair-thin tip (0.25px)
    let halfW = 3.4 * Math.pow(1 - tA * 0.94, 1.35);

    // 1. Deep shadow underside of the cylindrical shaft (lower-right normal)
    brush.set("barb_silk", PALETTE.charcoalBlack, Math.max(0.4, halfW * 0.7));
    brush.line(
      spA.x + spA.nx * halfW * 0.85, spA.y + spA.ny * halfW * 0.85,
      spB.x + spB.nx * halfW * 0.85, spB.y + spB.ny * halfW * 0.85
    );

    // 2. Core keratin body (translucent slate-ivory at calamus base, dark horn/slate along vane)
    let coreCol;
    if (tA < 0.14) {
      coreCol = PALETTE.pearlShadow;
    } else if (tA < 0.34) {
      coreCol = PALETTE.slateBright;
    } else {
      coreCol = PALETTE.graphiteDark;
    }
    brush.set("pearl_chalk", coreCol, Math.max(0.35, halfW * 0.85));
    brush.line(spA.x, spA.y, spB.x, spB.y);

    // 3. Central longitudinal groove shadow (characteristic of feather shafts)
    if (tA > 0.08 && tA < 0.82) {
      brush.set("2H", PALETTE.charcoalDeep, 0.45);
      brush.line(
        spA.x + spA.nx * halfW * 0.18, spA.y + spA.ny * halfW * 0.18,
        spB.x + spB.nx * halfW * 0.18, spB.y + spB.ny * halfW * 0.18
      );
    }

    // 4. Razor-sharp glossy specular sheen along the upper-left ridge of the rachis!
    let sheenIntensity = Math.sin(Math.pow(tA, 0.75) * Math.PI);
    if (sheenIntensity > 0.08) {
      let glintCol = (tA > 0.15 && tA < 0.42) ? PALETTE.slatePale : PALETTE.pearlPure;
      let glintW = Math.max(0.35, halfW * 0.52 * sheenIntensity * cfg.brightness);
      brush.set("rachis_gloss", glintCol, glintW);
      brush.line(
        spA.x - spA.nx * halfW * 0.42, spA.y - spA.ny * halfW * 0.42,
        spB.x - spB.nx * halfW * 0.42, spB.y - spB.ny * halfW * 0.42
      );

      // Extra hot-spot gleam on the highest arch of the rachis
      if (tA > 0.22 && tA < 0.72) {
        brush.set("rachis_gloss", PALETTE.pearlPure, glintW * 0.75);
        brush.line(
          spA.x - spA.nx * halfW * 0.35, spA.y - spA.ny * halfW * 0.35,
          spB.x - spB.nx * halfW * 0.35, spB.y - spB.ny * halfW * 0.35
        );
      }
    }
  }

  // Tiny pointed calamus tip (umbilicus inferior) where quill narrows at t = 0
  let sp0 = sampleSpine(0);
  let spTip = { x: sp0.x - sp0.tx * 9, y: sp0.y - sp0.ty * 9 };
  brush.set("pearl_chalk", PALETTE.pearlCream, 0.9);
  brush.line(spTip.x, spTip.y, sp0.x, sp0.y);
  brush.set("rachis_gloss", PALETTE.pearlPure, 0.65);
  brush.line(spTip.x, spTip.y, sp0.x - sp0.nx * 1.2, sp0.y - sp0.ny * 1.2);
}

function clothSplineRaw(pts, brName, col, wt, curv = 0.3) {
  brush.set(brName, col, wt);
  brush.spline(pts, curv);
}

// Small detached downy plumule / afterfeather tuft drifted onto the cotton cloth
function drawLooseDownTuft(x, y, angleDeg, scaleSz) {
  let rad = angleDeg * Math.PI / 180;
  let tx = Math.cos(rad), ty = Math.sin(rad);
  let nx = -ty, ny = tx;

  // Soft shadow on cloth
  brush.set("charcoal", PALETTE.mudDarkest, 1.1);
  brush.line(x + 4, y + 6, x + tx * 45 * scaleSz + 4, y + ty * 45 * scaleSz + 6);

  // Silky radiating slate-blue and smoky-grey plumules
  for (let i = 0; i < 48; i++) {
    let t = (i / 48);
    let side = (i % 2 === 0) ? -1 : 1;
    let bx = x + tx * (t * 48 * scaleSz);
    let by = y + ty * (t * 48 * scaleSz);
    let bAng = rad + side * (0.45 + (1 - t) * 0.55) + random(-0.25, 0.25);
    let bLen = (18 + 28 * Math.sin(t * Math.PI)) * scaleSz * random(0.7, 1.3);

    let x1 = bx + Math.cos(bAng) * bLen * 0.5;
    let y1 = by + Math.sin(bAng) * bLen * 0.5;
    let x2 = x1 + Math.cos(bAng + side * random(-0.35, 0.45)) * bLen * 0.55;
    let y2 = y1 + Math.sin(bAng + side * random(-0.35, 0.45)) * bLen * 0.55;

    let col = random() < 0.48 ? PALETTE.slateBright : (random() < 0.6 ? PALETTE.downLight : PALETTE.slateMid);
    clothSplineRaw([[bx, by, 0.5], [x1, y1, 0.9], [x2, y2, 0.1]], "down_wisp", col, 0.85, 0.45);
  }

  // Tiny gleaming stem
  brush.set("rachis_gloss", PALETTE.pearlPure, 0.55);
  brush.line(x, y, x + tx * 42 * scaleSz, y + ty * 42 * scaleSz);
}

// ============================================================================
// 5. ASSEMBLE THE FEATHER HEAP ACROSS THE PANEL BORDERS
// ============================================================================
function drawGuineafowlHeap() {
  // Loose downy plumules drifted onto the cloth near the borders
  drawLooseDownTuft(255, 235, -28, 1.15);
  drawLooseDownTuft(895, 650, 42, 1.05);
  drawLooseDownTuft(425, 955, 145, 1.2);

  // 9 hyperreal guineafowl feathers layered from bottom of the heap to the crown.
  // Positioned so they spill dramatically across the horizontal (v = 255, 635, 965)
  // and vertical (u = 395, 520, 845) bògòlanfini panel borders!
  let featherConfigs = [
    // 1. Deep bottom-left feather spilling across the v=635 border & left cross panel
    {
      x: 470, y: 555,
      length: 390,
      angle: 148,
      bend: -0.14,
      sCurve: 0.02,
      widthLeft: 76,
      widthRight: 88,
      leftAngleBias: 2,
      rightAngleBias: -3,
      spotSpacing: 21,
      spotRadius: 6.4,
