// =============================================================================
// GEOMETRIC & POLYGON CLIPPING ENGINE (0° / 45° / 90° CONSTRAINED)
// =============================================================================

function pointInPoly(px, py, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > py) !== (yj > py)) &&
      (px < (xj - xi) * (py - yi) / ((yj - yi) || 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function clipSegmentToPoly(x1, y1, x2, y2, poly) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let tValues = [0, 1];

  for (let i = 0; i < poly.length; i++) {
    let j = (i + 1) % poly.length;
    let x3 = poly[i][0], y3 = poly[i][1];
    let x4 = poly[j][0], y4 = poly[j][1];
    let ex = x4 - x3;
    let ey = y4 - y3;
    let denom = dx * ey - dy * ex;
    if (Math.abs(denom) > 1e-7) {
      let t = ((x3 - x1) * ey - (y3 - y1) * ex) / denom;
      let u = ((x3 - x1) * dy - (y3 - y1) * dx) / denom;
      if (t >= 0 && t <= 1 && u >= -1e-5 && u <= 1 + 1e-5) {
        tValues.push(Math.max(0, Math.min(1, t)));
      }
    }
  }

  tValues.sort((a, b) => a - b);
  let segments = [];
  for (let i = 0; i < tValues.length - 1; i++) {
    let tA = tValues[i];
    let tB = tValues[i + 1];
    if (tB - tA > 1e-4) {
      let midT = 0.5 * (tA + tB);
      let mx = x1 + midT * dx;
      let my = y1 + midT * dy;
      if (pointInPoly(mx, my, poly)) {
        segments.push([
          x1 + tA * dx, y1 + tA * dy,
          x1 + tB * dx, y1 + tB * dy
        ]);
      }
    }
  }
  return segments;
}

function getPolyBounds(poly) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let p of poly) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  return { minX, minY, maxX, maxY };
}

// =============================================================================
// BRUSH & MARKER FIELD PRIMITIVES
// =============================================================================

function drawClippedLine(x1, y1, x2, y2, poly, brushName, col, weight) {
  if (!poly) {
    brush.set(brushName, col, weight);
    brush.line(x1, y1, x2, y2);
    return;
  }
  let segs = clipSegmentToPoly(x1, y1, x2, y2, poly);
  if (segs.length === 0) return;
  brush.set(brushName, col, weight);
  for (let s of segs) {
    if ( Math.hypot(s[2] - s[0], s[3] - s[1]) > 0.6 ) {
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }
}

function drawPolyContour(poly, brushName, col, weight) {
  brush.set(brushName, col, weight);
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    if (Math.hypot(b[0] - a[0], b[1] - a[1]) > 0.5) {
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

// Lay a clean Otl Aicher graphic marker field with crisp 0/45/90 directional strokes
function layMarkerField(poly, col, angleDeg = 45, spacing = 7, weight = 1.35, washAlpha = 235, brushName = "flat_marker") {
  brush.noField();
  // 1. Solid graphic wash base so the colour field has zero pinholes
  brush.noStroke();
  brush.noHatch();
  brush.wash(col, washAlpha);
  brush.beginShape(0);
  for (let p of poly) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Clean parallel marker strokes strictly at 0°, 45°, 90°, or 135°
  let b = getPolyBounds(poly);
  let rad = (angleDeg * Math.PI) / 180;
  let dx = Math.cos(rad);
  let dy = Math.sin(rad);
  let nx = -dy;
  let ny = dx;

  let cx = 0.5 * (b.minX + b.maxX);
  let cy = 0.5 * (b.minY + b.maxY);
  let diag = Math.hypot(b.maxX - b.minX, b.maxY - b.minY) * 0.6 + 10;

  brush.set(brushName, col, weight);
  for (let d = -diag; d <= diag; d += spacing) {
    let px = cx + nx * d;
    let py = cy + ny * d;
    let x1 = px - dx * diag;
    let y1 = py - dy * diag;
    let x2 = px + dx * diag;
    let y2 = py + dy * diag;
    let segs = clipSegmentToPoly(x1, y1, x2, y2, poly);
    for (let s of segs) {
      if (Math.hypot(s[2] - s[0], s[3] - s[1]) > 1.0) {
        brush.line(s[0], s[1], s[2], s[3]);
      }
    }
  }
}

// Create an octagon with strict 0°, 45°, 90° edges
function makeOctagon(cx, cy, rx, ry, chamfer) {
  let c = Math.min(chamfer, rx * 0.9, ry * 0.9);
  return [
    [cx - rx + c, cy - ry],
    [cx + rx - c, cy - ry],
    [cx + rx, cy - ry + c],
    [cx + rx, cy + ry - c],
    [cx + rx - c, cy + ry],
    [cx - rx + c, cy + ry],
    [cx - rx, cy + ry - c],
    [cx - rx, cy - ry + c]
  ];
}

// Create an oriented octagon along axis angleDeg (where angleDeg is 0, 45, 90, 135)
// Because angleDeg is a multiple of 45°, all 8 edges remain strictly 0°, 45°, 90°, or 135°!
function makeOrientedOctagon(cx, cy, halfU, halfN, chamfer, angleDeg) {
  let rad = (angleDeg * Math.PI) / 180;
  let ux = Math.cos(rad), uy = Math.sin(rad);
  let nx = -uy, ny = ux;
  let c = Math.min(chamfer, halfU * 0.85, halfN * 0.85);
  let local = [
    [-halfU + c, -halfN],
    [ halfU - c, -halfN],
    [ halfU,     -halfN + c],
    [ halfU,      halfN - c],
    [ halfU - c,  halfN],
    [-halfU + c,  halfN],
    [-halfU,      halfN - c],
    [-halfU,     -halfN + c]
  ];
  return local.map(([u, n]) => [cx + u * ux + n * nx, cy + u * uy + n * ny]);
}

function makeOrientedRect(cx, cy, u1, u2, n1, n2, angleDeg) {
  let rad = (angleDeg * Math.PI) / 180;
  let ux = Math.cos(rad), uy = Math.sin(rad);
  let nx = -uy, ny = ux;
  let local = [
    [u1, n1],
    [u2, n1],
    [u2, n2],
    [u1, n2]
  ];
  return local.map(([u, n]) => [cx + u * ux + n * nx, cy + u * uy + n * ny]);
}

// =============================================================================
// HYPERREAL WATER DROPLET RENDERER (STRICTLY CLIPPED TO PARENT COLOUR FIELD)
// =============================================================================

function drawWaterDroplet(cx, cy, r, fam, clipPoly, elongateAngle = null) {
  if (clipPoly && !pointInPoly(cx, cy, clipPoly)) return;

  // Check that droplet stays mostly within the graphic colour field so edges stay crisp
  if (clipPoly) {
    let checkR = r * 0.85;
    if (!pointInPoly(cx + checkR, cy, clipPoly) ||
        !pointInPoly(cx - checkR, cy, clipPoly) ||
        !pointInPoly(cx, cy + checkR, clipPoly) ||
        !pointInPoly(cx, cy - checkR, clipPoly)) {
      return;
    }
  }

  let rx = r;
  let ry = r;
  if (elongateAngle === 90) ry = r * 1.28;
  if (elongateAngle === 0) rx = r * 1.28;

  // 1. External lower-right cast shadow crescent (lens shadow before caustic)
  let shCx = cx + r * 0.34;
  let shCy = cy + r * 0.34;
  let shPoly = makeOctagon(shCx, shCy, rx * 0.92, ry * 0.92, r * 0.52);
  layMarkerField(shPoly, fam.darkest, 45, Math.max(2.2, r * 0.35), 0.55, 175, "detail_marker");

  // 2. Focused caustic lens glow inside the lower-right shadow crescent
  let causCx = cx + r * 0.24;
  let causCy = cy + r * 0.24;
  let causPoly = makeOctagon(causCx, causCy, rx * 0.65, ry * 0.65, r * 0.38);
  layMarkerField(causPoly, fam.caustic, 135, Math.max(2.0, r * 0.3), 0.5, 210, "detail_marker");

  // 3. Main droplet dome body (octagonal 0/45/90 micro-contour)
  let dropPoly = makeOctagon(cx, cy, rx, ry, r * 0.56);

  // Upper-left internal refraction dark crescent
  let inDarkPoly = makeOctagon(cx - r * 0.16, cy - r * 0.16, rx * 0.78, ry * 0.78, r * 0.44);
  layMarkerField(inDarkPoly, fam.dark, 45, Math.max(2.0, r * 0.32), 0.5, 195, "detail_marker");

  // Lower-right internal bright caustic belly
  let inLightPoly = makeOctagon(cx + r * 0.18, cy + r * 0.18, rx * 0.62, ry * 0.62, r * 0.35);
  layMarkerField(inLightPoly, fam.light, 45, Math.max(1.8, r * 0.28), 0.45, 190, "detail_marker");

  let inSpecGlow = makeOctagon(cx + r * 0.25, cy + r * 0.25, rx * 0.42, ry * 0.42, r * 0.24);
  layMarkerField(inSpecGlow, fam.caustic, 135, Math.max(1.6, r * 0.25), 0.4, 220, "detail_marker");

  // 4. Crisp dark upper-left meniscus rim & bright lower-right internal reflection arc
  brush.set("rotring", fam.darkest, Math.max(0.32, Math.min(0.75, r * 0.08)));
  for (let idx of [5, 6, 7, 0, 1]) {
    let a = dropPoly[idx];
    let b = dropPoly[(idx + 1) % 8];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  brush.set("rotring", fam.spec, Math.max(0.28, Math.min(0.65, r * 0.07)));
  for (let idx of [2, 3, 4]) {
    let a = dropPoly[idx];
    let b = dropPoly[(idx + 1) % 8];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // 5. Primary pinpoint pure white specular window on upper-left dome
  let spX = cx - r * 0.34;
  let spY = cy - r * 0.34;
  let spR = Math.max(1.1, r * 0.24);
  let spPoly = makeOctagon(spX, spY, spR, spR * 0.85, spR * 0.45);
  layMarkerField(spPoly, "#FFFFFF", 45, 1.5, 0.45, 255, "detail_marker");

  brush.set("rotring", "#FFFFFF", Math.max(0.4, r * 0.09));
  brush.line(spX - spR * 0.6, spY, spX + spR * 0.6, spY);
  if (r > 6) {
    // Secondary tiny glint
    brush.line(cx - r * 0.12, cy - r * 0.48, cx + r * 0.05, cy - r * 0.48);
    // Bottom-right secondary caustic dot
    brush.set("rotring", "#FFFFFF", 0.35);
    brush.line(cx + r * 0.38, cy + r * 0.46, cx + r * 0.52, cy + r * 0.32);
  }
}

