        if (tileFam === PALETTE.BLUE || tileFam === PALETTE.ORANGE) shCol = tileFam.dark;
        brush.set("flat_marker", shCol, 1.15);
        for (let y = y1 + 3; y < y2; y += 6) {
          let segsTile = clipSegmentToPoly(x1, y, x2, y, sz);
          for (let s of segsTile) {
            brush.line(s[0], s[1], s[2], s[3]);
          }
        }
      }

      // 3. Crisp graphic water puddles clipped to this tile
      for (let pud of deckPuddles) {
        let pCol = (pud.fam === PALETTE.BLUE) ? PALETTE.BLUE.light : PALETTE.WHITE.light;
        brush.set("flat_marker", pCol, 1.1);
        for (let y = y1 + 2.5; y < y2; y += 5) {
          let segsP = clipSegmentToPoly(x1, y, x2, y, pud.poly);
          for (let s of segsP) {
            brush.line(s[0], s[1], s[2], s[3]);
          }
        }
      }

      // 4. Hyperreal non-slip ceramic quarry tile dimples & bevels
      drawTileHyperrealSurface(x1, y1, x2, y2, tileFam);
    }
  }

  // Draw crisp graphic meniscus rims around the deck puddles (clipped out of grout channels)
  for (let pud of deckPuddles) {
    drawPolyContour(pud.poly, "rotring", pud.fam.dark, 0.7);
    // Inner white specular meniscus line offset by 3px
    let insetPoly = pud.poly.map(p => [p[0] + 2.5, p[1] + 2.5]);
    drawPolyContour(insetPoly, "rotring", "#FFFFFF", 0.55);
  }

  // 5. Render the recessed grout lines filled with hyperrealistic encrusted chlorine scale
  drawGroutAndChlorineScale(xStops, yStops);
}

function drawGutterAndDiagonalStripesOnTile(tilePoly, x1, y1, x2, y2) {
  // Diagonal band 1: x + y <= 360 -> Slotted White & Silver Pool Gutter Grate over deep Pool Blue channel
  // Diagonal band 2: 360 < x + y <= 470 -> Pool Blue graphic border
  // Diagonal band 3: 470 < x + y <= 535 -> Safety Orange graphic baseline stripe
  for (let s = x1 + y1 - 20; s <= x2 + y2 + 20; s += 5) {
    // Line x + y = s -> from (s - y2, y2) to (x2, s - x2)
    let lx1 = s - y2, ly1 = y2;
    let lx2 = s - y1, ly2 = y1;
    let segs = clipSegmentToPoly(lx1, ly1, lx2, ly2, tilePoly);
    if (segs.length === 0) continue;

    let col = null;
    let bName = "flat_marker";
    let w = 1.15;

    if (s <= 350) {
      let mod = ((Math.floor(s / 24) % 2) + 2) % 2;
      if (mod === 0) {
        col = PALETTE.WHITE.light;
      } else {
        col = PALETTE.BLUE.darkest;
      }
    } else if (s <= 365) {
      col = PALETTE.SILVER.dark;
    } else if (s <= 475) {
      col = PALETTE.BLUE.base;
    } else if (s <= 535) {
      col = PALETTE.ORANGE.base;
    }

    if (col) {
      brush.set(bName, col, w);
      for (let seg of segs) {
        brush.line(seg[0], seg[1], seg[2], seg[3]);
      }
    }
  }

  // Add hyperreal gutter grate cross-ribs and specular wet edges at 45°
  for (let s = 24; s <= 348; s += 24) {
    let segs = clipSegmentToPoly(s - y2, y2, s - y1, y1, tilePoly);
    for (let seg of segs) {
      brush.set("rotring", PALETTE.WHITE.spec, 0.55);
      brush.line(seg[0], seg[1], seg[2], seg[3]);
      brush.set("rotring", PALETTE.BLUE.caustic, 0.4);
      brush.line(seg[0] + 3, seg[1] + 3, seg[2] + 3, seg[3] + 3);
    }
  }
  // Crisp 45° border lines between the Blue and Orange deck bands
  for (let borderS of [365, 475, 535]) {
    let segs = clipSegmentToPoly(borderS - y2, y2, borderS - y1, y1, tilePoly);
    for (let seg of segs) {
      brush.set("rotring", PALETTE.SILVER.darkest, 0.8);
      brush.line(seg[0], seg[1], seg[2], seg[3]);
    }
  }
}

function drawTileHyperrealSurface(x1, y1, x2, y2, fam) {
  // 1. Chamfered ceramic edge highlight (top & left) and shadow (bottom & right)
  brush.set("rotring", fam.spec, 0.55);
  brush.line(x1 + 2, y1 + 2, x2 - 2, y1 + 2);
  brush.line(x1 + 2, y1 + 2, x1 + 2, y2 - 2);

  brush.set("rotring", fam.dark, 0.65);
  brush.line(x1 + 2, y2 - 2, x2 - 2, y2 - 2);
  brush.line(x2 - 2, y1 + 2, x2 - 2, y2 - 2);

  // Outer sharp graphic border
  brush.set("rotring", PALETTE.SILVER.darkest, 0.55);
  brush.line(x1, y1, x2, y1);
  brush.line(x2, y1, x2, y2);
  brush.line(x2, y2, x1, y2);
  brush.line(x1, y2, x1, y1);

  // 2. Non-slip raised ceramic dimple grid (28px spacing)
  let step = 28;
  for (let tx = x1 + 18; tx <= x2 - 16; tx += step) {
    for (let ty = y1 + 18; ty <= y2 - 16; ty += step) {
      // Skip gutter slot area
      if (tx + ty < 365) continue;
      // Top-left sunlit crescent of raised ceramic boss
      brush.set("rotring", fam.spec, 0.35);
      brush.line(tx - 4, ty - 2, tx - 2, ty - 4);
      brush.line(tx - 2, ty - 4, tx + 2, ty - 4);
      // Bottom-right shadow crescent of raised ceramic boss
      brush.set("rotring", fam.dark, 0.35);
      brush.line(tx - 2, ty + 4, tx + 2, ty + 4);
      brush.line(tx + 2, ty + 4, tx + 4, ty + 2);
    }
  }

  // 3. Subtle mineral water-spot rings & ceramic grain (strictly horizontal/45° micro-marks)
  brush.set("2H", fam.mid, 0.35);
  for (let i = 0; i < 14; i++) {
    let rx = random(x1 + 8, x2 - 24);
    let ry = random(y1 + 8, y2 - 8);
    if (rx + ry > 370) {
      brush.line(rx, ry, rx + random(8, 20), ry);
    }
  }
}

function drawGroutAndChlorineScale(xStops, yStops) {
  const groutCenters = [120, 360, 600, 840, 1080];
  const halfG = 8; // 16px wide grout channels

  // Vertical grout channels
  for (let gx of groutCenters) {
    let gPoly = [[gx - halfG, 0], [gx + halfG, 0], [gx + halfG, 1200], [gx - halfG, 1200]];
    layMarkerField(gPoly, PALETTE.SILVER.dark, 90, 4, 0.9, 220, "detail_marker");

    // Deep recessed shadow along left edge of vertical grout channel
    brush.set("rotring", PALETTE.SILVER.darkest, 0.7);
    brush.line(gx - halfG + 1, 0, gx - halfG + 1, 1200);
    brush.set("2B", PALETTE.SILVER.darkest, 0.55);
    brush.line(gx - halfG + 3, 0, gx - halfG + 3, 1200);

    // Sunlit right lip of vertical grout channel
    brush.set("rotring", PALETTE.WHITE.mid, 0.45);
    brush.line(gx + halfG - 1.5, 0, gx + halfG - 1.5, 1200);

    // Hyperrealistic Chlorine Scale (calcium carbonate + trichlor efflorescence crusts)
    for (let y = 6; y < 1194; y += random(5, 13)) {
      let clusterLen = random(6, 26);
      let side = random() < 0.55 ? -1 : 1;
      let sx = gx + side * random(1.5, halfG - 2.2);
      let sy = y;
      let ey = Math.min(1196, y + clusterLen);

      // Chalky white calcium scale crust hugging the mortar joint
      brush.set("charcoal", PALETTE.WHITE.light, random(0.45, 0.85));
      brush.line(sx, sy, sx, ey);

      // Crystalline 45° scale spurs bridging across the grout channel
      if (random() < 0.65) {
        let dx = -side * random(3, 9);
        let sx2 = Math.max(gx - halfG + 1.5, Math.min(gx + halfG - 1.5, sx + dx));
        let sy2 = sy + Math.abs(sx2 - sx);
        brush.set("rotring", PALETTE.WHITE.spec, 0.45);
        brush.line(sx, sy, sx2, sy2);

        // Pale turquoise/greenish copper-chlorine salt tint on scale edge
        if (random() < 0.45) {
          let saltCol = random() < 0.6 ? PALETTE.BLUE.caustic : PALETTE.GREEN.caustic;
          brush.set("rotring", saltCol, 0.32);
          brush.line(sx, sy + 1.5, sx2, sy2 + 1.5);
        }
      }

      // Micro-cracks in the mortar between scale blooms
      if (random() < 0.35) {
        brush.set("rotring", PALETTE.SILVER.darkest, 0.35);
        brush.line(gx - 3, sy, gx + 3, sy + 6);
      }
    }
  }

  // Horizontal grout channels
  for (let gy of groutCenters) {
    let gPoly = [[0, gy - halfG], [1200, gy - halfG], [1200, gy + halfG], [0, gy + halfG]];
    layMarkerField(gPoly, PALETTE.SILVER.dark, 0, 4, 0.9, 220, "detail_marker");

    // Deep recessed shadow along top edge of horizontal grout channel
    brush.set("rotring", PALETTE.SILVER.darkest, 0.7);
    brush.line(0, gy - halfG + 1, 1200, gy - halfG + 1);
    brush.set("2B", PALETTE.SILVER.darkest, 0.55);
    brush.line(0, gy - halfG + 3, 1200, gy - halfG + 3);

    // Sunlit bottom lip
    brush.set("rotring", PALETTE.WHITE.mid, 0.45);
    brush.line(0, gy + halfG - 1.5, 1200, gy + halfG - 1.5);

    // Encrusted chlorine scale along horizontal grout joints
    for (let x = 6; x < 1194; x += random(5, 13)) {
      let clusterLen = random(6, 28);
      let side = random() < 0.55 ? -1 : 1;
      let sy = gy + side * random(1.5, halfG - 2.2);
      let sx = x;
      let ex = Math.min(1196, x + clusterLen);

      brush.set("charcoal", PALETTE.WHITE.light, random(0.45, 0.85));
      brush.line(sx, sy, ex, sy);

      if (random() < 0.65) {
        let dy = -side * random(3, 9);
        let sy2 = Math.max(gy - halfG + 1.5, Math.min(gy + halfG - 1.5, sy + dy));
        let sx2 = sx + Math.abs(sy2 - sy);
        brush.set("rotring", PALETTE.WHITE.spec, 0.45);
        brush.line(sx, sy, sx2, sy2);

        if (random() < 0.45) {
          let saltCol = random() < 0.6 ? PALETTE.BLUE.caustic : PALETTE.GREEN.caustic;
          brush.set("rotring", saltCol, 0.32);
          brush.line(sx + 1.5, sy, sx2 + 1.5, sy2);
        }
      }

      if (random() < 0.35) {
        brush.set("rotring", PALETTE.SILVER.darkest, 0.35);
        brush.line(sx, gy - 3, sx + 6, gy + 3);
      }
    }
  }

  // Extra dense chlorine scale efflorescence at the 25 grout-cross intersections
  for (let gx of groutCenters) {
    for (let gy of groutCenters) {
      let crossPoly = makeOctagon(gx, gy, 7, 7, 3);
      layMarkerField(crossPoly, PALETTE.WHITE.base, 45, 2.2, 0.6, 220, "detail_marker");
      brush.set("rotring", PALETTE.WHITE.spec, 0.45);
      brush.line(gx - 5, gy - 2, gx + 5, gy - 2);
      brush.line(gx - 2, gy - 5, gx - 2, gy + 5);
      brush.set("rotring", PALETTE.SILVER.darkest, 0.4);
      brush.line(gx - 6, gy + 4, gx + 4, gy - 6);
    }
  }
}

// =============================================================================
// LAYER 2: COILED LANE ROPE (MOULDED FLOAT DISCS & SILVER STEEL CABLE)
// =============================================================================

function drawSteelCableSegment(x1, y1, x2, y2, width = 20) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  if (len < 1) return;
  let angleDeg = Math.round((Math.atan2(dy, dx) * 180) / Math.PI);
  let cx = 0.5 * (x1 + x2);
  let cy = 0.5 * (y1 + y2);
  let halfU = 0.5 * len;
  let halfN = 0.5 * width;

  // 1. Clean Silver marker base for braided stainless steel cable
  let cablePoly = makeOrientedRect(cx, cy, -halfU, halfU, -halfN, halfN, angleDeg);
  layMarkerField(cablePoly, PALETTE.SILVER.base, angleDeg, 3, 0.85, 245, "detail_marker");

  // 2. Cylindrical metallic shadow & highlight bands
  let shBand = makeOrientedRect(cx, cy, -halfU, halfU, 2, halfN, angleDeg);
  layMarkerField(shBand, PALETTE.SILVER.dark, angleDeg, 2.5, 0.7, 230, "detail_marker");

  let hiBand = makeOrientedRect(cx, cy, -halfU, halfU, -halfN + 2, -1, angleDeg);
  layMarkerField(hiBand, PALETTE.WHITE.spec, angleDeg, 2.2, 0.65, 240, "detail_marker");

  // 3. Diagonal 45° braided wire-rope twist strands
  let rad = (angleDeg * Math.PI) / 180;
  let ux = Math.cos(rad), uy = Math.sin(rad);
  let nx = -uy, ny = ux;
  for (let u = -halfU + 4; u < halfU - 4; u += 7) {
    let ax = cx + (u - 4) * ux - (halfN - 2) * nx;
    let ay = cy + (u - 4) * uy - (halfN - 2) * ny;
    let bx = cx + (u + 4) * ux + (halfN - 2) * nx;
    let by = cy + (u + 4) * uy + (halfN - 2) * ny;
    brush.set("rotring", PALETTE.SILVER.darkest, 0.45);
    brush.line(ax, ay, bx, by);
    brush.set("rotring", "#FFFFFF", 0.35);
    brush.line(ax + ux * 1.5, ay + uy * 1.5, bx + ux * 1.5, by + uy * 1.5);
  }

  drawPolyContour(cablePoly, "rotring", PALETTE.SILVER.darkest, 0.65);
}

// Render a single moulded anti-wave plastic float disc in side/oblique profile
// Strictly aligned to 0°, 45°, 90°, or 135°
function drawMouldedFloatDisc(cx, cy, angleDeg, fam, isShadowed = false) {
  let halfU = 14.5; // 29px disc thickness along rope
  let halfN = 56;   // 112px disc diameter across rope
  let rad = (angleDeg * Math.PI) / 180;
  let ux = Math.cos(rad), uy = Math.sin(rad);
  let nx = -uy, ny = ux;

  // Ensure light always hits the top/left side of the cylinder regardless of rope direction
  let lightSign = (nx + ny <= 0) ? 1 : -1;

  // 1. Main octagonal disc silhouette laid in clean marker
  let discPoly = makeOrientedOctagon(cx, cy, halfU, halfN, 5.5, angleDeg);
  let baseCol = isShadowed ? fam.mid : fam.base;
  layMarkerField(discPoly, baseCol, (angleDeg + 90) % 180, 4.5, 1.05, 250, "flat_marker");

  // 2. Cylindrical 3D shading bands across the diameter (along N)
  // Upper-left bright wet plastic reflection band
  let nHi1 = lightSign * 16;
  let nHi2 = lightSign * 42;
  let hiMin = Math.min(nHi1, nHi2), hiMax = Math.max(nHi1, nHi2);
  let hiPoly = makeOrientedRect(cx, cy, -halfU + 2, halfU - 2, hiMin, hiMax, angleDeg);
  layMarkerField(hiPoly, isShadowed ? fam.base : fam.light, angleDeg, 3.2, 0.8, 225, "detail_marker");

  // Specular wet streak along the cylinder ridge
  let spMin = Math.min(lightSign * 25, lightSign * 33);
  let spMax = Math.max(lightSign * 25, lightSign * 33);
  let spPoly = makeOrientedRect(cx, cy, -halfU + 2.5, halfU - 2.5, spMin, spMax, angleDeg);
  layMarkerField(spPoly, isShadowed ? fam.light : fam.spec, angleDeg, 2.2, 0.65, 235, "detail_marker");

  // Lower-right deep cylindrical shadow band
  let sh1 = -lightSign * 14;
  let sh2 = -lightSign * 46;
  let shMin = Math.min(sh1, sh2), shMax = Math.max(sh1, sh2);
  let shPoly = makeOrientedRect(cx, cy, -halfU + 2, halfU - 2, shMin, shMax, angleDeg);
  layMarkerField(shPoly, isShadowed ? fam.darkest : fam.dark, angleDeg, 3.2, 0.85, 230, "detail_marker");

  // Reflected warm deck bounce light along the very bottom rim
  let rf1 = -lightSign * 46;
  let rf2 = -lightSign * 53;
  let rfPoly = makeOrientedRect(cx, cy, -halfU + 4, halfU - 4, Math.min(rf1, rf2), Math.max(rf1, rf2), angleDeg);
  layMarkerField(rfPoly, fam.mid, angleDeg, 2.5, 0.6, 200, "detail_marker");

  // 3. Moulded Wave-Quelling Turbine Slots & Radial Fin Ribs (Hyperreal plastic structure!)
  // Every competitive float disc has two rows of recessed hollow slots flanked by raised plastic ribs
  const slotNRanges = [
    [-47, -31],
    [-25, -9],
    [-3,   13],
    [ 19,  35],
    [ 40,  50]
  ];
  const slotURanges = [
    [-11.5, -3.2],
    [  3.2, 11.5]
  ];

  for (let [nA, nB] of slotNRanges) {
    for (let [uA, uB] of slotURanges) {
      let slotPoly = makeOrientedRect(cx, cy, uA, uB, nA, nB, angleDeg);
      // Deep shadow inside the hollow wave-quelling chamber
      let cavCol = (nA * lightSign > 10) ? fam.dark : fam.darkest;
      layMarkerField(slotPoly, cavCol, angleDeg, 2.2, 0.6, 240, "detail_marker");

      // Inner Silver cable visible through the central slots!
      if (Math.abs(0.5 * (nA + nB)) < 12) {
        let cablePeek = makeOrientedRect(cx, cy, uA + 1.5, uB - 1.5, -5, 5, angleDeg);
        layMarkerField(cablePeek, PALETTE.SILVER.mid, angleDeg, 2.0, 0.5, 220, "detail_marker");
      }

      // Crisp injection-moulded rib highlight on the sunlit edge of the slot
      let p1 = [cx + uB * ux + nA * nx, cy + uB * uy + nA * ny];
      let p2 = [cx + uB * ux + nB * nx, cy + uB * uy + nB * ny];
      let p3 = [cx + uA * ux + nB * nx, cy + uA * uy + nB * ny];
      brush.set("rotring", (nA * lightSign > 0) ? "#FFFFFF" : fam.light, 0.42);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(p2[0], p2[1], p3[0], p3[1]);
    }
  }

  // 4. Central raised injection-moulded collar ring around the equator of the disc (u in [-3, +3])
  let collarBand = makeOrientedRect(cx, cy, -2.6, 2.6, -halfN + 1, halfN - 1, angleDeg);
  brush.set("rotring", fam.darkest, 0.45);
  drawPolyContour(collarBand, "rotring", fam.darkest, 0.45);

  // Specular glint on the central collar ridge
  let spC1 = [cx - 1.2 * ux + (lightSign * 28) * nx, cy - 1.2 * uy + (lightSign * 28) * ny];
  let spC2 = [cx + 1.2 * ux + (lightSign * 28) * nx, cy + 1.2 * uy + (lightSign * 28) * ny];
  brush.set("rotring", "#FFFFFF", 0.7);
  brush.line(spC1[0], spC1[1], spC2[0], spC2[1]);

  // 5. Water droplets beaded on the plastic disc surface
  if (!isShadowed) {
    for (let k = 0; k < 2; k++) {
      let du = random(-9, 9);
      let dn = random(-36, 36);
      let dx = cx + du * ux + dn * nx;
      let dy = cy + du * uy + dn * ny;
      drawWaterDroplet(dx, dy, random(2.4, 4.2), fam, discPoly);
    }
  }

  // 6. Razor-sharp graphic outer contour of the moulded disc
  drawPolyContour(discPoly, "rotring", fam.darkest, 0.75);
}

// Render the Face-On Octagonal Moulded Float Disc & Stainless Steel Tension Hook at the free end
function drawFaceOnDiscAndHook(cx, cy) {
  const R = 62;
  // 1. Outer Octagonal Shroud in Safety Orange
  let outerOct = makeOctagon(cx, cy, R, R, 26);
  layMarkerField(outerOct, PALETTE.ORANGE.base, 45, 5, 1.15, 250, "flat_marker");

  // Upper-left sunlit plastic bevel on outer ring
  let hiOct = makeOctagon(cx - 3, cy - 3, R - 4, R - 4, 24);
  brush.set("rotring", PALETTE.ORANGE.spec, 0.75);
  for (let i of [5, 6, 7, 0, 1]) {
    brush.line(hiOct[i][0], hiOct[i][1], hiOct[(i + 1) % 8][0], hiOct[(i + 1) % 8][1]);
  }

  // 2. Dark recessed turbine annulus (where the 8 radial wave-breaker fins sit)
  let recessOct = makeOctagon(cx, cy, R - 11, R - 11, 21);
  layMarkerField(recessOct, PALETTE.ORANGE.darkest, 135, 3.5, 0.9, 245, "detail_marker");

  // 3. Eight Radial Moulded Plastic Turbine Fins at exact 0°, 45°, 90°, 135° angles!
  for (let a = 0; a < 360; a += 45) {
    let rad = (a * Math.PI) / 180;
    let rIn = 21;
    let rOut = R - 10;
    let mR = 0.5 * (rIn + rOut);
    let halfLen = 0.5 * (rOut - rIn);
    let fcx = cx + Math.cos(rad) * mR;
    let fcy = cy + Math.sin(rad) * mR;
    let finPoly = makeOrientedRect(fcx, fcy, -halfLen, halfLen, -4.5, 4.5, a % 180);
    let finCol = (a === 180 || a === 225 || a === 270 || a === 135) ? PALETTE.ORANGE.light : PALETTE.ORANGE.mid;
    layMarkerField(finPoly, finCol, a % 180, 2.2, 0.65, 245, "detail_marker");
    drawPolyContour(finPoly, "rotring", PALETTE.ORANGE.spec, 0.45);
  }

  // Concentric wave-baffle ring at mid-radius
  let midRing = makeOctagon(cx, cy, 36, 36, 15);
  drawPolyContour(midRing, "rotring", PALETTE.ORANGE.light, 1.2);
  drawPolyContour(midRing, "rotring", PALETTE.ORANGE.spec, 0.5);

  // 4. Inner White High-Density Polyethylene Hub Collar
  let hubOct = makeOctagon(cx, cy, 22, 22, 9);
  layMarkerField(hubOct, PALETTE.WHITE.light, 45, 3, 0.8, 250, "detail_marker");
  drawPolyContour(hubOct, "rotring", PALETTE.WHITE.darkest, 0.7);

  // 5. Central Silver Stainless Steel Swage Ferrule & Tension Hook assembly
  let ferruleOct = makeOctagon(cx, cy, 12, 12, 5);
  layMarkerField(ferruleOct, PALETTE.SILVER.base, 135, 2.2, 0.65, 250, "detail_marker");
  drawPolyContour(ferruleOct, "rotring", PALETTE.SILVER.darkest, 0.75);

  // Machined stainless steel tension hook & turnbuckle extending at 135° (up-left) from the hub
  let turnbucklePoly = makeOrientedOctagon(cx - 32, cy - 32, 28, 8.5, 3.5, 45);
  layMarkerField(turnbucklePoly, PALETTE.SILVER.light, 45, 2.5, 0.7, 250, "detail_marker");
  let tbShadow = makeOrientedRect(cx - 32, cy - 32, -24, 24, 1.5, 7.5, 45);
  layMarkerField(tbShadow, PALETTE.SILVER.dark, 45, 2.0, 0.55, 235, "detail_marker");
  drawPolyContour(turnbucklePoly, "rotring", PALETTE.SILVER.darkest, 0.7);

  // Specular metallic streak along the turnbuckle barrel
  brush.set("rotring", "#FFFFFF", 0.75);
  brush.line(cx - 14, cy - 18, cx - 48, cy - 52);

  // Octagonal stainless steel locking hook loop at (cx - 64, cy - 64)
  let hookOuter = makeOctagon(cx - 64, cy - 64, 18, 18, 7.5);
  layMarkerField(hookOuter, PALETTE.SILVER.light, 45, 2.5, 0.7, 245, "detail_marker");
  let hookHole = makeOctagon(cx - 64, cy - 64, 9, 9, 4);
  layMarkerField(hookHole, PALETTE.BLUE.base, 45, 2.5, 0.7, 245, "detail_marker");
  drawPolyContour(hookOuter, "rotring", PALETTE.SILVER.darkest, 0.75);
