function drawCoiledLaneRope() {
  // Helper to place a sequence of moulded discs along a 0°, 45°, or 90° path segment
  function populateSegment(x1, y1, x2, y2, colorPattern, startIdx, isShadowed = false) {
    let dx = x2 - x1;
    let dy = y2 - y1;
    let len = Math.hypot(dx, dy);
    let angleDeg = ((Math.round((Math.atan2(dy, dx) * 180) / Math.PI) % 360) + 360) % 360;

    // 1. Draw the continuous braided Silver stainless steel cable first
    drawSteelCableSegment(x1, y1, x2, y2, 20);

    // 2. Place moulded float discs every 34px along the segment
    let step = 34;
    let margin = 20;
    let idx = startIdx;
    for (let d = margin; d <= len - margin; d += step) {
      let t = d / len;
      let px = x1 + t * dx;
      let py = y1 + t * dy;
      let fam = colorPattern[idx % colorPattern.length];
      drawMouldedFloatDisc(px, py, angleDeg % 180, fam, isShadowed);
      idx++;
    }
    return idx;
  }

  // Draw an octagonal 45°-chamfered corner coupling / elbow spacer where rope segments bend by 45°
  function drawCornerSpacer(vx, vy, fam) {
    let spPoly = makeOctagon(vx, vy, 22, 22, 9);
    layMarkerField(spPoly, PALETTE.SILVER.base, 45, 3, 0.75, 245, "detail_marker");
    let innerRing = makeOctagon(vx, vy, 14, 14, 6);
    layMarkerField(innerRing, fam.base, 135, 2.5, 0.65, 240, "detail_marker");
    drawPolyContour(spPoly, "rotring", PALETTE.SILVER.darkest, 0.7);
    drawPolyContour(innerRing, "rotring", fam.darkest, 0.6);
    brush.set("rotring", "#FFFFFF", 0.6);
    brush.line(vx - 10, vy - 14, vx + 4, vy - 14);
  }

  // ---------------------------------------------------------------------------
  // LOOP A: UNDER-PASSING COIL (Upper-left to upper-right)
  // Color pattern: Pool Blue & White alternating with Signal Green markers
  // ---------------------------------------------------------------------------
  const patternUnder = [
    PALETTE.BLUE, PALETTE.BLUE, PALETTE.BLUE,
    PALETTE.WHITE, PALETTE.WHITE,
    PALETTE.GREEN, PALETTE.GREEN,
    PALETTE.WHITE, PALETTE.WHITE
  ];

  const underNodes = [
    [250, -20],
    [250, 175],
    [425, 350],
    [795, 350],
    [970, 175],
    [1220, 175]
  ];

  let idxA = 0;
  for (let i = 0; i < underNodes.length - 1; i++) {
    let a = underNodes[i];
    let b = underNodes[i + 1];
    idxA = populateSegment(a[0], a[1], b[0], b[1], patternUnder, idxA, i === 2);
    if (i < underNodes.length - 2) {
      drawCornerSpacer(b[0], b[1], patternUnder[idxA % patternUnder.length]);
    }
  }

  // ---------------------------------------------------------------------------
  // LOOP B: MAIN FOREGROUND COIL (Wrapping around the deck & framing the swim cap)
  // Color pattern: Classic Olympic Safety Orange wave-breaker end section,
  // transitioning to White, Signal Green, and Pool Blue!
  // ---------------------------------------------------------------------------
  const patternMain = [
    // 10 Safety Orange wave-quelling floats
    PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE,
    PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE,
    // 3 White floats
    PALETTE.WHITE, PALETTE.WHITE, PALETTE.WHITE,
    // 4 Signal Green floats
    PALETTE.GREEN, PALETTE.GREEN, PALETTE.GREEN, PALETTE.GREEN,
    // 3 White floats
    PALETTE.WHITE, PALETTE.WHITE, PALETTE.WHITE,
    // 6 Pool Blue floats
    PALETTE.BLUE, PALETTE.BLUE, PALETTE.BLUE, PALETTE.BLUE, PALETTE.BLUE, PALETTE.BLUE,
    // 2 White + 8 Safety Orange floats along bottom and right
    PALETTE.WHITE, PALETTE.WHITE,
    PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE,
    PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE, PALETTE.ORANGE
  ];

  const mainNodes = [
    [1020, -20],
    [1020, 230],
    [800, 450],
    [370, 450],
    [175, 645],
    [175, 875],
    [350, 1050],
    [890, 1050],
    [1070, 870],
    [1070, 560],
    [960, 450]
  ];

  let idxB = 0;
  for (let i = 0; i < mainNodes.length - 1; i++) {
    let a = mainNodes[i];
    let b = mainNodes[i + 1];
    idxB = populateSegment(a[0], a[1], b[0], b[1], patternMain, idxB, false);
    if (i < mainNodes.length - 2) {
      drawCornerSpacer(b[0], b[1], patternMain[idxB % patternMain.length]);
    }
  }

  // ---------------------------------------------------------------------------
  // LOOP C: FREE TERMINAL END & FACE-ON OCTAGONAL DISC WITH SILVER HOOK
  // ---------------------------------------------------------------------------
  drawSteelCableSegment(370, 450, 235, 315, 20);
  drawCornerSpacer(370, 450, PALETTE.ORANGE);
  drawMouldedFloatDisc(315, 395, 45, PALETTE.ORANGE, false);
  drawFaceOnDiscAndHook(235, 315);
