// =============================================================================
// LAYER 3: WET SILICONE SWIM CAP (GRAPHIC FACETS + HYPERREAL STRETCHED CREASES)
// =============================================================================

// Render hyperrealistic stretched silicone fold ridges, troughs, and wet specular ribbons
// strictly clipped inside a graphic 0°/45°/90° cap facet polygon!
function renderSiliconeCreaseBundle(poly, x1, y1, x2, y2, fam, width = 34) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  if (len < 1) return;
  let nx = -dy / len;
  let ny = dx / len;
  if (nx + ny > 0) {
    // Orient normal toward upper-left light source
    nx = -nx;
    ny = -ny;
  }

  // Cross-sectional silicone fold profile from -width to +width:
  // [-width..-0.45w]: deep shadow trough before the fold
  // [-0.45w..-0.10w]: rich saturated silicone slope
  // [-0.10w..+0.22w]: translucent sunlit subsurface stretch glow
  // [+0.02w..+0.12w]: razor-sharp wet silicone specular ridge!
  // [+0.22w..+0.65w]: steep shadow flank behind the crest
  // [+0.65w..+width]: warm bounce light in the lower valley
  for (let s = -width; s <= width; s += 1.6) {
    let normS = s / width;
    let col = fam.base;
    let bName = "cpencil";
    let w = 0.65;

    if (normS < -0.52) {
      col = fam.darkest;
      bName = "charcoal";
      w = 0.7;
    } else if (normS < -0.22) {
      col = fam.dark;
      bName = "2B";
      w = 0.65;
    } else if (normS < -0.02) {
      col = fam.light;
      bName = "cpencil";
      w = 0.65;
    } else if (normS < 0.13) {
      col = fam.spec;
      bName = "rotring";
      w = 0.55;
    } else if (normS < 0.30) {
      col = fam.caustic;
      bName = "cpencil";
      w = 0.6;
    } else if (normS < 0.68) {
      col = fam.darkest;
      bName = "charcoal";
      w = 0.75;
    } else {
      // Warm orange/white bounce light reflected into the silicone crease valley!
      col = (fam === PALETTE.GREEN) ? PALETTE.ORANGE.light : fam.mid;
      bName = "cpencil";
      w = 0.55;
    }

    let lx1 = x1 + nx * s;
    let ly1 = y1 + ny * s;
    let lx2 = x2 + nx * s;
    let ly2 = y2 + ny * s;
    drawClippedLine(lx1, ly1, lx2, ly2, poly, bName, col, w);
  }

  // Pure white wet silicone double-specular line right along the stretched crest
  drawClippedLine(x1 + nx * (width * 0.05), y1 + ny * (width * 0.05),
                  x2 + nx * (width * 0.05), y2 + ny * (width * 0.05),
                  poly, "rotring", "#FFFFFF", 0.75);
  drawClippedLine(x1 + nx * (width * 0.11), y1 + ny * (width * 0.11),
                  x2 + nx * (width * 0.11), y2 + ny * (width * 0.11),
                  poly, "rotring", fam.spec, 0.45);

  // Fine perpendicular/45° micro-stretch puckers across the crest
  let stepP = 18;
  for (let d = 14; d < len - 14; d += stepP) {
    let px = x1 + (dx / len) * d;
    let py = y1 + (dy / len) * d;
    drawClippedLine(px - nx * 6, py - ny * 6, px + nx * 9, py + ny * 9, poly, "rotring", fam.spec, 0.3);
  }
}

function drawWetSiliconeSwimCap() {
