// ============================================================================
// STATE HELPERS (Guarantees brush.set() before any stroke operation)
// ============================================================================

function useStroke(brushName, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
}

function useWaterFill(col, alpha, bleed = 0.28, tex = 0.58, border = 0.28) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

function useSolidWash(col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
}

function drawPoly(pts, curv = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 1.2) return;
  brush.line(x1, y1, x2, y2);
}

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (dist(prev[0], prev[1], pts[i][0], pts[i][1]) >= 1.8) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curv);
  }
}

// ============================================================================
// COLOR & DEPTH UTILITIES
// ============================================================================

function hexToRgb(hex) {
  let c = hex.replace("#", "");
  let num = parseInt(c, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  let cl = (v) => constrain(Math.round(v), 0, 255);
  return (
    "#" +
    ((1 << 24) + (cl(r) << 16) + (cl(g) << 8) + cl(b))
      .toString(16)
      .slice(1)
  );
}

function mixHex(c1, c2, t) {
  let a = hexToRgb(c1);
  let b = hexToRgb(c2);
  let k = constrain(t, 0, 1);
  return rgbToHex(
    lerp(a[0], b[0], k),
    lerp(a[1], b[1], k),
    lerp(a[2], b[2], k)
  );
}

// Returns ambient water color at normalized depth d in [0, 1]
function waterColorAtDepth(d) {
  if (d < 0.3) return mixHex(PALETTE.viridian, PALETTE.duskyTeal, d / 0.3);
  if (d < 0.65) return mixHex(PALETTE.duskyTeal, PALETTE.pelagicBlue, (d - 0.3) / 0.35);
  return mixHex(PALETTE.pelagicBlue, PALETTE.paynesDeep, (d - 0.65) / 0.35);
}

// Shifts object colors bluer & cooler with distance into the turquoise/Payne's grey depth
function depthFade(hexCol, d, strength = 1.0) {
  let waterCol = waterColorAtDepth(d);
  let veil = constrain(Math.pow(d, 1.05) * 0.86 * strength, 0, 0.92);
  return mixHex(hexCol, waterCol, veil);
}

function normalize3(v) {
  let len = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / len, v[1] / len, v[2] / len];
}

function dot3(a, b) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

// ============================================================================
// SCENE DATA CONSTRUCTION
// ============================================================================

function buildSceneData() {
  // Construct 9 massive interlocking stud-link chain links descending diagonally
  // from upper-left (60, -35) to lower-right (1115, 1215)
  let numLinks = 9;
  let curX = 68;
  let curY = -32;

  for (let i = 0; i < numLinks; i++) {
    let d = i / (numLinks - 1); // 0.0 at top-left, 1.0 at bottom-right
    let sc = lerp(1.16, 0.72, d);

    // Slight heavy catenary sag: steeper near top-left, slightly shallower toward bottom-right
    let chainAngle = lerp(54.5, 47.0, d);

    // Alternating perpendicular roll angles around the chain axis
    // Odd links are mostly face-on (-17 deg); even links are 3/4 profile (+73 deg)
    let isFace = i % 2 === 1;
    let rollPhi = isFace ? -17 + random(-3, 3) : 73 + random(-3, 3);

    // Stadium link dimensions scaled by sc
    let rBar = 31 * sc;       // Iron bar radius (diameter = 62 * sc)
    let rWidth = 69 * sc;     // Half-width of stadium centerline
    let halfFlat = 64 * sc;   // Half-length of straight flank
    let rLength = halfFlat + rWidth; // Total centerline half-length = 133 * sc

    chainLinks.push({
      index: i,
      cx: curX,
      cy: curY,
      d: d,
      sc: sc,
      chainAngle: chainAngle,
      rollPhi: rollPhi,
      isFace: isFace,
      rBar: rBar,
      rWidth: rWidth,
      halfFlat: halfFlat,
      rLength: rLength
    });

    // Advance to next link center using exact taut interlocking pitch:
    // Pitch = (rLength_i - rBar_i) + (rLength_next - rBar_next)
    let nextD = (i + 1) / (numLinks - 1);
    let nextSc = lerp(1.16, 0.72, nextD);
    let pitch = (133 - 31) * sc + (133 - 31) * nextSc;
    let midAngle = lerp(chainAngle, lerp(54.5, 47.0, nextD), 0.5);
    curX += cos(midAngle) * pitch;
    curY += sin(midAngle) * pitch;
  }

  // Construct slanted shafts of noon light fanning down from LIGHT_SRC (320, -340)
  let rayConfigs = [
    { angle: 44.5, spread: 4.2, len: 1850, intensity: 0.75, layer: "back" },
    { angle: 50.0, spread: 6.5, len: 1950, intensity: 1.00, layer: "both" },
    { angle: 55.8, spread: 3.8, len: 1900, intensity: 0.85, layer: "front" },
    { angle: 60.5, spread: 7.2, len: 2000, intensity: 0.95, layer: "both" },
    { angle: 66.2, spread: 4.5, len: 1950, intensity: 0.80, layer: "back" },
    { angle: 71.0, spread: 6.0, len: 1850, intensity: 0.90, layer: "both" },
    { angle: 76.5, spread: 5.0, len: 1750, intensity: 0.70, layer: "front" },
    { angle: 81.8, spread: 4.0, len: 1650, intensity: 0.55, layer: "back" },
    { angle: 39.2, spread: 3.5, len: 1650, intensity: 0.50, layer: "back" }
  ];

  for (let rc of rayConfigs) {
    lightShafts.push(rc);
  }
}

// ============================================================================
// 3D LINK SURFACE EVALUATION
// ============================================================================

// Evaluates point and 3D normal on a link's stadium torus at spine parameter t in [0,1)
// and bar cross-section angle alpha (degrees)
function evalLinkSurface(link, t, alphaDeg) {
  let { cx, cy, chainAngle, rollPhi, rBar, rWidth, halfFlat } = link;

  // Parameterize stadium perimeter:
  // 4 segments: right flank, bottom arc, left flank, top arc
  let segLenFlat = 2 * halfFlat;
  let segLenArc = Math.PI * rWidth;
  let totalPerim = 2 * segLenFlat + 2 * segLenArc;
  let distAlong = ((t % 1) + 1) % 1 * totalPerim;

  let s0 = 0, u0 = 0, ns = 0, nu = 0, ts = 0, tu = 0;

  if (distAlong < segLenFlat) {
    // 1. Right straight flank (u = +rWidth, s goes from -halfFlat to +halfFlat)
    let f = distAlong / segLenFlat;
    s0 = lerp(-halfFlat, halfFlat, f);
    u0 = rWidth;
    ns = 0; nu = 1;
    ts = 1; tu = 0;
  } else if (distAlong < segLenFlat + segLenArc) {
    // 2. Bottom semicircle (centered at s = +halfFlat, angle from 0 to 180 deg)
    let f = (distAlong - segLenFlat) / segLenArc;
    let ang = f * 180;
    s0 = halfFlat + sin(ang) * rWidth;
    u0 = cos(ang) * rWidth;
    ns = sin(ang); nu = cos(ang);
    ts = cos(ang); tu = -sin(ang);
  } else if (distAlong < 2 * segLenFlat + segLenArc) {
    // 3. Left straight flank (u = -rWidth, s goes from +halfFlat to -halfFlat)
    let f = (distAlong - segLenFlat - segLenArc) / segLenFlat;
    s0 = lerp(halfFlat, -halfFlat, f);
    u0 = -rWidth;
    ns = 0; nu = -1;
    ts = -1; tu = 0;
  } else {
    // 4. Top semicircle (centered at s = -halfFlat, angle from 180 to 360 deg)
    let f = (distAlong - 2 * segLenFlat - segLenArc) / segLenArc;
    let ang = 180 + f * 180;
    s0 = -halfFlat + sin(ang) * rWidth;
    u0 = cos(ang) * rWidth;
    ns = sin(ang); nu = cos(ang);
    ts = cos(ang); tu = -sin(ang);
  }

  let ca = cos(alphaDeg);
  let sa = sin(alphaDeg);

  // Local point on bar cross-section
  let s = s0 + rBar * ca * ns;
  let u = u0 + rBar * ca * nu;
  let w = rBar * sa;

  // Roll around chain axis by rollPhi
  let cPhi = cos(rollPhi);
  let sPhi = sin(rollPhi);

  let pPerp = u * cPhi - w * sPhi;
  let pZ = u * sPhi + w * cPhi;

  // Spine center z (used for clean back/front loop splitting)
  let spineZ = u0 * sPhi;

  // Local normal rotated by rollPhi
  let nS = ca * ns;
  let nPerp = ca * nu * cPhi - sa * sPhi;
  let nZ = ca * nu * sPhi + sa * cPhi;

  // Transform from (s, perp) to canvas (x, y)
  let cAng = cos(chainAngle);
  let sAng = sin(chainAngle);

  // Subtle foreshortening along chain axis from pZ
  let sProj = s - pZ * 0.08;
  let x = cx + sProj * cAng - pPerp * sAng;
  let y = cy + sProj * sAng + pPerp * cAng;

  let nx = nS * cAng - nPerp * sAng;
  let ny = nS * sAng + nPerp * cAng;
  let nz = nZ;

  return {
    x, y, z: pZ, spineZ,
    nx, ny, nz,
    s, u, w, s0, u0
  };
}

// Evaluates point on the central cast-iron cross-stud
// uFrac in [-1, 1] across link width, alphaDeg around stud cylinder
function evalStudSurface(link, uFrac, alphaDeg) {
  let { cx, cy, chainAngle, rollPhi, rBar, rWidth } = link;
  let uSpan = rWidth - rBar * 0.55;
  let u = uFrac * uSpan;

  // Stud flares out near its ends where it welds into the side bars
  let flare = 1.0 + 0.38 * Math.pow(uFrac, 2);
  let studRad = rBar * 0.72 * flare;

  let s = studRad * cos(alphaDeg);
  let w = studRad * sin(alphaDeg);

  let cPhi = cos(rollPhi);
  let sPhi = sin(rollPhi);

  let pPerp = u * cPhi - w * sPhi;
  let pZ = u * sPhi + w * cPhi;

  let nS = cos(alphaDeg);
  let nPerp = -0.22 * uFrac * cPhi - sin(alphaDeg) * sPhi;
  let nZ = -0.22 * uFrac * sPhi + sin(alphaDeg) * cPhi;
  let nNorm = normalize3([nS, nPerp, nZ]);

  let cAng = cos(chainAngle);
  let sAng = sin(chainAngle);
  let sProj = s - pZ * 0.08;

  let x = cx + sProj * cAng - pPerp * sAng;
  let y = cy + sProj * sAng + pPerp * cAng;

  let nx = nNorm[0] * cAng - nNorm[1] * sAng;
  let ny = nNorm[0] * sAng + nNorm[1] * cAng;
  let nz = nNorm[2];

  return { x, y, z: pZ, nx, ny, nz, uFrac };
}

// ============================================================================
// LAYER 1: STACKED WATERCOLOR GLAZES (TURQUOISE/VIRIDIAN -> PAYNE'S GREY)
// ============================================================================

function renderWaterGlazes() {
  // Solid base washes to anchor the gradient before translucent watercolor bleeds
  let baseBands = [
    { y1: -60, y2: 320, col: PALETTE.viridian, a: 145 },
    { y1: 180, y2: 580, col: PALETTE.duskyTeal, a: 155 },
    { y1: 420, y2: 860, col: PALETTE.midSlate, a: 165 },
    { y1: 680, y2: 1060, col: PALETTE.pelagicBlue, a: 175 },
    { y1: 880, y2: 1260, col: PALETTE.paynesDeep, a: 195 }
  ];

  for (let b of baseBands) {
    useSolidWash(b.col, b.a);
    drawPoly([
      [-60, b.y1],
      [1260, b.y1 - 40],
      [1260, b.y2 + 40],
      [-60, b.y2]
    ], 0.1);
  }

  // Stacked organic watercolor glazes batched by depth zone
  // Notice the slant matching the diagonal underwater light & depth transition
  let glazeLayers = [
    // Upper canopy: sunlit turquoise, viridian, celadon
    { yMin: -80, yMax: 280, col: PALETTE.viridian, alpha: 62, bleed: 0.42, count: 6 },
    { yMin: -60, yMax: 240, col: PALETTE.surfTeal, alpha: 55, bleed: 0.38, count: 6 },
    { yMin: -50, yMax: 190, col: PALETTE.surfLight, alpha: 42, bleed: 0.45, count: 5 },

    // Upper-mid transition: dusky teal and slate viridian
    { yMin: 140, yMax: 520, col: PALETTE.duskyTeal, alpha: 65, bleed: 0.36, count: 6 },
    { yMin: 260, yMax: 680, col: PALETTE.midSlate, alpha: 68, bleed: 0.35, count: 6 },

    // Mid-lower transition: cold pelagic blue-grey
    { yMin: 480, yMax: 920, col: PALETTE.pelagicBlue, alpha: 74, bleed: 0.35, count: 6 },

    // Deep abyss: stacked Payne's grey glazes
    { yMin: 680, yMax: 1150, col: PALETTE.paynesMid, alpha: 82, bleed: 0.34, count: 6 },
    { yMin: 860, yMax: 1280, col: PALETTE.paynesDeep, alpha: 92, bleed: 0.32, count: 6 },
    { yMin: 980, yMax: 1280, col: PALETTE.abyss, alpha: 95, bleed: 0.28, count: 5 }
  ];

  for (let layer of glazeLayers) {
    useWaterFill(layer.col, layer.alpha, layer.bleed, 0.65, 0.25);
    for (let k = 0; k < layer.count; k++) {
      let cx = map(k, 0, layer.count - 1, 60, 1140) + random(-140, 140);
      let cy = random(layer.yMin, layer.yMax);
      // Slant the water glazes slightly up-right so upper-right stays more turquoise
      // and lower-left / bottom-right sink deeper into Payne's grey
      cy += (cx - 600) * -0.12;
      let rx = random(280, 520);
      let ry = random(140, 270);
      let pts = [];
      let nPts = 9;
      for (let m = 0; m < nPts; m++) {
        let ang = (m / nPts) * 360;
        let rMod = 0.8 + 0.4 * noise(cx * 0.005 + cos(ang), cy * 0.005 + sin(ang));
        pts.push([
          cx + cos(ang) * rx * rMod,
          cy + sin(ang) * ry * rMod
        ]);
      }
      drawPoly(pts, 0.4);
    }
  }

  // Subtle underwater current texture using waves vector field
  brush.field("waves");
  for (let i = 0; i < 95; i++) {
    let x = random(-40, 1240);
    let y = random(-40, 1240);
    let d = constrain(y / 1200, 0, 1);
    let col = d < 0.45
      ? mixHex(PALETTE.surfTeal, PALETTE.duskyTeal, d / 0.45)
      : mixHex(PALETTE.midSlate, PALETTE.paynesDeep, (d - 0.45) / 0.55);
    useStroke("charcoal", col, random(0.4, 1.1));
    brush.flowLine(x, y, random(80, 220), random(-15, 25));
  }
  brush.noField();
}

// ============================================================================
// LAYER 2: BACKGROUND SHAFTS OF NOON LIGHT
// ============================================================================

function renderBackgroundLightShafts() {
  // Soft watercolor light-lift glazes along the shafts
  for (let shaft of lightShafts) {
    if (shaft.layer === "front") continue;

    let a1 = shaft.angle - shaft.spread * 0.5;
    let a2 = shaft.angle + shaft.spread * 0.5;
    let r0 = 260;
    let r1 = shaft.len;

    let p1 = [LIGHT_SRC.x + cos(a1) * r0, LIGHT_SRC.y + sin(a1) * r0];
    let p2 = [LIGHT_SRC.x + cos(a2) * r0, LIGHT_SRC.y + sin(a2) * r0];
    let p3 = [LIGHT_SRC.x + cos(a2) * r1, LIGHT_SRC.y + sin(a2) * r1];
    let p4 = [LIGHT_SRC.x + cos(a1) * r1, LIGHT_SRC.y + sin(a1) * r1];

    useWaterFill(PALETTE.chalkTeal, 26 * shaft.intensity, 0.38, 0.45, 0.15);
    drawPoly([p1, p2, p3, p4], 0.15);

    // Upper brighter core of the beam
    let rMid = shaft.len * 0.58;
    let pm3 = [LIGHT_SRC.x + cos(a2) * rMid, LIGHT_SRC.y + sin(a2) * rMid];
    let pm4 = [LIGHT_SRC.x + cos(a1) * rMid, LIGHT_SRC.y + sin(a1) * rMid];
    useWaterFill(PALETTE.chalkCyan, 24 * shaft.intensity, 0.42, 0.4, 0.12);
    drawPoly([p1, p2, pm3, pm4], 0.15);

    // Long soft chalky pastel streaks inside background shafts
    let numStreaks = Math.floor(22 * shaft.intensity);
    for (let s = 0; s < numStreaks; s++) {
      let ang = random(a1, a2);
      let startR = random(280, 750);
      let segLen = random(260, 680);
      let endR = startR + segLen;
      let x1 = LIGHT_SRC.x + cos(ang) * startR;
      let y1 = LIGHT_SRC.y + sin(ang) * startR;
      let x2 = LIGHT_SRC.x + cos(ang) * endR;
      let y2 = LIGHT_SRC.y + sin(ang) * endR;

      let dMid = constrain(((y1 + y2) * 0.5) / 1200, 0, 1);
      let streakCol = dMid < 0.4
        ? mixHex(PALETTE.chalkIce, PALETTE.chalkCyan, dMid / 0.4)
        : mixHex(PALETTE.chalkCyan, PALETTE.chalkDusk, (dMid - 0.4) / 0.6);

      useStroke("pastel_beam", streakCol, random(0.7, 1.6));
      safeLine(x1, y1, x2, y2);
    }
  }
}

// ============================================================================
// LAYER 4 & 5: VOLUMETRIC 3D CHAIN LINK RENDERING (BACK & FRONT PASSES)
// ============================================================================

function renderLinkHalf(link, passType) {
  let { d, sc } = link;

  // Sample the stadium loop into 48 segments around t in [0, 1)
  let nSegs = 48;
  let nAlpha = 10; // Cross-section strips across the visible hemisphere

  // Determine which t-segments belong to "back" (spineZ < 0) vs "front" (spineZ >= 0)
  // Using a tiny overlap at the transition so there is never a seam
  for (let i = 0; i < nSegs; i++) {
    let t0 = i / nSegs;
    let t1 = (i + 1) / nSegs;
    let tMid = (t0 + t1) * 0.5;

    let centerSample = evalLinkSurface(link, tMid, 0);
    let isFrontSeg = centerSample.spineZ >= -2.5 * sc;
    let isBackSeg = centerSample.spineZ <= 2.5 * sc;

    if ((passType === "back" && !isBackSeg) || (passType === "front" && !isFrontSeg)) {
      continue;
    }

    // Build cross-sectional quad strips over the visible front hemisphere of the bar
    for (let j = 0; j < nAlpha; j++) {
      // Scan alpha so we cover the camera-facing side of the bar cylinder
      let a0 = -170 + (j / nAlpha) * 340;
      let a1 = -170 + ((j + 1) / nAlpha) * 340;
      let aMid = (a0 + a1) * 0.5;

      let pMid = evalLinkSurface(link, tMid, aMid);
      // Back-face culling on the bar cylinder itself
      if (pMid.nz < -0.15) continue;

      let p00 = evalLinkSurface(link, t0, a0);
      let p10 = evalLinkSurface(link, t1, a0);
      let p11 = evalLinkSurface(link, t1, a1);
      let p01 = evalLinkSurface(link, t0, a1);

      // Compute 3D lighting on this facet
      let nVec = normalize3([pMid.nx, pMid.ny, pMid.nz]);
      let ndotl = dot3(nVec, LIGHT_DIR);

      // Self-occlusion inside the inner eye of the link and on back loops
      let eyeOcc = (Math.abs(pMid.s0) > link.halfFlat * 0.7 && dot3([pMid.nx, pMid.ny, 0], [0, 0, 0]) === 0) ? 1.0 : 1.0;
      if (passType === "back") ndotl -= 0.18;

      // Determine base iron color from lighting
      let baseCol;
      if (ndotl > 0.48) {
        baseCol = mixHex(PALETTE.ironMid, PALETTE.ironSpec, (ndotl - 0.48) / 0.52);
      } else if (ndotl > 0.08) {
        baseCol = mixHex(PALETTE.ironSlate, PALETTE.ironMid, (ndotl - 0.08) / 0.40);
      } else if (ndotl > -0.28) {
        baseCol = mixHex(PALETTE.ironDark, PALETTE.ironSlate, (ndotl + 0.28) / 0.36);
      } else {
        baseCol = mixHex(PALETTE.ironBlack, PALETTE.ironDark, constrain((ndotl + 0.8) / 0.52, 0, 1));
      }

      // Fade bluer with depth
      let shadedCol = depthFade(baseCol, d, 1.0);

      // Solid wash pass for dense, heavy iron volume
      useSolidWash(shadedCol, 225);
      drawPoly([
        [p00.x, p00.y],
        [p10.x, p10.y],
        [p11.x, p11.y],
        [p01.x, p01.y]
      ], 0.05);
    }
  }

  // On the "front" pass, also render the central cast-iron cross-stud and interlocking shadows
  if (passType === "front") {
    renderCrossStud(link);
    renderInterlockShadow(link);
  }

  // Sculptural contour hatching & iron grain along the bar for this pass
  renderIronContourStrokes(link, passType);
}

function renderCrossStud(link) {
  let { d } = link;
  let nU = 10;
  let nA = 10;

  for (let i = 0; i < nU; i++) {
    let u0 = lerp(-0.95, 0.95, i / nU);
    let u1 = lerp(-0.95, 0.95, (i + 1) / nU);
    let uMid = (u0 + u1) * 0.5;

    for (let j = 0; j < nA; j++) {
      let a0 = -160 + (j / nA) * 320;
      let a1 = -160 + ((j + 1) / nA) * 320;
      let aMid = (a0 + a1) * 0.5;

      let pMid = evalStudSurface(link, uMid, aMid);
      if (pMid.nz < -0.1) continue;

      let p00 = evalStudSurface(link, u0, a0);
      let p10 = evalStudSurface(link, u1, a0);
      let p11 = evalStudSurface(link, u1, a1);
      let p01 = evalStudSurface(link, u0, a1);

      let ndotl = dot3([pMid.nx, pMid.ny, pMid.nz], LIGHT_DIR);
      // Darken ends of stud where it meets the side bars
      ndotl -= Math.pow(Math.abs(uMid), 2.2) * 0.25;

      let col;
      if (ndotl > 0.35) {
        col = mixHex(PALETTE.ironMid, PALETTE.ironSpec, (ndotl - 0.35) / 0.65);
      } else if (ndotl > -0.1) {
        col = mixHex(PALETTE.ironDark, PALETTE.ironMid, (ndotl + 0.1) / 0.45);
      } else {
        col = mixHex(PALETTE.ironBlack, PALETTE.ironDark, constrain((ndotl + 0.8) / 0.7, 0, 1));
      }

      useSolidWash(depthFade(col, d, 1.0), 230);
      drawPoly([
        [p00.x, p00.y],
        [p10.x, p10.y],
        [p11.x, p11.y],
        [p01.x, p01.y]
      ], 0.05);
    }
  }

  // Cast-iron seam & cross-contour strokes on the stud
  let seamPts = [];
  for (let i = 0; i <= 8; i++) {
    let u = lerp(-0.92, 0.92, i / 8);
    let p = evalStudSurface(link, u, 25);
    seamPts.push([p.x, p.y, 0.9]);
  }
  useStroke("2B", depthFade(PALETTE.ironBlack, d, 0.9), 1.1 * link.sc);
  safeSpline(seamPts, 0.3);

  let litSeamPts = [];
  for (let i = 0; i <= 8; i++) {
    let u = lerp(-0.88, 0.88, i / 8);
    let p = evalStudSurface(link, u, -45);
    litSeamPts.push([p.x, p.y, 0.8]);
  }
  useStroke("cpencil", depthFade(PALETTE.ironSpec, d, 0.9), 0.9 * link.sc);
  safeSpline(litSeamPts, 0.3);
}

// Deep occlusion shadow where adjacent links bite into each other's eyes
function renderInterlockShadow(link) {
  let { d, sc } = link;
  let shadowCol = depthFade(PALETTE.ironBlack, d, 0.85);

  // Top eye notch (t around 0.875) and bottom eye notch (t around 0.375)
  let notches = [0.375, 0.875];
  for (let tCenter of notches) {
    for (let k = 0; k < 14; k++) {
      let tOff = random(-0.055, 0.055);
      let aStart = random(110, 165);
      let pts = [];
      for (let m = 0; m < 4; m++) {
        let p = evalLinkSurface(link, tCenter + tOff + m * 0.012, aStart + m * 14);
        pts.push([p.x, p.y, 1.1 - m * 0.2]);
      }
      useStroke("charcoal", shadowCol, random(0.9, 1.8) * sc);
      safeSpline(pts, 0.4);
    }
  }
}

// Longitudinal wrought-iron fiber lines & cross-contour cylindrical hatching
function renderIronContourStrokes(link, passType) {
  let { d, sc } = link;
  let strokeDensity = Math.floor(lerp(68, 28, d));

  for (let i = 0; i < strokeDensity; i++) {
    let tStart = random(0, 1);
    let sampleCenter = evalLinkSurface(link, tStart, 0);
    let isFront = sampleCenter.spineZ >= 0;
    if ((passType === "back" && isFront) || (passType === "front" && !isFront)) {
      continue;
    }

    let alpha = random(-155, 155);
    let p0 = evalLinkSurface(link, tStart, alpha);
    if (p0.nz < 0.02) continue;

    let ndotl = dot3([p0.nx, p0.ny, p0.nz], LIGHT_DIR);
    let isCrossContour = random() < 0.42;

    let pts = [];
    if (isCrossContour) {
      // Cross-sectional ring hatching wrapping around the round bar
      let aSpan = random(45, 95);
      for (let k = 0; k <= 4; k++) {
        let p = evalLinkSurface(link, tStart + k * 0.003, alpha + (k / 4 - 0.5) * aSpan);
        if (p.nz > -0.05) pts.push([p.x, p.y, 0.5 + 0.6 * sin((k / 4) * 180)]);
      }
    } else {
      // Longitudinal forged-iron grain along the spine
      let tSpan = random(0.04, 0.11);
      for (let k = 0; k <= 4; k++) {
        let p = evalLinkSurface(link, tStart + (k / 4) * tSpan, alpha + random(-4, 4));
        if (p.nz > -0.05) pts.push([p.x, p.y, 0.5 + 0.6 * sin((k / 4) * 180)]);
      }
    }

    if (pts.length >= 3) {
      let col;
      let bName = "iron_grain";
      if (ndotl > 0.38) {
        col = mixHex(PALETTE.ironMid, PALETTE.surfLight, 0.45);
        bName = "cpencil";
      } else if (ndotl > 0.0) {
        col = PALETTE.ironSlate;
      } else {
        col = PALETTE.ironBlack;
        bName = "2B";
      }
      useStroke(bName, depthFade(col, d, 0.95), random(0.55, 1.15) * sc);
      safeSpline(pts, 0.45);
    }
  }
}

// ============================================================================
// LAYER 6: HYPERREAL DETAILS (RUST SCALE, CAUSTICS, BARNACLES, SEA-SQUIRTS)
// ============================================================================

function renderLinkHyperDetail(link) {
  // Order on each link:
  // 1. Flaking rust scale plaques
  // 2. Rippling caustic light networks on upper sun-facing iron
  // 3. Encrusted volcano barnacle clusters
  // 4. Translucent sea-squirts (tunicates)
  renderRustScaleOnLink(link);
  renderCausticsOnLink(link);
  renderBarnaclesOnLink(link);
  renderSeaSquirtsOnLink(link);
}

// 1. FLAKING RUST SCALE
function renderRustScaleOnLink(link) {
  let { d, sc, index } = link;
  // Closer links show rich stratified rust scale; deeper links fade bluer
  let numPatches = Math.floor(lerp(18, 6, d));

  for (let p = 0; p < numPatches; p++) {
    let tCenter = (p / numPatches + random(-0.03, 0.03) + 1) % 1;
    let aCenter = random(-115, 95);
    let centerPt = evalLinkSurface(link, tCenter, aCenter);
    if (centerPt.nz < 0.12) continue;

    let ndotl = dot3([centerPt.nx, centerPt.ny, centerPt.nz], LIGHT_DIR);

    // Build an irregular flaking rust plaque polygon on the 3D surface
    let polyPts = [];
    let rimPts = [];
    let shadowPts = [];
    let nVerts = 8;
    let tRad = random(0.022, 0.052);
    let aRad = random(18, 38);

    for (let v = 0; v < nVerts; v++) {
      let ang = (v / nVerts) * 360;
      let jag = 0.65 + 0.55 * noise(index * 10 + p * 3 + cos(ang), sin(ang));
      let tv = tCenter + cos(ang) * tRad * jag;
      let av = aCenter + sin(ang) * aRad * jag;
      let pt = evalLinkSurface(link, tv, av);
      polyPts.push([pt.x, pt.y]);

      if (v <= 4) {
        rimPts.push([pt.x, pt.y, 0.8]);
      }
      if (v >= 3 && v <= 7) {
        shadowPts.push([pt.x + 1.8 * sc, pt.y + 2.2 * sc, 0.9]);
      }
    }

    // Choose dusky rust tone according to illumination
    let rustCol;
    if (ndotl > 0.35) {
      rustCol = random() < 0.5 ? PALETTE.rustOchre : PALETTE.rustSienna;
    } else if (ndotl > 0.0) {
      rustCol = random() < 0.5 ? PALETTE.rustSienna : PALETTE.rustUmber;
    } else {
      rustCol = random() < 0.5 ? PALETTE.rustDeep : PALETTE.rustViolet;
    }

    let fadedRust = depthFade(rustCol, d, 0.92);
    useSolidWash(fadedRust, 195);
    drawPoly(polyPts, 0.15);

    // Dark undercut shadow crack beneath peeling rust scale edge
    if (d < 0.82 && shadowPts.length >= 3) {
      useStroke("rotring", depthFade(PALETTE.ironBlack, d, 0.88), 0.95 * sc);
      safeSpline(shadowPts, 0.25);
    }

    // Crisp mineral edge highlight on upper lifted flake rim
    if (ndotl > 0.1 && d < 0.78 && rimPts.length >= 3) {
      let rimCol = depthFade(PALETTE.rustCrust, d, 0.9);
      useStroke("cpencil", rimCol, 0.75 * sc);
      safeSpline(rimPts, 0.25);
    }

    // Fine pitted rust stipple inside the plaque
    if (d < 0.7) {
      useStroke("iron_grain", depthFade(PALETTE.rustDeep, d, 0.9), 0.7 * sc);
      for (let s = 0; s < 4; s++) {
        let p1 = evalLinkSurface(link, tCenter + random(-tRad, tRad) * 0.6, aCenter + random(-aRad, aRad) * 0.6);
        let p2 = [p1.x + random(-4, 4) * sc, p1.y + random(-4, 4) * sc];
        safeLine(p1.x, p1.y, p2[0], p2[1]);
      }
    }
  }
}

// 2. CAUSTIC LIGHT PATTERNS RIPPLING ACROSS EACH LINK
function renderCausticsOnLink(link) {
  let { d, sc, index } = link;
  // Caustics are strongest on upper/mid links and fade into ghostly cyan deeper down
  let causticStrength = Math.pow(1.0 - d * 0.78, 1.3);
  if (causticStrength < 0.08) return;

  // Project a 3D cellular Voronoi-like wave network onto the sun-facing surfaces of the bar & stud
  let nCellsT = 26;
  let nCellsA = 7;

  let glowCol = depthFade(PALETTE.chalkCyan, d * 0.7, 0.75);
  let coreCol = depthFade(PALETTE.chalkWhite, d * 0.6, 0.65);

  for (let i = 0; i < nCellsT; i++) {
    let tBase = i / nCellsT;
    for (let j = 0; j < nCellsA; j++) {
      let aBase = lerp(-125, 65, j / nCellsA);
      let pSample = evalLinkSurface(link, tBase, aBase);
      if (pSample.nz < 0.18) continue;

      let ndotl = dot3([pSample.nx, pSample.ny, pSample.nz], LIGHT_DIR);
      if (ndotl < 0.18) continue;

      // Evaluate wavy caustic ridge phase in 3D space so ripples flow across the curvature
      let wx = pSample.x * 0.028 + index * 1.7;
      let wy = pSample.y * 0.028 - index * 1.1;
      let waveVal = Math.sin(wx * 2.1 + Math.cos(wy * 1.9)) + Math.cos(wy * 2.3 - Math.sin(wx * 1.7));

      if (Math.abs(waveVal) < 0.55) {
        // Trace a rippling caustic filament along the curved iron surface
        let filamentPts = [];
        let dirT = 0.014 * cos(wx * 55 + wy * 40);
        let dirA = 14.0 * sin(wx * 45 - wy * 60);

        for (let step = -2; step <= 2; step++) {
          let tCur = tBase + step * dirT + 0.004 * sin(step * 90);
          let aCur = aBase + step * dirA + 4.0 * cos(step * 90);
          let pt = evalLinkSurface(link, tCur, aCur);
          if (pt.nz > 0.1) {
            let press = (1.1 - Math.abs(step) * 0.35) * causticStrength * ndotl;
            filamentPts.push([pt.x, pt.y, constrain(press, 0.2, 1.3)]);
          }
        }

        if (filamentPts.length >= 3) {
          // Outer turquoise caustic halo
          useStroke("caustic_glow", glowCol, 1.35 * sc * causticStrength);
          safeSpline(filamentPts, 0.55);

          // Bright noon-light core filament on strongly lit crests
          if (ndotl > 0.38 && d < 0.72) {
            useStroke("cpencil", coreCol, 0.85 * sc * causticStrength);
            safeSpline(filamentPts, 0.55);
          }
        }
      }
    }
  }

  // Also ripple caustics across the central cross-stud
  if (d < 0.8) {
    for (let k = 0; k < 7; k++) {
      let u0 = lerp(-0.75, 0.75, k / 6);
      let pts = [];
      for (let m = 0; m < 4; m++) {
        let u = u0 + (m - 1.5) * 0.11;
        let a = -55 + 25 * sin(k * 70 + m * 50);
        let p = evalStudSurface(link, constrain(u, -0.9, 0.9), a);
        let ndotl = dot3([p.nx, p.ny, p.nz], LIGHT_DIR);
        if (p.nz > 0.15 && ndotl > 0.15) {
          pts.push([p.x, p.y, 0.85 * causticStrength]);
        }
      }
      if (pts.length >= 3) {
        useStroke("caustic_glow", glowCol, 1.15 * sc * causticStrength);
        safeSpline(pts, 0.5);
        if (d < 0.55) {
          useStroke("cpencil", coreCol, 0.7 * sc * causticStrength);
          safeSpline(pts, 0.5);
        }
      }
    }
  }
}

// 3. ENCRUSTED VOLCANO BARNACLE CLUSTERS (Balanus)
function renderBarnaclesOnLink(link) {
  let { d, sc, index } = link;
  let numClusters = Math.floor(lerp(9, 4, d));

  for (let c = 0; c < numClusters; c++) {
    // Place clusters around shoulders, flanks, and outer silhouette edges
    let tCluster = (c / numClusters + 0.04 * sin(index * 45 + c * 90) + 1) % 1;
    let aCluster = (c % 2 === 0) ? random(-105, -25) : random(15, 95);

    let barnCount = Math.floor(random(4, 9) * lerp(1.1, 0.6, d));
    for (let b = 0; b < barnCount; b++) {
      // First barnacle in cluster is large adult; others are smaller surrounding spat
      let sizeMult = b === 0 ? random(1.0, 1.35) : random(0.45, 0.9);
      let t = tCluster + random(-0.038, 0.038);
      let a = aCluster + random(-28, 28);

      let basePt = evalLinkSurface(link, t, a);
      if (basePt.nz < -0.05) continue;

      drawSingleBarnacle(basePt, sc * sizeMult, d);
    }
  }

  // Also a cluster of barnacles right on the cross-stud
  let studBarnCount = Math.floor(lerp(6, 2, d));
  for (let b = 0; b < studBarnCount; b++) {
    let u = random(-0.65, 0.65);
    let a = random(-85, 45);
    let basePt = evalStudSurface(link, u, a);
    if (basePt.nz > 0.05) {
      drawSingleBarnacle(basePt, sc * random(0.55, 1.05), d);
    }
  }
}

function drawSingleBarnacle(pt, scaleFactor, d) {
  let rBase = 11.5 * scaleFactor;
  let rTop = 5.8 * scaleFactor;
  let height = 9.5 * scaleFactor;

  // Direction the barnacle cone grows outward (aligned with surface normal + slight upward phototropism)
  let gx = pt.nx * 0.85 - 0.15;
  let gy = pt.ny * 0.85 - 0.25;
  let topX = pt.x + gx * height;
  let topY = pt.y + gy * height;

  // Tangent vector across the barnacle base
  let tx = -gy;
  let ty = gx;
  let tLen = Math.hypot(tx, ty) || 1;
  tx /= tLen;
  ty /= tLen;

  let ndotl = dot3([pt.nx, pt.ny, pt.nz], LIGHT_DIR);

  // Cast shadow on the iron behind/below the barnacle cone
  let shCol = depthFade(PALETTE.ironBlack, d, 0.9);
  useSolidWash(shCol, 175);
  drawPoly([
    [pt.x + tx * rBase * 0.9, pt.y + ty * rBase * 0.9],
    [pt.x - tx * rBase * 1.1 + 3 * scaleFactor, pt.y - ty * rBase * 1.1 + 4 * scaleFactor],
    [topX - tx * rTop + 4 * scaleFactor, topY - ty * rTop + 5 * scaleFactor],
    [topX + tx * rTop * 0.5, topY + ty * rTop * 0.5]
  ], 0.15);

  // Lit side calcareous plates vs shadow side plates
  let litPlateCol = depthFade(ndotl > 0.15 ? PALETTE.barnLight : PALETTE.barnMid, d, 0.92);
  let midPlateCol = depthFade(PALETTE.barnSlate, d, 0.92);
  let darkPlateCol = depthFade(PALETTE.barnShadow, d, 0.92);

  // Left/Upper lit half of volcano cone
  useSolidWash(litPlateCol, 225);
  drawPoly([
    [pt.x - tx * rBase, pt.y - ty * rBase],
    [pt.x + gx * rBase * 0.25, pt.y + gy * rBase * 0.25],
    [topX, topY],
    [topX - tx * rTop, topY - ty * rTop]
  ], 0.1);

  // Right/Lower shadow half of volcano cone
  useSolidWash(ndotl > 0.2 ? midPlateCol : darkPlateCol, 225);
  drawPoly([
    [pt.x, pt.y + gy * rBase * 0.2],
    [pt.x + tx * rBase, pt.y + ty * rBase],
    [topX + tx * rTop, topY + ty * rTop],
    [topX, topY]
  ], 0.1);

  // Dark diamond operculum aperture at the summit
  let holeCol = depthFade(PALETTE.barnHole, d, 0.85);
  useSolidWash(holeCol, 240);
  drawPoly([
    [topX - tx * rTop * 0.75, topY - ty * rTop * 0.75],
    [topX + gx * rTop * 0.45, topY + gy * rTop * 0.45],
    [topX + tx * rTop * 0.75, topY + ty * rTop * 0.75],
    [topX - gx * rTop * 0.45, topY - gy * rTop * 0.45]
  ], 0.05);

  // Detailed calcareous ribs & feathery cirri on closer links
  if (d < 0.78 && scaleFactor > 0.5) {
    useStroke("2B", darkPlateCol, 0.65 * scaleFactor);
    for (let r = -1; r <= 1; r++) {
      let bx = pt.x + tx * rBase * (r * 0.55);
      let by = pt.y + ty * rBase * (r * 0.55);
      let rx = topX + tx * rTop * (r * 0.5);
      let ry = topY + ty * rTop * (r * 0.5);
      safeLine(bx, by, rx, ry);
    }

    // Chalky highlight on the jagged rim of the aperture
    useStroke("cpencil", depthFade(PALETTE.chalkWhite, d, 0.85), 0.7 * scaleFactor);
    safeLine(
      topX - tx * rTop * 0.8,
      topY - ty * rTop * 0.8,
      topX + gx * rTop * 0.45,
      topY + gy * rTop * 0.45
    );

    // Delicate feeding cirri (feathery fan) extending from some barnacles into the current
    if (random() < 0.42 && d < 0.65) {
      let cirriCol = depthFade(PALETTE.barnCirri, d, 0.85);
      useStroke("pen", cirriCol, 0.45 * scaleFactor);
      for (let f = 0; f < 3; f++) {
        let angOff = (f - 1) * 18;
        let cLen = (7 + f * 2) * scaleFactor;
        let cx1 = topX + (gx * cos(angOff) - gy * sin(angOff)) * cLen * 0.5;
        let cy1 = topY + (gx * sin(angOff) + gy * cos(angOff)) * cLen * 0.5;
        let cx2 = cx1 + 4 * scaleFactor;
        let cy2 = cy1 - 3 * scaleFactor;
        safeSpline([
          [topX, topY, 0.8],
          [cx1, cy1, 0.6],
          [cx2, cy2, 0.2]
        ], 0.4);
      }
    }
  }
}

// 4. SEA-SQUIRTS (ASCIDIANS / TUNICATES)
function renderSeaSquirtsOnLink(link) {
  let { d, sc } = link;
  if (d > 0.85) return;

  // Sea-squirts cling in small clusters of 2-4 along sheltered flanks & undersides
  let numGroups = Math.floor(lerp(4, 1, d));

  for (let g = 0; g < numGroups; g++) {
    let tGroup = random(0.08, 0.92);
    let aGroup = random() < 0.6 ? random(35, 115) : random(-115, -55);
    let basePt = evalLinkSurface(link, tGroup, aGroup);
    if (basePt.nz < 0.0) continue;

    let count = Math.floor(random(2, 4));
    for (let s = 0; s < count; s++) {
      let t = tGroup + (s - 1) * 0.018;
      let a = aGroup + random(-14, 14);
      let pt = evalLinkSurface(link, t, a);
      drawSingleSeaSquirt(pt, sc * random(0.75, 1.18), d);
    }
  }
}

function drawSingleSeaSquirt(pt, scaleFactor, d) {
  // Bulbous curved vase-like body swaying slightly right/down-right with the current
  let len = random(26, 38) * scaleFactor;
  let wMax = random(9.5, 13.5) * scaleFactor;

  // Growth direction: outward from iron + gentle current sway
  let dirX = pt.nx * 0.65 + 0.45;
  let dirY = pt.ny * 0.65 + 0.25;
  let dLen = Math.hypot(dirX, dirY) || 1;
  dirX /= dLen;
  dirY /= dLen;

  let perpX = -dirY;
  let perpY = dirX;

  let tipX = pt.x + dirX * len;
  let tipY = pt.y + dirY * len;
  let midX = pt.x + dirX * len * 0.52 + perpX * 2.5 * scaleFactor;
  let midY = pt.y + dirY * len * 0.52 + perpY * 2.5 * scaleFactor;

  // Secondary side excurrent siphon branching off near 65% height
  let sideSiphonX = midX + dirX * len * 0.18 + perpX * wMax * 1.15;
  let sideSiphonY = midY + dirY * len * 0.18 + perpY * wMax * 1.15;

  // Dusky twilight plum / rose-ochre coloration
  let isOchre = random() < 0.35;
  let bodyDark = depthFade(isOchre ? PALETTE.rustDeep : PALETTE.squirtDeep, d, 0.9);
  let bodyMid = depthFade(isOchre ? PALETTE.squirtOchre : PALETTE.squirtPlum, d, 0.9);
  let bodyLit = depthFade(isOchre ? PALETTE.rustCrust : PALETTE.squirtRose, d, 0.88);
  let rimCol = depthFade(PALETTE.squirtRim, d, 0.82);
  let glowCol = depthFade(PALETTE.squirtGlow, d, 0.8);

  // Sac shadow base
  useSolidWash(bodyDark, 215);
  drawPoly([
    [pt.x - perpX * wMax * 0.55, pt.y - perpY * wMax * 0.55],
    [midX - perpX * wMax * 0.95, midY - perpY * wMax * 0.95],
    [tipX - perpX * wMax * 0.38, tipY - perpY * wMax * 0.38],
    [tipX + perpX * wMax * 0.38, tipY + perpY * wMax * 0.38],
    [sideSiphonX, sideSiphonY],
    [midX + perpX * wMax * 0.95, midY + perpY * wMax * 0.95],
    [pt.x + perpX * wMax * 0.55, pt.y + perpY * wMax * 0.55]
  ], 0.35);

  // Translucent inner core glow (watercolor bleed)
  useWaterFill(bodyMid, 135, 0.22, 0.5, 0.25);
  drawPoly([
    [pt.x - perpX * wMax * 0.35, pt.y - perpY * wMax * 0.35],
    [midX - perpX * wMax * 0.75, midY - perpY * wMax * 0.75],
    [tipX - perpX * wMax * 0.28, tipY - perpY * wMax * 0.28],
    [tipX + perpX * wMax * 0.2, tipY + perpY * wMax * 0.2],
    [midX + perpX * wMax * 0.45, midY + perpY * wMax * 0.45]
  ], 0.35);

  // Wrinkled leathery tunic contour rings & translucent backlit rim highlights
  useStroke("cpencil", bodyLit, 0.8 * scaleFactor);
  safeSpline([
    [pt.x - perpX * wMax * 0.45, pt.y - perpY * wMax * 0.45, 0.6],
    [midX - perpX * wMax * 0.85, midY - perpY * wMax * 0.85, 1.0],
    [tipX - perpX * wMax * 0.35, tipY - perpY * wMax * 0.35, 0.8]
  ], 0.45);

  // Translucent backlit cyan/rose rim where noon light catches the gelatinous tunic
  useStroke("caustic_glow", glowCol, 0.75 * scaleFactor);
  safeSpline([
    [midX - perpX * wMax * 0.9, midY - perpY * wMax * 0.9, 0.5],
    [tipX - perpX * wMax * 0.38, tipY - perpY * wMax * 0.38, 1.1],
    [tipX + perpX * wMax * 0.32, tipY + perpY * wMax * 0.32, 0.7]
  ], 0.4);

  // Dark siphon openings at the tips + delicate rim frills
  useStroke("2B", bodyDark, 1.2 * scaleFactor);
  safeLine(
    tipX - perpX * wMax * 0.25,
    tipY - perpY * wMax * 0.25,
    tipX + perpX * wMax * 0.25,
    tipY + perpY * wMax * 0.25
  );
  safeLine(
    sideSiphonX - dirX * wMax * 0.2,
    sideSiphonY - dirY * wMax * 0.2,
    sideSiphonX + dirX * wMax * 0.2,
    sideSiphonY + dirY * wMax * 0.2
  );

  useStroke("cpencil", rimCol, 0.65 * scaleFactor);
  safeLine(
    tipX - perpX * wMax * 0.32,
    tipY - perpY * wMax * 0.32,
    tipX + perpX * wMax * 0.32,
    tipY + perpY * wMax * 0.32
  );
}

// ============================================================================
// LAYER 3 & 7: SWAYING KELP THREADS & HYDROID FILAMENTS
// ============================================================================

function renderKelpPass(isBackgroundPass) {
  for (let i = chainLinks.length - 1; i >= 0; i--) {
    let link = chainLinks[i];
    let { d, sc, index } = link;

    let strandCount = isBackgroundPass
      ? Math.floor(lerp(7, 3, d))
      : Math.floor(lerp(11, 4, d));

    for (let s = 0; s < strandCount; s++) {
      let tAttach = (s / strandCount + index * 0.17) % 1;
      let aAttach = isBackgroundPass ? random(70, 155) : random(-85, 75);
      let pt0 = evalLinkSurface(link, tAttach, aAttach);

      // Gentle underwater surge swaying strands toward the right/down-right
      let totalLen = random(110, 290) * sc;
      let baseSwayAngle = random(18, 46);
      let freq = random(1.2, 2.4);
      let amp = random(14, 34) * sc;
      let phase = random(0, 360);

      let nPts = 7;
      let ribbonPts = [];
      let edgePts = [];

      for (let k = 0; k < nPts; k++) {
        let f = k / (nPts - 1);
        let distAlong = f * totalLen;
        let waveOffset = sin(phase + f * 360 * freq) * amp * Math.pow(f, 0.85);

        let px = pt0.x + cos(baseSwayAngle) * distAlong - sin(baseSwayAngle) * waveOffset;
        let py = pt0.y + sin(baseSwayAngle) * distAlong + cos(baseSwayAngle) * waveOffset;

        // Taper pressure from attachment base to delicate tip
        let press = lerp(1.35, 0.15, Math.pow(f, 0.8));
        ribbonPts.push([px, py, press]);
        edgePts.push([px - 1.8 * sc * (1 - f), py - 1.8 * sc * (1 - f), press * 0.85]);
      }

      let isNarrowThread = random() < 0.55;
      let darkCol = depthFade(PALETTE.kelpDark, d, 0.92);
      let midCol = depthFade(random() < 0.5 ? PALETTE.kelpOlive : PALETTE.kelpBronze, d, 0.9);
      let litCol = depthFade(PALETTE.kelpLit, d, 0.88);
      let backlitCol = depthFade(PALETTE.kelpEdge, d, 0.82);

      if (isNarrowThread) {
        // Fine swaying kelp thread / filamentous algae
        useStroke("2B", darkCol, 1.05 * sc);
        safeSpline(ribbonPts, 0.55);

        useStroke("cpencil", litCol, 0.7 * sc);
        safeSpline(edgePts, 0.55);
      } else {
        // Broader ruffled kelp blade with ruffled edge and translucent backlit rim
        useStroke("charcoal", darkCol, 2.1 * sc);
        safeSpline(ribbonPts, 0.5);

        useStroke("cpencil", midCol, 1.5 * sc);
        safeSpline(ribbonPts, 0.5);

        if (!isBackgroundPass && d < 0.78) {
          useStroke("caustic_glow", backlitCol, 0.75 * sc);
          safeSpline(edgePts, 0.55);
        }
      }

      // Delicate feathery hydroid side-branches near the base of some strands
      if (!isBackgroundPass && d < 0.68 && s % 3 === 0) {
        useStroke("pen", backlitCol, 0.45 * sc);
        for (let b = 1; b <= 3; b++) {
          let bp = ribbonPts[b];
          if (!bp) continue;
          let hx = bp[0] + random(10, 24) * sc;
          let hy = bp[1] + random(-8, 14) * sc;
          safeSpline([
            [bp[0], bp[1], 0.7],
            [(bp[0] + hx) * 0.5, (bp[1] + hy) * 0.5 - 3 * sc, 0.5],
            [hx, hy, 0.15]
          ], 0.4);
        }
      }
    }
  }
}

// ============================================================================
// LAYER 8: FOREGROUND CHALKY PASTEL LIGHT SHAFTS & MARINE SNOW PARTICLES
// ============================================================================

function renderForegroundLightShaftsAndParticles() {
  // 1. Translucent watercolor & chalky pastel light shafts slicing across the chain
  for (let shaft of lightShafts) {
    if (shaft.layer === "back") continue;

    let a1 = shaft.angle - shaft.spread * 0.5;
    let a2 = shaft.angle + shaft.spread * 0.5;

    // Subtle veil glaze where the noon beam crosses in front of the chain
    let r0 = 320;
    let r1 = shaft.len * 0.82;
    let p1 = [LIGHT_SRC.x + cos(a1) * r0, LIGHT_SRC.y + sin(a1) * r0];
    let p2 = [LIGHT_SRC.x + cos(a2) * r0, LIGHT_SRC.y + sin(a2) * r0];
    let p3 = [LIGHT_SRC.x + cos(a2) * r1, LIGHT_SRC.y + sin(a2) * r1];
    let p4 = [LIGHT_SRC.x + cos(a1) * r1, LIGHT_SRC.y + sin(a1) * r1];

    useWaterFill(PALETTE.chalkCyan, 16 * shaft.intensity, 0.45, 0.35, 0.1);
    drawPoly([p1, p2, p3, p4], 0.15);

    // Lift the light shafts out with long soft chalky pastel streaks
    let streakCount = Math.floor(34 * shaft.intensity);
    for (let s = 0; s < streakCount; s++) {
      let ang = random(a1, a2);
      let rStart = random(280, 960);
      let rLen = random(220, 640);
      let rEnd = rStart + rLen;

      let x1 = LIGHT_SRC.x + cos(ang) * rStart;
      let y1 = LIGHT_SRC.y + sin(ang) * rStart;
      let x2 = LIGHT_SRC.x + cos(ang) * rEnd;
      let y2 = LIGHT_SRC.y + sin(ang) * rEnd;

      // Clip/skip streaks completely off-canvas
      if ((x1 < -50 && x2 < -50) || (x1 > 1250 && x2 > 1250) || (y1 > 1250 && y2 > 1250)) {
        continue;
      }

      let dMid = constrain(((y1 + y2) * 0.5) / 1200, 0, 1);
      let col;
      if (dMid < 0.28) {
        col = mixHex(PALETTE.chalkWhite, PALETTE.chalkIce, dMid / 0.28);
      } else if (dMid < 0.62) {
        col = mixHex(PALETTE.chalkIce, PALETTE.chalkCyan, (dMid - 0.28) / 0.34);
      } else {
        col = mixHex(PALETTE.chalkCyan, PALETTE.chalkDusk, (dMid - 0.62) / 0.38);
      }

      // Alternate between wide soft pastel beam and finer chalky grain streaks
      if (s % 3 === 0) {
        useStroke("pastel_beam", col, random(0.8, 1.85) * (1 - dMid * 0.35));
      } else {
        useStroke("chalk_soft", col, random(0.65, 1.45) * (1 - dMid * 0.35));
      }
      safeLine(x1, y1, x2, y2);
    }

    // Crisp, delicate chalk-pencil core rays near the top surface
    let fineCount = Math.floor(14 * shaft.intensity);
    for (let f = 0; f < fineCount; f++) {
      let ang = random(a1 + 0.4, a2 - 0.4);
      let rStart = random(310, 620);
      let rEnd = rStart + random(160, 420);
      let x1 = LIGHT_SRC.x + cos(ang) * rStart;
      let y1 = LIGHT_SRC.y + sin(ang) * rStart;
      let x2 = LIGHT_SRC.x + cos(ang) * rEnd;
      let y2 = LIGHT_SRC.y + sin(ang) * rEnd;

      let dMid = constrain(((y1 + y2) * 0.5) / 1200, 0, 1);
      let col = mixHex(PALETTE.chalkWhite, PALETTE.chalkCyan, dMid);
      useStroke("cpencil", col, random(0.45, 0.95));
      safeLine(x1, y1, x2, y2);
    }
  }

  // 2. Fine spray and micro-motes for suspended marine snow particles in the light shafts
  for (let shaft of lightShafts) {
    let a1 = shaft.angle - shaft.spread * 0.6;
    let a2 = shaft.angle + shaft.spread * 0.6;

    // Fine spray passes along the light beams
    let sprayPasses = Math.floor(18 * shaft.intensity);
    for (let p = 0; p < sprayPasses; p++) {
      let ang = random(a1, a2);
      let rStart = random(340, 1350);
      let rEnd = rStart + random(90, 260);
      let x1 = LIGHT_SRC.x + cos(ang) * rStart;
      let y1 = LIGHT_SRC.y + sin(ang) * rStart;
      let x2 = LIGHT_SRC.x + cos(ang) * rEnd;
      let y2 = LIGHT_SRC.y + sin(ang) * rEnd;

      if (x1 < -20 || x1 > 1220 || y1 < -20 || y1 > 1220) continue;

      let d = constrain(y1 / 1200, 0, 1);
      let spCol = d < 0.45
        ? mixHex(PALETTE.chalkWhite, PALETTE.chalkCyan, d / 0.45)
        : mixHex(PALETTE.chalkCyan, PALETTE.chalkDusk, (d - 0.45) / 0.55);

      useStroke("spray", spCol, random(0.55, 1.35) * (1 - d * 0.4));
      safeLine(x1, y1, x2, y2);
    }
  }

  // Individual glinting suspended particles & out-of-focus plankton motes
  let numMotes = 240;
  for (let m = 0; m < numMotes; m++) {
    // Bias particles toward the slanted noon light fan
    let shaft = random(lightShafts);
    let ang = shaft.angle + random(-shaft.spread * 0.85, shaft.spread * 0.85);
    let rad = random(350, 1680);
    let x = LIGHT_SRC.x + cos(ang) * rad + random(-35, 35);
    let y = LIGHT_SRC.y + sin(ang) * rad + random(-35, 35);

    if (x < 10 || x > 1190 || y < 10 || y > 1190) continue;

    let d = constrain(y / 1200, 0, 1);
    let moteCol = d < 0.4
      ? mixHex(PALETTE.chalkWhite, PALETTE.chalkIce, d / 0.4)
      : mixHex(PALETTE.chalkCyan, PALETTE.chalkDusk, (d - 0.4) / 0.6);

    if (random() < 0.22) {
      // Soft out-of-focus bokeh particle
      useStroke("chalk_soft", moteCol, random(0.6, 1.3));
      brush.circle(x, y, random(2.2, 5.5), 0.35);
    } else {
      // Tiny sharp suspended silt speck catching noon light
      useStroke("cpencil", moteCol, random(0.65, 1.35));
      safeLine(x, y, x + random(1.6, 3.8), y + random(1.6, 3.8));
    }
  }
}
